INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('af415d7d-6293-4dd8-a708-6db4a152fda1', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XI', 'DEL CONTRATO DE OBRA O EMPRESA', 32);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('b3acad9a-9aee-4908-85c5-598b39dca41f', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XII', 'DE LOS SERVICIOS PROFESIONALES', 33);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('f89ac9f5-1b16-491b-be3e-4602f461037e', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XIII', 'DEL CONTRATO DE EDICION', 34);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('10031603-368a-4923-8535-f71d2d2f9aa3', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XVII', '', 35);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('5e0a9efc-2295-4cae-b3b5-2f28947d8dd6', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XVIII', 'DE LA RENTA VITALICIA', 36);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('ae53d1a3-2d24-450e-a3cf-e4c6f6255f62', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XIX', 'LOTERIAS Y RIFAS; APUESTAS Y JUEGO', 37);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('e424c539-e0a9-4bd3-bdab-648e87b50fd9', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XX', 'LA TRANSACCION', 38);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('0f07c5cb-7448-4bc5-a1cd-def40ded626f', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO XXI', 'DEL COMPROMISO', 39);
INSERT INTO sections (id, law_id, parent_id, kind, number, heading, position) VALUES ('3214fa56-6180-430d-8793-9d2ba0468283', 'a0000000-0000-0000-0000-000000000001', 'ec47d03c-6b06-432e-97ae-5fe54f751502', 'titulo', 'TITULO FINAL', '', 40);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('785afc88-b7bd-4d76-b289-8e2242f441c7', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '1', 'Personalidad', 1, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b979df71-5992-4b46-bbff-eb6e752089ee', '785afc88-b7bd-4d76-b289-8e2242f441c7', 1, 'La personalidad civil comienza con el nacimiento y termina con la muerte; sin embargo, al que está por nacer se le considera nacido para todo lo que le favorece, siempre que nazca en condiciones de viabilidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a05b43e9-2831-4967-9367-8f113d6f9bdd', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '2', 'Partos Dobles', 2, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c0bc85ae-4ee3-4369-b357-32504968d1ae', 'a05b43e9-2831-4967-9367-8f113d6f9bdd', 1, 'Si dos o más nacen de un mismo parto, se considerarán iguales en los derechos civiles que dependen de la edad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ff4da80-38e1-408d-a4a1-0639de253dfd', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '3', 'Comorencia', 3, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('710dc0da-724e-4479-9f65-a8109969b365', '3ff4da80-38e1-408d-a4a1-0639de253dfd', 1, 'Si dos o más personas hubiesen fallecido de modo que no se pueda probar cuál de ellas murió primero, se presume que fallecieron todas al mismo tiempo, sin que se pueda alegar transmisión alguna de derechos entre ellas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('243ebfdd-469e-4aff-9997-ba0082ff2c98', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '4', 'Identificación de la persona', 4, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aefd9455-7d05-44ab-b85f-a21f787039eb', '243ebfdd-469e-4aff-9997-ba0082ff2c98', 1, 'La persona individual se identifica con el nombre con que se inscriba su nacimiento en el Registro Civil, el que se compone del nombre propio y del apellido de sus padres casados o de sus padres no casados que lo hubieren reconocido. Los hijos de madre soltera serán inscritos con los apellidos de ésta. Los hijos de padres desconocidos serán inscritos con el nombre que les de la persona o institución que los inscriba.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72fb7416-41b4-49ef-a48a-aa354a12e178', '243ebfdd-469e-4aff-9997-ba0082ff2c98', 2, 'En el caso de los menores ya inscritos en el Registro Civil con un sólo apellido, la madre, o quien ejerza la patria potestad, podrá acudir nuevamente a dicho Registro a ampliar la inscripción correspondiente para inscribir los dos apellidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f0127509-b779-4810-bdee-61ca58b001b8', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '5', NULL, 5, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c191ec07-60d0-4314-8fad-8df656c71b79', 'f0127509-b779-4810-bdee-61ca58b001b8', 1, 'El que constante y públicamente use nombre propio o apellido distinto del que consta en su partida de nacimiento, o use incompleto su nombre, u omita alguno de los apellidos que le corresponden, puede establecer su identificación por medio de declaración jurada hecha en escritura pública, por la misma persona si fuere mayor de edad o por sus padres que ejercieren la patria potestad. También podrá hacerse por cualquiera que tenga interés en la identificación conforme el procedimiento establecido por el Código Procesal Civil y Mercantil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('43b64bcd-c0e9-480d-976f-d245de0fe17b', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '6', NULL, 6, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7aff1e7-4657-4e59-9b2c-6cbf38781b7a', '43b64bcd-c0e9-480d-976f-d245de0fe17b', 1, 'Cambio de Nombre Las personas no pueden cambiar sus nombres sino con autorización judicial. La persona a quien perjudique un cambio de nombre, puede oponerse a la pretensión del solicitante en la forma que dispone el Código Procesal Civil y Mercantil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56360c40-7eb1-4604-91f7-853a945432dc', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '7', NULL, 7, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34aafb22-c965-4c9f-b446-f24081f716bc', '56360c40-7eb1-4604-91f7-853a945432dc', 1, 'En los casos a que se refieren los artículos anteriores, la alteración se anotará al margen de la partida de nacimiento. La identificación y el cambio de nombre no modifican la condición civil del que la obtiene ni constituye prueba alguna de la filiación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6b036fd1-ef4d-490b-9be4-c49b1c018643', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '8', 'Capacidad', 8, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8adbd86f-e730-4c37-8158-aefde099f526', '6b036fd1-ef4d-490b-9be4-c49b1c018643', 1, 'La capacidad para el ejercicio de los derechos civiles se adquiere por la mayoría de edad. Son mayores de edad los que han cumplido dieciocho años.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6fa5cd60-2c4d-4fde-a4bf-2cc5d2196e72', '6b036fd1-ef4d-490b-9be4-c49b1c018643', 2, 'Los menores que han cumplido catorce años son capaces para algunos actos determinados por la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f7e60fb3-75c2-41b0-99cc-828a27d314e9', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '9', 'Incapacidad', 9, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74334a34-1bd0-4ea9-96c8-260fd137efa4', 'f7e60fb3-75c2-41b0-99cc-828a27d314e9', 1, 'Los mayores de edad que adolecen de enfermedad mental que los priva de discernimiento, deben ser declarados en estado de interdicción. Pueden asimismo ser declarados en estado de interdicción, las personas que por abuso de bebidas alcohólicas o de estupefacientes, se exponen ellas mismas o exponen a sus familias a graves perjuicios económicos. La declaratoria de interdicción produce, desde la fecha en que sea establecida en sentencia firme, incapacidad absoluta de la persona para el ejercicio de sus derechos; pero los actos anteriores a tal declaratoria pueden ser anulados si se probare que la incapacidad existía notoriamente en la época en que se verificaron.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('abea0e1a-d275-4a31-81d1-c045a5ebe9d2', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '10', NULL, 10, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('326eb781-b512-452b-908d-72f7d7ac8157', 'abea0e1a-d275-4a31-81d1-c045a5ebe9d2', 1, 'Las perturbaciones mentales transitorias no determinan la incapacidad de obrar, pero son nulas las declaraciones de voluntad emitidas en tales situaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0d4522ed-9853-4881-8a45-7c439bb06d27', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '11', NULL, 11, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('259ecf0a-2f23-47d4-bd65-0d365177b47c', '0d4522ed-9853-4881-8a45-7c439bb06d27', 1, 'Después de la muerte de un individuo, los actos realizados por él mismo no podrán impugnarse por incapacidad sino cuando la interdicción ha sido pedida antes de su muerte, o cuando la prueba de la incapacidad resulte del mismo acto que se impugna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('df0be8b8-dfa4-42b8-bc9a-3b566235d5e6', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '12', NULL, 12, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ab81749-a9c3-4a08-a3be-a259433b133d', 'df0be8b8-dfa4-42b8-bc9a-3b566235d5e6', 1, 'La interdicción puede solicitarla indistintamente el Ministerio Público, los parientes del incapacitado o las personas que tengan contra él alguna acción qué deducir; y termina cuando cesa la causal que la motivó y así lo declare la autoridad judicial a instancia de quienes tienen derecho a pedirla o del mismo declarado incapaz.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f03e734-8cd7-48a2-b4ba-8eb779e03d11', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '13', NULL, 13, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e933ff3-ee74-49c6-9b6e-41c817a43d2a', '0f03e734-8cd7-48a2-b4ba-8eb779e03d11', 1, 'Quienes padezcan de ceguera congénita o adquirida en la infancia, y los sordomudos tienen incapacidad civil para ejercitar sus derechos, pero son capaces los que puedan expresar su voluntad de manera indubitable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f704a05f-e0b4-41d9-9c0b-071cfe508a9e', 'a0000000-0000-0000-0000-000000000001', 'e376c57d-ca1f-421e-9860-c687741eb116', '14', NULL, 14, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c97a2cf1-5962-40c8-b863-ea842caf9996', 'f704a05f-e0b4-41d9-9c0b-071cfe508a9e', 1, 'Los incapaces pueden ejercitar sus derechos y contraer obligaciones por medio de sus representantes legales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afcde264-dbb3-494d-9ac7-7caf74de3a9e', 'f704a05f-e0b4-41d9-9c0b-071cfe508a9e', 2, 'DE LAS PERSONAS JURIDICAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2e8c0f4-a687-458b-b443-fe20b36364ec', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '15', NULL, 15, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74218e08-969a-4001-be97-df82d0a28890', 'c2e8c0f4-a687-458b-b443-fe20b36364ec', 1, 'Son personas Jurídicas: 1. El Estado, las municipalidades, las iglesias de todos los cultos, La Universidad de San Carlos y las demás instituciones de derecho público creadas o reconocidas por la ley;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c868b334-3944-43a6-87cb-19729aaa3dd1', 'c2e8c0f4-a687-458b-b443-fe20b36364ec', 2, '2. Las funciones y demás entidades de interés público creadas o reconocidas por la ley.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70b5228c-556b-41ee-b525-0730bb3de46b', 'c2e8c0f4-a687-458b-b443-fe20b36364ec', 3, '3. Las asociaciones sin finalidades lucrativas, que se proponen promover, ejercer y proteger sus intereses sindicales, políticos, económicos, religiosos, sociales, culturales, profesionales o de cualquier otro orden, cuya constitución fuere debidamente aprobada por la autoridad respectiva. Los patronatos y los comités para obras de recreo, utilidad o beneficio social creados o autorizados por la autoridad correspondiente, se consideran también como asociaciones; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c29f0d5a-098e-4d6f-bfe4-a23cb084391c', 'c2e8c0f4-a687-458b-b443-fe20b36364ec', 4, '4. Las sociedades, consorcios y cualesquiera otras con fines lucrativos que permitan las leyes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28ba34ad-0df4-4f6d-af65-5dc4e98091e7', 'c2e8c0f4-a687-458b-b443-fe20b36364ec', 5, 'Las asociaciones no lucrativas a que se refiere el inciso 3º podrán establecerse con la autorización del Estado, en forma accionada, sin que, por ese solo hecho, sean consideradas como empresas mercantiles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9dff14f0-bf62-4490-9e7d-556dfe8b9639', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '16', NULL, 16, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50ace7c5-04dc-41ca-a991-8d84b93586be', '9dff14f0-bf62-4490-9e7d-556dfe8b9639', 1, 'La persona jurídica forma una entidad civil distinta de sus miembros individualmente considerados; puede ejercitar todos los derechos y contraer las obligaciones que sean necesarios para realizar sus fines y será representada por la persona u órgano que designe la ley, las reglas de su institución, sus estatutos o reglamentos, o la escritura social.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9dd8e3a0-230d-4ba1-a9f3-2d113fd999c6', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '17', NULL, 17, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67203e1b-81c1-4175-bee2-fcd3c8f61b81', '9dd8e3a0-230d-4ba1-a9f3-2d113fd999c6', 1, 'Las iglesias son capaces para adquirir y poseer bienes y disponer de ellos, siempre que los destinen exclusivamente a fines religiosos, de asistencia social o a la educación. Su personaría se determina por las reglas de su institución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('176ccdbe-6533-4ee0-a6b2-fcf65b0a6912', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '18', 'Personalidad de las asociaciones civiles', 18, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52f1ac15-65ba-4de5-8e0a-5ed4f81c0501', '176ccdbe-6533-4ee0-a6b2-fcf65b0a6912', 1, 'Las instituciones, los establecimientos de asistencia social y demás entidades de interés público, regulan su capacidad civil por las leyes que las hayan creado o reconocido, y las asociaciones por las reglas de su institución, cuando no hubieren sido creadas por el Estado. La personalidad jurídica de las asociaciones civiles es efecto del acto de su inscripción en el registro del municipio donde se constituyan. El acto de su inscripción no convalida las disposiciones de sus estatutos que adolezcan de nulidad o que sean anulables. La acción correspondiente podrá ejercitarse por quien tenga interés en el asunto o por la Procuraduría General de la Nación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8abaf716-3651-45c0-8e08-f610d5d63f07', '176ccdbe-6533-4ee0-a6b2-fcf65b0a6912', 2, 'El Organismo Ejecutivo deberá emitir en un plazo no mayor de tres meses después de la entrada en vigencia de la presente ley, el reglamento que norme y establezca los requisitos de inscripción ante el Registro Civil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cf803eac-2de9-424b-a5ea-6a447d68c228', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '19', NULL, 19, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('faa4dbb5-c105-40b1-ae00-5ef0235aeceb', 'cf803eac-2de9-424b-a5ea-6a447d68c228', 1, 'Las personas jurídicas a que se refiere el inciso 4º del artículo 15, quedan sujetas a lo convenido en su escritura constitutiva o en sus estatutos debidamente aprobados por la autoridad que corresponda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('654d255b-b1ab-494d-a2da-30413a7b3185', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '20', NULL, 20, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ecd607c-1c99-4e82-bd9b-ae527e1db564', '654d255b-b1ab-494d-a2da-30413a7b3185', 1, 'Las fundaciones se constituirán por escritura pública o por testamento. En el instrumento de fundación debe indicarse el patrimonio afecto y el fin a que se destina y la forma de administración. La autoridad respectiva aprobará el funcionamiento de la fundación si no fuere contraria a la ley, y a falta de disposiciones suficientes, dictará las reglas necesarias para dar cumplimiento a la voluntad del fundador. El Ministerio Público deberá vigilar por que los bienes de las fundaciones se empleen conforme a su destino.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0d3728f0-208e-42de-adca-07434bff2b02', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '21', NULL, 21, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('16a19979-663e-4cc8-86bd-9d8981a3978b', '0d3728f0-208e-42de-adca-07434bff2b02', 1, 'Si el fin de la fundación no fuere realizable, o si resultaren insuficientes los bienes para la finalidad propuesta, o se hiciere oneroso su mantenimiento, probadas estas circunstancias ante el juez de Primera Instancia competente, será incorporado el patrimonio de la fundación a otra institución que persiga fines análogos, salvo lo que a este respecto hubiere dispuesto el fundador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3896ff2-5a3b-40dc-bcc4-e9e74bc5fb5b', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '22', NULL, 22, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f1dbb45-bf00-4528-ae89-4413112e0b4d', 'e3896ff2-5a3b-40dc-bcc4-e9e74bc5fb5b', 1, 'Las fundaciones extranjeras quedan sujetas a las anteriores disposiciones en cuanto a su aprobación y funcionamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('76a2e2ed-c1bd-404d-a738-9ccc70f55933', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '23', NULL, 23, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c065c8e-936f-489c-9557-c4060376ddfb', '76a2e2ed-c1bd-404d-a738-9ccc70f55933', 1, 'Quienes integren uniones, asociaciones o comités que se propongan llevar a cabo fines de socorro o de beneficencia u obras publicas, monumentos, exposiciones, festejos y similares, cuando no tengan personalidad jurídica, son responsables solidariamente de los fondos que recauden y de su inversión en la finalidad anunciada. Cuando ésta no se haya realizado, los fondos recogidos serán destinados mediante disposición de la autoridad, a fines de asistencia social.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e62d190-197a-405a-866d-d469ef30dce5', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '24', NULL, 24, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f495c68-8179-4f7a-af06-443fe682b892', '5e62d190-197a-405a-866d-d469ef30dce5', 1, 'Las personas jurídicas son civilmente responsables de los actos de sus representantes que en el ejercicio de sus funciones perjudiquen a tercero, o cuando violen la ley o no la cumplan; quedando a salvo la acción que proceda contra los autores del daño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c871f2c4-9846-47ff-af69-0127fc175ab5', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '25', NULL, 25, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a46e948-73e3-47ae-9f3c-1a35fae1407c', 'c871f2c4-9846-47ff-af69-0127fc175ab5', 1, 'Las asociaciones podrán disolverse por la voluntad de la mayoría de sus miembros y por las causas que determinen sus estatutos. También pueden disolverse por acuerdo de la autoridad respectiva, a pedido del Ministerio Público, cuando se compruebe que sus actividades son contrarias a la ley y al orden público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('935356d3-2970-433a-a4f7-34cdf5905880', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '26', NULL, 26, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fbe2df9f-f6dc-453a-9407-02af5c57a8e8', '935356d3-2970-433a-a4f7-34cdf5905880', 1, 'Disuelta una asociación, los bienes que le pertenezcan tendrán el destino previsto en sus estatutos; y si nada se hubiere dispuesto, serán considerados como bienes vacantes y aplicados a los objetos que determine la autoridad que acuerde la disolución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c221ac4e-a48e-4c7e-8678-6093145f207b', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '27', NULL, 27, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('66c6b687-f9fd-44ed-95e4-c1eeeca3f3d9', 'c221ac4e-a48e-4c7e-8678-6093145f207b', 1, 'La extinción de la persona jurídica no la exime de las responsabilidades que hubiere dejado pendientes; y no cesará la representación de las personas que la hayan tenido, sino hasta que estén fenecidos los asuntos relacionados con dicha persona jurídica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('95c7d853-57f5-4ed0-a84a-5debf36c229f', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '28', NULL, 28, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab31c413-66e5-4450-98d2-a89d8c239c2e', '95c7d853-57f5-4ed0-a84a-5debf36c229f', 1, 'Las compañías o asociaciones legalmente constituidas en el extranjero, podrán establecerse en el país o tener en él agencias o sucursales, previa autorización del Ejecutivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d22d7844-2496-47ba-9a2f-f4eec30b30df', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '29', NULL, 29, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8693d2b8-5a13-4dad-af7e-d218911486b7', 'd22d7844-2496-47ba-9a2f-f4eec30b30df', 1, 'No se dará la autorización a que se refiere el artículo anterior, sín que la compañía o asociación compruebe legalmente estar constituida y autorizada con arreglo a las leyes del país de su domicilio; que por su constitución y fines no se opongan a las leyes de la República y que ha nombrado mandatario expensado y arraigado con todas las facultades generales y especiales que la ley exige para responder de los negocios judiciales y extrajudiciales que se relacionen con la compañía o asociación. Si el apoderado no tuviere todas estas facultades, se le considerará investido de ellas, por ministerio de la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5fc86738-9de8-4ba2-8113-9329eb6d2461', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '30', NULL, 30, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f8ed7d2-c209-4b6b-a5d5-0dade4fd077d', '5fc86738-9de8-4ba2-8113-9329eb6d2461', 1, 'Las compañías o asociaciones extranjeras que tengan negocios en la República, están obligadas: 1º. A establecer agencias o sucursales que atiendan dichos negocios;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e25795b-d098-43fc-b39b-e521cc10c2e9', '5fc86738-9de8-4ba2-8113-9329eb6d2461', 2, '2º. A tener contabilidad, en forma legal y escrita en español, en que consten las operaciones o negocios que verificaren en el país; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4516fff-ecc6-4985-b52a-0e7286aedd1b', '5fc86738-9de8-4ba2-8113-9329eb6d2461', 3, '3º. A someterse a las leyes y tribunales de la república para la decisión de las cuestiones judiciales a que den lugar los negocios de la agencia o sucursal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a4938426-4e47-480c-b7eb-1663381dfab2', 'a0000000-0000-0000-0000-000000000001', '48f46d2a-881a-4971-8dcb-e79def48fec4', '31', NULL, 31, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('694982af-0d3e-4c4a-8d94-3620eaa6038d', 'a4938426-4e47-480c-b7eb-1663381dfab2', 1, 'Las compañías o asociaciones extranjeras, establecidas en Guatemala y las sucursales y agencias extranjeras, que infrinjan las prescripciones contenidas en el artículo anterior, podrán ser clausuradas por la autoridad administrativa, sin perjuicio de hacer efectivas las responsabilidades en que hubieren incurrido con ocasión de sus actividades. Las fundaciones, instituciones, establecimientos de asistencia social y asociaciones cuyas finalidades sean de interés público, estarán sometidas a la vigilancia del Estado. Dichas entidades y las sociedades por acciones, podrán también ser intervenidas por el Ejecutivo cuando el interés o el orden público lo requieran.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cec01d3c-d471-4621-8aa0-f65b245b74ee', 'a4938426-4e47-480c-b7eb-1663381dfab2', 2, 'DEL DOMICILIO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2534161-892f-42f8-b5a2-e086e7ccb77b', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '32', NULL, 32, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ed4ae1d-1180-4928-a3ac-68584fc64524', 'c2534161-892f-42f8-b5a2-e086e7ccb77b', 1, 'El domicilio se constituye voluntariamente por la residencia en un lugar con ánimo de permanecer en él.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('df5ac5a8-3d24-4843-9083-7c20609dd6c8', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '33', NULL, 33, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('106854fb-3e6f-4d90-bcbf-20650ef31393', 'df5ac5a8-3d24-4843-9083-7c20609dd6c8', 1, 'Se presume el ánimo de permanecer, por la residencia continua durante un año en el lugar. Cesará la presunción anterior si se comprobare que la residencia es accidental o que se tiene en otra parte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('82997138-3b8c-49c8-8ae3-50e8fedf911f', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '34', NULL, 34, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e635d7d1-e1be-46e7-90e5-c8b53a5fb948', '82997138-3b8c-49c8-8ae3-50e8fedf911f', 1, 'Si una persona vive alternativamente o tiene ocupaciones habituales en varios lugares, se considera domiciliada en cualquiera de ellos; pero si se trata de actos que tienen relación especial con un lugar determinado, éste será el domicilio de la persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e630745-081b-4faa-8d5c-0a2453e38283', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '35', NULL, 35, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('934c2960-a70c-47ac-954a-610d491036b6', '3e630745-081b-4faa-8d5c-0a2453e38283', 1, 'La persona que no tiene residencia habitual se considera domiciliada en el lugar donde se encuentra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ac5de5e6-b2b2-4f13-ae61-02e3db8658ee', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '36', NULL, 36, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55cf97f0-3b0c-4cf9-95b8-6ae6501cb21d', 'ac5de5e6-b2b2-4f13-ae61-02e3db8658ee', 1, 'El domicilio legal de una persona es el lugar en donde la ley le fija su residencia para el ejercicio de sus derechos y el cumplimiento de sus obligaciones, aunque de hecho no esté allí presente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '37', NULL, 37, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('230fa70a-9d03-45ee-8682-1fc14c55e68b', '57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 1, 'Se reputa domicilio legal: a) Del menor de edad e incapacitado, el de las personas que ejerzan la patria potestad, o la tutela.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cbab7d9e-d74a-402a-9777-9f4f60b842f0', '57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 2, 'b) De los funcionarios, empleados, dependientes y demás personas, el lugar en que prestan sus servicios; pero los que accidentalmente se hallen desempeñando alguna comisión, no adquieren domicilio en el lugar;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afb30fb6-1081-419f-a254-b334fe167ded', '57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 3, 'c) De los militares en servicio activo, el lugar en que están destinados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e98b627d-629a-4463-90d3-6797a97a4d0a', '57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 4, 'd) De los que se hallen extinguiendo una condena, el lugar donde la extinguen, por lo que toca a las relaciones jurídicas posteriores a ella; en cuanto a las anteriores, conservarán el último que hayan tenido; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae3e5e59-42bb-4a13-8d26-1faffa3826b6', '57a2dad1-22f0-4122-82ed-ad7065f9e2e2', 5, 'e) De los agentes diplomáticos guatemaltecos residentes en el extranjero por razón de su cargo, el último domicilio que tenían en el territorio nacional.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c072415b-ab87-4cc0-bb7a-c66b9af2d14a', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '38', NULL, 38, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e131977-9557-474e-a5a6-3c4203ba276e', 'c072415b-ab87-4cc0-bb7a-c66b9af2d14a', 1, 'El domicilio de una persona jurídica es el que se designa en el documento en que conste su creación o, en su defecto, el lugar en que tenga su administración o sus oficinas centrales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f458cedb-90bf-44c4-8451-c1b11788b1cf', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '39', NULL, 39, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d8a2a65-9d5f-4a5c-be5d-5271915714da', 'f458cedb-90bf-44c4-8451-c1b11788b1cf', 1, 'También se reputa como domicilio de las personas jurídicas que tengan agencias o sucursales permanentes en lugares distintos de los de su domicilio, el lugar en que se hallan dichas agencias o sucursales respecto de los actos o contratos que éstas ejecuten.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af1be1f9-e43c-4228-8cee-e91017d58885', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '40', NULL, 40, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4671e375-fe8e-4d1d-a4ba-a85b2aedd5c3', 'af1be1f9-e43c-4228-8cee-e91017d58885', 1, 'Las personas, en sus contratos, pueden designar un domicilio especial para el cumplimiento de las obligaciones que éstos originen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9374b85c-178c-4faa-979f-9d05c9ccffe6', 'a0000000-0000-0000-0000-000000000001', '0a4eed52-2f69-4017-b0cd-4392d9e3ecbb', '41', NULL, 41, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ce58a85-d9b6-4edf-8b18-cfcc17e65142', '9374b85c-178c-4faa-979f-9d05c9ccffe6', 1, 'La vecindad es la circunscripción municipal en que una persona reside y se rige por las mismas leyes que el domicilio. La vecindad confiere iguales derechos e impone las mismas obligaciones locales a guatemaltecos y extranjeros.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a878be2-e6d1-4909-91a8-098840965abf', '9374b85c-178c-4faa-979f-9d05c9ccffe6', 2, 'DE LA AUSENCIA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca73b58e-5d80-4571-b773-68ad5443fbb8', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '42', NULL, 42, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5fbbd3a5-acda-4172-9a92-c154e20f8b09', 'ca73b58e-5d80-4571-b773-68ad5443fbb8', 1, 'Es ausente la persona que se halla fuera de la República y tiene o ha tenido su domicilio en ella. Se considera también ausente, para los efectos legales, la persona que ha desaparecido de su domicilio y cuyo paradero se ignora.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6c060980-6943-447d-b5e7-7e69069288a8', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '43', NULL, 43, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c39a680e-f1fb-4301-adf7-7d8adb7f2389', '6c060980-6943-447d-b5e7-7e69069288a8', 1, 'Declaración de ausencia para la representación en juicio Toda persona que tenga derechos qué ejercitar u obligaciones qué cumplir en la República y se ausente de ella, deberá dejar mandatario legalmente constituido, con todas las facultades especiales para responder de las obligaciones del mandante; y si no lo hiciere, se le declarará ausente a petición de parte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d43f1d7a-bed0-4203-8438-ac8cbbe8a636', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '44', NULL, 44, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e29c4ec-466b-4412-867f-4557fe30228b', 'd43f1d7a-bed0-4203-8438-ac8cbbe8a636', 1, 'La declaratoria anterior tendrá como único objeto, nombrar defensor judicial al ausente, para los casos en que deba responder a una demanda o hacer valer algún derecho en juicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5dcc1894-ab15-4bc8-a161-731161fdfb18', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '45', NULL, 45, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1fed460e-ee32-43f8-8b88-928c5faccdcb', '5dcc1894-ab15-4bc8-a161-731161fdfb18', 1, 'Si el ausente hubiere dejado apoderado sin facultades suficientes para la defensa en juicio, el cargo de defensor judicial recaerá de preferencia en éste. A falta de apoderado, el juez nombrará a una persona de notoria honradez, arraigo y competencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0b594ecf-814b-427e-a22a-6686fdede505', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '46', NULL, 46, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('17edce16-6c1b-4f13-969b-cd07a7970e15', '0b594ecf-814b-427e-a22a-6686fdede505', 1, 'Termina el cargo de defensor Judicial del ausente: a) Desde que termine el litigio en que se le nombró;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44c126bb-d26c-48f1-b2ab-ef4ba6babc45', '0b594ecf-814b-427e-a22a-6686fdede505', 2, 'b) Desde que se provea de guardador de bienes al ausente; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd061cc5-6cd4-4c9c-bb78-2520376af37d', '0b594ecf-814b-427e-a22a-6686fdede505', 3, 'c) Desde que el ausente se apersone por sí o por medio de apoderado con facultades suficientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a09b379-ef73-4597-9fa8-05899b8de83b', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '47', NULL, 47, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3742040-5307-42a8-b206-0f4943dfc866', '4a09b379-ef73-4597-9fa8-05899b8de83b', 1, 'Declaración de ausencia para la guarda y administración de bienes del ausente Cuando el ausente tenga bienes que deban ser administrados, cualquier persona capaz o el Ministerio Público puede denunciar la ausencia y solicitar el nombramiento de guardador de sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('798a4a3b-bdf0-48ef-a884-a895eb6c4091', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '48', NULL, 48, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('737c5cba-19e8-457e-8cba-f0911be89938', '798a4a3b-bdf0-48ef-a884-a895eb6c4091', 1, 'Si el ausente hubiere dejado mandatario se procederá como lo expresa el artículo 45.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8a3ebf39-85a4-4291-b47b-75ea854192c2', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '49', 'La ausencia debe ser declarada judicialmente', 49, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e97e0f2c-b8f1-4698-b578-c7e229ca30ef', '8a3ebf39-85a4-4291-b47b-75ea854192c2', 1, 'Concluido el procedimiento respectivo y hecho el nombramiento definitivo de guardador, la persona designada entre las que menciona él artículo que precede, recibirá los bienes, llenando previamente los requisitos legales y asumirá la representación del ausente, cesando en sus cargos el defensor específico y el depositario provisional.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0fa0594c-88f6-4408-8c76-655a296047e6', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '50', NULL, 50, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45fc8c4c-2d21-4e98-8775-2dbc900c51d2', '0fa0594c-88f6-4408-8c76-655a296047e6', 1, 'El representante del ausente es administrador de los bienes de éste y tiene las mismas obligaciones, facultades y prohibiciones de los tutores, en lo que fueren aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f03c7aa-6f18-418c-b5a5-0ed71f436d47', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '51', NULL, 51, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e55c1a6-463d-43fc-8b25-c1c8722538a5', '0f03c7aa-6f18-418c-b5a5-0ed71f436d47', 1, 'El guardador tendrá derecho a una retribución anual que fijará el juez de Primera Instancia competente, de acuerdo con lo dispuesto para la tutela en el artículo 340.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fd78a21-d2b5-477d-8652-75e1eac38684', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '52', NULL, 52, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e51ec584-f601-496d-a256-6a19d5592675', '6fd78a21-d2b5-477d-8652-75e1eac38684', 1, 'Cuando el guardador sea removido por su culpa no tendrá derecho a retribución alguna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a664301a-f735-4d97-8bd4-f8daf49c0c06', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '53', NULL, 53, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d90d567e-ced3-4424-92c7-fa9bd4af2d55', 'a664301a-f735-4d97-8bd4-f8daf49c0c06', 1, 'Termina el cargo de guardador: 1. 1º. Cuando se apersona el ausente por sí o por medio de apoderado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a171c190-27bf-4a90-bb57-f3030318a1e6', 'a664301a-f735-4d97-8bd4-f8daf49c0c06', 2, '2. Cuando se extinguen los bienes o dejan de pertenecer al ausente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37b08730-e884-43a2-b683-97d2943d3ae5', 'a664301a-f735-4d97-8bd4-f8daf49c0c06', 3, '3. Cuando fallezca el guardador, se le admita la renuncia o se le remueva del cargo, según las reglas establecidas para el tutor en lo que fueren aplicables, en cuyos casos el juez procederá de oficio a nombrar nuevo guardador; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01eed374-d710-4ffc-99c4-208b0c74a972', 'a664301a-f735-4d97-8bd4-f8daf49c0c06', 4, '4. Cuando se da la administración a las personas que indica el artículo 55.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e7e8d755-45f0-46ef-99db-8e47e370c355', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '54', NULL, 54, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bef7555a-64b5-4db2-abab-b0f77adcc9f6', 'e7e8d755-45f0-46ef-99db-8e47e370c355', 1, 'El Ministerio Público y los parientes del ausente deben denunciar al juez de Primera Instancia respectivo, las causas de remoción del guardador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67061275-1d56-47d3-8fc2-bfc67f7f7a13', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '55', 'Administración por los parientes', 55, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('415b0311-a02f-4bf7-9515-56cb50742b86', '67061275-1d56-47d3-8fc2-bfc67f7f7a13', 1, 'La administración de los bienes podrá ser solicitada y ejercida por el cónyuge e hijos del ausente y a falta de ellos, por los parientes consanguíneos en el orden de sucesión que establece la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ef71689-917b-4751-9029-2b3be6c79c3b', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '56', NULL, 56, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf1140e1-ccac-4b38-95c8-d53f1f2f2517', '0ef71689-917b-4751-9029-2b3be6c79c3b', 1, 'Antes de concederse la administración a los parientes del ausente, se practicará inventario y tasación de los bienes y liquidación o partición de los que pertenecen al matrimonio si el ausente fuere casado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('35c59df4-b31d-42c2-9846-de8fcc51308b', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '57', NULL, 57, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4e221af-5640-4eff-99c2-d8bd12f5e00e', '35c59df4-b31d-42c2-9846-de8fcc51308b', 1, 'Los parientes que solicitaren la administración constituirán hipoteca o prestarán fianza por el valor de los bienes del ausente. Mientras no se otorgue la expresada garantía, no cesará la administración del guardador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8933c39c-b0d6-49e3-afe7-79841b446d92', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '58', NULL, 58, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d8b7688-f7c1-452c-abaa-07bb3bcac51f', '8933c39c-b0d6-49e3-afe7-79841b446d92', 1, 'Al entrar el administrador designado en posesión de los bienes, cesará la representación del guardador, quien deberá rendirle cuentas de su administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('76c11f1d-b707-4260-a34a-4417f963bcb8', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '59', NULL, 59, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1088e161-e271-468f-999a-896f15345c09', '76c11f1d-b707-4260-a34a-4417f963bcb8', 1, 'Los parientes que tuvieren la administración, asumirán la representación legal del ausente y harán suyos los frutos naturales y civiles de los bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67d61ba4-88a0-4b3f-abe4-38dc95ef7540', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '60', NULL, 60, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c6e78863-29ce-4a71-8e5a-9b50a84bb488', '67d61ba4-88a0-4b3f-abe4-38dc95ef7540', 1, 'El administrador no podrá enajenar ni gravar los bienes del ausente, sin llenar las formalidades que las leyes establecen en cuanto a los bienes de menores o incapacitados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4cb079c0-2dbf-43aa-9da3-069bfdf1bf87', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '61', NULL, 61, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6d8faac0-e336-4572-821c-d2abdfdab271', '4cb079c0-2dbf-43aa-9da3-069bfdf1bf87', 1, 'El guardador o el administrador que adquieran para el ausente bienes o derechos por sucesión u otro título gratuito, deben denunciarlos al juez respectivo dentro de quince días y ampliarán hasta el valor de estos bienes o derechos, la garantía que hubieren prestado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b20c2481-c408-4edc-b640-21e7853dd084', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '62', NULL, 62, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f552c052-ef4b-45db-97ce-791624d6d5e4', 'b20c2481-c408-4edc-b640-21e7853dd084', 1, 'Se reputa vivo al ausente, para el efecto de adquirir por cualquier título, mientras no se haya decretado la posesión definitiva de sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ee3de59-c2b6-4e76-8b69-c0cd4681c851', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '63', 'Muerte presunta y posesión de los herederos', 63, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f3eaa8cc-d935-4663-a22f-c9cda4b0a5f1', '9ee3de59-c2b6-4e76-8b69-c0cd4681c851', 1, 'Transcurridos cinco años desde que se decretó la administración por los parientes o desde que se tuvo la última noticia del ausente, podrá declararse la muerte presunta de éste y, en tal caso, podrán sus herederos testamentarios o legales, pedir la posesión de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5623adb1-8b56-4554-b996-389ece180184', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '64', NULL, 64, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0c75cc2-4802-45aa-b78e-e6b74843d0e3', '5623adb1-8b56-4554-b996-389ece180184', 1, 'Podrá asimismo declararse la muerte presunta: a) De la persona que desapareciere durante una guerra en que haya tomado parte o se hubiere encontrado en la zona de operaciones, cuando haya transcurrido un año de terminada la guerra sin que se tenga noticias de ella;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('744d958a-275f-4423-91e4-9f4e2bdbc65a', '5623adb1-8b56-4554-b996-389ece180184', 2, 'b) De la persona que se hubiere encontrado a bordo de un buque náufrago, o al verificarse un accidente de aviación, cuando haya transcurrido un año desde su desaparición; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('751cb5cf-ae7a-4c1c-af12-642cf4c1a74f', '5623adb1-8b56-4554-b996-389ece180184', 3, 'c) De la persona cuyo cadáver no haya sido encontrado y hubiere desaparecido por causa de explosión, incendio, terremoto, derrumbe, inundación u otro siniestro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c298b11a-d8df-411f-b4d1-0ad54c8cf727', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '65', NULL, 65, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('281a7e4d-1fd9-4c87-8840-111c4e3fcae1', 'c298b11a-d8df-411f-b4d1-0ad54c8cf727', 1, 'Cuando no constare la fecha del siniestro en que se presume fallecida alguna persona, el juez fijará el día y la hora en que se reputen ser los de la muerte, en vista de las circunstancias en que pueda haber ocurrido y de las pruebas que presenten los interesados. A falta de datos acerca de la hora del fallecimiento, se fijará como tal, la última hora del día presuntivo de la muerte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2e4d788f-ae4c-4909-9e48-4eaf035e353b', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '66', NULL, 66, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c5b65e8-7a08-4600-a8cf-da4bf311d672', '2e4d788f-ae4c-4909-9e48-4eaf035e353b', 1, 'La herencia corresponderá a los que resulten herederos del ausente en la fecha señalada como día de la muerte presunta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f68530fe-cd0f-49b5-a037-6fbea4a12671', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '67', NULL, 67, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('871124fb-6309-4893-bb70-9ef64d2b224c', 'f68530fe-cd0f-49b5-a037-6fbea4a12671', 1, 'En cualquier tiempo en que se estableciere la fecha exacta del fallecimiento del ausente, en esa fecha se considerará abierta la sucesión para el efecto de declarar quiénes son los herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ec86d3d-e411-46ea-865e-fcb600a6fe87', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '68', NULL, 68, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c8a5fbe-d31d-47d3-8b5e-7d2a37ed86b9', '0ec86d3d-e411-46ea-865e-fcb600a6fe87', 1, 'La resolución que declare la muerte presunta así como la que otorgue la posesión definitiva de los bienes, será inscrita en los registros del estado civil y de la propiedad inmueble que correspondan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('10f533ec-2c13-4308-9ec5-5d8dbaf9c23a', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '69', NULL, 69, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('743bb32b-3415-4162-a0bc-f39b3bf08b9d', '10f533ec-2c13-4308-9ec5-5d8dbaf9c23a', 1, 'En cualquier estado en que aparezca revocado el testamento que motivó la posesión definitiva, o que se presente otro testamento posterior del ausente, se conferirá la herencia a los que resulten herederos según los documentos últimamente aparecidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6837f595-796f-4f6d-be4d-31b5c110241c', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '70', NULL, 70, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4fb3f5f5-598e-4154-82f3-dd74f4ab0851', '6837f595-796f-4f6d-be4d-31b5c110241c', 1, 'Decretada la posesión definitiva, los propietarios de bienes usufructuados, los legatarios y, en general, todos aquellos que tengan derechos subordinados a la condición de muerte del ausente, podrán hacerlos valer.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4bb549ab-e3f8-436e-9198-2274ec917f8a', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '71', NULL, 71, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5220dc2-9b9b-4f10-a960-defbff99d679', '4bb549ab-e3f8-436e-9198-2274ec917f8a', 1, 'Cesará la posesión definitiva cuando haya noticia comprobada de que vive el ausente; desde entonces, el heredero quedará con el carácter de guardador y sujeto a todas las obligaciones de éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f5849fc6-41a9-4faf-a49c-5e6b8adc4264', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '72', NULL, 72, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8094d3fa-6d02-4d38-b1b0-46334f246f9d', 'f5849fc6-41a9-4faf-a49c-5e6b8adc4264', 1, 'Los que por cualquier título tengan la administración o custodia de los bienes del ausente, o hayan obtenido la posesión definitiva de ellos, no podrán retenerlos por causa alguna ni rehusar su entrega inmediata al ausente que regrese o a la persona que legalmente lo represente. El ausente, mientras viva, conserva la posesión civil de estos bienes, bajo el amparo de la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1a244640-1d7c-4220-b894-056cf9180172', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '73', NULL, 73, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43e02693-9fe6-43e4-b2a7-d85fb60ae8b3', '1a244640-1d7c-4220-b894-056cf9180172', 1, 'Los poseedores de los bienes deben proveer de alimentos a los que tengan derecho a recibirlos, en los términos que la ley establece.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e5e7457-5d1a-46d6-b72e-1b15b945f20f', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '74', NULL, 74, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f5cdadd7-df9c-465b-9775-e9dd278c8407', '5e5e7457-5d1a-46d6-b72e-1b15b945f20f', 1, 'Los efectos jurídicos de la declaración de ausencia y de muerte presunta, respecto a los bienes, se determinan por la ley del lugar en que se hallen situados. Las demás relaciones jurídicas seguirán sujetas a la ley que anteriormente las regía.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0555605c-aeef-4960-b32d-0a493fad548d', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '75', NULL, 75, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ca87a98-c263-4a5c-aef8-4f7619a5da85', '0555605c-aeef-4960-b32d-0a493fad548d', 1, 'Si el ausente o presunto muerto aparece o se prueba su existencia, aun después de la posesión definitiva, recobrará sus bienes en el estado en que éstos se encuentren, el precio de los vendidos y los que provengan del empleo que se haya hecho de ese precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('95c3ab7f-0840-4e5d-a5c8-4d3e68c62f61', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '76', NULL, 76, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13c3a3ef-1817-4b21-9c31-cd49e92fa074', '95c3ab7f-0840-4e5d-a5c8-4d3e68c62f61', 1, 'Los herederos o legatarios que hayan obtenido la posesión definitiva de los bienes, no podrán adquirirlos por prescripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4e9a0cc7-4969-45f7-8709-b71e1c1cf328', 'a0000000-0000-0000-0000-000000000001', 'ec8ee6af-2242-42c5-9180-5346530ec172', '77', 'Matrimonio del cónyuge', 77, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b7548cf-db07-4b20-a894-fa69179aba10', '4e9a0cc7-4969-45f7-8709-b71e1c1cf328', 1, 'Si el cónyuge de la persona declarada muerta contrae nuevo matrimonio, éste será válido aunque el ausente viva, a no ser que los cónyuges o uno de ellos conociera la circunstancia de estar vivo el ausente. En este caso, la acción de nulidad corresponde al ausente o al cónyuge que haya ignorado, al casarse, que aquél vivía. Esta acción prescribe a los seis meses contados, para el ausente, desde la fecha en que tuvo conocimiento del nuevo matrimonio; y para el cónyuge, desde que supo la supervivencia del ausente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ba7f4db-fb80-4fac-a3d9-59868cc108c3', '4e9a0cc7-4969-45f7-8709-b71e1c1cf328', 2, 'DE LA FAMILIA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('152d4a77-7b9b-4863-8cbd-ec16616ae551', '4e9a0cc7-4969-45f7-8709-b71e1c1cf328', 3, 'DEL MATRIMONIO PARRAFO I Disposiciones generales');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fa5ff2a2-34bc-4fb8-87ef-950b024ad685', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '78', 'El matrimonio, institución social', 78, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01d9c418-2689-42bb-8f77-b7dd7a972ae7', 'fa5ff2a2-34bc-4fb8-87ef-950b024ad685', 1, 'El matrimonio es una institución social por la que un hombre y una mujer se unen legalmente, con ánimo de permanencia y con el fin de vivir juntos, procrear, alimentar y educar a sus hijos y auxiliarse entre sí.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('66a5660c-5c77-42d2-9a49-1628e3b44421', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '79', NULL, 79, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5c4fddf-5db9-4d3f-a653-7055297185e3', '66a5660c-5c77-42d2-9a49-1628e3b44421', 1, 'El matrimonio se funda en la igualdad de derechos y obligaciones de ambos cónyuges, y en su celebración deben cumplirse todos los requisitos y llenarse las formalidades que exige este Código para su validez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a867fc2d-bf35-4211-959c-00f040779990', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '80', 'Esponsales', 80, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55f67f67-c512-4e5f-a033-1ad536a33f29', 'a867fc2d-bf35-4211-959c-00f040779990', 1, 'Los esponsales no producen obligación de contraer matrimonio, pero dan lugar a demandar la restitución de las cosas donadas y entregadas con promesa de un matrimonio que no se efectuó.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb83bd0e-606c-4abf-9d86-b011d00e1eb8', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '81', 'Aptitud para contraer matrimonio', 81, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e461e49f-fc98-40f0-9df1-3f62322b66c9', 'bb83bd0e-606c-4abf-9d86-b011d00e1eb8', 1, 'La mayoría de edad determina la libre aptitud para contraer matrimonio. Sin embargo, pueden contraerlo: el varón mayor');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('486d3cc6-a11e-4b8e-aa5b-54d0a9b2526c', 'bb83bd0e-606c-4abf-9d86-b011d00e1eb8', 2, 'de 16 años y la mujer mayor de 14, siempre que medie la autorización que determinan los artículos siguientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2c2237e3-e737-43de-b384-ca0320b634ab', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '82', NULL, 82, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2631432f-f8ea-437a-aa1b-7358cca69623', '2c2237e3-e737-43de-b384-ca0320b634ab', 1, 'La autorización deberán otorgarla conjuntamente el padre y la madre, o el que de ellos ejerza, sólo, la patria potestad. La del hijo adoptivo menor la dará el padre o la madre adoptante.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc3866da-c7a3-40eb-ad07-6ddf7d1ccc90', '2c2237e3-e737-43de-b384-ca0320b634ab', 2, 'A falta de padres, la autorización la dará el tutor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('04151b72-3115-486b-b97a-9fec9005dc34', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '83', 'Autorización judicial', 83, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bcc24749-e7b3-40ed-bcc5-01984d5d6c6b', '04151b72-3115-486b-b97a-9fec9005dc34', 1, 'Si no puede obtenerse la autorización conjunta del padre y de la madre, por ausencia, enfermedad u otro motivo, bastará la autorización de uno de los progenitores; y si ninguno de los dos puede hacerlo, la dará el juez de Primera Instancia del domicilio del menor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f69a0882-6e77-4538-adc6-61748aea1df1', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '84', NULL, 84, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('31b1ef52-f94e-4b47-8a79-554811e15541', 'f69a0882-6e77-4538-adc6-61748aea1df1', 1, 'En caso de desacuerdo de los padres o de negativa de la persona llamada a otorgar la autorización, el juez puede concederla cuando los motivos en que se funde la negativa no fueren razonables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab8fa8d5-f89c-47e6-8173-2d2f57fd052a', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '85', 'Matrimonio por poder', 85, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f3e29dd-c2de-4c7b-8c3d-56631b8bb1ff', 'ab8fa8d5-f89c-47e6-8173-2d2f57fd052a', 1, 'El matrimonio podrá celebrarse por poder. El mandato debe ser especial, expresar la identificación de la persona con la que debe contraerse el matrimonio y contener declaración jurada acerca de las cuestiones que menciona el artículo 93. La revocatoria del poder no surtirá efecto si fuere notificada legalmente al mandatario cuando el matrimonio ya estuviere celebrado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63845d42-9f8b-4ac1-8112-ba9555964eaf', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '86', 'Matrimonio celebrado fuera de la república', 86, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('850bb896-6e97-42f5-8a11-9c7b0b2123b2', '63845d42-9f8b-4ac1-8112-ba9555964eaf', 1, 'El matrimonio celebrado fuera del territorio nacional, en la forma y con los requisitos que en el lugar de su celebración establezcan las leyes, producirá todos sus efectos en la República, a no ser que medie impedimento absoluto para contraerlo por alguna de las causas que determina este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b52fabfe-0eb4-4630-a180-d39b90e945d2', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '87', 'Nacionalidad', 87, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('445a67c4-1335-46fd-ba0a-ef1a9b3a4e91', 'b52fabfe-0eb4-4630-a180-d39b90e945d2', 1, 'La guatemalteca casada con extranjero conserva su nacionalidad, a menos que quiera adoptar la de su cónyuge, en cuyo caso deberá hacerlo constar expresamente en las diligencias matrimoniales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('336c78c6-2ca9-42b2-8e54-a0f9e87af094', 'b52fabfe-0eb4-4630-a180-d39b90e945d2', 2, 'PARRAFO II Impedimentos para contraer matrimonio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2cff6902-6272-4b51-9aeb-2a333e3e5359', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '88', 'Casos de insubsistencia', 88, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a482d05-9ea9-4a1a-b530-db9908d420a8', '2cff6902-6272-4b51-9aeb-2a333e3e5359', 1, 'Tienen impedimento absoluto para contraer matrimonio: 1. Los parientes consanguíneos en línea recta, y en lo colateral, los hermanos y medio hermanos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4743fe99-ad3f-452f-8e27-231b9d997941', '2cff6902-6272-4b51-9aeb-2a333e3e5359', 2, '2. Los ascendientes y descendientes que hayan estado ligados por afinidad; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('809693d5-41f6-47c9-980a-86e75c71861d', '2cff6902-6272-4b51-9aeb-2a333e3e5359', 3, '3. Las personas casadas; y las unidas de hecho con persona distinta de su conviviente, mientras no se haya disuelto legalmente esa unión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e787fdb3-05af-4922-9760-c4ba23f98071', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '89', 'Ilicitud del matrimonio', 89, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('efaf2784-1055-4bdf-a674-a8a9409c2a52', 'e787fdb3-05af-4922-9760-c4ba23f98071', 1, 'No podrá ser autorizado el matrimonio: 1. Del menor de dieciocho años, sin el consentimiento expreso de sus padres o del tutor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('58fcd4a5-c21d-46f9-9ad4-1edc27ea070b', 'e787fdb3-05af-4922-9760-c4ba23f98071', 2, '2. Del varón menor de dieciséis años o de la mujer menor de catorce años cumplidos, salvo que antes de esa edad hubiere concebido la mujer y presten su consentimiento las personas que ejerzan la patria potestad o la tutela.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5514dd62-7927-4f7c-a19d-ae91bdb6e3f2', 'e787fdb3-05af-4922-9760-c4ba23f98071', 3, '3. De la mujer antes de que transcurran trescientos días contados desde la disolución del anterior matrimonio, o de la unión de hecho, o desde que se declare nulo el matrimonio, a menos que haya habido parto dentro de este término, o que uno de los cónyuges haya estado materialmente separado del otro o ausente por el término indicado. Si la nulidad del matrimonio hubiere sido declarada por impotencia del marido, la mujer podrá contraer nuevo matrimonio sin espera de término alguno.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb412b32-3fd3-4d09-988f-40bdfd2b330c', 'e787fdb3-05af-4922-9760-c4ba23f98071', 4, '4. Del tutor y del protutor o de sus descendientes, con la persona que esté bajo su tutela o protutela.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('294f928a-1894-490b-b16b-76435855b3a6', 'e787fdb3-05af-4922-9760-c4ba23f98071', 5, '5. Del tutor o del protutor o de sus descendientes, con la persona que haya estado bajo su tutela, sino después de aprobadas y canceladas las cuentas de su administración.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1eef5a8f-efd9-460c-a620-cdaa44dc988d', 'e787fdb3-05af-4922-9760-c4ba23f98071', 6, '6. Del que teniendo hijos bajo su patria potestad, no hiciere inventario judicial de los bienes de aquéllos, ni garantizare su manejo, salvo que la administración pasare a otra persona; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('888d4b62-d7db-4c59-845c-87fd9a7750a8', 'e787fdb3-05af-4922-9760-c4ba23f98071', 7, '7. Del adoptante con el adoptado, mientras dure la adopción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16138f0f-82c0-4718-b6c2-c481f137016c', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '90', 'Sanciones', 90, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38a6d06c-6e2d-494e-9248-1c80685490c2', '16138f0f-82c0-4718-b6c2-c481f137016c', 1, 'Si no obstante lo prescrito en el artículo anterior fuere celebrado el matrimonio, éste será válido, pero tanto el funcionario como las personas culpables de la Infracción serán responsables de conformidad con la ley y las personas a que se refieren los Incisos 4º y 5º, perderán la administración de los bienes de los menores, y no podrán sucederles por intestado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38c57d6f-7e28-4f48-84bb-e32fc9f9afec', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '91', NULL, 91, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d915284-60c3-4d52-a7e1-0999c9661870', '38c57d6f-7e28-4f48-84bb-e32fc9f9afec', 1, 'Si el funcionario que interviene en el acto tuviere conocimiento de la existencia de algún impedimento legal, ya por razón de oficio o por denuncia del Ministerio Público o de cualquier persona, ordenará la suspensión de las diligencias matrimoniales y no podrá proseguirlas sino hasta que los Interesados obtengan');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93ba7195-22f8-4f72-a02b-c1fc8c47011a', '38c57d6f-7e28-4f48-84bb-e32fc9f9afec', 2, 'resolución favorable por la autoridad competente. Si la denuncia no fuere ratificada, quedará sin efecto.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76136a65-c1b4-4382-9d81-ec4fbe9851e9', '38c57d6f-7e28-4f48-84bb-e32fc9f9afec', 3, 'PARRAFO III Celebración del matrimonio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('31f3d81e-aa11-47ab-b4f5-c23a5e7acd79', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '92', 'Funcionarios que pueden autorizar el matrimonio', 92, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0038b184-dd1c-4647-bcaf-1bb3f6bb15ba', '31f3d81e-aa11-47ab-b4f5-c23a5e7acd79', 1, 'El matrimonio debe autorizarse por el alcalde municipal o el concejal que haga sus veces, o por un notario hábil legalmente para el ejercicio de su profesión. También podrá autorizarlo el ministro de cualquier culto que tenga esa facultad, otorgada por la autoridad administrativa que corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e722bbcf-8636-48de-853b-f8cdb0487940', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '93', 'Formalidades', 93, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a311f7d9-56bb-4fe2-85a4-fd2782d0bf2b', 'e722bbcf-8636-48de-853b-f8cdb0487940', 1, 'Las personas civilmente capaces que pretendan contraer matrimonio, lo manifestarán así ante el funcionario competente de la residencia de cualquiera de los contrayentes, quien recibirá bajo juramento de cada uno de ellos, legalmente identificados, declaración sobre los puntos siguientes, que hará constar en acta: nombres y apellidos, edad, estado civil, vecindad, profesión u oficio, nacionalidad y origen, nombres de los padres y de los abuelos si los supieren, ausencia de parentesco entre sí que impida el matrimonio, no tener impedimento legal para contraerlo y régimen económico que adopten si no presentaren escritura de capitulaciones matrimoniales, y manifestación expresa de que no están legalmente unidos de hecho con tercera persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('25df737e-6bb0-4e8d-b8e4-57ef2f557942', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '94', 'Menores de edad', 94, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bc2e155-f921-49da-960d-e7392a01d619', '25df737e-6bb0-4e8d-b8e4-57ef2f557942', 1, 'Los menores de edad que soliciten contraer matrimonio, deben comparecer acompañados de sus padres, o tutores, o presentar autorización escrita de ellos, en forma auténtica, o judicial si procediere y, además, las partidas de nacimiento o, si esto no fuere posible, certificación de la calificación de edad declarada por el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9da79fc7-9568-4d1a-b94a-caf1d8e3a878', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '95', 'Contrayente que fue casado', 95, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a5c0914-353b-4c49-8492-f4789f480237', '9da79fc7-9568-4d1a-b94a-caf1d8e3a878', 1, 'El contrayente que hubiese sido casado, presentará el documento legal que acredite la disolución o insubsistencia del matrimonio anterior; si hubiese tenido hijos, comprobará estar garantizada la obligación de alimentarlos; y si tuviere bienes de menores bajo su administración, presentará el inventario respectivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e8d78232-b141-4059-ac68-6c2182b2eab2', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '96', 'Contrayente extranjero', 96, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('daa95b3d-dda7-4d40-b901-a3caf710cbe0', 'e8d78232-b141-4059-ac68-6c2182b2eab2', 1, 'El contrayente que fuere extranjero o guatemalteco naturalizado, deberá comprobar en forma fehaciente su identidad y libertad de estado. Previamente a la celebración del matrimonio, se publicarán edictos en el Diario Oficial y en otro de mayor circulación, por el término de 15 días, emplazando a denunciarlo a quienes sepan de algún impedimento legal para el mismo. Si el matrimonio no fuere celebrado dentro de los seis meses de publicados los edictos, éstos perderán su efecto legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9aedae8e-97be-4efb-9810-109312382238', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '97.1', NULL, 97, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e63d44be-b5a8-4478-86aa-e5a5e082f24a', '9aedae8e-97be-4efb-9810-109312382238', 1, 'La Constancia de sanidad es obligatoria para ambos contrayentes. Será extendida en los centros de atención médica públicos o por un médico y cirujano colegiado activo, haciendo constar que la persona examinada no padece de enfermedad contagiosa incurable, perjudicial al otro cónyuge o la descendencia, o que no tiene defectos físicos que imposibiliten la procreación. No están obligadas a presentar certificado de sanidad las personas que residan en lugares en que se carece de médico y cirujano colegiado activo o de centros de atención médica públicos y quienes ya hubieren tenido relaciones de hecho que hagan innecesario dicho certificado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('58709764-0130-4349-85e6-d8e4e6276da2', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '98', 'Señalamiento de día y hora', 98, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0368bfd-acee-41f4-a3fb-64a48b833edd', '58709764-0130-4349-85e6-d8e4e6276da2', 1, 'Cerciorado el funcionario de la capacidad de los contrayentes y cumplidos, en su caso, los requisitos que exigen los artículos anteriores, señalará, si lo solicitan los contrayentes, día y hora para la celebración del matrimonio, o procederá a su celebración Inmediata.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('256da978-0047-4277-8874-d03a4fd86038', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '99', 'Ceremonia de la celebración', 99, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb11da74-27fd-4867-9821-f10af5e48eec', '256da978-0047-4277-8874-d03a4fd86038', 1, 'Estando presentes los contrayentes, procederá el funcionario que debe autorizar el matrimonio, a dar lectura a los artículos 78, 108 a 114 de este Código; recibirá de cada uno de los cónyuges su consentimiento expreso de tomarse, respectivamente, como marido y mujer y, en seguida, los declarará unidos en matrimonio. El acta deberá ser aceptada y firmada por los cónyuges y los testigos, si los hubiere, poniendo su impresión digital los que no sepan hacerlo, además del funcionario autorizante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('02c95819-a3c6-47d9-bc22-0e2e29d289f6', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '100', 'Constancia del acto', 100, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88ee05b7-b95f-4410-b2fa-ccf99e7de817', '02c95819-a3c6-47d9-bc22-0e2e29d289f6', 1, 'Una vez efectuado el matrimonio, el funcionario que lo autorice entregará inmediatamente constancia del acto a los contrayentes, razonará las cédulas de vecindad y demás documentos de identificación que se le presenten, y enviará aviso a la Oficina de Registro de Cédula de Vecindad respectiva, dentro de los 15 días siguientes a la celebración de dicho acto, para que se hagan las anotaciones correspondientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f90a90ee-2242-4ab9-a606-dd554163f802', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '101', 'Actas de matrimonio', 101, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('abc9793f-a6c2-4c91-a0dc-64a1c45af36c', 'f90a90ee-2242-4ab9-a606-dd554163f802', 1, 'Las actas de matrimonio serán asentadas en un libro especial que deberán llevar las municipalidades. Los notarios harán constar el matrimonio en acta notarial que deberá ser protocolizada, y los ministros de los cultos, en libros debidamente autorizados por el Ministerio de Gobernación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9c1da3a-3106-4fc5-9c77-dffaf32858c2', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '102', 'Copia del acta al registro civil', 102, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('234d969d-80a0-443a-85e0-f91634510593', 'e9c1da3a-3106-4fc5-9c77-dffaf32858c2', 1, 'Dentro de los quince días hábiles siguientes a la celebración del matrimonio, el alcalde que lo haya autorizado deberá enviar al Registro Civil que corresponda, copia certificada del acta, y los notarios y ministros de los cultos aviso circunstanciado. La falta de cumplimiento de esta');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f9713c0c-7ea2-46d5-94ff-8d77399e53b0', 'e9c1da3a-3106-4fc5-9c77-dffaf32858c2', 2, '1 Reformado como aparece en el texto por el artículo 1 del Decreto 08-2008, publicado en el Diario de Centro América el 15 de marzo de 2007');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94356b0a-bb9d-4851-85ab-ecd273d331a3', 'e9c1da3a-3106-4fc5-9c77-dffaf32858c2', 3, 'obligación será sancionada, en cada caso, con multa de uno a cinco quetzales, que impondrá el juez local a favor de la municipalidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('300b0caf-83d8-4fee-938b-faa4fc9fc802', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '103', NULL, 103, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae6c3058-abc8-4877-a882-41332de509c5', '300b0caf-83d8-4fee-938b-faa4fc9fc802', 1, 'Todos los días y horas son hábiles para la celebración del matrimonio. Las diligencias, constancias, certificaciones, avisos y testimonios relativos al mismo se extenderán en papel simple.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ecf64a1c-95aa-4f07-8bd4-0d274fa5538a', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '104', NULL, 104, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28b655c5-3298-4c9c-88a4-8a28469b53fd', 'ecf64a1c-95aa-4f07-8bd4-0d274fa5538a', 1, 'Cuando se trate de matrimonios que deban celebrarse fuera del perímetro de la sede municipal, el alcalde, o quien haga sus veces, concurrirá a donde sea necesario, siempre que los interesados faciliten los medios de transporte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eccd90e8-a05e-4fa1-b1c5-e4159e5d26d2', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '105', 'Matrimonio en artículo de muerte', 105, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('08cc7682-6d52-443d-ab02-ef44bbc847d8', 'eccd90e8-a05e-4fa1-b1c5-e4159e5d26d2', 1, 'En caso de enfermedad grave de uno de ambos contrayentes, podrá ser autorizado el matrimonio sin observarse las formalidades establecidas, siempre que no exista ningún impedimento ostensible y evidente que haga ilegal el acto y que conste claramente el consentimiento de los contrayentes enfermos. El funcionario deberá constituirse en el lugar donde sea requerido por los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('da3670ef-6795-4bb7-9471-7a123a36d715', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '106', 'Recursos', 106, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc10ff83-911f-4a9e-bce2-dde749c23f94', 'da3670ef-6795-4bb7-9471-7a123a36d715', 1, 'Contra los actos y providencias del funcionario que deba celebrar el matrimonio, que pongan obstáculo indebido a su celebración, podrán ocurrir los interesados a los jueces de Primera Instancia o de paz de la jurisdicción, quienes, en vista de las justificaciones que se les presenten, resolverán lo que proceda, sin demora alguna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('311789bd-df07-4d5c-a9bd-00014a713da9', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '107', 'Militares', 107, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d498137-3512-498e-afe6-00d21efc6789', '311789bd-df07-4d5c-a9bd-00014a713da9', 1, 'Los militares y demás individuos pertenecientes al Ejército, que se hallen en campaña o en plaza sitiada, podrán contraer matrimonio ante el jefe del cuerpo o de la plaza, siempre que no tengan ningún impedimento notorio que imposibilite la unión. Dentro de quince días de terminada la campaña o levantado el sitio, se enviará el acta original del matrimonio al Registro Civil que corresponda.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('33400d4f-8130-47f2-a33d-0f67add8a959', '311789bd-df07-4d5c-a9bd-00014a713da9', 2, 'PARRAFO IV Deberes y derechos que nacen del matrimonio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d0aa3a1-271e-4071-bcbf-77fa0ac172d6', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '108', 'Apellido de la mujer casada', 108, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7ed29ec-e09b-4506-91e5-70a953f7f622', '7d0aa3a1-271e-4071-bcbf-77fa0ac172d6', 1, 'Por el matrimonio, la mujer tiene el derecho de agregar a su propio apellido el de su cónyuge y de conservarlo siempre, salvo que el matrimonio se disuelva por nulidad o por divorcio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1b34d7d3-0139-4670-b5ae-92edf4e53c2b', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '109', 'Representación conyugal', 109, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f15ba0dc-1033-465a-91da-4d3878425660', '1b34d7d3-0139-4670-b5ae-92edf4e53c2b', 1, 'La representación conyugal corresponde en igual forma a ambos cónyuges, quienes tendrán autoridad y consideraciones iguales en el hogar, de común acuerdo fijarán el lugar de su residencia y arreglarán todo lo relativo a la educación y establecimiento de los hijos y a la economía familiar. En caso de divergencia entre los cónyuges, el juez de familia decidirá a quien le corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d52499c3-0ec3-4ada-a653-1847107a5ebf', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '110', 'Protección a la mujer', 110, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76da95ff-7c95-4d77-8e88-39c697913d3d', 'd52499c3-0ec3-4ada-a653-1847107a5ebf', 1, 'El marido debe protección y asistencia a su mujer y está obligado a suministrarle todo lo necesario para el sostenimiento del hogar de acuerdo con sus posibilidades económicas. Ambos cónyuges tienen la oblación de atender y de cuidar a sus hijos, durante la minoría de edad de estos últimos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('06e14b06-e362-4e0b-8b69-e698e182ae64', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '111', 'Obligaciones de la mujer en el sostenimiento del hogar', 111, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('852fc49d-a071-40dd-82ba-17e08644c41c', '06e14b06-e362-4e0b-8b69-e698e182ae64', 1, 'La mujer deberá también contribuir equitativamente al sostenimiento del hogar, si tuviere bienes propios o desempeñare algún empleo, profesión, oficio o comercio; pero si el marido estuviere imposibilitado para trabajar y careciere de bienes propios, la mujer cubrirá todos los gastos con los ingresos que reciba.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3551de87-310a-498d-bd94-22cb9d270fc4', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '112', NULL, 112, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e504d79a-6b56-406a-ae07-f2e25d117c5c', '3551de87-310a-498d-bd94-22cb9d270fc4', 1, 'Derechos de la mujer sobre los ingresos del marido La mujer tendrá siempre derecho preferente sobre el sueldo, salario o ingresos del marido, por las cantidades que correspondan para alimentos de ella y de sus hijos menores.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29b49f34-e328-4751-9ca6-45ffae171f73', '3551de87-310a-498d-bd94-22cb9d270fc4', 2, 'Igual derecho compete al marido en los casos en que la mujer tenga la obligación de contribuir en todo o en parte para los gastos de la familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0b6cf57d-9898-47e1-8511-dcbd3d59d19c', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '113.2', 'Derogado', 113, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ffc1409-b4d8-4679-8660-ab0a86b42258', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '114.3', 'Derogado', 114, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b1f8c17f-e672-44ef-8c99-3052ece57c7d', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '115', 'Representación de la mujer', 115, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e4256a1-fffc-492c-8b8c-c855b89fe7b8', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 1, 'En caso de divergencia entre los cónyuges en cuanto el ejercicio de la representación conyugal, el Juez de Familia, considerando la conducta de cada uno de los integrantes de la pareja, tanto afuera como dentro del hogar, designarán a cuál de los cónyuges confiere la representación, indicando el tiempo por el que se le confiere y las condiciones que debe cumplir el otro cónyuge para recuperar la posibilidad de ejercer nuevamente la misma. En todo caso la administración se ejercerá individualmente, sin necesidad de declaratoria judicial para tal efecto en los siguientes casos:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2577a456-b28a-4e08-96c8-4d862029082d', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 2, '1. Si se declarara la interdicción judicial de uno de los cónyuges;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('072bb0e8-4633-4827-8a9d-2b74c507728e', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 3, '2. En caso de abandono voluntario del hogar o por declaratoria de ausencia, y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2b35876-8b88-45ea-aaf8-7debeb07d768', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 4, '2 Derogado por el artículo 3 del Decreto 80-98 publicado en el Diario de Centro América el 31 de diciembre de 1998. 3 Ibídem');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('58f447b5-47a7-4a02-a078-982bb3cbb7e5', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 5, '3. por condena de prisión, por todo el tiempo que dure la misma.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b36ed2d6-08cd-4d61-a429-cc6e4856753d', 'b1f8c17f-e672-44ef-8c99-3052ece57c7d', 6, 'PARRAFO V Régimen económico del matrimonio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d18a7cb3-5444-471c-bfa6-fb5531a74ea0', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '116', 'Capitulaciones matrimoniales', 116, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b02565f-8b58-467c-98d1-95d006689f00', 'd18a7cb3-5444-471c-bfa6-fb5531a74ea0', 1, 'El régimen económico del matrimonio se regula por las capitulaciones matrimoniales otorgadas por los contrayentes antes o en el acto de la celebración del matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33f30205-24ee-495b-9e9e-34d792b89891', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '117', NULL, 117, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a132a41c-74b3-4857-b1b0-59f17c66e2c2', '33f30205-24ee-495b-9e9e-34d792b89891', 1, 'Las capitulaciones matrimoniales son los pactos que otorgan los contrayentes para establecer y regular el régimen económico del matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8062122a-f8e8-4ed0-a44f-bb78d0f2b7ac', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '118', NULL, 118, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19f70701-0f61-482a-ae98-425ac0ecddef', '8062122a-f8e8-4ed0-a44f-bb78d0f2b7ac', 1, 'Son obligatorias las capitulaciones matrimoniales en los casos siguientes: 1. Cuando alguno de los contrayentes tenga bienes cuyo valor llegue a dos mil quetzales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('100df02e-59c6-4949-b9bc-61fb9c520e32', '8062122a-f8e8-4ed0-a44f-bb78d0f2b7ac', 2, '2. Si alguno de los contrayentes ejerce profesión, arte u oficio, que le produzca renta o emolumento que exceda de doscientos quetzales al mes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2841ed0a-ca78-48c1-beaa-9b6f3040db99', '8062122a-f8e8-4ed0-a44f-bb78d0f2b7ac', 3, '3. Si alguno de ellos tuviere en administración bienes de menores o incapacitados que estén bajo su patria potestad, tutela o guarda; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('83a4b57e-d5b1-497d-bb69-72295de92b65', '8062122a-f8e8-4ed0-a44f-bb78d0f2b7ac', 4, '4. Si la mujer fuere guatemalteca y el varón extranjero o guatemalteco naturalizado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('31559d2f-bbcb-40c5-bcd2-030a4718b5c8', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '119', NULL, 119, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5c15c46-7a7c-4318-b590-6c91433081a3', '31559d2f-bbcb-40c5-bcd2-030a4718b5c8', 1, 'Las capitulaciones matrimoniales deberán constar en escritura pública o en acta levantada ante el funcionario que haya de autorizar el matrimonio. El testimonio de la escritura o la certificación del acta, se inscribirán en el Registro Civil, una vez efectuado el matrimonio; y también en el Registro de la Propiedad, si se afectaren bienes inmuebles o derechos reales sobre los mismos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('159f4055-4ede-4da8-9616-0a2a021f7a54', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '120', NULL, 120, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1bf3047a-5095-4436-870a-af92c5bd84ac', '159f4055-4ede-4da8-9616-0a2a021f7a54', 1, 'Son nulas y se tendrán por no puestas, las cláusulas del convenio que contravengan las disposiciones de la ley, o restrinjan derechos y obligaciones de los cónyuges entre sí o con respecto a los hijos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('832e7692-dd2e-4129-8e72-4353f6e6d72b', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '121', NULL, 121, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad27b015-308a-43a2-b97e-b56d901413fe', '832e7692-dd2e-4129-8e72-4353f6e6d72b', 1, 'Las capitulaciones deberán comprender: 1. La designación detallada de los bienes que tenga cada uno de los cónyuges al contraer matrimonio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('abb18e2c-9571-417f-ac86-9e30ff668359', '832e7692-dd2e-4129-8e72-4353f6e6d72b', 2, '2. Declaración del monto de las deudas de cada uno; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b0c1183-3861-4a8d-bead-610e2c6c68bb', '832e7692-dd2e-4129-8e72-4353f6e6d72b', 3, '3. Declaración expresa de los contrayentes sobre si adoptan el régimen de comunidad absoluta, el de separación absoluta, o el de comunidad de gananciales; o con las modalidades y condiciones a que quieran sujetarlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5bd17dcf-1042-494c-bcc7-cace754e8d4c', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '122', 'Comunidad absoluta', 122, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6457b2f-cd03-4115-97c7-49dd4f80154b', '5bd17dcf-1042-494c-bcc7-cace754e8d4c', 1, 'En el régimen de comunidad absoluta, todos los bienes aportados al matrimonio por los contrayentes o adquiridos durante el mismo, pertenecen al patrimonio conyugal y se dividirán por mitad al disolverse el matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('696b49dc-44ef-4906-9abe-68ead44158c7', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '123', 'Separación absoluta', 123, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('454322ea-56a7-42c9-bec7-7fbc02a3a80e', '696b49dc-44ef-4906-9abe-68ead44158c7', 1, 'En el régimen de separación absoluta cada cónyuge conserva la propiedad y administración de los bienes que le pertenecen y será dueño exclusivo de los frutos, productos y accesiones de los mismos. Serán también propios de cada uno de los cónyuges los salarios, sueldos, emolumentos y ganancias que obtuviere por servicios personales o en el ejercicio del comercio o industria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('da99a0d9-4332-4f88-b6e2-6ce14b460984', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '124', 'Comunidad de gananciales', 124, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c937a3e-a0b4-487d-ba09-aa63093dfa0b', 'da99a0d9-4332-4f88-b6e2-6ce14b460984', 1, 'Mediante el régimen de comunidad de gananciales, el marido y la mujer conservan la propiedad de los bienes que tenían" al contraer matrimonio y de los que adquieren durante él, por título gratuito o con el valor de unos y otros; pero harán suyos por mitad, al disolverse el patrimonio conyugal los bienes siguientes. 1. Los frutos de los bienes propios de cada uno de los cónyuges, deducidos los gastos de producción, reparación, conservación y cargas fiscales y municipales de los respectivos bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36d3b8aa-928a-486b-8a56-1fd6130b5f09', 'da99a0d9-4332-4f88-b6e2-6ce14b460984', 2, '2. Los que se compren o permuten con esos frutos, aunque se haga la adquisición a nombre de uno solo de los cónyuges; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f542a987-c98f-4a7f-9a78-0c7a87ec29ac', 'da99a0d9-4332-4f88-b6e2-6ce14b460984', 3, '3. Los que adquiera cada cónyuge con su trabajo, empleo, profesión o industria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aa012670-ca1c-4e84-bf99-5094636d4fee', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '125', 'Alteración de las capitulaciones', 125, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f120faa2-bc6d-4168-ae13-f41d08860d59', 'aa012670-ca1c-4e84-bf99-5094636d4fee', 1, 'Los cónyuges tienen derecho irrenunciable de alterar las capitulaciones matrimoniales y adoptar otro régimen económico del patrimonio conyugal, durante el matrimonio. La modificación de las capitulaciones matrimoniales deberá hacerse por medio de escritura pública que se inscribirá en los registros respectivos, y sólo perjudicará a tercero desde la fecha de la inscripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2e76ceb8-cef0-4647-9e1f-2f042ff142c4', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '126', 'Régimen subsidiario', 126, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a9c50239-d9e3-4e8b-9714-316339b5124d', '2e76ceb8-cef0-4647-9e1f-2f042ff142c4', 1, 'A falta de capitulaciones sobre los bienes se entenderá contraído el matrimonio bajo el régimen de comunidad de gananciales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a97f4cd5-b216-4cfc-b605-a05a8a8d2a33', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '127', 'Bienes propios de cada cónyuge', 127, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14e5f1b2-75f0-4c95-8abf-f30b3bd61c7f', 'a97f4cd5-b216-4cfc-b605-a05a8a8d2a33', 1, 'No obstante lo establecido en los artículos anteriores, son bienes propios de cada cónyuge los que adquiera por herencia, donación u otro título gratuito, y las indemnizaciones por accidentes o por seguros de');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf6a05da-3f7f-4b0f-b821-cdd0d258a93a', 'a97f4cd5-b216-4cfc-b605-a05a8a8d2a33', 2, 'vida, de daños personales o enfermedades, deducidas las primas pagadas durante la comunidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1bf05d9c-9f9e-48c7-9e81-fb5d5e8b27e8', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '128', 'Sostenimiento del hogar', 128, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25c3b973-740a-43c0-9e33-425b2b0f0bd4', '1bf05d9c-9f9e-48c7-9e81-fb5d5e8b27e8', 1, 'La separación absoluta de bienes no exime en ningún caso a los cónyuges, de la obligación común de sostener los gastos del hogar, la alimentación y educación de los hijos y las demás cargas del matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2fb9634c-af8e-4f57-8d1f-97ac81bce71a', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '129', 'Menaje de la casa', 129, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b512e572-6545-4b6c-ad9d-58b8938cd590', '2fb9634c-af8e-4f57-8d1f-97ac81bce71a', 1, 'Corresponde exclusivamente a la mujer el menaje del hogar conyugal, exceptuándose únicamente los objetos de uso personal del marido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a2ead1af-d1c2-41b7-9f13-11d4e1444e66', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '130', 'Cónyuges extranjeros', 130, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fdaf5236-5033-4005-b604-492cb6d4f740', 'a2ead1af-d1c2-41b7-9f13-11d4e1444e66', 1, 'El régimen de bienes entre cónyuges extranjeros de una misma nacionalidad, se determina, a falta de capitulaciones, por la ley personal que les es común en el momento de la celebración del matrimonio; y si fueren de distinta nacionalidad, por la del lugar en que los esposos fijaron el primer domicilio conyugal. El cambio de nacionalidad de los esposos o de uno de ellos, no tendrá influencia sobre el régimen de los bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('11e0f7b9-e588-4de5-8949-59b2ca616092', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '131', 'Administración', 131, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3dcaf95b-50ad-44f0-8da3-c1d0af2356b3', '11e0f7b9-e588-4de5-8949-59b2ca616092', 1, 'Bajo el régimen de comunidad absoluta o en el de comunidad de gananciales, ambos cónyuges administrarán el patrimonio conyugal, ya sea en forma conjunta o separadamente. Cada cónyuge o conviviente tiene la libre disposición de los bienes que se encuentran inscritos a su nombre en los registros públicos, sin perjuicio de responden ante el otro por la disposición que hiciere de los bienes comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc885564-b153-48a5-8d75-dc5eddcaf05b', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '132', 'Oposición', 132, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15d3188d-4dfc-4de7-9fc9-bc83204aff61', 'dc885564-b153-48a5-8d75-dc5eddcaf05b', 1, 'Cualquiera de los cónyuges puede oponerse a que el otro realice actos que redunden o puedan redundar en perjuicio del patrimonio conyugal. También pueden pedir al juez que haga cesar la administración del otro cónyuge, así como que modifique el régimen económico del matrimonio por el de separación de bienes, cuando el otro cónyuge incurra en negligencia, incapacidad o imprudencia en la administración del patrimonio conyugal, poniendo en riesgo el patrimonio o el adecuado suministro de alimentos para la familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('27b6dff4-cf9a-42d7-8101-f6db3faa9a1d', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '133.4', 'Derogado', 133, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c1679fc-9830-4739-ac9b-170c2da59b36', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '134', 'Marido menor de edad', 134, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('17e48f70-5994-45a2-a9ba-130390158df0', '1c1679fc-9830-4739-ac9b-170c2da59b36', 1, 'Si el marido fuere menor de dieciocho años, deberá ser asistido en la administración de sus bienes y los del patrimonio conyugal, por la persona que ejerza sobre él la patria potestad o tutela; pero si la mujer fuere');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('790641d2-84e8-4f20-bca4-2d14fd8fe7cf', '1c1679fc-9830-4739-ac9b-170c2da59b36', 2, '4 Derogado por el Artículo 7 del Decreto No. 80-98 publicado en Diario de Centro América el 31 de diciembre de 1998.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7dafac79-2184-4dfa-b2aa-8cd0baf082f9', '1c1679fc-9830-4739-ac9b-170c2da59b36', 3, 'mayor de edad, ella ejercerá la administración de los bienes hasta que el marido llegue a la mayoría.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ce155e8-a297-48f4-9db2-c78435dabbfd', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '135', 'Responsabilidad de los bienes comunes', 135, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0afee4f-78c3-4595-913f-b2bbc64a73c5', '1ce155e8-a297-48f4-9db2-c78435dabbfd', 1, 'De las obligaciones que contraiga cualquiera de los cónyuges para el sostenimiento de la familia, responderán los bienes comunes, y si éstos fueren insuficientes, los bienes propios de cada uno de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('00d4fe6e-112f-424a-888f-1ad458d3fb60', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '136', 'Hechos ilícitos', 136, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0dfa230e-fe88-4365-b103-c0e1411a251b', '00d4fe6e-112f-424a-888f-1ad458d3fb60', 1, 'La responsabilidad civil por hechos ilícitos de un cónyuge, no obliga al otro en sus bienes propios ni en su parte de los comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0c2791b4-2b51-4a96-814a-9fd6cd522204', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '137', 'Deudas anteriores al matrimonio', 137, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47082b4f-eb81-4f0b-8816-3958bb60f06d', '0c2791b4-2b51-4a96-814a-9fd6cd522204', 1, 'Las deudas anteriores al matrimonio serán pagadas con los bienes propios del que las contrajo, aun cuando aquél se rija por el régimen de comunidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9169fa12-9ffd-42a3-a765-a5e28a366539', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '138', 'Gastos de enfermedad y funerales', 138, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20dc1542-0188-4d3d-965d-aa8ec079c19f', '9169fa12-9ffd-42a3-a765-a5e28a366539', 1, 'Los gastos que causaren las enfermedades, así como los que se originen por funerales y lutos a consecuencia de la muerte de un cónyuge o de los hijos de ambos, se reputan deudas comunes del matrimonio, por las cuales son responsables los bienes propios de los cónyuges, en el caso de ser insuficientes los comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60a5bdb2-9d64-4e22-80de-ce7306fa30bb', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '139', 'Disolución de la comunidad de bienes', 139, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12508d25-7268-43e1-994c-8fd1705f350b', '60a5bdb2-9d64-4e22-80de-ce7306fa30bb', 1, 'La comunidad de bienes termina: 1º. Por la disolución del matrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de13e332-f35c-4ca6-87c3-39765ab89596', '60a5bdb2-9d64-4e22-80de-ce7306fa30bb', 2, '2º. Por separación de bienes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('130762ec-37e6-4d99-89f2-9316b4a57623', '60a5bdb2-9d64-4e22-80de-ce7306fa30bb', 3, '3º. Por ser condenado en sentencia judicial firme alguno de los cónyuges por delito cometido en contra del otro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c8283430-32a4-4f41-b1a2-5d58b2672e86', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '140', 'Liquidación del patrimonio conyugal', 140, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('079ac43d-4e45-4458-978b-bcf29824c339', 'c8283430-32a4-4f41-b1a2-5d58b2672e86', 1, 'Concluida la comunidad de bienes, se procederá inmediatamente a su liquidación. Si el régimen económico fuere el de comunidad parcial, los bienes que queden después de pagar las cargas y obligaciones de la comunidad y de reintegrar los bienes propios de cada cónyuge, son gananciales que corresponderán por mitad, a marido y mujer o a sus respectivos herederos');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bfa7b2bb-ba6d-4d37-9c17-da0fdca4fed9', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '141', NULL, 141, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ebef6810-8b86-433e-8cf1-fac05ae421ba', 'bfa7b2bb-ba6d-4d37-9c17-da0fdca4fed9', 1, 'El abandono injustificado del hogar conyugal por uno de los cónyuges, hace cesar para él, desde el día del abandono, los efectos de la comunidad de bienes en cuanto le favorezcan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63406465-9a7d-4d85-afac-20a8c20e7f0e', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '142', NULL, 142, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13b08269-75cf-4dd2-b6d2-3bef9b239e69', '63406465-9a7d-4d85-afac-20a8c20e7f0e', 1, 'En caso de separación de hecho, el cónyuge culpable no tendrá derecho a gananciales durante el tiempo de la separación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8435f397-4bd9-40cc-a6e9-c3b92eafe659', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '143', NULL, 143, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aec9d483-e2b2-4e64-998d-f0e1894e5c17', '8435f397-4bd9-40cc-a6e9-c3b92eafe659', 1, 'Cuando se declare la nulidad del matrimonio, el cónyuge que hubiere obrado de mala fe no tendrá parte en las utilidades. Si los dos procedieron de mala fe, el hecho de ambos quedará compensado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2c6f2506-cddf-4474-bfd3-b82caebf26b2', '8435f397-4bd9-40cc-a6e9-c3b92eafe659', 2, 'PARRAFO VI Insubsistencia y nulidad del matrimonio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d64a099e-1756-409f-8383-e9f608f5eebf', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '144', 'Insubsistencia del matrimonio', 144, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c1315e41-3b0d-470c-9371-472fa7c5ef42', 'd64a099e-1756-409f-8383-e9f608f5eebf', 1, 'El matrimonio es insubsistente en los casos que enumera el artículo 88. La declaratoria de insubsistencia puede hacerla de oficio el juez, con intervención de los cónyuges y del Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5f33f636-110f-4584-bb9b-5afe67728347', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '145', 'Anulabilidad del matrimonio', 145, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7963ee8a-06d2-41e5-902e-9c2ea2d44f7f', '5f33f636-110f-4584-bb9b-5afe67728347', 1, 'Es anulable el matrimonio: 1. Cuando uno o ambos cónyuges han consentido por error, dolo o coacción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd522446-9dc4-4d36-9111-81ca64a5be3f', '5f33f636-110f-4584-bb9b-5afe67728347', 2, '2. Del que adolezca de impotencia absoluta o relativa para la procreación, siempre que por su naturaleza sea perpetua, incurable y anterior al matrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7ca80ab-567c-427e-83c8-ee4b2ecf3df3', '5f33f636-110f-4584-bb9b-5afe67728347', 3, '3. De cualquier persona que padezca incapacidad mental al celebrarlo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99f0ed1c-54c0-4a67-83dd-d0c5e5ac4470', '5f33f636-110f-4584-bb9b-5afe67728347', 4, '4. Del autor, cómplice o encubridor de la muerte de un cónyuge, con el cónyuge sobreviviente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4b48a53d-5bb8-4f0c-892b-3af255ecf67f', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '146', 'Error o dolo', 146, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70c6e8b3-9cdf-4aef-b9aa-26483c47960a', '4b48a53d-5bb8-4f0c-892b-3af255ecf67f', 1, 'El error que hace anulable el matrimonio es el que recae sobre la identidad personal del otro contrayente, o se produce por la ignorancia de algún defecto sustancial del mismo, de tal gravedad, que haga Insoportable la vida en común o constituya un peligro para la prole. La acción de nulidad que nace del error o dolo, sólo puede deducirse por el cónyuge engañado, dentro de treinta días de haberse dado cuenta del error o del dolo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('512ebe7b-1c75-4ddc-a5c5-50c9f51ec40c', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '147', 'Violencia', 147, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c0a0237-daca-4477-bc8e-d05cd080f46e', '512ebe7b-1c75-4ddc-a5c5-50c9f51ec40c', 1, 'La anulación por motivo de coacción corresponde demandarla al contrayente agraviado, dentro de sesenta días contados desde la fecha en que cesó la violencia, amenaza o intimidación. En el caso del matrimonio del raptor con la raptada, el término comenzará a contarse desde que la mujer haya recobrado su plena libertad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a49beea4-5c89-418f-a0aa-55e719665cd5', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '148', 'Ejercicio de las acciones', 148, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70f2a3f1-3953-4e7e-8cf9-8df5b81f932b', 'a49beea4-5c89-418f-a0aa-55e719665cd5', 1, 'La anulación del matrimonio por ocurrir el caso del inciso 2º del artículo 145, puede pedirse por cualquiera de los contrayentes si la impotencia es relativa; pero si fuere absoluta el cónyuge impotente no podrá demandar la nulidad.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2003233c-f77c-4556-b469-b9f553df1c4f', 'a49beea4-5c89-418f-a0aa-55e719665cd5', 2, 'La acción deberá ser ejercida dentro de seis meses de haberse efectuado el matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('797005f5-b393-4dbb-b95f-558d994dda9b', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '149', NULL, 149, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20198f19-6f51-483e-8544-c48622eca8fc', '797005f5-b393-4dbb-b95f-558d994dda9b', 1, 'La acción de nulidad, en el caso del inciso 4º del articulo 145, puede ser deducida por el cónyuge inocente, por los hijos de la víctima o por el Ministerio Público, dentro del término de seis meses contados, para el cónyuge inocente, desde que tuvo conocimiento de la culpabilidad de su nuevo cónyuge y para los hijos y el Ministerio Público, desde que se celebró el nuevo matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e831be5c-9f35-4d11-89cd-bdc023d007de', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '150', NULL, 150, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0d47124d-246d-4813-8276-1192c13baf6a', 'e831be5c-9f35-4d11-89cd-bdc023d007de', 1, 'La nulidad por incapacidad mental de uno de los cónyuges puede demandarse por el cónyuge capaz, por el padre, madre o tutor del incapacitado y por el Ministerio Público, dentro de sesenta días contados desde que tengan conocimiento del matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('86456a02-e943-40ff-b9bb-c7bc5cf96614', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '151', NULL, 151, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3573f325-c39c-407c-806d-1d3f2da4065f', '86456a02-e943-40ff-b9bb-c7bc5cf96614', 1, 'La acción de nulidad, que no sea la determinada en los artículos 149 y 150, no pasa a los herederos del cónyuge, pero sí podrán éstos continuar la demanda iniciada por su causante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('40404682-79ef-4bbd-a956-6f71c575220a', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '152', NULL, 152, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e05bd2c-2655-4f68-a016-4eaa09ff042d', '40404682-79ef-4bbd-a956-6f71c575220a', 1, 'La declaratoria de nulidad o de insubsistencia del matrimonio se mandará publicar por el juez en el Diario Oficial y se comunicará a los registros civiles y de la propiedad, para que se hagan las cancelaciones o anotaciones correspondientes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ce13ff8-ddb2-42fd-842a-ddd88dde8077', '40404682-79ef-4bbd-a956-6f71c575220a', 2, 'PARRAFO VII De la separación y del divorcio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7bfb9c44-a71d-463d-8e76-b2b0019fd4a6', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '153', NULL, 153, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b38c359-e9e1-415f-9ed9-a04cd5b6dbf9', '7bfb9c44-a71d-463d-8e76-b2b0019fd4a6', 1, 'EL matrimonio se modifica por la separación y se disuelve por el divorcio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d41cea49-1abb-43eb-bab5-b3440003a8c8', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '154', 'Separación y divorcio', 154, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4dda97c-a605-4098-b251-d15ad3766495', 'd41cea49-1abb-43eb-bab5-b3440003a8c8', 1, 'La separación de personas, así como el divorcio, podrán declararse: 1. Por mutuo acuerdo de los cónyuges; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57bd3717-180c-4036-8e7a-3c02e8a8a6a4', 'd41cea49-1abb-43eb-bab5-b3440003a8c8', 2, '2. Por voluntad de uno de ellos mediante causa determinada.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('81843ccf-d312-44b2-9c8d-ab62e58bbb8d', 'd41cea49-1abb-43eb-bab5-b3440003a8c8', 3, 'La separación o divorcio por mutuo acuerdo de los cónyuges, no podrá pedirse sino después de un año, contado desde la fecha en que se celebró el matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d59d923-1061-4e40-bee2-fca1bf532d58', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '155', 'Causas', 155, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('16a6a914-d0d5-4a5f-8f9f-2ed8c961ac52', '2d59d923-1061-4e40-bee2-fca1bf532d58', 1, 'Son causas comunes para obtener la separación o el divorcio: 1. La infidelidad de cualquiera de los cónyuges;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dbf4c696-20b9-45f3-93cf-1c2fb8ad2060', '2d59d923-1061-4e40-bee2-fca1bf532d58', 2, '2. Los malos tratamientos de obra, las riñas y disputas continuas, las injurias graves y ofensas al honor y, en general, la conducta que haga insoportable la vida en común;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d96d6f71-dd1a-482d-a3a4-e49eb25f6478', '2d59d923-1061-4e40-bee2-fca1bf532d58', 3, '3. El atentado de uno de los cónyuges contra la vida del otro o de los hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('84be05f1-9e4e-4e5d-abf5-50f434768136', '2d59d923-1061-4e40-bee2-fca1bf532d58', 4, '4. La separación o abandono voluntarios de la casa conyugal o la ausencia inmotivada, por más de un año;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11e69a40-50bb-4912-a2ca-e66c912b04c5', '2d59d923-1061-4e40-bee2-fca1bf532d58', 5, '5. El hecho de que la mujer de a luz durante el matrimonio, a un hijo concebido antes de su celebración, siempre que el marido no haya tenido conocimiento del embarazo antes del matrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87c9fc61-37c0-40f5-99ca-130473ec5201', '2d59d923-1061-4e40-bee2-fca1bf532d58', 6, '6. La incitación del marido para prostituir a la mujer o corromper a los hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de48614b-9d38-464f-813c-091c755ec760', '2d59d923-1061-4e40-bee2-fca1bf532d58', 7, '7. La negativa infundada de uno de los cónyuges a cumplir con el otro o con los hijos comunes, los deberes de asistencia y alimentación a que está legalmente obligado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5c22a249-3baa-440b-a9d8-bf3b5e79a972', '2d59d923-1061-4e40-bee2-fca1bf532d58', 8, '8. La disipación de la hacienda doméstica;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d02127a8-b672-435a-9cdf-f8e451fb50a8', '2d59d923-1061-4e40-bee2-fca1bf532d58', 9, '9. Los hábitos de juego o embriaguez, o el uso indebido y constante de estupefacientes, cuando amenazaren causar la ruina de la familia o constituyan un continuo motivo de desavenencia conyugal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a48b73ae-9def-49e2-aff3-0c493da0f20e', '2d59d923-1061-4e40-bee2-fca1bf532d58', 10, '10. La denuncia de delito o acusación calumniosa hecha por un cónyuge contra el otro;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b019923c-a009-4807-90e0-f84d461bd915', '2d59d923-1061-4e40-bee2-fca1bf532d58', 11, '11. La condena de uno de los cónyuges, en sentencia firme, por delito contra la propiedad o por cualquier otro delito común que merezca pena mayor de cinco años de prisión;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50ce7e9a-b9cb-482e-b292-db64408a8d2c', '2d59d923-1061-4e40-bee2-fca1bf532d58', 12, '12. La enfermedad grave, incurable y contagiosa, perjudicial al otro cónyuge o a la descendencia;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('61d958c7-7a4b-4aef-9d9e-ac144ae29349', '2d59d923-1061-4e40-bee2-fca1bf532d58', 13, '13. La impotencia absoluta o relativa para la procreación, siempre que por su naturaleza sea incurable y posterior al matrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dcd61790-7ec2-4aa6-b6f8-2f0287a8b19f', '2d59d923-1061-4e40-bee2-fca1bf532d58', 14, '14. La enfermedad mental incurable de uno de los cónyuges que sea suficiente para declarar la interdicción; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5514ddfd-c798-4637-b0bc-bf6beb3872db', '2d59d923-1061-4e40-bee2-fca1bf532d58', 15, '15. Asimismo, es causa para obtener el divorcio, la separación de personas declarada en sentencia firme.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f657df67-3534-47ce-b4a0-df95ccf13c0a', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '156', NULL, 156, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d1a51a7-04ba-45da-addb-5370af7b05cc', 'f657df67-3534-47ce-b4a0-df95ccf13c0a', 1, 'Se presume voluntario el abandono e inmotivada la ausencia a que se refiere el Inciso 4º del artículo anterior; pero contra tales presunciones se admite prueba en contrario. La acción respectiva debe promoverse durante la ausencia o abandono del cónyuge demandado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f343ca1-1d84-4b9b-a1d6-0df5b9b5ce77', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '157', NULL, 157, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bdf9164-20ac-4dc6-a808-ca459a61a838', '4f343ca1-1d84-4b9b-a1d6-0df5b9b5ce77', 1, 'No son causa de separación ni de divorcio, los actos de infidelidad cometidos en connivencia o con el consentimiento del otro cónyuge, o cuando después de consumados y conocidos por el otro, han continuado los cónyuges conviviendo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a56c3bd6-2c51-4891-82fa-4d54d57b58b7', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '158', NULL, 158, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9a9d93ab-b6e7-4373-bb39-c9f17174a83f', 'a56c3bd6-2c51-4891-82fa-4d54d57b58b7', 1, 'Quién puede solicitar la separación o el divorcio por causa determinada El divorcio y la separación sólo pueden solicitarse por el cónyuge que no haya dado causa a él, y dentro de los seis meses siguientes al día en que hayan llegado a su conocimiento los hechos en que se funde la demanda.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4922b020-790a-4990-b37c-06623f0b8077', 'a56c3bd6-2c51-4891-82fa-4d54d57b58b7', 2, 'No puede declararse el divorcio o la separación con el simple allanamiento de la parte demandada. Asimismo, no es suficiente prueba para declarar el divorcio o la separación, la confesión de la parte demandada sobre la causa que lo motiva.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7865c51-c2b2-4a15-b24b-a0ae066732db', 'a56c3bd6-2c51-4891-82fa-4d54d57b58b7', 3, 'PARRAFO VIII Efecto de la separación y del divorcio');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('846fbaed-a29c-4aba-b39c-c0f91480c6e9', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '159', NULL, 159, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c66f120-0066-492d-b780-da1d6318949f', '846fbaed-a29c-4aba-b39c-c0f91480c6e9', 1, 'Son efectos civiles comunes de la separación y del divorcio, los siguientes: 1. La liquidación del patrimonio conyugal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7cf2891-2e9f-49df-9ea9-ac97cfa6b74c', '846fbaed-a29c-4aba-b39c-c0f91480c6e9', 2, '2. El derecho de alimentos a favor del cónyuge inculpable, en su caso; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('26d9c4fe-df22-463f-b074-e8bd38158a49', '846fbaed-a29c-4aba-b39c-c0f91480c6e9', 3, '3. La suspensión o pérdida de la patria potestad, cuando la causal de separación o divorcio la lleve consigo y haya petición expresa de parte interesada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('839a3190-f729-405a-9ce3-44dc25a0e542', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '160', NULL, 160, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2c1dae4-a515-4444-ab16-084fe5d965b1', '839a3190-f729-405a-9ce3-44dc25a0e542', 1, 'Son efectos propios de la separación, además de la subsistencia del vínculo conyugal, los siguientes: 1. El derecho del cónyuge inculpable, a la sucesión intestada del otro cónyuge; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('577f08a1-8996-4004-9f6f-787d534fc616', '839a3190-f729-405a-9ce3-44dc25a0e542', 2, '2. El derecho de la mujer de continuar usando el apellido del marido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('704a94d2-a4df-4096-94df-1213ad6ce132', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '161', NULL, 161, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7fdd453-2657-4236-834c-cfd5cf2f8c53', '704a94d2-a4df-4096-94df-1213ad6ce132', 1, 'Es efecto propio del divorcio la disolución del vínculo conyugal, que deja a los cónyuges en libertad para contraer nuevo matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8f0798b1-d553-4d08-95bb-8c8b2f254ac8', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '162', 'Protección a la mujer y a los hijos', 162, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5c299999-e923-4f84-ae13-2b9a97ef466d', '8f0798b1-d553-4d08-95bb-8c8b2f254ac8', 1, 'Desde el momento en que sea presentada la solicitud de separación o de divorcio, la mujer y los hijos quedarán bajo la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f2f9519-fb49-4b3a-be52-c8da8db00336', '8f0798b1-d553-4d08-95bb-8c8b2f254ac8', 2, 'protección de la autoridad para seguridad de sus personas y de sus bienes, y se dictarán las medidas urgentes que sean necesarias. Los hijos quedarán provisionalmente en poder del cónyuge que determine el Juez, hasta que se resuelva en definitiva, a no ser que causas graves obliguen a confiarlos a un tutor provisional.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('84eb4ef1-8ca2-48d6-8dcd-9a7ef7964e1e', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '163', 'Mutuo acuerdo', 163, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a374e1b1-b7b8-4450-adeb-540154885a9a', '84eb4ef1-8ca2-48d6-8dcd-9a7ef7964e1e', 1, 'Si la separación o el divorcio se solicitaren por mutuo acuerdo, los cónyuges deberán presentar un proyecto de convenio sobre los puntos siguientes: 1. A quién quedan confiados los hijos habidos en el matrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('873c880e-6637-4c4d-b8bb-536806ce8758', '84eb4ef1-8ca2-48d6-8dcd-9a7ef7964e1e', 2, '2. Por cuenta de quién de los cónyuges deberán ser alimentados y educados los hijos, y cuando esta obligación pese sobre ambos cónyuges, en qué proporción contribuirá cada uno de ellos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1b52f31d-c5f9-4c1d-8f92-1271c4a570a6', '84eb4ef1-8ca2-48d6-8dcd-9a7ef7964e1e', 3, '3. Qué pensión deberá pagar el marido a la mujer si ésta no tiene rentas propias que basten para cubrir sus necesidades; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f50eec4a-be19-4daf-9821-9a81cdaaa056', '84eb4ef1-8ca2-48d6-8dcd-9a7ef7964e1e', 4, '4. Garantía que se preste para el cumplimiento de las obligaciones que por el convenio contraigan los cónyuges.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ba660e3-a51f-4b00-ade1-cc1d07568d69', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '164', 'Obligación del juez', 164, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be9b867e-85b8-46d3-93b1-397e75ee59ad', '7ba660e3-a51f-4b00-ade1-cc1d07568d69', 1, 'Para el efecto expresado en el artículo anterior, el juez, bajo su responsabilidad, debe calificar la garantía, y si ésta, a su juicio, no fuere suficiente, ordenará su ampliación, de manera que lo estipulado asegure satisfactoriamente las obligaciones de los cónyuges.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8ac30efc-2e5e-4008-94e0-6589834e9b1c', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '165', NULL, 165, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd97baa5-7274-440f-9475-6f4579530366', '8ac30efc-2e5e-4008-94e0-6589834e9b1c', 1, 'Si la separación o el divorcio se demandaran por causa determinada, deberá el juez resolver las cuestiones a que se refiere el artículo 163; pero, tanto en este caso como en el de mutuo acuerdo, no podrá declararse la separación o el divorcio mientras no estén suficientemente garantizadas la alimentación y educación de los hijos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f02d3a53-a4e0-403c-bbef-31de08731f71', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '166', 'A quién se confían los hijos', 166, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bff3c99e-89d7-43b3-a55e-5fce1a7a3baf', 'f02d3a53-a4e0-403c-bbef-31de08731f71', 1, 'Los padres podrán convenir a quién de ellos se confían los hijos; pero el juez, por causas graves y motivadas, puede resolver en forma distinta, tomando en cuenta el bienestar de los hijos. Podrá también el juez resolver sobre la custodia y cuidado de los menores, con base en estudios o Informes de trabajadores sociales o de organismos especializados en la protección de menores. En todo caso, cuidará de que los padres puedan comunicarse libremente con ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8df10732-0751-446c-aca1-7b6b1b76db20', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '167', 'Obligación de los padres separados', 167, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6fe5200f-02eb-4f03-8a21-1c6c2acce7a6', '8df10732-0751-446c-aca1-7b6b1b76db20', 1, 'Cualesquiera que sean las estipulaciones del convenio o de la decisión judicial, el padre y la madre quedan sujetos, en todo caso, a las obligaciones que tienen para con sus hijos y conservan el derecho de relacionarse con ellos y la obligación de vigilar su educación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56777b5b-fd45-4611-95dc-a0e910f8ab77', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '168', 'Obligación del juez respecto de los hijos', 168, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cdfebfa0-c360-452e-8b01-9f0c3ff8e45d', '56777b5b-fd45-4611-95dc-a0e910f8ab77', 1, 'En cualquier tiempo el juez podrá dictar, a pedido de uno de los padres o de los parientes consanguíneos, o del Ministerio Público, las providencias que considere beneficiosas para los hijos y que sean requeridas por hechos nuevos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3f90456f-3bb9-4180-9f61-00bcc8255790', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '169.5', 'Pensión a la mujer', 169, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e059fbad-33c1-4d9c-a8dc-7fe562b643f3', '3f90456f-3bb9-4180-9f61-00bcc8255790', 1, 'La mujer inculpable gozará de la pensión alimenticia a que se refiere el Inciso 3º del artículo 163, la cual será fijada por el juez, si no lo hicieren los cónyuges, teniendo en cuenta las posibilidades de quien debe prestarla y las necesidades de quien ha de recibirla. La mujer gozará de la pensión mientras y no contraiga nuevo matrimonio; y el marido inculpable tendrá el mismo derecho, sólo cuando esté imposibilitado para dedicarse a trabajos que le proporcionen medio de subsistencia y no contraiga nuevo matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d6cbe8c6-4b51-4047-a5f4-0059987a039b', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '170', 'Liquidación del patrimonio conyugal', 170, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('84fcb95e-8797-4e98-b4e2-af39d98af961', 'd6cbe8c6-4b51-4047-a5f4-0059987a039b', 1, 'Al estar firme la sentencia que declare la insubsistencia o nulidad del matrimonio, o la separación o el divorcio, se procederá a liquidar el patrimonio conyugal en los términos prescritos por las capitulaciones, por la ley, o por las convenciones que hubieren celebrado los cónyuges.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc0df13c-ddda-45a1-9c51-bf7a0d4add12', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '171', 'Pérdida del apellido', 171, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b151290-5c31-4efa-975a-3b7739d81fce', 'fc0df13c-ddda-45a1-9c51-bf7a0d4add12', 1, 'La mujer divorciada no tiene derecho a usar el apellido del marido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4e886527-0899-467e-9b19-06297175e4c4', 'a0000000-0000-0000-0000-000000000001', '7cec98c0-f372-43bf-897d-74d06ee9fba5', '172', 'Efectos', 172, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca18dad3-443a-4e2d-8b8d-50eae0c418a1', '4e886527-0899-467e-9b19-06297175e4c4', 1, 'Los efectos y consecuencias de la insubsistencia o de la nulidad del matrimonio, así como los de la separación y del divorcio, se regirán, en cuanto a las personas, por las leyes del país donde hayan sido decretadas.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f27c25fc-2bc5-42a6-bea4-b6bf99d46f97', '4e886527-0899-467e-9b19-06297175e4c4', 2, 'DE LA UNION DE HECHO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37552bc2-8cd3-4e6f-8876-7e50c1bc7571', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '173', 'Cuándo procede declararla', 173, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad4bd06b-b79b-4d29-8e15-7443e00ad042', '37552bc2-8cd3-4e6f-8876-7e50c1bc7571', 1, 'La unión de hecho de un hombre y de una mujer con capacidad para contraer matrimonio, puede ser declarada por ellos mismos ante el alcalde de su vecindad o un notario, para que produzca efectos legales, siempre que exista hogar y la vida en común se haya mantenido constantemente por más de tres años ante sus familiares y relaciones sociales, cumpliendo los fines de procreación, alimentación y educación de los hijos y de auxilio recíproco.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e751e38f-641f-4ab2-bf50-a994903c2b7d', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '174', 'Cómo se hace constar', 174, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('433f5370-d56a-485f-93c8-96df3e4a172a', 'e751e38f-641f-4ab2-bf50-a994903c2b7d', 1, 'La manifestación a que se refiere el artículo anterior, se hará constar en acta que levantará el alcalde, o en escritura pública o acta notarial si fuere requerido un notario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('628aa33e-c022-44ac-b240-c7c3bab52abc', 'e751e38f-641f-4ab2-bf50-a994903c2b7d', 2, '5 Declara inconstitucional la frase que dice: "observe buena conducta y", por el Expediente Número 541- 2006 publicado el Diario de Centro América el 13-agosto de 2008.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bcc69274-ca5e-4b99-9768-276bcd851690', 'e751e38f-641f-4ab2-bf50-a994903c2b7d', 3, 'Identificados en forma legal, declararán bajo juramento sus nombres y apellidos, lugar y fecha de nacimiento, domicilio y residencia, profesión u oficio, día en que principió la unión de hecho, hijos procreados, indicando sus nombres y edades, y bienes adquiridos durante la vida en común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7cbbbde-c584-4081-99d6-716eff9b9e85', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '175', 'Aviso al registro civil', 175, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ef026c5-3cda-4d2c-aecc-5a933515be20', 'b7cbbbde-c584-4081-99d6-716eff9b9e85', 1, 'Dentro de los quince días siguientes, el alcalde o el notario dará aviso al Registro Civil jurisdiccional para que proceda a la inscripción de la unión de hecho, oficina que entregará a los interesados constancia de dicha inscripción, la que producirá iguales efectos que la certificación de matrimonio. La falta de este aviso será sancionada con una multa de cinco quetzales, que impondrá el juez local a solicitud de parte.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c82fb9d1-65cc-4769-84b4-2cc1437b82fb', 'b7cbbbde-c584-4081-99d6-716eff9b9e85', 2, 'La certificación del acta municipal o el testimonio notarial, se presentarán al Registro de la Propiedad, si se hubieren declarado inmuebles, como bienes comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a14d9ff3-35d9-4cfc-acb8-8e3dd955c62a', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '176', 'Enajenación de bienes', 176, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e05380fb-b2dc-402b-8df3-7a3ee9cdc290', 'a14d9ff3-35d9-4cfc-acb8-8e3dd955c62a', 1, 'Los bienes comunes no podrán enajenarse ni gravarse sin consentimiento de las dos partes, mientras dure la unión y no se haga liquidación y adjudicación de los mismos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('70719547-63e3-4a8d-9d8c-2838a46640d7', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '177', 'Unión de menores', 177, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c1aa262-8748-47d8-8afe-87de1731befd', '70719547-63e3-4a8d-9d8c-2838a46640d7', 1, 'Los alcaldes o notarios no podrán aceptar declaración de unión de hecho de menores de edad, sin el consentimiento de los padres o del tutor o, en su caso, autorización del juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c972f10b-b981-4b64-8bbf-ae917269fb84', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '178', 'Solicitud de reconocimiento judicial', 178, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e97b964-ad3c-42f0-b7ac-71f4d8957c03', 'c972f10b-b981-4b64-8bbf-ae917269fb84', 1, 'También puede solicitar el reconocimiento de la unión de hecho una sola de las partes, ya sea por existir oposición o por haber muerto la otra, en cuyos casos deberá presentarse el interesado ante el Juez de Primera Instancia competente, quien en sentencia hará la declaración de la unión de hecho, si hubiere sido plenamente probada. En dicha declaración, fijará el juez el día o fecha probable en que la unión dio principio, los hijos procreados y los bienes adquiridos durante ella. La certificación de la sentencia favorable al demandante, deberá presentarse al Registro Civil y al de la Propiedad si hubiere bienes inmuebles, para que se proceda a las respectivas inscripciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c98e8d5a-25cf-4398-b9da-5057fa9be358', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '179', 'Término', 179, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('669a1985-7688-4262-8df2-d3bd6209a289', 'c98e8d5a-25cf-4398-b9da-5057fa9be358', 1, 'La acción a que se refiere el artículo anterior, deberá iniciarse antes de que transcurran tres años desde que la unión cesó, salvo el derecho de los hijos para demandar en cualquier tiempo la declaración judicial de la unión de hecho de sus padres, para el solo efecto de establecer su filiación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('990a925d-5110-4fb9-bb69-1fbc9a8d689c', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '180', 'Uniones ilícitas', 180, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca1a40e9-1e64-4382-82f8-9931297faa3e', '990a925d-5110-4fb9-bb69-1fbc9a8d689c', 1, 'La mujer que a sabiendas que el varón tiene registrada su unión de hecho con otra mujer, y el hombre que a sabiendas que la mujer tiene registrada su unión con otro hombre, hicieren vida común, no gozarán de la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1d516b2-db62-4516-bf7f-409baaa95258', '990a925d-5110-4fb9-bb69-1fbc9a8d689c', 2, 'protección de la ley, mientras la unión registrada no hubiere sido disuelta legalmente y liquidados los bienes comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3834f349-89a6-454c-83fd-298c50ba3b2c', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '181', 'Preferencia en varias uniones', 181, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ead65ca-a959-4c06-bed4-340016d44148', '3834f349-89a6-454c-83fd-298c50ba3b2c', 1, 'En el caso de que varias mujeres, igualmente solteras, demandaren la declaración de la unión de hecho con el mismo hombre soltero, el juez hará la declaración únicamente en favor de aquélla que probare los extremos previstos en el artículo 173; y en igualdad de circunstancias, la declaratoria se hará en favor de la unión más antigua. Lo dispuesto en este artículo es aplicable siempre que las uniones de hecho que se pretenda se declaren, coexistan en el momento de solicitarse la declaratoria respectiva o bien en la fecha en que ocurrió la muerte de la persona con quien se mantuvo la unión de hecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('407b5342-4fea-434a-bcaa-19769e1451d2', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '182', 'Efectos de la inscripción', 182, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be6b4131-d9bb-4a12-b00e-445e495bf002', '407b5342-4fea-434a-bcaa-19769e1451d2', 1, 'La unión de hecho inscrita en el Registro Civil, produce los efectos siguientes: 1. Los hijos nacidos después de ciento ochenta días de la fecha fijada como principio de la unión de hecho, y los nacidos dentro de los trescientos días siguientes al día en que la unión cesó, se reputan hijos del varón con quien la madre estuvo unida, presunción contra la cual se admite prueba en contrario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e6a2ed9-e509-4ea7-a02a-f75115cd021d', '407b5342-4fea-434a-bcaa-19769e1451d2', 2, '2. Si no hubiere escritura de separación de bienes, los adquiridos durante la unión de hecho se reputan bienes de ambos, salvo prueba en contrario que demuestre que el bien fue adquirido por uno solo de ellos, a título gratuito, o con el valor o por permuta de otro bien de su exclusiva propiedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c391e28d-604e-442f-b245-b651595950f3', '407b5342-4fea-434a-bcaa-19769e1451d2', 3, '3. Derecho de una de las partes a solicitar la declaratoria de ausencia de la otra y, una vez declarada, pedir la cesación de su unión con el ausente, liquidación del haber común y adjudicación de los bienes que le correspondan.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4673acfe-389c-412b-af35-c9618107ca92', '407b5342-4fea-434a-bcaa-19769e1451d2', 4, '4. En caso de fallecimiento de alguno de ellos, el sobreviviente puede pedir la liquidación del haber común y adjudicación de bienes, al igual que en el caso del inciso anterior; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a5b9681-10fe-43a8-9d7a-10c3b271a633', '407b5342-4fea-434a-bcaa-19769e1451d2', 5, '5. Sujeción del hombre y la mujer a los derechos y obligaciones de los cónyuges durante el matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('747efc51-1a8a-435d-a696-4b07d0ba1ff8', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '183', 'Cese de la unión', 183, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e20c40e-c20e-4322-b8ba-333bbfa8f57a', '747efc51-1a8a-435d-a696-4b07d0ba1ff8', 1, 'La unión de hecho puede cesar por mutuo acuerdo de varón y mujer, en la misma forma que se constituyó; o por cualquiera de las causas señaladas en el artículo 155 para el divorcio y la separación, en cuyo caso la cesación deberá ser declarada judicialmente. La cesación de la unión de hecho por mutuo acuerdo deberá hacerse constar ante el juez de Primera Instancia del domicilio de los convivientes, o ante un notario; pero para que se reconozca y se ordene la anotación respectiva en el Registro Civil debe');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37005527-3bfe-434c-8064-fa99784073d7', '747efc51-1a8a-435d-a696-4b07d0ba1ff8', 2, 'cumplirse previamente con lo que dispone el artículo 163 de este Código, con respecto al divorcio de los cónyuges.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('70a7c021-e590-4858-b131-00565277fec4', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '184', NULL, 184, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c3b2915-1f82-4224-9a00-c5e9545a4130', '70a7c021-e590-4858-b131-00565277fec4', 1, 'El varón y la mujer cuya unión de hecho conste en la forma legal, se heredan recíprocamente abintestato en los mismos casos que para los cónyuges determina este Código. Las disposiciones de este Código relativas a los deberes y derechos que nacen del matrimonio y al régimen económico de éste, tienen validez para las uniones de hecho, en lo que fueren aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2546e6df-269c-41ea-b88a-8182f0924396', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '185', 'Aviso al Registro', 185, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82d5fc25-8704-490b-bd64-bb11c7d01410', '2546e6df-269c-41ea-b88a-8182f0924396', 1, 'Terminadas las diligencias de la cesación e la unión y satisfechas las exigencias legales, la autoridad que haya intervenido en ellas o el notario que autorice la escritura de separación, liquidación y adjudicación de bienes, dará aviso al Registro Civil en que se inscribió la unión de hecho, para que se haga la anotación correspondiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1a87264b-7585-4b95-b5e2-d6ba8697f42f', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '186', 'Libertad de Estado', 186, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f93b8995-d59e-4ec5-91d3-68a17fcd3089', '1a87264b-7585-4b95-b5e2-d6ba8697f42f', 1, 'La separación, una vez registrada, deja libres de estado a hombre y mujer, pero sin que esto perjudique las obligaciones que ambos tienen que cumplir con respecto a los hijos, quienes conservarán íntegros sus derechos a ser alimentados, no obstante cualquier estipulación de los padres.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('239d1c3e-f484-479a-a306-598f269c0647', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '187', 'Matrimonio de uno de los unidos de hecho', 187, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef44aa2c-3216-4fad-aa44-53c66a2200bf', '239d1c3e-f484-479a-a306-598f269c0647', 1, 'Para que pueda autorizarse el matrimonio de cualquiera de los dos que haya hecho vida común que estuviere registrada, es indispensable que se proceda a cumplir con lo preceptuado en el artículo 183.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0aba913c-4591-4b9e-9ee9-20e8cbaa7271', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '188', 'Oposición al matrimonio', 188, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('af669f9e-51cf-4bad-962c-555c268107a1', '0aba913c-4591-4b9e-9ee9-20e8cbaa7271', 1, 'Al matrimonio puede oponerse parte interesada para exigir que previamente se resuelvan aquellas cuestiones y se liquiden los bienes comunes. El funcionario que intervenga en el matrimonio no podrá autorizarlo si el solicitante no comprueba haber liquidado los bienes comunes y asegurado la prestación de alimentos de los hijos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17f4c681-239e-4f49-ac11-0c7f1c4c3112', 'a0000000-0000-0000-0000-000000000001', '6c7ddd6f-466c-42f7-ae3f-0054bc5339cd', '189', 'Matrimonio de los que están unidos de hecho', 189, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f3d982ef-5756-41a0-bb3c-715f495572fd', '17f4c681-239e-4f49-ac11-0c7f1c4c3112', 1, 'Cuando las personas ligadas por unión de hecho desearen contraer matrimonio entre sí, la autoridad respectiva o el notario a quien acudieren, lo efectuará con sólo presentar certificación de la Inscripción del Registro Civil, en la cual conste dicha circunstancia. El matrimonio subsecuente de los padres hace que se tenga como nacidos de matrimonio a los hijos habidos antes de su celebración y durante la unión de hecho.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5af8922b-2d2e-4cda-a4f9-06bb8f8f5de8', '17f4c681-239e-4f49-ac11-0c7f1c4c3112', 2, 'DEL PARENTESCO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e4746f7b-c94b-4540-b60d-32391dfaba36', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '190', 'Clases de parentesco', 190, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2161085b-7efb-4651-a3c4-9d65e49f590b', 'e4746f7b-c94b-4540-b60d-32391dfaba36', 1, 'La ley reconoce el parentesco de consanguinidad dentro del cuarto grado el de afinidad dentro del segundo grado, y el civil, que nace de la adopción y sólo existe entre el adoptante y el adoptado. Los cónyuges son parientes, pero no forman grado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5fa299ec-3348-400f-8164-6d9aa09fa057', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '191', 'Consanguinidad', 191, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('84ff6e45-d94f-4a50-bf6d-ffbbc47c37a1', '5fa299ec-3348-400f-8164-6d9aa09fa057', 1, 'Parentesco de consanguinidad es el que existe entre personas que descienden de un mismo progenitor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0161e8e5-c8b9-4cde-8ff2-a0a60acdf6c6', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '192', 'Afinidad', 192, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3779682c-de1d-4519-912a-7421749a8d7e', '0161e8e5-c8b9-4cde-8ff2-a0a60acdf6c6', 1, 'Parentesco de afinidad es el vínculo que une a un cónyuge con el otro y sus respectivos parientes consanguíneos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2bb0ebbd-3b26-4b87-b7c7-eb400b8a5b17', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '193', 'Grado', 193, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1478b73d-0841-44a2-9e40-d952308024aa', '2bb0ebbd-3b26-4b87-b7c7-eb400b8a5b17', 1, 'El parentesco se gradúa por el número de generaciones; cada generación constituye un grado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('056bd4df-6fd4-4fdf-95ff-7c51897adb90', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '194', 'Línea', 194, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25241a22-67b9-4a59-bf36-fad864993ae8', '056bd4df-6fd4-4fdf-95ff-7c51897adb90', 1, 'La serie de generaciones o grados procedentes de un ascendiente común forma línea.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('71f7493b-cf57-4251-818f-3ab732a1e90d', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '195', NULL, 195, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e464acd8-79af-4858-9040-a9a863b213c9', '71f7493b-cf57-4251-818f-3ab732a1e90d', 1, 'La línea es recta, cuando las personas descienden unas de otras, y colateral o transversal, cuando las personas provienen de un ascendiente común, pero no descienden unas de otras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('23da9fee-e331-4767-922e-74190a635dac', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '196', NULL, 196, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d968270-9cab-4492-974a-1ecb716adb82', '23da9fee-e331-4767-922e-74190a635dac', 1, 'En la línea recta, sea ascendente o descendente, hay tantos grados como generaciones, o sea tantos como personas, sin incluirse la del ascendiente común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ba005f0f-6e4f-469a-879c-faea34b03630', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '197', NULL, 197, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('091ef0bb-aa72-4309-902b-7485e746fc8f', 'ba005f0f-6e4f-469a-879c-faea34b03630', 1, 'En línea colateral los grados se cuentan igualmente por generaciones subiendo desde la persona cuyo parentesco se requiere comprobar hasta el ascendiente común y bajando desde éste hasta el otro pariente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d18987b9-0668-49b4-a0b6-f31083870a0e', 'a0000000-0000-0000-0000-000000000001', 'db802e43-2f81-4999-86d4-8f4cc5e4b581', '198', NULL, 198, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('659e14b6-6a96-4411-b173-0f6d6c7ab362', 'd18987b9-0668-49b4-a0b6-f31083870a0e', 1, 'EL parentesco de afinidad se computa del mismo modo que el de consanguinidad, y concluye por la disolución del matrimonio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f893a6fb-4cd6-403c-b08c-69b206305f44', 'd18987b9-0668-49b4-a0b6-f31083870a0e', 2, 'PATERNIDAD Y FILIACION MATRIMONIAL');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c5f5bd82-b6fe-4bd8-877d-7bdc81aad854', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '199', 'Paternidad del marido', 199, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d949fbf1-5f45-4e14-9bb3-532348786599', 'c5f5bd82-b6fe-4bd8-877d-7bdc81aad854', 1, 'El marido es padre del hijo concebido durante el matrimonio, aunque éste sea declarado insubsistente, nulo o anulable. Se presume concebido durante el matrimonio:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4df45f8-75e1-47b6-8a0c-5561096ded56', 'c5f5bd82-b6fe-4bd8-877d-7bdc81aad854', 2, '1. El hijo nacido después de ciento ochenta días de la celebración del matrimonio, o de la reunión de los cónyuges legalmente separados; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a088e5ef-eecd-4cd7-9af2-2ecdb994039a', 'c5f5bd82-b6fe-4bd8-877d-7bdc81aad854', 3, '2. El hijo nacido dentro de los trescientos días siguientes a la disolución del matrimonio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('575d4caf-10bd-455a-8cd0-b5d835106dbd', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '200.6', 'Prueba en contrario', 200, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13e64bb7-f91a-4717-8c70-8cce6c2cd3e6', '575d4caf-10bd-455a-8cd0-b5d835106dbd', 1, 'Contra la presunción del artículo anterior no se admiten otras pruebas que la prueba molecular genética del Ácido Desoxirribonucleico (ADN), así como haber sido físicamente imposible al marido tener acceso con su cónyuge en los primeros ciento veinte días de los trescientos que precedieron al nacimiento, por ausencia, enfermedad, impotencia o cualquiera otra circunstancia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a5f2b4a2-6106-4326-8ac2-7b0731cc4c8f', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '201', 'Impugnación por el marido', 201, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57dd2194-7e55-42d7-bbf7-ffdac5ea974b', 'a5f2b4a2-6106-4326-8ac2-7b0731cc4c8f', 1, 'El nacido dentro de los ciento ochenta días siguientes a la celebración del matrimonio, se presume hijo del marido si éste no impugna su paternidad. La impugnación no puede tener lugar:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12a74ae4-94fa-4525-b81b-2ff65c79c5e3', 'a5f2b4a2-6106-4326-8ac2-7b0731cc4c8f', 2, '1. Si antes de la celebración del matrimonio tuvo conocimiento de la preñez;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6acb9d5d-6f56-40bd-b4b7-177999b4b238', 'a5f2b4a2-6106-4326-8ac2-7b0731cc4c8f', 3, '2. Si estando presente en el acto de la inscripción del nacimiento en el Registro Civil, firmó o consintió que se firmará a su nombre la partida de nacimiento; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c2b22ea-f710-4f2d-9743-5063230206ae', 'a5f2b4a2-6106-4326-8ac2-7b0731cc4c8f', 4, '3. Si por documento público o privado, el hijo hubiere sido reconocido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5dd562d6-b761-45fb-82ae-85ff29c693ed', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '202', NULL, 202, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e66fe961-6d78-4363-b16f-102601e4a0ae', '5dd562d6-b761-45fb-82ae-85ff29c693ed', 1, 'La filiación del hijo nacido después de los trescientos días de la disolución del matrimonio, podrá impugnarse por el marido; pero el hijo y la madre tendrán también derecho para justificar la paternidad de aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a538cf2c-90ce-46ba-94c0-9ac9b9ed06c4', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '203', 'Adulterio de la madre', 203, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d46002e9-3cf7-443c-b3f9-f6cf6cc8a4ae', 'a538cf2c-90ce-46ba-94c0-9ac9b9ed06c4', 1, 'El marido no puede impugnar la paternidad del hijo concebido o nacido durante el matrimonio, alegando el adulterio de la madre, aún cuando ésta declare en contra de la paternidad del marido, salvo que se le hubiere ocultado el embarazo y el nacimiento del hijo, en cuyo caso si podrá negar la paternidad probando todos los hechos que justifiquen la impugnación. Si al marido se le hubiere declarado en estado de interdicción, podrá ejercitar ese derecho su representante legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef79eaef-6a37-4ea8-9c35-a81d1c4966f9', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '204', 'Término', 204, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc0680ce-5e8c-4d3f-935e-e4b234573833', 'ef79eaef-6a37-4ea8-9c35-a81d1c4966f9', 1, 'La acción del marido negando la paternidad del hijo nacido de su cónyuge, deberá intentarse judicialmente, dentro de sesenta días, contados desde la fecha del nacimiento, si está presente; desde el día en que regresó a la residencia de su cónyuge, si estaba ausente; o desde el día en que descubrió el hecho, si se le ocultó el nacimiento. Los herederos del marido solamente podrán continuar la acción de impugnación de la paternidad iniciada por él, pero este derecho podrán ejercitarlo únicamente dentro de sesenta días contados desde la muerte del marido.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92f2da08-aaf4-48ca-9c6b-b7679cd48a1d', 'ef79eaef-6a37-4ea8-9c35-a81d1c4966f9', 2, '6 Reformado por el Artículo 1, del Decreto No. 39-2008 publicado en el Diario de Centro América el 26-de agosto de 2008.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f54f89c4-aef9-4670-bb3f-c98f3dc63dbb', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '205', 'Acción de los herederos', 205, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3cc1b3b7-e949-409b-9292-c3b4788c01a2', 'f54f89c4-aef9-4670-bb3f-c98f3dc63dbb', 1, 'Podrán asimismo impugnar la filiación, si el hijo fuere póstumo o si el presunto padre hubiere fallecido antes de que transcurriera el plazo señalado en el artículo anterior. Los herederos deberán iniciar la acción dentro de sesenta días, contados desde que el hijo haya sido puesto en posesión de los bienes del padre, o desde que los herederos se vean turbados por el hijo en la posesión de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('20a6f235-f604-4833-914e-58bfb2cc4a92', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '206', 'Derechos de la mujer encinta', 206, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('427e2e4c-bae5-4510-adc5-2c47b1507291', '20a6f235-f604-4833-914e-58bfb2cc4a92', 1, 'En caso de separación o disolución del matrimonio, la mujer que esté encinta deberá denunciarlo al juez o al marido, en el término de noventa días contados desde su separación o divorcio. Asimismo, si la mujer quedare encinta a la muerte del marido, deberá denunciarlo al juez competente, dentro del mismo término, a fin de que, en uno u otro caso, se tomen las disposiciones necesarias para comprobar la efectividad del parto en el tiempo legal y establecer la filiación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('067e0c3b-2f1d-451d-a55a-7f57fd3da55e', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '207', 'Nuevas nupcias de la madre', 207, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('90731d72-c52a-4455-9d80-6f3c3335a067', '067e0c3b-2f1d-451d-a55a-7f57fd3da55e', 1, 'Si disuelto un matrimonio, la madre contrajere nuevas nupcias dentro de los trescientos días siguientes a la fecha de la disolución, el hijo que naciere dentro de los ciento ochenta días de celebrado el segundo matrimonio, se presume concebido en el primero. Se presume concebido en el segundo matrimonio, el hijo que naciere después de los ciento ochenta días de su celebración, aunque se esté dentro de los trescientos días posteriores a la disolución del primer matrimonio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e37bb195-c1f4-48cb-89d7-7c53ed74ee2b', '067e0c3b-2f1d-451d-a55a-7f57fd3da55e', 2, 'Contra estas presunciones es admisible la prueba a que se refiere el artículo 200.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0aab072e-6fc2-4e26-b076-68d43ae9101c', 'a0000000-0000-0000-0000-000000000001', '29ca3527-d07b-4cbb-b37b-b69d1c00e780', '208', 'En todo juicio de filiación será parte la madre, si viviere', 208, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41dec7b0-6376-4148-86d0-47453c9596fd', '0aab072e-6fc2-4e26-b076-68d43ae9101c', 1, 'PATERNIDAD Y FILIACION EXTRAMATRIMONIAL');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a60fca3d-86b8-4a77-a675-700362fd01c6', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '209', 'Igualdad de derechos de los hijos', 209, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34a0751a-bf7e-4dcc-805a-6f1effee1661', 'a60fca3d-86b8-4a77-a675-700362fd01c6', 1, 'Los hijos procreados fuera de matrimonio, gozan de iguales derechos que los hijos nacidos de matrimonio; sin embargo, para que vivan en el hogar conyugal se necesita el consentimiento expreso del otro cónyuge.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bafb5901-df94-49db-9210-6f93879c9a97', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '210', 'Reconocimiento del padre', 210, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5623ae0-367f-41af-8a83-bd8a43d2d273', 'bafb5901-df94-49db-9210-6f93879c9a97', 1, 'Cuando la filiación no resulte del matrimonio ni de la unión de hecho registrada de los padres, se establece y se prueba, con relación a la madre, del solo hecho del nacimiento; y, con respecto del padre, por el reconocimiento voluntario, o por sentencia judicial que declare la paternidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ad58103-5016-4ff9-b147-2dc3b4a535b4', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '211', 'Formas de reconocimiento', 211, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc9f9a6a-2121-4fbd-956f-b4881437c687', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 1, 'El reconocimiento voluntario puede hacerse: 1. En la partida de nacimiento, por comparecencia ante el registrador civil;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('efe46da6-f771-4d2a-9ed8-4f7429220fe1', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 2, '2. Por acta especial ante el mismo registrador;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d65b968b-f0ad-40b1-ac1e-4acca21f6f07', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 3, '3. Por escritura pública;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d6afa5fa-759f-4c98-b7cb-c941267633d4', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 4, '4. Por testamento; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eee679d6-9bb9-4012-9bc0-67891e38d510', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 5, '5. Por confesión judicial.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6bd9d22d-d435-4abb-b5b0-86dcf95f31f1', '6ad58103-5016-4ff9-b147-2dc3b4a535b4', 6, 'En los casos de los tres últimos incisos de este artículo, debe presentarse al registrador civil testimonio o certificación del documento en que conste el reconocimiento para su inscripción y anotación de la partida de nacimiento respectiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('653d6f71-90d3-4a42-9d5b-428e48c02851', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '212', 'El reconocimiento no es revocable', 212, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e2c0521-e79b-4cae-8e97-9710c8b02cfb', '653d6f71-90d3-4a42-9d5b-428e48c02851', 1, 'El reconocimiento no es revocable por el que lo hizo. Si se ha hecho en testamento y éste se revoca, no se tiene por revocado el reconocimiento. Tampoco puede sujetarse a ninguna modalidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('890ab833-5ea8-4a73-9e0c-256fbadc736b', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '213', NULL, 213, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab3093e5-4d02-4214-bfb8-eb3c79328beb', '890ab833-5ea8-4a73-9e0c-256fbadc736b', 1, 'Es válido el reconocimiento que se hace por medio de testamento, aunque éste se declare nulo por falta de requisitos testamentarios especiales que no hubieran anulado el acto si sólo se hubiera otorgado el reconocimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e8b6ae4c-34e2-4788-92b3-96d438f2a547', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '214', 'Reconocimiento de ambos padres', 214, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2af31ca-9825-4254-acbe-cc35563c2d99', 'e8b6ae4c-34e2-4788-92b3-96d438f2a547', 1, 'Los padres pueden reconocer al hijo conjunta o separadamente. El reconocimiento hecho por uno solo de los padres, sólo produce efecto respecto de él.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e60b8137-ec91-499b-9d7d-b09a3764d3f1', 'e8b6ae4c-34e2-4788-92b3-96d438f2a547', 2, 'El padre o la madre que no intervino en el acto, así como el propio hijo o un tercero interesado legítimamente, puede impugnar el reconocimiento, dentro de seis meses a contar del día en que tal hecho fuere conocido por ellos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ecec6e5-0b28-4c27-9a02-8731c875da56', 'e8b6ae4c-34e2-4788-92b3-96d438f2a547', 3, 'Si el hijo fuere menor de edad, puede contradecir el reconocimiento dentro del año siguiente a su mayoría.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5cbd84b0-89c5-4e1b-aef0-c5bb7d6984e5', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '215', 'Reconocimiento separado', 215, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('af5c0827-748b-41bd-b9a1-d08aad8dfbe0', '5cbd84b0-89c5-4e1b-aef0-c5bb7d6984e5', 1, 'Cuando el padre o la madre hicieren el reconocimiento separadamente, no estarán obligados a revelar el nombre de la persona con quien hubieren tenido el hijo. No será permitido al padre hacer reconocimiento de hijos, atribuyendo la maternidad a una mujer casada con otra persona, salvo que el marido haya impugnado la paternidad y obtenido sentencia favorable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('759df167-c2a9-4e8d-8261-ae652b312c68', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '216', 'Reconocimiento por los abuelos', 216, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa657df5-ed25-433d-a7f6-108566feb315', '759df167-c2a9-4e8d-8261-ae652b312c68', 1, 'En caso de muerte o incapacidad del padre o de la madre, el hijo puede ser reconocido por el abuelo paterno o por el abuelo materno, respectivamente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2098f348-41fc-4ca0-9b6b-cf025ec44dbb', '759df167-c2a9-4e8d-8261-ae652b312c68', 2, 'Si el incapaz recobrare la salud, podrá impugnar el reconocimiento dentro del año siguiente al día en que tenga conocimiento de aquel hecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4e71d5ca-57f9-41ca-8a4c-7cf11019be7b', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '217', 'Reconocimiento por el menor de edad', 217, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e86840f2-82e1-447f-b157-9e40bdae79c6', '4e71d5ca-57f9-41ca-8a4c-7cf11019be7b', 1, 'El varón menor de edad no puede reconocer a un hijo sin el consentimiento de los que ejerzan sobre él la patria potestad, o de la persona bajo cuya tutela se encuentre, o, a falta de ésta, sin la autorización judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c5a08c1b-4766-4a99-8afa-e893db6b4b6d', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '218', NULL, 218, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82e0df16-b7ba-411c-9a20-e60f38fef3ed', 'c5a08c1b-4766-4a99-8afa-e893db6b4b6d', 1, 'La mujer mayor de catorce años sí tiene la capacidad civil necesaria para reconocer a sus hijos, sin necesidad de obtener el consentimiento a que se refiere el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('962d6341-ac44-4186-a5a6-63a2da79b114', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '219', 'Derechos de la mujer que ha cuidado a un niño', 219, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('718ab6ab-10b6-4a66-9295-1567475c6249', '962d6341-ac44-4186-a5a6-63a2da79b114', 1, 'La mujer que ha cuidado a un niño, como hijo suyo, y ha proveído a su subsistencia y educación, tiene derecho a que no lo separen de ella por efecto del reconocimiento que un hombre haya hecho del menor. Pero si fuere obligada a entregarlo por resolución judicial, el padre que pretenda llevárselo, deberá previamente pagar el monto de lo gastado en el sostenimiento del niño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c73912e2-337d-44b3-b1c7-bac55236c32f', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '220', 'Acción judicial de filiación', 220, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1f1288cc-ee5d-41a7-a66c-e48af3a0de8d', 'c73912e2-337d-44b3-b1c7-bac55236c32f', 1, 'El hijo que no fuere reconocido voluntariamente, tiene derecho a pedir que judicialmente se declare su filiación y este derecho nunca prescribe respecto de él. Los herederos del hijo podrán proseguir la acción que éste dejare iniciada al tiempo de su fallecimiento o intentarla si el hijo falleciere durante su menor edad, o si hubiere adolecido de incapacidad y muriere en ese estado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93ac0995-479a-4134-94e8-e23bd0d712a9', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '221.7', 'Casos en que puede ser declarada la paternidad', 221, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b303849-a55d-486d-8250-90173f256be2', '93ac0995-479a-4134-94e8-e23bd0d712a9', 1, 'La paternidad puede ser judicialmente declarada: 1. Cuando existan cartas, escritos o documentos en que se reconozca;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc57308a-7efc-4e79-969b-84cd6b4e0831', '93ac0995-479a-4134-94e8-e23bd0d712a9', 2, '2. Cuando el pretensor se halle en posesión notoria de estado de hijo del presunto padre;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d4d5184-bbf7-44dc-b187-cda99feee955', '93ac0995-479a-4134-94e8-e23bd0d712a9', 3, '3. En los casos de violación, estupro o rapto, cuando la época del delito coincida con la de la concepción; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3e40f71-cfa5-4341-b2c0-a03ce9662359', '93ac0995-479a-4134-94e8-e23bd0d712a9', 4, '4. Cuando el presunto padre haya vivido maridablemente con la madre durante la época de la concepción.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6301da6e-218f-4103-b32c-68ed7a7a0c20', '93ac0995-479a-4134-94e8-e23bd0d712a9', 5, '7 Adicionado el numeral 5º a este artículo (221), por el Decreto No. 39-2008 publicado en el Diario de Centro América el 26 agosto de 2008.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50ecaa9b-7a79-4fe0-bc17-ed83ddec8ff9', '93ac0995-479a-4134-94e8-e23bd0d712a9', 6, '5. Cuando el resultado de la prueba biológica, del Ácido Desoxirribonucleico -ADN-, determine científicamente la filiación con el presunto padre, madre e hijo. Si el presunto padre se negare a someterse a la práctica de dicha prueba, ordenada por juez competente, su negativa se tendrá como prueba de la paternidad, salvo prueba en contrario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93ed9089-de5d-4fa5-8fcb-94fef39a6a55', '93ac0995-479a-4134-94e8-e23bd0d712a9', 7, 'La prueba del Ácido Desoxirribonucleico -ADN-, deberá ser ordenada por juez competente, pudiendo realizarse en cualquier institución de carácter pública o privada, nacional o extranjera especializadas en dicha materia. Este medio de prueba, deberá cumplir con los requisitos establecidos en la ley para su admisibilidad. En juicios de impugnación de paternidad o maternidad, será admisible en iguales condiciones y circunstancias, la prueba molecular genética del Ácido Desoxirribonucleico -ADN-.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d62746d3-96d0-4f5e-a74a-fa996838a7ee', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '222', 'Presunción de paternidad', 222, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d8a70e2e-0103-4335-bcd3-e41089a6c79f', 'd62746d3-96d0-4f5e-a74a-fa996838a7ee', 1, 'Se presumen hijos de los padres que han vivido maridablemente: 1. Los nacidos después de ciento ochenta días contados desde que iniciaron sus relaciones de hecho; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34aa3350-90c1-4b9f-9a40-cc03b3199d9e', 'd62746d3-96d0-4f5e-a74a-fa996838a7ee', 2, '2. Los nacidos dentro de los trescientos días siguientes al día en que cesó la vida común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e846a4d-ea28-4532-90b2-2bd2dad895e7', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '223', 'Posesión notoria de estado', 223, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('23e109a1-ab17-41d2-bba3-1a75ac7b94d9', '9e846a4d-ea28-4532-90b2-2bd2dad895e7', 1, 'Para que haya posesión notoria de estado se requiere que el presunto hijo haya sido tratado como tal por sus padres o los familiares de éstos y que, además, concurra cualquiera de las circunstancias siguientes: 1. Que hayan proveído a su subsistencia y educación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('822688c3-48ff-4bb2-a323-20f0336d50d6', '9e846a4d-ea28-4532-90b2-2bd2dad895e7', 2, '2. Que el hijo haya usado, constante y públicamente, el apellido del padre; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8fb96150-a92c-4950-af9a-1362da550225', '9e846a4d-ea28-4532-90b2-2bd2dad895e7', 3, '3. Que el hijo haya sido presentado como tal en las relaciones sociales de la familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ccdf7ab-30fd-46e4-8d1c-83cfe1635cb8', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '224', 'Acción de filiación después del fallecimiento de los padres', 224, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('07155631-f4e0-4b7f-ad03-9096126c6d7d', '9ccdf7ab-30fd-46e4-8d1c-83cfe1635cb8', 1, 'La acción de filiación sólo podrá entablarse en vida del padre o de la madre contra quien se dirija, salvo en los siguientes casos: 1. Cuando el hijo sea póstumo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2de9d73b-89be-4527-ac17-aec17e760e69', '9ccdf7ab-30fd-46e4-8d1c-83cfe1635cb8', 2, '2. Cuando la persona contra quien se dirija la acción hubiera fallecido durante la menor edad del hijo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0832dcc-d31c-43e0-b85d-b6da15f9095f', '9ccdf7ab-30fd-46e4-8d1c-83cfe1635cb8', 3, '3. En los casos mencionados en el artículo 221.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('97e922ab-e7c9-41fb-a188-1ca199c05f2c', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '225', 'Indemnización a la madre', 225, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('69ca80ed-e9e3-4713-a8ef-f0a4ccaa8344', '97e922ab-e7c9-41fb-a188-1ca199c05f2c', 1, 'La madre tiene derecho a ser indemnizada del daño moral en los casos de acceso carnal delictuoso, o de minoridad al tiempo de la concepción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ff8e537c-550b-417f-bec8-82d9354bb6f7', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '226.8', 'Improcedencia de la acción', 226, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29c0ca21-dc98-4191-9f97-ab870f07adea', 'ff8e537c-550b-417f-bec8-82d9354bb6f7', 1, 'La acción concedida en el artículo anterior y la declaratoria a que se refieren los incisos 3º y 4º del artículo 221 no proceden en los casos siguientes: 1. Si durante la época de la concepción, la madre tuvo comercio carnal con persona distinta del presunto padre; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('328e96f6-4c2c-4804-b515-7edcfd042911', 'ff8e537c-550b-417f-bec8-82d9354bb6f7', 2, '2. Si durante la época de la concepción fue manifiestamente imposible al demandado tener acceso carnal con la madre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e45898fa-d5dc-4c96-81f2-f63f74f2fb4b', 'a0000000-0000-0000-0000-000000000001', '9f92e043-d7e0-4719-a62b-012f29737c81', '227', 'Reconocimiento es acto declarativo', 227, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('712a2334-d6e5-425a-91d9-18dbabfb5917', 'e45898fa-d5dc-4c96-81f2-f63f74f2fb4b', 1, 'El reconocimiento voluntario y el judicial son actos declarativos de la paternidad y, por consiguiente, surten sus efectos desde la fecha del nacimiento del hijo. Sobre la calidad de hijo no puede celebrarse transacción ni compromiso alguno; pero sí sobre los derechos pecuniarios, que puedan deducirse de la filiación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57e546b6-e631-430e-8796-6797ff1ebdbd', 'e45898fa-d5dc-4c96-81f2-f63f74f2fb4b', 2, 'DE LA ADOPCION 9 Derogado este Capitulo por el artículo 67 del Decreto 77-2007 del Congreso de la República de fecha 11-12-2007.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d6cc70c-e669-4e8a-aa32-ca37b55cd15c', 'a0000000-0000-0000-0000-000000000001', '2bec47a0-b190-4993-8cef-0e8485f0f75b', '228.10', NULL, 228, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b4c2e04-ea1e-4e81-b1e9-92336746a01d', '4d6cc70c-e669-4e8a-aa32-ca37b55cd15c', 1, 'Todos los aspectos relativos a la adopción se regirán por la Ley de Adopciones."');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ddb9acbc-126e-4bd1-bd0c-55afcb5c0e78', 'a0000000-0000-0000-0000-000000000001', '2bec47a0-b190-4993-8cef-0e8485f0f75b', '229', NULL, 229, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57d5e354-dece-497a-8fd4-b91893d6b684', 'ddb9acbc-126e-4bd1-bd0c-55afcb5c0e78', 1, 'al 251. 11Derogados');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('09fc0444-fd47-4d81-953c-2784adabd6e2', 'ddb9acbc-126e-4bd1-bd0c-55afcb5c0e78', 2, 'DE LA PATRIA POTESTAD');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d068d82e-0a23-4a45-a56e-82073f000c1e', 'ddb9acbc-126e-4bd1-bd0c-55afcb5c0e78', 3, '8 Declara inconstitucional la frase que dice: "llevó una vida notoriamente desarreglada o", contenida en el numeral 1, por el Expediente Número 541-2006 publicada el 13 agosto de 2008. 9 Derogado este Capitulo por el artículo 67 del Decreto 77-2007 del Congreso de la República de fecha 11-12-2007. 10 Reformado por el Artículo 63, del Decreto No. 77-2007 publicado en el Diario de Centro América el 31 de diciembre de 2007. 11 Derogados los artículos del 229 al 251, por el artículo 67 del Decreto No. 77-2007, publicado en el Diario de Centro América el 31 de diciembre de 2007.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bca94ec9-bf1d-42a9-b427-5b4f0c26d85c', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '252', 'En el matrimonio y fuera de él', 230, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d96578a-59a9-4ab0-9526-626a4422e527', 'bca94ec9-bf1d-42a9-b427-5b4f0c26d85c', 1, 'La patria potestad se ejerce sobre los hijos menores, conjuntamente por el padre y la madre en el matrimonio y en la unión de hecho; y por el padre o la madre, en cuyo poder esté el hijo, en cualquier otro caso. Los hijos mayores de edad permanecerán bajo la patria potestad, solamente que hayan sido declarados en estado de interdicción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e7b885c9-5638-42f0-9246-aed797afb298', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '253', 'Obligaciones de ambos padres', 231, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc1f68b1-ae1a-4810-95c5-e7fe82ef0053', 'e7b885c9-5638-42f0-9246-aed797afb298', 1, 'El padre y la madre están obligados a cuidar y sustentar a sus hijos, sean o no de matrimonio, educarlos y corregirlos, empleando medios prudentes de disciplina, y serán responsables conforme a las leyes penales si los abandonan moral o materialmente y dejan de cumplir los deberes inherentes a la patria potestad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd3f46d6-3853-42a9-b9e3-fc764abacec4', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '254', 'Representación del menor o incapacitado', 232, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('154805c8-338c-45d5-acff-0bea525552d5', 'dd3f46d6-3853-42a9-b9e3-fc764abacec4', 1, 'La patria potestad comprende el derecho de representar legalmente al menor o incapacitado en todos los actos de la vida civil; administrar sus bienes y aprovechar sus servicios atendiendo a su edad y condición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9f29dafe-e5f5-4282-9779-e98f26c9acba', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '255.12', NULL, 233, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c766a4a-8fe4-4bae-bab5-93d7cd3047af', '9f29dafe-e5f5-4282-9779-e98f26c9acba', 1, 'Mientras subsista el vínculo matrimonial o la unión de hecho, el padre y la madre ejercerán conjuntamente la patria potestad, la representación del menor o la del incapacitado y la administración de sus bienes; la tendrán también, ambos padres, conjunta o separadamente, salvo los casos regulados en el artículo 115, o en los de separación o de divorcio, en los que la representación y la administración la ejercerá quien tenga la tutela del menor o del incapacitado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6b9c8af5-be13-40c4-ad7b-e91138e2d901', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '256', 'Pugna entre el padre y la madre', 234, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d958e88f-f4d1-40b8-b0f5-952ff4ef416b', '6b9c8af5-be13-40c4-ad7b-e91138e2d901', 1, 'Siempre que haya pugna de derechos e intereses entre el padre y la madre, en ejercicio de la patria potestad, la autoridad judicial respectiva debe resolver lo que más convenga al bienestar del hijo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6511412e-f7e1-421e-891e-ac27dcf3395f', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '257', 'Padres menores de edad', 235, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fa0281d-d1fc-4d80-a027-cbe30c7b37c2', '6511412e-f7e1-421e-891e-ac27dcf3395f', 1, 'Si los padres fueren menores de edad, la administración de los bienes de los hijos será ejercitada por la persona que tuviere la patria potestad o la tutela sobre el padre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37df7e5e-96a7-4ff8-ab91-2e826b96229d', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '258', NULL, 236, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2339e4a7-5c3f-4596-92d4-f5b4b4c2c0a5', '37df7e5e-96a7-4ff8-ab91-2e826b96229d', 1, '13Hijo adoptivo. La patria potestad sobre el hijo adoptivo la ejerce únicamente la persona que lo haya adoptado. 6. Por declaratoria judicial de adoptabilidad dictada por el juez de la niñez y la adolescencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38b2a2c9-e88d-4eff-8ef7-7e811e7fe482', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '259', 'Capacidad relativa de los menores', 237, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b1cbf6c6-d9a4-479a-9f66-52f6c71dfdd9', '38b2a2c9-e88d-4eff-8ef7-7e811e7fe482', 1, 'Los mayores de catorce años tienen capacidad para contratar su trabajo y percibir la retribución convenida, con la que ayudarán a sus padres para su propio sostenimiento.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('169a4e5c-4e3b-4f79-9ef9-9e899c322a2f', '38b2a2c9-e88d-4eff-8ef7-7e811e7fe482', 2, '12 Reformado por el Artículo 8 del Decreto No. 80-98 publicado el 31 de diciembre de 1998. 13 Adicionado el numeral 6 a este artículo, por el Artículo 64, del Decreto Número 77-2007 publicado el Diario de Centro América el 31 diciembre de 2007.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('334785e8-0a6f-4566-bc02-3990667b3398', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '260', 'Los hijos deben vivir con sus padres casados o unidos', 238, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a768b245-15b5-4b14-ba2b-68bdcadc1402', '334785e8-0a6f-4566-bc02-3990667b3398', 1, 'Los hijos menores de edad deben vivir con sus padres, o con el padre o la madre que los tenga a su cargo; no pueden sin permiso de ellos dejar la casa paterna o materna o aquélla en que sus padres los han puesto; debiendo en todos los casos ser auxiliada la autoridad doméstica por la pública, para hacer volver a los hijos al poder y obediencia de sus progenitores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e654198e-5051-4443-a428-200563654e77', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '261', 'Madre soltera o separada', 239, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e7ff7ed-2dcf-406d-ae5d-eb5386fe19e6', 'e654198e-5051-4443-a428-200563654e77', 1, 'Cuando el padre y la madre no sean casados ni estén unidos de hecho, los hijos estarán en poder de la madre, salvo que ésta convenga en que pasen a poder del padre, o que sean internados en un establecimiento de educación. Si la separación de los padres procede de la disolución del matrimonio, se estará a lo dispuesto en el artículo 166.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71388196-5c3c-4b06-93af-9ae31ea6528a', 'e654198e-5051-4443-a428-200563654e77', 2, 'En todo caso el que por vías de hecho sustrajere al hijo del poder de la persona que legalmente lo tenga a su cargo, será responsable conforme a la ley; y la autoridad deberá prestar auxilio para la devolución del hijo, a fin de reintegrar en la patria potestad al que la ejerza especialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5f86274-234c-47e2-bc44-75c8e2542cf1', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '262', 'El interés de los hijos es predominante', 240, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ebbd8390-4d1f-4b85-95d8-ae77a12d6a47', 'b5f86274-234c-47e2-bc44-75c8e2542cf1', 1, 'No obstante lo preceptuado en los artículos anteriores, cuando la conducta de los padres sea perjudicial al hijo y se demande la suspensión o pérdida de la patria potestad, debe el juez adoptar las providencias urgentes que exija el interés y conveniencia del menor y puede disponer también, mientras resuelve en definitiva, que salga de la casa de sus padres y quede al cuidado del pariente más próximo, o de otra persona de reconocida honorabilidad, o si fuere posible, de un centro educativo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d41cc8dc-6e48-4cbe-87fc-de4a9faf7151', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '263', 'Los hijos deben respeto a sus padres', 241, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('17c54e62-4a57-4b82-9ace-b09edfca102b', 'd41cc8dc-6e48-4cbe-87fc-de4a9faf7151', 1, 'Los hijos aun cuando sean mayores de edad y cualquiera que sea su estado y condición, deben honrar y respetar a sus padres y están obligados a prestarles asistencia en todas las circunstancias de la vida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5012b9f-a31c-44b4-8736-3788607d570d', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '264', 'Bienes de los hijos', 242, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2b4e656-5810-455d-ae9a-7fa5d8ac73ab', 'b5012b9f-a31c-44b4-8736-3788607d570d', 1, 'Los padres no pueden enajenar ni gravar los bienes de los hijos ni contraer en nombre de ellos, obligaciones que excedan los límites de su ordinaria administración, sino por causa de absoluta necesidad y evidente utilidad y previa la autorización del juez competente e intervención del Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7530f32b-745d-4d1e-853a-98d5f6aef561', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '265', NULL, 243, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35e68b7e-90d7-4c06-bd9a-ce129038a291', '7530f32b-745d-4d1e-853a-98d5f6aef561', 1, 'Tampoco podrán los padres celebrar contratos de arrendamiento por más de tres años, ni recibir la renta anticipada por más de un año, sin autorización judicial; ni vender valores comerciales, industriales, títulos de renta, acciones, bonos, frutos y ganados, por menor valor del que se cotice en la plaza el día de la venta; ni prestar garantía en representación de los hijos, a favor de tercera persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7917fb16-93a7-4926-9ca9-5169c1e397e2', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '266', NULL, 244, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dca48e1f-069e-45f2-a3a0-452596cb268f', '7917fb16-93a7-4926-9ca9-5169c1e397e2', 1, 'Siempre que el juez conceda licencia para enajenar o gravar bienes inmuebles, tomará las medidas necesarias para hacer que el producto de la venta o el monto del crédito sea empleado en el objeto que motivó la autorización y que el saldo, si lo hubiere, se invierta debidamente, depositándose mientras tanto en un establecimiento bancario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('745d09a1-e7bb-46ed-a143-2593c6a4fd0a', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '267', NULL, 245, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b571548-2d0d-4fcf-8279-7cfac62861b2', '745d09a1-e7bb-46ed-a143-2593c6a4fd0a', 1, 'Salvo el caso de sucesión intestada, el que ejerza la patria potestad no puede adquirir, ni directa ni indirectamente, bienes o derechos del menor. Los actos realizados contra esta prohibición pueden ser anulados a solicitud del hijo o de sus herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f6dbbd7a-a6db-49ce-a338-98cd30dd54f2', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '268', 'Tutor especial', 246, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a7d4af2-f98d-4ba8-9a5b-fd7aebc8b0da', 'f6dbbd7a-a6db-49ce-a338-98cd30dd54f2', 1, 'Si surge conflicto de intereses entre hijos sujetos a la misma patria potestad, o entre ellos y los padres, el juez nombrará un tutor especial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('644c5edc-4f3d-4c52-b310-48f51011e1eb', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '269', 'Separación de la patria potestad', 247, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5cd94cb1-1aaa-484c-a6a6-b43344cf4223', '644c5edc-4f3d-4c52-b310-48f51011e1eb', 1, 'Si el que ejerce la patria potestad disipa los bienes de los hijos, o por su mala administración, se disminuyen o deprecian, será separado de ella, a solicitud de los ascendientes del menor, sus parientes colaterales dentro del cuarto grado de consanguinidad, o del Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c55092c1-78c2-4c9f-9871-73a19258d8e4', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '270', NULL, 248, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('636bcf40-03fc-4d7c-acd6-4d337f0b313a', 'c55092c1-78c2-4c9f-9871-73a19258d8e4', 1, 'Los padres están obligados a prestar garantía de la conservación y administración de los bienes de los hijos, cuando pasen a ulteriores nupcias o cuando sean declarados en quiebra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f370f56-6482-4492-8b52-358ddf3c8243', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '271', NULL, 249, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a7e019a-fdea-4fb7-8cad-35d809dae1dd', '7f370f56-6482-4492-8b52-358ddf3c8243', 1, 'Si al que se halla bajo la patria potestad se le hiciere alguna donación, o se le dejare herencia o legado, con la expresa condición de que los bienes no los administren los padres, será respetada la voluntad del donante o testador, quien deberá designar la persona o institución administradora y, si no lo hiciere, el nombramiento lo hará el juez en persona de reconocida solvencia y honorabilidad, si no hubiere institución bancaria autorizada para tales encargos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('313aef77-e9a2-42cc-ba3c-dab4029f42a8', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '272', NULL, 250, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca8c98e3-b0a7-4abf-8b6d-2a9534ad4463', '313aef77-e9a2-42cc-ba3c-dab4029f42a8', 1, 'Los padres deben entregar a los hijos, luego que éstos lleguen a la mayoría de edad, los bienes que les pertenezcan y rendir cuentas de su administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b0803e15-f079-4356-a47d-e2285d7d4963', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '273', 'Suspensión', 251, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ace3f0eb-b471-4634-ad5a-8ac37ab09a3f', 'b0803e15-f079-4356-a47d-e2285d7d4963', 1, 'La patria potestad se suspende: 1. Por ausencia del que la ejerce, declarada Judicialmente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c8a8b59-ecca-4071-a699-27cb8fcaabbf', 'b0803e15-f079-4356-a47d-e2285d7d4963', 2, '2. Por interdicción, declarada en la misma forma;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd87fae0-35b5-4393-8e2c-60cb50186e00', 'b0803e15-f079-4356-a47d-e2285d7d4963', 3, '3. Por ebriedad consuetudinaria; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('598aa8cf-a897-4197-ac7f-fc006327d2cd', 'b0803e15-f079-4356-a47d-e2285d7d4963', 4, '4. Por tener el hábito del juego o por el uso indebido y constante de drogas estupefacientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('40a02608-af50-43e4-9551-ad17fe941675', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '274', 'Pérdida', 252, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f184c4bb-b1dd-41a3-bcab-622182588a2b', '40a02608-af50-43e4-9551-ad17fe941675', 1, 'La patria potestad se pierde: 1. Por las costumbres depravadas o escandalosas de los padres, dureza excesiva en el trato de los hijos o abandono de sus deberes familiares;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b03d7a9d-e2c9-4bdb-ad23-edef422f34b0', '40a02608-af50-43e4-9551-ad17fe941675', 2, '2. Por dedicar a los hijos a la mendicidad, o darles órdenes, consejos, insinuaciones y ejemplos corruptores;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e4fe1c9-5bc4-413f-acbc-5b0566f11dd6', '40a02608-af50-43e4-9551-ad17fe941675', 3, '3. Por delito cometido por uno de los padres contra el otro, o contra la persona de alguno de sus hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('026636cc-69af-4041-8a18-944242515084', '40a02608-af50-43e4-9551-ad17fe941675', 4, '4. Por la exposición o abandono que el padre o la madre hicieren de sus hijos, para el que los haya expuesto o abandonado; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('65dd017d-944e-40d1-b4a5-aeccc21701af', '40a02608-af50-43e4-9551-ad17fe941675', 5, '5. Por haber sido condenado dos o más veces por delito del orden común, si la pena excediere de tres años de prisión por cada delito.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc7f0815-a68e-42c8-9505-6ef0f148aaf3', '40a02608-af50-43e4-9551-ad17fe941675', 6, 'También se pierde la patria potestad cuando el hijo es adoptado por otra persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ab106db-562f-4bf7-a37b-529a41e63d42', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '275', NULL, 253, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fe8518e2-3209-4518-889e-e45e1c46b4d4', '6ab106db-562f-4bf7-a37b-529a41e63d42', 1, 'El que haya sido suspendido en el ejercicio de la patria potestad o la hubiere perdido, no quedará exonerado de las obligaciones hacia sus hijos, que se establecen en el presente capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a222c133-7805-4dae-81ca-edfc6ddbb8c4', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '276', NULL, 254, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8898fd7a-fd61-4e0d-a616-6de1311956a2', 'a222c133-7805-4dae-81ca-edfc6ddbb8c4', 1, 'Sólo podrán promover la acción sobre pérdida o suspensión de la patria potestad, los ascendientes del menor, sus parientes colaterales dentro del cuarto grado de consanguinidad y el Ministerio Público. El progenitor inocente y el Ministerio Publico serán parte en el juicio en todos los casos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78a334fb-fb5f-424a-bae6-0653876e2b31', 'a0000000-0000-0000-0000-000000000001', '5907142c-5d9f-4b7d-b4d6-6ac73d9fa7b3', '277', 'Restablecimiento', 255, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1171bf65-6120-4c52-8e45-4f18f2b1c70d', '78a334fb-fb5f-424a-bae6-0653876e2b31', 1, 'El juez en vista de las circunstancias de cada caso, puede, a petición de parte, restablecer al padre o a la madre en el ejercicio de la patria potestad en los siguientes casos: 1. Cuando la causa o causas de la suspensión o pérdida hubieren desaparecido y no fueren por cualquier delito contra las personas o los bienes de los hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('78f89013-64ba-4f7a-aa3a-3371ec6a1c85', '78a334fb-fb5f-424a-bae6-0653876e2b31', 2, '2. Cuando en el caso de delito cometido contra el otro cónyuge, a que se refiere el inciso 3º del artículo 274, no haya habido reincidencia y hubieren existido circunstancias atenuantes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ba4f440-a02e-4fc9-a03e-dd38cae82394', '78a334fb-fb5f-424a-bae6-0653876e2b31', 3, '3. Cuando la rehabilitación fuere pedida por los hijos mayores de catorce años o por su tutor, siempre que la causa de pérdida de la patria potestad no estuviere comprendida dentro de los casos específicos que determina el inciso 1º de este artículo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('16aa4a96-1d8f-41fb-8ed8-d30fc4d59a20', '78a334fb-fb5f-424a-bae6-0653876e2b31', 4, 'En todos los casos debe probarse la buena conducta del que se intente rehabilitar, por lo menos en los tres años anteriores a la fecha en que se presente la solicitud respectiva.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('562af388-528d-4638-ad05-21f1c4315aa3', '78a334fb-fb5f-424a-bae6-0653876e2b31', 5, 'DE LOS ALIMENTOS ENTRE PARIENTES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16e85a5c-db5a-4e38-89b7-eb1b6f4f222a', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '278', 'Concepto', 256, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('928a79b9-b85c-47a5-a0b2-75797a4d4009', '16e85a5c-db5a-4e38-89b7-eb1b6f4f222a', 1, 'La denominación de alimentos comprende todo lo que es indispensable para el sustento, habitación, vestido, asistencia médica y también la educación e instrucción del alimentista cuando es menor de edad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3944222b-b6c0-4f1b-8c7a-a44f3ae007bc', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '279', NULL, 257, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27b01730-df39-4bf0-86bf-f01deef3566e', '3944222b-b6c0-4f1b-8c7a-a44f3ae007bc', 1, 'Los alimentos han de ser proporcionados a las circunstancias personales y pecuniarias de quien los debe y de quien los recibe, y serán fijados por el juez, en dinero. Al obligado se le puede permitir que los alimentos los preste de otra manera cuando, a juicio del juez, medien razones que lo justifiquen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3fe65b3a-6ed6-4af8-9e8d-12b90aff2c94', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '280', NULL, 258, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec97e5d4-5bd3-4a26-b6c9-ffba4a983aa0', '3fe65b3a-6ed6-4af8-9e8d-12b90aff2c94', 1, 'Los alimentos se reducirán o aumentarán proporcionalmente, según el aumento o disminución que sufran las necesidades del alimentista, y la fortuna del que hubiere de satisfacerlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b73813aa-828e-438c-8fb0-43b09fd13ba9', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '281', NULL, 259, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e50b460-4bb5-444a-a653-3743ea267674', 'b73813aa-828e-438c-8fb0-43b09fd13ba9', 1, 'Los alimentos sólo se deben en la parte en que los bienes y el trabajo del alimentista no alcancen a satisfacer sus necesidades.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('22244aa4-f524-4c61-bd17-9ebcf853bbf4', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '282', NULL, 260, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13dff9f3-a631-4176-bca6-b3fb07d1dd2e', '22244aa4-f524-4c61-bd17-9ebcf853bbf4', 1, 'No es renunciable ni transmisible a un tercero, ni embargable, el derecho a los alimentos. Tampoco pueden compensarse con lo que el alimentista debe al que ha de prestarlos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('330a3743-c106-44f7-90de-24e53a5e4781', '22244aa4-f524-4c61-bd17-9ebcf853bbf4', 2, 'Podrán, sin embargo, compensarse, embargarse, renunciarse y enajenarse las pensiones alimenticias atrasadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ece49a50-bfba-4877-8b24-3276949fde3a', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '283', 'Personas obligadas', 261, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34f32ce2-dfcb-4a6b-bda4-3dfcb5d32c10', 'ece49a50-bfba-4877-8b24-3276949fde3a', 1, 'Están obligados recíprocamente a darse alimentos, los cónyuges, los ascendientes, descendientes y hermanos. Cuando el padre, por sus circunstancias personales y pecuniarias, no estuviere en posibilidad de proporcionar alimentos a sus hijos, y la madre tampoco pudiere hacerlo, tal obligación corresponde a los abuelos paternos de los alimentistas, por todo el tiempo que dure la imposibilidad del padre de éstos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a64a6ba-884b-48a5-ac10-d2e6a4bf96f4', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '284', NULL, 262, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50820959-e4f1-4255-b36c-fc0fadb77aeb', '7a64a6ba-884b-48a5-ac10-d2e6a4bf96f4', 1, 'Cuando recaiga sobre dos o más personas la obligación de dar alimentos, se repartirá entre ellas el pago, en cantidad proporcionada a su caudal respectivo; en caso de urgente necesidad, y por circunstancias especiales, el juez podrá decretar que uno o varios de los obligados los preste provisionalmente, sin perjuicio de que pueda reclamar de los demás la parte que le corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f38239a-b92e-4944-8e6c-fca92671c04a', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '285', NULL, 263, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3272ad5-67d5-4861-ae19-a6cd83d1505e', '7f38239a-b92e-4944-8e6c-fca92671c04a', 1, 'Cuando dos o más alimentistas tuvieren derecho a ser alimentados por una misma persona, y ésta no tuviere fortuna bastante para atender a todos, los prestará en el orden siguiente: 1. A su cónyuge;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8d9575d1-5d5a-4d94-858e-d670f01e6229', '7f38239a-b92e-4944-8e6c-fca92671c04a', 2, '2. A los descendientes del grado más próximo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57965b2a-345e-4b4a-a989-bdf98810c0cb', '7f38239a-b92e-4944-8e6c-fca92671c04a', 3, '3. A los ascendientes, también del grado más próximo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e40372f2-34a7-48b9-bdca-5c92e5a4017e', '7f38239a-b92e-4944-8e6c-fca92671c04a', 4, '4. A los hermanos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5cfd6f8a-916a-4634-839d-f84b24e585a1', '7f38239a-b92e-4944-8e6c-fca92671c04a', 5, 'Si los alimentistas concurrentes fuesen el cónyuge, o varios hijos sujetos a la patria potestad, el juez atendiendo a las necesidades de uno y otros, determinará la preferencia o la distribución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5003e5b9-e3b6-40cb-b9d5-eddd48337796', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '286', 'Derechos para alimentos', 264, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e82a93c1-1f24-4dd6-a4fc-6f054a53d8fd', '5003e5b9-e3b6-40cb-b9d5-eddd48337796', 1, 'De las deudas que la mujer se vea obligada a contraer para alimentos de ella y de los hijos, por no proporcionar el padre lo indispensable para cubrirlos, será éste responsable de su pago en la cuantía necesaria para ese objeto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37c2dff4-aded-4a6f-adb0-8b33998ddd2a', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '287', NULL, 265, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55e52e3e-c4cc-44f1-b6a3-8f90aed4ac83', '37c2dff4-aded-4a6f-adb0-8b33998ddd2a', 1, 'La obligación de dar alimentos será exigible, desde que los necesitare la persona que tenga derecho a percibirlos. El pago se hará por mensualidades anticipadas, y cuando fallezca el alimentista, sus herederos no estarán obligados a devolver lo que éste hubiere recibido anticipadamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0a942c4e-ce93-4263-b780-859748526c5c', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '288', NULL, 266, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8bcb7535-be75-48cb-84a6-d1d61c88e83c', '0a942c4e-ce93-4263-b780-859748526c5c', 1, 'El que haya suministrado alimentos con protesta de cobrarlos, tiene derecho a ser indemnizado por la persona que esté obligada a satisfacerlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('329eb710-3af0-4b3e-aad8-dd25d075fcec', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '289', NULL, 267, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b17eb270-0389-44a4-9db0-5c739b8cfcda', '329eb710-3af0-4b3e-aad8-dd25d075fcec', 1, 'Cesará la obligación de dar alimentos: 1. Por la muerte del alimentista;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6448c190-265f-46aa-acfc-e9152364b533', '329eb710-3af0-4b3e-aad8-dd25d075fcec', 2, '2. Cuando aquél que los proporciona se ve en la imposibilidad de continuar prestándolos, o cuando termina la necesidad del que los recibía;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed7f7d39-9533-4672-9bd6-71d9b24098af', '329eb710-3af0-4b3e-aad8-dd25d075fcec', 3, '3. En el caso de injuria, falta o daño grave inferidos por el alimentista, contra el que debe prestarlos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0d731ffe-d744-4e60-a151-7652da7e362e', '329eb710-3af0-4b3e-aad8-dd25d075fcec', 4, '4. Cuando la necesidad de los alimentos dependa de la conducta viciosa o de la falta de aplicación al trabajo del alimentista, mientras subsistan estas causas; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b7169ae-56e6-4120-9408-addbbab35e77', '329eb710-3af0-4b3e-aad8-dd25d075fcec', 5, '5. Si los hijos menores se casaren sin el consentimiento de los padres.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f28840a-68ae-4371-83b8-a5c223476d08', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '290', NULL, 268, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19e6a165-a69d-4d64-b3d3-f13d61919019', '0f28840a-68ae-4371-83b8-a5c223476d08', 1, 'Los descendientes no pueden tampoco exigir alimentos: 1. Cuando han cumplido dieciocho años de edad, a no ser que se hallen habitualmente enfermos, impedidos o en estado de interdicción; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c99dcd5e-2179-4d30-b84c-55ebb782e0c7', '0f28840a-68ae-4371-83b8-a5c223476d08', 2, '2. Cuando se les ha asegurado la subsistencia hasta la misma edad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('39fa5728-4a0b-4a81-9674-36b81ecf0104', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '291', NULL, 269, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c271d368-628a-4d28-b7d5-3b3ac8d12fbb', '39fa5728-4a0b-4a81-9674-36b81ecf0104', 1, 'Las disposiciones de este capítulo son aplicables a los demás casos en que por ley, por testamento o por contrato, se tenga derecho a alimentos, salvo lo pactado u ordenado por el testador o lo dispuesto por la ley, para el caso especial de que se trate. El derecho de alimentos que provenga de contrato o disposición testamentaria, no perjudica, en ningún caso, la preferencia que la ley establece en favor de los parientes del obligado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('563d00fd-e585-4c1a-b54d-914cd5189067', 'a0000000-0000-0000-0000-000000000001', '46753d55-d70b-419f-94f0-068d3de69bc8', '292', 'Obligación de garantía', 270, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('212777ce-e22e-4f9d-9f0c-d5cee74f9d4e', '563d00fd-e585-4c1a-b54d-914cd5189067', 1, 'La persona obligada a dar alimentos contra la cual haya habido necesidad de promover juicio para obtenerlos, deberá garantizar suficientemente la cumplida prestación de ellos con hipoteca, si tuviere bienes hipotecables, o con fianza u otras seguridades, a juicio del juez. En este caso, el alimentista tendrá derecho a que sean anotados bienes suficientes del obligado a prestar alimentos, mientras no los haya garantizado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('00f06bde-bac2-4bf9-896b-63cb85f43a5c', '563d00fd-e585-4c1a-b54d-914cd5189067', 2, 'DE LA TUTELA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64255216-8da4-4e72-ba3a-d7b7c50c2b5a', '563d00fd-e585-4c1a-b54d-914cd5189067', 3, 'PARRAFO I DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ffe10e61-e017-4d11-a4ec-aa75f3162d15', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '293', 'Casos en que procede', 271, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29db5e25-cdd7-425f-bf3a-935250362190', 'ffe10e61-e017-4d11-a4ec-aa75f3162d15', 1, 'El menor de edad que no se halle bajo la patria potestad, quedará sujeto a tutela para el cuidado de su persona y de sus bienes. También quedará sujeto a tutela aunque fuere mayor de edad, el que hubiere sido declarado en estado de interdicción, si no tuviere padres. El tutor es el representante legal del menor o incapacitado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65a76804-8297-4eac-894c-54efae9de4f9', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '294', NULL, 272, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f196eabb-5c52-4e10-a664-169c2a8871c0', '65a76804-8297-4eac-894c-54efae9de4f9', 1, 'La tutela se ejerce por un tutor y un protutor, cuyos cargos son personales y no pueden delegarse, pero pueden otorgar mandatos especiales para actos determinados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38071158-f88f-4e90-9061-11958abf7e6a', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '295', NULL, 273, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae94b6f0-7026-4a2c-a21d-8aeee29ee6f8', '38071158-f88f-4e90-9061-11958abf7e6a', 1, 'La tutela y protutela son cargos públicos a cuyo desempeño están obligadas todas las personas que se encuentren en pleno goce de sus derechos civiles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9b649bf2-1699-427d-b734-56785f89f5f2', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '296', 'Clases de tutela', 274, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1fc918d-8020-4ec5-a661-65db0c909e36', '9b649bf2-1699-427d-b734-56785f89f5f2', 1, 'La tutela puede ser testamentaria, legítima y judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ff2b53ef-6307-4daa-bb5b-aaee1f52076f', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '297', 'Testamentaria', 275, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56e4dd53-6bd6-4cd5-a30e-7d5a04d8a822', 'ff2b53ef-6307-4daa-bb5b-aaee1f52076f', 1, 'La tutela testamentaria se instituye por testamento, por el padre o la madre sobreviviente, para los hijos que estén bajo su patria potestad; por el abuelo o la abuela, para los nietos que estén sujetos a su tutela legitima; por cualquier testador, para el que instituya heredero o legatario, si éste careciere de tutor nombrado por el padre o la madre y de tutor legítimo; y por el adoptante que designe heredero o legatario o su hijo adoptivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9977bfd4-7890-4acd-9a02-701f8e1c2c96', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '298', NULL, 276, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a735471-c9c2-429d-8f04-54714bda75ac', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 1, 'Los padres y los abuelos, en su caso, pueden nombrar un tutor y un protutor para todos o para varios de sus hijos o para cada uno de ellos. Pueden también nombrar varios tutores y protutores para que ejerzan el cargo uno en defecto de otro, respectivamente, en el orden de su designación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('730b1aa6-9a6a-4e08-beff-076f30053d04', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 2, '1. ARTICULO 299. Legítima. La tutela legítima de los menores corresponde en el orden siguiente: 2. Al abuelo paterno;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('65dc27f5-4c2f-476c-b0fe-bbde8ad96d36', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 3, '3. Al abuelo materno;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2d312d1-5287-414d-bc5c-0f34f4f1ebfe', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 4, '4. A la abuela paterna;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62d8c5d2-43c0-4dc9-877a-22624a17ed7d', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 5, '5. A la abuela materna; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb92e1a8-afd6-4991-9ef1-b3f664b5e122', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 6, '6. A los hermanos sin distinción de sexo, siendo preferido los que procedan de ambas líneas y entre éstos el de mayor edad y capacidad.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c308bebd-ff13-42b7-b0fb-1a57b3259052', '9977bfd4-7890-4acd-9a02-701f8e1c2c96', 7, 'La Línea materna será preferida a la paterna para la tutela de los hijos fuera de matrimonio. Sin embargo, mediando motivos justificados para variar la precedencia, puede el juez nombrar tutor al pariente que reúna las mejores condiciones de conocimiento y familiaridad con el menor, solvencia, idoneidad y preparación, que constituya una garantía para el desempeño satisfactorio de su cargo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('287c50ac-1d88-47c0-a1fa-dd2bf7f80b22', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '300', 'Judicial', 277, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f05c717-33c3-4c6e-93b0-6c7fa6de2cc5', '287c50ac-1d88-47c0-a1fa-dd2bf7f80b22', 1, 'La tutela judicial procede por nombramiento del juez competente, cuando no haya tutor testamentario ni legítimo. Para este efecto, el Ministerio Público y cualquier persona capaz deben denunciar a la autoridad el hecho que da lugar a la tutela no provista. Para la designación de la persona del tutor, el juez deberá tomar en cuenta las circunstancias que se mencionan en el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c1bb0b47-0ceb-4666-b399-719653d018f4', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '301', 'Tutela de los declarados en estado de interdicción', 278, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77058f2d-e3de-4282-b956-de72d5ee5968', 'c1bb0b47-0ceb-4666-b399-719653d018f4', 1, 'La tutela de los mayores de edad declarados en interdicción corresponde. 1. Al cónyuge;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d06fcaec-23f9-4e7b-b328-c51986b858f0', 'c1bb0b47-0ceb-4666-b399-719653d018f4', 2, '2. Al padre y a la madre;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0639e3a7-e594-45d1-bd7b-32e0aa3a5af2', 'c1bb0b47-0ceb-4666-b399-719653d018f4', 3, '3. A los hijos mayores de edad; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ab13fc8-1418-4c7d-95e9-e5e4f88a435c', 'c1bb0b47-0ceb-4666-b399-719653d018f4', 4, '4. A los abuelos, en el orden anteriormente establecido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e87d50b5-faa7-4f51-9d78-b6d0eda5525c', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '302', NULL, 279, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a67109d-08c9-4fee-a2f8-e1bcbfaf58f0', 'e87d50b5-faa7-4f51-9d78-b6d0eda5525c', 1, 'Si hallándose en ejercicio un tutor legítimo o judicial apareciere el testamentario, se transferirá inmediatamente a éste la tutela.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('64d9ad19-7144-4447-93f3-cfe5486fe929', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '303', NULL, 280, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b844c04-1bf7-47c7-a505-6305ab3226aa', '64d9ad19-7144-4447-93f3-cfe5486fe929', 1, 'Derecho de los menores que han cumplido dieciséis años A los menores que hayan cumplido la edad de dieciséis años, debe asociarlos el tutor en la administración de los bienes para su información y conocimiento; y si carecieren de tutor testamentario tendrán derecho a proponer candidato entre sus parientes llamados a la tutela legitima, o a falta de éstos, a persona de reconocida honorabilidad para que ejerza la tutela judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cb22b69d-5a3e-47ef-9984-addbc5b8b615', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '304', 'Protutor', 281, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76be7f36-2031-452b-b9da-1638dcff6297', 'cb22b69d-5a3e-47ef-9984-addbc5b8b615', 1, 'El protutor intervendrá en las funciones de la tutela, para asegurar su recto ejercicio. La designación del protutor se hará en la misma forma que la del tutor. Puede recaer en parientes del pupilo o en otras personas, siempre que reuna las condiciones de notoria honradez y arraigo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '305', NULL, 282, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8da11d10-0723-4772-bde6-cdc207f34699', '4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 1, 'El protutor está obligado: 1. A Intervenir en el inventario y avalúo de los bienes del menor y en la calificación y otorgamiento de la garantía que debe prestar el tutor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('78fe1c36-75a4-4198-9e0a-3c3426fc094b', '4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 2, '2. A defender los derechos del menor en juicio y fuera de él, siempre que estén en oposición con los intereses del tutor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae7f2d50-32d7-47cf-88da-e26cf90d9244', '4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 3, '3. A promover el nombramiento de tutor, cuando proceda la remoción del que estuviera ejerciéndola, o cuando la tutela quede vacante o abandonada;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a92fc138-17fa-40c3-a770-97a2e267faff', '4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 4, '4. A intervenir en la rendición de cuentas del tutor; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f64348d-5ebe-4f33-9e3f-e55e0ed99239', '4897ef06-b8cb-4c29-8f56-91f7c69ddf9d', 5, '5. A ejercer las demás atribuciones que le señala la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29591e30-d963-4b34-89cc-3f1fe6c5be88', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '306', 'Tutores específicos', 283, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd7f7500-d3ae-4a1e-b760-85465f1c37d8', '29591e30-d963-4b34-89cc-3f1fe6c5be88', 1, 'Cuando hubiere conflicto de intereses entre varios pupilos sujetos a una misma tutela, el juez les nombrará tutores específicos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46420de8-772c-40da-9cb4-02b359078a06', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '307', NULL, 284, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94d3eda8-572f-42dc-9ed8-e65250ee9e9e', '46420de8-772c-40da-9cb4-02b359078a06', 1, 'Mientras no se nombre tutor y protutor y no se disciernan los cargos, el juez, de oficio, o a solicitud del Ministerio Público, deberá dictar las providencias');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12290f0b-309f-4b66-94ba-7ace0fc8df81', '46420de8-772c-40da-9cb4-02b359078a06', 2, 'necesarias para el cuidado de la persona del menor o incapacitado y la seguridad de sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('182e47b7-b657-465c-9184-ef497e9be52b', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '308', 'Tutores legales', 285, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70ed7ef5-9b80-4bbe-8806-a5cae29725bb', '182e47b7-b657-465c-9184-ef497e9be52b', 1, 'Los directores o superiores de los establecimientos de asistencia social, que acojan menores o incapacitados, son tutores y representantes legales de los mismos, desde el momento de su ingreso, y su cargo no necesita discernimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('39b0ae62-ea9a-4107-8d9d-90e24e10f16b', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '309.14', NULL, 286, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d9a6990-0496-4a12-920e-e6e29329de5b', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '310', NULL, 287, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('83e31c91-cc6c-4170-a1ab-43c752209f13', '4d9a6990-0496-4a12-920e-e6e29329de5b', 1, 'Los extranjeros no están obligados a aceptar el cargo de tutor o protutor, sino en el caso de que se trate de sus parientes y connacionales. La admisión de tales cargos, no implica la adquisición de la nacionalidad guatemalteca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aee30e94-e6f4-4bca-8179-ef315c6ee5a2', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '311', NULL, 288, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd3be3de-0e24-4149-b30d-ec641e26fd9f', 'aee30e94-e6f4-4bca-8179-ef315c6ee5a2', 1, 'El discernimiento de la tutela, se rige por la ley del lugar del domicilio del menor o incapacitado. El cargo de tutor, discernido en país extranjero, de conformidad con las leyes de dicho país, será reconocido en la república.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf5c3ca3-325e-4cbf-a31a-2f9d03b61d5f', 'aee30e94-e6f4-4bca-8179-ef315c6ee5a2', 2, 'La tutela en cuanto a los derechos y obligaciones que impone, se rige por las leyes del lugar en que fue discernido el cargo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4fec1aea-8669-4faa-a3f3-f2eb998fc632', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '312', NULL, 289, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f360acd5-0dca-4856-b6bc-78a673645cf2', '4fec1aea-8669-4faa-a3f3-f2eb998fc632', 1, 'Las facultades de los tutores, respecto a los bienes que el menor o incapacitado tuviere fuera del lugar de su domicilio, se ejercitarán conforme a la ley del lugar en que dichos bienes se hallen situados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83d66f2d-901b-4a9d-b659-f0cd4212cad5', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '313', NULL, 290, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('305b3f3b-10b0-49d5-b36e-8ebe7464edd5', '83d66f2d-901b-4a9d-b659-f0cd4212cad5', 1, 'Las disposiciones relativas a los tutores, regirán para las personas que administren bienes de menores o incapaces, en casos determinados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f257eab-10b1-40f1-91c9-b68983684d8e', '83d66f2d-901b-4a9d-b659-f0cd4212cad5', 2, 'PARRAFO II INHABILIDAD Y EXCUSAS PARA LA TUTELA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '314', 'Prohibiciones', 291, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('edf29019-2fb3-432d-8747-ab7fac0d668c', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 1, 'No puede ser autor ni protutor: 1. El menor de edad y el incapacitado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2706a025-4cd5-4611-8151-b50e182b2e4d', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 2, '2. El que hubiere sido penado por robo, hurto, estafa, falsedad, faltas y delitos contra la honestidad, u otros delitos del orden común que merezcan pena mayor de dos años;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('353e3621-1564-4b33-a877-a78a7851375f', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 3, '14 Derogado por el Artículo 67, del Decreto No. 77-2007 publicado en el Diario de Centro América el 31 de diciembre de 2007.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3731a35e-34d0-4c80-8077-dfbf54dc6649', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 4, '3. El que hubiere sido removido de otra tutela, o no hubiere rendido cuentas de su administración, o si habiéndolas rendido, no estuviesen aprobadas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8ec7c10a-fa78-4732-bb19-70ccee48668d', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 5, '4. El ebrio consuetudinario, el que haga uso habitual de estupefacientes, el vago y el de notoria mala conducta;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('af2792c1-7e63-4958-8e48-92c9a5f654b5', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 6, '5. El fallido o concursado, mientras no haya obtenido su rehabilitación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('af059159-26ff-44cd-84be-587753ca2708', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 7, '6. El que tenga pendiente litigio propio o de sus ascendientes, descendientes o cónyuges, con el menor o incapacitado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a6ccf3f-37a8-42cc-924d-ec7a8f7fe3b4', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 8, '7. El que ha perdido el ejercicio de la patria potestad o la administración de los bienes de sus hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88ba1c84-5b58-486e-a063-f8e572fb9063', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 9, '8. El acreedor o deudor del menor por cantidad apreciable en relación con los bienes del menor, a juicio del juez, a menos que con conocimiento de causa, haya sido nombrado por testamento;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('00755644-09c7-4289-8cfd-e83c5ce856a7', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 10, '9. El que no tenga domicilio en la república; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12a9f84f-6ee0-4cf2-a3c9-06ae30af3f88', '29fe75e3-43e6-4624-a3fd-4b83355ecbd9', 11, '10. El ciego y el que padezca enfermedad grave, Incurable o contagiosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('685bd678-e3c3-455d-a77e-a4a046601bd0', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '315', NULL, 292, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb26cdf3-69e7-4f5a-9465-43c69c79ffd8', '685bd678-e3c3-455d-a77e-a4a046601bd0', 1, 'Los tutores o protutores a quienes sobrevenga alguna de las incapacidades que se mencionan en el artículo anterior, serán separados de su cargo por declaración judicial, previa denuncia y comprobación del hecho por el Ministerio Público o algún pariente del pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c0ab410e-6e2b-41de-b484-df7769caacf0', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '316', 'Remoción', 293, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b148b649-42a5-4e75-b949-3bca493338f8', 'c0ab410e-6e2b-41de-b484-df7769caacf0', 1, 'Serán también removidos de la tutela y protutela: 1. Los que demuestren negligencia, ineptitud o infidelidad en el desempeño del cargo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eae776f1-c3c5-4a02-89b4-d7af5c05af9a', 'c0ab410e-6e2b-41de-b484-df7769caacf0', 2, '2. Los que incitaren al pupilo a la corrupción o al delito;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b17cd46-7919-4eae-926b-ff18822169b2', 'c0ab410e-6e2b-41de-b484-df7769caacf0', 3, '3. Los que emplearen maltrato con el menor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62bdfbab-32cf-45a7-9d5e-1b937d6cc753', 'c0ab410e-6e2b-41de-b484-df7769caacf0', 4, '4. Los que a sabiendas hayan cometido inexactitud en el Inventario, omitiendo bienes o créditos activos o pasivos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4f2a8147-b8a2-4843-9fc2-6d8a02f469aa', 'c0ab410e-6e2b-41de-b484-df7769caacf0', 5, '5. Los que se ausenten por más de seis meses, del lugar en que desempeñen la tutela y protutela.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '317', 'Excusa', 294, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('522e6487-b10e-484a-96d8-57944175f945', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 1, 'Pueden excusarse de la tutela y protutela:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f9e2d35-dd23-4c8d-83cf-c6fd38f650d9', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 2, '1. Los que tengan a su cargo otra tutela o protutela;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77f909f8-1f09-426a-8bef-5743024ba185', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 3, '2. Los mayores de sesenta años;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2db2a5f1-84ad-47c3-8c6e-da19dd835150', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 4, '3. Los que tengan bajo su patria potestad tres o más hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8ceebe7e-51bb-49e0-bc70-365670aecafa', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 5, '4. Las mujeres;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('799535ee-aefb-4982-8878-3e56d1ee9c70', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 6, '5. Los que por sus limitados recursos no puedan atender el cargo sin menoscabo de su subsistencia;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ad031ee-0ae0-418d-98ae-2f65e0bfceec', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 7, '6. Los que padezcan enfermedad habitual que les impida cumplir los deberes de su cargo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c65072b3-fc8f-4aff-9828-07eb076c9351', '7f8e1b43-ae41-4fdf-a2d1-9b981a353065', 8, '7. Los que tengan que ausentarse de la República por más de un año.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b1c735fb-a8a6-4a59-983b-19ff1e17467c', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '318', NULL, 295, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('943e5050-e182-4df9-9e5a-46f95193805e', 'b1c735fb-a8a6-4a59-983b-19ff1e17467c', 1, 'Los que no fueren parientes del menor o incapacitado, no estarán obligados a aceptar la tutela o protutela si hubiere personas llamadas por la ley, que no tengan excusa o impedimentos para ejercer aquellos cargos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6784333d-2709-4789-8c22-31f2360f1c8f', 'b1c735fb-a8a6-4a59-983b-19ff1e17467c', 2, 'PARRAFO III EJERCICIO DE LA TUTELA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5fc706d9-39e4-4a3a-926d-b4ec0a7983c3', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '319', 'Discernimiento del cargo', 296, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb329326-cdd0-4ef9-8fe1-ab3aac6cf832', '5fc706d9-39e4-4a3a-926d-b4ec0a7983c3', 1, 'El tutor y el protutor no entrarán a ejercer sus cargos, sino después de discernidos por el juez. Ninguna tutela puede ser discernida sin estar llenados todos los requisitos que para su ejercicio exige la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fb394f4-8808-415d-831c-411a1b639dde', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '320', 'Obligación de hacer inventario', 297, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7aa51a10-f6b4-47ea-b823-825fa111b12d', '6fb394f4-8808-415d-831c-411a1b639dde', 1, 'El tutor procederá al inventario y avalúo de los bienes del menor o incapacitado, dentro de los treinta días siguientes a la aceptación del cargo, plazo que podrá ser restringido o ampliado prudencialmente por el juez, según las circunstancias. En ningún caso, ni aun por disposición del testador, quedará el tutor eximido de esta obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('97495eac-5f1e-43c3-9bda-d97de2fc3fcc', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '321', 'Constitución de garantía', 298, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25c42cbd-0759-4053-a83b-97ddbc05a816', '97495eac-5f1e-43c3-9bda-d97de2fc3fcc', 1, 'Practicado el inventario, el tutor y el protutor quedan solidariamente obligados a promover la constitución de la garantía, salvo que no haya bienes, o que tratándose de tutor testamentario hubiere sido relevado de esta obligación por el testador, en cuanto a los bienes objeto de la herencia, donación o legado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d5beeb52-62ea-4df0-aef2-3abe3aa2575e', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '322', NULL, 299, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf6fcce6-96c7-4594-acdd-1f3cebd859c3', 'd5beeb52-62ea-4df0-aef2-3abe3aa2575e', 1, 'Cuando con posterioridad al discernimiento de la tutela, sobrevenga o se descubra causa que haga obligatoria la caución, lo harán saber al juez, el propio tutor o el protutor, o el Ministerio Público, para el efecto de la constitución de la garantía.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90c32987-eeff-4f13-80b4-bc66664bec41', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '323', NULL, 300, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32d027b0-9231-44c3-9744-2f9d60dc7133', '90c32987-eeff-4f13-80b4-bc66664bec41', 1, 'La garantía deberá asegurar: 1. El importe de los bienes muebles que reciba el tutor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7cc959bf-5161-4944-a181-6c82f517f38a', '90c32987-eeff-4f13-80b4-bc66664bec41', 2, '2. El promedio de la renta de los bienes, en los últimos tres años anteriores a la tutela; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b57f8e25-e51f-44f6-bebe-fa20177a12e0', '90c32987-eeff-4f13-80b4-bc66664bec41', 3, '3. Las utilidades que durante un año puede percibir el pupilo de cualquier empresa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aaef26f2-4e8b-4c2f-a0d2-05dd92698059', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '324', NULL, 301, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b19c7f1f-2f02-4e11-b93c-f7a07b92480a', 'aaef26f2-4e8b-4c2f-a0d2-05dd92698059', 1, 'La garantía deberá aumentarse o disminuirse, según aumente o disminuya el valor de los bienes expresados y el de las cosas en que aquella esté constituida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ace78d3-5b84-4e9b-a1e4-7a7f9ef83eb1', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '325', NULL, 302, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('00d76e5c-2511-415a-a2c8-7c8125500612', '0ace78d3-5b84-4e9b-a1e4-7a7f9ef83eb1', 1, 'La garantía deberá consistir en hipoteca, prenda o fianza otorgada por alguna institución bancaria o legalmente autorizada para el efecto. La garantía personal y aun la caución juratoria, pueden admitirse por el juez cuando, a su juicio, fueren suficientes, tomando en cuenta el valor de los bienes que vaya a administrar el tutor y la solvencia y buena reputación de éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37a51b45-b721-4a44-905d-ead3103a4a71', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '326', NULL, 303, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6f5939f1-3d94-4616-9872-0d38e03d5bca', '37a51b45-b721-4a44-905d-ead3103a4a71', 1, 'La garantía prendaria que preste el tutor, se constituirá depositando los efectos o valores en una institución de crédito autorizada para recibir depósitos; y a falta de ella, en una persona de notorio arraigo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29353503-3ba3-469e-8fd0-54729376bd7f', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '327', NULL, 304, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b91e6f04-3fdd-4f83-9cea-be35e9342693', '29353503-3ba3-469e-8fd0-54729376bd7f', 1, 'El juez fijará, a solicitud y propuesta del tutor, la pensión alimenticia, de acuerdo con el inventario y las circunstancias del pupilo, sin perjuicio de alterarla, según el aumento o disminución del patrimonio y otros motivos que apreciará el tribunal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('71c1b1d0-740e-469a-9899-ad11e16fd54b', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '328', 'Presupuesto', 305, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc2690bc-ac18-4576-8007-e2eeedb64c86', '71c1b1d0-740e-469a-9899-ad11e16fd54b', 1, 'El tutor, dentro del primer mes de ejercer su cargo, someterá a la aprobación del juez, el presupuesto de gastos de administración para el año. Para los gastos extraordinarios que pasen de quinientos quetzales, necesita el tutor autorización judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fbb4721d-9c68-4219-88aa-2404f7926aa0', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '329', NULL, 306, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d3b1805-543d-4171-8b97-a726a84ab12b', 'fbb4721d-9c68-4219-88aa-2404f7926aa0', 1, 'Las alhajas, muebles preciosos, efectos públicos, bonos, acciones y valores, que a juicio del juez no hayan de estar en poder del tutor, serán depositados en un establecimiento autorizado por la ley para recibir depósitos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('95dfc838-b59c-4cc0-89d9-90b2190ca482', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '330', 'Carrera, oficio o profesión del menor', 307, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e06f511a-020b-4d2a-885d-eaac175f407b', '95dfc838-b59c-4cc0-89d9-90b2190ca482', 1, 'El tutor destinará al menor a la carrera, oficio o profesión que éste elija, según sus circunstancias. Si ya había iniciado alguna de estas actividades durante la patria potestad, el tutor no puede');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b5f10bb-40c4-419e-b45f-48dfec7e3ca0', '95dfc838-b59c-4cc0-89d9-90b2190ca482', 2, 'variarla sin autorización del juez, para lo cual deberá tomarse en cuenta las aptitudes y circunstancias del menor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bc8b1a09-056d-4506-be9c-0410b7ac5fd2', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '331', 'El pupilo debe respeto y obediencia al tutor', 308, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('658cc8bd-bb75-4ede-ade0-de2aa10de0e6', 'bc8b1a09-056d-4506-be9c-0410b7ac5fd2', 1, 'Este tiene respecto de aquél, las facultades de los padres, con las limitaciones que la ley establece.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ba75499-801d-4912-85f4-091f8d137c5d', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '332', 'Necesidad de autorización judicial', 309, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a6d315c-eeb9-4369-a06d-4a0686f4ddb0', '9ba75499-801d-4912-85f4-091f8d137c5d', 1, 'El tutor necesita autorización judicial: 1. Para enajenar o gravar bienes inmuebles o derechos reales del menor incapacitado; para dar los primeros en arrendamiento por más de tres años, o con anticipo de renta por más de un año; para hacer o reconocer mejoras que no sean necesarias; para constituir servidumbres pasivas; y en general, para celebrar otra clase de contratos que afecten el patrimonio del pupilo, siempre que pasen de quinientos quetzales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c56f640e-e4eb-40d3-aaae-0d57c13147a7', '9ba75499-801d-4912-85f4-091f8d137c5d', 2, 'Los contratos a que se refiere este inciso, no pueden ser prorrogados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a70a44e8-0e57-47ab-b70a-c48e1f3aef10', '9ba75499-801d-4912-85f4-091f8d137c5d', 3, '2. Para tomar dinero a mutuo, debiendo sujetarse a las condiciones y garantías que acuerde el juez;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba06419d-65aa-43db-b527-4f08b6e91575', '9ba75499-801d-4912-85f4-091f8d137c5d', 4, '3. Para repudiar herencias, legados y donaciones;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2255653-4b3e-4247-a156-446ccec35c55', '9ba75499-801d-4912-85f4-091f8d137c5d', 5, '4. Para transigir o comprometer en árbitros, las cuestiones en que el pupilo tuviere interés;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b68dbe24-4a7f-460f-a3e1-29ea0008feb7', '9ba75499-801d-4912-85f4-091f8d137c5d', 6, '5. Para hacerse pago de los créditos que tenga contra el menor o incapacitado; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc4e3942-68f7-48da-af22-4efca7ac3795', '9ba75499-801d-4912-85f4-091f8d137c5d', 7, '6. Para resolver la forma, condiciones y garantías en que debe colocar el dinero del pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3d26e454-d9e0-41f2-8f2d-dfe14bec189c', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '333', NULL, 310, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1439df25-ba4c-47f0-8804-549d8597310f', '3d26e454-d9e0-41f2-8f2d-dfe14bec189c', 1, 'La venta de valores comerciales o industriales, títulos de renta, acciones, bonos, frutos y ganados, podrá hacerse extrajudicialmente, pero nunca por menor valor del que se cotice en la plaza el día de la venta, lo cual deberá comprobar el tutor al rendir sus cuentas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('08861262-1f99-46fd-9bd6-aaeaafb2dedc', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '334', NULL, 311, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1f899065-1156-435e-b9ea-48a5ef1acbc2', '08861262-1f99-46fd-9bd6-aaeaafb2dedc', 1, 'El tutor responde de los intereses legales del capital del pupilo, cuando por su omisión o negligencia, quedare improductivo o sin empleo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('229472d9-028c-432d-84f8-f25f7b0d575a', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '335', NULL, 312, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('403bff57-b64b-4598-8811-51cddd915422', '229472d9-028c-432d-84f8-f25f7b0d575a', 1, 'El tutor no puede sin autorización judicial, liquidar la empresa que forme parte del patrimonio del menor o variar el comercio o industria a que éste o sus causantes hubieren estado dedicados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '336', 'Prohibiciones', 313, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a0ca4c0-7689-4bf0-930d-f598f0279877', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 1, 'Quedan prohibidos al tutor los actos siguientes:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('21e4e372-d1de-4404-9065-59e303a73da6', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 2, '1. Contratar por sí o por interpósita persona, con el menor o incapacitado, o aceptar contra él créditos, derechos o acciones, a no ser que resulten de subrogación legal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('78684a23-5d7f-4c04-b4e5-d4c4a19566b0', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 3, '2. Disponer a título gratuito de los bienes del menor o incapacitado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7ec9b220-0f78-42e2-af05-d98ecaf031d8', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 4, '3. Aceptar donaciones del expupilo, sin estar aprobadas y canceladas las cuentas de su administración salvo cuando el tutor fuere ascendiente, cónyuge o hermano del donante;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7fbb49d6-478d-4746-8fbe-075e80b9b246', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 5, '4. Hacer remisión voluntaria de derechos del menor o incapacitado; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40d89fbe-9ace-4631-bbb5-39d33a08c6a5', '4cca38e9-59a4-4fd1-8859-eba9fbcc25f5', 6, '5. Aceptar la institución de beneficiario en seguros a su favor, provenientes de su pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c4c55009-8fe7-4929-8acb-181667756fbb', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '337', NULL, 314, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('08f1aac2-b6b5-4abf-8443-136e02bd9ee7', 'c4c55009-8fe7-4929-8acb-181667756fbb', 1, 'Tampoco podrán contratar acerca de bienes del menor o incapacitado, por si o por interpósita persona, los parientes del tutor, salvo que éstos sean coherederos o copartícipes del pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6d46f6b8-5ddc-47f2-84b2-ca1d7940bc8e', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '338', NULL, 315, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad556a56-8f2c-4c29-bb03-396f80c7ab95', '6d46f6b8-5ddc-47f2-84b2-ca1d7940bc8e', 1, 'El tutor no puede reconocer hijos del pupilo, sino con el consentimiento expreso de éste y en ningún caso los del incapaz, ni consentir expresa o tácitamente las resoluciones desfavorables al pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a26f12e-6668-4139-bc6e-44c9899f286b', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '339', NULL, 316, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56e21f13-ade1-4cb2-b7ed-ea1c63ae9943', '4a26f12e-6668-4139-bc6e-44c9899f286b', 1, 'Durante el ejercicio de la tutela, el protutor está obligado a defender los derechos del menor en juicio y fuera de él, cuando estén en oposición con los intereses del tutor; y a promover el nombramiento, cuando proceda la remoción del que la tuviere en ejercicio, o cuando la tutela quede vacante o abandonada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fbc3f04e-abd9-422c-aeea-964607ff81a4', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '340', 'Retribución de la tutela', 317, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b6206842-e998-43b7-952e-e7d2fe54855e', 'fbc3f04e-abd9-422c-aeea-964607ff81a4', 1, 'La tutela y protutela dan derecho a una retribución que se pagará anualmente y que no bajará del cinco ni excederá del quince por ciento anual de las rentas y productos líquidos de los bienes del pupilo. Cuando la retribución no hubiere sido fijada en el testamento, o cuando sin mediar negligencia del tutor, no hubiere rentas o productos líquidos, la fijará el juez, teniendo en cuenta la importancia del caudal del pupilo y el trabajo que ocasione el ejercicio de la tutela. La retribución se distribuirá entre el tutor y el protutor, correspondiendo al primero el setenta y cinco por ciento y al segundo el veinticinco por ciento restante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fb319c46-c2a8-4ffb-8121-9fc6f196e700', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '341', NULL, 318, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('469972f4-d723-4d6b-9e97-a7f5cf3b656e', 'fb319c46-c2a8-4ffb-8121-9fc6f196e700', 1, 'Cuando el tutor y el protutor hubieren sido removidos por su culpa, no tendrán derecho a recibir retribución alguna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29a949ef-1edf-4285-859b-1819991e6d54', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '342', NULL, 319, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aad61e35-135b-496d-b296-d36204c9d233', '29a949ef-1edf-4285-859b-1819991e6d54', 1, 'El tutor está obligado a llevar una contabilidad, comprobada y exacta de todas las operaciones de su administración, en libros autorizados, aun cuando el testador le hubiere relevado de rendir cuentas. Al final de su cargo, presentará una memoria que resuma los actos llevados a cabo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f0079cb-c4a7-4441-a0c9-2f4d84dd4774', '29a949ef-1edf-4285-859b-1819991e6d54', 2, 'PARRAFO IV Rendición de cuentas de la tutela');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9dc2982-0e25-47e1-89e6-0f12abd4a984', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '343', NULL, 320, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('284b0e9e-f0f8-4b1c-8c87-d66888404df9', 'e9dc2982-0e25-47e1-89e6-0f12abd4a984', 1, 'El tutor deberá rendir cuentas anualmente y al concluirse la tutela o cesar en su cargo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bad8f4cf-1704-4ee1-b97c-5571dd5f137f', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '344', NULL, 321, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15837731-8288-4ea7-989e-4be0e3efa8e3', 'bad8f4cf-1704-4ee1-b97c-5571dd5f137f', 1, 'La rendición anual de cuentas se hará ante el juez con intervención del protutor y del Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e046cec6-5342-4b49-9144-583a16f651a9', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '345', NULL, 322, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f09b211-068a-4b2f-b672-15a2f29f5abd', 'e046cec6-5342-4b49-9144-583a16f651a9', 1, 'La rendición final de cuentas se hará por el tutor o sus herederos, al expupilo o a quien lo represente, dentro de sesenta días contados desde que terminó el ejercicio de la tutela.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1e624925-49ba-4dbf-ba32-98b7f20c0a43', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '346', NULL, 323, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b94877e-53bc-4cb3-b09e-c421f90c9605', '1e624925-49ba-4dbf-ba32-98b7f20c0a43', 1, 'El tutor que sustituya a otro está obligado a exigir la entrega de bienes y la rendición de cuentas al que lo ha precedido. Si no lo hiciere, es responsable de los daños y perjuicios que por su omisión se siguieren al pupilo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9353bcf6-920b-4066-a937-dd483c7d9199', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '347', NULL, 324, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1b47a67-7482-4981-a01e-7005a95a66d1', '9353bcf6-920b-4066-a937-dd483c7d9199', 1, 'Las cuentas deben ir acompañadas de sus documentos Justificativos. Sólo podrá excusarse la comprobación de los gastos en que no se acostumbre recoger recibo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c290879-8f3e-419c-bc43-b9a60ee6a9fe', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '348', NULL, 325, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('06ffdf02-a5e2-457f-9218-52d0b5917c5b', '1c290879-8f3e-419c-bc43-b9a60ee6a9fe', 1, 'Los gastos de la rendición de cuentas, serán a cargo del menor o incapacitado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1e28bbed-0da5-40ff-baf6-e0a0c2e542fb', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '349', 'Entrega de bienes', 326, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0eda67c-c8d2-4a60-aad1-b2bf389d0860', '1e28bbed-0da5-40ff-baf6-e0a0c2e542fb', 1, 'El tutor, concluida la tutela, está obligado a entregar al que fue su pupilo, todos los bienes y documentos que le pertenezcan. Esta obligación no se suspende por estar pendiente la rendición de cuentas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8d071bf6-7bc3-47a5-9460-27994c9f1727', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '350', NULL, 327, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f086767-8885-4860-9a0d-0dff6d6f19d2', '8d071bf6-7bc3-47a5-9460-27994c9f1727', 1, 'El saldo de las cuentas que resultare a favor o en contra del tutor, producirá interés legal. En el primer caso, desde que el pupilo sea requerido para el pago, previa entrega de los bienes; en el segundo, desde la rendición de cuentas, si hubieren sido rendidas dentro del término legal, y en caso contrario, desde que éste expire.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb7bec9e-a0f2-46af-b1e3-6d06b1d38da4', 'a0000000-0000-0000-0000-000000000001', '9cf05388-4dd6-47d2-bb4f-b20feeb83095', '351', 'Prescripción de acciones', 328, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f65db3b4-bb1a-403c-83ea-0ace0ae821bd', 'eb7bec9e-a0f2-46af-b1e3-6d06b1d38da4', 1, 'Las acciones u obligaciones que recíprocamente correspondan al tutor y al expupilo, por razón del ejercicio de la tutela, se extinguen a los cinco años de concluida ésta.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf6bd408-c2ca-4eb3-aeed-e6a5b0c272fa', 'eb7bec9e-a0f2-46af-b1e3-6d06b1d38da4', 2, 'DEL PATRIMONIO FAMILIAR');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bc8152a3-68a7-4427-a1a3-871d7450b121', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '352', 'Concepto', 329, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c98e3213-b1ce-446a-93f6-b93d67701557', 'bc8152a3-68a7-4427-a1a3-871d7450b121', 1, 'El patrimonio familiar es la institución jurídico-social por la cual se destina uno o más bienes a la protección del hogar y sostenimiento de la familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65d39ddb-23ed-4953-a7e0-e9e57d23102a', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '353', 'Bienes sobre los cuales puede constituirse', 330, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1fc03753-8350-4f28-be35-15997e576438', '65d39ddb-23ed-4953-a7e0-e9e57d23102a', 1, 'Las casas de habitación, los predios o parcelas cultivables, los establecimientos industriales y comerciales, que sean objeto de explotación familiar, pueden constituir el patrimonio de familia, siempre que su valor no exceda de la cantidad máxima fijada en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ffaa6ed-b719-4266-ae33-422b21f80761', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '354', NULL, 331, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb9b7f1e-08dc-4516-99ba-b9ba80b33dd0', '7ffaa6ed-b719-4266-ae33-422b21f80761', 1, 'Sólo puede fundarse un patrimonio para cada familia, por el padre o la madre sobre sus bienes propios, o por marido y mujer sobre bienes comunes de la sociedad conyugal. También puede constituirse por un tercero, a título de donación o legado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('191b381e-5386-431f-b8e9-59026c44ab78', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '355', 'Valor máximo del patrimonio', 332, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52323189-1773-4472-9d65-597e287470bf', '191b381e-5386-431f-b8e9-59026c44ab78', 1, 'No puede establecerse patrimonio familiar que exceda de cien mil quetzales en el momento de su constitución. Cuando el valor de los bienes afectos halla sido inferior a dicha suma podrá ampliarse hasta llegar a ese valor, sujetándose la ampliación al mismo procedimiento que para su constitución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93bba450-bd70-4c86-81c9-040e477bae2b', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '356', 'Caracteres del patrimonio', 333, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b56fa6f-a5e1-42d1-af05-b4323258fa76', '93bba450-bd70-4c86-81c9-040e477bae2b', 1, 'Los bienes constituidos en patrimonio familiar son indivisibles, inalienables, inembargables y no podrán estar gravados ni gravarse, salvo el caso de servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5645b84d-4294-47ab-8dbe-bb438c8179a0', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '357', 'No puede hacerse en fraude de acreedores', 334, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('beb8f5de-b3e2-4dd8-a6ba-1e4fa58badf6', '5645b84d-4294-47ab-8dbe-bb438c8179a0', 1, 'El establecimiento del patrimonio familiar no puede hacerse en fraude de acreedores. Los bienes deben estar libres de anotación y gravamen y la gestión del instituyente solicitando la aprobación judicial, será publicada para que llegue a conocimiento de los que puedan tener interés en oponerse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('13d8a506-0d0f-4509-80f0-55ca65576e6a', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '358', 'Obligación de los beneficiarios', 335, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7b41b31-aa07-4400-8adc-7f6ea47c444b', '13d8a506-0d0f-4509-80f0-55ca65576e6a', 1, 'Los miembros de la familia beneficiaria están obligados a habitar la casa o a explotar personalmente el predio agrícola, o la industria o negocio establecido, salvo las excepciones que el juez permita temporalmente por motivos justificados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d929ac3d-bbe4-4593-8c7a-f12748a7e904', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '359', NULL, 336, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a192a487-321f-4ec4-b88d-5b8c9725ef74', 'd929ac3d-bbe4-4593-8c7a-f12748a7e904', 1, 'Si el inmueble constituido en patrimonio familiar fuere inscrito únicamente a nombre del cabeza de familia, se entenderá que ha sido constituido para el sostenimiento del cónyuge, de los hijos menores o incapaces y de las personas que tengan derecho a ser alimentadas por aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90f80f74-0849-458e-a6eb-59d22128f7d8', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '360', 'Obligación de constituir patrimonio', 337, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05a4ad2e-27fd-4eb8-bf4d-77cc257174e7', '90f80f74-0849-458e-a6eb-59d22128f7d8', 1, 'Cuando haya peligro de que la persona que tiene obligación de dar alimentos, pierda sus bienes por mala administración o porque los esté dilapidando, los acreedores alimentistas tienen derecho a exigir judicialmente que se constituya patrimonio familiar sobre determinado bien del obligado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b4de0444-c33e-4980-9fe3-ddbc10f4c6b5', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '361', 'Aprobación judicial', 338, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01c04237-b47d-4ee6-898a-5bf9b6b00cbc', 'b4de0444-c33e-4980-9fe3-ddbc10f4c6b5', 1, 'Para la constitución del patrimonio familiar se requiere la aprobación judicial y su inscripción en el Registro de la Propiedad, previos los trámites que fije el Código Procesal Civil y Mercantil. Sin embargo, cuando el Estado proceda al parcelamiento y distribución de un bien nacional, podrá darle a cada parcela el carácter de patrimonio familiar; y bastará esta calificación legal, para su constitución y registro. En lo demás, este patrimonio familiar se regulará de conformidad con lo dispuesto en este capítulo en todo lo que le sea aplicable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7e1a0686-0c55-4785-b04d-0c2f71d49946', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '362', 'Administrador', 339, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a575f95c-374c-4c66-8890-31bd98fc6eb4', '7e1a0686-0c55-4785-b04d-0c2f71d49946', 1, 'El representante legal de la familia será el administrador del patrimonio familiar y representante a la vez de los beneficiarios en todo lo que al patrimonio se refiera.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61c189be-33c6-4bac-ab48-29ae8fb52f5e', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '363', NULL, 340, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05570961-9b93-4f6e-b182-513026be9348', '61c189be-33c6-4bac-ab48-29ae8fb52f5e', 1, 'El patrimonio familiar termina: 1. Cuando todos los beneficiarios cesen de tener derecho a percibir alimentos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0443203-c6e3-4232-94aa-4477b15ff962', '61c189be-33c6-4bac-ab48-29ae8fb52f5e', 2, '2. Cuando sin causa justificada y sin autorización judicial, la familia deje de habitar la casa que debe servirle de morada, o de cultivar por su cuenta la parcela o predio vinculado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('436a25a4-bf2b-4aec-8a6b-897bc15bc334', '61c189be-33c6-4bac-ab48-29ae8fb52f5e', 3, '3. Cuando se demuestre la utilidad y necesidad para la familia, de que el patrimonio quede extinguido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf2fee68-9b84-429a-8c82-41df49c31c82', '61c189be-33c6-4bac-ab48-29ae8fb52f5e', 4, '4. Cuando se expropien los bienes que lo forman; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff997003-431c-4373-87ca-3e43f2239f8d', '61c189be-33c6-4bac-ab48-29ae8fb52f5e', 5, '5. Por vencerse el término por el cual fue constituido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('62e2324e-0aff-48b3-b3a1-41e949c07672', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '364', NULL, 341, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c71a6949-1761-4955-82db-a5c913a3c909', '62e2324e-0aff-48b3-b3a1-41e949c07672', 1, 'El patrimonio familiar a término fijo, debe comprender el término indispensable para que el menor de los miembros actuales de la familia alcance la mayoría de edad; pero en ningún caso podrá constituirse un patrimonio familiar por un término menor de diez años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('18321657-0bdc-4944-974b-258c3b386de6', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '365', NULL, 342, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c788e82-282d-42e9-8fa4-d874280c64a2', '18321657-0bdc-4944-974b-258c3b386de6', 1, 'Terminado el derecho al patrimonio familiar, los bienes sobre que fue constituido, volverán al poder de quien lo constituyó o de sus herederos; pero si el dominio corresponde a los beneficiarios, tendrán derecho de hacer cesar la indivisión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0c01d6c3-6927-4717-9e83-b3502675dec7', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '366', NULL, 343, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9eba1c9a-e36e-4aff-a1ed-be62b91d03c2', '0c01d6c3-6927-4717-9e83-b3502675dec7', 1, 'Cuando el patrimonio se extinga por expropiación del inmueble, la indemnización respectiva se depositará en una institución bancaria mientras se constituye un nuevo patrimonio familiar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c382f6c5-d66d-4225-8251-6b493b1bb9d7', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '367', NULL, 344, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('39fa79bc-89f9-4628-a0fe-1858dd87c077', 'c382f6c5-d66d-4225-8251-6b493b1bb9d7', 1, 'Puede disminuirse el valor del patrimonio familiar cuando por causas posteriores a su establecimiento, ha sobrepasado la cantidad fijada como máxima, o porque sea de utilidad y necesidad para la familia dicha disminución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d658137-d676-4373-8650-2eb309db003c', 'a0000000-0000-0000-0000-000000000001', 'f202efc0-d933-49fa-918b-57d685e0148f', '368', NULL, 345, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4742545f-b3e7-45fd-8e9d-526a89dffdb8', '4d658137-d676-4373-8650-2eb309db003c', 1, 'El Ministerio Público intervendrá en la constitución, extinción y redacción del patrimonio familiar.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('024bf0b4-67ef-4dba-9014-bc65036c2d07', '4d658137-d676-4373-8650-2eb309db003c', 2, 'DEL REGISTRO CIVIL');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bed10da-17a4-4ff1-b5cf-732f743b53be', '4d658137-d676-4373-8650-2eb309db003c', 3, 'PARRAFO I Disposiciones generales');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b31fe1c2-c1e1-42a5-97bd-4f5f2b6789eb', '4d658137-d676-4373-8650-2eb309db003c', 4, 'ARTICULOS 369 al 437 15 DEROGADOS.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('006fd22f-82b6-4cc6-953c-29dab4c19cec', '4d658137-d676-4373-8650-2eb309db003c', 5, 'PARRAFO IX Registro de personas jurídicas');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3eef266e-f858-493c-964d-b72d2ec18998', 'a0000000-0000-0000-0000-000000000001', '9e460e57-7f3c-47f3-832d-6caa735bbd18', '438', NULL, 346, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91c03f99-7a8f-4f39-92cc-1554fadb3d45', '3eef266e-f858-493c-964d-b72d2ec18998', 1, 'En el libro especial de Registro de Personas Jurídicas se hará la inscripción de las comprendidas en los incisos 3º y 4º y párrafo final del artículo 15 de este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a3534e2-9417-4e34-b298-5c5edfa0bc3b', 'a0000000-0000-0000-0000-000000000001', '9e460e57-7f3c-47f3-832d-6caa735bbd18', '439', NULL, 347, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c1ecd379-9774-4056-8b46-1a3104a7e1ad', '3a3534e2-9417-4e34-b298-5c5edfa0bc3b', 1, 'La inscripción se hará con presencia del testimonio de la escritura pública en que se constituya la persona jurídica, debiéndose dar cumplimiento a los requisitos que establece el tratado de sociedades en el Código respectivo. Con la escritura debe acompañarse una copia de la misma en papel sellado del menor valor, que quedará archivada, devolviéndose el testimonio de la escritura con la razón de haber quedado inscrita la persona jurídica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('19f1afcd-f7e0-49d6-8778-8feab027bceb', 'a0000000-0000-0000-0000-000000000001', '9e460e57-7f3c-47f3-832d-6caa735bbd18', '440', NULL, 348, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f677754-b53f-4731-a51c-6a223e019ae1', '19f1afcd-f7e0-49d6-8778-8feab027bceb', 1, 'Las asociaciones que menciona el inciso 3º del citado artículo 15, presentarán para su inscripción, copia simple certificada de sus estatutos o reglamento y el acuerdo de su aprobación y del reconocimiento de su personalidad jurídica documentos que quedarán en poder del Registro.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91ceab54-97b4-488e-a94e-5bdfdfb97d3e', '19f1afcd-f7e0-49d6-8778-8feab027bceb', 2, 'PARRAFO X Disposición General');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bbd513ab-0214-48e9-b98a-9dba01850da0', 'a0000000-0000-0000-0000-000000000001', '9e460e57-7f3c-47f3-832d-6caa735bbd18', '441.16', NULL, 349, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('630ee690-d4c0-4009-b604-2c2b96dc91e7', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 1, 'DEROGADO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40194f94-8441-4041-ae0c-fa9466e7526d', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 2, '15 Derogado los artículos 369 al 437, a partir del treinta de septiembre de dos mil ocho, por el Artículo 103, Decreto No. 90-2005 publicado en el Diario de Centro América el 20 de febrero de 2006.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf31ec5b-5ef7-4715-a40a-f8c7cb593365', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 3, '16 Derogado a partir del treinta de septiembre de dos mil ocho, por el Artículo 103, Decreto No. 90-2005 publicado en el Diario de Centro América el 20 de febrero de 2006.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2658ca03-4e4c-44a7-a2b7-be2994b1f7aa', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 4, 'DE LOS BIENES DE LA PROPIEDAD Y DEMAS DERECHOS REALES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('631ecf9e-b3af-443c-9c7b-98c78f06a2ae', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 5, 'DE LOS BIENES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ff96059-bd28-4a6a-9c72-8017edad56d2', 'bbd513ab-0214-48e9-b98a-9dba01850da0', 6, 'DE LAS VARIAS CLASES DE BIENES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d8edc4ba-fd5e-4832-a84e-29410f007b40', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '442', 'Concepto', 350, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8603034a-e09f-432b-9676-76c82090884a', 'd8edc4ba-fd5e-4832-a84e-29410f007b40', 1, 'Son bienes las cosas que son o pueden ser objeto de apropiación, y se clasifican en inmuebles y muebles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('037aa7b7-5284-4144-8171-f6178d11eba2', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '443', 'Cosas apropiables', 351, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a2162c2-71bd-47f8-acef-8edf39c97959', '037aa7b7-5284-4144-8171-f6178d11eba2', 1, 'Pueden ser objeto de apropiación todas las cosas que no estén excluidas del comercio por su naturaleza o por disposición de la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8153859a-bc51-496c-9cd6-c27794795d51', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '444', 'Cosas fuera del comercio', 352, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d37ede5e-9804-445e-a302-4096c883a866', '8153859a-bc51-496c-9cd6-c27794795d51', 1, 'Están fuera del comercio por su naturaleza, las que no pueden ser poseídas exclusivamente por ninguna persona, y por disposición de la ley, las que ella declara irreductibles a propiedad particular.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('750298e2-8ef9-42fa-90c1-25fa5bc492f4', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '445', 'Bienes inmuebles', 353, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a37bb3ef-8844-4d5e-937d-c8bbe215706b', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 1, 'Son bienes inmuebles: 1. El suelo, el subsuelo, el espacio aéreo, las minas mientras no sean extraídas, y las aguas que se encuentren en la superficie o dentro de la tierra;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e30db083-3a0c-43b3-8a50-ba46cf8d47f7', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 2, '2. Los árboles y plantas mientras estén unidos a la tierra, y los frutos no cosechados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d3d293c-7b7e-4b5b-b807-32fed04aa18c', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 3, '3. Las construcciones adheridas al suelo de manera fija y permanente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5feb0b0c-fa6f-4054-ae2c-a379fdac8881', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 4, '4. Las cañerías conductoras de agua, gas o electricidad, Incorporadas al inmueble;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('63b16ed1-8128-46e4-86a2-20526dcb369c', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 5, '5. Los ferrocarriles y sus vías; las líneas telegráficas y telefónicas, y las estaciones radiotelegráficas fijas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8eedc421-f7f9-46bf-8143-7c027ae18b2f', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 6, '6. Los muelles, y los diques y construcciones que, aun cuando sean flotantes, estén destinados por su objeto y condiciones a permanecer en un punto fijo de un río, lago o costa; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cab614d5-6357-452f-acec-5112b5d42012', '750298e2-8ef9-42fa-90c1-25fa5bc492f4', 7, '7. Los viveros de animales, palomares, colmenares, estanques de peces o criaderos análogos, cuando el propietario los haya colocado o los conserve con el propósito de mantenerlos unidos de modo permanente a la finca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0bdc6782-2597-4ce8-a2cd-dbe039706cfd', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '446', 'Se reputan bienes inmuebles', 354, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d951b620-7631-44e5-b07e-2d1b17e22aa8', '0bdc6782-2597-4ce8-a2cd-dbe039706cfd', 1, 'Se consideran inmuebles para los efectos legales, los derechos reales sobre inmuebles y las acciones que los aseguran.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('718dd5f9-48f3-4a41-861a-b3d111ca9132', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '447', 'Parte integrante', 355, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bdb6fdb8-c95c-4891-89b6-58484da6cab2', '718dd5f9-48f3-4a41-861a-b3d111ca9132', 1, 'Es parte integrante de un bien lo que no puede ser separado sin destruir, deteriorar o alterar el mismo bien.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c34a37a-562e-49fc-9363-dc1d33cd4be3', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '448', 'Materiales de un edificio', 356, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4ea3748-78cc-4b26-bd3b-e59c4faade99', '1c34a37a-562e-49fc-9363-dc1d33cd4be3', 1, 'No pierden el carácter de parte integrante de un edificio los materiales que se han separado mientras se hacen reparaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('415f7b75-5e4a-4f37-84ed-5f25a873d71d', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '449', 'Accesorios', 357, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1368c007-06ed-4bc7-80b3-8cbe8ff8542b', '415f7b75-5e4a-4f37-84ed-5f25a873d71d', 1, 'Es accesorio del bien todo lo que está aplicado permanentemente a su fin económico y se halla en una relación que responde a ese fin. La separación temporal de los bienes no les hace perder su calidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e86ae305-aead-403a-ac61-56ee8e42b7ab', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '450', 'Condición de integrantes y accesorios', 358, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('318b38f0-9262-49aa-91c1-1f01aa15bbee', 'e86ae305-aead-403a-ac61-56ee8e42b7ab', 1, 'Las partes integrantes y los accesorios de un bien siguen la condición de éste, salvo los casos en que la ley o el contrato permitan su diferenciación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca2836c6-4d81-4119-bf73-6c5cad176685', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '451', 'Bienes muebles', 359, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b1f2140a-b9d8-4b69-83a0-5f52ef2cb9c0', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 1, 'Son bienes muebles: 1. Los bienes que pueden trasladarse de un lugar a otro, sin menoscabo de ellos mismos ni del inmueble donde estén colocados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7a10213-550f-4893-ae59-7558fd9c6502', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 2, '2. Las construcciones en terreno ajeno, hechas para un fin temporal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f75b4ba3-7581-4e61-a6df-7694296e3040', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 3, '3. Las fuerzas naturales susceptibles de apropiación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05738d76-8c76-40ba-8204-605225f17a70', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 4, '4. Las acciones o cuotas y obligaciones de las sociedades accionadas, aun cuando estén constituidas para adquirir inmuebles, o para la edificación u otro comercio sobre esta clase de bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('124a1409-228a-4fd9-a303-e7c69a8aca4f', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 5, '5. Los derechos de crédito referentes a muebles, dinero o servicios personales, y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98da1249-ddab-442b-aa0a-094069c0b8c6', 'ca2836c6-4d81-4119-bf73-6c5cad176685', 6, '6. Los derechos de autor o inventor comprendidos en la propiedad literaria, artística e industrial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a0030d9-377f-43dc-9fb6-c8ae36a9ab5c', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '452', 'Menaje de casa', 360, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3992f14d-eb49-4245-91dd-e22fa69f9774', '3a0030d9-377f-43dc-9fb6-c8ae36a9ab5c', 1, 'Cuando se use de las palabras muebles o bienes muebles de una casa, se comprenderán los que sirven exclusiva y propiamente para el uso ordinario de una familia, según las circunstancias de las personas que la integran. En consecuencia, no se comprenderán los libros, dinero, joyas, documentos, papeles de crédito, medallas, armas, instrumentos de artes y oficios, ropas, granos y animales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ad45150-b46f-475d-b9ba-fda1b846cb6d', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '453', NULL, 361, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e169bcce-358f-4345-92ff-a274f7d24913', '0ad45150-b46f-475d-b9ba-fda1b846cb6d', 1, 'Los materiales provenientes de la destrucción de un edificio que no sean utilizados en reparaciones del mismo y los reunidos para la construcción de uno nuevo, son muebles mientras no estén empleados en la construcción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5608e054-6cd7-4b24-8833-65158f9eb907', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '454', 'Bienes fungibles', 362, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c56e5b85-c594-4309-83aa-5691ad19ab04', '5608e054-6cd7-4b24-8833-65158f9eb907', 1, 'Los bienes muebles son fungibles si pueden ser sustituidos por otros de la misma especie, calidad y cantidad; y no fungibles los que no pueden ser reemplazados por otros de las mismas cualidades.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c7df057-434d-414a-9053-ed8bf2f2ae79', 'a0000000-0000-0000-0000-000000000001', 'a36f1566-042b-486b-a0ec-7792ff1e157c', '455', 'Semovientes', 363, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('75fa1f4d-99ca-4702-b981-a1e1595ed4f8', '1c7df057-434d-414a-9053-ed8bf2f2ae79', 1, 'Los semovientes son bienes muebles; pero los animales puestos al servicio de la explotación de una finca, se reputan como inmuebles.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('acd7c6bd-c1f7-44c5-873a-d27a88852d9f', '1c7df057-434d-414a-9053-ed8bf2f2ae79', 2, 'DE LOS BIENES CON RELACION A LAS PERSONAS A QUIENES PERTENECEN');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e052546-77f9-483c-afdc-fe8c8be24469', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '456', 'Dominio de los bienes', 364, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46e9e442-a3b4-42d9-a444-79979b71bb9d', '8e052546-77f9-483c-afdc-fe8c8be24469', 1, 'Los bienes son del dominio del poder público o de propiedad de los particulares.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('884846ee-381f-4f39-9c31-af8e755e1eb9', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '457', 'Bienes del dominio público', 365, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0fd61b6d-68e5-4c6d-b9ef-222926fdbaa2', '884846ee-381f-4f39-9c31-af8e755e1eb9', 1, 'Los bienes del dominio del poder público pertenecen al Estado o a los municipios y se dividen en bienes de uso público común y de uso especial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c95f1fa9-3999-4bde-954e-98a42f3a0140', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '458', 'Bienes nacionales de uso común', 366, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b56ef39-79ee-4357-b5a0-3527406e7492', 'c95f1fa9-3999-4bde-954e-98a42f3a0140', 1, 'Son bienes nacionales de uso público común: 1. Las calles, parques, plazas, caminos y puentes que no sean de propiedad privada,');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bafb2417-86b5-445f-a10a-21095eba9135', 'c95f1fa9-3999-4bde-954e-98a42f3a0140', 2, '2. Los puertos, muelles, embarcaderos, pontones y demás obras de aprovechamiento general, construidos o adquiridos por el Estado o las municipalidades;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c18f1827-2293-419d-a32c-2ad1e201fbcb', 'c95f1fa9-3999-4bde-954e-98a42f3a0140', 3, '3. Las aguas de la zona marítima territorial en la extensión y términos que fije la ley respectiva; los lagos y ríos navegables y flotables y sus riberas, los ríos, vertientes y arroyos que sirven de límite al territorio nacional; las caídas y nacimientos de agua de aprovechamiento industrial, en la forma que establece la ley de la materia; y las aguas no aprovechadas por particulares; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3f8ad81-5210-44bd-bed7-0529903f547c', 'c95f1fa9-3999-4bde-954e-98a42f3a0140', 4, '4. La zona marítimo-terrestre de la República, la plataforma continental, el espacio aéreo y la estratosfera en la extensión y forma que determina la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('709b206d-5642-48d0-bf1f-b3ea571427f0', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '459', 'Bienes nacionales de uso no común', 367, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff7bb670-93b2-4714-86db-2906227a7f74', '709b206d-5642-48d0-bf1f-b3ea571427f0', 1, 'Son bienes nacionales de uso no común: 1. Los que están destinados al servicio del Estado, de las municipalidades y de las entidades estatales descentralizadas, y los demás que constituyen su patrimonio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34dcd161-6eb1-4145-b234-4dba236c6e68', '709b206d-5642-48d0-bf1f-b3ea571427f0', 2, '2. Los de uso público, cuando dejen de serlo de hecho o por virtud de una ley;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('654f8c4f-fb36-43a6-96fd-1c0772a4ddfb', '709b206d-5642-48d0-bf1f-b3ea571427f0', 3, '3. Los ingresos fiscales y municipales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77b9065d-8a72-40c6-91c5-d0c86365d2c4', '709b206d-5642-48d0-bf1f-b3ea571427f0', 4, '4. El subsuelo, los yacimientos de hidrocarburos y los minerales antes de ser extraídos, así como cualquiera otra sustancia orgánica o inorgánica del subsuelo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('68372ca5-cd10-47cd-856a-bcd2f822ba27', '709b206d-5642-48d0-bf1f-b3ea571427f0', 5, '5. Los terrenos baldíos y las tierras que no sean de propiedad privada;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('924cc85e-b34f-4376-aadf-576f77781287', '709b206d-5642-48d0-bf1f-b3ea571427f0', 6, '6. Los que habiendo sido de propiedad particular queden vacantes, y los que adquieran el Estado o las municipalidades por cualquier título legal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7ba3615-47c8-4f84-b4c3-6db4cd3fc7ab', '709b206d-5642-48d0-bf1f-b3ea571427f0', 7, '7. Los excesos de propiedades rústicas o urbanas, de conformidad con la ley; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35d6b146-9077-4ef7-9222-4918f9123b7d', '709b206d-5642-48d0-bf1f-b3ea571427f0', 8, '8. Los monumentos y las reliquias arqueológicas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ab5a786-15db-4407-b08a-b0c8c2f70c8b', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '460', 'Bienes de propiedad privada', 368, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8dcff532-7e23-438f-a31c-03057beab5ca', '0ab5a786-15db-4407-b08a-b0c8c2f70c8b', 1, 'Son bienes de propiedad privada los de las personas individuales o jurídicas que tienen título legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b16595b-5513-456f-9806-a6a2b9cfa0d3', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '461', 'Aprovechamientos de bienes nacionales', 369, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7efdb58f-d8d0-4539-b8eb-769381cac3e7', '7b16595b-5513-456f-9806-a6a2b9cfa0d3', 1, 'Los bienes de uso común son inalienables e imprescriptibles. Pueden aprovecharse de ellos todos los habitantes, con las restricciones establecidas por la ley, pero para aprovechamientos especiales se necesita concesión otorgada con los requisitos que establecen las leyes respectivas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a4a4461c-b03d-41e7-9a17-66b3647e1d02', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '462', NULL, 370, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57a51b73-7566-4208-9fd0-d75f87a482bc', 'a4a4461c-b03d-41e7-9a17-66b3647e1d02', 1, 'Los bienes que constituyen el patrimonio del Estado, de los municipios y de las entidades estatales descentralizadas, están sujetos a las leyes especiales y subsidiariamente a lo dispuesto en este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33689b16-11fa-494e-b25a-fb18c45cfde2', 'a0000000-0000-0000-0000-000000000001', 'e9b9edb8-939d-41d3-9b37-4a1742cb454e', '463', NULL, 371, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f49bf486-b317-43cc-8186-7fd28f5584ec', '33689b16-11fa-494e-b25a-fb18c45cfde2', 1, 'El traspaso de los bienes del dominio público de uso común al patrimonio del Estado o de los municipios, deberá hacerse llenándose los trámites que señalan las leyes y reglamentos respectivos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f6c06fd-de4b-450f-827a-427e75b2a4e8', '33689b16-11fa-494e-b25a-fb18c45cfde2', 2, 'DE LA PROPIEDAD');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2d41b23-a25f-4fda-bb69-9ec678ed5ffc', '33689b16-11fa-494e-b25a-fb18c45cfde2', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6f37790f-f870-4961-90d7-e0fc4c40363e', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '464', 'Contenido del derecho de propiedad', 372, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a1f7ef6-cb64-426e-ad06-b1b879ac1fa1', '6f37790f-f870-4961-90d7-e0fc4c40363e', 1, 'La propiedad es el derecho de gozar y disponer de los bienes dentro de los límites y con la observancia de las obligaciones que establecen las leyes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fcaacd3a-2241-4c45-a0cc-e6a5b5f6f282', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '465', 'Abuso del derecho', 373, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('73a74431-74bb-44d0-a5e9-5decce35229e', 'fcaacd3a-2241-4c45-a0cc-e6a5b5f6f282', 1, 'El propietario, en ejercicio de su derecho, no puede realizar actos que causen perjuicio a otras personas y especialmente en sus trabajos de explotación industrial, está obligado a abstenerse de todo exceso lesivo a la propiedad del vecino.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b882ca47-f243-432e-9536-e8d89b79fae2', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '466', 'Derecho del perjudicado', 374, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6924ac9c-e74f-4479-9d5f-4decd6c60e30', 'b882ca47-f243-432e-9536-e8d89b79fae2', 1, 'El que sufre o está amenazado con un daño porque otro se exceda o abusa en el ejercicio de su derecho de propiedad, puede exigir que se restituya al estado anterior, o que se adopten las medidas del caso, sin perjuicio de la indemnización por el daño sufrido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d2a8c84-68bb-4cee-a344-8669647d93d0', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '467', 'Expropiación forzosa', 375, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f0e0c16-39ca-4c17-b0ae-e93bbc4db95a', '4d2a8c84-68bb-4cee-a344-8669647d93d0', 1, 'La propiedad puede ser expropiada por razones de utilidad colectiva, beneficio social o interés público, previa indemnización determinada de conformidad con la ley de la materia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('312878f3-4f0a-4480-b296-684ea0423237', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '468', 'Defensa de la propiedad', 376, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5280e46e-def6-473e-9b17-2e8e75928c6b', '312878f3-4f0a-4480-b296-684ea0423237', 1, 'El propietario tiene derecho de defender su propiedad por los medios legales y de no ser perturbado en ella, si antes no ha sido citado, oído y vencido en juicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61300086-74c0-469d-99c1-835096adc3e9', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '469', 'Reivindicación', 377, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57fcf695-ccdc-4946-8331-aea328b07d46', '61300086-74c0-469d-99c1-835096adc3e9', 1, 'El propietario de una cosa tiene el derecho de reivindicarla de cualquier poseedor o detentador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e003c89-50be-4c74-a351-41a91c2b7fab', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '470', 'Derecho de autor', 378, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7e9c610-9ff9-49ad-a203-3adf7ac5f770', '3e003c89-50be-4c74-a351-41a91c2b7fab', 1, 'El producto o valor de trabajo o industria lícitos, así como las producciones del ingenio o del talento de cualquiera persona, son propiedad suya y se rigen por las leyes relativas a la propiedad en general y por las especiales sobre estas materias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8027e339-aa73-4f06-a9eb-c92bf2eb104e', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '471', 'Frutos de los bienes', 379, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52f3d83d-c380-44a3-a1b4-6f05907e4e25', '8027e339-aa73-4f06-a9eb-c92bf2eb104e', 1, 'El propietario de un bien tiene derecho a sus frutos y a cuanto se incorpora por accesión, de conformidad con lo dispuesto en el capítulo respectivo de este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a7875fe0-a3e1-4ede-b3ff-e7a6b7101cc7', 'a0000000-0000-0000-0000-000000000001', '8b4a1aea-02cb-411e-86c8-131b54d7549d', '472', 'Bienes de interés histórico y artístico', 380, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77d21076-113d-4606-a09c-a3eaac28e998', 'a7875fe0-a3e1-4ede-b3ff-e7a6b7101cc7', 1, 'Las cosas de propiedad privada, inmuebles y muebles, declaradas como objetos de interés artístico, histórico o arqueológico, están sometidas a leyes especiales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c141797-8f73-48a3-be9b-aae99a345fd0', 'a7875fe0-a3e1-4ede-b3ff-e7a6b7101cc7', 2, 'DE LAS LIMITACIONES DE LA PROPIEDAD');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0de42cad-9b58-4823-9cdd-59aa298f7103', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '473', 'Subsuelo y sobresuelo', 381, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d4b04b65-087c-4466-8f91-f5cd92aabee1', '0de42cad-9b58-4823-9cdd-59aa298f7103', 1, 'La propiedad del predio se extiende al subsuelo y al sobresuelo, hasta donde sea útil al propietario, salvo disposiciones de leyes especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0bb44099-53dd-443c-bbc6-780037fd5271', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '474', 'Prohibición de hacer excavaciones que dañen al vecino', 382, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64f22f51-f1c2-4708-8d25-84dcd329f1bf', '0bb44099-53dd-443c-bbc6-780037fd5271', 1, 'En un predio no pueden hacerse excavaciones o construcciones que debiliten el suelo de la propiedad vecina, sin que se hagan las obras de consolidación indispensables para evitar todo daño ulterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('690c0385-eb6b-48d1-b547-0a7c2ae22757', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '475', 'Deslinde y amojonamiento', 383, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f14cd6d-7699-4dff-8093-2684641727da', '690c0385-eb6b-48d1-b547-0a7c2ae22757', 1, 'Todo propietario tiene derecho de obligar a los vecinos propietarios o poseedores, al deslinde y al amojonamiento; y según la costumbre del lugar y la clase de propiedad, a construir y a mantener a prorrata las obras que los separen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef6bd381-7b58-4358-b24c-93328927a750', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '476', 'Obligación de cerrar el fundo', 384, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ec73340-c9bc-4348-b0e5-2d20c7535169', 'ef6bd381-7b58-4358-b24c-93328927a750', 1, 'Todo propietario debe cerrar su fundo, del modo que lo estime conveniente o lo dispongan las leyes y reglamentos municipales, salvo los derechos de servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a4c064a-6ea2-433c-a805-32d535272bb1', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '477', 'Construcciones cerca de edificios públicos', 385, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ef54c69-0542-49eb-8149-2fd8222810dc', '6a4c064a-6ea2-433c-a805-32d535272bb1', 1, 'Nadie puede edificar ni plantar cerca de las plazas fuertes, fortalezas y edificios públicos, sino sujetándose a las condiciones exigidas en los reglamentos respectivos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aca3173a-f5c3-4c2f-935d-4b8884165b94', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '478', 'Servidumbres establecidas', 386, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e9a374f-bf80-465a-8bcd-6a873386913c', 'aca3173a-f5c3-4c2f-935d-4b8884165b94', 1, 'Las servidumbres establecidas por utilidad pública o comunal respecto de construcciones o plantaciones, para mantener expedita la navegación de los ríos o la construcción o separación de las vías públicas o para las demás obras comunales de esta clase, se determinan y resuelven por leyes y reglamentos especiales; y a falta de éstos, por las reglas establecidas en este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8f1c5a0e-40f4-45b4-a09b-4cd5f21fb2c5', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '479', 'Construcciones no permitidas', 387, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc766be3-ef27-4291-92c4-4cc2429de1eb', '8f1c5a0e-40f4-45b4-a09b-4cd5f21fb2c5', 1, 'Nadie puede construir a menos de dos metros de distancia de una pared ajena o medianera, aljibes, pozos, cloacas, letrinas, acueductos, hornos, fraguas, chimeneas, establos ni depósitos de agua ni de materias corrosivas, sin construir las obras de resguardo necesarias, y con sujeción a cuantas condiciones se prevengan en los reglamentos de policía y de sanidad. Dentro de poblado se prohíbe depositar materias inflamables o explosivas, salvo que lo establezcan reglamentos especiales; e instalar máquinas y fábricas para trabajos industriales que sean peligrosos, nocivos o molestos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('58bfe5c8-4f69-4084-9aef-c90a766d80ac', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '480', 'Prohibición de actos que dañen pared medianera', 388, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52d6ec68-2f46-45cf-a984-83944000ea06', '58bfe5c8-4f69-4084-9aef-c90a766d80ac', 1, 'No se puede poner contra una pared medianera que divida dos predios de distinto dueño, ninguna acumulación de basura, tierra, estiércol u otras materias que puedan dañar la salubridad de las personas y la solidez y seguridad de los edificios. Tanto en estos casos como en los enunciados en el artículo anterior, a falta de reglamentos generales o locales, se ocurrirá a un juicio pericial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1d472249-bec3-4231-afb6-2e7000c8c47e', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '481', 'Siembra de árboles cerca de heredad ajena', 389, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5979c82e-5c61-4c22-925e-8245a991e169', '1d472249-bec3-4231-afb6-2e7000c8c47e', 1, 'No se debe plantar árboles cerca de una heredad ajena, sino a distancia no menor de tres metros de la línea divisoria, si la plantación se hace de árboles grandes, y de un metro si la plantación es de arbustos o árboles pequeños.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c02cf882-08c6-47c1-a8d2-d206ace5f65d', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '482', 'Derecho de exigir que se arranquen los árboles', 390, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('24518c54-c476-42fc-9065-450802b7884d', 'c02cf882-08c6-47c1-a8d2-d206ace5f65d', 1, 'Todo propietario puede pedir que se arranquen los árboles que existan a mayor distancia de la señalada en el artículo que precede, si por la extensión de sus raíces amenazaren la seguridad de sus construcciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ea783071-2090-4ebb-8dbf-4afa6fdbc802', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '483', 'Ramas que se caen sobre propiedad vecina', 391, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5fe7433-0c15-46ee-a0fa-04f06a8965bb', 'ea783071-2090-4ebb-8dbf-4afa6fdbc802', 1, 'Si las ramas de los árboles se extienden sobre alguna heredad, jardines o patios vecinos, el dueño de éstos tendrá derecho de reclamar que se corten en cuanto se extiendan sobre sus propiedades.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5ee90f7-ec91-44c3-b5c5-8648778509f3', 'ea783071-2090-4ebb-8dbf-4afa6fdbc802', 2, 'Los frutos de las ramas que se extienden sobre el predio del vecino pertenecen a éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec40aa6f-74a4-41c8-b106-8073c0fbc138', 'a0000000-0000-0000-0000-000000000001', '3f07b5c6-3c7b-4380-a4df-502f25e5c22b', '484', 'Obra peligrosa', 392, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2140be2-6e03-401c-b04b-872305e9804b', 'ec40aa6f-74a4-41c8-b106-8073c0fbc138', 1, 'Si un edificio o pared amenazare peligro, podrá el propietario ser obligado a su demolición o a ejecutar las obras necesarias para evitarlo. Si no cumpliere el propietario, la autoridad podrá hacerlo demoler a costa de éste. Lo mismo se observará cuando algún árbol amenazare caerse.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b1bc846-c7b4-40ac-bd4e-203cef710f21', 'ec40aa6f-74a4-41c8-b106-8073c0fbc138', 2, 'DE LA COPROPIEDAD');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('752d1b99-a42f-496f-9ca7-c794b2f5924e', 'ec40aa6f-74a4-41c8-b106-8073c0fbc138', 3, 'PARRAFO I Disposiciones generales');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('653614bf-7878-4cef-a970-e4251a8b094b', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '485', 'Cuándo hay copropiedad', 393, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db8a6df7-fce3-4f2a-bcb3-3d13b18a0b2f', '653614bf-7878-4cef-a970-e4251a8b094b', 1, 'Hay copropiedad cuando un bien o un derecho pertenece pro indiviso a varias personas. A falta de contrato o disposición especial, se regirá la copropiedad por las disposiciones del presente capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('00df7312-89e9-4df1-b141-1097489614a7', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '486', 'Cuotas de los partícipes', 394, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19a05732-0edd-446c-b780-190706ca581a', '00df7312-89e9-4df1-b141-1097489614a7', 1, 'Las cuotas de los copartícipes se presumen iguales. El concurso de los comuneros, tanto en los beneficios como en las cargas de la comunidad, será proporcional a sus respectivas cuotas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('495506a4-d97c-4067-9160-6a6772742eb5', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '487', 'Uso de la cosa común', 395, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0a21cf0-c287-44b0-87a4-ad25e5a34c60', '495506a4-d97c-4067-9160-6a6772742eb5', 1, 'Cada partícipe podrá servirse de las cosas comunes, siempre que disponga de ellas conforme a su destino y de manera que no perjudique el interés de la comunidad ni impida a los copropietarios usarla según su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('be913a84-faaf-4895-abde-048d5fec11c0', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '488', 'Obligaciones de los comuneros', 396, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc2e28de-3e18-47c0-9a63-2d229dbac4bd', 'be913a84-faaf-4895-abde-048d5fec11c0', 1, 'Cada partícipe debe contribuir a los gastos necesarios para la conservación de la cosa común, salvo la facultad de liberarse de esta obligación con la renuncia de la parte que le corresponde en el dominio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('529c5947-7961-4ec2-8499-10eeb188d913', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '489', 'Innovaciones', 397, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('90ca976a-85cc-4037-9064-c73fb4986547', '529c5947-7961-4ec2-8499-10eeb188d913', 1, 'Ninguno de los condueños podrá, sin el consentimiento de los demás, hacer alteraciones que modifiquen la cosa común, aunque de ellas pudieran resultar ventajas para todos, a no ser que fueren aprobadas por la mayoría de los copropietarios que represente por lo menos las dos terceras partes del valor total de la misma.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('522a29db-7cfa-4fc2-a91a-3e4d7f97a1f2', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '490', 'Administración', 398, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('75d40572-05bc-4c7c-9e36-00e778c74dc3', '522a29db-7cfa-4fc2-a91a-3e4d7f97a1f2', 1, 'Para la administración del bien común, serán obligatorios los acuerdos de la mayoría de los partícipes, que represente por lo menos las dos terceras partes del valor total de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b23d677c-ed57-4595-bf32-386423ffa331', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '491', 'Derecho de cada condueño', 399, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6c3d735-4cfa-4705-9211-1a8d0ffec6a4', 'b23d677c-ed57-4595-bf32-386423ffa331', 1, 'Todo condueño tiene la plena propiedad de la parte alícuota que le corresponda y la de sus frutos y utilidades, pudiendo, en consecuencia, enajenarla, cederla o gravarla y aun ceder únicamente su');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c0a1b9be-17e5-40c9-be92-5ed16434b537', 'b23d677c-ed57-4595-bf32-386423ffa331', 2, 'aprovechamiento, salvo si se tratare de derecho personal. Pero el efecto de la enajenación o gravamen con relación a los condueños, estará limitado a la porción que se le adjudique en la división al cesar la comunidad. Los condueños gozan del derecho de tanteo, que podrán ejercitar dentro de los quince días siguientes de haber sido notificados del contrato que se pretende celebrar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c614ac06-8584-47e5-8c65-ee2111656e27', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '492', 'Derecho de pedir la división', 400, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8d9c1ffc-3ca5-4d59-905a-76221b3031f5', 'c614ac06-8584-47e5-8c65-ee2111656e27', 1, 'Ningún copropietario estará obligado a permanecer en la comunidad. Cada uno de ellos podrá pedir en cualquier tiempo que se divida la cosa común, salvo los casos en que la indivisión esté establecida por la ley. Acordada la división, cada comunero tendrá derecho preferente a adquirir las partes de los otros si ellos quisieren venderlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ad2b488d-d86e-4702-8aeb-15ff4f192415', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '493', 'Pacto de indivisión', 401, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50b991c5-eb7d-460b-b87c-1e533bf5bb27', 'ad2b488d-d86e-4702-8aeb-15ff4f192415', 1, 'Será válido el pacto de conservar la cosa indivisa por tiempo determinado que no exceda de tres años, plazo que podrá prorrogarse por nueva convención. La autoridad judicial, sin embargo, cuando lo exijan graves y urgentes circunstancias, puede ordenar la división de la cosa común aun antes del tiempo convenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('354b1302-b194-44ab-a240-dbf43331fd37', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '494', 'Improcedencia de la división', 402, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4b851b8-2a88-42f2-a712-f109ffcd2bdf', '354b1302-b194-44ab-a240-dbf43331fd37', 1, 'Los copropietarios no podrán exigir la división de la cosa común, cuando de hacerla resulte inservible para el uso a que se destina. En este caso, si los condueños no convinieren en que se adjudique a uno de ellos indemnizando a los demás, se procederá a su venta y se repartirá su precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7e1519dd-9066-486e-abed-0a137a44b798', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '495', 'Deudas contraídas por un partícipe y por los comuneros', 403, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('80a5a2c1-e258-4f61-be20-26cf49b5d5b8', '7e1519dd-9066-486e-abed-0a137a44b798', 1, 'A las deudas contraídas en pro de la comunidad y durante ella, no está obligado sino el condominio que las contrajo, quien tendrá acción contra los otros para reembolso de lo que hubiere pagado. Si la deuda hubiere sido contraída por los comuneros colectivamente, sin expresión de cuotas y sin haberse estipulado solidaridad, están obligados al acreedor por partes iguales, salvo el derecho de cada uno contra los otros para que se le abone lo que haya pagado de más respecto a la cuota que le corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b10d558-b1af-45ed-9c6f-e93c06beecb1', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '496', 'Derecho de pedir el acotamiento de tierras', 404, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92238f2f-95ae-4cae-b79c-24b5c3320660', '8b10d558-b1af-45ed-9c6f-e93c06beecb1', 1, 'Cada uno de los comuneros en una tierra podrá pedir que se acote una parte proporcional a su cuota, para explotarla con labores agrícolas. Si los demás comuneros se negaren a concedérsela podrá acudir al juez local para que resuelva.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d32216cb-3180-41e9-8e7f-bd0e2f2305e5', '8b10d558-b1af-45ed-9c6f-e93c06beecb1', 2, 'Otorgada la parcela, los gastos y los frutos de ella pertenecerán exclusivamente al comunero que la haya obtenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d2f6b682-8123-4902-8300-46034365fa3f', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '497', 'Sanciones por distracción de fondos', 405, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3c53cfd9-29d8-466b-b705-98718a90a6b9', 'd2f6b682-8123-4902-8300-46034365fa3f', 1, 'Cada comunero debe a la comunidad lo que saca indebidamente de ella, incluidos los intereses legales del dinero común que haya empleado en sus propias atenciones, y responderá también de cualesquiera daños que haya causado en el bien común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2c874f07-eaa8-4d70-9335-b5928bcbcfc9', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '498', 'Derecho de tanteo', 406, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b30d7a4-6a37-4e95-8705-f7884fe29cdf', '2c874f07-eaa8-4d70-9335-b5928bcbcfc9', 1, 'Si se hubiere de poner en explotación todo o parte de la cosa común, cualquiera de los comuneros tendrá derecho preferente a obtenerla en igualdad de condiciones del que ofrezca la mejor propuesta. Si pidieren el arriendo dos o más comuneros y no lograren ponerse de acuerdo, se hará la adjudicación a todos ellos en proporción a sus respectivas cuotas en el condominio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b4897c7f-b84a-41ff-82bd-03807c266046', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '499', 'Derechos de los acreedores', 407, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('84ec1245-d78a-49c3-b2de-a5741483ac21', 'b4897c7f-b84a-41ff-82bd-03807c266046', 1, 'Los acreedores de uno o más condueños, tienen derecho para hacer embargar y vender la porción correspondiente a sus deudores, pero sin dividir por ello la cosa común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03dcb656-26f8-43aa-a835-3452f54d9a5f', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '500', NULL, 408, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f9b84ac7-675a-4052-99b5-36896f16f18d', '03dcb656-26f8-43aa-a835-3452f54d9a5f', 1, 'Aplicabilidad de las reglas de la participación de la herencia. Serán aplicables a la división entre los participes en la comunidad, las reglas concernientes a la partición de la herencia. Los comuneros quedan recíprocamente obligados al saneamiento en proporción a la parte de cada uno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('66fc5349-355c-468e-b465-7e3200f9df5f', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '501', 'Acreedores o cesionarios en la partición', 409, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ccf8b7fc-b10a-4d00-979e-9f036204482b', '66fc5349-355c-468e-b465-7e3200f9df5f', 1, 'Los acreedores o cesionarios de los partícipes podrán concurrir a la división de la cosa común y oponerse a que se verifique sin su concurso. Pero no podrán impugnar la división consumada, excepto en el caso de fraude o en el de haberse verificado sin su concurso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ad12b11-d6cb-4e40-9f0a-3f77f2b4f287', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '502', 'No hay perjuicio de tercero', 410, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8996f234-2ebf-486b-b7f8-8287ca53303d', '0ad12b11-d6cb-4e40-9f0a-3f77f2b4f287', 1, 'La división de la cosa común no perjudicará a tercero que hubiere inscrito su derecho antes de la partición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9fd03eab-2d9b-4f37-9cd7-af5a5b285a04', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '503', 'Cesa la copropiedad', 411, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('639aa885-8200-49a0-bf29-e08b8864772b', '9fd03eab-2d9b-4f37-9cd7-af5a5b285a04', 1, 'La copropiedad cesa por la división de la cosa común; por su pérdida, destrucción o enajenación; y por la consolidación o reunión de todas las cuotas en un solo copropietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('76067104-9ce2-4e5e-94e2-d11f848ceda8', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '504', 'Comunidad de tierras', 412, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91d35d0d-3473-43c4-be66-1a52b19a43ab', '76067104-9ce2-4e5e-94e2-d11f848ceda8', 1, 'Las formas de comunidad de tierras entre campesinos serán reguladas por las leyes agrarias.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7075aa68-4ffb-41cc-83a6-c482c2c6e12d', '76067104-9ce2-4e5e-94e2-d11f848ceda8', 2, 'PARRAFO II Copropiedad en la medianería de inmuebles');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bde034f2-fc5b-4345-83ac-2c3ad0d1b316', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '505', 'Medianería', 413, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14c170cc-e88a-4316-b7b5-07b9f6e35b16', 'bde034f2-fc5b-4345-83ac-2c3ad0d1b316', 1, 'Hay copropiedad en una pared, foso o cerca que sirve de límite y separación a dos propiedades contiguas; y mientras no haya prueba o signo exterior que demuestre lo contrario, se presume:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c92bc29-e70e-400d-b8f3-54b47ade9dd4', 'bde034f2-fc5b-4345-83ac-2c3ad0d1b316', 2, '1. En las paredes divisorias de los edificios contiguos, hasta el punto común de elevación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8bc2141c-08a4-499d-8282-2eba611c494f', 'bde034f2-fc5b-4345-83ac-2c3ad0d1b316', 3, '2. En las paredes divisorias de los jardines o corrales situados en poblado o en el campo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3219c28d-875d-4513-8d29-c175abedfb03', 'bde034f2-fc5b-4345-83ac-2c3ad0d1b316', 4, '3. En las cercas, vallados y setos vivos que dividen los predios rústicos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e1e7efbe-cd51-4035-8734-52c498303590', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '506', 'Signo contrario a la medianería', 414, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0e890eff-5e7e-49ef-9f5b-78ef0b4f9abb', 'e1e7efbe-cd51-4035-8734-52c498303590', 1, 'Hay signo contrario a la medianería: 1. Cuando hay ventanas o huecos abiertos en las paredes divisorias de los edificios;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ccc8667-2c5d-46ec-9d29-30225c97b777', 'e1e7efbe-cd51-4035-8734-52c498303590', 2, '2. Cuando conocidamente toda la pared, vallado o seto están construidos sobre el terreno de una de las fincas y no por mitad entre uno y otro de las dos contiguas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('866505e8-b7ba-4e89-b721-504fd6abefcd', 'e1e7efbe-cd51-4035-8734-52c498303590', 3, '3. Cuando la pared soporta las cargas de carreras, pisos y armaduras de una de las posesiones y no de la contigua;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1366b466-628c-41ec-a7d3-ca189027bcb0', 'e1e7efbe-cd51-4035-8734-52c498303590', 4, '4. Cuando la pared divisoria entre patios, jardines y otras heredades, están construidas de modo que la albardilla cae hacia una sola de las propiedades;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b8c82384-3391-44f0-99cd-a91bd102ef1c', 'e1e7efbe-cd51-4035-8734-52c498303590', 5, '5. Cuando la pared divisoria, construida de mampostería presenta piedras llamadas pasaderas, que de distancia en distancia salen de la superficie sólo por un lado de la pared y no por el otro;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7578f64-96d5-4d5f-ab8d-6a57ebb5261d', 'e1e7efbe-cd51-4035-8734-52c498303590', 6, '6. Cuando la pared fuere divisoria entre un edificio del cual forma parte y un jardín, campo, corral o sitio sin edificio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2799322-d89f-408f-a2c2-b1359db8d4c2', 'e1e7efbe-cd51-4035-8734-52c498303590', 7, '7. Cuando una heredad se halle cerrada o defendida por vallado, cerca, o setos vivos y las contiguas no lo estén;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('81139fd7-0e39-4f74-9dc7-dd3e688b3e6a', 'e1e7efbe-cd51-4035-8734-52c498303590', 8, '8. Cuando la cerca que cierra completamente una heredad es de distinta especie de la que tiene la vecina en sus lados contiguos a la primera; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5402905b-9895-4172-ac1d-9f800959d241', 'e1e7efbe-cd51-4035-8734-52c498303590', 9, '9. Cuando en las cercas de alambre de cualquier clase, el alambre esté clavado en los postes o setos vivos que lo sostienen, solamente del lado de una heredad y no del lado de la heredad contigua.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('55c3894b-25e0-44ff-9508-e516edbad134', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '507', 'Presunción en contra de la medianería', 415, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b15cb1e1-aff6-4076-b119-9a02863cb05d', '55c3894b-25e0-44ff-9508-e516edbad134', 1, 'En general se presume que en los casos señalados en el artículo anterior, la propiedad de las paredes, cercas, vallados o setos, pertenece exclusivamente al dueño de la finca o heredad que tiene a su favor aquellos signos exteriores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('468c0298-849d-4a8f-b22a-5125c05e8f04', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '508', 'Árboles medianeros', 416, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2329f96a-31ff-4b16-a1be-91ef6b191084', '468c0298-849d-4a8f-b22a-5125c05e8f04', 1, 'Los árboles que crecen en el seto medianero se reputan comunes, y cada uno de los propietarios tiene derecho a pedir que sean cortados, probando que de algún modo le dañan; pero si sirven de lindero o forman parte de una cerca, no deben cortarse ni substituirse sino de común acuerdo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cf2134f9-583c-4393-9d1d-5357af95a457', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '509', 'Presunción en cuanto a zanjas', 417, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f324ba16-2ed8-4337-9aef-a3e04ee17169', 'cf2134f9-583c-4393-9d1d-5357af95a457', 1, 'Las zanjas o acequias abiertas entre las heredades se presumen también medianeras, si no hay título o signo que demuestre lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca7d97a0-9040-4a8a-b7e5-105723290625', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '510', 'Presunción en cuanto a la tierra sacada de la zanja', 418, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef90b7a3-7091-4499-a051-8fa7216c5921', 'ca7d97a0-9040-4a8a-b7e5-105723290625', 1, 'Hay signo contrario a la medianería cuando la tierra o broza sacada de la zanja o acequia para abrirla o limpiarla se halla sólo de un lado; en este caso se presume que la propiedad de la zanja o acequia es exclusivamente del dueño de la heredad que tiene a su favor este signo exterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('277b49f1-20dd-4a36-b0c4-378db1027085', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '511', 'Cesa la presunción anterior', 419, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f081080c-a53d-425c-9156-acd38b18fdbc', '277b49f1-20dd-4a36-b0c4-378db1027085', 1, 'La presunción que establece el anterior artículo, cesa cuando la inclinación del terreno obliga a echar la tierra de un solo lado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ea8e761-c793-4f1a-b3dc-55bf786b1b56', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '512', 'Obligaciones de los condueños', 420, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae7f183a-1300-41a2-b887-3c2df1a2106e', '1ea8e761-c793-4f1a-b3dc-55bf786b1b56', 1, 'Los dueños de los predios están obligados a cuidar de que no se deterioren la pared, cerca, zanja o seto medianeros; y si por hecho propio o de alguno de sus dependientes o animales se deterioren, deben reponerlos, pagando los daños y perjuicios que se hubieren causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('70af83bc-ed7d-450e-9634-68009c8c3adc', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '513', 'Reparación y mantenimiento de construcciones medianeras', 421, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8bdda92d-9870-4274-a382-ca273d3ec165', '70af83bc-ed7d-450e-9634-68009c8c3adc', 1, 'La reparación y reconstrucción de las paredes medianeras y el mantenimiento de los vallados, cercas, setos vivos, zanjas o acequias, también medianeros, se costearán proporcionalmente por todos los dueños que tengan a su favor esta medianería.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5b18d35-33f9-4ef6-8524-45a169d02d5e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '514', 'Renuncia de la medianería', 422, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1fbe8de4-3009-47ed-806f-2cdb52affe75', 'b5b18d35-33f9-4ef6-8524-45a169d02d5e', 1, 'El propietario de un edificio que se apoya en una pared medianera, puede, al derribarlo, renunciar o no a la medianería. En el primer caso serán de su cuenta todos los gastos necesarios para evitar o reparar los daños que causen la demolición.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff2de14c-20ff-406c-95a2-a2c7c9548e21', 'b5b18d35-33f9-4ef6-8524-45a169d02d5e', 2, 'En el segundo, además de esta obligación, queda sujeto a las que imponen los artículos 512 y 513.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('15a6d15a-a080-4eca-b6df-6c140eda43b9', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '515', 'Contrato para adquirir la medianería', 423, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb2a89f8-f079-46c7-beeb-da22956b2547', '15a6d15a-a080-4eca-b6df-6c140eda43b9', 1, 'El propietario de una finca contigua a una pared divisoria no medianera, sólo puede darle este carácter en todo o en parte, por contrato con el dueño de ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f2b99655-d194-45d6-bc2b-a275210d324a', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '516', 'Derecho de alzar la pared medianera', 424, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d67d7e9c-1f20-4059-a089-601030e7718a', 'f2b99655-d194-45d6-bc2b-a275210d324a', 1, 'Todo propietario puede alzar la pared medianera haciéndolo a sus expensas e indemnizando de los perjuicios que se ocasionen por la obra, aunque sean temporales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d33fafce-1158-489c-ad9a-d488db93b1fd', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '517', 'Limitación de la medianería', 425, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c55e2d99-0c82-46bb-b978-8c70d390715c', 'd33fafce-1158-489c-ad9a-d488db93b1fd', 1, 'Mientras el dueño de la pared divisoria tenga a su favor una servidumbre de luz o de vista, el dueño del predio vecino sólo podrá adquirir la medianería hasta la altura de la parte inferior de las ventanas o huecos que constituyen el signo exterior de la servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('feab7975-3c44-4c5c-a29e-c524c6c43a42', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '518', 'Obras a cargo del dueño que haya alzado la pared', 426, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f241a7c-1314-466c-a073-b72a6fea8bea', 'feab7975-3c44-4c5c-a29e-c524c6c43a42', 1, 'Serán igualmente de cuenta del dueño de la pared, todas las obras de conservación, en la parte que éste haya aumentado de altura o de espesor y las que en la parte medianera sean necesarias, siempre que el deterioro provenga de la mayor altura o espesor que se haya dado a la pared.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('001e8f4d-6450-43a4-bb33-ec6d94a3febf', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '519', 'Obligación de reconstruir la pared', 427, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d331417a-12d8-4ce5-b016-680843981589', '001e8f4d-6450-43a4-bb33-ec6d94a3febf', 1, 'Si la pared medianera no puede resistir la mayor elevación, el propietario que quiera levantarla tendrá la obligación de reconstruirla a su costo, y si fuere necesario darle mayor espesor, deberá darlo de su suelo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('394f96b3-e7eb-4b7d-9134-0c66f8e45dbe', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '520', 'Medianería hasta la altura común', 428, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b17c4c15-8d7f-4f98-9ab8-13231bdb8b8b', '394f96b3-e7eb-4b7d-9134-0c66f8e45dbe', 1, 'En los casos señalados por los artículos 516, 517 y 519, la pared continuará medianera hasta la altura en que lo era anteriormente, aun cuando haya sido construida de nuevo a expensas de uno solo de los medianeros; y desde el punto donde comenzó la mayor altura, es propia exclusivamente del que la construyó.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('53762aaf-7ebc-49db-8a33-67682310a45a', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '521', 'Adquisición de la medianería en la parte elevada', 429, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a84b428-6b9f-4ef0-ad61-829ee7b0dd33', '53762aaf-7ebc-49db-8a33-67682310a45a', 1, 'Los demás propietarios que no hayan contribuido a dar más elevación o espesor a la pared medianera, podrán, sin embargo, adquirir en la parte nuevamente elevada los derechos de medianería, pagando proporcionalmente el valor de la obra y la mitad del valor del terreno sobre que se hubiere dado mayor espesor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c0c0a305-f8e9-4695-847c-fa88ad99eef6', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '522', 'Uso de la pared medianera', 430, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('75c97cf0-db7b-4979-b55a-e3d88aeba471', 'c0c0a305-f8e9-4695-847c-fa88ad99eef6', 1, 'Cada propietario de una pared medianera, podrá usar de ella, en proporción al derecho que tenga en la mancomunidad; podrá, por tanto, edificar apoyando su obra en la pared medianera o introduciendo vigas hasta la mitad de su espesor; pero sin impedir el respectivo uso común de los demás medianeros. Para usar el medianero de este derecho, ha de dar aviso previo a los demás interesados en la medianería y si alguno se opusiere, se fijarán por peritos las condiciones necesarias para que la nueva obra no perjudique los derechos de aquéllos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('672645d0-2e2f-4bf8-b9fb-3668848afb26', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '523', 'No se puede abrir ventanas en pared medianera', 431, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96007ca9-025e-42d4-b438-7974e705db21', '672645d0-2e2f-4bf8-b9fb-3668848afb26', 1, 'Ningún propietario puede, sin consentimiento del otro, abrir ventanas ni hueco alguno en pared medianera.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9384057-7379-4403-b9c2-305bc92fc36e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '524', 'Ventanas en pared no medianera', 432, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56c5aaa6-196c-44c7-a63c-c8f150f53205', 'e9384057-7379-4403-b9c2-305bc92fc36e', 1, 'El dueño de una pared no medianera, contigua a finca ajena, puede abrir en ella ventanas o huecos para recibir las luces a una altura tal, que la parte inferior de la ventana, diste del suelo de la vivienda a que da luz, tres metros a lo menos, en todo caso con reja de hierro remetida en la pared y con red de alambre cuyas mallas tengan tres centímetros a lo más.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4aaa3655-304b-44d1-9f01-2166bf34c54c', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '525', 'Derecho del vecino', 433, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8cb2eb3f-07ed-4d7a-95df-faa98ab013d6', '4aaa3655-304b-44d1-9f01-2166bf34c54c', 1, 'Sin embargo, de lo dispuesto en el artículo anterior, el dueño de la finca o propiedad contigua a la pared en que estuviesen abiertas ventanas o huecos, podrá construir pared contigua a ella, o si se adquiere la medianería, apoyarse en la misma pared medianera, aunque de uno u otro modo cubra los huecos o ventanas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4ac35a9b-2083-4af6-bf31-d3faaef1a178', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '526', 'Ventanas de vista de costado u oblicuas', 434, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1b9aad5f-7f93-42f3-802e-622ead2d22de', '4ac35a9b-2083-4af6-bf31-d3faaef1a178', 1, 'No se puede tener ventanas para asomarse, o balcones ni otros semejantes voladizos sobre la propiedad del vecino, prolongándolos más allá del límite que separa las heredades. Tampoco puede tenerse vistas de costado u oblicuas, sobre la misma propiedad, si no hay seis decímetros de distancia.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea54fc38-0f68-4d06-992d-488e1c49f81d', '4ac35a9b-2083-4af6-bf31-d3faaef1a178', 2, 'La distancia se mide desde la línea de separación de las dos propiedades.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9671d94b-2bbd-4e24-b330-11ffbab3f8b6', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '527', 'Ventanas de vista directa', 435, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb03419e-c8a0-42d6-b771-815c4aa75206', '9671d94b-2bbd-4e24-b330-11ffbab3f8b6', 1, 'No pueden abrirse ventanas o balcones que den vista a las habitaciones, patios o corrales del predio vecino, a menos que medie una distancia de tres metros. La distancia se medirá entre el plano vertical de la línea más saliente de la ventana o balcón y el plano vertical de la línea divisoria de los dos predios, en el punto en que dichas líneas se estrechan más, si no son paralelas.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afb2f6fa-f56e-4d84-9425-845bc1825ad4', '9671d94b-2bbd-4e24-b330-11ffbab3f8b6', 2, 'PARRAFO III De la propiedad horizontal');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f9c279a1-3460-45fd-9c97-4d33292ac361', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '528', NULL, 436, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f910c34-7170-4fe5-ad85-8d63fb74044c', 'f9c279a1-3460-45fd-9c97-4d33292ac361', 1, 'Propiedad singular en edificios de varios pisos, departamentos y habitaciones. Los distintos pisos, departamentos y habitaciones de un mismo edificio de más de una planta, susceptibles de aprovechamiento independiente, pueden pertenecer a diferentes propietarios, en forma separada o en condominio, siempre que tengan salida a la vía pública o a determinado espacio común que conduzca a dicha vía.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('197d553c-7e5b-4580-9d1e-0e59a4e2f47e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '529', 'Cómo se origina la propiedad horizontal', 437, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfd0b16a-cfc5-42f9-ab6f-b27fb290655c', '197d553c-7e5b-4580-9d1e-0e59a4e2f47e', 1, 'El régimen de propiedad horizontalmente dividida puede originarse: a) Cuando el propietario o los propietarios comunes de un edificio decidan someterlo a este régimen para efectuar cualquier negocio jurídico con todos o parte de sus diferentes pisos, una vez que se hayan inscrito en el Registro de la Propiedad como fincas independientes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2dee23e7-fe9a-4087-827c-5a111d1e7e0e', '197d553c-7e5b-4580-9d1e-0e59a4e2f47e', 2, 'b) Cuando una o varias personas construyan un edificio con el mismo propósito; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55300a12-ad68-45dc-a37d-492778c819c0', '197d553c-7e5b-4580-9d1e-0e59a4e2f47e', 3, 'c) Cuando en disposición de última voluntad se instituya a los herederos o a algunos de ellos como legatarios de pisos de un mismo edificio susceptible de propiedad horizontal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ba9b9bc4-f502-4f8f-80a9-25cc65b695cc', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '530', 'El inmueble debe estar libre de gravámenes', 438, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3974f9f3-718e-4d5e-8b4f-fe400a889e90', 'ba9b9bc4-f502-4f8f-80a9-25cc65b695cc', 1, 'Todo inmueble, para que pueda organizarse en el régimen de propiedad horizontal, debe encontrarse libre de gravámenes, limitaciones, anotaciones o reclamaciones de cualquiera naturaleza. En caso contrario, deben prestar su consentimiento expreso las personas a cuyo favor aparecieren inscritos tales gravámenes, limitaciones o reclamaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '531', 'Debe constituirse por escritura pública', 439, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c7c17bce-4d95-4be6-aa7a-4f5afab601aa', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 1, 'El régimen de la propiedad horizontal se debe constituir por escritura pública, que ha de inscribirse en el Registro de la Propiedad Inmueble. La escritura constitutiva debe contener los requisitos siguientes:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f6bcb5d-026c-4515-b74d-928f9f854361', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 2, '1. Declaración del propietario o propietarios de someter a este régimen el inmueble de su propiedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0285958a-bfa3-4111-9619-af1d1222a406', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 3, '2. Situación, medidas y colindancias del terreno, así como una descripción total del edificio y mención de sus servicios de agua, electricidad y cualesquiera otros de que goce;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('10959798-56fc-4a0e-8793-16fe7d8cc4be', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 4, '3. Descripción de cada piso con los datos que sean necesarios para su identificación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3e52a6c-6d97-4ca8-8194-c6eac8290f90', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 5, '4. El valor del inmueble y el de cada piso;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5df84381-69d4-487e-be94-9faee3511c88', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 6, '5. Descripción de los elementos y partes comunes del edificio y de los elementos y partes comunes limitados a las unidades independientes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4aeda67d-880a-460d-9e64-32a6a97fd7f6', '5bc5f98f-b59b-43a5-862b-4ee3eaf41041', 7, '6. Cualquier otro dato que consideren conveniente los otorgantes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('db0f139e-392d-4728-baba-ab3e9f5cb5ea', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '532', 'Piso Departamento Habitación', 440, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a20492d6-dc36-41c5-884e-cc87ec21604e', 'db0f139e-392d-4728-baba-ab3e9f5cb5ea', 1, 'Se entiende por piso el conjunto de departamentos y habitaciones construidos en un mismo plano horizontal, en un edificio de varias plantas; por departamento la construcción que ocupa parte de un piso, y por habitación el espacio constituido por un solo aposento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('49523679-3527-42b5-a13a-60cb13e5c0ca', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '533', 'Propiedad singular y condominio', 441, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cfa56e66-c82b-463c-b90b-fe5dc75234fa', '49523679-3527-42b5-a13a-60cb13e5c0ca', 1, 'Cada titular es dueño exclusivo de su piso y copropietario de los elementos y partes comunes del edificio total. Son elementos comunes, además del terreno, las cosas necesarias para la seguridad, conservación y servicios generales para el uso y goce de todo el inmueble y de cada planta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c6f75ab-5cbe-4129-a4ec-9b9687adde51', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '534', 'Indivisión forzosa', 442, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0263cb95-0028-4866-b8a0-93cfe3a16ab3', '1c6f75ab-5cbe-4129-a4ec-9b9687adde51', 1, 'Los elementos y partes comunes se han de mantener en indivisión forzosa mientras dure el régimen de propiedad horizontal, siendo nulo cualquier pacto en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9fcd66b6-8d86-4aca-8865-839c77e8fa89', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '535', 'Facultades del propietario', 443, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2811df14-e486-4243-9a72-cce25a45ce39', '9fcd66b6-8d86-4aca-8865-839c77e8fa89', 1, 'Cada piso, departamento o habitación puede trasmitirse o gravarse con independencia del edificio total de que forma parte. El propietario tiene derecho de usar, gozar y disponer de él con las limitaciones que establecen las leyes, escritura constitutiva del régimen y reglamento de copropiedad y administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e8a2e0f-3a33-4a7b-8c0f-763174de741d', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '536', 'Prohibiciones', 444, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8abd7dfa-e7fa-40ed-a72d-1c28ce39e87c', '9e8a2e0f-3a33-4a7b-8c0f-763174de741d', 1, 'Cada propietario de piso, departamento o habitación debe abstenerse de destinar su propiedad a usos contrarios a la moral y buenas costumbres, hacerla servir a otros objetos que los convenidos en la escritura constitutiva, efectuar actos que perturben la tranquilidad de los demás propietarios u ocupantes, o realizar hechos que comprometan la seguridad, solidez y salubridad del edificio, así como incurrir en omisiones que produzcan los mismos resultados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3885b15b-febe-4fd9-83a8-20359fb42ad5', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '537', NULL, 445, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c29c5bb-086f-4611-974a-6dc265f020a6', '3885b15b-febe-4fd9-83a8-20359fb42ad5', 1, 'Acción contra el propietario que viole las prohibiciones Si el dueño de un piso, departamento o habitación faltare en forma grave a las obligaciones que determina el artículo anterior, los propietarios pueden acudir al juez para que comprobados los hechos, declare la exclusión del demandado del goce personal de la unidad y responda de los daños y perjuicios causados a los dueños u ocupantes de los demás departamentos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8acf8da9-7d21-483e-92eb-dbde9a5d7a68', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '538', 'Infracciones cometidas por inquilinos', 446, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aad80310-7861-46ff-b67d-65e18894526a', '8acf8da9-7d21-483e-92eb-dbde9a5d7a68', 1, 'Las infracciones a que se refieren los artículos anteriores cometidas por inquilinos u ocupantes, son causales para el desahucio; y la acción puede ejercitarla el administrador como representante legal de los propietarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('73f2fd36-8c7f-4c50-b203-d1572f532801', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '539', 'Prohibición a los dueños del primero y último pisos', 447, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('923c7916-5f72-4e40-930a-03c4d7ecaebc', '73f2fd36-8c7f-4c50-b203-d1572f532801', 1, 'El propietario del último piso, departamento o habitación situados en la planta más alta, no podrá elevar el nivel de dicha planta sin el consentimiento unánime de los demás propietarios y la autorización municipal respectiva. Sin cumplir estos mismos requisitos, el propietario de la planta baja o del subsuelo o de departamento o habitación situados en los mismos, no podrá hacer sótanos o excavaciones de ninguna especie.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e2c40188-e5be-4001-89f2-442f39a81da8', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '540', 'Mejoras comunes', 448, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('317e22d2-c4fd-4f1d-9e00-374f3c53c32e', 'e2c40188-e5be-4001-89f2-442f39a81da8', 1, 'Las reformas a todo el edificio, destinadas al mejoramiento del mismo o al uso más cómodo de los elementos comunes, así como las modificaciones que alteren su estructura, deben ser acordadas por todos los propietarios, y cuando afecten especialmente alguna planta, el consentimiento de su propietario es indispensable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8ecf0666-29c1-49a9-be1b-964ab17826e1', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '541', 'Obras urgentes', 449, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1cb6fee9-fe8f-4297-b575-389989513c16', '8ecf0666-29c1-49a9-be1b-964ab17826e1', 1, 'Cuando el edificio o sus elementos comunes requieran obras urgentes o necesarias de reparación para su seguridad o conservación, cualquier propietario de piso, en ausencia del administrador, puede hacerlas a sus expensas y tiene derecho a repetir contra los demás para el pago proporcional de los gastos hechos, mediante la presentación de los comprobantes respectivos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a262e845-e347-4bc2-b183-61df0a72821e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '542', 'Autorización de obras urgentes', 450, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a358a62b-8a91-4490-8984-e19cff16b542', 'a262e845-e347-4bc2-b183-61df0a72821e', 1, 'La estimación de la urgencia o necesidad de las obras y su importe, corresponde a la mayoría de los propietarios o, en su defecto, al juez competente, cuando lo solicite cualquiera de ellos, si no hubiere acuerdo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c0b25ccb-ec48-4726-88c9-fa18c5792dbf', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '543', 'Mejoras en cada piso', 451, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('834b30d0-dfca-40f4-9f93-32b914f9da29', 'c0b25ccb-ec48-4726-88c9-fa18c5792dbf', 1, 'Cada propietario puede hacer toda clase de obras y reparaciones en su piso, siempre que no dañe la estructura o partes esenciales del edificio, perjudicando su seguridad, solidez o salubridad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('865ae4f0-80a9-4814-96be-8b1353ce7553', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '544', 'Oposición a las mejoras', 452, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5128b85d-1fac-40d4-91d9-043b00e440a9', '865ae4f0-80a9-4814-96be-8b1353ce7553', 1, 'En caso de que cualquier interesado considere que las obras o reparaciones perjudican el edificio o limitan el libre uso y goce a otras unidades del mismo, puede acudir al juez ejercitando las acciones procedentes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef7339d9-6d2b-4f00-8aa9-070bea405173', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '545', 'Gastos comunes', 453, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6354f67d-7854-4e56-8d1d-87b07bc37415', 'ef7339d9-6d2b-4f00-8aa9-070bea405173', 1, 'Cada propietario debe contribuir a los gastos comunes de administración, mantenimiento, reparación, pago de servicios generales y primas de seguros sobre el edificio total; así como al pago de los impuestos que a éste correspondan, sin perjuicio de cubrir por su cuenta los impuestos de su propiedad particular.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1300286f-0b5f-4018-afa0-5c9fcd75112d', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '546', 'Adeudos al enajenarse el piso', 454, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1df42cac-79c5-406f-80f6-54c829555b24', '1300286f-0b5f-4018-afa0-5c9fcd75112d', 1, 'La obligación de los propietarios de pagar los gastos comunes se transmite al causahabiente, siendo éste responsable solidariamente con el enajenante por los adeudos pendientes ocurridos antes de la enajenación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c204df85-dd7b-4bd4-92fb-945241d63335', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '547', 'Administración del edificio', 455, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41b61510-cf2d-42c2-85eb-046b098d8d15', 'c204df85-dd7b-4bd4-92fb-945241d63335', 1, 'Los edificios sometidos al régimen de propiedad horizontal deben ser administrados por la persona que designe la mayoría de propietarios. El administrador ejercerá su cargo con sujeción a las disposiciones que debe contener el reglamento de copropiedad y administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d85d7b0f-5957-4401-a823-54bda55410fb', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '548', 'Facultades del administrador', 456, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a8f4967-0d86-47dd-a2d0-5b20c9f75512', 'd85d7b0f-5957-4401-a823-54bda55410fb', 1, 'El administrador es el representante legal de los propietarios en todos los asuntos judiciales o extrajudiciales comunes relacionados con el edificio, sea que se promuevan a nombre o en contra de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('21cbc3c3-5b1d-4bc7-ab21-f6b14edd42f1', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '549', NULL, 457, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('246f105d-968f-42a8-80eb-33a2d08d86c8', '21cbc3c3-5b1d-4bc7-ab21-f6b14edd42f1', 1, 'El administrador tendrá las facultades generales que la ley otorga a todo mandatario, y las que requieran cláusula especial que se le confieran por el reglamento de copropiedad y administración, o en disposición tomada por los propietarios con el voto favorable de la mayoría.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50dc6303-0f20-45a6-94d1-68d6143e24ab', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '550', NULL, 458, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29ea88a8-1602-4f1c-9881-56d5cbff5edd', '50dc6303-0f20-45a6-94d1-68d6143e24ab', 1, 'Los asuntos de interés común que no se encuentren comprendidos dentro de las facultades conferidas al administrador, así como aquellos que correspondan a éste pero que los propietarios estimen conveniente conocer personalmente, deben ser resueltos por la mayoría de los mismos propietarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5658be1e-5029-4640-87fb-27c9cda55732', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '551', 'Informe y rendición de cuentas', 459, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c74558a-5dd2-4ece-9f91-f85472425a48', '5658be1e-5029-4640-87fb-27c9cda55732', 1, 'La asamblea de propietarios debe anualmente conocer del informe del administrador y de la cuenta que éste debe rendir. Aprobará el presupuesto de gastos para el año siguiente y determinará la forma en que deben allegarse los fondos necesarios para cubrirlo. Las disposiciones legalmente adoptadas por la asamblea obligan a todos los propietarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6e8a679a-9b96-4b14-b13f-4f9e67755874', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '552', 'Seguros comunes', 460, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b7f98d2-4381-4945-9bfc-28e0f28c1249', '6e8a679a-9b96-4b14-b13f-4f9e67755874', 1, 'El edificio total debe ser asegurado contra los riesgos que pueda sufrir, determinados en la escritura constitutiva, sin perjuicio de los seguros particulares a que igualmente estén obligados los titulares o que acuerde la mayoría de propietarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('df55eca3-3b78-4352-8a1f-e8ba815f5748', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '553', 'Destino de la indemnización', 461, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5914c16e-b11b-4fda-b6fe-25d7008571b0', 'df55eca3-3b78-4352-8a1f-e8ba815f5748', 1, 'En caso de siniestro que destruya el edificio, la indemnización del seguro se entregará al administrador, previo afianzamiento de su responsabilidad, para que pague en primer lugar los gravámenes si los hubiere y, enseguida, la reparación o reconstrucción del edificio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e1064efa-bb1b-4d39-ba54-215175341c98', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '554', NULL, 462, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d42b7a6f-9b16-4d8a-8e8a-79cafa6ec6c4', 'e1064efa-bb1b-4d39-ba54-215175341c98', 1, 'Si la indemnización no alcanzare a cubrir los gastos de reconstrucción, el costo adicional se debe satisfacer por los titulares perjudicados por el siniestro, en proporción al valor de su propiedad, salvo lo que dispongan en cada caso los propietarios afectados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4468585a-a9ee-4420-8b00-f7268688725e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '555', 'Extinción del régimen', 463, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d6b9f69-42ec-4f3e-8f0c-083444fe789a', '4468585a-a9ee-4420-8b00-f7268688725e', 1, 'El régimen de propiedad horizontal puede extinguirse por resolución expresa de los dueños de unidades singulares del edificio, tomada con el voto de las dos terceras partes del total de propietarios. Sin embargo, la minoría inconforme con esta determinación puede adquirir las unidades singulares de los que hayan votado por la extinción del régimen, a efecto de mantenerlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f1173053-e704-4ac0-8341-7cb235c33f7e', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '556', NULL, 464, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ce72bc7-7e7f-43ce-8ace-9401fcb797c7', 'f1173053-e704-4ac0-8341-7cb235c33f7e', 1, 'La extinción no puede otorgarse sino en el caso de que todas las unidades singulares del inmueble se encuentren libres de gravamen y anotación o, en caso contrario, que los interesados presten su consentimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('988592d2-9fc7-4857-9eba-ca3045a966fc', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '557', NULL, 465, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f9fa09c-7130-44c4-8482-82b0040b4158', '988592d2-9fc7-4857-9eba-ca3045a966fc', 1, 'Los propietarios de unidades singulares del edificio, al extinguirse el régimen quedan como dueños en común del terreno, de la construcción, o de los materiales aprovechables según el caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3cdfce90-60fe-46f0-a1ce-d26997034c3b', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '558', NULL, 466, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('59d057d5-5b5c-432f-add1-13ae0203526f', '3cdfce90-60fe-46f0-a1ce-d26997034c3b', 1, 'La cancelación del régimen de propiedad horizontal de un inmueble, deben hacerla constar los propietarios en escritura pública que debe inscribirse en el Registro de la Propiedad. Las fincas filiales se refundirán en la finca matriz en la cual se harán las inscripciones respectivas a favor de los comuneros y los gravámenes y anotaciones que pesaren sobre las fincas canceladas, en su caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('574fe2df-d015-43f8-ba80-d200dc620d1a', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '559', 'Reglamento de copropiedad y administración', 467, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c9c95be-84f4-4c16-b178-7bed20796960', '574fe2df-d015-43f8-ba80-d200dc620d1a', 1, 'Para la regulación de las recíprocas relaciones de vecindad y condominio, así como le referente a la administración y atención de los servicios comunes, deberán los otorgantes del régimen');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7a7d35d-9f14-4b58-a7a0-ee8e4a383d61', '574fe2df-d015-43f8-ba80-d200dc620d1a', 2, 'aprobar e incluir en la escritura constitutiva el Reglamento de copropiedad y administración y determinar en él las formas de mayoría para los casos de aprobación de los actos y negocios que requiera el voto de los propietarios. El Reglamento puede ser modificado en la misma forma y a sus disposiciones deben sujetarse los nuevos adquirentes, inquilinos y ocupantes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('158bc0ed-d53b-463e-a66d-ca656b7ed8a6', '574fe2df-d015-43f8-ba80-d200dc620d1a', 3, 'DE LA PROPIEDAD EN FIDEICOMISO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fffa5989-f30b-4c1d-b706-b2f31c04cb38', 'a0000000-0000-0000-0000-000000000001', '620c1dc2-7f53-491b-a0e0-616b83975a71', '560', NULL, 468, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0c9f71b3-b5cc-46ae-9a46-6497d4e62183', 'fffa5989-f30b-4c1d-b706-b2f31c04cb38', 1, 'al 578. DEROGADOS. 17');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa88cf88-4bf6-4bb2-8bf1-dbfdd8bc9a2c', 'fffa5989-f30b-4c1d-b706-b2f31c04cb38', 2, 'DE LA PROPIEDAD DE LAS AGUAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6f2d32b9-2c1a-4d46-8a84-6dfe0ade34d6', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '579', 'Aguas de dominio privado', 469, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e86665f6-ebb7-4f73-b576-60d89ea1e221', '6f2d32b9-2c1a-4d46-8a84-6dfe0ade34d6', 1, 'Son de dominio privado: 1. Las aguas pluviales que caigan en predios de propiedad privada, mientras no traspasen sus linderos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e405a3d4-8bc2-4a30-9be2-8eb85429ffc8', '6f2d32b9-2c1a-4d46-8a84-6dfe0ade34d6', 2, '2. Las aguas continuas y discontinuas que nazcan en dichos predios, mientras discurran por ellos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f4b64a1-f0b9-460d-97e1-2d6b64752aed', '6f2d32b9-2c1a-4d46-8a84-6dfe0ade34d6', 3, '3. Las lagunas y sus álveos formados por la naturaleza, en los expresados terrenos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('68c9d3d0-3771-4270-9d06-bd4b9c73ad91', '6f2d32b9-2c1a-4d46-8a84-6dfe0ade34d6', 4, '4. Las aguas subterráneas obtenidas por medios artificiales en propiedades particulares.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a692ea18-b1de-4a96-9441-2302a14f8507', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '580', 'Propiedad de los álveos o cauces', 470, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5cb2d87-1bf4-462d-8c2c-62a910699ec4', 'a692ea18-b1de-4a96-9441-2302a14f8507', 1, 'Pertenecen al propietario los álveos o cauces naturales de las corrientes discontinuas formadas por aguas pluviales y los álveos de los ríos y arroyos en la parte que atraviesan sus heredades, pero no podrá ejecutar labores ni construir obras que puedan hacer variar el curso natural de las mismas en perjuicio de otro, o cuya destrucción por la fuerza de las avenidas, pueda causar daño a predios, fábricas o establecimientos, fuentes, caminos o poblaciones. Los álveos de las charcas, lagunas o lagos que colindan con sus propiedades le');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5f5a902-b05a-48b8-9aac-9d2b90143d1e', 'a692ea18-b1de-4a96-9441-2302a14f8507', 2, '17 Derogados los artículos del 560 al 578, por el Artículo 1 del Capítulo II Disposiciones Derogatorias y Modificatorias del Decreto del Congreso número 2-70 del Congreso de la República, Código de Comercio, publicado en el Diario de Centro América el 22 de junio de 1970.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67c8a6e3-0b8d-4edf-8af7-c7ebfa160edd', 'a692ea18-b1de-4a96-9441-2302a14f8507', 3, 'pertenecerán en proporción a su colindancia, siempre que no sean de propiedad de persona determinada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cbf47e8a-f75a-4a84-8716-a16aad0d6826', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '581', 'Aguas subterráneas', 471, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('637f3410-fa2b-495e-bd4b-f0ccf301f1af', 'cbf47e8a-f75a-4a84-8716-a16aad0d6826', 1, 'Todo propietario puede abrir pozos dentro de sus fincas, para obtener y elevar aguas subterráneas, y efectuar cualquiera otra obra con el objeto de buscar el alumbramiento de dichas aguas, pero sin que tales trabajos puedan mermar o distraer aguas públicas o privadas de su corriente superficial natural que se destinan a un servicio público o a un aprovechamiento particular preexistente, con titulo legítimo, en cuyo caso, la autoridad, a solicitud de los interesados, podrá ordenar la suspensión de la obra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('55b23c8f-4193-4c26-9517-f846670eb547', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '582', 'Distancias a que pueden abrirse los pozos', 472, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('761968c8-6b22-4614-8b8d-69a76d6c5664', '55b23c8f-4193-4c26-9517-f846670eb547', 1, 'Las obras artificiales a que se refiere el artículo anterior no podrán ejecutarse a menor distancia de cuarenta metros de edificios ajenos, de un ferrocarril o carretera, ni a menos de cien metros de otro alumbramiento o fuente, río, canal, acequia o abrevadero público, sin la licencia correspondiente de los dueños o, en su caso, del municipio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a979b4e-5299-4ed7-af0a-d6cc12794521', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '583', NULL, 473, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('686903c2-3a9a-4e62-9229-bb675cbb1540', '4a979b4e-5299-4ed7-af0a-d6cc12794521', 1, 'Los pozos no deberán perforarse a menor distancia de dos metros entre uno y otro dentro de las poblaciones, y de quince metros, por lo menos, en el campo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93406a50-506a-4e2b-a2ec-9ce490cc393c', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '584', 'Propiedad de las aguas alumbradas', 474, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8df16b24-cee1-48a1-ad21-7623ec2385ce', '93406a50-506a-4e2b-a2ec-9ce490cc393c', 1, 'El propietario que obtenga el alumbramiento de aguas subterráneas por medios artificiales, será dueño de ellas aunque salgan de la finca de su pertenencia, con sujeción a lo que establece el artículo siguiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9d6ba281-8d0c-4a87-ad27-64f8c17bb123', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '585', NULL, 475, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1320d83c-f8b8-41ba-aa47-2ce7772e1d47', '9d6ba281-8d0c-4a87-ad27-64f8c17bb123', 1, 'Si para aprovechar las aguas alumbradas tuviere el dueño necesidad de conducirlas por predios inferiores ajenos, deberá constituir la servidumbre correspondiente, pero si las dejare abandonadas a su curso natural y los dueños de estos predios las hubieren aprovechado por cinco años ininterrumpidos, adquirirán el derecho de disfrutarlas por el orden de su colocación, dándose preferencia al que se haya anticipado en su uso, quien no podrá ser privado de él por otro, aun cuando éste estuviere situado más arriba, sin antes ser vencido en juicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('defc6194-a8b6-445a-97c1-11e8ef696171', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '586', NULL, 476, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57d66992-d23c-44f7-957e-0b4cc994b0ce', 'defc6194-a8b6-445a-97c1-11e8ef696171', 1, 'Para los efectos del artículo anterior, se tendrán por aguas subterráneas, las que habiendo corrido por la superficie, desaparecieren por causas de erupciones volcánicas, terremotos u otros accidentes de la naturaleza.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('15e514f8-9f61-4530-8fca-fee2f0f530f8', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '587', 'Concesionarios mineros', 477, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1c52916-9ec0-4b21-ab21-36c0bfd869de', '15e514f8-9f61-4530-8fca-fee2f0f530f8', 1, 'Los concesionarios de pertenencias mineras, socavones y galerías generales de desagües de minas, tienen la propiedad de las aguas halladas en sus labores, mientras conserven la concesión de sus minas respectivas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7dccb8f3-8c9a-40bc-831b-bccab2169b76', 'a0000000-0000-0000-0000-000000000001', 'f0c0ffc0-e0ae-4c9e-9a2f-279fb15ccf64', '588', NULL, 478, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6dfb9d7b-dcd1-4f63-954f-2cfc5d164d10', '7dccb8f3-8c9a-40bc-831b-bccab2169b76', 1, 'Todo lo relativo al uso, aprovechamiento y disfrute de las aguas públicas y particulares, se regirá por las disposiciones de las leyes agrarias o de la ley especial del régimen de aguas y regadíos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2b3097d-ee22-4b0c-8f88-3ae32b050f56', '7dccb8f3-8c9a-40bc-831b-bccab2169b76', 2, 'DE LA PROPIEDAD POR OCUPACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af11b8ad-df5f-456a-af85-0b94bd1ec228', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '589', 'Ocupación de muebles', 479, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2773907b-92e4-4c01-9fea-58df8fd457b9', 'af11b8ad-df5f-456a-af85-0b94bd1ec228', 1, 'Las cosas muebles o semovientes que no pertenecen a ninguno, pueden adquirirse por ocupación, de conformidad con lo dispuesto en leyes especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('be671b92-3278-4786-b67e-a16267b93041', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '590', 'Los inmuebles no pueden adquirirse por ocupación', 480, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('662a7cd5-95d1-4c19-af57-b1800596be9e', 'be671b92-3278-4786-b67e-a16267b93041', 1, 'Los que no estén reducidos a propiedad particular pertenecen a la Nación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('caaaa939-3c90-4b70-bc18-facf304b0e84', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '591', 'Muebles que pueden ser objeto de ocupación', 481, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5a8576f-d60c-4f97-98b6-fdee5b51eddf', 'caaaa939-3c90-4b70-bc18-facf304b0e84', 1, 'Pueden ser objeto de ocupación las piedras, conchas y otras substancias que se encuentran en las riberas del mar, de los ríos y arroyos, de uso público y que no presentan señales de dominio anterior. También pueden ser objeto de ocupación las cosas cuya propiedad abandona voluntariamente su dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2a00a35-7ed3-43dd-bc71-5a0054117deb', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '592', 'Tesoro descubierto', 482, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3cb624df-0f8b-468f-9fd6-2789cbe02e78', 'c2a00a35-7ed3-43dd-bc71-5a0054117deb', 1, 'El tesoro encontrado en terreno propio pertenece íntegramente al descubridor. El tesoro encontrado en terreno ajeno se dividirá por partes iguales entre el dueño del terreno y la persona que haya hecho el descubrimiento. Sin embargo, el descubridor no tendrá derecho a su porción sino cuando el descubrimiento sea fortuito, o cuando haya buscado el tesoro con permiso del dueño del terreno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('576f6625-cc42-4f5a-8e9f-6b3692bd1015', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '593', 'Descubrimiento de tesoro', 483, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bf60df3-a96a-4920-9d9e-c64978fc27b5', '576f6625-cc42-4f5a-8e9f-6b3692bd1015', 1, 'Nadie puede buscar tesoro en terreno ajeno, sin permiso escrito del dueño. El interesado que obtuviere permiso y prestare garantía a satisfacción del propietario, podrá hacer excavaciones para sacar dinero, alhajas u objetos preciosos, que alegare pertenecerle.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9fa95935-438d-40ca-84a3-53301fcb90fb', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '594', NULL, 484, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5af0cee-70af-44be-849b-bc6c5aab94a9', '9fa95935-438d-40ca-84a3-53301fcb90fb', 1, 'No probándose el derecho sobre dichos dineros, alhajas u objetos preciosos, serán considerados como bienes perdidos o como tesoro encontrado en suelo ajeno, según los antecedentes y señales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e947cf0-9938-4af6-8255-680febfae70a', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '595', NULL, 485, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae703768-183f-413c-97f5-8bce2c61547a', '3e947cf0-9938-4af6-8255-680febfae70a', 1, 'En el segundo caso del artículo anterior, deducidas las costas se dividirá el tesoro por partes iguales entre el denunciador y el dueño del suelo; pero no podrá éste pedir indemnización de perjuicios, a menos de renunciar a su porción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('203ed8fe-bae3-4a7d-b6e5-ad6206d127d5', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '596', 'Bienes mostrencos', 486, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d08f43a4-469d-4e5a-91a4-ed411ba507ef', '203ed8fe-bae3-4a7d-b6e5-ad6206d127d5', 1, 'El que encontrare un mueble, o semoviente al parecer extraviado y cuyo dueño se ignore, deberá presentarlo a la autoridad municipal más próxima al lugar donde hubiere tenido lugar el hallazgo. La autoridad que reciba el bien encontrado, pondrá el hecho en conocimiento público, y si transcurrido el término fijado no se presentare persona que justifique su dominio, se procederá a su venta en pública subasta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('44c4bac2-a8ed-4c89-aaa0-ee285b625b3f', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '597', NULL, 487, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1fcfae8-d543-4e0e-b9f4-cbbc7627ade3', '44c4bac2-a8ed-4c89-aaa0-ee285b625b3f', 1, 'El dueño que recobre lo perdido o su precio, está obligado al pago de los gastos y a abonar a quien lo halló el diez por ciento del valor de la cosa o del producto de la venta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90d545e0-0ce0-4832-9932-0e705d0a1b70', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '598', NULL, 488, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a84f2bf-0bc5-45e2-94d5-0fb3035d2d5d', '90d545e0-0ce0-4832-9932-0e705d0a1b70', 1, 'La persona que hallare cosas perdidas y no las entregare a la autoridad, perderá su porción a favor de los fondos de justicia y quedará sujeta a la acción de daños y perjuicios que podrá deducir el propietario y, según las circunstancias, a la sanción penal que corresponda. El procedimiento que la autoridad deberá seguir en el caso del hallazgo de cosas a que se refieren los tres artículos anteriores, será el señalado en la ley especial de bienes mostrencos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('18c2d1c8-8e1d-4fe9-8c80-639fc5a7b915', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '599', NULL, 489, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20a94c47-ee36-4726-93a6-2463e531d45e', '18c2d1c8-8e1d-4fe9-8c80-639fc5a7b915', 1, 'No se presumen abandonadas por sus dueños las cosas que los navegantes en el agua y en el aire, arrojen para aligerar la nave, ni los despojos provenientes del siniestro. Tampoco se presumirán abandonadas las cosas que, con el fin de salvarlas, sean sacadas a la vía pública o a otro lugar, en caso de terremoto, incendio u otro siniestro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c6989b08-3c62-48ce-a56b-f24b273dc061', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '600', 'Caza y pesca', 490, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82480644-0ec9-4f3a-9b1b-571658138788', 'c6989b08-3c62-48ce-a56b-f24b273dc061', 1, 'Son susceptibles de ocupación por la caza y la pesca, los animales bravíos o salvajes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f0ab8f80-bf60-4b83-885e-9d08a832941b', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '601', NULL, 491, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b31854ed-4ca4-437a-8741-0df481c7dd17', 'f0ab8f80-bf60-4b83-885e-9d08a832941b', 1, 'No se puede cazar sino en tierras propias, o en las ajenas con permiso del dueño. Pero no será necesario este permiso si las tierras no estuvieren cercadas, ni plantadas, ni cultivadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8ac2319a-bc9e-4dc5-b66a-9afa6b737f1d', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '602', NULL, 492, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ca6d735-3802-4a84-8bf5-18c8046f6977', '8ac2319a-bc9e-4dc5-b66a-9afa6b737f1d', 1, 'Si alguno cazare en tierras ajenas sin permiso del dueño, cuando por la ley esté obligado a obtenerlo, lo que cace será para el dueño, a quien además indemnizará de todo perjuicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c3f189e9-eeed-43f2-991c-fc018632b76f', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '603', NULL, 493, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5aa1a75-404d-4f36-88e3-3e45d18ed563', 'c3f189e9-eeed-43f2-991c-fc018632b76f', 1, 'Se entiende que el cazador o pescador se apodera del animal bravío y lo hace suyo, desde el momento en que lo ha herido de manera que no le sea fácil escapar, y mientras persiste en perseguirlo o desde el momento en que el animal ha caído en sus trampas o redes, con tal que las haya armado o tendido en paraje en que le sea lícito cazar o pescar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f4d19785-991c-4ec5-bdc7-265409d42618', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '604', NULL, 494, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d8b478e7-56f7-4c92-9602-3bbfad1b3f5d', 'f4d19785-991c-4ec5-bdc7-265409d42618', 1, 'Si el animal herido muriese en tierras ajenas donde no es lícito cazar sin permiso del dueño, éste o quien le represente, deberá entregarlo al cazador o permitir que entre a buscarlo. Si no diere permiso, deberá pagar el valor del animal herido; pero si el cazador entra a buscarlo sin el permiso indicado, perderá todo derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78696f99-92f3-4751-86d3-49c589980e7a', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '605', NULL, 495, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eeb27f25-d7d7-4486-b196-670bd0d6b6ce', '78696f99-92f3-4751-86d3-49c589980e7a', 1, 'Los animales feroces que escapen del encierro en que los tengan sus dueños, podrán ser destruidos por cualquiera y podrán también ser ocupados desde que el dueño abandone su persecución. Cualquier persona puede apoderarse de los animales bravíos y hacerlos suyos, tan luego como recobren su libertad natural, con tal de que no vaya el dueño en su seguimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('689348b2-b106-4a70-84c2-07b3beb62526', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '606', NULL, 496, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92f45345-5b0f-4580-96a8-57d5423a78e5', '689348b2-b106-4a70-84c2-07b3beb62526', 1, 'Los animales no domésticos y peces que de su respectivo criadero pasaren a otro perteneciente a distinto dueño, serán propiedad de éste, siempre que no hayan sido atraídos por medio de algún artificio o engaño, pues en este caso, el aprehensor estará obligado a la indemnización de todo perjuicio y a la devolución de la pieza cobrada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3319d27-f842-4017-85e7-cb3f32e4d368', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '607', NULL, 497, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4a6f8145-cf1e-4833-847c-8560dbd19f92', 'e3319d27-f842-4017-85e7-cb3f32e4d368', 1, 'El propietario de un enjambre de abejas tendrá derecho a perseguirlo sobre el fundo ajeno, indemnizando al poseedor de éste del daño causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b233e99-d525-4d3c-a4cc-a9f1355bfe5c', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '608', NULL, 498, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cfb540fd-25a0-4b91-a039-003b30575105', '8b233e99-d525-4d3c-a4cc-a9f1355bfe5c', 1, 'Los animales sin marca alguna que se encuentren en una finca particular se presume que son del dueño de ésta, mientras no se pruebe lo contrario, a no ser que el propietario no tenga cría de la raza a que los animales pertenezcan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a6a8837-6676-4e44-b0b6-fba67554bb1c', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '609', NULL, 499, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9059a19-c642-49c9-a73e-aa66cceb9b46', '6a6a8837-6676-4e44-b0b6-fba67554bb1c', 1, 'Los animales sin marca que se encuentren en tierras de propiedad particular que varias personas exploten en común, se presume que pertenecen al dueño de la cría de la misma especie y de la misma raza en ellas establecida, mientras no se pruebe lo contrario; pero si dos o más fueren dueños de la misma especie o raza, se reputarán de propiedad común si no se prueba que pertenecen a alguno de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9fdd5e73-4150-4077-aa1e-ee9ea59fde9d', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '610', NULL, 500, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eab3e4d8-f14f-46d5-be05-cd0149de5d79', '9fdd5e73-4150-4077-aa1e-ee9ea59fde9d', 1, 'Los animales domésticos, que nacen y se crían ordinariamente bajo el dominio del hombre, aunque salgan de su poder pueden reclamarlos de cualquiera que los retenga, pagando los gastos de su alimentación si se hubieren causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('970694e1-f5e3-4178-8606-4083197e3713', 'a0000000-0000-0000-0000-000000000001', '08e7d2f9-e82b-493d-878c-1cf094abee3f', '611', NULL, 501, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('747cd46e-f5ea-471c-8e55-01fa4ae46474', '970694e1-f5e3-4178-8606-4083197e3713', 1, 'El ejercicio de la caza y la pesca se sujetará a los reglamentos sobre la materia.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b52a0b05-6033-40e0-ab82-7a48a93cb688', '970694e1-f5e3-4178-8606-4083197e3713', 2, 'DE LA POSESION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7503ac83-4a4c-4876-87bc-7499cead4485', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '612', 'Concepto de la posesión', 502, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62a0d96f-2244-4a2b-a0a7-73b0021dcbea', '7503ac83-4a4c-4876-87bc-7499cead4485', 1, 'Es poseedor el que ejerce sobre un bien todas o algunas de las facultades inherentes al dominio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b2398bc1-544e-4d30-accf-3b93f309e23c', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '613', 'Posesión Temporal', 503, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88b79c0a-8a34-4730-a6aa-85a360e4b167', 'b2398bc1-544e-4d30-accf-3b93f309e23c', 1, 'El poseedor temporal en virtud de un derecho es poseedor inmediato, correspondiendo la posesión mediata a quien le confirió tal derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd9218b6-6cd9-4d4b-a168-fe75bc44354d', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '614', 'Casos en que no hay posesión', 504, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('368b2551-4765-442f-8f06-479df9d786b9', 'dd9218b6-6cd9-4d4b-a168-fe75bc44354d', 1, 'No es poseedor quien ejerce el poder sobre la cosa en virtud de la situación de dependencia en que se encuentra respecto del propietario de la misma y la retiene en provecho de éste en cumplimiento de las instrucciones que de él ha recibido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5c56945-422a-44d1-b779-5e92f3b31a7e', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '615', NULL, 505, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9feac3e5-7088-4fcb-825d-0a1e297a1b43', 'b5c56945-422a-44d1-b779-5e92f3b31a7e', 1, 'Tampoco es poseedor el que tiene la cosa o disfruta del derecho por actos meramente facultativos o de simple tolerancia, concedidos o permitidos por el propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fa919e56-9bf3-417f-a032-4e45884453b6', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '616', 'Bienes objeto de la posesión', 506, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('90eaffce-e229-47f1-b509-54770a13c3b9', 'fa919e56-9bf3-417f-a032-4e45884453b6', 1, 'Sólo pueden ser objeto de posesión los bienes corporales y los derechos que sean susceptibles de apropiación. La posesión de los derechos se rige por las mismas disposiciones que regulan la de las cosas corporales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fec7799c-dcea-465c-b6e4-cd98cb761829', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '617', 'La posesión presume la propiedad', 507, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5e8a0fa-dc71-4ce9-ae58-42fd26c5815f', 'fec7799c-dcea-465c-b6e4-cd98cb761829', 1, 'La posesión da al que la tiene, la presunción de propietario, mientras no se pruebe lo contrario. Sólo la posesión que se adquiere y disfruta en concepto de dueño de la cosa poseída, puede producir el dominio por usucapión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0fb9e9c5-7ace-4273-bc13-07569bf99743', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '618', 'Transmisión de la posesión', 508, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c4acb79-cd34-4fc5-882e-ea83a5ef0230', '0fb9e9c5-7ace-4273-bc13-07569bf99743', 1, 'La posesión continúa de derecho en la persona del sucesor. El poseedor puede agregar a la suya la posesión de su antecesor o antecesores, con tal que ambas posesiones tengan los requisitos legales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5c0adcd1-698e-4296-abde-782cade6015c', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '619', 'Posesión actual, anterior e intermedia', 509, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf0b3f05-bbc6-49e2-bef1-1ccca5d50e0d', '5c0adcd1-698e-4296-abde-782cade6015c', 1, 'La posesión actual y la anterior hacen presumir la posesión intermedia; pero la posesión actual no hace presumir la anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a05db801-494f-48f2-8f27-6992810a9bc9', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '620', 'Condiciones para la usucapión', 510, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('491d1bd5-8125-4de5-9d29-4a3649a01a73', 'a05db801-494f-48f2-8f27-6992810a9bc9', 1, 'Para que la posesión produzca el dominio se necesita que esté fundada en justo título, adquirida de buena fe, de manera continua, pública y pacífica y por el tiempo señalado en la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('468da2f9-3c24-4c35-8e37-ebcf8ba317da', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '621', 'Justo título', 511, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5bdefaec-84f4-45ac-a7b6-ceef4993376f', '468da2f9-3c24-4c35-8e37-ebcf8ba317da', 1, 'Es justo título para la usucapión, el que siendo traslativo de dominio, tiene alguna circunstancia que lo hace ineficaz para verificar por sí sólo la enajenación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65b9fa0d-5b57-4521-b94c-fef8158c47b2', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '622', 'Buena fe', 512, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b7564bc-c7ed-499e-9b00-8428ef73de0b', '65b9fa0d-5b57-4521-b94c-fef8158c47b2', 1, 'La buena fe del poseedor consiste en la creencia de que la persona de quien recibió la cosa era dueña de ella y podía transmitir su dominio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d363e60-8f79-4bc6-ba44-20e4d88e42d6', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '623', 'Presunción de buena fe', 513, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('61a67d7e-59fe-422c-b6e7-8f4e6b0b3e90', '2d363e60-8f79-4bc6-ba44-20e4d88e42d6', 1, 'La buena fe dura mientras las circunstancias permiten al poseedor presumir que posee legítimamente, o hasta que es citado en juicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '624', 'Efectos de la posesión de buena fe', 514, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94ce9b9b-ae47-4d9e-bd0e-dbe6f95749e4', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 1, 'El poseedor de buena fe que haya adquirido la posesión por título traslativo de dominio, goza de los derechos siguientes: 1. Hacer suyos los frutos percibidos, mientras su buena fe no sea interrumpida;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6a9f322-7b47-4dcc-ba2d-ebd930bd82f1', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 2, '2. De que se le abonen todos los gastos necesarios y útiles, teniendo derecho de retener la cosa poseída hasta que se haga el pago;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0c1448a-1bc0-4f64-9434-c4d427e3b68c', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 3, '3. Retirar las mejoras voluntarias, si no se causa daño en el bien mejorado, o reparando el que se cause al retirarlas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1ce6f6b-5369-47b4-b7f2-7b4b99c9bf42', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 4, '4. Que se le abonen los gastos hechos por él para la producción de frutos naturales y civiles que no haga suyos por estar pendientes al tiempo de interrumpirse la posesión, teniendo derecho al interés legal sobre el importe de esos gastos desde el día en que los haya hecho;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd61d342-180e-499e-bf0f-6b9603fa98ec', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 5, '5. No ser desposeído de la cosa, si antes no ha sido citado, oído y vencido en juicio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a3e95af-a6fd-463c-a523-5691e14b33c1', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 6, '6. Ser preferido a cualquier otro que la pida con igual derecho, excepto el caso en que deba darse posesión indivisa;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e005b3f-53de-4994-9ece-ff69c79435c5', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 7, '7. Servirse de la posesión como medio para adquirir el dominio por prescripción; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e910c3a-7adb-40ed-a575-ee5cab69cc98', 'f3ae0d17-40b0-4706-abc3-f8074a8f1e1c', 8, '8. Ser considerado dueño de los muebles que posee.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f0377cc-db6b-4dfa-8aad-d3d7674ee0b1', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '625', 'Frutos percibidos', 515, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('63ede29c-db69-460c-a289-f8b2714904cb', '0f0377cc-db6b-4dfa-8aad-d3d7674ee0b1', 1, 'Se entiende percibidos los frutos naturales desde que se separan o levantan. Los frutos civiles se producen día por día, y pertenecen al poseedor en esta proporción, luego que le son debidos, aunque no los haya recibido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e88f4562-7083-433b-a3f1-3b28e7133852', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '626', 'Comprobación de gastos', 516, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bc56bb7-c802-4b1f-9dc7-78505266ea8a', 'e88f4562-7083-433b-a3f1-3b28e7133852', 1, 'El poseedor debe justificar el importe de los gastos a que tenga derecho; y cuando hubiere percibido frutos que legalmente no le correspondieren, habrá lugar a la compensación de valores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d80be37-8d70-4800-b107-5d9c33ee9d55', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '627', 'Gastos', 517, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('933c37ac-a9ca-4b58-80d0-bd288da0df19', '4d80be37-8d70-4800-b107-5d9c33ee9d55', 1, 'Son gastos necesarios los que están prescritos por la ley y aquellos sin los cuales la cosa se pierde o desmejora. Gastos útiles, los que sin ser necesarios aumentan el precio o producto de la cosa; y voluntarios, los que sirven sólo al ornato de la cosa, o al placer o comodidad del poseedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a39639b-c8ea-428d-9400-07e5bcfc8bd7', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '628', 'Poseedor de mala fe', 518, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('702c7264-63f6-4ff2-ad4d-b7b5fb708baa', '7a39639b-c8ea-428d-9400-07e5bcfc8bd7', 1, 'Es poseedor de mala fe el que entra a la posesión sin título alguno para poseer; y también el que conoce los vicios de su título que le impiden poseer con derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a83e7af-d424-4b18-a50b-a4dc9b4cf241', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '629', 'Posesión de mala fe', 519, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c9cf4ec-49a5-427b-8139-ccbacf1cdce9', '3a83e7af-d424-4b18-a50b-a4dc9b4cf241', 1, 'El poseedor de mala fe está obligado a la devolución del bien que ha poseído y de sus frutos, o el valor de éstos estimado al tiempo que los percibió o los debió percibir; y a responder de la pérdida o deterioro de la cosa, sobrevenidos por su culpa o por caso fortuito o fuerza mayor, salvo que pruebe que tal pérdida o deterioro se habría causado aunque la posesión la hubiere tenido el propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1b31f0b2-cf07-4e24-b132-588a581124f9', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '630', 'Posesión discontinua', 520, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('795a4062-2c57-41d1-a532-42fadf9735ea', '1b31f0b2-cf07-4e24-b132-588a581124f9', 1, 'Existe discontinuidad en la posesión, cuando la cosa poseída se abandona o desampara por más de un año, o antes, cuando expresa o tácitamente se manifiesta la intención de no conservarla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('801c0d80-bef3-4bcc-9db7-5d252c177692', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '631', 'Posesión violenta', 521, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('49078bf3-1708-4729-8fae-df6d60cc80c7', '801c0d80-bef3-4bcc-9db7-5d252c177692', 1, 'Es posesión violenta la que se adquiere por la fuerza o por medio de coacción moral o material contra el poseedor, contra la persona que lo representa o contra quien tiene la cosa a nombre de aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83c6b8e0-6439-4531-9877-b31b48eee6b0', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '632', 'Posesión pública y clandestina', 522, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5610c22e-ccec-4f4b-aef4-7e927db04be8', '83c6b8e0-6439-4531-9877-b31b48eee6b0', 1, 'Posesión pública es la que se disfruta de manera que pueda ser conocida de todos; y clandestina, la que se ejerce ocultándola a los que tienen derecho para oponerse a ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3aa4db99-a9e1-4de1-9e57-f9562f513713', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '633', 'Posesión de bienes inmuebles', 523, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1683950-9f1a-4151-be5c-8fc1ba12bec2', '3aa4db99-a9e1-4de1-9e57-f9562f513713', 1, 'Tratándose de bienes inmuebles, la posesión por diez años, con las demás condiciones señaladas en el artículo 620, da derecho al poseedor para solicitar su titulación supletoria a fin de ser inscrita en el Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6191ac35-d341-469e-bd17-4636b45aeb91', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '634', NULL, 524, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2499daca-795c-4a66-846f-de012098bf52', '6191ac35-d341-469e-bd17-4636b45aeb91', 1, 'Las diligencias de titulación supletoria deberán sujetarse al procedimiento que señala la ley respectiva, y la resolución aprobatoria de las mismas es título para adquirir la propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ade831cd-b7c6-44ad-8922-1f657cc7c06b', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '635', NULL, 525, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f62999e-f68e-4e2c-b055-f2e3bab6d69a', 'ade831cd-b7c6-44ad-8922-1f657cc7c06b', 1, 'Sólo los guatemaltecos de nacimiento pueden obtener titulación supletoria de terrenos comprendidos dentro de quince kilómetros a lo largo de las fronteras y del litoral. Si se trata de personas jurídicas, los individuos que las formen deben ser todos guatemaltecos de nacimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('30bf50b7-9937-48ee-b8d9-c510cfb4276a', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '636', NULL, 526, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('516695f1-e7e6-4e53-9558-c304bd06e8ed', '30bf50b7-9937-48ee-b8d9-c510cfb4276a', 1, 'Los inmuebles situados dentro de las reservas del Estado no pueden titularse supletoriamente. Tampoco pueden titularse los excesos de las propiedades raíces, los que se adquieren según lo dispuesto por las leyes administrativas de la materia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ee341735-5b58-48aa-92a8-6d507740c395', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '637', NULL, 527, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dbc69b48-1e6a-4544-89f6-27f2369726b7', 'ee341735-5b58-48aa-92a8-6d507740c395', 1, 'La posesión registrada de un inmueble, una vez consumado el término de diez años desde la fecha de la inscripción del título en el Registro de la Propiedad,');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3b1cd391-9016-4e02-8842-5e9646646dac', 'ee341735-5b58-48aa-92a8-6d507740c395', 2, 'se convierte en inscripción de dominio y puede oponerse a cualquiera otra inscripción de propiedad relativa al mismo bien. Sin embargo, el usucapiente puede entablar juicio para que se le declare dueño aun antes del tiempo señalado en el párrafo anterior, y la sentencia que así le declare, es título para la inscripción de la propiedad y para cancelar el asiento a favor del antiguo dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8454cebc-d390-4db3-a253-3622d94bdd46', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '638', NULL, 528, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('07115448-ac1d-4b51-bf0b-c632baf15b9c', '8454cebc-d390-4db3-a253-3622d94bdd46', 1, 'Una misma cosa no puede ser poseída por varias personas a la vez, de suerte que cada una pretenda poseerla toda; pero sí pueden poseer una cosa en común, teniendo todas ellas la posesión indivisa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c778eb9f-2c76-4af3-a99c-3a941d314f7c', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '639', NULL, 529, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3be04e26-e0d4-45d9-a8d5-009f61eb8285', 'c778eb9f-2c76-4af3-a99c-3a941d314f7c', 1, 'El que hubiere perdido la posesión de una cosa mueble o semoviente o aquel a quien se la hubiesen quitado, podrá reivindicarla de quien la tenga, sin perjuicio de que este último, si hubiese adquirido la cosa de buena fe, pueda exigir indemnización de quien la hubiere habido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03b05866-008f-4c9f-ab4c-2220a9e740f4', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '640', NULL, 530, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('827dfadc-8061-4ac8-b23e-eecff1baf9e4', '03b05866-008f-4c9f-ab4c-2220a9e740f4', 1, 'Si el actual poseedor de la cosa sustraída o perdida, la hubiere comprado en una feria o en venta pública o a personas que negocien en cosas análogas, no podrá el propietario exigir la restitución, sin reembolsar al poseedor la cantidad que la cosa le hubiere costado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('867e0118-0952-4fd8-acb6-8eb8424d77a2', 'a0000000-0000-0000-0000-000000000001', '3f04952b-0dec-4f1e-a44d-31b86d9113d6', '641', 'Posesión de la herencia', 531, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf4480de-9f54-4daf-81a5-48302e2427c2', '867e0118-0952-4fd8-acb6-8eb8424d77a2', 1, 'La posesión de la herencia se adquiere desde el momento de la muerte del causante, aunque el heredero lo ignore. El que válidamente repudia una herencia, se entiende no haberla poseído jamás.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45a7124e-e7d3-40b3-be0f-68b6cc415e51', '867e0118-0952-4fd8-acb6-8eb8424d77a2', 2, 'DE LA USUCAPION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29386849-ee48-49ee-88a8-c5686c37916d', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '642', 'Quiénes pueden adquirir por usucapión', 532, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7bcbd16-9744-4393-9cf6-b5a82a0ac811', '29386849-ee48-49ee-88a8-c5686c37916d', 1, 'Pueden adquirir la propiedad por usucapión, todas las personas capaces para adquirir por cualquier otro título.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6d559640-62bd-4a62-b239-6335cbb74ba3', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '643', 'Cosas prescribibles', 533, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ba40f9b-f021-44a3-a338-4e3b025a455d', '6d559640-62bd-4a62-b239-6335cbb74ba3', 1, 'Son susceptibles de prescripción todas las cosas que están en el comercio de los hombres.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('faaf53e6-8a05-40c2-aea1-e9f42f967f1f', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '644', 'El derecho de prescribir es irrenunciable', 534, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d27fbaa7-d1bc-4363-8aa4-9c397618a3fc', 'faaf53e6-8a05-40c2-aea1-e9f42f967f1f', 1, 'Los que tienen capacidad para enajenar, pueden renunciar la prescripción consumada, pero el derecho de prescribir es irrenunciable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e1d798b2-fc5f-4a38-8038-f9c2d60367e4', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '645', NULL, 535, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba33d25d-ddab-49ad-9eb7-440b40796a8e', 'e1d798b2-fc5f-4a38-8038-f9c2d60367e4', 1, 'Los acreedores pueden utilizar la prescripción consumada que renuncia el adquiriente Los acreedores, y cualquiera otra persona interesada en hacer valer la prescripción, podrán utilizarla a pesar de la renuncia del adquirente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d138e5e3-3d98-4955-87d8-3f197c6c5c2e', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '646', NULL, 536, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27114e2f-f731-4cf1-ac10-9bf55ee1e8fd', 'd138e5e3-3d98-4955-87d8-3f197c6c5c2e', 1, 'La usucapión sólo favorece al que posee a nombre propio El que posee a nombre de otro no puede adquirir por prescripción la cosa poseída, a no ser que legalmente se haya mudado la causa de la posesión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('15c9fb50-b8e9-4fc2-af2e-c4db9549707c', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '647', 'Mudada la causa de la posesión', 537, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('273b1859-36d8-47f1-8573-0a03a27f1b2f', '15c9fb50-b8e9-4fc2-af2e-c4db9549707c', 1, 'Se dice mudada legalmente la causa de la posesión cuando el que poseía a nombre de otro, comienza a poseer legalmente a nombre propio; pero, en este caso, la prescripción no corre sino desde el día en que se haya mudado la causa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f020cb32-cf2d-41ad-8a69-7474be2aea14', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '648', 'Posesión común', 538, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8aa58501-8de9-4612-9b64-a9604d1f8c0b', 'f020cb32-cf2d-41ad-8a69-7474be2aea14', 1, 'Si varias personas poseen en común alguna cosa, no puede ninguna de ellas prescribir contra sus copropietarios o coposeedores, pero sí puede prescribir contra un extraño y, en este caso, la prescripción aprovecha a todos los partícipes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('428eaad8-4131-4896-9058-da324ed3912a', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '649', 'La prescripción no vale sin título', 539, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e82bdb1b-1751-4642-95d1-3154c43ddc65', '428eaad8-4131-4896-9058-da324ed3912a', 1, 'El que alega la prescripción, debe probar la existencia del título en que funda su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('547f0fd0-7c3e-48da-8a82-ea2f1435d46e', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '650', 'Efecto de la prescripción', 540, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('89a53c05-7bf4-4026-b0f4-335baf0f960e', '547f0fd0-7c3e-48da-8a82-ea2f1435d46e', 1, 'La prescripción una vez perfeccionada, produce el dominio de la cosa adquirida, y con la acción que nace de él, puede reivindicarse de cualquier poseedor y utilizarse como acción o excepción por el usucapiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3df62524-d9b8-4058-bbe0-cf92ca29a7e9', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '651', 'Prescripción de inmuebles y muebles', 541, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bec9a24f-9c19-472a-b1ba-8c463106f25b', '3df62524-d9b8-4058-bbe0-cf92ca29a7e9', 1, 'Salvo disposiciones especiales, el dominio sobre bienes inmuebles y demás derechos reales sobre los mismos, se adquiere por prescripción, por el transcurso de diez años. Los bienes muebles y semovientes, por el de dos años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '652', 'Casos en que no corre la prescripción', 542, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d4aa885-316f-4644-a049-e427173b145c', '887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 1, 'No corre la prescripción: 1. Contra los menores y los incapacitados, durante el tiempo que estén sin representante legal constituido. Los representantes serán responsables de los daños y perjuicios que por la prescripción se causen a sus representados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('103fa64f-8863-4825-9ab8-9e6368884f76', '887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 2, '2. Entre padres e hijos, durante la patria potestad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7b688354-b488-45f7-858a-9a3a529224ee', '887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 3, '3. Entre los menores e incapacitados y sus tutores, mientras dure la tutela;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('daa71d53-94fa-406a-9760-4cc01fec3211', '887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 4, '4. Entre los consortes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5c96bab-2950-492c-a32e-b3b55857210e', '887fd5d6-fe9a-4c5f-8aa5-5a3b18144d43', 5, '5. Entre copropietarios, mientras dure la indivisión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b369ef08-ffa8-400f-8670-123864776093', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '653', 'Interrupción de la prescripción', 543, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c260001f-ea00-4d3b-a5b9-fa6ced1f4b93', 'b369ef08-ffa8-400f-8670-123864776093', 1, 'La prescripción se interrumpe:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b35401ad-6bf2-459d-b68c-a08d64ef2cf4', 'b369ef08-ffa8-400f-8670-123864776093', 2, '1. Si el poseedor es privado de la posesión de la cosa, o del goce del derecho durante un año;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2db92c22-a1c5-4aa7-936c-fdd82d15610f', 'b369ef08-ffa8-400f-8670-123864776093', 3, '2. Por notificación de la demanda o por cualquier providencia precautoria ejecutada, salvo si el acreedor desistiere de la acción intentada, o el demandado fuere absuelto de la demanda, o el acto judicial se declare nulo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('353236aa-219c-45db-85eb-dd8eb15d8c44', 'b369ef08-ffa8-400f-8670-123864776093', 4, '3. Si la persona a cuyo favor corre la prescripción reconoce expresamente, de palabra o por escrito, o tácitamente por hechos indudables, el derecho de la persona contra quien prescribe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('12d4911a-aa9f-4f12-af73-d0a4f1bcdc78', 'a0000000-0000-0000-0000-000000000001', '0c19b9dc-c10a-4ec5-96eb-67e9e8afe747', '654', 'Efectos de la interrupción', 544, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77b2658e-338a-4cc2-a2ab-0c55a1a364a1', '12d4911a-aa9f-4f12-af73-d0a4f1bcdc78', 1, 'El efecto de la interrupción, es inutilizar, para la prescripción, todo el tiempo corrido antes de ella.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44342d01-f1ad-4af9-b8f9-9e7b98f0f528', '12d4911a-aa9f-4f12-af73-d0a4f1bcdc78', 2, 'DE LA ACCESION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8a838aef-4ace-4864-a312-08678ce0f737', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '655', 'Frutos naturales y civiles', 545, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('687a918e-668b-480b-a885-d65cb9a16cb7', '8a838aef-4ace-4864-a312-08678ce0f737', 1, 'Los frutos naturales y civiles pertenecen al propietario de la cosa que los produce.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2f132ef8-fa5e-4d4c-99ce-a90a5044a154', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '656', NULL, 546, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('daac99a5-f6a5-43a3-9343-01d45df1bb6a', '2f132ef8-fa5e-4d4c-99ce-a90a5044a154', 1, 'Son frutos naturales las producciones espontáneas de la tierra, las crías de los animales y demás productos que se obtengan con o sin la industria del hombre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6d64379e-83e0-4f9b-b201-b22af2e54d66', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '657', NULL, 547, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a681ccd7-a856-4cb2-9dc5-86125a762a68', '6d64379e-83e0-4f9b-b201-b22af2e54d66', 1, 'No se conceptúan frutos naturales sino los que están manifiestos, producidos o nacidos. Respecto de los animales, basta que estén en el vientre de la madre. La cría de los animales pertenece exclusivamente al dueño de la hembra, salvo que haya estipulación contraria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('945e631d-285b-4857-8d5e-67470aeee811', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '658', 'Accesión por incorporación a bienes inmuebles', 548, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c837c672-c489-493d-8b56-495960d4e580', '945e631d-285b-4857-8d5e-67470aeee811', 1, 'Lo que se une o se incorpora a una cosa pertenece al propietario de ésta, de conformidad con las disposiciones siguientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6af8364a-e3bf-4383-be0e-0a8d7c2c0909', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '659', NULL, 549, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42a01bd9-5f93-4a63-97d8-2bbeae2b910d', '6af8364a-e3bf-4383-be0e-0a8d7c2c0909', 1, 'Toda construcción, siembra, plantación u obra verificada sobre o debajo del suelo, se presume hecha por el propietario a sus expensas y que le pertenece.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f1b8656-a3ea-4f94-8404-ecb8509cf6c9', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '660', 'Accesión de mala fe con materiales ajenos', 550, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2525a2d5-a408-4980-b42e-c241fac79860', '4f1b8656-a3ea-4f94-8404-ecb8509cf6c9', 1, 'El propietario del suelo que ha hecho construcciones, plantaciones u obras con materiales ajenos, debe pagar al dueño el valor de éstos, y quedará también obligado, en caso de mala fe, al pago de los daños y perjuicios; pero el propietario de los materiales no tiene derecho de llevárselos, a menos que pueda hacerlo sin destruir la obra construida o sin que perezcan las plantaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88f76101-1fc5-4908-b3b6-3bc236bb5a71', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '661', 'Accesión de buena fe', 551, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd5ab834-9942-4b59-9ace-f3bf4eba882c', '88f76101-1fc5-4908-b3b6-3bc236bb5a71', 1, 'El dueño del terreno en que se edificare, sembrare o plantare de buena fe, tendrá derecho a hacer suya la obra, siembra o plantación, previa la indemnización correspondiente; o de obligar al que edificó o plantó a pagarle el precio del terreno, y al que sembró, solamente su renta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('acda0520-e673-4bf1-9f16-97fd77c1b204', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '662', 'Sembrador o edificador de mala fe', 552, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94af42af-3dfb-4b14-bb21-219f9299763a', 'acda0520-e673-4bf1-9f16-97fd77c1b204', 1, 'El que de mala fe edifica, planta o siembra en terreno ajeno, pierde lo edificado, plantado o sembrado, sin que tenga derecho a reclamar indemnización alguna del dueño del suelo, ni de retener la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ee946e4d-0109-4683-be27-9ce693b23990', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '663', 'Derecho del dueño', 553, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1a64f47-169d-4046-93b0-a690335d0aaa', 'ee946e4d-0109-4683-be27-9ce693b23990', 1, 'El dueño del terreno en que se haya edificado de mala fe, podrá pedir la demolición de la obra y la reposición de las cosas a su estado primitivo, a costa del edificador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9138dd53-639b-4257-a3cd-68ff5168ec6e', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '664', 'Mala fe de ambas partes', 554, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ba4b999-fa7b-4bdf-bde3-e659dc53d53a', '9138dd53-639b-4257-a3cd-68ff5168ec6e', 1, 'Cuando haya mala fe, no sólo por parte del que edificare, sino por parte del dueño del terreno, se entenderá compensada esta circunstancia y se arreglarán los derechos de uno y otro, conforme lo resuelto para el caso de haberse procedido de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16cb5e15-348d-4a0b-8b0c-34a24db0d51d', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '665', 'Cuando haya mala fe en el edificador o sembrador', 555, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7dfe5ec-8428-446e-9ebf-5f4d58449ba6', '16cb5e15-348d-4a0b-8b0c-34a24db0d51d', 1, 'Se entiende que hay mala fe de parte del edificador, plantador o sembrador, cuando hace la plantación, edificación o siembra en terreno que es ajeno, no pidiendo previamente al dueño su consentimiento por escrito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('481d2d44-ddb9-4ab9-af7e-c5de68826f58', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '666', 'Cuando hay mala fe en el dueño', 556, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b2acf9f-e39e-4b14-8f05-59297b168f5c', '481d2d44-ddb9-4ab9-af7e-c5de68826f58', 1, 'Se entiende haber mala fe por parte del dueño, siempre que a su vista o ciencia y paciencia se hicieren el edificio, la siembra o la plantación y no se opusiere a ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f73a46aa-4234-4761-88a9-780df6290997', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '667', 'Materiales y plantas pertenecientes a tercero', 557, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6e882e8a-3e73-446a-b17d-6b9a5f5d7b2b', 'f73a46aa-4234-4761-88a9-780df6290997', 1, 'Si los materiales, plantas o semillas pertenecen a un tercero que no ha procedido de mala fe, el dueño del terreno es responsable subsidiariamente del valor de aquellos objetos, siempre que concurran las dos circunstancias siguientes: 1. Que el que de mala fe empleó los materiales, plantas o semillas no tenga bienes con qué responder de su valor; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b1665cb3-5a87-44ee-9245-eb7d37b3ac97', 'f73a46aa-4234-4761-88a9-780df6290997', 2, '2. Que lo edificado, plantado o sembrado aproveche al dueño del terreno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('24d9f75b-7459-492e-ba37-ad603c06f5ca', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '668', NULL, 558, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff6ede40-d838-44ec-8a16-ff064277c9a5', '24d9f75b-7459-492e-ba37-ad603c06f5ca', 1, 'No tendrá lugar lo dispuesto en el artículo anterior, si el propietario usa del derecho que le concede el artículo 663.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a0c97a1-0a22-4601-b569-35e9ae5a9937', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '669', 'Accesiones ocasionadas por las aguas', 559, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c9295b10-9d0f-45c0-923d-ed3e22c7cc76', '4a0c97a1-0a22-4601-b569-35e9ae5a9937', 1, 'Son de dominio público los terrenos que se unen a la zona marítimo-terrestre por las accesiones y aterramientos que ocasione el mar. Cuando por consecuencia de estas accesiones y por efecto de retirarse el mar, la línea interior que limita la expresada zona avance hacia aquél, los');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f40ffe65-e1b0-4976-92c6-0b42eb3e6689', '4a0c97a1-0a22-4601-b569-35e9ae5a9937', 2, 'terrenos sobrantes de lo que era antigua zona marítimo-terrestre, pasarán a ser propiedad de la nación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83dc5514-2795-4db6-818a-209e6ceb535b', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '670', 'Propiedad de la nación', 560, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2841b14c-b39e-47e6-a3cf-eb0deca4fb43', '83dc5514-2795-4db6-818a-209e6ceb535b', 1, 'Son propiedad de la nación las islas ya formadas o que se formen en la zona marítimo-terrestre y en las rías y desembocaduras. Pero si estas islas se formaren en terrenos de propiedad particular, continuarán perteneciendo a los dueños de la finca o fincas desmembradas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a6fb1a67-0b31-46cb-b2ea-fa49717d3fa7', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '671', 'Dominio público', 561, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5bd80038-da74-42f4-a72e-746dd6410602', 'a6fb1a67-0b31-46cb-b2ea-fa49717d3fa7', 1, 'Es de dominio público lo que el mar arroje y no tenga dueño conocido, salvo lo dispuesto en el título relativo a ocupación y en leyes especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f3cf576-6a16-481a-88f6-1aea6cebc0ee', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '672', NULL, 562, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f5b56092-2371-4fd1-b72c-06d2ee46c750', '4f3cf576-6a16-481a-88f6-1aea6cebc0ee', 1, 'Los terrenos que fuesen accidentalmente inundados por las aguas de los lagos, o por los arroyos, ríos y demás corrientes, continuarán siendo propiedad de sus dueños respectivos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cb3ad1ae-59e9-441a-9d73-058b4dec46e5', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '673', 'Cauces de los ríos', 563, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20c3b041-2e45-48e9-95db-dfcbb6c64e6f', 'cb3ad1ae-59e9-441a-9d73-058b4dec46e5', 1, 'Los cauces de los ríos que queden abandonados por variar naturalmente el curso de las aguas, pertenecen a los dueños de los predios ribereños en toda la longitud respectiva. Si el cauce abandonado separaba heredades de distintos dueños, la nueva línea divisoria correrá equidistante de unas y otras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c8e22c74-491c-4027-b516-bae926afc2a6', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '674', 'Nuevo cruce del río', 564, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e945e6a-4fc7-4545-9211-d586276eb11b', 'c8e22c74-491c-4027-b516-bae926afc2a6', 1, 'Cuando en un río navegable o flotable, variando naturalmente de dirección, se abre un nuevo cauce en heredad privada, este cauce entrará en el dominio público. El dueño de la heredad lo recobrará siempre que las aguas vuelvan a dejarlo en seco, ya naturalmente o bien por trabajos legalmente autorizados al efecto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('12e4452b-7259-427f-86ed-30e32a292afb', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '675', 'Cauces abandonados', 565, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('21446b8c-6906-4784-96a1-03e437497e6c', '12e4452b-7259-427f-86ed-30e32a292afb', 1, 'Los cauces públicos que queden en seco a consecuencia de trabajos autorizados por concesión especial, formarán parte de ésta, si no se establece otra cosa en las condiciones con que se hizo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b47c0d3d-e29f-4b2a-987c-4aa5885f50fd', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '676', 'Avulsión', 566, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c2eab19-7eab-44bc-bebf-57025e56d268', 'b47c0d3d-e29f-4b2a-987c-4aa5885f50fd', 1, 'Cuando la corriente de un arroyo, torrente o río segrega de su ribera una porción conocida de terreno, y la transporta a las heredades fronteras o a las inferiores, el dueño de la finca que orillaba la ribera segregada conserva la propiedad de la porción de terreno incorporado; pero si dentro del término de seis meses no ejercitare su derecho, lo perderá en favor del dueño del terreno a que se hubiere agregado la porción arrancada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('de7314d8-db05-4634-9fab-3f3df69a1e0f', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '677', NULL, 567, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('240fe0dd-1068-4df9-a309-65df4c251322', 'de7314d8-db05-4634-9fab-3f3df69a1e0f', 1, 'Si la porción conocida de terreno segregado de una ribera queda aislada en el cauce, continúa perteneciendo al dueño del terreno cuya ribera fue segregada. Lo mismo sucederá cuando dividiéndose un río en arroyos, circunde y aisle algunos terrenos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6616ee28-afc4-472a-ae64-e589f391b004', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '678', 'Formación de islas', 568, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0805e1c-2a6a-4dba-9d3c-d29314533308', '6616ee28-afc4-472a-ae64-e589f391b004', 1, 'Las islas que, por sucesiva acumulación de arrastres superiores, se van formando en las rías, pertenecen a los dueños de las');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db93af27-5213-41bd-a35e-7d749822e7c5', '6616ee28-afc4-472a-ae64-e589f391b004', 2, 'márgenes u orillas más cercanas a cada una, o a las de ambas márgenes si la isla se hallase en medio río, dividiéndose entonces longitudinalmente por la mitad. Si una sola isla así formada, distare de una margen más que de otra, será únicamente y por completo dueño suyo el de la margen más cercana.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('27620417-42de-49c2-8495-29d4288ad414', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '679', 'Aluvión', 569, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7bdce5f-867e-451a-be85-80d87ba355c7', '27620417-42de-49c2-8495-29d4288ad414', 1, 'Pertenece a los dueños de los terrenos confinantes con los arroyos, torrentes, ríos y lagos, el acrecentamiento que reciban paulatinamente por accesión o sedimentación de las aguas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ea1ff63-b7fc-4a3b-870f-f5da597581c0', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '680', 'Bienes mostrencos', 570, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6705c9d6-464d-4f1b-8431-d83bd8f22c89', '9ea1ff63-b7fc-4a3b-870f-f5da597581c0', 1, 'Cualquiera puede recoger y salvar los animales, maderas, frutos, muebles y otros productos de la industria arrebatados por las corrientes de las aguas públicas o sumergidos en ellas, presentándolos inmediatamente a la autoridad local, que dispondrá su depósito o su venta en pública subasta, cuando no puedan conservarse. Se anunciará en seguida el hallazgo, y si dentro de los tres meses hubiere reclamación por parte del dueño, se le entregará el objeto o su precio, previo abono de los gastos de conservación y el derecho de salvamento, que consistirá en un 10 por ciento. Transcurrido aquel plazo sin haber reclamado el dueño, perderá éste su derecho, y se devolverá todo a quien lo salvó, previo abono de los gastos de conservación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d71c96e-bb2c-4184-b27d-a03da9b56694', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '681', 'Brozas, ramas y leñas flotantes', 571, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b635af40-4729-43b2-b847-be0c0835a38e', '4d71c96e-bb2c-4184-b27d-a03da9b56694', 1, 'Las brozas, ramas y leñas que vayan flotando en las aguas o sean depositadas por ellas en el cauce o en terreno de dominio público, son del primero que las recoja. Las dejadas en terrenos de dominio privado, son del dueño de la finca respectiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38a38911-6237-4674-b55c-82d33df4ea57', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '682', 'Árboles arrancados por las aguas', 572, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca30362f-9493-42bf-83cb-03fca8025af7', '38a38911-6237-4674-b55c-82d33df4ea57', 1, 'Los árboles arrancados y transportados por la corriente de las aguas, pertenecen al propietario del terreno a donde vinieren a parar, si no los reclaman dentro de un mes sus antiguos dueños, quienes deberán abonar los gastos ocasionados en recoger los árboles o ponerlos en lugar seguro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ee78f94a-da51-4f13-a65e-d9da2c43ddd4', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '683', 'Objetos sumergidos en los causes públicos y privados', 573, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d200aed8-bea9-4d47-8767-b6290669a903', 'ee78f94a-da51-4f13-a65e-d9da2c43ddd4', 1, 'Los objetos sumergidos en los cauces públicos siguen perteneciendo a sus dueños, pero si en el término de seis meses no los extrajeren, serán de las personas que verifiquen la extracción, previo el permiso de la autoridad. Si los objetos sumergidos ofrecieren obstáculos a las corrientes o al tránsito, se concederá por la autoridad un término prudente a los dueños, transcurrido el cual sin que hagan uso de su derecho, se procederá a la extracción como de cosa abandonada. El dueño de objetos sumergidos en aguas de propiedad particular, solicitará del dueño de éstas el permiso para extraerlos; y en el caso de que éste lo negare, concederá el permiso la autoridad, previa fianza de daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5021abfe-effd-47d3-8666-73f9fb78e338', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '684', 'Defensa contra las aguas', 574, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4685fc0-0456-4292-a097-26f83fec2a9a', '5021abfe-effd-47d3-8666-73f9fb78e338', 1, 'Los dueños de predios lindantes con cauces públicos, tienen libertad de poner defensas contra las aguas en sus respectivas');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed500c8e-c768-47b9-8ae9-d731f092d873', '5021abfe-effd-47d3-8666-73f9fb78e338', 2, 'márgenes, por medio de plantaciones, estacadas o revestimientos, siempre que lo juzguen conveniente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ce98c7d6-eef6-4110-93d9-412c33bb873a', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '685', 'Terrenos pantanosos', 575, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3de5f1be-da98-4377-afce-f622c1fcaa09', 'ce98c7d6-eef6-4110-93d9-412c33bb873a', 1, 'Los dueños de lagunas o terrenos pantanosos y encharcadizos, que quieran desecarlos o sanearlos, podrán extraer de los terrenos públicos la tierra y piedra indispensables para el terraplén y demás obras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('649efd54-1a2a-4dc5-9062-1d4713db6751', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '686', 'Accesión por incorporación a bienes muebles', 576, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f30b1b63-6282-414d-95c6-c652a5e76c8a', '649efd54-1a2a-4dc5-9062-1d4713db6751', 1, 'Cuando dos cosas muebles pertenecientes a dueños distintos, se unen de tal manera que vienen a formar una sola, sin que intervenga mala fe, el propietario de la principal adquiere lo accesorio, pagando su valor. Se reputa principal, entre dos cosas incorporadas, la de mayor valor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5177f397-3329-4c55-9f69-c43383758eed', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '687', 'Cosa principal', 577, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e145c6ab-03d1-4930-b1b6-ef5d803135d0', '5177f397-3329-4c55-9f69-c43383758eed', 1, 'Si no pudiere hacerse la calificación conforme a la regla establecida en el artículo que precede, se reputará principal el objeto cuyo uso, perfección o adorno, se haya conseguido por la unión del otro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d6eac790-3e9a-4aa1-8db8-78fb48789d2d', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '688', 'Cosa accesoria', 578, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f29e3d8-c7ab-463b-a3ed-f262b75c575f', 'd6eac790-3e9a-4aa1-8db8-78fb48789d2d', 1, 'En la pintura, escultura y bordado; en los escritos, impresos, grabados y litografías, se estima por accesorio, la tabla, el metal, la piedra, el lienzo, el papel o el pergamino.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('97f8a481-5bce-4f26-b37a-bbd4e7ded3de', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '689', 'Cosas que pueden separarse', 579, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('04ea7cdc-bacd-4916-bebb-859e94390fdb', '97f8a481-5bce-4f26-b37a-bbd4e7ded3de', 1, 'Cuando las cosas unidas pueden separarse sin detrimento, y subsistir independientemente, los dueños respectivos tienen derecho de exigir la separación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2879f30f-f1c8-4343-9a46-f77976a5dcc9', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '690', 'Cosas que no pueden separarse', 580, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15c21415-a4c3-4699-b8c9-02d70deed359', '2879f30f-f1c8-4343-9a46-f77976a5dcc9', 1, 'Cuando las cosas no pueden separarse sin que la que se reputa accesoria sufra deterioro, el dueño de la principal tendrá también derecho a pedir la separación; pero quedará obligado a indemnizar al dueño de la accesoria, siempre que éste haya procedido de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('991c6a33-0e5c-4e24-b5e9-cb8423fd8cf9', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '691', 'Pérdida de lo accesorio por mala fe de su dueño', 581, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a6bc51fc-3c79-4d33-89de-15e5cbfbed91', '991c6a33-0e5c-4e24-b5e9-cb8423fd8cf9', 1, 'Cuando el dueño de la cosa accesoria es el que ha hecho la incorporación, la pierde si ha obrado de mala fe; y está, además, obligado a indemnizar al propietario de la principal, de los perjuicios que se le hayan seguido por la incorporación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e2ea32e0-75bd-4683-abda-793575e39bd9', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '692', 'Mala fe del dueño de la cosa principal', 582, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1c2435e-2237-493e-89d0-9fe8ae69e9fe', 'e2ea32e0-75bd-4683-abda-793575e39bd9', 1, 'Si el dueño de la cosa principal es el que ha procedido de mala fe, el que lo sea de la accesoria, tendrá derecho a que se le pague su valor y se le indemnice de los daños y perjuicios, o que la cosa de su pertenencia se separe, aunque para ello haya de destruirse la principal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ae71f495-3053-4983-a111-ff92521cfcb3', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '693', 'Incorporación sin oposición', 583, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('23240fd4-f1d0-4e08-9e90-68baa525a07d', 'ae71f495-3053-4983-a111-ff92521cfcb3', 1, 'Si la incorporación se hace por cualquiera de los dueños, a la vista o ciencia y paciencia del otro, sin que éste se oponga, los derechos respectivos se arreglarán conforme a lo dispuesto en el artículo 686.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63689bac-816c-40c6-a7a2-01a8dffc0512', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '694', 'Derecho de indemnización', 584, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6d8ab826-4e8a-4f71-a01a-f868908a292c', '63689bac-816c-40c6-a7a2-01a8dffc0512', 1, 'Siempre que el dueño de la materia empleada tenga derecho a indemnización, podrá exigir que ésta consista en la entrega de una cosa igual en valor y en todas sus circunstancias a la empleada, o bien en el precio de ella, fijado por expertos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fb300f7-c069-4131-8116-e72f158aa4a2', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '695', 'Mezcla de cosas no separables sin detrimento', 585, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ecf961c-9fde-484c-a82f-e56f54f3afc2', '6fb300f7-c069-4131-8116-e72f158aa4a2', 1, 'Si se mezclan dos cosas de igual o diferente especie por voluntad de sus dueños o por casualidad, y las cosas no son separables sin detrimento, el propietario en cuyo poder se haya verificado la confusión o mezcla, podrá adquirir para sí la cosa mezclada o confundida, reintegrando al otro propietario el valor proporcional a la parte que le corresponda. Si la mezcla se verificare en poder de un tercero, cada propietario adquirirá un derecho proporcional a la parte que le corresponda, atendiendo al valor de las cosas mezcladas o confundidas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9eae9ec3-7bbc-44b1-8052-7b8613f5c6b9', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '696', NULL, 586, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6219afb2-5b4a-4226-a73c-1e5d659168f2', '9eae9ec3-7bbc-44b1-8052-7b8613f5c6b9', 1, 'Si por voluntad de uno solo, pero con buena fe, se mezclan o confunden dos cosas de igual o diferente especie, los derechos de los propietarios se arreglarán por lo dispuesto en el artículo anterior; a no ser que el dueño de la cosa mezclada sin su consentimiento, prefiera la indemnización de daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b52c15a8-8068-43e9-bad9-b5fd6eec88ad', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '697', 'Mezcla de mala fe', 587, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48e041e4-5e5a-417f-be46-a0a33cf53737', 'b52c15a8-8068-43e9-bad9-b5fd6eec88ad', 1, 'El que de mala fe hace la mezcla o confusión, pierde la cosa mezclada o confundida que fuere de su propiedad y queda, además obligado a la indemnización de los perjuicios causados al dueño de la cosa o cosas con que se hizo la mezcla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8ead3667-650c-426c-a2cf-0b33808706fe', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '698', 'Empleo de materia ajena', 588, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8358fe5c-11b1-41a2-990f-1ced39178c9a', '8ead3667-650c-426c-a2cf-0b33808706fe', 1, 'El que de buena fe empleó materia ajena en todo o en parte para formar una cosa de nueva especie, hará suya la obra, siempre que el mérito artístico de ésta exceda en precio a la materia cuyo valor indemnizará al dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('23c80972-d57b-41b5-aafe-614fc8c71316', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '699', NULL, 589, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa578c7e-0322-4d35-a0f2-e899cb40e61f', '23c80972-d57b-41b5-aafe-614fc8c71316', 1, 'Cuando el mérito artístico de la obra sea inferior en precio a la materia, el dueño de ésta hará suya la nueva especie y tendrá derecho, además de reclamar indemnización de daños y perjuicios, descontándose del monto de éstos el valor de la obra, a tasación de expertos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2722fec4-3229-42b4-9358-d69043c041fc', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '700', NULL, 590, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12d577b0-5b52-4de9-8619-863e6d965ee1', '2722fec4-3229-42b4-9358-d69043c041fc', 1, 'Si la nueva especie se hizo de mala fe, el dueño de la materia empleada tiene el derecho de quedarse con la obra, sin pagar nada al que la hizo; o de exigir de éste que le pague el valor de la materia y lo indemnice de los perjuicios que se le hayan seguido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('db361a19-98c9-4984-afb0-650456766652', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '701', 'Mala fe en mezcla o confusión', 591, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f78e5d18-423c-4cd9-8c49-ee1bdc24cd6f', 'db361a19-98c9-4984-afb0-650456766652', 1, 'La mala fe, en los casos de mezcla o confusión, se calificará conforme a lo dispuesto en los artículos 665 y 666 de este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('efd1379e-cbe2-4f5b-b1e3-01ec43edc1bd', 'a0000000-0000-0000-0000-000000000001', '73f0a656-840b-4c3d-8376-6cbb1856d925', '702', NULL, 592, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38a8a0a1-bb4b-4b86-89d6-82b8f3e9f383', 'efd1379e-cbe2-4f5b-b1e3-01ec43edc1bd', 1, 'Cuando la cosa se haga común entre los propietarios de las materias de que se haya formado, cada uno de ellos podrá pedir su venta por cuenta de los interesados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f750048-b642-4ef2-8154-fdaaf45009c6', 'efd1379e-cbe2-4f5b-b1e3-01ec43edc1bd', 2, 'USUFRUCTO, USO Y HABITACION');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aebf7602-eea2-4220-a5d7-0cfa163b2336', 'efd1379e-cbe2-4f5b-b1e3-01ec43edc1bd', 3, 'DERECHOS Y OBLIGACIONES DEL USUFRUCTUARIO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('32dd8864-43ad-4615-bf6f-e7e889cee0be', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '703', 'Extensión del usufructo', 593, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('630985c7-c96a-4d04-8691-2fe70cc96ba9', '32dd8864-43ad-4615-bf6f-e7e889cee0be', 1, 'Pertenecen al usufructuario los frutos naturales y civiles que los bienes produzcan ordinaria y extraordinariamente, salvo las limitaciones establecidas en el título en que se constituya.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8129f572-fdf7-47c7-b19c-d6717b015336', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '704', 'Forma de constitución', 594, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f11dde7-b39f-4af4-bc80-bb7c94ed181f', '8129f572-fdf7-47c7-b19c-d6717b015336', 1, 'El usufructo se constituye por contrato o por acto de última voluntad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e6df05b8-b678-4779-bc9f-f18c7ac288c7', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '705', 'Duración del usufructo', 595, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('85595d31-b7af-4240-a01f-7670bcf07464', 'e6df05b8-b678-4779-bc9f-f18c7ac288c7', 1, 'El usufructo puede constituirse por tiempo fijo, vitalicio, puramente o bajo condición, pero no a perpetuidad, y sobre toda especie de bienes muebles e inmuebles. Asimismo puede constituirse a favor de personas jurídicas, o de una o varias personas individuales, simultánea o sucesivamente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5828d0cd-9dab-4793-8703-cc921768b38d', 'e6df05b8-b678-4779-bc9f-f18c7ac288c7', 2, 'En caso de disfrute sucesivo, el usufructo sólo aprovechará a las personas que existan cuando concluya el derecho del anterior usufructuario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('de5b804d-9371-4757-b24d-a2c5f8c727fc', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '706', 'El usufructo no puede exceder de treinta años', 596, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('815d7e40-d1ce-45ea-9755-b5b2508b2511', 'de5b804d-9371-4757-b24d-a2c5f8c727fc', 1, 'Cuando en la constitución del usufructo no se fije tiempo para su duración, se entiende constituido por toda la vida del usufructuario. El usufructo que no sea vitalicio y el constituido a favor de personas jurídicas no podrá exceder de treinta años, salvo que se trate de bienes nacionales, en cuyo caso podrá ser hasta por cincuenta años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b547fbf1-c755-472b-a8c5-273387135ef5', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '707', NULL, 597, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb4af760-dd2e-4a78-9147-0f4e4f58343b', 'b547fbf1-c755-472b-a8c5-273387135ef5', 1, 'No hay derecho de acrecer Si se constituye el usufructo a favor de varias personas simultáneamente, sea por herencia o por contrato, no hay derecho de acrecer, si el constituyente no la ha establecido clara y expresamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('471498f8-3a77-4aa1-bb33-3755c7ab669e', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '708', 'Derechos de los acreedores', 598, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7232363b-1939-4a0d-8aba-6e8d464ceb40', '471498f8-3a77-4aa1-bb33-3755c7ab669e', 1, 'Los acreedores del usufructuario pueden embargar los productos del usufructo y oponerse a toda cesión o renuncia de éste que se haga en fraude de aquéllos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f02c8a8f-775e-4df1-aaa5-c26c841ab39d', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '709', 'Derecho del usufructuario', 599, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1708917c-b94a-4071-b704-8c921f53e873', 'f02c8a8f-775e-4df1-aaa5-c26c841ab39d', 1, 'Los frutos naturales pendientes al tiempo de comenzar el usufructo, pertenecen al usufructuario, salvo las obligaciones a que tales frutos estén afectos con anterioridad. Los pendientes al tiempo de extinguirse el usufructo, pertenecen al propietario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('badde57c-143a-4a8a-bf34-a3d61e6f1ca4', 'f02c8a8f-775e-4df1-aaa5-c26c841ab39d', 2, 'El dueño de los frutos pendientes al constituirse o al terminarse el usufructo, es quien debe pagar los gastos de cultivo del año rural correspondiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8186e99d-7592-4835-98d3-3ee6db9c6a68', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '710', 'Los frutos civiles pertenecen al usufructuario día por día', 600, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('079c464f-5fe1-4428-955f-75d21f1bf01e', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '711', NULL, 601, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52159fa9-4ce4-4c87-92a5-860dd7dc52bf', '079c464f-5fe1-4428-955f-75d21f1bf01e', 1, 'El usufructuario de cosas muebles que se gastan y deterioran lentamente con el uso, tiene derecho a servirse de ellas según su naturaleza y destino; y al fin del usufructo, no está obligado a restituirlas sino en el estado en que se hallen, respondiendo solamente de aquellas pérdidas o deterioros que provengan de dolo o culpa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c0e12c2-06e7-434e-99f0-adfe44f23d58', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '712', NULL, 602, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a489ee6-73a7-43b0-b05d-beefbfc8c1c3', '7c0e12c2-06e7-434e-99f0-adfe44f23d58', 1, 'El usufructo de una heredad se extiende a sus bosques y arboledas, pero el usufructuario debe conservarlos y reponer los árboles que derribe, sujetándose en la explotación, a las disposiciones de las leyes forestales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('744847dd-2b18-4ed8-ade2-1c8143078e32', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '713', 'Obligación de restituir', 603, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db89a07d-f515-4a04-aa66-2232bd43d701', '744847dd-2b18-4ed8-ade2-1c8143078e32', 1, 'Si el usufructo comprende cosas que no pueden usarse sin consumirse, el usufructuario está obligado a restituirlos en igual género, cantidad y calidad; y si esto no fuere posible, a pagar su valor si se hubiesen dado estimadas, o su precio corriente al tiempo de cesar el usufructo, si no fueron estimadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aa1d637a-f4dd-4e8e-9ce6-45c6f7df7563', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '714', 'Usufructo sobre capitales', 604, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba3dfdc5-278c-4b97-8efb-a9ce161d912c', 'aa1d637a-f4dd-4e8e-9ce6-45c6f7df7563', 1, 'Si el usufructo se constituye sobre capitales puestos a rédito, el usufructuario hace suyo éste y no aquéllos; pero en toda novación o convenio que modifique la obligación primitiva, se necesita el consentimiento del usufructuario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af050164-af19-4912-9db5-d97ab2d0cb4b', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '715', 'Goce de la accesión', 605, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac39572c-8f9a-4918-841d-6cf32b063977', 'af050164-af19-4912-9db5-d97ab2d0cb4b', 1, 'El usufructuario puede gozar del aumento que sobrevenga por accesión a la cosa usufructuada, de las servidumbres y, en general, de todos los derechos de que gozaría el propietario. Goza también del producto de las minas y canteras que se estén explotando al empezar el usufructo, que perteneciere al propietario, pero no del de las nuevas minas que se descubran, ni del tesoro que se encuentre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('96eea9e1-5d9f-4a15-8408-cce9ca0f212e', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '716', 'Enajenación del usufructo', 606, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('90b7bdd1-bebd-4838-81de-b61ba5c5978a', '96eea9e1-5d9f-4a15-8408-cce9ca0f212e', 1, 'El usufructuario puede gozar por sí mismo de la cosa usufructuada, arrendarla a otro, y, enajenar su derecho de usufructo, salvo lo dispuesto en el artículo 708, pero todos los contratos que como tal usufructuario celebre, terminarán al fin del usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca809f86-ac39-4def-b033-98dc6fbd8cd8', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '717', NULL, 607, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c1ddd3f-fa4a-47a2-a5e6-323bfd62ceab', 'ca809f86-ac39-4def-b033-98dc6fbd8cd8', 1, 'El usufructuario no tiene derecho a que se le abonen las mejoras que hiciere en la cosa usufructuada, pero sí lo tendrá para que le sean compensadas con los deterioros que se le puedan imputar. En cuanto a las mejoras separables sin detrimento de la cosa, el usufructuario podrá llevárselas si el propietario no le abonare su valor. Lo dispuesto en este artículo, se entiende sin perjuicio de las convenciones que hayan celebrado el usufructuario y el propietario, relativas a mejoras, o de lo que sobre esta materia se haya previsto en la constitución del usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7483fb3-9677-44db-9029-f7f7587beab4', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '718', 'Cesión del usufructo', 608, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bb23c6f-eaed-4acd-b527-33be9cd59dd8', 'b7483fb3-9677-44db-9029-f7f7587beab4', 1, 'Cedido el usufructo a un tercero, el cedente y el cesionario serán solidariamente responsables al propietario de la cosa usufructuada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f08a2041-1426-40bd-a81f-9c1e1f584023', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '719', 'Servidumbres', 609, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('326cebe9-90fd-4059-968b-c8381145ab20', 'f08a2041-1426-40bd-a81f-9c1e1f584023', 1, 'El usufructuario no puede constituir servidumbres perpetuas sobre la finca que usufructúa; las que constituya cesarán al terminar el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3e7c8b8-9feb-48b1-9db9-3de8782f0428', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '720', 'Obligaciones del usufructuario', 610, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1679b7e-a8ac-4f2c-a533-a841f8f99fb1', 'd3e7c8b8-9feb-48b1-9db9-3de8782f0428', 1, 'El usufructuario tomará las cosas en el estado en que se encuentran; pero no podrá entrar en posesión de ellas, sin hacer previo inventario de los muebles y descripción del estado de los inmuebles, con citación del propietario. Los gastos inherentes a este acto serán a cargo del usufructuario. Cuando haya sido relevado el usufructuario de las obligaciones de que trata este artículo, el propietario tendrá derecho de hacer que se lleven a cabo a sus expensas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9dc6595b-b0b5-411d-82c0-208ad7c5b9d7', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '721', 'Garantía', 611, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bc55012-b5b1-4e35-8800-02f130b3e21e', '9dc6595b-b0b5-411d-82c0-208ad7c5b9d7', 1, 'El usufructuario debe garantizar el buen uso de su derecho, a satisfacción del propietario. No están obligados a prestar garantía el donante con reserva de usufructo y el que hubiere sido dispensado de tal obligación por el instituyente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c6543258-bf97-43e4-b9e3-01007ac66137', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '722', 'Derecho del propietario si no se presta garantía', 612, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('903c3b8a-0eb5-43f5-94a7-333e0a24db37', 'c6543258-bf97-43e4-b9e3-01007ac66137', 1, 'Si el usufructuario no presta garantía en los casos en que deba darla, podrá el propietario exigir que los inmuebles se pongan en administración, que los muebles se vendan, que los efectos públicos, títulos de crédito nominativos y al portador, se depositen en un banco u otra institución de crédito, y que los capitales o sumas en metálico y el precio de la enajenación de los bienes muebles se inviertan en valores seguros. El interés del precio de las cosas muebles y de los efectos públicos y valores, y los productos de los bienes puestos en administración, pertenecen al usufructuario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6dadb21f-2b72-4943-aed6-9b75b1c05ae5', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '723', 'Administración por el propietario', 613, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18a14208-454d-489b-8743-e10fdb1056c8', '6dadb21f-2b72-4943-aed6-9b75b1c05ae5', 1, 'También podrá el propietario, si lo prefiere, mientras el usufructuario no preste garantía, o quede dispensado de ella, retener en su poder los bienes del usufructo, en calidad de administrador, con la obligación de entregar al usufructuario su producto líquido, deducida la suma que por dicha administración se convenga o judicialmente se señale. El administrador podrá ser removido por mala administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5b3dc41f-0a88-461f-845b-27720b64fcd1', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '724', 'Recobro de la administración por el usufructuario', 614, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37bc2dfb-51eb-48f4-b4ab-d6662a03e67f', '5b3dc41f-0a88-461f-845b-27720b64fcd1', 1, 'El retardo en dar garantía no priva al usufructuario del derecho sobre los frutos y puede en todo tiempo, respetando los actos legalmente ejecutados, reclamar la administración, prestando la garantía a que está obligado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f1c5c9c4-1af8-4a42-ac58-00cc565b39e9', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '725', 'Abuso del usufructuario', 615, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36df5a5a-3034-45af-956a-8dc0970fa625', 'f1c5c9c4-1af8-4a42-ac58-00cc565b39e9', 1, 'El usufructuario tiene la obligación de dar garantía aun cuando no haya estado obligado a ella por el título constitutivo del');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0a8dd4d-374e-441e-b73d-d270de128577', 'f1c5c9c4-1af8-4a42-ac58-00cc565b39e9', 2, 'usufructo, si abusa causando deterioros en el fundo o dejándolo destruirse por falta de reparación, así como cuando por el cambio de circunstancias personales del usufructuario, no ofrece éste las mismas seguridades que al constituirse el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c172b4c4-de26-4fce-88d3-a6e2bb6995b1', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '726', 'Reparaciones ordinarias', 616, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0c8615ca-467c-4daf-a518-c5a7206aa8d2', 'c172b4c4-de26-4fce-88d3-a6e2bb6995b1', 1, 'El usufructuario debe hacer las reparaciones ordinarias indispensables para la conservación de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('116d5bff-3968-48b8-b12c-e19c8a93622b', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '727', 'Reparaciones extraordinarias', 617, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d75e2a6-e8e3-4028-94c6-0dfac53cba82', '116d5bff-3968-48b8-b12c-e19c8a93622b', 1, 'Las reparaciones extraordinarias serán a cargo del propietario. El usufructuario está obligado a darle aviso, cuando fuere urgente la necesidad de hacerlas.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a6d5a71-fe76-4515-8227-361bba8fec12', '116d5bff-3968-48b8-b12c-e19c8a93622b', 2, 'Son reparaciones extraordinarias las que se necesitan para restablecer o reintegrar los bienes que se hayan arruinado o deteriorado por vejez, caso fortuito o accidente no imputable al usufructuario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3f226761-f79b-4cd2-b8bb-1b9bbc3b8c8c', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '728', 'Aviso que debe dar el usufructuario', 618, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1bed7074-7377-4827-9271-4d804d01fe9c', '3f226761-f79b-4cd2-b8bb-1b9bbc3b8c8c', 1, 'La omisión del aviso oportuno al propietario, hace responsable al usufructuario de la destrucción, pérdida o menoscabo de la cosa por falta de las reparaciones. Si por la urgencia del caso fuere necesaria la pronta reparación antes de dar aviso al propietario, y la hiciere el usufructuario, éste tendrá derecho a que se le abone su valor, siempre que diere el aviso inmediatamente después de dar principio a la obra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('846f9c11-87b2-45d4-a5ee-c3d04ada56d0', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '729', 'Reparaciones hechas por el propietario', 619, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd4444b8-e3d6-4fc6-9c0a-77a4b5a39a50', '846f9c11-87b2-45d4-a5ee-c3d04ada56d0', 1, 'Si el propietario hiciere las reparaciones extraordinarias, tendrá derecho a exigir del usufructuario, el interés legal de la cantidad invertida en ellas, mientras dure el usufructo. Si no las hiciere cuando fueren indispensables para la conservación de la cosa, podrá hacerlas el usufructuario, pero tendrá derecho a exigir del propietario, al concluir el usufructo, el reembolso de su valor, sin intereses.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dddcef0c-863f-4c57-ac56-a3495ced8350', '846f9c11-87b2-45d4-a5ee-c3d04ada56d0', 2, 'Si el propietario se negare a satisfacer dicho importe, tendrá el usufructuario derecho a retener la cosa hasta reintegrarse con sus productos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4eeafe6b-c404-4d19-8ad3-a81971cd79ee', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '730', NULL, 620, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05d5a515-c26a-4e45-9381-c08f7e3a744c', '4eeafe6b-c404-4d19-8ad3-a81971cd79ee', 1, 'Las disposiciones de los artículos que preceden se aplican también cuando por vejez, o por caso fortuito, se arruina solamente en parte el edificio que formaba un accesorio necesario para el goce del fundo sujeto al usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b941ca68-28cd-4c43-b64b-f16b516cb558', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '731', 'Carga que soporta el usufructuario', 621, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad2272d7-ee6c-47ba-aef4-7b410e33b635', 'b941ca68-28cd-4c43-b64b-f16b516cb558', 1, 'Cuando el usufructo sea a título gratuito, el usufructuario está obligado a soportar todos los impuestos y contribuciones que pesen sobre la cosa usufructuada; pero si fuere constituido a título oneroso, el usufructuario sólo estará obligado a pagar los impuestos que impliquen servicios para el goce de la cosa usufuctuada.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f55ede0-79d1-4bf6-a5c0-dd5f92f9f64a', 'b941ca68-28cd-4c43-b64b-f16b516cb558', 2, 'Lo dispuesto en este artículo es sin perjuicio de lo pactado al constituirse el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a1a518c1-e1ea-4877-a5c8-7f3dc9d50a62', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '732', 'Ejecución de la finca', 622, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb1a5414-21f0-4571-812d-dc2103f52b1a', 'a1a518c1-e1ea-4877-a5c8-7f3dc9d50a62', 1, 'Si la finca se embarga o vende judicialmente para el pago de una deuda del propietario, el usufructo no será perjudicado sino por los gravámenes o actos anteriormente inscritos o anotados en el Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6b64c863-6def-4b5d-b20f-63a98ecd7e03', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '733', 'Usufructo de patrimonio', 623, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cde88c6e-25ba-47bf-9990-dd04317e25b4', '6b64c863-6def-4b5d-b20f-63a98ecd7e03', 1, 'El usufructuario de un patrimonio, o de una parte del patrimonio, estará obligado al pago total o proporcional a su parte de todas las anualidades de rentas vitalicias, y de los intereses de todas las deudas o legados que graven el patrimonio. Cuando se trate del pago de un capital, si el usufructuario adelantare la cantidad con que debe contribuir la cosa usufructuada, se le restituirá aquél, sin intereses, al terminar el usufructo. Si el usufructuario no quisiere hacer este adelanto, tendrá derecho el propietario a elegir entre el pago de la cantidad adeudada o hacer vender una porción de los bienes sujetos al usufructo, hasta la concurrencia de la cantidad debida.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('046ef287-50f6-40a2-8433-15a404b99f1a', '6b64c863-6def-4b5d-b20f-63a98ecd7e03', 2, 'En el primer caso, el usufructuario debe abonarle el interés durante el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('24e7bd6e-3f8c-40b9-a4eb-a3409651470e', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '734', 'Derechos del propietario perturbados por un tercero', 624, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7c3a9f4-ebae-44cf-9f6a-20d3480d1184', '24e7bd6e-3f8c-40b9-a4eb-a3409651470e', 1, 'Si los derechos del propietario son perturbados por un tercero, sea del modo y por el motivo que fuere, el usufructuario está obligado a ponerlo en conocimiento de aquél; y si no lo hace, es responsable de los daños que resulten, como si hubiesen sido ocasionados por su culpa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c3718a0-b739-4351-9405-cc4d468c0fc1', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '735', 'Costas de los pleitos', 625, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7b9a2c6-d8cf-47c7-964d-462e211b3bfe', '7c3718a0-b739-4351-9405-cc4d468c0fc1', 1, 'Los gastos, costas y condenas de los pleitos sostenidos con motivo del usufructo, son de cuenta del propietario, si el usufructo se ha constituido por título oneroso; y del usufructuario, si se ha constituido por título gratuito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ac97c7bf-e2b9-4a5c-920c-af1433eab8cd', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '736', NULL, 626, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a80aa30-2794-4e82-8d8c-0828876a0669', 'ac97c7bf-e2b9-4a5c-920c-af1433eab8cd', 1, 'Si el pleito interesa al mismo tiempo al dueño y al usufructuario, contribuirán a los gastos en proporción a sus derechos respectivos, si el usufructo se constituyó a título gratuito; pero el usufructuario, en ningún caso está obligado a responder por más de lo que produce el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ba61515-a655-47a1-9301-2625c32127af', 'a0000000-0000-0000-0000-000000000001', '84558b14-21f3-4610-b11d-4e895a4dd82d', '737', 'Usufructo sobre animales', 627, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('23a3f631-2bcd-4403-a05b-bbadf5b3fd92', '7ba61515-a655-47a1-9301-2625c32127af', 1, 'Si el usufructo está constituido sobre animales y éstos perecen sin culpa del usufructuario, sólo estará obligado para con el propietario a darle cuenta de las pieles o de su valor; pero si no todo el rebaño pereciere, el usufructuario estará obligado a reemplazar con las crías los animales muertos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc2f22c6-fbdb-4bcb-b08e-34f49637ac49', '7ba61515-a655-47a1-9301-2625c32127af', 2, 'MODO DE EXTINGUIRSE EL USUFRUCTO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3ae3f83-aa12-4a15-b57b-9ebd3077f613', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '738', 'Extinción del usufructo', 628, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6dc15869-1d38-4231-9977-3cb64e371fdb', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 1, 'El usufructo se extingue: 1. Por muerte del usufructuario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('09548832-5f1f-4902-b899-af1c4c530d5d', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 2, '2. Por vencimiento del plazo por el cual se constituyó, o por realizarse la condición resolutoria a la cual estaba sujeto el usufructo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a9d7d7bd-7205-412e-92fe-7b4636ef04b0', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 3, '3. Por la reunión del usufructo, y de la propiedad en una misma persona; pero si la reunión se verifica en una sola cosa o parte de lo usufructuado, en lo demás subsistirá el usufructo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b311c651-4c9f-4e65-820e-15e7940a86bd', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 4, '4. Por prescripción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a380a1bf-a3b3-4869-9aa5-a63bf56318f3', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 5, '5. Por renuncia del usufructuario, salvo lo dispuesto respecto de las renuncias hechas en fraude de acreedores;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a4b46e5-87b9-4532-8fba-99709835f937', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 6, '6. Por la pérdida de la cosa usufructuada. Si la destrucción no es total, el derecho continúa sobre el resto; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7cc6bc29-707f-49d8-9fd8-5b6767f40269', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 7, '7. Por la anulación o cesación del derecho del que constituyó el usufructo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('149c0f3e-52e0-494c-8fc5-718ea42a0e75', 'd3ae3f83-aa12-4a15-b57b-9ebd3077f613', 8, '8. ARTICULO 739. Cesación del usufructo. También puede cesar el usufructo por el abuso que el usufructuario haga de su derecho, deteriorando los bienes o dejándolos perecer por falta de las reparaciones ordinarias. En este caso, la extinción del usufructo no procede de hecho, sino que debe ser declarada por resolución judicial. También puede optar el propietario en el mismo caso, a que se le ponga en posesión de los bienes, obligándose a pagar al usufructuario, periódicamente, el producto líquido de los mismos, deducido el honorario de administración, fijado de conformidad con la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e28e515-c914-4ac9-974e-e0794b57d087', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '740', 'Destrucción del bien usufructuado', 629, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7efe0d2b-307e-464f-9bc0-ae2ff40fe0ad', '9e28e515-c914-4ac9-974e-e0794b57d087', 1, 'Si el usufructo estuviere constituido sobre una finca de la que forme parte un edificio, y éste llegare a perecer, de cualquier modo que sea, el usufructuario, tendrá derecho a disfrutar del suelo y de los materiales. Lo mismo sucederá cuando el usufructo estuviere constituido solamente sobre un edificio y éste pereciere. En tal caso, si el propietario quisiere construir otro edificio, tendrá derecho a ocupar el suelo y a servirse de los materiales, quedando obligado a pagar al usufructuario, mientras dure el usufructo, los intereses de las sumas correspondientes al valor del suelo y de los materiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a445fda0-2771-42ee-8c0d-fe0e0dcd22c4', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '741', 'Impedimento temporal', 630, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7698fb18-d778-4866-aabd-e47458108f11', 'a445fda0-2771-42ee-8c0d-fe0e0dcd22c4', 1, 'El impedimento temporal, por caso fortuito o fuerza mayor, no extingue el usufructo, ni da derecho a exigir indemnización del propietario. El tiempo del impedimento se tendrá por corrido para el usufructuario, de quien serán los frutos que durante él pueda producir la cosa usufructuada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c4961444-a02b-41ef-8008-83ca48415b16', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '742', 'Usufructo a término', 631, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bbe0abe3-a81f-4527-992b-6858ac131e9e', 'c4961444-a02b-41ef-8008-83ca48415b16', 1, 'El usufructo concedido por el tiempo que tarde un tercero en llegar a cierta edad, subsistirá el número de años prefijados; aunque éste muera antes, salvo si el usufructo hubiere sido expresamente concedido sólo en atención a la existencia de dicho tercero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4c413195-9c32-4b5c-8c75-0909be72b894', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '743', 'Seguro', 632, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3170aa2-9f83-4f32-8a6f-5113268a4df9', '4c413195-9c32-4b5c-8c75-0909be72b894', 1, 'Si el usufructuario concurriere con el propietario al seguro del predio usufructuado, el segundo percibirá el precio del seguro en caso de siniestro, y el usufructuario continuará en el goce del nuevo edificio si se construyere, o tendrá derecho a los intereses del precio si la reedificación no conviniere al propietario. Si el propietario se hubiese negado a contribuir al seguro del predio constituyéndolo por sí solo el usufructuario, adquirirá éste el derecho de percibir por entero, en caso de siniestro, el precio del seguro, pero con la obligación de invertirlo en la reconstrucción de la finca.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f8ac520-0cf3-49a0-9467-ba844fad2c83', '4c413195-9c32-4b5c-8c75-0909be72b894', 2, 'Si el usufructuario se hubiere negado a contribuir al seguro constituyéndolo por sí solo el propietario, percibirá éste íntegro el precio del seguro, en caso de siniestro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b1dc8282-6440-4697-add1-bc8595729ff5', 'a0000000-0000-0000-0000-000000000001', '98221c0e-e8d1-4c81-8a18-efa53caff72c', '744', 'Expropiación de la cosa usufructuada', 633, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20692b91-484a-4be6-bd0f-c05c4a8ba556', 'b1dc8282-6440-4697-add1-bc8595729ff5', 1, 'Si la cosa usufructuada fuere expropiada por causa de utilidad pública, el propietario estará obligado a abonar al usufructuario el interés legal del importe de la indemnización que recibiere, por todo el tiempo que deba durar el usufructo. El usufructuario podrá exigir que el propietario garantice el pago de los réditos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46dcd5c1-dbc4-4521-ad53-82c8cdce34fc', 'b1dc8282-6440-4697-add1-bc8595729ff5', 2, 'USO Y HABITACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ee61f24-4e7f-4f1e-abf1-465050619aac', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '745', 'Contenido del uso', 634, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a69d3d1d-e254-4640-b69a-200c21c59851', '3ee61f24-4e7f-4f1e-abf1-465050619aac', 1, 'El uso da derecho de servirse de cosa ajena o de aprovecharse de los frutos de ella, en cuanto basten para las necesidades del usuario y las de su familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e32f309-f45d-4988-a8e2-e727e88812d4', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '746', 'Contenido de la habitación', 635, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01930276-b75d-4eb1-9586-c5271c5dc344', '8e32f309-f45d-4988-a8e2-e727e88812d4', 1, 'La habitación se limita a lo que sea necesario para quien tiene el derecho y para su familia, aun cuando no la haya tenido en el momento de constituirse tal derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('837ca8ab-2de3-4c21-b8fd-d2760b83a5d5', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '747', NULL, 636, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('322b8b48-ac73-4052-814c-1cb1b50080c4', '837ca8ab-2de3-4c21-b8fd-d2760b83a5d5', 1, 'Los derechos de uso y habitación se regulan por el título que los constituye. Si el título no determina la extensión de estos derechos, se regularán conforme a los artículos siguientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('effe8048-8f59-4b1b-ac92-44a1975068c3', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '748', 'Son derechos inalienables', 637, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3ed73cd-8135-45f3-b373-aefe7d7db760', 'effe8048-8f59-4b1b-ac92-44a1975068c3', 1, 'Los derechos de uso y habitación no se pueden enajenar, gravar ni arrendar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1e9bb5d8-537e-489b-9db5-681bde34d426', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '749', 'Obligaciones de prestar garantía y de hacer inventario', 638, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e7d61ed-73ca-44ff-8175-b2ab64ff3f50', '1e9bb5d8-537e-489b-9db5-681bde34d426', 1, 'Para gozar de los derechos de uso y habitación, debe prestarse previamente garantía y hacerse');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('674b33e9-4bae-42e3-9db1-18eda8243163', '1e9bb5d8-537e-489b-9db5-681bde34d426', 2, 'formal inventario y descripción del estado de los inmuebles, con citación del propietario. En cuanto a la garantía rigen las mismas prescripciones que para el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('facee5e4-ad94-4b88-9bca-1ff1b7bbab53', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '750', NULL, 639, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a9b301f-dcf8-4d93-9784-bc8053040f6a', 'facee5e4-ad94-4b88-9bca-1ff1b7bbab53', 1, 'Los derechos de uso y habitación se establecen y se pierden de la misma manera que el usufructo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('877ceb3e-a3a9-44fa-bc11-dd198ae0fe2f', 'a0000000-0000-0000-0000-000000000001', '1b2d5ac9-bd5b-4b55-8bf6-ab76794b72d8', '751', 'Obligaciones del usuario y del habitacionista', 640, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('df046a5f-7ad7-4a18-9790-03cd1945e14f', '877ceb3e-a3a9-44fa-bc11-dd198ae0fe2f', 1, 'Si quien tiene el uso de un fundo tomare todos sus frutos, o si quien tiene derecho de habitación ocupare toda la casa, estará obligado a hacer los gastos de cultivo o de reparaciones ordinarias y a pagar las contribuciones. Si no tomare más que una parte de los frutos, o no ocupare más que una parte de la casa, contribuirá en proporción de lo que goce.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('85adddfc-3aac-400d-86fa-742ab14ab678', '877ceb3e-a3a9-44fa-bc11-dd198ae0fe2f', 2, 'DE LAS SERVIDUMBRES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d71641e-9833-4b0b-9f4c-df07a54e53bf', '877ceb3e-a3a9-44fa-bc11-dd198ae0fe2f', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6477602f-a3d7-4795-8360-9b3dd5210142', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '752', 'Concepto', 641, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f057dc2-12c2-4891-aba1-798f5ab64cf6', '6477602f-a3d7-4795-8360-9b3dd5210142', 1, 'Servidumbre es el gravamen impuesto sobre un predio para uso de otro predio de distinto dueño o para utilidad pública o comunal. Sin embargo, el propietario de dos fincas puede gravar una de ellas con servidumbre en beneficio de la otra.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c9ea13a-4381-42e5-b554-ded7e651ff8d', '6477602f-a3d7-4795-8360-9b3dd5210142', 2, 'El inmueble a cuyo favor está constituida la servidumbre se llama predio dominante; el que la sufre, predio sirviente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9bf2184-af78-4867-89ce-e2ed65ac932b', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '753', 'La servidumbre consiste en no hacer o en tolerar', 642, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4e58797-2230-4549-9e9f-30ac70bfed7f', 'e9bf2184-af78-4867-89ce-e2ed65ac932b', 1, 'Para que al dueño del predio sirviente pueda exigirse la ejecución de un hecho es necesario que esté expresamente determinado por la ley o en el acto en que se constituyó la servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88b5d232-8fa3-444b-9047-8e05c3b0ab2b', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '754', 'Clasificación', 643, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20d6d279-95f2-4975-916a-8c3514a5856f', '88b5d232-8fa3-444b-9047-8e05c3b0ab2b', 1, 'Las servidumbres son continuas o discontinuas, aparentes o no aparentes. Son continuas aquellas cuyo uso es o puede ser incesante, sin intervención de ningún hecho actual del hombre; y discontinuas, aquéllas cuyo uso necesita algún hecho actual del hombre.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3505b2b-a89f-4b94-81b3-88d9a7400e4b', '88b5d232-8fa3-444b-9047-8e05c3b0ab2b', 2, 'Son aparentes, las que se anuncian por obras o signos exteriores dispuestos para su uso y aprovechamiento, y no aparentes, las que no presentan signo exterior de su existencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f706dfdd-f246-455d-a85f-c85f415e0b3d', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '755', 'Inseparabilidad', 644, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fceb9b40-30f1-4f71-b9cf-3b1e60af8084', 'f706dfdd-f246-455d-a85f-c85f415e0b3d', 1, 'Las servidumbres son inseparables del inmueble a que activa o pasivamente pertenecen.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd0a7a2e-3e1e-45c9-8232-a196ae6cf170', 'f706dfdd-f246-455d-a85f-c85f415e0b3d', 2, 'Si los inmuebles mudan de dueño, la servidumbre continúa, ya activa, ya pasivamente, en el predio en que estaba constituida, hasta que legalmente se extinga.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('73e333ef-56d3-46fb-890c-bfa7980b7759', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '756', 'Indivisibilidad', 645, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37e45dc6-7212-4e40-a077-2ed9f33d91a0', '73e333ef-56d3-46fb-890c-bfa7980b7759', 1, 'Las servidumbres son indivisibles. Si se divide el predio sirviente, cada una de sus porciones tiene que tolerarla en la parte que le corresponde. Si se divide el dominante, cada propietario de éste puede usarla por entero, pero no alterarla ni agravarla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aadb5c1f-3bdc-4c90-975e-8df2ef25d04c', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '757', 'Servidumbres voluntarias y legales', 646, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('742bd850-a60c-4ca5-94f6-013dbf837b10', 'aadb5c1f-3bdc-4c90-975e-8df2ef25d04c', 1, 'Las servidumbres se derivan de la situación natural de los predios, de las obligaciones impuestas por la ley o de la voluntad de los propietarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('395fa19d-688f-4478-a7d8-1bfc9701fbef', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '758', NULL, 647, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('04a3b3f3-d781-423f-beda-bf302b5acb7b', '395fa19d-688f-4478-a7d8-1bfc9701fbef', 1, 'Las servidumbres que tienen por objeto el interés de los particulares, pueden ser establecidas, derogadas o modificadas por la voluntad de éstos, siempre que tengan capacidad para disponer de sus bienes. Lo concerniente a servidumbres legales establecidas para utilidad pública o comunal se regirá por leyes y reglamentos especiales y, en su defecto, por las disposiciones de este título.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1a92044f-464e-459e-82ae-a51b6006fb99', 'a0000000-0000-0000-0000-000000000001', 'a501bd96-ce41-400a-b6ae-0b8a4eeea6db', '759', 'Amplitud de la servidumbre', 648, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7eecc5a2-0fd4-46c2-b006-fb2523e984b9', '1a92044f-464e-459e-82ae-a51b6006fb99', 1, 'Al constituirse una servidumbre, se entienden concedidos todos los medios necesarios para su uso; y extinguida aquélla, cesan también estos derechos accesorios, pero no aquellos medios que se han obtenido por un título Independiente de la servidumbre.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('231a82cf-acf8-4a4c-9dfb-3be4490c00bc', '1a92044f-464e-459e-82ae-a51b6006fb99', 2, 'DE LA SERVIDUMBRE DE ACUEDUCTO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '760', 'Casos en que puede imponerse', 649, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94135834-a9ea-482b-a95a-ef30c4b29eed', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 1, 'Puede imponerse la servidumbre forzosa de acueducto, para la conducción de aguas destinadas a algún servicio de utilidad pública, previa indemnización. Puede imponerse también servidumbre forzosa de acueducto para objetos de interés privado, previa indemnización, en los casos siguientes:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0f2ef8c-cd26-48a8-b6f8-a61171e3275a', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 2, '1. Establecimiento o aumento de riegos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4948492-735d-4f02-84eb-7e367cdf2a08', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 3, '2. Establecimiento de baños y fábricas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d927963-c0e9-48e7-99d0-f9ce7c778d2e', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 4, '3. Desecación de lagunas y terrenos pantanosos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec2df74d-6d74-40c5-832a-2972f4194ebd', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 5, '4. Evasión o salida de aguas procedentes de alumbramientos artificiales; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('970a2850-cf80-48d1-9d86-6c44b8d53726', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 6, '5. Salida de aguas de escorrederas y drenajes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6dd429d3-91b0-4226-9592-69fdd5d673bb', '10f90d11-d1a0-4ee4-bae9-e7fdeaae0901', 7, 'En los tres primeros casos puede imponerse la servidumbre, no sólo para la conducción de las aguas necesarias, sino también para la evasión de las sobrantes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1857ceb-3771-4565-a28f-f0e128a27b49', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '761', 'Oposición del dueño del predio sirviente', 650, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6dac2a98-c7d1-4f17-b194-72610d144b67', 'd1857ceb-3771-4565-a28f-f0e128a27b49', 1, 'El dueño del terreno sobre que trate de imponerse la servidumbre forzosa de acueducto, podrá oponerse por alguna de las causas siguientes: 1. Por pretenderse construir acequia descubierta que sea perjudicial por su calidad de agua;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5aef36a6-bccb-49d6-8b96-59a464aaeff6', 'd1857ceb-3771-4565-a28f-f0e128a27b49', 2, '2. Por ser peligrosa para el terreno del predio sirviente, cuando se intente utilizarla para objetos de interés privado; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1969acee-e37e-4593-9de6-5a6ba6c0846c', 'd1857ceb-3771-4565-a28f-f0e128a27b49', 3, '3. Por poderse establecer sobre otros predios con iguales ventajas para el que pretenda imponerla y menores inconvenientes para el que haya de sufrirla.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('128aea3d-1e3e-4226-9c09-0ed24c30d73c', 'd1857ceb-3771-4565-a28f-f0e128a27b49', 4, 'No puede imponerse la servidumbre forzosa de acueducto para objeto de interés privado, sobre edificios, ni sobre jardines, ni huertas existentes al tiempo de hacerse la solicitud.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('69312d12-d6f8-4322-b237-808d3cccfff1', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '762', 'División del fundo', 651, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4e653f5-5a00-4f77-a598-85a3e548133e', '69312d12-d6f8-4322-b237-808d3cccfff1', 1, 'Cuando un terreno de regadío que recibe el agua por un solo punto, se divide por herencia, venta u otro título entre dos o más dueños, los de la parte superior quedan obligados a dar paso al agua como servidumbre de acueducto para riego de los inferiores, sin poder exigir por ello indemnización, salvo pacto en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('85e2433d-3311-4c90-a611-b7aa77d17c47', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '763', 'Cómo se constituye', 652, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e10e5e6-4555-4d31-ac70-15ef23cc90f9', '85e2433d-3311-4c90-a611-b7aa77d17c47', 1, 'La servidumbre forzosa de acueducto podrá constituirse: 1. Por acequia descubierta cuando no sea peligrosa por su profundidad o situación ni ofrezca otros inconvenientes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ff20884-7705-4a4c-a2fc-5b4c92d80d9d', '85e2433d-3311-4c90-a611-b7aa77d17c47', 2, '2. Con acequia cubierta cuando lo exija su profundidad, contigüidad a habitaciones o caminos, o algún otro motivo análogo a juicio de autoridad competente; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0396d6f-748b-4432-8c47-7f8c4e374c38', '85e2433d-3311-4c90-a611-b7aa77d17c47', 3, '3. Con cañería o tubería, cuando puedan ser absorbidas aguas ajenas; cuando las aguas conducidas pueden infeccionar a otras, absorber sustancias nocivas o causar daños a obras o edificios; y siempre que resulte necesario del expediente que al efecto se forme.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b038551f-6b89-4a71-9898-696800cfa14e', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '764', NULL, 653, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('105164b3-e1ad-4444-aa2f-de3d72b14f86', 'b038551f-6b89-4a71-9898-696800cfa14e', 1, 'La servidumbre forzosa de acueducto puede establecerse temporal o perpetuamente. Se entenderá perpetua para los efectos de este Código, cuando su duración exceda de cinco años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e145233e-ac4b-4feb-a0c9-4ad7ef09d6e3', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '765', 'Servidumbre temporal', 654, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56327515-9a23-4427-9fd0-4eee8bf09eb2', 'e145233e-ac4b-4feb-a0c9-4ad7ef09d6e3', 1, 'Si la servidumbre fuese temporal, se abonará previamente al dueño del terreno el duplo del arriendo que correspondería por la parte que se le ocupa, con la adición del importe de los daños y desperfectos para el resto de la finca, incluso los que procedan de su fraccionamiento por interposición de acequia. Además, será de cargo del dueño del predio dominante, el reponer las cosas a su antiguo estado, terminada la servidumbre. Si ésta fuese perpetua se abonará el valor del terreno ocupado y de los daños y perjuicios que se causaren al resto de la finca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5da8d9f9-aaf6-4152-8397-4e5c450453aa', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '766', 'Obligaciones del que otorga la servidumbre', 655, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('940ebc9c-cc6b-49ff-b576-07dbae8a7a99', '5da8d9f9-aaf6-4152-8397-4e5c450453aa', 1, 'Serán de cuenta del que haya promovido y obtenga la servidumbre de acueducto, todas las obras necesarias para su construcción, conservación y limpieza. Al efecto se le autorizará para ocupar temporalmente los terrenos indispensables para el depósito de materiales, previa indemnización de daños y perjuicios, o garantía suficiente en el caso de no ser éstos fáciles de prever o no conformarse con ella los interesados. Estos podrán compelerle a ejecutar las obras y limpias necesarias para impedir estancamientos o filtraciones que originen deterioros.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a2d2f3b-9db2-40ec-bfc2-e6a20739eed1', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '767', 'Anchura del conducto', 656, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb97b756-3199-4894-bbd5-118639502ac0', '4a2d2f3b-9db2-40ec-bfc2-e6a20739eed1', 1, 'Al establecerse la servidumbre forzosa de acueducto se fijará, en vista de la naturaleza y configuración del terreno, la anchura en que deben tener la acequia y sus márgenes, según la cantidad de agua que habrá de ser conducida. Si por ser la acequia de construcción antigua o por otra causa, no estuviere determinada la anchura de su cauce, se fijará conforme a las bases anteriores, cuando lo solicite cualquiera de los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90a22b4a-705e-479a-a89a-3d44d0a72755', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '768', 'Derecho de paso', 657, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('511642f1-eeab-426f-8c1f-5e40b137c51e', '90a22b4a-705e-479a-a89a-3d44d0a72755', 1, 'A la servidumbre forzosa de acueducto es inherente el derecho de paso por sus márgenes, para su exclusivo servicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d71a7378-2d59-4fa5-9f93-b644883c3b76', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '769', NULL, 658, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f75f592b-9a36-47d2-b398-2ee78335a6b5', 'd71a7378-2d59-4fa5-9f93-b644883c3b76', 1, 'Si el acueducto atravesare vías públicas o particulares, de cualquiera naturaleza que sean, quedará obligado, el que haya obtenido la concesión, a construir y conservar las alcantarillas, canales y puentes necesarios; y si hubiere de atravesar otros acueductos, se procederá de modo que no retarde ni acelere el curso de las aguas, ni disminuya su caudal, ni adultere su calidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('08ba99f9-f8d9-4367-970c-c57df610d6f0', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '770', 'Aumento de capacidad del acueducto', 659, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('373a1636-1f5d-478a-a432-c6f27156f19f', '08ba99f9-f8d9-4367-970c-c57df610d6f0', 1, 'Cuando el dueño de un acueducto que atraviese tierras ajenas, solicite aumentar su capacidad para que reciba mayor caudal de agua, se usarán las mismas reglas que para su establecimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e28cecb3-7d35-4329-a2fb-d7e0f267658c', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '771', 'Prohibición de hacer plantaciones', 660, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('375455c6-f132-49fa-844f-5e8fb440de18', 'e28cecb3-7d35-4329-a2fb-d7e0f267658c', 1, 'El dueño de un acueducto podrá fortificar sus márgenes con céspedes, estacadas, paredes o ribazos de piedra suelta, pero no con plantaciones de ninguna clase. El dueño del predio sirviente tampoco podrá hacer plantación ni operación alguna de cultivo en las mismas márgenes, y las raíces que penetren en ellas podrán ser cortadas por el dueño del acueducto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('461e62e3-972b-434b-a3a1-b0c25c91085f', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '772', 'Facultades del dueño del predio sirviente', 661, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87f6d70e-38be-4d89-a4ea-769a8c1fb83f', '461e62e3-972b-434b-a3a1-b0c25c91085f', 1, 'La servidumbre de acueducto no obsta para que el dueño del predio sirviente pueda cerrarlo y cercarlo, así');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64483a0e-26ad-465c-8494-9f7d50ea1482', '461e62e3-972b-434b-a3a1-b0c25c91085f', 2, 'como edificar sobre el acueducto mismo, de manera que éste no experimente perjuicio ni se imposibiliten las reparaciones y limpias necesarias que hará oportunamente el dueño del acueducto, dando aviso anticipado al propietario, arrendatario o administrador del predio sirviente. Si para la limpieza fuese preciso demoler parte de algún edificio, el costo de su reparación será a cargo de quien hubiere edificado sobre el acueducto, en caso de no haber dejado las correspondientes aberturas o boquetes para aquel servicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('39eff537-7a55-4193-9ab4-fb61f5208f83', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '773', NULL, 662, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec3fd818-ffe5-4a00-924b-86293f27e134', '39eff537-7a55-4193-9ab4-fb61f5208f83', 1, 'El dueño del predio sirviente podrá construir sobre el acueducto, puentes para pasar de una a otra parte del predio; pero lo hará con la solidez necesaria y de manera que no se amengüen las dimensiones del acueducto ni se embarace el curso del agua.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a2d05ba-bde6-4193-80e7-c1b30233860b', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '774', NULL, 663, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3550ae8e-4175-4c86-bc06-2f138ec86199', '3a2d05ba-bde6-4193-80e7-c1b30233860b', 1, 'En toda acequia o acueducto, el agua, el cauce, los cajeros y las márgenes serán considerados como parte integrante de la heredad o edificio a que van destinadas las aguas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8352d9a9-69b7-4212-a573-27322ce2e4a1', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '775', 'Prohibiciones', 664, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47acc1cb-6969-4f15-a868-22af56f0b6ec', '8352d9a9-69b7-4212-a573-27322ce2e4a1', 1, 'Nadie podrá en los casos y condiciones especificados en los artículos precedentes, construir edificio ni puente sobre acequia o acueducto ajeno, ni derivar agua, ni aprovecharse de los productos de ella, ni de los de sus márgenes, ni utilizar la fuerza de la corriente, sin expreso consentimiento del dueño. Tampoco podrán los dueños de los predios que atravesare una acequia o acueducto, o por cuyos linderos corriere, alegar derecho de posesión al aprovechamiento de su cauce ni márgenes, a no ser que se fundare en títulos de propiedad que expresen tal derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('746379e3-c73d-4fea-b1f2-ce83dde21848', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '776', 'Caducidad', 665, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa059923-0e50-4aba-a5eb-c3b6c785a7e9', '746379e3-c73d-4fea-b1f2-ce83dde21848', 1, 'La concesión de la servidumbre de acueducto sobre predios ajenos, caducará si dentro del plazo que se hubiere fijado, el concesionario no hiciere uso de ella; dicha caducidad se opera sin perjuicio de satisfacer al dueño de cada predio sirviente la indemnización que corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ddf9f737-ea6a-4e15-a37b-635af6027a85', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '777', 'Servidumbres urbanas de acueducto', 666, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c27ea2d3-3b97-4dc5-97ff-595aca59494c', 'ddf9f737-ea6a-4e15-a37b-635af6027a85', 1, 'Las servidumbres urbanas de acueducto, canal, puente, cloaca, sumidero y demás establecidas para el servicio público y privado de las poblaciones, edificios, jardines y fábricas, se regirán por las disposiciones generales y locales. Las procedentes de contratos privados que no afecten a las atribuciones de los municipios, se regirán por las leyes aplicables al contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('929922b8-5da6-4bb4-b518-03957b13c0ae', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '778', 'Servidumbre de estribo', 667, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac9d53d4-01d9-484b-8d6e-4b1065fe526a', '929922b8-5da6-4bb4-b518-03957b13c0ae', 1, 'En los mismos casos que la servidumbre de acueducto, puede imponerse la servidumbre forzosa de estribo, cuando el que intenta construir una presa no sea dueño de las riberas o terrenos donde haya de apoyarlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('265f1f74-5ddc-408a-8f8f-475ca9d78995', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '779', 'Pago de terreno ocupado', 668, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6676ab39-871f-4927-bb6f-90d66e7e8d7b', '265f1f74-5ddc-408a-8f8f-475ca9d78995', 1, 'Decretada la servidumbre forzosa de estribo de presa, se abonará al dueño del predio o predios sirvientes, el valor que por la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b709128e-6381-4e67-9842-999cc128b6ae', '265f1f74-5ddc-408a-8f8f-475ca9d78995', 2, 'ocupación del terreno corresponda; y además, se le indemnizará de los daños y perjuicios que hubieren experimentado las fincas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7e82eca-14a2-466a-98a5-027ef254fed7', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '780', 'Construcción de compuertas', 669, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bcb34008-3302-4c58-ac85-fc4de980cfdd', 'b7e82eca-14a2-466a-98a5-027ef254fed7', 1, 'El que para dar riego a su heredad o mejorarla necesite construir compuertas o partidor en la acequia o regadora por donde haya de recibirlo, sin gravamen ni merma para los demás regantes, podrá exigir de los dueños de las márgenes, que permitan su construcción, previo abono de daños y perjuicios, incluso los que se originen por la nueva servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b75c339-ece1-462d-94b3-84e5f85f6933', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '781', 'Servidumbre de abrevadero y de saca de agua', 670, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e058d749-52de-4e6e-9f7a-3e6bba573f2f', '8b75c339-ece1-462d-94b3-84e5f85f6933', 1, 'Las servidumbres forzosas de abrevadero y de saca de agua, solamente podrán imponerse por causa de utilidad pública en favor de alguna población o caserío, previa la Indemnización correspondiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2235c174-5130-45ac-aba2-7a7f88210215', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '782', NULL, 671, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b5d2137-1d05-49f5-a485-9ce720818f6b', '2235c174-5130-45ac-aba2-7a7f88210215', 1, 'No se impondrán estas servidumbres sobre los pozos ordinarios, las cisternas o aljibes ni sobre los edificios o terrenos cercados con pared.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3fb4e50d-bbb0-4edc-9f40-e4765f392ad2', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '783', NULL, 672, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05483596-c70d-4b73-830b-2e970cf1390c', '3fb4e50d-bbb0-4edc-9f40-e4765f392ad2', 1, 'Las servidumbres de abrevadero y de saca de agua llevan consigo la obligación, en los predios sirvientes, de dar paso a personas y ganados hasta el fundo donde hayan de ejercerse aquéllas, debiendo ser también extensiva a este servicio la indemnización.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('682ab9de-eebe-4689-9e3a-8ea6fae12b8e', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '784', NULL, 673, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f1db4e8-9031-4d93-bcf2-b8c73d67409e', '682ab9de-eebe-4689-9e3a-8ea6fae12b8e', 1, 'Son aplicables a las concesiones de esta clase de servidumbres, las prescripciones que se dejan establecidas para el otorgamiento de las de acueducto; al decretarlas se fijará, según su objeto y las circunstancias de la localidad, la anchura de la vía o senda que haya de conducir al abrevadero o punto destinado para sacar agua.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4816ff4d-829c-497f-ab6a-338fe9a3d18f', 'a0000000-0000-0000-0000-000000000001', '18aa34ec-bfeb-41ee-b1bd-e9673638c098', '785', NULL, 674, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fff6c58c-4e66-4ab2-a1b9-2375df3e8778', '4816ff4d-829c-497f-ab6a-338fe9a3d18f', 1, 'Los dueños de predios sirvientes podrán variar la dirección de la vía o senda destinada al uso de estas servidumbres, pero no su anchura ni entrada, y en todo caso sin que la variación perjudique el uso de las servidumbres.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92162f29-ffca-4e66-8d4f-2601a4f7191b', '4816ff4d-829c-497f-ab6a-338fe9a3d18f', 2, 'SERVIDUMBRE LEGAL DE PASO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('786269e7-dfd0-425e-b1cb-544ce4e8b3e1', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '786', 'Derecho del predio enclavado', 675, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('714b33c9-ead2-42bd-ac76-7d45c6c16c4d', '786269e7-dfd0-425e-b1cb-544ce4e8b3e1', 1, 'El propietario de un predio enclavado entre otros ajenos que no tenga salida a la vía pública, o que no pueda procurársela sin excesivo gasto o dificultad, tiene derecho a exigir paso por los predios vecinos, para el aprovechamiento y explotación del mismo predio. El propietario de una finca rústica, tenga o no salida a la vía pública, podrá también exigir paso por los predios vecinos hasta la estación de cualquier ferrocarril. En ambos casos y mientras resuelven en definitiva las autoridades judiciales, podrá constituirse provisionalmente por éstas, previa garantía de indemnización y de daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('082157b6-1338-48cb-abaa-98c3d950cd55', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '787', 'Indemnización al predio sirviente', 676, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1174adac-37c4-4cfe-8b09-a0ea4f459a99', '082157b6-1338-48cb-abaa-98c3d950cd55', 1, 'Se deberá siempre una indemnización equivalente al valor del terreno necesario y al perjuicio que ocasione ese');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a79a009-0899-4945-884c-565d3a1f4acc', '082157b6-1338-48cb-abaa-98c3d950cd55', 2, 'gravamen. La misma disposición se aplicará al que teniendo paso por predio de otro, necesite ensanchar el camino para conducir vehículos con los mismos fines.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b13f9a66-9011-487c-a4bd-3c29191d98cf', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '788', 'Prescripción', 677, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d93dc5c-b3d5-4ee2-b10a-d2f64cc45675', 'b13f9a66-9011-487c-a4bd-3c29191d98cf', 1, 'La acción para reclamar esa indemnización es prescriptible; pero, aunque prescriba, subsistirá la servidumbre obtenida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('784c4b32-0d29-43e6-b25a-90033a16ae86', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '789', 'Lugar de la servidumbre', 678, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c2bf22e-296f-4bd5-b61f-291713e7be4e', '784c4b32-0d29-43e6-b25a-90033a16ae86', 1, 'El dueño del predio sirviente tiene el derecho de señalar el lugar donde ha de constituirse la servidumbre de paso. Si no estuviere de acuerdo el dueño del predio dominante por ser impracticable o muy gravoso para este el lugar designado, podrá ocurrir al juez competente para que, oyendo el dictamen de expertos, resuelva lo más conveniente, procurando conciliar los intereses de los dos predios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e0710ec-532a-4b37-b360-fb03fe9b2345', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '790', 'Predio obligado', 679, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4147a2ed-e7f9-4151-8811-73bcc4eab774', '5e0710ec-532a-4b37-b360-fb03fe9b2345', 1, 'Si hubiere varios predios por donde pueda darse el paso, el obligado a la servidumbre será aquel por donde fuere más corta la distancia. Si ésta fuere igual por dos o más predios, el juez designará cuál de éstos ha de dar el paso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f2dc4bb3-7b46-457e-8e16-fd9e410d696a', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '791', 'Anchura de paso', 680, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('980617b1-ea88-47dd-b17e-612ae3a076da', 'f2dc4bb3-7b46-457e-8e16-fd9e410d696a', 1, 'En la servidumbre de paso, el ancho de éste será el que baste a las necesidades del predio dominante, a juicio del juez, no pudiendo exceder de seis metros ni bajar de dos, sino por convenio de los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2777b352-850b-40b2-ae57-38aa6e8bb25b', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '792', 'Paso sin indemnización', 681, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43cb39ae-f5fc-42d0-8b78-6c97a28f5867', '2777b352-850b-40b2-ae57-38aa6e8bb25b', 1, 'Si un fundo queda cerrado por todas partes, por causa de venta, permuta o división, los vendedores, permutantes o copartícipes, están obligados a dar el paso sin indemnización alguna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3c56ae76-6dd8-4119-8cdb-69ec65d1aa06', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '793', 'Exoneración de la servidumbre', 682, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c0cd2c46-0e62-4328-92c8-0fc10faad185', '3c56ae76-6dd8-4119-8cdb-69ec65d1aa06', 1, 'Si obtenida la servidumbre de paso, deja de ser indispensable para el predio dominante por la adquisición de otros terrenos que le dan un acceso cómodo al camino o por otro medio, el dueño del predio sirviente tendrá derecho para pedir que se le exonere de la servidumbre, restituyendo lo que al establecer ésta se hubiere pagado por el valor del terreno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d2400d1-40b4-4a93-b2ac-c7cc474a178a', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '794', 'Paso para servicio público', 683, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ccb8702-214f-4eb8-ada4-617156885db2', '2d2400d1-40b4-4a93-b2ac-c7cc474a178a', 1, 'Cuando la servidumbre de paso tenga por objeto un servicio público, debe darse por el punto menos perjudicial al predio sirviente; pero buscando siempre la mayor facilidad y menor distancia hacia el punto en que el servicio deba ser prestado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e235aac-da66-4479-9b9a-e6a7132fb553', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '795', 'Entrada al predio sirviente', 684, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a14fc8c2-6ecf-470b-9e18-a44114b970d9', '3e235aac-da66-4479-9b9a-e6a7132fb553', 1, 'Todo propietario debe permitir la entrada y paso por su propiedad, siempre que sean absolutamente necesarios para construir o reparar un muro u obra de interés particular del vecino, o en interés común de ambos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c1fed538-1c87-4d7e-96e4-4f6e36e1c3bc', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '796', 'Servidumbre para establecer comunicación telefónica', 685, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('66878803-b414-4c32-b349-857f725da014', 'c1fed538-1c87-4d7e-96e4-4f6e36e1c3bc', 1, 'Cuando para establecer comunicaciones telefónicas particulares entre dos o más fincas, o para conducir energía eléctrica a una finca, sea necesario colocar postes o tender alambres en terrenos de una finca ajena, el dueño de ésta debe permitirlo, mediante la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35b8f004-388b-456b-9001-08eebd162ea9', 'c1fed538-1c87-4d7e-96e4-4f6e36e1c3bc', 2, 'indemnización correspondiente, la que a falta de acuerdo entre las partes, fijará el juez en las diligencias respectivas. Esta servidumbre comprende el derecho de tránsito de las personas y el de la conducción de los materiales indispensables para la construcción y vigilancia de la línea.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('582ce328-0c11-475c-9091-ec7a27e5f509', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '797', 'Conducción de energía eléctrica', 686, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f700a06f-ef77-46e3-a7fe-efa7bccc9641', '582ce328-0c11-475c-9091-ec7a27e5f509', 1, 'Las servidumbres provenientes de la conducción de energía eléctrica para las poblaciones y del paso de vehículos aéreos, se regirán por leyes especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a55d2be9-d7bd-4112-ac55-dc75eca79ffb', 'a0000000-0000-0000-0000-000000000001', 'af2b588e-a033-4623-b6cf-63bb00c150f5', '798', 'Servidumbre legal de desagüe', 687, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4aaa3967-4ba7-4a0e-987b-131f0d386561', 'a55d2be9-d7bd-4112-ac55-dc75eca79ffb', 1, 'Cuando un predio rústico o urbano se encuentre enclavado en otro u otros, de manera que no tenga comunicación directa con algún camino, canal o calle pública, estarán obligados los dueños de los predios circunvecinos a permitir por entre éstos, el desagüe del central. Las dimensiones y dirección del conducto se fijarán por el juez, previo informe de peritos y audiencia de los interesados, observándose, en cuanto fuere posible, las reglas dadas en este capítulo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d88715b-e0ef-4216-afcf-b215ee4aeb0d', 'a55d2be9-d7bd-4112-ac55-dc75eca79ffb', 2, 'DE LAS SERVIDUMBRES VOLUNTARIAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('08114695-d965-4e4f-96b6-10fb889097cf', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '799', 'Las servidumbres voluntarias se rigen por su título', 688, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ffb5294-61a7-41e1-8739-5f252151b070', '08114695-d965-4e4f-96b6-10fb889097cf', 1, 'El ejercicio y extensión de las servidumbres establecidas por la voluntad del propietario, se regulan por los respectivos títulos y, en su defecto, por las disposiciones de este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ccbbf5ce-0974-4464-80c5-06cb13162a25', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '800', 'Propiedad común', 689, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('24631b45-dc8b-4c2f-a960-b26021c82bbf', 'ccbbf5ce-0974-4464-80c5-06cb13162a25', 1, 'Si fueren varios los propietarios de un predio, no se podrá imponer servidumbre sino con el consentimiento de todos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('982c63e1-3f8d-457d-ad4d-3f505edf4a66', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '801', NULL, 690, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc574e9d-c67f-470c-bafa-0bb485d06e69', '982c63e1-3f8d-457d-ad4d-3f505edf4a66', 1, 'Si fueren varios los propietarios, y uno solo de ellos adquiere la servidumbre sobre otro predio a favor del común, todos los propietarios podrán aprovecharse de ella, quedando obligados a los gravámenes y a los pactos con que se haya adquirido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90170889-056c-4eb9-a6db-36aa2b80bee2', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '802', 'Propiedad resoluble', 691, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2f5ad6b-416e-4fbc-80c7-e32ec9436729', '90170889-056c-4eb9-a6db-36aa2b80bee2', 1, 'Los que sólo tienen dominio resoluble, como aquel a quien se ha legado un fundo bajo condición no realizada, y otros semejantes, pueden constituir servidumbre; pero queda sin efecto, desde que se resuelve el derecho del constituyente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c7b83e51-bb2f-4dfc-be17-950e5de5d2dd', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '803', 'Fundo hipotecado', 692, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f9cdc1f-e48f-4041-8c29-f6fb479c97ea', 'c7b83e51-bb2f-4dfc-be17-950e5de5d2dd', 1, 'El dueño de un fundo hipotecado puede constituir servidumbre; pero si por tal motivo bajase el valor de aquél, de modo que perjudique al acreedor, tendrá derecho éste para hacer que se venda el fundo libre de la servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16e0f2de-7162-4787-8c23-aa3846ac1abe', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '804', 'Adquisición de la servidumbre', 693, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74128c11-2ff6-429f-b846-f0507ed9f94c', '16e0f2de-7162-4787-8c23-aa3846ac1abe', 1, 'Puede adquirirse la servidumbre en favor de un fundo por los poseedores de éste, sean de buena o de mala fe; y pueden');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d0d635a-ffe0-4260-855f-e0977e85c874', '16e0f2de-7162-4787-8c23-aa3846ac1abe', 2, 'igualmente adquirirla los que no gozan de la libre administración de sus bienes y los administradores de bienes ajenos en provecho de éstos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4e5be213-e281-4a51-8cb6-a8f3f8877a85', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '805', NULL, 694, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f72808c1-e96c-4351-a30d-a09cd2aaec8b', '4e5be213-e281-4a51-8cb6-a8f3f8877a85', 1, 'Las servidumbres continuas y aparentes se adquieren por cualquier título legal, inclusive la prescripción por el transcurso de diez años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('20b16fd7-6779-47fa-bee8-9b8830325183', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '806', NULL, 695, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1f837f2-38bd-4455-9572-fbea19a51f6d', '20b16fd7-6779-47fa-bee8-9b8830325183', 1, 'Las servidumbres continuas no aparentes, y las discontinuas, sean o no aparentes, no podrán adquirirse por prescripción sino por otro título legal. La posesión, aunque sea inmemorial, no basta para establecerlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('894a7838-0bb9-43a9-a917-6c33b74c706e', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '807', 'Título', 696, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6d680f39-32f1-475e-b0ba-03c98a736a46', '894a7838-0bb9-43a9-a917-6c33b74c706e', 1, 'Al que pretenda tener derecho a una servidumbre, toca probar, aunque esté en posesión de ella, el título en virtud del cual la goza.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e632e004-0e63-4149-b7f8-0ef831c01b3c', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '808', 'Pruebas supletorias', 697, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bfef05c-0750-4737-8822-a36b3f5fcd10', 'e632e004-0e63-4149-b7f8-0ef831c01b3c', 1, 'La falta de títulos constitutivos de las servidumbres que no pueden adquirirse por prescripción, únicamente se puede suplir por confesión judicial o reconocimiento hecho en escritura pública por el dueño del predio sirviente, o por sentencia firme que declare existir la servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b20a54a4-17ac-4e65-8ad5-12e6eeb8a475', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '809', 'Obligaciones del dueño del predio dominante', 698, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('132cc3f6-e6e9-4891-a9f7-9c29ba940c75', 'b20a54a4-17ac-4e65-8ad5-12e6eeb8a475', 1, 'El dueño del predio dominante debe hacer a su costa las obras que fueren necesarias para que al dueño del predio sirviente no se cause por servidumbre, más gravamen que el consiguiente a ella. Si por su descuido u omisión se causare daño, estará obligado a la indemnización.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e3e4b29-1ea3-45b7-9d89-2f7f514256a1', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '810', NULL, 699, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b10dd1e2-fe88-4010-8dc3-7cbbd2e37ca4', '5e3e4b29-1ea3-45b7-9d89-2f7f514256a1', 1, 'El dueño del predio sirviente no podrá menoscabar de modo alguno la servidumbre constituida sobre aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1f3b6446-84d5-44d8-8c57-8885647dc601', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '811', 'Cambio del lugar de la servidumbre', 700, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('08c1df90-ed3d-4bb1-8a5b-f27d23fc792b', '1f3b6446-84d5-44d8-8c57-8885647dc601', 1, 'Si el lugar primitivamente destinado para el uso de una servidumbre llegare a presentar graves inconvenientes al dueño del predio sirviente, éste podrá ofrecer otro que sea cómodo al dueño del predio dominante, quien no podrá rehusarlo si no se perjudica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab35b540-3fcd-4c9d-bfd6-24992db3439b', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '812', NULL, 701, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46aa5101-67a1-40c4-b887-e5718591f262', 'ab35b540-3fcd-4c9d-bfd6-24992db3439b', 1, 'El cambio de sitio para ejercicio de una servidumbre puede también admitirse a instancias del dueño del predio dominante, si éste prueba que el cambio le reporta una notoria ventaja y no produce daño alguno al predio sirviente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f28dae6e-39df-44f6-b55a-2cc68ed4c004', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '813', 'Obras que puede realizar el dueño del predio sirviente', 702, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f532a2df-0572-437a-8680-c794b5f475ae', 'f28dae6e-39df-44f6-b55a-2cc68ed4c004', 1, 'El dueño del predio sirviente puede ejecutar las obras que hagan menos gravosa la servidumbre, si de ellas no resulta perjuicio alguno al predio dominante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('136d5cb0-d2bb-445b-b52e-bbe214f91bba', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '814', NULL, 703, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('61fee504-f754-4f26-b60d-e04eca6f9a63', '136d5cb0-d2bb-445b-b52e-bbe214f91bba', 1, 'Si de la ejecución de dichas obras se siguiere algún perjuicio al predio dominante, el dueño del sirviente estará obligado a restablecer las cosas a su antiguo estado, y a indemnizar los daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cb8eabb0-2f1e-426c-8c8f-83f7e789aeb2', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '815', NULL, 704, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f433f4d6-085c-4e6e-b65d-3eb2a9e4eea2', 'cb8eabb0-2f1e-426c-8c8f-83f7e789aeb2', 1, 'Si el dueño del predio dominante se opone a las obras de que trata el artículo 813, la controversia se resolverá sumariamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3fe62692-74ba-410b-9f51-27447b7ce640', 'a0000000-0000-0000-0000-000000000001', '2f33343e-f919-4846-a765-b00d1f29cb9a', '816', 'Interpretación en caso de duda', 705, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48d1d02c-9ea6-44e0-a5e5-d9ee4dfa8266', '3fe62692-74ba-410b-9f51-27447b7ce640', 1, 'Cualquiera duda sobre el uso y extensión de la servidumbre, se decidirá en el sentido menos gravoso para el predio sirviente, sin imposibilitar ni dificultar el uso de la servidumbre.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d025cae4-5bfe-4fb4-ae17-c2138e6be9cc', '3fe62692-74ba-410b-9f51-27447b7ce640', 2, 'EXTINCION DE LAS SERVIDUMBRES VOLUNTARIAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c36aa272-de37-4e17-ab0c-72b149a47702', 'a0000000-0000-0000-0000-000000000001', '5828089d-d167-41c6-a5ec-676c85e49024', '817', NULL, 706, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f7e83e3-193d-438b-8689-134680c7da9b', 'c36aa272-de37-4e17-ab0c-72b149a47702', 1, 'Las servidumbres voluntarias se extinguen: 1. Por el no uso.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7432926d-18e3-465e-9114-f6f92dbdde7a', 'c36aa272-de37-4e17-ab0c-72b149a47702', 2, 'Cuando la servidumbre fuere continua y aparente, por el no uso de tres años, contados desde el día en que dejó de existir el signo aparente de la servidumbre. Cuando fuere discontinua o no aparente, por el no uso de cinco años, contados desde el día en que dejó de usarse por haber ejecutado el dueño del fundo sirviente acto contrario a la servidumbre, o por haber prohibido que se usare de ella. Si no hubo acto contrario o prohibición, aunque no se haya usado de la servidumbre, o si hubo tales actos, pero continúa el uso, no corre el tiempo de la prescripción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56525ce4-6238-4966-be96-cc0fbbea45a1', 'c36aa272-de37-4e17-ab0c-72b149a47702', 3, '2. Cuando los predios llegaren sin culpa del dueño del sirviente a tal estado que no pueda usarse la servidumbre.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92da61cc-e91e-430e-aa94-3589c5d59a9e', 'c36aa272-de37-4e17-ab0c-72b149a47702', 4, 'Si en lo sucesivo los predios vuelven a su estado anterior de manera que pueda usarse de ella, se restablecerá, a no ser que hayan transcurrido tres años, o que desde el día que pudo volverse a usar, haya pasado el tiempo suficiente para la prescripción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2622f6a-dbcb-4a18-b1e7-bee48f2840ea', 'c36aa272-de37-4e17-ab0c-72b149a47702', 5, '3. Por la remisión gratuita u onerosa, hecha por el dueño del predio dominante; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d7e675f-fe2d-4470-8330-2d8a32e56999', 'c36aa272-de37-4e17-ab0c-72b149a47702', 6, '4. Cuando constituida en virtud de un derecho revocable, se vence el plazo, se cumple la condición o sobreviene la circunstancia que debe poner término a aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d614eb68-8bb8-46af-a262-c4546be01ec0', 'a0000000-0000-0000-0000-000000000001', '5828089d-d167-41c6-a5ec-676c85e49024', '818', 'La prescripción en la posesión pro indiviso', 707, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc7393c6-448f-442f-9e81-cd77bc18c908', 'd614eb68-8bb8-46af-a262-c4546be01ec0', 1, 'Si el predio dominante pertenece a varios dueños pro indiviso, el uso de uno de ellos aprovecha a los demás para impedir la prescripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c652f4ae-e782-47a1-a6fd-b2bb05b76c9a', 'a0000000-0000-0000-0000-000000000001', '5828089d-d167-41c6-a5ec-676c85e49024', '819', NULL, 708, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc4f3a7d-29f4-4652-afe3-97e8a8b141d6', 'c652f4ae-e782-47a1-a6fd-b2bb05b76c9a', 1, 'Si entre los propietarios hubiere alguno contra quien por leyes especiales, no puede correr la prescripción, esta no correrá contra los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e8f82cb-06ff-48c0-94c1-af0a3b56b935', 'a0000000-0000-0000-0000-000000000001', '5828089d-d167-41c6-a5ec-676c85e49024', '820', 'Prescripción de las servidumbres legales', 709, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e95fa4fd-55e7-4727-b2f1-a9395948bcaa', '0e8f82cb-06ff-48c0-94c1-af0a3b56b935', 1, 'Las servidumbres legales establecidas por utilidad pública o comunal, se pierden por el no uso de cinco años, si se prueba que durante este tiempo se ha adquirido, por el que disfrutaba aquéllas, otra servidumbre de la misma naturaleza por distinto lugar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2651379d-1ba1-4115-aa75-d73d271bc1b0', 'a0000000-0000-0000-0000-000000000001', '5828089d-d167-41c6-a5ec-676c85e49024', '821', NULL, 710, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2e2dfff-0dbe-4c58-8727-6b7b81edc874', '2651379d-1ba1-4115-aa75-d73d271bc1b0', 1, 'Los aprovechamientos comunes de las aguas públicas y las concesiones de aprovechamientos especiales, quedan sujetos a lo que establezcan la ley y reglamentos respectivos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1009e1e8-6030-425f-80db-6ac46efe4ae6', '2651379d-1ba1-4115-aa75-d73d271bc1b0', 2, 'DERECHOS REALES DE GARANTIA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4369e3d5-2b25-4a1d-9422-c69df381ebc7', '2651379d-1ba1-4115-aa75-d73d271bc1b0', 3, 'DE LA HIPOTECA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bad14238-f1d4-4c68-a1f2-f5129ef1e606', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '822', 'Concepto', 711, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('af09f228-b042-4723-86cd-07af3bcd6fe1', 'bad14238-f1d4-4c68-a1f2-f5129ef1e606', 1, 'La hipoteca es un derecho real que grava un bien inmueble para garantizar el cumplimiento de una obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9cd7e68-1b9e-4018-b38e-66bc8c55724d', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '823', 'No hay saldo insoluto', 712, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03b93668-a69e-43bd-854c-ea4abd50662a', 'a9cd7e68-1b9e-4018-b38e-66bc8c55724d', 1, 'La hipoteca afecta únicamente los bienes sobre que se impone, sin que el deudor quede obligado personalmente ni aun por pacto expreso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4adcf337-f14b-4af1-bd73-f1edf1e3720d', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '824', 'Derecho del acreedor hipotecario', 713, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3490b10-6d70-4de7-9216-549a0dc2c8b3', '4adcf337-f14b-4af1-bd73-f1edf1e3720d', 1, 'La constitución de la hipoteca da derecho al acreedor para promover la venta judicial del bien gravado cuando la obligación sea exigible y no se cumpla. Es nulo el pacto de adjudicación en pago que se estipule al constituirse la hipoteca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e549048-ad7a-4e27-8d2f-e4a13b9ba4f8', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '825', 'Indivisibilidad de la hipoteca', 714, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a495469-dbe9-4552-85ba-08a3ce37bd68', '3e549048-ad7a-4e27-8d2f-e4a13b9ba4f8', 1, 'La hipoteca es indivisible y como tal, subsiste íntegra sobre la totalidad de la finca hipotecada aunque se reduzca la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e6fb24f9-0562-4718-8520-078bca35964a', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '826', 'División del gravamen si se divide la finca', 715, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b481ffe9-35be-4fef-9ff1-ce355cbedd8e', 'e6fb24f9-0562-4718-8520-078bca35964a', 1, 'El deudor tiene el derecho irrenunciable de pedir al acreedor la reducción de la garantía mediante la liberación del gravamen hipotecario que pesa sobre alguna o varias fincas, cuando hubiere pagado más del 50% de la deuda y siempre que el valor de los inmuebles que continúen gravados, guarden una justa relación con el saldo deudor. Si la determinación de las fincas que deben quedar excluidas de la hipoteca no pudiere hacerse de común acuerdo, se hará judicialmente por medio de juicio oral.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bc79de04-fe35-4f31-b64a-16ce4ce553ea', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '827', NULL, 716, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4bb7cb59-a4de-467e-861f-6f9527d86369', 'bc79de04-fe35-4f31-b64a-16ce4ce553ea', 1, '* División del gravamen si son varias fincas. Cuando se hipotequen varias fincas a la vez por un solo crédito, todas ellas responderán conjuntamente de su pago. Sin embargo, los interesados podrán asignar a cada finca la cantidad o parte de gravamen que debe garantizar. En este caso, el acreedor no podrá ejercer su derecho en perjuicio de tercero sobre las fincas hipotecadas, sino por la cantidad que a cada una de ellas se le hubiere asignado; pero podrá ejercerlo sobre las mismas fincas no mediando perjuicio de tercero, por la cantidad que alguna de ellas no hubiere alcanzado a cubrir');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37bb5f78-9bba-451b-b591-0efdc1821864', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '828', 'Imputación del deudor', 717, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e2652c2-7c77-4674-83bb-9cc4a982efc7', '37bb5f78-9bba-451b-b591-0efdc1821864', 1, 'Si la parte de crédito pagado se puede aplicar a la liberación de una u otra de las fincas gravadas, el deudor elegirá la que debe quedar libre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('edeac066-1106-424d-88e2-2999512c1fb9', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '829', 'Inmueble sujeto a condición', 718, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ebae2889-d6a3-4b7e-9d51-05d7d030b951', 'edeac066-1106-424d-88e2-2999512c1fb9', 1, 'El que hipotecare un bien sobre el cual tuviere un derecho eventual limitado, o sujeto a condiciones suspensivas, rescisorias o resolutorias, que consten en el Registro de la Propiedad, lo hace con las condiciones o limitaciones a que está sujeto ese derecho aunque así no se exprese. La hipoteca surtirá efectos contra tercero desde su inscripción en el Registro, si la obligación llega a realizarse o la condición a cumplirse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '830', 'Extensión de la hipoteca', 719, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e633dfe-2247-4534-a77d-23885485311f', '8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 1, 'La hipoteca se extiende: 1. A las accesiones naturales y mejoras;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('59383075-8b41-46e9-8cc7-83111b0f3b7f', '8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 2, '2. A los nuevos edificios que el propietario construya y a los nuevos pisos que levante sobre los edificios hipotecados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a0d252a-3fa1-4bd4-ad96-0b9746376a13', '8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 3, '3. A los derechos del deudor en los excesos de la superficie del inmueble; Y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad9dc641-9628-4a36-ae83-183272b02ad0', '8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 4, '4. A las indemnizaciones que se refieran a los bienes hipotecados concedidas o debidas al propietario por seguros, expropiación forzosa o daños y perjuicios;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('66692ab4-c68b-4134-ad47-b7c40151761f', '8b8a362a-07be-4c9d-a283-8dfe0787bb4b', 5, '5. A las servidumbres y demás derechos reales a favor del inmueble.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c7d5bdcf-aadf-4b47-9ba8-0b0ede76447f', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '831', 'Pago de las indemnizaciones', 720, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('acd87d32-01d5-4f3d-a514-81a6d01c6b03', 'c7d5bdcf-aadf-4b47-9ba8-0b0ede76447f', 1, 'En caso de indemnización, los acreedores hipotecarios harán valer sus derechos sobre el precio que se pague, si fuere por expropiación por utilidad pública. Si la finca estuviere asegurada y se destruyere por incendio u otra eventualidad, subsistirá la hipoteca en los restos de la finca y además el valor del seguro quedará afecto al pago.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5550fc2-83db-4ba9-acb1-ea914ad05493', 'c7d5bdcf-aadf-4b47-9ba8-0b0ede76447f', 2, 'Si fueren varios los acreedores hipotecarios, el monto de la indemnización hasta el límite de las obligaciones que consten en el Registro, se depositará a la orden del juez para que verifique los pagos de conformidad con lo dispuesto en el artículo siguiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6bd7f64-f79b-4bd4-a3d4-a777d8aff960', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '832', NULL, 721, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f3a2b9f5-99c0-4853-915e-3d2e75c11e93', 'b6bd7f64-f79b-4bd4-a3d4-a777d8aff960', 1, 'El pago de las indemnizaciones deberá hacerlo el juez según el orden de preferencia que les corresponda legalmente a los acreedores hipotecarios. Sobre las sumas que retiren los acreedores no correrán intereses.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc73a9cc-230d-4efd-9580-fcb6ad2282a1', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '833', NULL, 722, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('386a27de-e9b4-46cf-80ba-e57d60656695', 'dc73a9cc-230d-4efd-9580-fcb6ad2282a1', 1, 'Si la indemnización por expropiación forzosa o por daños y perjuicios causados en bienes hipotecados sobre cuyos frutos o muebles se hubiere constituido');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f682f943-ec24-42df-b990-6af095a29e33', 'dc73a9cc-230d-4efd-9580-fcb6ad2282a1', 2, 'prenda agraria, no fuere especialmente aplicable al inmueble o a los bienes pignorados, el pago se hará por el juez, de manera equitativa, tomando en cuenta el monto de los capitales garantizados, los daños y perjuicios sufridos y demás circunstancias que sean necesarias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('226b668e-e3da-4913-af6e-054ce9c967a4', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '834', 'Los frutos no quedan incluidos en la hipoteca', 723, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91d1d933-9922-47ba-9a7d-86c9d0c240e6', '226b668e-e3da-4913-af6e-054ce9c967a4', 1, 'Los bienes de una finca sobre los cuales puede constituirse prenda agraria no quedarán incluidos en la hipoteca, salvo que estuvieren libres de gravamen al ejecutarse el cumplimiento de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef54a2c7-7ae2-4863-a395-b38b5bb31d50', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '835', 'Quién puede hipotecar', 724, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d89a2574-0dd9-4638-b2ab-ddd5c64f0dba', 'ef54a2c7-7ae2-4863-a395-b38b5bb31d50', 1, 'Sólo puede hipotecar el que puede enajenar, y únicamente pueden ser hipotecados los bienes inmuebles que pueden ser enajenados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b866afe2-f4eb-43ec-9e1f-a84e343ad3d1', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '836', 'Nulidad de la Prohibición de enajenar', 725, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d850d407-adfe-4703-91c8-4811f50f4369', 'b866afe2-f4eb-43ec-9e1f-a84e343ad3d1', 1, 'El dueño de los bienes gravados con hipoteca podrá siempre enajenarlos o hipotecarlos no obstante cualquier estipulación en contrario, salvo lo que se establezca en contratos que se refieran a créditos bancarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d6e41c7e-a944-4d05-9570-460499ec24bc', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '837', NULL, 726, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a257a61-12c0-41d2-9689-f4d0e8ac3efa', 'd6e41c7e-a944-4d05-9570-460499ec24bc', 1, 'El predio común no puede ser hipotecado sino con el consentimiento de todos los propietarios. Sin embargo, pueden hipotecarse los derechos que el condómino tenga en el predio común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f4b37b7f-1d48-4492-b1d0-6b06b0bdfff1', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '838', 'Bienes que no pueden hipotecarse', 727, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('22c200eb-660b-4084-8f3f-21f4677b8d73', 'f4b37b7f-1d48-4492-b1d0-6b06b0bdfff1', 1, '1. El inmueble destinado a patrimonio de familia. 2. Los bienes adquiridos por herencia, legado o donación, cuando el causante haya puesto dicha condición, pero ésta no podrá exceder del término de cinco años. Para los menores de edad, dicho término se cuenta desde que cumplan la mayoría de edad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('99c45cbe-33e7-49ce-aead-f6c7c995f61e', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '839', 'Hipoteca del edificio sobre suelo ajeno', 728, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de4350d7-26e6-4ad9-a469-18b863539c83', '99c45cbe-33e7-49ce-aead-f6c7c995f61e', 1, 'La hipoteca del edificio o parte del edificio construido en suelo ajeno, no afecta los derechos del propietario del suelo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c7e2d7e4-3927-40e2-9ed4-196f7930f021', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '840', 'Edificios en propiedad horizontal', 729, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fa9b46e-f556-4bd0-8499-3a6579f195d5', 'c7e2d7e4-3927-40e2-9ed4-196f7930f021', 1, 'El edificio organizado en el régimen de propiedad horizontal puede hipotecarse en su totalidad por resolución unánime de todos los propietarios, o separadamente por el dueño del piso o finca independiente; pero, en el primer caso, deberá determinarse la cantidad o parte de gravamen que se asigne a cada piso del edificio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37bd7462-60f6-46b4-b983-12820a15a7a3', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '841', 'Aceptación de la hipoteca', 730, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f05d845a-accf-4455-98c9-75b26dbdacbf', '37bd7462-60f6-46b4-b983-12820a15a7a3', 1, 'La constitución y aceptación de la hipoteca deben ser expresas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f385226-72f5-4d52-9953-b0a9b804ffb1', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '842', 'Hipoteca y otras garantías', 731, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a6c93171-efbc-4609-9243-cc92b978681d', '4f385226-72f5-4d52-9953-b0a9b804ffb1', 1, 'Si se constituyeren hipotecas y otras garantías, deberá determinarse la cantidad o parte de gravamen que se asigne a los bienes hipotecados y a las demás garantías. Sin embargo, si se constituye prenda e hipoteca, ésta puede garantizar el saldo insoluto que deje la prenda, pero en este caso no habrá responsabilidad personal del deudor, ni aún por pacto expreso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('be766d5b-2341-446d-a186-08b02b35351e', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '843', 'Unificación de fincas cuando una de ellas esté hipotecada', 732, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b8cbb181-cf1d-4b09-9f67-fece8dc1c3db', 'be766d5b-2341-446d-a186-08b02b35351e', 1, 'No podrán unificarse en el registro dos o más fincas cuando alguna de ellas, por lo menos, estuviere hipotecada, sin que preceda convenio del propietario con los acreedores hipotecarios y los que tengan algún derecho real inscrito sobre las mismas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38bbfda0-e8df-4a43-8461-e1b39cb0c8e3', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '844', 'Intereses sobre el capital que asegura la hipoteca', 733, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd16efab-c0f0-493b-9985-c1aa3e50d4c3', '38bbfda0-e8df-4a43-8461-e1b39cb0c8e3', 1, 'La hipoteca constituida en garantía de una obligación que devengue intereses, no asegurará, con perjuicio de tercero, sino los intereses de las dos últimas anualidades y los que se causen desde que se anote la ejecución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0049d46c-4794-4cfe-892f-de141ba56c4f', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '845', 'Insuficiencia de la garantía', 734, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18dd61cd-09f3-42cd-9323-aefbd152ba5b', '0049d46c-4794-4cfe-892f-de141ba56c4f', 1, 'Si la garantía ya no fuere suficiente por haber disminuido el valor de la finca hipotecada, el acreedor podrá exigir que se mejore la garantía hasta hacerla suficiente para responder de la obligación. Si quedare comprobada, mediante prueba pericial la insuficiencia de la garantía y el deudor no la mejorare dentro del término que señalare el juez, el plazo se dará por vencido y procederá el cobro del crédito');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7e6e5caa-0aed-4ef0-89b3-24cce6cf3194', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '846', 'Cancelación de gravámenes en caso de remate', 735, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f007c452-8d57-4847-af43-9d7d55efc5c5', '7e6e5caa-0aed-4ef0-89b3-24cce6cf3194', 1, 'Los bienes rematados por ejecución de un acreedor hipotecario, pasarán al rematario o adjudicatario libres de las hipotecas de grado inferior que sobre ellos pesaren y también de los demás gravámenes, inscripciones y anotaciones inscritas con posterioridad a la inscripción de la hipoteca motivo de la ejecución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7f53bc5-77fe-49cc-85ae-3f05f4b2b9c7', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '847', NULL, 736, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e48284c9-12b9-4536-b5f3-4f478e5347e1', 'b7f53bc5-77fe-49cc-85ae-3f05f4b2b9c7', 1, 'También tiene derecho el rematario o adjudicatario a que se cancelen las hipotecas anteriores, siempre que pagare íntegramente los capitales e intereses hasta el vencimiento de los plazos o la fecha de pago, si ya hubieren transcurrido los plazos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0cf06111-fd3e-463b-adbe-cbb7dbf39c67', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '848', NULL, 737, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5eb11635-c9e9-450b-aec7-661c82b71670', '0cf06111-fd3e-463b-adbe-cbb7dbf39c67', 1, 'Los bienes inmuebles rematados en virtud de ejecución no hipotecaria, pasarán al adquirente con los gravámenes, anotaciones y limitaciones inscritos con anterioridad a la anotación de la demanda ejecutiva o del embargo, en su caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5a251b87-5a4f-4ad2-8e12-ff70572d7500', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '849', 'Derecho de tanteo en el remate', 738, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a30be36c-b84a-4ad2-b173-74f6fdc69d19', '5a251b87-5a4f-4ad2-8e12-ff70572d7500', 1, 'Después de los comuneros, los acreedores hipotecarios por su orden, tendrán derecho preferente durante el remate, a que la finca se les adjudique por la mejor postura que se hiciere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a78bf41-9554-401a-abf0-695d3ce69602', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '850', 'Pagos con el precio que se obtenga en le remate', 739, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fe3b44c2-3566-46ef-9aec-668483b895ef', '7a78bf41-9554-401a-abf0-695d3ce69602', 1, 'Del precio que se obtenga en la venta judicial de los bienes gravados, se pagarán:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8120890d-f53c-4793-bb39-9811b5dd3d44', '7a78bf41-9554-401a-abf0-695d3ce69602', 2, '1. Los gastos de rigurosa conservación que haya autorizado el juez;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e624b4ff-6ad5-4c78-9673-49580f1c9b88', '7a78bf41-9554-401a-abf0-695d3ce69602', 3, '2. La deuda por contribuciones de la finca o fincas objeto de la ejecución, correspondientes a los últimos cinco años;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4449d00f-f348-43ec-92fb-21d9380dc3e5', '7a78bf41-9554-401a-abf0-695d3ce69602', 4, '3. La deuda por seguros vigentes de la finca o fincas rematadas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5c4d7fc9-6763-42a6-82c5-1e4c4106cdd0', '7a78bf41-9554-401a-abf0-695d3ce69602', 5, '4. Los gastos del procedimiento ejecutivo, comprendiendo honorarios de abogado, procurador, depositario o interventor y expertos, regulados conforme a la ley; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1bfdaf1a-4a20-4834-9472-5d6b965e7bd9', '7a78bf41-9554-401a-abf0-695d3ce69602', 6, '5. Los acreedores hipotecarios, subhipotecarios o prendarios, conforme al lugar y preferencia legal de sus títulos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d0e976b6-b322-40ce-91b9-cb1009bb6e9d', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '851', NULL, 740, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c8f06f3a-2ed7-423c-9938-69118cfb548a', 'd0e976b6-b322-40ce-91b9-cb1009bb6e9d', 1, 'Si hubieren sido varias las ejecuciones, los pagos a que se refiere el inciso 4, del artículo anterior quedarán sujetos al orden de preferencia que corresponda a cada hipoteca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fcc1ecd7-ead8-4927-bb8a-0462c74aa178', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '852', 'Subhipoteca', 741, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2087c97-e727-4eee-8785-15230bb61c00', 'fcc1ecd7-ead8-4927-bb8a-0462c74aa178', 1, 'El crédito garantizado con hipoteca puede subhipotecarse en todo o en parte, llenándose las formalidades aplicables establecidas para la constitución de la hipoteca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83d80bbd-2a41-4d70-9355-964aeb27f8ec', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '853', 'Notificación al deudor', 742, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c11056ef-818b-4507-b7eb-83f81145c281', '83d80bbd-2a41-4d70-9355-964aeb27f8ec', 1, 'La subhipoteca deberá notificarse al deudor para que pueda inscribirse en el Registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e36c488-90ab-40f7-b068-ebed3603fe3d', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '854', 'Pago con intervención judicial', 743, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e71c27c3-7c44-41d4-8a27-fa48b4b9aff2', '8e36c488-90ab-40f7-b068-ebed3603fe3d', 1, 'Si el crédito estuviere subhipotecado o anotado, el deudor deberá hacer el pago con intervención judicial, si no hubiere acuerdo entre los interesados. El juez ordenará los pagos correspondientes y la cancelación de los gravámenes o anotaciones que los garantizaren.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca1ea905-1ca1-455b-81db-97425ee2d825', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '855', 'Caso en que la subhipoteca ocupa el lugar de la hipoteca', 744, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d9adf656-99d8-4363-b9f4-4695859154cb', 'ca1ea905-1ca1-455b-81db-97425ee2d825', 1, 'Si la finca pasare en propiedad al acreedor hipotecario, la hipoteca se extingue, pero la subhipoteca ocupará su lugar como hipoteca, en favor del acreedor respectivo, sin que la responsabilidad del inmueble pueda exceder del crédito hipotecario gravado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61ce2547-58ca-4939-8e84-1678f55bb6b7', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '856', 'Prescripción de la hipoteca', 745, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bb72681-d4c4-4e87-8dfc-c1aa1be18323', '61ce2547-58ca-4939-8e84-1678f55bb6b7', 1, 'La obligación garantizada con hipoteca prescribirá a los diez años contados desde el vencimiento de la obligación o de la fecha en que se tuviere como vencido en virtud de lo estipulado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('30ee7c6d-9c02-45d1-9e15-d5fcc3d07b7a', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '857', 'Hipoteca en cuentas corrientes de crédito', 746, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5962cc6a-dded-4524-803f-e728762e0599', '30ee7c6d-9c02-45d1-9e15-d5fcc3d07b7a', 1, 'Puede constituirse hipoteca en garantía de crédito en cuenta corriente, fijándose en la escritura de constitución la cantidad máxima de que responda la finca hipotecada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3988939-c0a9-4455-9dc4-b6f5209400fc', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '858', 'Garantía que presta la hipoteca', 747, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('719fe468-d9dc-4eb8-872b-f4ae982625d5', 'e3988939-c0a9-4455-9dc4-b6f5209400fc', 1, 'La hipoteca constituida para garantizar un crédito abierto con limitación de cantidad, garantiza las sumas parciales entregadas a cuenta en cualquier tiempo, en cuanto no excedan de la suma prefijada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('04a8272b-bb85-4422-82af-f7cbbbe8e8ff', 'a0000000-0000-0000-0000-000000000001', '52f3edcb-73e7-402f-b606-78991ea7d806', '859', 'Hipoteca de cédulas', 748, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7cf4f119-fda2-4698-a19e-0c6e7979d54a', '04a8272b-bb85-4422-82af-f7cbbbe8e8ff', 1, 'Puede constituirse hipoteca en garantía de obligaciones futuras a favor de instituciones bancarias. En este caso, es indispensable designar al acreedor, el monto máximo de las obligaciones que se garantiza y el término de vigencia de la garantía. En la escritura en que se establezcan las obligaciones o se otorguen los préstamos, deberán consignarse que están garantizados con la hipoteca preconstituida y cada obligación o préstamo quedará sujeta además a las estipulaciones que se hubieren especificado en cada caso en el contrato o título respectivo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd85c622-d49d-48b6-b9a7-f0c2ac4f6679', '04a8272b-bb85-4422-82af-f7cbbbe8e8ff', 2, 'CEDULAS HIPOTECARIAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8c18d143-5368-49a6-9025-53cac6060ac3', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '860', NULL, 749, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('827f8862-ca61-4996-bf9a-272dc43d0cdd', '8c18d143-5368-49a6-9025-53cac6060ac3', 1, 'Puede constituirse hipoteca para garantizar un crédito representado por cédulas sin que sea necesario que haya acreedor y emitirse las cédulas a favor del mismo dueño del inmueble hipotecado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63952a8e-e483-4d8c-870b-272e9b31eed8', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '861', 'Solidaridad de gravamen si son varios bienes', 750, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('538adc48-2fb8-4c22-a9b0-b11d59689f57', '63952a8e-e483-4d8c-870b-272e9b31eed8', 1, 'Si son varios los inmuebles hipotecados, todos ellos garantizarán solidariamente el crédito; y si forman un solo cuerpo, deberán unificarse previamente en el registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed10d23a-0509-41c3-989f-74f03a820cba', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '862', 'Propiedades pro indiviso y en que exista usufructo', 751, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dbe7c6ca-cb84-4161-a905-df83bd18eef5', 'ed10d23a-0509-41c3-989f-74f03a820cba', 1, 'Las propiedades que estén pro indiviso y aquellas en que la nuda propiedad y el usufructo correspondan a diversas personas, se admitirán en garantía, siempre que en el primer caso consientan expresamente en el gravamen de toda la propiedad los copropietarios y en el segundo el usufructuario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('22089dea-25f0-4689-8a76-7d309eb218aa', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '863', 'Propiedades gravadas', 752, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('69c29e44-bda6-4ca1-b449-4f02c546ad8e', '22089dea-25f0-4689-8a76-7d309eb218aa', 1, 'No se admitirán en garantía las propiedades que se encuentren anotadas o gravadas ni las sujetas a condiciones suspensivas, rescisorias o resolutorias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3bf07d76-a081-448b-a680-4029c4a52f60', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '864', 'Bonos bancarios', 753, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dcb88f82-72e9-40b9-bfde-5ab3a7df3daa', '3bf07d76-a081-448b-a680-4029c4a52f60', 1, 'Los bancos de crédito territorial podrán emitir cédulas o bonos hipotecarios por una suma Igual al importe total de los préstamos sobre inmuebles que otorgaren.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '865', NULL, 754, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d29544e4-4da0-4005-9b58-5d0dffb4a8f4', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 1, 'La hipoteca de cédulas se hará constar en escritura pública que deberá contener los requisitos especiales siguientes: 1. El monto del crédito representado por las cédulas y el monto de cada serie; si se emitieron varias;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3313ec0a-06c9-4e65-8c61-c96cb8c98be9', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 2, '2. El valor y número de cédulas que se emiten y la serie a que pertenecen;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('75e130d9-dfe3-4853-96e7-3e434b78f748', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 3, '3. El tipo de interés y el tiempo y lugar del pago;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0c52839f-81d6-4d17-9d18-25eaa17becd8', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 4, '4. El plazo del pago o los pagos sucesivos en caso de hacerse amortizaciones graduales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e43e24dc-8915-4e02-9c38-7efa9412bfd5', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 5, '5. Identificación de la finca o fincas hipotecadas y expresión del monto del avalúo practicado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec07c04b-6fa6-43f7-97dd-fddca8dfab54', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 6, '6. Designación de persona o institución que como agente financiero esté encargado del servicio de la deuda, pago de intereses, comisiones y amortizaciones;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c31bcb0b-f67d-4f33-b5b4-209d1effe709', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 7, '7. El nombre de la persona o institución a cuyo favor se hace la emisión, en caso de que no fuere al portador y el del propio otorgante si fuere a su favor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a6b31e1-5308-49b0-85fa-063fc9f5b9d5', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 8, '8. La especificación de las emisiones anteriores, si las hubiere; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7be9dec-e07a-492b-825a-7e8607c1e76e', 'e09159b4-3ee0-4e10-8ea1-25a12b2642cd', 9, '9. Si la emisión se dividiere en series, el orden de preferencia para su pago, si se hubiere establecido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('34c087dd-7bd2-45e5-8b83-ec113b00c754', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '866', 'Requisitos de la escritura de cédulas o bonos', 755, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('902ce2ea-4235-477b-830d-a71fd9f7f4ce', '34c087dd-7bd2-45e5-8b83-ec113b00c754', 1, 'Verificada la inscripción de la hipoteca en el Registro, se emitirán las cédulas. Cada cédula será del valor de cien quetzales o de cualquier múltiplo de cien');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5c1cf37e-678e-4db1-990e-4280966c1962', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '867', 'Emisión de cédulas', 756, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd467374-6dd3-4427-9481-385e164873dd', '5c1cf37e-678e-4db1-990e-4280966c1962', 1, 'El monto de la emisión de cédulas hipotecarias no puede exceder del setenta y cinco por ciento del avalúo del inmueble hipotecado, practicado por valuador autorizado o bancario y aprobado por el Ministerio de Hacienda y Crédito Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6ec2a15-a50c-42a2-9ccc-521028e56154', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '868', 'Requisitos de las cédulas o bonos', 757, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('58ca778e-94b7-42e5-b756-dff0cff8c47d', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 1, 'Las cédulas contendrán: 1. Número de orden e indicación de la serie a que pertenecen.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c670dcc-9128-46e3-8022-e817b3040b29', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 2, '2. Un resumen de las disposiciones pertinentes de la escritura en que se constituye la hipoteca;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('494b7a8c-5074-4f36-9f2b-d8513ad0d2f4', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 3, '3. El número de cupones y sus respectivos vencimientos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11e04d0c-c049-4411-b087-86bf6346391f', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 4, '4. Lugar y fecha de la emisión de las cédulas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95495291-f88b-4bce-b397-ee8e4f2727d0', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 5, '5. Firma del agente financiero;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('392e344e-6f50-476f-ae0d-f2674870ae4b', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 6, '6. Firma del otorgante de la hipoteca; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e81408e-fb3b-4d8e-a301-aabff9cee635', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 7, '7. Firma y sello del registrador de la Propiedad Inmueble.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('613daa52-8f21-4a4d-947c-7df286edfc7c', 'b6ec2a15-a50c-42a2-9ccc-521028e56154', 8, 'Las cédulas emitidas por una institución bancaria, serán firmadas por el representante legal de la misma, sin los requisitos enunciados en los incisos 6 y 7.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2df883f-3f1a-4e85-a488-f65baffa27b7', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '869', 'Cupones de las cédulas', 758, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5c8671d-28c3-4483-9f37-fb8c5d02db1a', 'c2df883f-3f1a-4e85-a488-f65baffa27b7', 1, 'Si el crédito devenga intereses y éstos no se hubieren descontado, se agregará a cada cédula tantos cupones que sirvan de título al portador para la cobranza de aquéllos, como períodos de pago de intereses.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('192f7fd9-a9ea-4ea7-a392-6660a9356779', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '870', 'Requisitos que deben tener los cupones', 759, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b9687887-0f5e-4657-98ee-3e3a7771a9ac', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 1, 'Cada cupón contendrá: 1. La denominación de cupón hipotecario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b028ab35-317b-4c3d-a9c9-f62a1c2ff9e7', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 2, '2. El número, serie, lugar y fecha de la cédula;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5835ed79-91e4-479c-a6da-346dd10cd9e3', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 3, '3. El valor y especie en que debe pagarse;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('587c9429-d0ef-4774-9105-3f62eac2814c', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 4, '4. Lugar y fecha de su pago;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f544b302-4a5c-4b4c-be33-50d7d81e516d', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 5, '5. La firma del otorgante de la hipoteca; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6dfd27a8-8d60-4cda-aa18-9f1d84634a23', '192f7fd9-a9ea-4ea7-a392-6660a9356779', 6, '6. El sello del Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f0b729c4-648c-4617-a8a7-023bc755a033', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '871', 'Deben redactarse en español', 760, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76fe0a12-d2c2-41b9-996c-34fccfb0684d', 'f0b729c4-648c-4617-a8a7-023bc755a033', 1, 'Las cédulas y los cupones se redactarán en español, irán impresos, grabados o litografiados, podrán contener traducciones a uno o varios idiomas extranjeros y no causarán impuesto de papel sellado ni timbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b315c35a-0605-4ba3-ba88-b3f15692ff14', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '872', 'Son títulos que aparejan ejecución', 761, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('26e9560f-eca2-4c05-8347-d9cd146fdf57', 'b315c35a-0605-4ba3-ba88-b3f15692ff14', 1, 'Las cédulas y los cupones vencidos son títulos que aparejan ejecución y pueden traspasarse por la simple tradición si fueren al portador, o por endoso si fueren nominativos. El endoso no hace responsable al endosante y se reputará auténtico mientras no se pruebe lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8a5b6293-52b8-4550-b8dd-4beef5f49654', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '873', 'Depreciación de la garantía', 762, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae6fcc80-07ba-4e9c-bd4a-4590eea13280', '8a5b6293-52b8-4550-b8dd-4beef5f49654', 1, 'Si la finca hipotecada desmejorare él valor y se tema fundadamente que pueda llegar a no cubrir las responsabilidades hipotecarias, los tenedores de cédulas que representen por lo menos el 25 por ciento de las no pagadas, podrán pedir al juez la venta del inmueble aunque el plazo no esté vencido, a menos que el deudor amplíe la garantía de conformidad con lo dispuesto en el artículo 845, de lo cual será notificada la persona encargada del servicio de la deuda. Si la venta se efectuare, con el precio que se obtenga se hará el pago del crédito, descontándose los intereses anticipados y los no vencidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ed44769-0338-46c8-aac5-b5e6190c6f54', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '874', 'Intervención del inmueble', 763, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfc1e3d9-31c5-4a91-9c10-d9a631972f93', '9ed44769-0338-46c8-aac5-b5e6190c6f54', 1, 'Si el poseedor de la finca hipotecada no la cuidare y atendiere como es debido, dentro de una prudente administración, los tenedores del veinticinco por ciento de las cédulas no redimidas o la institución encargada del servicio de la deuda, podrán pedir que se ponga la finca en intervención. El juez, con justificación de los hechos nombrará interventor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b398d733-81ca-4916-b724-544363283bb8', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '875', 'Repartición del precio del remate', 764, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b290dac-089b-4c7e-bbcc-c56751acfaf4', 'b398d733-81ca-4916-b724-544363283bb8', 1, 'Cuando el precio del remate no alcance a cubrir la totalidad de la primera hipoteca, se repartirá a prorrata entre las cédulas correspondientes a tal hipoteca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('91a43111-0629-46ce-93b2-a084bd16a3bd', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '876', 'Consignación del valor de las cédulas o cupones', 765, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfae879d-c8e2-4bfc-8e9e-f8d5a1f472cf', '91a43111-0629-46ce-93b2-a084bd16a3bd', 1, 'Las cédulas o cupones vencidos que no se presenten para su cobro, podrán ser pagados por consignación de su valor ante el juez. En la misma forma podrán pagarse las cédulas y cupones no vencidos si el deudor quisiere cancelarlos antes del vencimiento.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3182e6d7-de75-46a9-9c1e-47b8fbeb435c', '91a43111-0629-46ce-93b2-a084bd16a3bd', 2, 'La constancia de la consignación aprobada servirá para la cancelación de la hipoteca en el registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7e117e57-7a72-4c70-b90d-673269fc40df', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '877', 'Reposición de cédulas o bonos', 766, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7b96580-3152-447c-99e8-cb6aa802bdf7', '7e117e57-7a72-4c70-b90d-673269fc40df', 1, 'La reposición de las cédulas o bonos se sujetará a lo establecido para la reposición de títulos o acciones de sociedades anónimas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('628d8168-e010-4715-9857-ea14f4b592d4', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '878', 'Cancelación de la hipoteca', 767, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9fbf49a0-3978-44bd-b82f-6b091e040dcc', '628d8168-e010-4715-9857-ea14f4b592d4', 1, 'La hipoteca de cédulas se cancelará por uno de los medios siguientes: 1. Por escritura pública otorgada por el emisor o por el intermediario si lo hubiere. Con el testimonio deberán presentarse al Registro las cédulas a que se refiere la cancelación o la constancia de la consignación por las cédulas y cupones no presentados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7256a59-f9b2-4db0-bafa-518a67a75646', '628d8168-e010-4715-9857-ea14f4b592d4', 2, '2. Por solicitud escrita al Registro acompañando las cédulas o constancia de depósito en su caso; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e30121b-ca96-4d96-8844-5617759a8484', '628d8168-e010-4715-9857-ea14f4b592d4', 3, '3. Por sentencia firme.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('04001b96-e22e-4c80-83cd-e2e4e02ebcd4', '628d8168-e010-4715-9857-ea14f4b592d4', 4, 'Las cédulas se conservarán originales en el Registro, con la razón de haber sido canceladas; pero no será necesario presentar copia de ellas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb387d86-40a2-4880-9ae8-0a54d57f14a2', 'a0000000-0000-0000-0000-000000000001', '03ff5023-c561-43fb-893e-8c3d43487dad', '879', NULL, 768, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b138fcc8-8a73-4fa4-9106-449c161618cd', 'eb387d86-40a2-4880-9ae8-0a54d57f14a2', 1, 'Las disposiciones de la hipoteca común son aplicables a la hipoteca de cédulas siempre que no contraríen lo dispuesto en este capítulo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3d40a6c6-b830-41f2-a44d-5603f5434429', 'eb387d86-40a2-4880-9ae8-0a54d57f14a2', 2, 'PRENDA COMUN');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('09e0f208-f7e2-4710-8542-53b9da9c684b', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '880', 'Concepto', 769, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e55d39c8-e316-43cb-bd19-041154fa3e61', '09e0f208-f7e2-4710-8542-53b9da9c684b', 1, 'La prenda es un derecho real que grava bienes muebles para garantizar el cumplimiento de una obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('58fb971f-3516-44f2-b442-2d2ca8d9bf19', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '881', 'Saldo insoluto', 770, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb4a5c3e-8799-403c-ab49-4e1741af4437', '58fb971f-3516-44f2-b442-2d2ca8d9bf19', 1, 'La prenda afecta únicamente los bienes sobre que se impone, cualquiera que sea su poseedor, sin que el deudor quede obligado personalmente, salvo pacto expreso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4655c4b0-5030-472f-9074-a679310b0e0f', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '882', 'Derecho que tiene el acreedor', 771, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bd3ff5b-6c51-4762-a6be-4139e353838a', '4655c4b0-5030-472f-9074-a679310b0e0f', 1, 'El contrato de prenda da al acreedor el derecho de ser pagado con preferencia a otros acreedores del precio en que se venda la prenda. Es nulo todo pacto que autorice al acreedor para apropiarse la prenda o para disponer de ella por sí mismo en caso de falta de pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ad6b7a86-7c6b-4146-a319-b2771f793fdb', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '883', 'Prenda a varias personas sucesivamente', 772, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7e4aad7-2937-4196-9a11-33de50b18532', 'ad6b7a86-7c6b-4146-a319-b2771f793fdb', 1, 'Un objeto puede darse en prenda a varias personas sucesivamente, con previo aviso en forma auténtica a los acreedores que ya tienen la misma garantía. Los acreedores seguirán el orden en que han sido constituidas las prendas para el efecto de la preferencia en el pago. El primer acreedor tendrá derecho de sustituir al depositario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1511a426-e19a-41a2-bf48-78694d335ef1', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '884', 'Formalidades para la constitución de la prenda', 773, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('39275593-cfbf-4c90-8600-5f474b114659', '1511a426-e19a-41a2-bf48-78694d335ef1', 1, 'La prenda debe constar en escritura pública o documento privado, haciéndose constar la especie y naturaleza de los bienes dados en prenda, su calidad, peso, medida, cuando fueren necesarios, y demás datos indispensables para su identificación; nombre del depositario y especificación de los seguros que estuvieren vigentes sobre los bienes pignorados. La aceptación del acreedor y del depositario deberá ser expresa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93dcaf05-b8af-4c27-a35d-5d9b72c2133b', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '885', 'Depositario', 774, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('240f06e0-bdc4-4b4d-be68-f4d4c5e129df', '93dcaf05-b8af-4c27-a35d-5d9b72c2133b', 1, 'Los bienes pignorados, al constituirse la garantía, deberán ser depositados en el acreedor o en un tercero designado por las partes, o bien en el propio deudor si el acreedor consiente en ello. La persona que reciba la prenda tiene las obligaciones y derechos de los depositarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c22796e5-3076-4c0a-ba89-cc666bfdf099', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '886', NULL, 775, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b3fd021a-4daf-43a9-9326-1df3004a2ee2', 'c22796e5-3076-4c0a-ba89-cc666bfdf099', 1, 'La prenda de los títulos nominativos se constituirá por medio de endoso al celebrarse el contrato que es objeto de la garantía y el deudor recibirá un resguardo con el fin de hacer constar el objeto del endoso. En este caso el deudor dará aviso de la pignoración a la institución emisora para que no se haga ningún traspaso de los títulos pignorados, mientras estén afectos a la obligación que garanticen. La prenda de títulos al portador se hace por la mera tradición de éstos, describiéndolos en el contrato respectivo, y el deudor recibirá un resguardo para su propia garantía.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b58f7c04-5844-42d7-bf00-395ba502973b', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '887', 'Prenda de créditos', 776, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec0f1ed0-655b-47e3-9a83-d4bca5e61b8d', 'b58f7c04-5844-42d7-bf00-395ba502973b', 1, 'Siempre que la prenda fuere un crédito, el depositario estará obligado a hacer lo que sea necesario para que no se altere ni menoscabe el derecho que aquél representa. Las cantidades que reciba las aplicará a la amortización de intereses y capital, si fuere el caso, salvo lo que las partes convengan en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03731fe7-6c8b-4640-8a53-4e3e8f8e26d5', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '888', NULL, 777, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a64a408-2b2e-4a40-899b-0bf0a76fd668', '03731fe7-6c8b-4640-8a53-4e3e8f8e26d5', 1, 'Prenda de facturas Cuando la garantía consista en facturas por cobrar, el depositario de la prenda hará el cobro, retendrá su valor en depósito y lo hará saber a los interesados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec2670b9-81b2-4261-9438-276e66c00795', '03731fe7-6c8b-4640-8a53-4e3e8f8e26d5', 2, 'Si consistiere en facturas de mercadería por recibir, tomará la mercadería y la conservará en prenda, dando también aviso a los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e83ac73d-7744-4280-9f30-d8d3aba066c9', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '889', 'Prenda constituida por un tercero', 778, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b18bd8f-9f6c-4b57-b537-f32f19f3c365', 'e83ac73d-7744-4280-9f30-d8d3aba066c9', 1, 'Si el bien pignorado no pertenece al deudor sino a un tercero que no ha consentido en el gravamen, la prenda no subsiste y el acreedor podrá exigir que se le preste otra garantía a su satisfacción, o se le pague inmediatamente su crédito; pero si el acreedor hubiere procedido de mala fe, no tendrá los derechos a que se refiere el presente artículo. El tercero no podrá exigir del acreedor la restitución de la prenda sin reembolsar a éste el valor del crédito y sus intereses, cuando el que prestó la garantía negocie en cosas análogas o las hubiere adquirido en feria o venta pública.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f3cfd2a9-245d-4e18-9bfc-ef69c4439b8e', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '890', 'Saneamiento', 779, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c4d6d81-9890-4de2-b469-354a456160fa', 'f3cfd2a9-245d-4e18-9bfc-ef69c4439b8e', 1, 'El deudor está obligado al saneamiento de la cosa dada en prenda, pero si se tratare de créditos u otros valores, únicamente responderá de su existencia y legitimidad en el momento de la pignoración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dfb47337-e4ca-4202-9fd4-b2554fb18855', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '891', 'Imputación del deudor', 780, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f5a63e0-2875-4fc4-884a-d4e7a667472a', 'dfb47337-e4ca-4202-9fd4-b2554fb18855', 1, 'El deudor no podrá reclamar la restitución de la prenda mientras no haya pagado la totalidad de la deuda, salvo que siendo varios los bienes pignorados, los interesados hubieren convenido en asignar a cada cosa la cantidad por la que debe responder.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8303e12d-41a4-4258-9f4a-60ba869a4390', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '892', 'Uso del bien pignorado', 781, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f14d5ccb-8771-418b-a75d-34fbae082bf3', '8303e12d-41a4-4258-9f4a-60ba869a4390', 1, 'Los bienes dados en prenda no se podrán usar sin consentimiento del dueño y del acreedor. Tampoco podrán ser trasladados fuera del lugar de la explotación agrícola, pecuaria o industrial o del señalado en el contrato, ni exportarse sin autorización escrita del acreedor. El poseedor de las cosas dadas en prenda que disponga en cualquier forma de ellas y el tercero que las adquiera, si el gravamen estuviere inscrito en el registro quedan igualmente obligados y responsables ante el acreedor, civil y criminalmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('db39b6aa-c7ed-4c07-8516-a0c72cee7c21', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '893', 'Abuso del depositario', 782, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f74a4671-df65-439e-a8d4-e4d410e23376', 'db39b6aa-c7ed-4c07-8516-a0c72cee7c21', 1, 'Si el depositario abusare de la prenda será responsable en caso de pérdida o deterioro y el deudor tendrá derecho de hacerla depositar en otra persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a2831dd1-c469-4eb5-96fd-8a56b8e49001', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '894', 'Cambio de acreedor', 783, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32d667c2-0c3e-47d9-a799-9720113a40a2', 'a2831dd1-c469-4eb5-96fd-8a56b8e49001', 1, 'El cambio de acreedor no altera las condiciones del contrato');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed83eac3-b47e-4631-be28-eaf87c6e471c', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '895', 'Amortización con los frutos', 784, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec1c394e-76c1-4d2b-a328-9b0e8ad8fd14', 'ed83eac3-b47e-4631-be28-eaf87c6e471c', 1, 'Los frutos de la cosa empeñada pertenecen al dueño de ella; pero si por convenio los percibe el acreedor, su importe se aplicará primero a los intereses y el sobrante al capital. Esta disposición rige también para el caso de indemnización.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('45a3674b-86bb-4e91-a06f-8bb1aeadbbc7', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '896', 'Pérdidas o destrucción de la prenda', 785, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11b181ae-862b-4ac3-a375-93a97fb2f52f', '45a3674b-86bb-4e91-a06f-8bb1aeadbbc7', 1, 'Si se perdiere o destruyere la prenda, será pagada por el depositario, quien sólo podrá eximirse de esta obligación probando que no se perdió ni destruyó por su culpa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('035973b3-5ef4-40be-80a4-afa99392cc16', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '897', NULL, 786, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87e716fd-e498-4ba3-a570-45a035c69a8f', '035973b3-5ef4-40be-80a4-afa99392cc16', 1, 'Cuando la pérdida fuere por accidente o caso fortuito acaecido después de pagado el crédito o de cumplida la obligación principal, el depositario pagará el valor de la prenda si no tuvo justa causa para demorar su devolución. Tiene igual responsabilidad el acreedor que sin causa legal, no quiso admitir anteriormente el pago de su crédito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e536f731-1ed4-4ff1-b5d7-8a3bf8847e54', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '898', 'Depreciación y venta de la cosa pignorada', 787, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4873916a-abfe-4115-9de8-5a697a8e8b61', 'e536f731-1ed4-4ff1-b5d7-8a3bf8847e54', 1, 'Si la cosa dada en prenda se deteriora o disminuye su valor, el acreedor o el deudor pueden solicitar que se venda en pública subasta, o al precio corriente. La disminución o la suficiencia de la garantía las calificará el juez en juicio oral. Si se efectuare la venta de la prenda, su importe sustituirá la cosa, pero si calculado el monto del capital e intereses hasta el vencimiento del plazo o la fecha de pago, resultare excedente, éste se entregará al propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca89dff4-ec18-49ff-b735-93282387f8e3', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '899', 'Oposición a la venta', 788, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47d77774-d55c-4fe9-b82d-24e51cad4eb3', 'ca89dff4-ec18-49ff-b735-93282387f8e3', 1, 'El deudor puede oponerse a la venta y obtener la restitución de la cosa, constituyendo otra garantía declarada suficiente por el juez, oyendo expertos. Este derecho es irrenunciable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1669fce9-4980-4c42-bacb-6b4db3c735d0', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '900', 'Venta solicitada por el deudor', 789, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b771961d-67a0-4d5c-a7b5-2e92ca142047', '1669fce9-4980-4c42-bacb-6b4db3c735d0', 1, 'También puede el deudor solicitar la venta en igual forma, de la cosa o cosas pignoradas, si se le presentare ocasión ventajosa para hacerlo, en cuyo caso, una vez verificada la venta, se procederá como lo dispone el párrafo segundo del artículo 898.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dfa04c73-6bc3-4ab6-9956-d56ade5bc326', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '901', NULL, 790, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c29253b5-5ec4-4571-98e8-566e3f69c224', 'dfa04c73-6bc3-4ab6-9956-d56ade5bc326', 1, 'Cuando fueren varias las cosas dadas en prenda y su valor total excediere del monto del crédito, el juez, podrá, a solicitud del deudor y previa calificación, limitar la venta a las cosas cuyo valor sea suficiente a cubrir la deuda, sin perjuicio de subastar las restantes si el precio de las vendidas no cubriere la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61de4e02-fbb8-41ec-8582-7d997638ef86', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '902', NULL, 791, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b68fd2f0-1ff7-497d-bda8-91c4ff566184', '61de4e02-fbb8-41ec-8582-7d997638ef86', 1, 'Las indemnizaciones relativas a los bienes pignorados quedan afectas al pago del crédito prendario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bd889c59-acaf-4d00-a055-bc37928bfa31', 'a0000000-0000-0000-0000-000000000001', '6e5629e7-4f06-454f-af67-13025fd1a745', '903', 'Montes de piedad', 792, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f76599a3-ded2-46cd-a2de-9917772692fe', 'bd889c59-acaf-4d00-a055-bc37928bfa31', 1, 'Respecto de los montes de piedad y demás establecimientos autorizados para prestar sobre prendas, se observarán las leyes y reglamentos que les conciernen, y subsidiariamente las disposiciones de este capítulo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0b2fa31-af52-48a7-9845-5cbac52a7c04', 'bd889c59-acaf-4d00-a055-bc37928bfa31', 2, 'PRENDA AGRARIA, GANADERA E INDUSTRIAL');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dcb8146b-8303-4a9e-be7c-3615a718a7ef', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '904', NULL, 793, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c66a280-0edd-4de7-98f5-194f286791b0', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 1, 'Bienes que pueden ser objeto de prenda sin desplazamiento Puede constituirse prenda con independencia de los inmuebles a que pertenezca y quedan en posesión del deudor, sobre los bienes siguientes:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f967e914-c63b-4873-8530-8113ac5097f2', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 2, '1. Los frutos pendientes, futuros o cosechados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98bb82bf-9529-4fe7-9f2b-beeb6d6a9c01', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 3, '2. Los productos de las plantas y las plantas que sólo pueden utilizarse mediante el corte.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0dc9f1cd-8e0b-4a2c-b238-273797ae3a1f', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 4, '3. Las máquinas, aperos o instrumentos usados en la agricultura.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ea89c62-e972-4c36-8101-7233ca8f8045', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 5, '4. Los animales y sus crías.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c9cd5682-a4a4-4867-bdde-8ab33fe42113', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 6, '5. Las máquinas e instrumentos usados en la industria.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d72308d7-ddd7-4b4d-82a6-afc1a5929ad0', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 7, '6. Las materias primas de toda clase y los productos en cualquier estado de las fábricas o industrias; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98a7cd77-cb5c-49dd-882d-640cb9998a70', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 8, '7. Los productos de las minas y canteras.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62092a2e-6295-4498-9fae-dd87e289fb0f', 'dcb8146b-8303-4a9e-be7c-3615a718a7ef', 9, 'También puede constituirse prenda sobre vehículos y demás muebles fácilmente identificables que constituyan garantía de una operación comercial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9f7c3a4e-87fd-49a9-8692-2dba6fa871bd', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '905', 'Los bienes pueden pignorarse aunque exista hipoteca', 794, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76c34267-e999-428b-8a70-601ec22c6e67', '9f7c3a4e-87fd-49a9-8692-2dba6fa871bd', 1, 'Aunque la finca estuviere hipotecada, podrán pignorarse los bienes a que se refiere el artículo anterior, pero debe darse la preferencia al acreedor hipotecario, quien podrá ejercer este derecho dentro de cinco días contados desde que el deudor le haga saber en forma auténtica, las bases del contrato que proyecta celebrar. Si el acreedor hipotecario no concede el crédito, no podrá oponerse a que el deudor lo obtenga de otra persona sobre las mismas bases.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ecef148a-6ef8-4a92-b5b4-14ef54c66ae1', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '906', 'Pago de saldo insoluto con la siguiente cosecha', 795, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('015d7f19-00bd-464b-a5c7-f6b8483c53e8', 'ecef148a-6ef8-4a92-b5b4-14ef54c66ae1', 1, 'Sólo la cosecha pendiente podrá pignorarse, pero cuando su producto no alcanzare a amortizar el crédito prendario, el saldo insoluto quedará cancelado con el producto de la cosecha subsiguiente, aunque no alcanzare a cubrir la totalidad de dicho saldo. Cuando la prenda recayere sobre ganado o productos industriales cualquier saldo quedará');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70db8c86-06d1-42ce-af19-b3873ae81481', 'ecef148a-6ef8-4a92-b5b4-14ef54c66ae1', 2, 'cancelado con las cosechas de los dos años subsiguientes. De esta limitación se exceptúan los créditos concedidos por instituciones bancarias');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dfec7092-4378-4aa7-b790-9f640fea85f7', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '907', 'Preferencia en el pago', 796, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13e528f2-e34e-4021-801b-d139d335ada4', 'dfec7092-4378-4aa7-b790-9f640fea85f7', 1, 'El acreedor prendario tiene preferencia sobre cualquier otro acreedor, en el precio de los bienes dados en prenda, por el importe del crédito, intereses y gastos si los hubiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ecdffa9-009e-43be-a3d5-909032605e59', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '908', 'Nuevos gravámenes', 797, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e52e5a5c-755c-4e9d-8737-4e3bcc08cff6', '3ecdffa9-009e-43be-a3d5-909032605e59', 1, 'Puede constituirse nuevo gravamen sobre bienes ya pignorados, o darse en garantía la parte restante de una cosecha pendiente a persona distinta del primer acreedor, siempre que éste, impuesto de las bases del contrato que se pretenda celebrar, en la forma expresada en el artículo 905, no quiera o no pueda conceder nuevo crédito; pero en todo caso, sin perjuicio de los derechos que como primer acreedor le corresponden.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7fe807f3-7cdf-4565-af03-57deed5ff48b', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '909', 'Depositario', 798, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a6f8b4e-680d-4327-b193-825cd80e7b13', '7fe807f3-7cdf-4565-af03-57deed5ff48b', 1, 'En la prenda sobre bienes fungibles podrá convenirse que los bienes pignorados puedan sustituirse, siempre y cuando el depositario tenga en existencia en el momento de la sustitución, bienes de las mismas características especificadas en el contrato respectivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('36c1baa6-362e-47a3-abb3-2ab98be1eeea', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '910', 'Inversión de los fondos', 799, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('26cc9b8b-a850-408a-9c45-06d7f342f9c6', '36c1baa6-362e-47a3-abb3-2ab98be1eeea', 1, 'Los fondos que se obtengan con prenda agraria, si hubiere hipoteca, deberán invertirse exclusivamente en gastos de administración, sostenimiento, cultivo, recolección y beneficio, y en reparación de maquinaria, en la finca de que se trata. En los créditos que se concedan para la compra de maquinaria, ganado o bienes de cualquier otra especie, se puede constituir prenda sobre esos bienes, aunque no estén todavía en poder del deudor. Esta prenda queda perfeccionada sin necesidad de otro requisito cuando el deudor adquiera los bienes pignorados');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('592c1f21-89c7-4ed3-afb2-37250ebd33b7', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '911', 'Extensión de la prenda', 800, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77309570-80a2-42cb-bbcf-f49d432ea317', '592c1f21-89c7-4ed3-afb2-37250ebd33b7', 1, 'Si para obtener nueva maquinaria, vehículos o semovientes destinados al servicio de la finca hipotecada, se dieren en prenda los frutos pendientes, la garantía prendaria se entenderá extendida a los nuevos bienes adquiridos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('caba4350-082c-405b-91b4-b3b4156d6f80', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '912', 'Inscripción en el Registro', 801, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e2346ea-8d5b-4757-ae9a-850192d4e7d7', 'caba4350-082c-405b-91b4-b3b4156d6f80', 1, 'La prenda agraria deberá inscribirse en el Registro de Inmuebles si recae en los bienes que se detallan en el artículo 904, exceptuándose la constituida sobre los bienes siguientes: 1. Los animales que no se destinan al servicio o explotación de la finca;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d88c4959-8178-437a-a4be-933acdd7e958', 'caba4350-082c-405b-91b4-b3b4156d6f80', 2, '2. Los frutos o productos ya cosechados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c186d522-fc69-400c-a5a7-608e1a74a319', 'caba4350-082c-405b-91b4-b3b4156d6f80', 3, '3. Las materias primas y los productos en cualquier estado, de las fábricas o industrias;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('633b706f-0fbc-4f9a-a073-0c36be0f2ca2', 'caba4350-082c-405b-91b4-b3b4156d6f80', 4, '4. Los productos extraídos de las minas y canteras; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b13443e-8c39-41f7-99db-6116c70e0b01', 'caba4350-082c-405b-91b4-b3b4156d6f80', 5, '5. Los enumerados en el Inciso 2, del artículo 904 si la finca fuere de un tercero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5be5a4f6-f04c-4b83-96ad-8b12b755908a', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '913', 'Prenda abierta', 802, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5072b639-5dc1-4bba-b46b-d38816922e56', '5be5a4f6-f04c-4b83-96ad-8b12b755908a', 1, 'Puede constituirse prenda en garantía de obligaciones futuras a favor de instituciones bancarias. En este caso, es indispensable designar al acreedor, el monto máximo de las obligaciones que se garantizan y el término de vigencia de la garantía. Cuando se creen las obligaciones o se otorguen los préstamos, deberá consignarse en el respectivo título o contrato que ellos están garantizados con la prenda preconstituida y que cada obligación o préstamo quedará sujeta además a las estipulaciones que se hubieren especificado en el contrato o título respectivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6cca0fb5-5c25-4bc2-a090-228fd0d6b9e2', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '914', 'Venta de los bienes', 803, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dda03d58-3a27-4013-8c26-07640d1e45ac', '6cca0fb5-5c25-4bc2-a090-228fd0d6b9e2', 1, 'Los bienes dados en prenda podrán ser vendidos por el deudor siempre que la venta sea al contado, que el precio cubra el total de lo adeudado y que previamente dé aviso al acreedor. Al hacer la venta deberá depositar el monto del crédito en el lugar donde debe hacerse el pago, ya sea en el Juzgado de Primera Instancia o en un establecimiento bancario, dentro de veinticuatro horas hábiles de haberse celebrado, más el término de la distancia, en su caso, y dar inmediatamente aviso al acreedor. La omisión de cualquiera de los requisitos aquí establecidos hace que el deudor incurra en las responsabilidades a que se refiere el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c8c48ebe-4e54-4ddd-a971-d6de57e75082', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '915', 'Derecho del acreedor para inspeccionar los bienes', 804, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('30e9c3ce-2142-4416-8b46-31bfe9fb06a7', 'c8c48ebe-4e54-4ddd-a971-d6de57e75082', 1, 'El acreedor podrá por si o por medio de un delegado, inspeccionar los bienes objeto de la prenda y si se encontraren sufriendo daño o deterioro o en estado de abandono por parte del deudor, el acreedor podrá también acudir al juez para que se nombre un interventor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('281537fc-ba85-41c3-8f21-116f9de6443f', 'a0000000-0000-0000-0000-000000000001', '5a32f14a-b172-47fa-b473-0ddc01c420f1', '916.18', NULL, 805, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea3170e6-164c-4b88-a1eb-46a04e058d85', '281537fc-ba85-41c3-8f21-116f9de6443f', 1, 'Las disposiciones de la prenda común y de la hipoteca son aplicables a la prenda agraria o industrial en cuanto no contraríen su naturaleza y lo preceptuado en la Ley de Garantías Mobiliarias.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec738f87-cb02-4bb9-a12b-de50baa100d1', '281537fc-ba85-41c3-8f21-116f9de6443f', 2, 'DE LA SUCESION HEREDITARIA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b3b59856-2e64-425e-8d99-e8286a4c1a18', '281537fc-ba85-41c3-8f21-116f9de6443f', 3, 'DE LA SUCESION EN GENERAL');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dda4c450-af0d-4404-babb-26455b9eecbe', '281537fc-ba85-41c3-8f21-116f9de6443f', 4, '18 Reformado como aparece en el texto por el Artículo 76, del Decreto No. 51-2007 publicado en el Diario de Centro América el 01 de enero de 2008.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5f30c70-a5a3-4fb3-9327-830629fb24ad', '281537fc-ba85-41c3-8f21-116f9de6443f', 5, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ed49c05-dc87-460a-94b7-bbfe6c2a73d1', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '917', 'Sucesión hereditaria', 806, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27c2e21a-a19d-439f-9382-c2b522a425ae', '1ed49c05-dc87-460a-94b7-bbfe6c2a73d1', 1, 'La sucesión por causa de muerte se realiza por la voluntad de la persona, manifestada en testamento y, a falta de éste, por disposición de la ley. La primera se llama testamentaria y la segunda, intestada, comprendiendo en uno y otro caso, todos los bienes, derechos y obligaciones que no se extinguen por la muerte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5646d3be-d551-4aa4-9631-360d6d952c7c', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '918', 'Transmisión de la herencia', 807, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cfca8975-c014-4406-b2b1-e2bc4cfdf20e', '5646d3be-d551-4aa4-9631-360d6d952c7c', 1, 'Los derechos a la sucesión de una persona se transmiten desde el momento de su muerte; y la sucesión puede ser a título universal y a título particular.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('350a3eec-41f7-459f-b154-5ed04254fea8', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '919', 'Herencia y legado', 808, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3021eb54-5c32-4bcf-a396-23f63334b4a3', '350a3eec-41f7-459f-b154-5ed04254fea8', 1, 'La asignación a título universal se llama herencia, la asignación a título particular se llama legado. El título es universal, cuando se sucede al causante en todos sus bienes y obligaciones transmisibles, a excepción de los legados. El título es particular cuando se sucede en uno o más bienes determinados. La sucesión puede ser en parte testada y en parte intestada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3359f02-2bd6-4478-9186-779bb76922d2', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '920', 'Responsabilidad limitada del heredero', 809, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a2a4bab-c623-4235-a719-94b1a1b3ccd0', 'e3359f02-2bd6-4478-9186-779bb76922d2', 1, 'El heredero sólo responde de las deudas y cargas de la herencia hasta donde alcancen los bienes de ésta. El legatario sólo responde de las cargas que expresamente le imponga el testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('362198a6-bdd5-4d14-894b-74271b9f0226', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '921', 'Legatarios considerados como herederos', 810, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a9c73876-dbee-4027-aff5-0ccaf6a4a6c2', '362198a6-bdd5-4d14-894b-74271b9f0226', 1, 'Cuando toda la herencia se distribuya en legados, los legatarios serán considerados como herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1106a8ed-40a9-4611-8b64-7464e0bc4b9c', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '922', 'Derechos del heredero', 811, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c8d0fa6-c734-4be0-b341-cedb5c7066ef', '1106a8ed-40a9-4611-8b64-7464e0bc4b9c', 1, 'Cada heredero puede disponer del derecho que tiene en la masa hereditaria, pero no puede disponer de las cosas que forman la sucesión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1678dac8-3fb5-4511-bc40-4eaf646c2a07', 'a0000000-0000-0000-0000-000000000001', '2ae76824-4a0d-4cc5-925c-1b957ed80178', '923', 'Ley que rige la capacidad para suceder', 812, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2db122d9-fd3b-4025-b724-30198a5a7c90', '1678dac8-3fb5-4511-bc40-4eaf646c2a07', 1, 'La capacidad para suceder se rige por la ley del domicilio que tenga el heredero o legatario al tiempo de la muerte del autor de la sucesión, cuando se trate de bienes situados fuera de la República.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f883487-f1e2-4430-bab4-4c3759b97f9b', '1678dac8-3fb5-4511-bc40-4eaf646c2a07', 2, 'DE LAS INCAPACIDADES PARA SUCEDER');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4e7f317b-9707-4631-8df7-882a9fc01bb4', 'a0000000-0000-0000-0000-000000000001', 'b8b47a49-ce77-4693-a17c-9953027ef020', '924', NULL, 813, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a255cc9f-c734-4133-aa7f-8bb0978d3f9b', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 1, 'Incapacidades para heredar, por indignidad Son incapacidades para suceder como herederos o legatarios, por causa de indignidad:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fdd12ac3-9b97-4723-a67d-1e34b454c212', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 2, '1. El que haya sido condenado por haber dado, mandado o intentado dar muerte a la persona de cuya sucesión se trate, o a los padres, hijos, cónyuge, conviviente');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ea31cb0-5f2b-47e9-bdf1-c08cc208ebe3', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 3, 'de hecho, o hermanos de ella. Esta causa de indignidad subsistirá no obstante la gracia acordada al criminal o la prescripción de la pena;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('13e8c6b4-7e2a-4621-8e78-fa3a224229d9', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 4, '2. El heredero mayor de edad que, siendo sabedor de la muerte violenta del autor de la sucesión, no la denunciare a los jueces en el término de un mes, cuando sobre ella no se hubiere procedido de oficio. Si los homicidas fueren ascendientes o descendientes, cónyuge o conviviente de hecho, o hermanos del heredero, cesará en éste la obligación de denunciar;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f80b268-d4a1-460b-9b93-e96582fb7882', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 5, '3. El que voluntariamente acusó al autor de la herencia, de un delito que merezca por lo menos la pena de un año de prisión;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('225e9d90-f578-4cde-9d0d-d2e83b4c978e', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 6, '4. El condenado por adulterio con el cónyuge del causante;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c7de4e72-9518-4e28-8000-90fcf8a6324c', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 7, '5. El pariente del autor de la herencia si, habiendo estado éste demente y abandonado no cuidó de él, de recogerlo o asilarlo en establecimiento público, si hubiere podido hacerlo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7dee57db-f5fe-4fc8-bb20-6a682eca2292', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 8, '6. El padre o la madre que haya abandonado a sus hijos menores de edad o que los haya corrompido o tratado de corromper, cualquiera que sea la edad de los hijos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3613a650-81ab-4713-a1f8-ffa61581fda1', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 9, '7. El que con dolo o coacción obligare al testador a hacer testamento, a cambiarlo o revocarlo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad94a605-e19b-43b8-b9d7-ffc23c4024fa', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 10, '8. El que por iguales medios impidiere a otro hacer testamento o revocar el que tuviere hecho, o suplantare, ocultare o alterare otro testamento posterior; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b6d91855-1202-49f9-a390-a71bd10f91c1', '4e7f317b-9707-4631-8df7-882a9fc01bb4', 11, '9. El que ejerciere violencia sobre el notario o testigos, para impedir el otorgamiento del testamento, o para conseguir que se teste a su favor o a favor de otra persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('75ca407b-44a6-4e03-a49c-05e13ee778be', 'a0000000-0000-0000-0000-000000000001', 'b8b47a49-ce77-4693-a17c-9953027ef020', '925', 'Cuándo no se aplican', 814, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d7dc7a72-30c0-4ca3-bd1e-8133daaceb17', '75ca407b-44a6-4e03-a49c-05e13ee778be', 1, 'Las incapacidades enumeradas en el artículo anterior no se aplican cuando el causante así lo dispone en disposiciones testamentarias posteriores a los hechos que las hayan producido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e1883650-6844-4243-bba8-f9f63d9c40ca', 'a0000000-0000-0000-0000-000000000001', 'b8b47a49-ce77-4693-a17c-9953027ef020', '926', 'Incapacidades para suceder por testamento', 815, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c56f199a-d3c0-4746-a463-a0d4ab097229', 'e1883650-6844-4243-bba8-f9f63d9c40ca', 1, 'Son incapaces para suceder por testamento: 1. Los ministros de los cultos, a menos que sean parientes del testador;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4de4d02d-09bc-411c-a569-7d29ec060f60', 'e1883650-6844-4243-bba8-f9f63d9c40ca', 2, '2. Los médicos o cirujanos que hubieren asistido al testador en su última enfermedad, si este falleciere de ella, salvo que sean parientes del testador;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ae0857a-6ab9-41b8-ba89-360f84342816', 'e1883650-6844-4243-bba8-f9f63d9c40ca', 3, '3. El notario que autoriza el testamento y sus parientes, y los testigos instrumentales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b71b53ef-b0c8-4c70-a5f5-750ea71eec2c', 'e1883650-6844-4243-bba8-f9f63d9c40ca', 4, '4. El tutor, el protutor y los parientes de ellos si no se hubieren aprobado las cuentas de la tutela, a no ser que fueren parientes del pupilo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('621f67b1-200e-4ed6-9d81-ff1d417dfd8f', 'e1883650-6844-4243-bba8-f9f63d9c40ca', 5, '5. Las instituciones extranjeras, cualquiera que sea su finalidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1b6436d1-2fc4-4820-8f78-35917e161cc9', 'a0000000-0000-0000-0000-000000000001', 'b8b47a49-ce77-4693-a17c-9953027ef020', '927', 'La indignidad de los ascendientes no daña a sus descendientes', 816, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0621eec6-bb62-4930-9733-3ed5ec354930', '1b6436d1-2fc4-4820-8f78-35917e161cc9', 1, 'La indignidad del padre o de la madre o de los descendientes, no daña a sus hijos o descendientes, ora sucedan por derecho propio o por representación. En este caso, ni el padre ni la madre, tienen sobre la parte de la herencia que pasa a sus hijos, los derechos de administración que la ley reconoce en favor de los padres.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('53d7bc82-e058-4fbf-8985-1fdcda89c865', 'a0000000-0000-0000-0000-000000000001', 'b8b47a49-ce77-4693-a17c-9953027ef020', '928', 'Acción por indignidad', 817, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab4ec01f-5f4d-488d-89bf-b8c7b2e276f4', '53d7bc82-e058-4fbf-8985-1fdcda89c865', 1, 'Sólo puede deducirse acción, para declarar la indignidad del heredero, dentro de dos años de que el indigno esté en posesión de la herencia o legado. No se podrá intentar esta acción contra sus herederos, si no se ha iniciado durante la vida de éste. No produce efecto la acción de indignidad contra tercero de buena fe.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4918f94-f13d-4c4b-a8bd-6a9b309bc159', '53d7bc82-e058-4fbf-8985-1fdcda89c865', 2, 'REPRESENTACION HEREDITARIA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b4a20894-eb44-4259-a1dc-7b81fd3bf76e', 'a0000000-0000-0000-0000-000000000001', '11a5b7f0-9c04-4300-b484-fa255bafc7fb', '929', 'Casos en que hay representación', 818, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12baaac0-0f51-4350-8dae-4d07969403bb', 'b4a20894-eb44-4259-a1dc-7b81fd3bf76e', 1, 'Derecho de representación hereditaria, es el que tienen los descendientes de una persona para heredar en lugar de ella, si hubiere muerto antes que su causante. Igual derecho existe cuando el heredero ha renunciado la herencia o la ha perdido por indignidad. En estos casos, los hijos o descendientes tendrán derecho a heredar representando al repudiante o al excluido.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70057cde-491a-4cca-9e0b-d68369e6cf8e', 'b4a20894-eb44-4259-a1dc-7b81fd3bf76e', 2, 'La persona que por indignidad perdiere el derecho a heredar, en ningún caso tendrá la administración de los bienes de los que entren a representarlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4623e982-72ab-4be1-bf82-a58c2717a68a', 'a0000000-0000-0000-0000-000000000001', '11a5b7f0-9c04-4300-b484-fa255bafc7fb', '930', 'Representación en línea colateral', 819, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e31a9b01-5732-4e03-878b-7bb6edf2632e', '4623e982-72ab-4be1-bf82-a58c2717a68a', 1, 'En la línea colateral corresponde la representación solamente a los hijos de los hermanos, quienes heredarán por estirpes si concurren con sus tíos. Si los sobrinos concurren solos, heredarán por partes iguales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5cfeadac-e733-4353-b4d8-17a3ce3f109a', 'a0000000-0000-0000-0000-000000000001', '11a5b7f0-9c04-4300-b484-fa255bafc7fb', '931', NULL, 820, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0e86566-a49a-418f-8aa7-74b48d83730c', '5cfeadac-e733-4353-b4d8-17a3ce3f109a', 1, 'No hay representación en la línea ascendiente ni de ningún otro pariente fuera de los mencionados en los artículos anteriores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b41adcfe-ee75-4bb6-808d-ad60357147c8', 'a0000000-0000-0000-0000-000000000001', '11a5b7f0-9c04-4300-b484-fa255bafc7fb', '932', NULL, 821, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('97affb95-9d5a-4554-aea8-655c94d7dbde', 'b41adcfe-ee75-4bb6-808d-ad60357147c8', 1, 'Siempre que se herede por representación en la línea recta descendente, la división de la herencia será por estirpes de modo que el representante o representantes no hereden más de lo que heredaría su representado si viviese.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2b7373d3-0a2c-431f-8628-383b3dd89e4f', 'a0000000-0000-0000-0000-000000000001', '11a5b7f0-9c04-4300-b484-fa255bafc7fb', '933', 'Representación en herencia testamentaria', 822, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('514d1f4b-52ce-4aac-b393-fac8d5a6f913', '2b7373d3-0a2c-431f-8628-383b3dd89e4f', 1, 'Las disposiciones de este capítulo rigen para la sucesión intestada y testamentaria; pero la representación en caso de testamento, sólo se efectuará cuando los herederos y legatarios sean parientes del testador.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0d729521-f9c1-4ba1-b105-09862171097b', '2b7373d3-0a2c-431f-8628-383b3dd89e4f', 2, 'DE LA SUCESION TESTAMENTARIA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('97c7f80f-93ad-4711-a4bc-89e4f5d9cadf', '2b7373d3-0a2c-431f-8628-383b3dd89e4f', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5a63591d-5276-41e9-b9e8-f42d0b23f96e', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '934', 'Libertad de testar', 823, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0099d94d-9911-4238-ba9c-59510fb655a5', '5a63591d-5276-41e9-b9e8-f42d0b23f96e', 1, 'Toda persona capaz civilmente puede disponer de sus bienes por medio de testamento a favor de cualquiera que no tenga incapacidad o prohibición legal para heredar. El testador puede encomendar a un tercero la distribución de herencias o legados que dejare para personas u objetos determinados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('048b3048-df52-4e76-91aa-146d213e20c2', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '935', 'Concepto del testamento', 824, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b798c97f-39f4-4b4b-b544-2d8ed4e45b8c', '048b3048-df52-4e76-91aa-146d213e20c2', 1, 'El testamento es un acto puramente personal y de carácter revocable, por el cual una persona dispone del todo o de parte de sus bienes, para después de su muerte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fa39fac0-4c32-4876-98b8-cea4845821ee', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '936', 'Límites de la libertad de testar', 825, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bc08369-b12d-48c0-a207-d75b72ff4794', 'fa39fac0-4c32-4876-98b8-cea4845821ee', 1, 'La libertad de testar sólo tiene por límite el derecho que algunas personas tienen a ser alimentadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9cfb1b9d-79ff-449e-9314-f015ccd3e4ba', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '937', 'Es prohibido el contrato de sucesión recíproca', 826, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a3387dd-795f-4bec-bf8f-8d9b7fcbfac2', '9cfb1b9d-79ff-449e-9314-f015ccd3e4ba', 1, 'Queda prohibido el contrato de sucesión recíproca, entre cónyuges o cualesquiera otras personas; y es nulo el testamento que se otorgue en virtud de contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c96aae06-65d1-47f1-9051-efce7b0d67e3', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '938', NULL, 827, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8beb967b-806e-4022-8c07-85e269ae2b5b', 'c96aae06-65d1-47f1-9051-efce7b0d67e3', 1, 'Se prohíbe que dos o más personas otorguen testamento en un mismo acto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8420bea8-6165-4f9c-b7c1-31cb667699a2', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '939', NULL, 828, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1279286c-0888-490f-8c49-0558a620e317', '8420bea8-6165-4f9c-b7c1-31cb667699a2', 1, 'Las cédulas o papeles a que se refiere el testador en el testamento, no podrán considerarse como parte de éste, aunque el testador lo ordene.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54358e78-9f03-4512-add5-3d18c9aab073', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '940', 'Interpretación de las disposiciones testamentarias', 829, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9a68d49f-146d-40ab-925e-461a287f1502', '54358e78-9f03-4512-add5-3d18c9aab073', 1, 'Toda disposición testamentaria deberá entenderse en el sentido literal de sus palabras, a no ser que aparezca claramente que fue otra la voluntad del testador. La interpretación del testamento no debe hacerse tomando sólo palabras o frases aisladas, sino la totalidad de la declaración de voluntad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d5b76935-a08a-4a2a-aa30-2d3d38b623c3', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '941', NULL, 830, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46066363-336c-4936-8bd2-4e6bfad21a02', 'd5b76935-a08a-4a2a-aa30-2d3d38b623c3', 1, 'El hijo póstumo o el nacido después de hecho el testamento, si no hubieren sido desheredados de manera expresa y el testador hubiere distribuido desigualmente sus bienes entre los hijos, tendrán derecho a una parte de la herencia equivalente a la porción que les correspondería si toda la herencia se hubiera repartido en partes iguales. Si los herederos testamentarios no son hijos del testador, el hijo póstumo y el nacido después de hecho el testamento que no hubiere sido desheredado expresamente, tendrán derecho al cincuenta por ciento de la herencia. En ambos casos la porción hereditaria que corresponda al hijo póstumo o al nacido después de hecho el testamento, se deducirá a prorrata de las porciones correspondientes a los herederos testamentarios. El hijo preterido se reputa desheredado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('20264587-dcd8-4b6f-8c31-fe1d99be8c27', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '942', 'Disposición a favor de parientes en general', 831, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c67dc99d-e0ce-466b-a80a-48fe0b491b77', '20264587-dcd8-4b6f-8c31-fe1d99be8c27', 1, 'La disposición redactada a favor de parientes del testador, en forma general e indeterminada, se entiende hecha únicamente a favor de los herederos llamados a la sucesión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1a13eec-7dfa-4c13-bba8-bf9e0be08db3', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '943', NULL, 832, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f337a69-c65b-4707-bbc6-c01314658220', 'd1a13eec-7dfa-4c13-bba8-bf9e0be08db3', 1, 'Donación por causa de muerte Las donaciones por causa de muerte se rigen por las mismas disposiciones de los testamentos sobre legados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('57cbce73-925e-4583-a209-20e73b2f1044', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '944', 'Fideicomiso', 833, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('836d9a37-2287-416f-ae17-508ecaa31359', '57cbce73-925e-4583-a209-20e73b2f1044', 1, 'En el fideicomiso instituido por testamento, la institución de crédito que actúe como fiduciaria no tendrá la calidad de heredero');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a688f56-0408-49ce-af49-15545a1c4b11', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '945', 'Incapacidades para testar', 834, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('33f1a299-6008-4f9a-94e6-8d6ae8b964ea', '4a688f56-0408-49ce-af49-15545a1c4b11', 1, 'Están incapacitados para testar. 1. El que se halle bajo interdicción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c729af92-8539-474c-9439-2d38ae82b068', '4a688f56-0408-49ce-af49-15545a1c4b11', 2, '2. El sordomudo y el que hubiere perdido el uso de la palabra, cuando no puedan darse a entender por escrito; y,');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('21e1eaf0-3186-4a71-96f4-8d482f67d9cf', '4a688f56-0408-49ce-af49-15545a1c4b11', 3, '3. El que sin estar bajo interdicción no gozare de sus facultades intelectuales y volitivas, por cualquier causa, en el momento de testar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb53a408-6855-4f52-b50b-17e8ff1166d1', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '946', NULL, 835, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71971cf7-0521-4bb2-8ace-cfb2a7f05cb9', 'bb53a408-6855-4f52-b50b-17e8ff1166d1', 1, 'No es heredero ni legatario el instituido por error, cuando ese error recae sobre la persona designada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4672f820-643b-4168-b0ed-98fab8443bf1', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '947', NULL, 836, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15ef3ba7-c9c0-4800-9345-a051d1fb7e6c', '4672f820-643b-4168-b0ed-98fab8443bf1', 1, 'La omisión de la institución de heredero en un testamento no anula las disposiciones que contiene. Los bienes, derechos y acciones de que no dispuso el testador que omitió la institución de heredero, pasan a sus herederos legales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88711635-70f6-4897-9b59-58b8aa8a82b2', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '948', NULL, 837, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('121b4e55-32fd-46f3-b389-f4ac8252c669', '88711635-70f6-4897-9b59-58b8aa8a82b2', 1, 'El testador que nombre dos o más personas como sus herederos, señalará la parte de herencia que destina a cada uno de ellos. Si no lo hiciere, será igual el derecho de todos los herederos a los bienes hereditarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2cac3243-fc8a-4f8d-a5d4-fb71843e7a3d', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '949', NULL, 838, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37bbbdc1-94b4-4a9e-bdd5-7dd52fa9c805', '2cac3243-fc8a-4f8d-a5d4-fb71843e7a3d', 1, 'Cuando reunidas las porciones que asignó el testador a sus herederos, excedan del monto de la masa hereditaria, se reducirán a prorrata.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a7f29314-910c-4663-be21-54944557a1bd', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '950', NULL, 839, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1781251a-8b7a-405c-8bb5-fe1042416e2f', 'a7f29314-910c-4663-be21-54944557a1bd', 1, 'Si el testador señala todas las porciones que deja a sus herederos, y queda algo sin aplicación determinada, esta parte corresponderá a los herederos legales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('47cf9472-bf1e-4faf-8387-f4078ccd9ae6', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '951', NULL, 840, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3cb18087-900c-454a-b748-66fd0f9a6b6e', '47cf9472-bf1e-4faf-8387-f4078ccd9ae6', 1, 'Designada en el testamento parte determinada de la herencia para uno o más herederos, sin señalarse la de sus coherederos, éstos se distribuirán con igualdad lo que sobre de la herencia, deducido lo que fue destinado especialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('76c3e488-7068-40a1-80d4-044a4212a9d5', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '952', NULL, 841, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('483a08bb-6646-48c6-b042-e0df83b24e8e', '76c3e488-7068-40a1-80d4-044a4212a9d5', 1, 'Salvo lo dispuesto por el testador, los bienes adjudicados por testamento, ya sea por herencia o por legados que vacaren por haber fallecido los adjudicatarios antes que el testador, pasarán por derecho de representación a quienes determina la ley, si fueren parientes de él.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('87e5ff37-afeb-4e7c-82ea-62dcd4528ac6', 'a0000000-0000-0000-0000-000000000001', '8e0ed4f7-ffc8-40b1-a4d6-c27e539cbef8', '953', NULL, 842, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f770fad-9351-4faa-b5a6-ad939a3ce110', '87e5ff37-afeb-4e7c-82ea-62dcd4528ac6', 1, 'Si la vacancia se produjera por la no aceptación de la herencia y no hubiere derecho de representación, los bienes pasarán al heredero universal testamentario; en su defecto, se adjudicarán a las personas a quienes corresponda la herencia intestada, conforme a la ley, siempre que éstas no hubieren sido desheredadas expresamente por el testador.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25cf1527-9979-43b6-96a2-195220d74db9', '87e5ff37-afeb-4e7c-82ea-62dcd4528ac6', 2, 'DE LA FORMA DE LOS TESTAMENTOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2f0fd32f-8d37-43cd-bbfc-f03546adf657', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '954', 'Formas testamentarias', 843, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dab80bf6-e5bd-4569-ae50-85c90968fa30', '2f0fd32f-8d37-43cd-bbfc-f03546adf657', 1, 'Los testamentos en cuanto a su forma, son comunes y especiales. Son comunes, el abierto y el cerrado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3564db36-d129-47ae-a391-afad63f327f0', '2f0fd32f-8d37-43cd-bbfc-f03546adf657', 2, 'Son especiales los que se otorguen en los casos y condiciones que se expresan en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('70794c42-7f6f-498d-bcd7-f741a86d13f1', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '955', 'Testamento en escritura pública', 844, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a481df0f-c860-40bf-b282-918c8aeef6d0', '70794c42-7f6f-498d-bcd7-f741a86d13f1', 1, 'El testamento común abierto deberá otorgarse en escritura pública, como requisito esencial para su validez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aa1bc130-26c3-4795-9ffe-772b3aa98fca', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '956', NULL, 845, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f2dc8194-8380-4b30-b6a9-85a6d4ff59b0', 'aa1bc130-26c3-4795-9ffe-772b3aa98fca', 1, 'El testador puede entregar al notario la minuta de sus disposiciones testamentarias o manifestar de palabra su última voluntad. El notario redactará el testamento, y procederá a su lectura en presencia de los testigos, en un solo acto y sin interrupción, llenando los demás requisitos que para el efecto exige el Código de Notariado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ecbf594f-b5a4-4ca2-a48b-4602f11e9a51', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '957', 'Testamento del ciego', 846, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ede3714-f538-4d61-be18-1dcc11ee087d', 'ecbf594f-b5a4-4ca2-a48b-4602f11e9a51', 1, 'En el testamento del ciego debe intervenir un testigo más de los que se requieren para el testamento abierto; será leído en alta voz');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ba5de1b-40c6-4d3e-880e-b602eac692af', 'ecbf594f-b5a4-4ca2-a48b-4602f11e9a51', 2, 'dos veces; la primera por el notario autorizante, y la segunda, por uno de los testigos elegido al efecto por el testador. Se hará mención especial de esta circunstancia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0b598677-fc5d-45f4-8f70-6c58ecdf4ee7', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '958', 'Testamento del sordo', 847, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bbf47256-f54a-4779-98f7-8ccb75af03ab', '0b598677-fc5d-45f4-8f70-6c58ecdf4ee7', 1, 'Si un sordo quiere hacer testamento abierto, deberá leer él mismo en voz inteligible, el instrumento, a presencia del notario y testigos, lo que se hará constar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '959', 'Formalidades del testamento cerrado', 848, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('187436a2-ed55-40aa-9917-4b40a49d6839', '3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 1, 'En el testamento cerrado se observarán las solemnidades pertinentes prescritas para el testamento abierto y, además, las siguientes: 1. El papel que contenga el testamento se pondrá dentro de una cubierta cerrada, de suerte que no pueda extraerse aquél sin romper esta;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('adc09e96-a459-467f-9bd9-c50a9a4002ab', '3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 2, '2. En presencia del notario y los testigos, y los intérpretes en su caso, manifestará el testador que el pliego que presenta contiene su testamento y si está escrito y firmado por él o escrito por mano ajena y si, por no poder firmar, lo ha hecho a su ruego otra persona, cuyo nombre expresará;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0dc1346e-079a-48fc-a134-f08b99dcf971', '3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 3, '3. Sobre la cubierta del testamento extenderá el notario el acta de su otorgamiento, dará fe de haberse observado las formalidades legales; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99dc9ef3-b04f-4b76-a385-bb5aa058e36e', '3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 4, '4. Extendida y leída el acta, la firmarán el testador, los testigos, los intérpretes si los hubiere y la autorizará el notario con su sello y firma.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fddeacf7-16df-4d48-8baa-9888d7feedb4', '3b523fbc-07f0-4bb3-a57c-dc10ff684cfe', 5, 'Si el testador no puede firmar, pondrá su impresión digital, y un testigo más, designado por él mismo, firmará a su ruego.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aeade7cd-34cf-4fa7-b103-75008795183a', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '960', NULL, 849, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6507f7c6-d274-4b8a-8529-ea437b7fc187', 'aeade7cd-34cf-4fa7-b103-75008795183a', 1, 'No pueden hacer testamento cerrado: El ciego; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('676c1f3b-c5a3-44b6-921e-ef1fb1c4a506', 'aeade7cd-34cf-4fa7-b103-75008795183a', 2, 'El que no sepa leer y escribir.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9963ff9b-f9fb-4ec3-a1d2-0b7183d6104b', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '961', NULL, 850, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6abb622-888d-41c3-9d9e-9ab3daa89571', '9963ff9b-f9fb-4ec3-a1d2-0b7183d6104b', 1, 'Los que no pueden hablar, pero sí escribir, podrán otorgar testamento cerrado, pero tanto el testamento como el acta de la plica deberán ser escritos y firmados de puño y letra del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('11ee9a6c-d60f-48b2-8867-6936e4ac69d7', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '962', NULL, 851, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('407880bc-2097-4694-a2fe-bf5ccdfa1778', '11ee9a6c-d60f-48b2-8867-6936e4ac69d7', 1, 'Autorizado el testamento cerrado, el notario lo entregará al testador, después de transcribir en el protocolo, con el número y en el lugar que le corresponde, el acta de otorgamiento. Dicho instrumento será firmado también por todos los que en el acto intervinieren.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('085ed433-9a6a-4760-9ff3-d46ab8f37b1a', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '963', NULL, 852, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2dd0ce5-deb6-43a4-af2f-762ce351cd71', '085ed433-9a6a-4760-9ff3-d46ab8f37b1a', 1, 'El testador podrá conservar en su poder el testamento cerrado, encomendar su guarda a persona de su confianza, o depositarlo en poder del notario. Cualquiera de estas tres circunstancias se hará constar en el acta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fd6b95c8-9063-4d5d-9529-981a4fe52187', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '964', NULL, 853, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5463b0e6-85d5-4c17-949b-5a0006087fcd', 'fd6b95c8-9063-4d5d-9529-981a4fe52187', 1, 'El notario o la persona que tenga en su poder el testamento cerrado, deberá presentarlo al juez competente luego que sepa el fallecimiento del testador y, a más tardar, dentro de diez días, bajo pena de responder de los daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('239ec19a-5723-4bdc-b259-1eaeadade1ba', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '965', 'Testamento militar', 854, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb8c7b7d-58f8-47e7-8c90-ae5a49d82828', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 1, 'Los militares en campaña, rehenes, prisioneros y demás individuos empleados en el Ejército o que sigan a éste, podrán otorgar testamento abierto ante el oficial bajo cuyo mando se encuentren. Es aplicable esta disposición a los individuos de un ejército que se halle en país extranjero.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1cea26eb-491d-4552-b778-681e249461c1', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 2, 'Si el testador estuviere enfermo o herido, podrá otorgarse ante el facultativo que lo asista, o ante un oficial de cualquier categoría.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f15e059-eaad-47d9-bc4f-07ec279a9878', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 3, 'Si estuviere en destacamento, ante el que manda éste, aunque sea subalterno.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('881ce2e3-17b1-46ca-952b-7c5b8ba495d7', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 4, 'En todos los casos de este artículo, será necesaria la presencia de dos testigos que sepan leer y escribir; y si el testador no pudiere firmar, lo hará por él cualquiera de los dos testigos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e687148-2448-45df-b5a8-40cc80d10c2a', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 5, 'ARTICULO 966. El testamento otorgado con arreglo al artículo anterior, deberá ser remitido con la brevedad posible al Cuartel General, y por éste al Ministerio de la Defensa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5acfe72d-711b-41e4-ab53-96d3000882d6', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 6, 'Si el testador hubiere fallecido, el Ministro remitirá el testamento al juez del último domicilio del difunto y, no siéndole conocido, a cualquier Juzgado de Primera Instancia del Ramo Civil del departamento de Guatemala, para que, de oficio, cite a los herederos y demás interesados en la sucesión.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce680016-588a-4f52-992f-1657a99f850c', '239ec19a-5723-4bdc-b259-1eaeadade1ba', 7, 'Estos deberán solicitar que el testamento se protocolice en la forma prevenida en el Código Procesal Civil y Mercantil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5ffa5efc-cc42-4408-b3a1-2bdd54ce5c37', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '967', 'Testamento marítimo', 855, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('824bc9d7-6c57-415a-9cc9-0ea05287762c', '5ffa5efc-cc42-4408-b3a1-2bdd54ce5c37', 1, 'Los testamentos abiertos o cerrados de los que vayan a bordo durante un viaje marítimo, se otorgarán en la forma siguiente: Si el buque es de guerra, ante el contador o ante el que ejerza sus funciones, en presencia de dos testigos que sepan leer y escribir, y que vean y entiendan al testador. El comandante del buque o el que haga sus veces, pondrá además, su "visto bueno".');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('69b1f8a0-8507-46c6-8b4e-41e01ba5e5f9', '5ffa5efc-cc42-4408-b3a1-2bdd54ce5c37', 2, 'En los buques mercantes autorizará el testamento el capitán o el que haga sus veces, con asistencia de dos testigos como se expresa anteriormente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a8ccb309-fc1b-482b-8845-0dbfc2cfde3e', '5ffa5efc-cc42-4408-b3a1-2bdd54ce5c37', 3, 'En uno y otro caso, los testigos se elegirán entre los pasajeros, si los hubiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('514e6729-53a5-4d69-bed8-5681b7fc609d', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '968', NULL, 856, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15891c93-72a4-454c-aa4e-35c9ac2bf4c0', '514e6729-53a5-4d69-bed8-5681b7fc609d', 1, 'El testamento del contador del buque de guerra y del capitán del mercante, serán autorizados por quien deba sustituirlos en el cargo, observándose en lo demás lo dispuesto en el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38da346f-766b-45d1-b9b2-d344f97d347d', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '969', NULL, 857, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f0c644a-9b85-4d00-9bec-d2c59df40dd4', '38da346f-766b-45d1-b9b2-d344f97d347d', 1, 'Los testamentos abiertos, hechos en alta mar, serán custodiados por el comandante o por el capitán, y se hará mención de ellos en el diario de navegación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bd9fed14-c640-419c-8df1-4d0e61b20597', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '970', NULL, 858, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1b061e5-43fc-4711-b4bf-6fc803750714', 'bd9fed14-c640-419c-8df1-4d0e61b20597', 1, 'En el testamento hecho en el mar, es nula toda disposición a favor de cualquiera persona que ejerza autoridad a bordo, a no ser que sea pariente del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('89e7253d-5272-4f96-b1cb-c0c7043db75b', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '971', 'Testamento en lugar incomunicado', 859, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('584d355a-fdf1-421e-8be2-916cdaad1feb', '89e7253d-5272-4f96-b1cb-c0c7043db75b', 1, 'Los que se hallen en lugar incomunicado por motivo de epidemia, podrán testar ante el juez local y en presencia de dos testigos que sepan leer y escribir.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e40e4d53-4052-4dd6-985d-0680e188a7e1', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '972', 'Testamento de preso', 860, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9151ea23-83f5-4188-8704-cd5d07d44653', 'e40e4d53-4052-4dd6-985d-0680e188a7e1', 1, 'Si el testador se halla preso podrá en caso de necesidad, otorgar testamento ante el jefe de la prisión pudiendo ser testigos, a falta de otros, los detenidos o presos, con tal que no sean inhábiles por otra causa y que sepan leer y escribir. En este testamento es nula toda disposición hecha a favor de los que tienen autoridad en la prisión, a menos que sean parientes del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2c978cef-a147-42d2-9e70-86a9154259fe', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '973', NULL, 861, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('442f3f51-7514-4ec0-b904-81a81aa9da55', '2c978cef-a147-42d2-9e70-86a9154259fe', 1, 'Los testamentos especiales a que se refieren los artículos anteriores, sólo son válidos si el testador muere durante la situación a que dichos artículos se refieren o dentro de los noventa días posteriores a la cesación de ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cc2cb3fe-ffc3-483e-a66f-58286658b800', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '974', 'Testamento en el extranjero', 862, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48ad5d5d-9c50-42c3-8c4f-e216a21d46b6', 'cc2cb3fe-ffc3-483e-a66f-58286658b800', 1, 'Los guatemaltecos podrán testar fuera del territorio nacional, sujetándose a las normas establecidas por las leyes del país en que se hallen. También podrán testar en alta mar, durante su navegación en un buque extranjero, con sujeción a las leyes de la nación a que el buque pertenezca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8c1bdd11-0879-4fe6-8dce-8b087b909ed0', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '975', NULL, 863, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77400b3c-6f00-4c52-ada9-16d06b4eaf12', '8c1bdd11-0879-4fe6-8dce-8b087b909ed0', 1, 'No será válido en Guatemala el testamento mancomunado que los guatemaltecos otorguen en país extranjero, aunque lo autoricen las leyes de la nación donde se hubiere otorgado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6addde7-6c37-4416-8021-41bfb8dc6146', 'a0000000-0000-0000-0000-000000000001', 'd6e51a5e-c6a2-495a-a472-61046dc6770a', '976', NULL, 864, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aefcb3c4-c07b-48a0-ac82-5397c443177e', 'b6addde7-6c37-4416-8021-41bfb8dc6146', 1, 'También podrán los guatemaltecos que se encuentran en país extranjero otorgar testamento, abierto o cerrado, ante el agente diplomático o consular de esta República, residente en el lugar del otorgamiento, si fuere notario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('010289d7-31d2-46c0-b208-b5814a7d18cf', 'b6addde7-6c37-4416-8021-41bfb8dc6146', 2, 'REVOCACION, NULIDAD, FALSEDAD Y CADUCIDAD DE LAS DISPOSICIONES TESTAMENTARIAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('99a28bea-9a84-4e76-b7b9-6d567a58ae63', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '977', NULL, 865, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3b0821e0-e15d-4789-99b8-136071832cde', '99a28bea-9a84-4e76-b7b9-6d567a58ae63', 1, 'Es nulo el testamento que se otorga sin la observancia de las solemnidades esenciales que la ley establece. El testamento cerrado será nulo, además, cuando apareciere rota la plica que lo contiene.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e6f31401-b227-4602-b478-f053a4605f8b', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '978', NULL, 866, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('53900565-38d1-49df-a539-3ddb0739e973', 'e6f31401-b227-4602-b478-f053a4605f8b', 1, 'Es anulable el testamento otorgado con violencia, dolo o fraude. El testador no puede prohibir que se impugne el testamento en los casos en que haya nulidad declarada por la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('caad978f-677a-4589-95ae-72121e58821d', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '979', NULL, 867, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb55e8c1-d4ff-4863-a2b7-d2fddf21807a', 'caad978f-677a-4589-95ae-72121e58821d', 1, 'El que de algún modo ejerza coacción sobre el testador para que haga, altere o revoque su testamento o cualquiera disposición testamentaria, pierde todos los derechos que por el testamento o por la ley le correspondan en los bienes de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7d2312e-e7a8-4f3a-a10a-6627c5648a6b', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '980', NULL, 868, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82a9d8e0-a492-475a-8273-203781e5b9fa', 'b7d2312e-e7a8-4f3a-a10a-6627c5648a6b', 1, 'Incurre también en la pena del artículo anterior quien impida que una persona haga, revoque o varíe su testamento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9549a219-86be-4d60-a8d1-beaacf8d30e0', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '981', NULL, 869, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('169d0c25-84eb-4cdf-853a-3e048eafe4c4', '9549a219-86be-4d60-a8d1-beaacf8d30e0', 1, 'Si el testamento posterior fuere declarado nulo o falso, subsistirá él anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c21b39d0-65f9-4320-8461-f07093318b58', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '982', NULL, 870, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b3359b02-27f6-4366-854a-08a6ba267a4d', 'c21b39d0-65f9-4320-8461-f07093318b58', 1, 'El testamento no puede ser revocado en todo ni en parte sino con las solemnidades necesarias para testar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('74a2a7c9-362c-4098-b40c-5a2bf27936ad', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '983', NULL, 871, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70dc29cc-9526-4794-b895-c6a3dd4d50f6', '74a2a7c9-362c-4098-b40c-5a2bf27936ad', 1, 'Todo testamento queda revocado por el otorgamiento de otro posterior. Sin embargo, el testador puede de manera expresa dejar vigente todo o parte del testamento anterior. Las donaciones por causa de muerte hechas con anterioridad al testamento caducarán salvo disposición en contrario del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1df7f932-dfc7-4a8c-827a-18ab102a7da0', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '984', NULL, 872, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9fb3d182-17c4-4665-b3fc-f44afe9adda1', '1df7f932-dfc7-4a8c-827a-18ab102a7da0', 1, 'Cuando se ha otorgado un testamento dando expresamente por causa la muerte del heredero instituido en el anterior, valdrá éste y se tendrá por no otorgado aquél si resulta falsa la noticia de la muerte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3444e4b7-3b8b-4da2-b6b8-6da1312e38b0', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '985', NULL, 873, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('875dc3c5-2e55-4a3b-86e2-2fac768a228d', '3444e4b7-3b8b-4da2-b6b8-6da1312e38b0', 1, 'Por la enajenación que haga el testador del todo o parte de una cosa dejada en testamento, se entiende revocada su disposición relativa a la cosa o parte enajenada, a no ser que vuelva a su dominio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bab0c304-6244-4b23-972c-5f80982c6a30', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '986', NULL, 874, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e91e12b-1573-4a01-aa50-143b56af0873', 'bab0c304-6244-4b23-972c-5f80982c6a30', 1, 'La donación o legado de un crédito hecho en testamento, queda revocado en todo o en parte, si el testador recibe en pago el todo o parte de la cantidad que se le debía o si por cualquier razón ha cancelado el crédito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('32cc86a9-bd91-4318-83ac-b37b155e40f3', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '987', NULL, 875, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('80ece639-9a81-4d69-b71f-f4d960b385f5', '32cc86a9-bd91-4318-83ac-b37b155e40f3', 1, 'No produce efecto el testamento en cuanto a la institución del heredero, si el nombrado tuviere incapacidad legal para heredar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5395997c-6d2c-4394-91e8-c7d4b11062b4', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '988', NULL, 876, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db3e3c15-671e-4d59-aec5-f1ab0f1fb14e', '5395997c-6d2c-4394-91e8-c7d4b11062b4', 1, 'Caduca la disposición testamentaria en que se deja algo bajo condición, si el heredero o el legatario a que se refiere, muere antes de que se verifique.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab098c51-79bc-4edc-844a-2ef374c70c24', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '989', NULL, 877, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9eb15f34-8bf6-47b6-a827-f377910d2723', 'ab098c51-79bc-4edc-844a-2ef374c70c24', 1, 'No caduca la disposición testamentaria si el testador ha nombrado heredero sustituto para el caso en que el heredero instituido muera antes que él, o no quiera, o no pueda aceptar la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('21b87e93-3ce9-4a0e-8634-1427568bda77', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '990', NULL, 878, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9229d1e6-ba46-465b-adbf-dd329ab88d2e', '21b87e93-3ce9-4a0e-8634-1427568bda77', 1, 'No caduca la herencia ni el legado que se deja desde día cierto o desde tiempo determinado aun cuando el heredero o el legatario mueran antes de haber llegado el día o vencido el tiempo que fijó el testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('259a07de-4fa3-4b6b-bc9b-8b1c5fbad603', 'a0000000-0000-0000-0000-000000000001', 'cfc99d9b-ff4b-4550-9272-a11d549c5863', '991', NULL, 879, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1c2d431-395f-4b96-ae2e-4e13c161e3dc', '259a07de-4fa3-4b6b-bc9b-8b1c5fbad603', 1, 'La disposición testamentaria de una cosa específica, en favor de alguno, no produce efecto si se destruye la cosa sin culpa de la persona obligada a entregarla.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f462b177-0972-4cc9-859f-437744b6f588', '259a07de-4fa3-4b6b-bc9b-8b1c5fbad603', 2, 'RTICULO 992. En todos los casos en que caduque o pierda su efecto la institución de heredero, pasará la herencia a los herederos legales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1db2faa-f38a-4230-8fe5-1835d0e6c342', '259a07de-4fa3-4b6b-bc9b-8b1c5fbad603', 3, 'HERENCIA CONDICIONAL Y A TÉRMINO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4daf16a2-419f-40a0-ac0d-db047b831577', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '993', 'Herencia condicional', 880, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37311bf7-b9e2-4b15-af40-a28cfa06add7', '4daf16a2-419f-40a0-ac0d-db047b831577', 1, 'Las disposiciones testamentarias podrán otorgarse bajo condición, haciendo depender su eficacia de la realización de un acontecimiento futuro e incierto. Las condiciones impuestas a los herederos y legatarios se regirán por lo establecido para las obligaciones condicionales en lo que no esté prevenido en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ac990ad9-42a8-4447-8589-09e0f2e1179b', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '994', NULL, 881, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94bcf16f-06a0-4cf3-b123-21e4cbcf34f1', 'ac990ad9-42a8-4447-8589-09e0f2e1179b', 1, 'La condición de no enajenar o no gravar los bienes, solo será válida hasta la mayoría de edad y cinco años más de los herederos o legatarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65111e15-892c-4ba7-9505-2f6d4527826c', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '995', NULL, 882, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2daaf42f-c8e0-46f5-95c8-1e644c662c15', '65111e15-892c-4ba7-9505-2f6d4527826c', 1, 'Se tendrá por no puesta la condición de no casarse; pero será válida la que se dirija a impedir el matrimonio con persona determinada. Podrá, sin embargo, legarse al causahabiente, el usufructo, uso o habitación, o una pensión personal, por el tiempo que permanezca soltero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90336ae6-6609-499e-9b2f-efed41780890', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '996', NULL, 883, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f625e0bd-d10d-4b06-835d-4d1418eed866', '90336ae6-6609-499e-9b2f-efed41780890', 1, 'Si el heredero o legatario fueren instituidos bajo condición suspensiva, se pondrán en administración los bienes que les correspondan, hasta que la condición se realice o haya certeza de que no podrá cumplirse.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('012e00b4-edb9-4819-968a-2c21953c3349', '90336ae6-6609-499e-9b2f-efed41780890', 2, 'Se tendrá por cumplida la condición cuando sin culpa del heredero o legatario, impida el cumplimiento de ella el interesado en que no se realice.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c626899-b334-4119-b9d1-19c56dc059ee', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '997', NULL, 884, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43050e85-10b6-4f21-af4d-dddfd84e4a93', '7c626899-b334-4119-b9d1-19c56dc059ee', 1, 'La administración de que habla el artículo anterior, se confiará al heredero o herederos sin condición; pero si no hubiere coherederos, podrá confiarse la administración al heredero condicional, siempre que garantice suficientemente su manejo a juicio del juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46d12f29-1f59-4c42-a9ed-c9a12c27c30f', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '998', 'Herencia a término', 885, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('affe0806-8ddd-4d52-a4ab-c9c97b22cc54', '46d12f29-1f59-4c42-a9ed-c9a12c27c30f', 1, 'Será válida la designación de día o tiempo en que haya de comenzar o cesar el efecto de la institución de heredero o legatario. En ambos casos, hasta que llegue el término señalado, o cuando éste concluya, se entenderá llamado el sucesor legítimo. Más, en el primer caso, no entrará éste en posesión de los bienes sino después de prestar caución suficiente, con intervención del instituido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4bbdcacf-700a-4128-93f8-28a8b8e17428', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '999', NULL, 886, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6920c501-f0a5-432c-a9e3-b06097fcf933', '4bbdcacf-700a-4128-93f8-28a8b8e17428', 1, 'En la herencia o legado conferidos desde día determinado, los frutos que produzcan los bienes hasta que llegue ese día, corresponderán a los herederos legales, si el testador no hubiere dispuesto de ellos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2675636b-96c7-4399-beda-8e4e480179a2', '4bbdcacf-700a-4128-93f8-28a8b8e17428', 2, 'RTICULO 1000. Si el testador instituye heredero o legatario hasta cierto día o tiempo determinado, no podrá el heredero retener los bienes hereditarios, ni hará suyos los frutos, desde que pasen el día o tiempo señalados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8dc01199-4b03-49d2-aec6-a34bb8704d8f', 'a0000000-0000-0000-0000-000000000001', '2637291a-51eb-429b-966f-fb182c3f2b48', '1001', NULL, 887, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('197b4637-1367-41b3-9ceb-b43e14bd600b', '8dc01199-4b03-49d2-aec6-a34bb8704d8f', 1, 'Los bienes y frutos de que habla el artículo anterior, pertenecerán en adelante al heredero instituido, o a los herederos legales del testador.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afdf7413-62b5-4126-8135-f48dcfe50e19', '8dc01199-4b03-49d2-aec6-a34bb8704d8f', 2, 'LEGADOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2eca739a-b1a8-4a76-ac78-065012a4bc36', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1002', NULL, 888, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed0c720b-ae76-499a-8776-57d59aafa9e4', '2eca739a-b1a8-4a76-ac78-065012a4bc36', 1, 'El testador puede disponer de una cosa, o de una cantidad, o del todo o de una parte de sus bienes, a título de legado, en favor de una o más personas individuales o jurídicas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1fae93d9-0207-4382-8789-bebe6189a8b2', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1003', NULL, 889, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3abf263a-f2d4-4687-a698-24eb033b38c9', '1fae93d9-0207-4382-8789-bebe6189a8b2', 1, 'Legatario es la persona a quien se da algo por testamento, conforme el artículo anterior, aun sin instituirlo heredero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('be203769-b4a5-4360-8be7-8b5efd1adac9', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1004', NULL, 890, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d7a5cced-77c7-4f6e-b71b-6c80c326c7f0', 'be203769-b4a5-4360-8be7-8b5efd1adac9', 1, 'Si toda la herencia se distribuye en legados, se prorratearán las deudas, gravámenes y porciones alimenticias entre los legatarios, en proporción al valor de sus respectivos legados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a78a852c-9afa-424b-b13e-211ad229c853', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1005', NULL, 891, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1bec83f-08c5-4593-8bc3-dcb0a0a70ed6', 'a78a852c-9afa-424b-b13e-211ad229c853', 1, 'No tiene efecto el legado de una cosa en especie, si no se halla en el dominio del testador al tiempo de su muerte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e494a5db-62c9-4423-87b6-2f15561fd9ea', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1006', NULL, 892, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57091d39-f419-42a1-a742-55b3035c661d', 'e494a5db-62c9-4423-87b6-2f15561fd9ea', 1, 'En el legado de una cosa indeterminada, comprendida en un género o en una especie, la elección corresponde al obligado a pagarlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60947a15-5305-4ae2-8ec5-1976b71e516f', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1007', NULL, 893, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc41756b-745d-4ab3-8764-72830303a64d', '60947a15-5305-4ae2-8ec5-1976b71e516f', 1, 'El legado de un crédito contra tercero o el de perdón o liberación de una deuda del legatario, sólo surtirá efecto en la parte del crédito o de la deuda subsistente al tiempo de morir el testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d7c178fc-1690-47b4-9f5f-ff0b093983fe', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1008', NULL, 894, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a8cd319-88af-4d6f-aedd-9fb6256792b1', 'd7c178fc-1690-47b4-9f5f-ff0b093983fe', 1, 'En los legados remuneratorios, se observarán las reglas sobre donaciones de este género.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d97d368a-ab08-452b-aace-d994971ea582', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1009', NULL, 895, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b8cc72b-7160-42d6-85a2-3314b9753298', 'd97d368a-ab08-452b-aace-d994971ea582', 1, 'El legado hecho a un acreedor tendrá efecto sin perjuicio del pago de su crédito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cffd6434-3607-46c3-a5fa-fbaf045ee40d', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1010', NULL, 896, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3b5d4f1a-70ea-4b6b-93aa-7d325b3201d7', 'cffd6434-3607-46c3-a5fa-fbaf045ee40d', 1, 'Se acepta el legado expresamente, cuando se pide; y tácitamente, cuando se recibe la cosa legada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('adf33690-553b-4fba-bddd-d5022e361278', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1011', NULL, 897, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f976a4f1-e3d6-4064-b07a-7990359c693f', 'adf33690-553b-4fba-bddd-d5022e361278', 1, 'Si el legado consiste en una pensión o renta vitalicia, ésta comienza a correr desde el día de la muerte del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cea3a2fa-43a1-48e8-aec0-66df43533d36', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1012', NULL, 898, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce5c9fdf-769e-4c2c-9af5-f33dad1a149e', 'cea3a2fa-43a1-48e8-aec0-66df43533d36', 1, 'Si entre varios herederos ninguno ha sido encargado particularmente de pagar el legado, cada uno debe hacerlo en proporción a la parte que le haya correspondido en la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('762276b9-6d06-4524-9366-45d4cd5ce2ab', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1013', NULL, 899, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b3e485b-3782-422c-88be-f2611ff74d9f', '762276b9-6d06-4524-9366-45d4cd5ce2ab', 1, 'Si la obligación de pagar el legado se ha impuesto a uno de los herederos, él solo debe hacerlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a5d67786-da25-45e5-80f8-d0ebe343ea76', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1014', NULL, 900, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be7a5137-38ac-48b1-a462-946ce29173fa', 'a5d67786-da25-45e5-80f8-d0ebe343ea76', 1, 'La cosa legada se entregará con sus accesorios y en el estado en que se encuentre el día de la muerte del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('679ba7c5-00c9-4e30-b30a-63fcdee86047', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1015', NULL, 901, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7d94965-1db3-4785-861e-f1a033a46279', '679ba7c5-00c9-4e30-b30a-63fcdee86047', 1, 'Los gastos necesarios para la entrega del legado, serán a cargo de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7adc7eb5-98c0-4cd7-9986-8d6d19fdcfd3', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1016', NULL, 902, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('411b2d4e-1fd5-43bf-99fb-584cbb18fc2b', '7adc7eb5-98c0-4cd7-9986-8d6d19fdcfd3', 1, 'Si la cosa legada estuviere gravada con una pensión, servidumbre u otra carga inherente al fundo, tal gravamen recaerá sobre el legatario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cbf10abc-6962-44d6-9903-f8c46949e662', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1017', NULL, 903, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('282424f4-c8a0-433e-9c42-a52f1d668805', 'cbf10abc-6962-44d6-9903-f8c46949e662', 1, 'Si la cosa legada estuviere empeñada por una obligación de la herencia o de un tercero, el heredero estará obligado al pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cccdb4a9-9cda-494b-8e3f-04675ef162a4', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1018', NULL, 904, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4dbc971f-f766-4f78-9dfa-9666985a331a', 'cccdb4a9-9cda-494b-8e3f-04675ef162a4', 1, 'Desde que pase un año del fallecimiento del testador, se abonarán intereses al legatario, si el legado consiste en dinero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('55329ef3-580f-4eb8-bf47-9798030f2071', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1019', NULL, 905, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('59e38d72-8144-4845-8b30-1acf39e4d9e2', '55329ef3-580f-4eb8-bf47-9798030f2071', 1, 'Al entrar el heredero en posesión de la herencia, tendrán los legatarios el derecho de pedir al albacea o al heredero, según las circunstancias, la entrega del legado y sus frutos e intereses.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3de58b01-d27f-45f1-a5cb-1b11f56be588', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1020', NULL, 906, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36de136f-ea4a-48e5-b1e6-d6744b7e77a8', '3de58b01-d27f-45f1-a5cb-1b11f56be588', 1, 'En todo caso se cumplirá la disposición del testador en cuanto al modo, orden y tiempo en que deban entregarse o pagarse los legados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f4da2a6d-a208-4a57-b728-cb0428534948', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1021', NULL, 907, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03fcd099-4be8-405f-b8ae-4219d5d16e76', 'f4da2a6d-a208-4a57-b728-cb0428534948', 1, 'El legatario que muera antes que el testador, no adquiere derecho alguno al legado, ni lo transmite a sus herederos, a no ser que éstos hubiesen sido llamados igualmente por el testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c435e189-dc9d-4b0c-a91c-8aa726795661', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1022', NULL, 908, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e770c20-5059-4a22-9d54-7e2879978df1', 'c435e189-dc9d-4b0c-a91c-8aa726795661', 1, 'No hay derecho de acrecer entre los legatarios, si el testador no lo estableció clara y expresamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0cc429f4-ccc3-47d2-b1f6-76a95e4e7a8d', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1023', NULL, 909, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46c66135-6356-48ab-be5d-1ffddc379418', '0cc429f4-ccc3-47d2-b1f6-76a95e4e7a8d', 1, 'Distribuida en legados toda la herencia, el heredero instituido, si lo hubiere, tendrá derecho a la cuarta parte de la herencia que se deducirá a prorrata de los legados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('709c771a-e464-490a-a5c6-86e0e0ab8d5d', '0cc429f4-ccc3-47d2-b1f6-76a95e4e7a8d', 2, 'RTICULO 1024. Si en el testamento se hubiere legado al heredero alguna cosa, y el valor de ésta, sumado al de la herencia, fuere menos que la cuarta parte de ella, tendrá derecho a completarla, deduciendo lo necesario a prorrata de los demás legados. Lo dispuesto en este precepto y en los artículos 1001, 1004, 1006, 1015, 1017, 1018 y 1023, se observará si el testador no hubiere dispuesto lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab128b4c-6d9f-4cd5-8ad5-ba7235c3892f', 'a0000000-0000-0000-0000-000000000001', '3edfa41d-2ea1-44ff-8785-1423321405de', '1025', NULL, 910, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9fbc667e-d198-4838-acd7-b10ba57d3df2', 'ab128b4c-6d9f-4cd5-8ad5-ba7235c3892f', 1, 'Las reglas establecidas con respecto a la herencia para dos o más herederos, regirán en los legados que se dejen a dos o más personas. Asimismo, regirá para los legados lo dispuesto en el capítulo III de este título.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bbc1492-601b-48be-9eb6-7250d5fff565', 'ab128b4c-6d9f-4cd5-8ad5-ba7235c3892f', 2, 'DE LA ACEPTACION Y DE LA RENUNCIA DE LA HERENCIA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61d7f4dc-594e-44b0-8285-4c6816dfb979', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1026', 'La aceptación de la herencia puede ser expresa o tácita', 911, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('682628dc-a89b-4935-a9f1-e62ba34e9c72', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1027', NULL, 912, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d075b695-d652-448a-a02a-3c48d8518559', '682628dc-a89b-4935-a9f1-e62ba34e9c72', 1, 'El heredero acepta expresamente la herencia, manifestándolo al juez, o pidiéndole posesión de los bienes, o usando del título o de la calidad del heredero en instrumento público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6df80162-0fda-4d90-b090-5ec9139c09f6', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1028', NULL, 913, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab3d5840-b41d-46c2-939f-829c4dacc43b', '6df80162-0fda-4d90-b090-5ec9139c09f6', 1, 'Acepta el heredero tácitamente, entrando en posesión de la herencia o practicando otros actos para los cuales no tendría derecho sin ser heredero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50e18f18-711f-401a-9c91-b6c678994458', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1029', NULL, 914, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0775b90c-6af6-47bd-b4d9-00f452985da0', '50e18f18-711f-401a-9c91-b6c678994458', 1, 'La herencia instituida a favor de personas jurídicas, menores e incapacitados, será aceptada por sus representantes legales. La renuncia de la herencia dejada a menores e incapacitados deberá hacerse con aprobación judicial e intervención del Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f4d6172b-67f7-4d54-bbf1-d647430bf9d7', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1030', NULL, 915, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b135718-5b6e-4746-9e3f-0d18db9a9055', 'f4d6172b-67f7-4d54-bbf1-d647430bf9d7', 1, 'La aceptación de la herencia no puede hacerse condicional ni parcialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ce0dabf-9d2c-4830-8d90-2af98ae15ff4', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1031', NULL, 916, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('715f935a-8afb-4089-8f27-cd3b9ace8aa7', '3ce0dabf-9d2c-4830-8d90-2af98ae15ff4', 1, 'El término para aceptar la herencia es de seis meses a contar de la muerte del testador, si el heredero se encuentra en el territorio de la República y de un año si está en el extranjero. Si pasa el término de la aceptación sin que nadie se presente a reclamar la herencia, ni haya heredero a quien manifiestamente pertenezca, o han renunciado los que tenían derecho a ella, se declarará vacante, arreglándose a las prescripciones del Código Procesal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1f6931f-c40e-4693-86b6-ed07692a06ae', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1032', NULL, 917, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('246b371d-e05a-4831-a739-9fe6d73f9180', 'd1f6931f-c40e-4693-86b6-ed07692a06ae', 1, 'Una vez aceptada la herencia, el heredero es propietario de ella desde la muerte del causante, y son suyos los frutos y las ganancias y pérdidas de los bienes hereditarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('89788885-91ee-4bcb-952b-f21e6109790c', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1033', NULL, 918, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('132e60fe-fcba-4121-8aec-fa49fba5ef02', '89788885-91ee-4bcb-952b-f21e6109790c', 1, 'Pueden renunciar la herencia y legados los que tengan la libre disposición de sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8f775195-1fbb-4cac-b0f3-28631ea44d9d', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1034', NULL, 919, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f88716c-78d9-46a4-ae7f-57c5ce7d6b30', '8f775195-1fbb-4cac-b0f3-28631ea44d9d', 1, 'El término para renunciar la herencia es el mismo que el de la aceptación. La renuncia debe ser expresa y hacerse por escrito ante el juez o por medio de escritura pública.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8ded406b-ab3a-4f50-8776-899fbf2c069e', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1035', NULL, 920, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d8ce7eb-f0f2-48a6-b328-8aa55a57a0d0', '8ded406b-ab3a-4f50-8776-899fbf2c069e', 1, 'La renuncia de la herencia solamente, no priva al que la hace de reclamar los legados que se le hubieren dejado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fceaa15e-0f4f-4a22-a730-ba1340d36e0f', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1036', NULL, 921, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('167c7067-aa70-4b69-bf0f-d7326b5ba295', 'fceaa15e-0f4f-4a22-a730-ba1340d36e0f', 1, 'El acreedor del heredero o legatario que renuncia a la herencia o al legado, puede reclamar la parte que cubra su crédito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd060512-9060-46e0-ac04-cdc0d41e7582', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1037', NULL, 922, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aad82f6f-51a3-48c0-be80-3a9c8a47b8c6', 'dd060512-9060-46e0-ac04-cdc0d41e7582', 1, 'El que es llamado a una misma herencia por testamento o intestado, si renuncia la una se entiende que renuncia las dos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('66f82199-0077-4cbe-9e9d-d5dbb8d3d017', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1038', NULL, 923, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88508159-f9b7-4aa0-bdc2-0e5ae7da7b3c', '66f82199-0077-4cbe-9e9d-d5dbb8d3d017', 1, 'Cuando alguno tuviere interés en que el heredero declare si acepta o renuncia a la herencia, podrá pedir, pasados nueve días de la apertura de ésta, que el juez fije un plazo que no excederá de treinta días, para que dentro de él haga su declaración, bajo apercibimiento de que si no lo hace se tendrá la herencia por aceptada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab4e7b62-d1e2-4e49-806d-f6599271bfb8', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1039', NULL, 924, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c75c9a6-e2bd-4d2a-99fb-dc6c0a17a3d4', 'ab4e7b62-d1e2-4e49-806d-f6599271bfb8', 1, 'Si el heredero renuncia la herencia en perjuicio de sus acreedores, pueden éstos, siempre que sus créditos fueren anteriores a la renuncia, pedir al juez que los autorice para aceptar en nombre de aquél. En este caso, la aceptación sólo aprovechará a los acreedores hasta el monto de sus créditos; correspondiendo el exceso, si lo hubiere, a los herederos que sean llamados por la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8a7cf014-45bc-409a-86a5-131658eafc6e', 'a0000000-0000-0000-0000-000000000001', '4d6e7e78-2af4-460a-8e8c-8d2716cbbe0d', '1040', NULL, 925, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44f14102-ad72-455c-bf25-7e170c3d4718', '8a7cf014-45bc-409a-86a5-131658eafc6e', 1, 'El que deba entrar a la posesión de la herencia por la renuncia del heredero, puede oponerse a que la acepten los acreedores pagando a éstos los créditos que tengan contra el que renunció.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee45c8f8-37cc-4aa8-ace0-fc2ceea957e6', '8a7cf014-45bc-409a-86a5-131658eafc6e', 2, 'ALBACEAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f8586a3c-f061-44fc-bad7-11ada426676b', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1041', NULL, 926, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c977928c-861c-489a-b073-9a013832d42e', 'f8586a3c-f061-44fc-bad7-11ada426676b', 1, 'Albacea o ejecutor testamentario, es la persona a quien el testador encarga el cumplimiento de su voluntad. Los albaceas tendrán todas las facultades que expresamente les haya conferido el testador, y no sean contrarias a las leyes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1a76b1c-8504-4a04-8d38-7f57cd73e88c', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1042', NULL, 927, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e6e83a7-39ca-475c-a44d-c6a68f575450', 'd1a76b1c-8504-4a04-8d38-7f57cd73e88c', 1, 'Puede haber también albacea Judicial, por nombramiento de juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('32c811a1-2d8e-4bbf-91a8-97b7cdc16267', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1043', NULL, 928, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92725217-cf08-4fb8-8e72-5560422a0ab0', '32c811a1-2d8e-4bbf-91a8-97b7cdc16267', 1, 'Se nombrará albacea judicial sólo en los casos de renuncia, remoción o falta del que estaba nombrado en el testamento, cuando así lo pidieren los herederos instituidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bbe82038-3d3e-470b-bd9d-46e7e00df454', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1044', NULL, 929, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c018260-1852-4660-93b2-e1ef4eb5c4bf', 'bbe82038-3d3e-470b-bd9d-46e7e00df454', 1, 'Los herederos o el juez en su caso, pueden exigir garantía al albacea judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e2675cc-35ad-4bf7-8785-40ba81a403a7', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1045', NULL, 930, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e6de4a4-01cc-4b6e-9a07-25c5c90672de', '9e2675cc-35ad-4bf7-8785-40ba81a403a7', 1, 'Incumbe a los herederos cumplir la voluntad del testador cuando éste no hubiere nombrado albacea.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2ee14937-58a1-4f6a-82c2-6e6baa6c4dbc', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1046', NULL, 931, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12713667-4bbd-4a6f-a00b-4bcf2bae21b2', '2ee14937-58a1-4f6a-82c2-6e6baa6c4dbc', 1, 'Incumbe también a los herederos ejecutar las disposiciones del testador, siempre que no se hayan cumplido, sea por no estar comprendidas en la comisión del albaceazgo, o por falta de posibilidad o de voluntad del albacea nombrado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ce8a930d-1909-4117-9dab-00a05897bfc3', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1047', NULL, 932, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c50878d-8f5d-4ec2-bc0d-219c183f80f7', 'ce8a930d-1909-4117-9dab-00a05897bfc3', 1, 'Puede conferirse el albaceazgo a una o más personas para lo que ejerzan mancomunadamente o una después de otra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3935d27a-d8fc-408c-9e15-b97f5e6eeefd', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1048', NULL, 933, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e8810f62-df70-4fbe-8bf8-dfd69823f252', '3935d27a-d8fc-408c-9e15-b97f5e6eeefd', 1, 'Para ser albacea se necesita haber cumplido dieciocho años de edad, poder legalmente administrar bienes, no ser incapaz de adquirirlos a título de herencia, y no estar en actual servicio de funciones judiciales o del Ministerio Público, aunque se halle con licencia temporal, salvo en los casos de que se trate de las sucesiones de sus parientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('74c092be-a4ac-446d-877b-7d20d510d282', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1049', NULL, 934, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72842fa3-0b32-4d90-b9e8-b7fbd2ba60cd', '74c092be-a4ac-446d-877b-7d20d510d282', 1, 'Ninguno está obligado a aceptar el cargo de albacea, pero no puede renunciarlo después de aceptarlo, sino con justa causa, a juicio del juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('526610dd-d306-458a-b948-7a0f68b54152', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1050', NULL, 935, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6c6272c-e900-4bb5-b79e-fd0f6822350a', '526610dd-d306-458a-b948-7a0f68b54152', 1, 'Las facultades y atribuciones de los albaceas, además de las que designe el testador, serán las siguientes: 1. Disponer y pagar los funerales del testador, con arreglo a lo ordenado por éste, y en defecto de tal disposición, según las costumbres del lugar y las posibilidades de la herencia;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8d0dc2a2-1c1f-4513-afd7-91a2a60ee1dc', '526610dd-d306-458a-b948-7a0f68b54152', 2, '2. Hacer las gestiones necesarias para la inmediata seguridad de los bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be81f04c-ffda-4002-ad56-504456d54ba8', '526610dd-d306-458a-b948-7a0f68b54152', 3, '3. Hacer el inventario, con intervención de los herederos, y cuando no los haya, con la de los interesados en los bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2e826954-a4c3-443b-86ed-760c3e330149', '526610dd-d306-458a-b948-7a0f68b54152', 4, '4. Pagar las deudas y legados; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('30945e4d-e032-4e21-8fa2-63d2b76ddecb', '526610dd-d306-458a-b948-7a0f68b54152', 5, '5. Administrar los bienes, hasta que los herederos tomen posesión de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2e3632e3-ee49-49a3-b7c4-5581d5272282', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1051', 'Obligaciones relativas al patrimonio familiar', 936, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62af8eb5-4260-42fc-a18f-e1413ed8153b', '2e3632e3-ee49-49a3-b7c4-5581d5272282', 1, 'Cuando el testador haya instituido patrimonio familiar, el albacea, y si no hubiere, los herederos, tienen obligación de hacer las gestiones pertinentes para cumplir lo dispuesto en el testamento, debiendo iniciarlas en el momento en que se abra la sucesión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29018b5f-806a-41ba-9ea8-569790c86ff6', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1052', 'Venta de bienes para pago de deudas y legados', 937, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3616efb1-8ee0-418d-80f4-7c425ab30679', '29018b5f-806a-41ba-9ea8-569790c86ff6', 1, 'Si no hubiere en la herencia dinero bastante para hacer los pagos de las deudas y de los legados, promoverán los albaceas la venta de los bienes muebles, y no alcanzando éstos, la de los inmuebles, procediendo en ambos casos con intervención de los herederos. Si los herederos fueren menores o incapaces, no se procederá sin la intervención judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc17d198-eddf-40a7-93ad-ed4f808b710a', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1053', 'Entrega de legados', 938, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96a5d1eb-e42a-4095-bcb9-8f7f7d9ca3e0', 'dc17d198-eddf-40a7-93ad-ed4f808b710a', 1, 'Practicado el inventario, cuidará el albacea que se entreguen los legados específicos y asegurará el pago de los demás legados, a su satisfacción; y quedará la herencia en poder de los herederos, aunque no haya transcurrido el término legal del albaceazgo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d676779d-69a5-4864-99a7-b1fca803dfdf', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1054', NULL, 939, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7580868c-72e6-4514-b0ee-291c5f91572f', 'd676779d-69a5-4864-99a7-b1fca803dfdf', 1, 'Mientras el albacea no sea removido ni haya declaratoria de herederos, tiene la representación de la sucesión para demandar y responder en juicio, salvo prohibición del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('62ae0e6c-34c3-4fcc-9e79-b4100f1879b4', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1055', 'El cargo de albacea no puede transmitirse', 940, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc599a2b-1675-4385-9c88-877794c5a189', '62ae0e6c-34c3-4fcc-9e79-b4100f1879b4', 1, 'El cargo de albacea es meramente personal y no puede transmitirse ni substituirse por el que lo ejerce. Pasan, sin embargo, a sus herederos, las responsabilidades civiles en que hubiese incurrido por su administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef018cb9-4d69-4dda-8784-f2e852693768', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1056', 'Para actos de administración pueden dar poderes especiales', 941, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d1d9772-328f-4175-8de0-fdbb7448858c', 'ef018cb9-4d69-4dda-8784-f2e852693768', 1, 'No obstante lo prevenido en el artículo anterior, podrán los albaceas dar poderes especiales en relación a los actos que a ellos les competen, siendo personalmente responsables por los actos del mandatario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0d42bd91-9d75-463c-9d43-7d94f166b477', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1057', 'Prohibición del albacea de adquirir bienes de la herencia', 942, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2e48f49-b2df-4480-b37b-e22c595b9e8b', '0d42bd91-9d75-463c-9d43-7d94f166b477', 1, 'Durante el ejercicio del albaceazgo, y mientras no estén aprobadas las cuentas de administración, no podrá adquirir el albacea por sí, ni por medio de otro, bienes de la testamentaria, ni créditos contra ella, bajo pena de nulidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('279d0f05-6cf4-4f8b-8434-e5d82e1dc9c9', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1058', 'Plazo del albaceazgo', 943, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1ac6ddb-daae-4607-9827-face7a80f14f', '279d0f05-6cf4-4f8b-8434-e5d82e1dc9c9', 1, 'El albacea, a quien el testador no haya fijado plazo, deberá cumplir su encargo dentro de un año contado desde su aceptación, o');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d91b80c8-e642-4119-b638-b5ded968ba1a', '279d0f05-6cf4-4f8b-8434-e5d82e1dc9c9', 2, 'desde que terminen los litigios que se promovieren sobre la validez o nulidad del testamento o de alguna de sus disposiciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d06da51-5143-43d7-ba44-f8bb5f333492', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1059', NULL, 944, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e8589d53-ec27-42d2-91bf-2fc44adffd6c', '4d06da51-5143-43d7-ba44-f8bb5f333492', 1, 'Si el testador quisiere ampliar el plazo legal deberá señalar expresamente el de la prórroga. Si no lo hubiese señalado, se entenderá prorrogado el plazo por un año. Si transcurrida esta prórroga, no se hubiese todavía cumplido la voluntad del testador, podrá el juez conceder otra por el tiempo que fuere necesario, atendidas las circunstancias del caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('637ce60d-d2c5-45b5-8da1-531fcf111fd7', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1060', NULL, 945, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5956652d-2d86-482e-85d5-aff0670cb50b', '637ce60d-d2c5-45b5-8da1-531fcf111fd7', 1, 'Los herederos y legatarios podrán de común acuerdo, prorrogar el plazo del albaceazgo por el tiempo que crea necesario; pero si el acuerdo fuese sólo por mayoría, la prórroga no podrá exceder de un año.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ab45092-c988-477f-9625-fd8c08f160da', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1061', 'Rendición de cuentas', 946, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('076cbc8f-3355-46cd-a238-497bf600e526', '1ab45092-c988-477f-9625-fd8c08f160da', 1, 'Son nulas de pleno derecho las disposiciones por las que el testador dispensa al albacea de la obligación de hacer inventario y rendir cuentas. El albacea dará a los interesados cuenta documentada del albaceazgo, inmediatamente después de haberlo ejercido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a1869b7-1d16-4550-aca1-40e66cc4247a', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1062', 'Gastos', 947, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('edc32e0b-4929-4d8c-8277-a96ce327bb43', '4a1869b7-1d16-4550-aca1-40e66cc4247a', 1, 'Los gastos del albaceazgo se pagarán de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('043e1a12-56a9-41ca-a84f-b34f5c48a777', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1063', 'Honorarios del albacea', 948, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afff833f-1a7a-4b05-94fc-15b08e6424a7', '043e1a12-56a9-41ca-a84f-b34f5c48a777', 1, 'El albacea, si no fuere heredero o legatario, tendrá por su trabajo el honorario del dos por ciento (2%) del valor de los bienes por él administrados o inventariados, si la cantidad llega o pasa de cincuenta mil quetzales; del tres por ciento (3%), si a cuarenta; del tres y medio por ciento (3 1/2%), si a treinta; del cuatro por ciento (4%), si a veinte; y del cinco por ciento (5%), cuando baje de esa cantidad. Si fueren varios los albaceas, ese honorario se distribuirá entre ellos, proporcionalmente al trabajo que cada cual haya realizado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2745be03-e915-4800-8c7b-3c60c3c5cdc5', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1064', 'Aseguramiento que pueden exigir los herederos', 949, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f51d513-8c2f-4c17-8732-c1b3750adcba', '2745be03-e915-4800-8c7b-3c60c3c5cdc5', 1, 'En la herencia desde día cierto, o desde que se hayan cumplido los encargos del testador, los herederos tienen derecho a exigir que el albacea asegure la devolución de los bienes, para cuando llegue el día o se hayan cumplido los encargos, sin más menoscabo en cuanto de él dependa, que el que resulta naturalmente de las disposiciones del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03ca1ec5-8552-40c8-b1fc-56b72e977b17', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1065', NULL, 950, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('54eaf590-f2de-48af-a5f4-51ed3ee3fd4d', '03ca1ec5-8552-40c8-b1fc-56b72e977b17', 1, 'Los legatarios desde día cierto, o desde que se hayan cumplido los encargos del testador, no habiendo herederos, gozan del mismo derecho concedido a éstos en el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ffc23bb0-d5f8-4cab-baba-ea17be449633', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1066', 'Remoción del albacea', 951, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f84d1255-b3e1-4d1a-a8ce-1e2f03a2f181', 'ffc23bb0-d5f8-4cab-baba-ea17be449633', 1, 'Por causa de negligencia, abuso o malversación pueden ser removidos los albaceas, sean cuales fueren su clase, y extensión de sus facultades, a petición de los interesados en los bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('acee8ab5-fec8-4b8a-a604-68c7563d3e4e', 'a0000000-0000-0000-0000-000000000001', 'feaef8ce-707f-4bce-909a-2c27a91c4cc0', '1067', NULL, 952, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f031ea75-b5bd-43c3-988c-0f3936c4a958', 'acee8ab5-fec8-4b8a-a604-68c7563d3e4e', 1, 'Termina el albaceazgo por la muerte, imposibilidad, renuncia o remoción del albacea, y por el vencimiento del término señalado por el testador, por la ley y, en su caso, por los interesados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('114ffb2c-f424-4c8c-a6c2-a4385a96407b', 'acee8ab5-fec8-4b8a-a604-68c7563d3e4e', 2, 'DE LA SUCESION INTESTADA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e651a646-4ac8-4e66-a857-6d375cc798bc', 'acee8ab5-fec8-4b8a-a604-68c7563d3e4e', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e18e11f-9388-420c-8a24-a7061b2cbf07', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1068', 'Casos en que tiene lugar', 953, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db978453-cbb2-4ef9-a7f0-563622bdb06e', '8e18e11f-9388-420c-8a24-a7061b2cbf07', 1, 'La sucesión intestada tiene lugar: 1. Cuando no hay testamento;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0c226ae4-39a7-4dbf-bef8-dd27350f2bbf', '8e18e11f-9388-420c-8a24-a7061b2cbf07', 2, '2. Cuando falta la condición puesta a la institución de heredero o el instituido muere antes que el testador, o es incapaz de heredar, o repudió la herencia; fuera de los casos de sustitución, representación y acrecimiento con arreglo a este Código;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('281835e6-2df7-43cb-9b6a-5f033ce06236', '8e18e11f-9388-420c-8a24-a7061b2cbf07', 3, '3. Cuando en el testamento no hay heredero instituido y el testador no ha dispuesto de todos sus bienes en legados; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db8afa21-09fd-434b-9b89-401d22e3c972', '8e18e11f-9388-420c-8a24-a7061b2cbf07', 4, '4. Cuando el testador ha dejado de disponer de alguno o algunos de sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('71ea2a46-cad0-4d3e-b5b7-afc97547b082', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1069', NULL, 954, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('58925c7f-9252-4858-9302-ea2814fc2c71', '71ea2a46-cad0-4d3e-b5b7-afc97547b082', 1, 'En los casos de los incisos 3 y 4 del artículo anterior, el intestado sólo procede respecto de los bienes de que no dispuso el testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('12d9f561-9a08-4cfa-8a1b-2fa8f05beee6', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1070', NULL, 955, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a760999-b85d-47ed-bca7-08449a0198d2', '12d9f561-9a08-4cfa-8a1b-2fa8f05beee6', 1, 'Para reglar la sucesión intestada, la ley sólo considera los vínculos del parentesco; no el sexo de las personas, ni la naturaleza, ni el origen de los bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6b8edcbe-1a15-4ead-8510-2cbd4c4842cf', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1071', NULL, 956, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c24bb62c-b322-44e2-8fe6-704df33dcbd4', '6b8edcbe-1a15-4ead-8510-2cbd4c4842cf', 1, 'En la sucesión intestada se hereda por derecho propio y por derecho de representación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9d19bb6-cd37-447d-85d4-7dab9323388e', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1072', NULL, 957, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18492475-e7a4-46dc-a135-bcae9b85e9b6', 'e9d19bb6-cd37-447d-85d4-7dab9323388e', 1, 'Los que suceden por derecho propio heredan por cabezas, es decir, que cada uno toma por iguales partes, la porción que la ley le asigna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f7a92f78-d34d-43e7-b549-122b7ed5f4c7', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1073', NULL, 958, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('78a0ee13-aead-4f36-9f2e-25064a9f0cfb', 'f7a92f78-d34d-43e7-b549-122b7ed5f4c7', 1, 'Los que suceden por derecho de representación, heredan por estirpes, tal como se expresa en el artículo 932.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ed483e6-eb8f-4716-82e5-a4a867dcd63a', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1074', NULL, 959, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57d12a15-d140-488f-baaa-0dd9e4d81534', '6ed483e6-eb8f-4716-82e5-a4a867dcd63a', 1, 'Son llamados a la sucesión intestada, según las reglas que más adelante se determinan, los parientes del difunto y, a falta de éstos, el Estado y las universidades de Guatemala, por partes iguales. El pariente más próximo en grado excluye al más remoto, salvo el derecho de representación en los casos en que deba tener lugar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52c533b4-99ca-4fb0-8bc6-aa1fc584590d', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1075', NULL, 960, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19e9bf22-9e6b-4ddb-b78e-068c00899dbd', '52c533b4-99ca-4fb0-8bc6-aa1fc584590d', 1, 'En el caso de ser la sucesión parte intestada y parte testamentaria, se procederá previamente a la liquidación, a fin de pagar el pasivo de la herencia, y en seguida se partirán separadamente los bienes intestados y los testamentarios, respetando siempre la voluntad del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('715e3dda-c119-4e88-af0a-ec00c4471d69', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1076.19', 'Todos los hijos heredan por partes iguales', 961, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d6300df9-237b-4663-8934-2975f21766f8', '715e3dda-c119-4e88-af0a-ec00c4471d69', 1, 'Los hijos biológicos o adoptivos, heredan a sus padres por partes iguales. más no conservan los derechos sucesorios con su antigua familia');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6bb4a1af-fe60-4235-9b20-02fc4dd909f2', 'a0000000-0000-0000-0000-000000000001', '43144a50-53e8-4dc7-9dc7-38173eee0222', '1077', NULL, 962, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f327fcb1-56e4-4256-a323-c158badc83cd', '6bb4a1af-fe60-4235-9b20-02fc4dd909f2', 1, 'Si hubiere varios parientes de un mismo grado y alguno o algunos renunciaren o no pudieren heredar, su parte acrecerá a los otros del mismo grado, salvo el derecho de representación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e679e58-bc7f-4d28-b32d-45c1b7693f8c', '6bb4a1af-fe60-4235-9b20-02fc4dd909f2', 2, 'ORDEN DE SUCESION INTESTADA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fae14bcc-cbe9-4a08-bc5d-70c7424614c3', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1078', NULL, 963, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('86ec3592-8509-425c-a262-c9c4a5056d38', 'fae14bcc-cbe9-4a08-bc5d-70c7424614c3', 1, 'La ley llama a la sucesión intestada, en primer lugar, a los hijos, incluyendo a los adoptivos, y al cónyuge sobreviviente que no tenga derecho a gananciales; quienes heredarán por partes iguales. No obstante el cónyuge sobreviviente cuyo derecho de gananciales sea menor que la cuota hereditaria que le correspondería en ausencia de gananciales, tendrá derecho a que se le complete un monto equivalente a dicha cuota, deduciéndose la diferencia de la masa hereditaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f5657f82-0e99-4a6f-b279-0bb80fe235f3', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1079', NULL, 964, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e614cdcb-18cf-40b1-98b4-6b740fd12ace', 'f5657f82-0e99-4a6f-b279-0bb80fe235f3', 1, 'A falta de descendencia, sucederán los ascendientes más próximos y el cónyuge, por iguales porciones, y cuando sólo hubiere una de esas partes, ésta llevará toda la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e40d8a8e-c6f1-4224-b019-412f6f392e7a', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1080', NULL, 965, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5181fb9f-3351-4d82-bb95-3ac4ebfc17d5', 'e40d8a8e-c6f1-4224-b019-412f6f392e7a', 1, 'A falta de los llamados a suceder, según el artículo anterior, sucederán los parientes colaterales hasta el cuarto grado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a230923-590c-4ad8-b510-43f702776d99', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1081', NULL, 966, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15e2b919-a374-415c-8e91-06bbf2c33a84', '6a230923-590c-4ad8-b510-43f702776d99', 1, 'Lo dispuesto en los artículos anteriores se entenderá sin perjuicio de los derechos de representación y de alimentos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33b403cb-5554-42be-9bb2-7017b3a1822d', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1082', NULL, 967, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1f29008-b2da-4da3-a214-4c50319b9ac4', '33b403cb-5554-42be-9bb2-7017b3a1822d', 1, 'El cónyuge separado no tendrá parte alguna en la herencia intestada de su mujer o marido, si por sentencia hubiere sido declarado culpable de la separación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9045fb26-3f50-454b-9880-72b05cff07d6', '33b403cb-5554-42be-9bb2-7017b3a1822d', 2, '19 Reformado como aparece en el texto por el Artículo 66, del Decreto No. 77-2007 publicado en el Diario de Centro América el 31 de diciembre de 2007.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b58917b5-b182-4b86-adf3-1f37f71cdc6f', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1083', NULL, 968, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25bc37f4-b364-4b91-ac0a-53cd005a585a', 'b58917b5-b182-4b86-adf3-1f37f71cdc6f', 1, 'El cónyuge divorciado no tendrá parte alguna en la herencia intestada de su excónyuge.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('caf1eea0-887e-4f1a-8652-19b760675853', 'a0000000-0000-0000-0000-000000000001', '23122085-c07e-4f83-acf9-0c7b7121b02e', '1084', NULL, 969, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f083399-c430-4929-bd8f-e3f3da6959fd', 'caf1eea0-887e-4f1a-8652-19b760675853', 1, 'La sucesión de las personas que tienen legalizada su unión de hecho, se regula por los preceptos anteriores. El hombre o mujer supérstite ocupan el primer lugar, juntamente con los hijos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88fc97d8-1b60-45ed-811e-e75ff1a35323', 'caf1eea0-887e-4f1a-8652-19b760675853', 2, 'PARTICION DE BIENES HEREDITARIOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('35d8d5ed-93a6-4d54-9112-6a9ed3694cc6', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1085', 'Obligación del albacea de hacer la partición', 970, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b72107dc-13a4-4165-b799-fc401741732c', '35d8d5ed-93a6-4d54-9112-6a9ed3694cc6', 1, 'Aprobados el inventario y la cuenta de administración, el albacea debe hacer inmediatamente la partición de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('76862d18-f5b0-41f5-943d-3fc10ad8c266', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1086', 'No puede suspenderse la partición', 971, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee499346-aa3c-4265-990f-9fdd75f9dcda', '76862d18-f5b0-41f5-943d-3fc10ad8c266', 1, 'Sólo puede suspenderse una partición, en virtud de convenio expreso de los interesados y por un término que no pase de tres años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('faae5f64-8623-4b62-9487-cce64e5c717b', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1087', 'No puede obligarse a la proindivisión', 972, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f4894db1-2f0f-44ff-9258-475f3301c790', 'faae5f64-8623-4b62-9487-cce64e5c717b', 1, 'A ningún coheredero puede obligársele a permanecer pro indiviso en los bienes hereditarios, ni aún por orden expresa del testador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b2aadaac-c7ff-4031-a407-c48fc7d3a4ca', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1088', 'Herederos que pueden pedir la partición', 973, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef28d24c-c055-417f-a52f-35917efa5dc3', 'b2aadaac-c7ff-4031-a407-c48fc7d3a4ca', 1, 'Todo coheredero que tenga la libre disposición de sus bienes puede pedir, en cualquier tiempo, la partición de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2ecb4797-b296-4645-a3ac-450c16aed073', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1089', NULL, 974, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c4f9dc4-ba79-4860-a4ee-66d1a4393926', '2ecb4797-b296-4645-a3ac-450c16aed073', 1, 'Por los incapacitados y por los ausentes deben pedir la partición sus representantes legítimos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1495276d-a7d9-4147-ab50-42381bc4b5da', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1090', NULL, 975, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('745fd0d3-eb15-4c92-82f5-22cc0add6fa4', '1495276d-a7d9-4147-ab50-42381bc4b5da', 1, 'Los herederos bajo condición, no pueden pedir la partición hasta que aquélla se cumpla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('10046ba2-9fad-4ec3-a2fe-75873c0e97e5', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1091', NULL, 976, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1b095b15-2aa5-4e56-9ee2-347a2dcfe5e9', '10046ba2-9fad-4ec3-a2fe-75873c0e97e5', 1, 'Los coherederos del heredero condicional pueden pedir la partición asegurando competentemente el derecho de aquél, para el caso de realizarse la condición; y hasta establecerse que ésta ha faltado o no puede ya verificarse, la partición se tendrá como provisional.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61bfc704-0635-4b31-ab57-c74b79ee122f', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1092', NULL, 977, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e1c9ceb-cbf9-4c5e-8a5a-e74819cca852', '61bfc704-0635-4b31-ab57-c74b79ee122f', 1, 'La partición se considerará provisional en el caso del artículo anterior, sólo en cuanto a la parte en que consiste el derecho del pretendiente, y en cuanto a las cauciones con que se haya asegurado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2b4b509-b9dc-40b1-9f8d-f3784c975b02', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1093', 'Legatario de parte alícuota', 978, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c7917a1e-f235-496f-a473-5257bd5447eb', 'c2b4b509-b9dc-40b1-9f8d-f3784c975b02', 1, 'El legatario de parte alícuota de la herencia, puede pedir la partición; el del género o cantidad puede pedir la entrega del legado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a7f104b6-c3eb-411f-9dd5-a636b21c73ca', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1094', 'Acreedor de heredero o legatario de parte alícuota', 979, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ce67920-414d-4c65-9c72-430731ad10fd', 'a7f104b6-c3eb-411f-9dd5-a636b21c73ca', 1, 'El acreedor de un heredero o de un legatario de parte alícuota que ha embargado el derecho que éstos tienen a la herencia y que ha obtenido sentencia de remate, puede pedir la partición, siempre que el pago no pueda hacerse con otros bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6e309c8f-f385-40a9-8b9a-ac4439516e86', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1095', NULL, 980, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91291dcd-c9e3-4907-bc59-b0a55ef8fb60', '6e309c8f-f385-40a9-8b9a-ac4439516e86', 1, 'También pueden pedirla los cesionarios, ya sea del heredero o del legatario de parte alícuota.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88978a06-f4d0-4493-ae66-7b614343ce85', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1096', NULL, 981, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('660f4b89-ac4d-4019-8eca-013bc5463868', '88978a06-f4d0-4493-ae66-7b614343ce85', 1, 'Si antes de hacerse la partición muere uno de los herederos, dejando dos o más herederos, deberán éstos proceder de consuno y bajo una misma representación bastando que uno de ellos pida la partición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('44247a46-2253-444d-9a00-0491f3ea7e36', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1097', NULL, 982, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a9584f0-c8b6-4dbc-8fa4-c2d10c8b87b1', '44247a46-2253-444d-9a00-0491f3ea7e36', 1, 'Respecto de la partición de los bienes de un ausente, una vez declarada la muerte presunta, se procederá de acuerdo con lo dispuesto en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2fc884af-e136-4b14-a5f5-4064f3c0c1ff', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1098', 'Partición hecha por el testador', 983, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('017c7b00-a007-40f1-b40e-2ec2eceb6a8a', '2fc884af-e136-4b14-a5f5-4064f3c0c1ff', 1, 'El dueño de los bienes puede hacer la partición de ellos por acto entre vivos, siempre que se respeten y aseguren los derechos de las personas que deben ser alimentadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc875543-8e4c-4d3f-987e-db33fe671ff5', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1099', 'Derechos de los alimentistas', 984, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('69d08301-ebbb-4ca4-9c38-880e606e858f', 'dc875543-8e4c-4d3f-987e-db33fe671ff5', 1, 'Al hacerse la partición de bienes, deben los herederos asegurar, en beneficio de los alimentistas, las porciones o cuotas a que éstos tengan derecho; y sin ese requisito no será inscrita la partición. En tal caso, los registradores harán de oficio, anotación sobre los bienes de la herencia, la que se cancelará hasta que estén garantizados los alimentos y las pensiones debidas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('802ac4bc-a9ae-4e3a-9319-4832d5f1509d', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1100', 'Heredero ausente', 985, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41189168-1bbd-4310-8981-df25dec1649d', '802ac4bc-a9ae-4e3a-9319-4832d5f1509d', 1, 'Si alguno de los herederos estuviere ausente y no tuviere representante legítimo, el juez a petición de cualquier persona capaz o del Ministerio Público, procederá a nombrarle su representante en los términos establecidos en el tratado de ausencia. Cuando hubiere ausentes, menores o incapacitados, la partición debe ser aprobada judicialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('354143d0-b770-493c-b591-5207aa061ef5', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1101', NULL, 986, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a147667-0164-4e65-8441-b311bf218ac8', '354143d0-b770-493c-b591-5207aa061ef5', 1, 'La proindivisión de bienes se regirá por las reglas de la comunidad de bienes, si los interesados no hubieren acordado las normas de administrarla y regirla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ecf2682-136b-4243-9f01-d68c85b79950', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1102', 'Partición extrajudicial', 987, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('405aed6c-e0fa-4a08-902b-3e9e52864184', '9ecf2682-136b-4243-9f01-d68c85b79950', 1, 'Cuando los herederos son mayores de edad y no hay ausentes o incapaces, podrán partir los bienes como mejor les parezca, sin intervención judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ee9a16d-09dd-44c7-8529-c2740641e57a', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1103', 'Obligación recíproca de los herederos', 988, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cee63e8d-f95e-44e1-93b7-2426af328511', '1ee9a16d-09dd-44c7-8529-c2740641e57a', 1, 'Los herederos deben abonarse recíprocamente las rentas y frutos que cada uno haya recibido de los bienes hereditarios, los gastos útiles y necesarios y los daños ocasionados por malicia o negligencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46b33ffa-ef34-494f-982c-fc277f613ff8', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1104', 'Deudas de la proindivisión', 989, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b4fc618-0c08-4f30-9d3f-42217b14daf9', '46b33ffa-ef34-494f-982c-fc277f613ff8', 1, 'Las deudas contraídas durante la proindivisión serán pagadas preferentemente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ebc4dba7-b697-4ef1-91da-58bc095656ec', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1105', 'Masa hereditaria', 990, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dad934a4-abd9-4119-8a00-328caf82d92e', 'ebc4dba7-b697-4ef1-91da-58bc095656ec', 1, 'De los bienes que deja una persona a su fallecimiento se pagarán sus deudas. El resto es masa hereditaria distribuida entre los que tienen derecho a ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('35032c3b-863f-4cde-8f87-6e3359d9f498', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1106', 'Gastos de enfermedad y muerte', 991, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62a1ff66-62d6-478c-b588-3258172c5f2e', '35032c3b-863f-4cde-8f87-6e3359d9f498', 1, 'Los gastos de última enfermedad, de funerales y lutos se deducirán de la masa hereditaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6685be51-9de1-4266-b825-ceceef14f25b', 'a0000000-0000-0000-0000-000000000001', 'fa55c427-d8a1-4f6d-99ee-4e3b0c4006f6', '1107', 'Gastos de partición', 992, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa3589df-49dd-481e-87c4-55e416c7963c', '6685be51-9de1-4266-b825-ceceef14f25b', 1, 'Los gastos de la partición se rebajarán del fondo común; los que se hagan por el interés particular de algún heredero o legatario, se imputarán a su haber.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f5c2f5c3-0936-41c6-b982-e01a09770f43', '6685be51-9de1-4266-b825-ceceef14f25b', 2, 'EFECTOS DE LA PARTICION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('146d9211-e237-4593-aabc-0b7a5b9a7536', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1108', NULL, 993, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a325d09a-afb6-43ba-9607-2e0d111b9319', '146d9211-e237-4593-aabc-0b7a5b9a7536', 1, 'La partición legalmente hecha, confiere a los coherederos la propiedad exclusiva de los bienes que les hayan sido adjudicados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a57b66ab-eec0-4411-99c1-26fd4152b404', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1109', 'Obligación recíproca de saneamiento', 994, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e160dac-a6aa-4dae-8ca4-d12b0957ef0a', 'a57b66ab-eec0-4411-99c1-26fd4152b404', 1, 'Los coherederos están obligados recíprocamente a indemnizarse en caso de evicción de los bienes repartidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d564bff1-880c-4a06-97fb-d203650c660a', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1110', 'Cuándo cesa la obligación de saneamiento', 995, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2e1fa433-1c33-486b-9f56-49328ba5a3eb', 'd564bff1-880c-4a06-97fb-d203650c660a', 1, 'La obligación de saneamiento sólo cesará en los casos siguientes: 1. Cuando al hacerse la partición entre herederos mayores, se pactó expresamente; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44f5d233-0338-496f-92af-483ce67bccd3', 'd564bff1-880c-4a06-97fb-d203650c660a', 2, '2. Cuando la evicción proceda de causa posterior a la partición o fuese ocasionada por culpa del que la sufre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5bbc0a09-ca33-4c23-95ab-7c01d11ce471', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1111', 'Derecho del que sufra la evicción', 996, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99db55fa-e060-430d-9069-2459ac2c0636', '5bbc0a09-ca33-4c23-95ab-7c01d11ce471', 1, 'El que sufra la evicción será indemnizado por los coherederos, en proporción a sus cuotas hereditarias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b0749e0c-1244-4365-8648-59ca47882c38', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1112', 'Cuota del que pierda su parte', 997, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ebed4c5-bc54-4a2a-a572-bd4d3d0d845c', 'b0749e0c-1244-4365-8648-59ca47882c38', 1, 'La cuota que deberá pagarse al que pierda total o parcialmente su parte por evicción, no será la que represente su haber primitivo, sino la que corresponda, hecha la deducción del total de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6eaf1a90-4504-4cf9-8bb2-dfe9f63418a6', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1113', 'Coheredero insolvente', 998, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fae9844-e0ec-4ec4-847e-e1d1aab2f955', '6eaf1a90-4504-4cf9-8bb2-dfe9f63418a6', 1, 'Si alguno de los coherederos que debe Indemnizar estuviere insolvente, la cuota con que debía contribuir se partirá entre los demás, incluyendo al que perdió su parte por evicción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a06dbed-731f-4ec3-8295-81fcc9d458e9', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1114', NULL, 999, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7830c9b7-096b-43a6-8493-62f5a3787f8e', '7a06dbed-731f-4ec3-8295-81fcc9d458e9', 1, 'Los que pagaren por el insolvente conservarán su acción contra él, para cuando mejore de fortuna.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('59acba42-9169-4e38-b3dd-1fa08eb0e645', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1115', 'Insolvencia del deudor después de la adjudicación', 1000, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d4ebe5b-ff2f-4ff9-8f7a-035b253635ee', '59acba42-9169-4e38-b3dd-1fa08eb0e645', 1, 'Si se adjudica como cobrable un crédito, los coherederos no responden de la insolvencia posterior del deudor; y sólo son responsables de su insolvencia al tiempo de hacerse la partición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('435db08e-dfb5-48a4-a637-e00c27a94cab', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1116', 'Créditos incobrables', 1001, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b195c97-eb21-4533-8170-cf2df94e8446', '435db08e-dfb5-48a4-a637-e00c27a94cab', 1, 'Por los créditos Incobrables adjudicados como tales, no hay responsabilidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('861e1b37-b479-4859-a646-693d8a8ae3d6', 'a0000000-0000-0000-0000-000000000001', 'd8d7a2dd-7f49-4287-90b1-f7eaeed97e3f', '1117', 'Responsabilidad de los coherederos', 1002, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab77d9a0-53fe-479a-9c00-24fa6f2b5d38', '861e1b37-b479-4859-a646-693d8a8ae3d6', 1, 'El heredero cuyos bienes hereditarios fueren embargados, o contra quien se pronuncie sentencia firme por causa de ellos, tiene derecho de pedir que sus coherederos caucionen la responsabilidad que puede resultarles; y en caso contrario, que se les prohíba enajenar los bienes que recibieron.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95e34414-d447-4ba8-bd92-967a5f177cff', '861e1b37-b479-4859-a646-693d8a8ae3d6', 2, 'RESCISION Y NULIDAD DE LA PARTICION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5ea3d951-3220-49af-9bc4-fc7ef773eece', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1118', 'Rescisión de particiones extrajudiciales', 1003, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6f9a3ba-3897-402d-a07f-0a1c7ba8ee7a', '5ea3d951-3220-49af-9bc4-fc7ef773eece', 1, 'Las particiones hechas extrajudicialmente sólo pueden ser rescindidas en los casos en que lo pueden ser los contratos en general.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d4b454b8-a027-4160-894f-897a7531652e', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1119', 'Rescisión de particiones judiciales', 1004, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('181b24a2-b78f-45f0-b262-923658a78b56', 'd4b454b8-a027-4160-894f-897a7531652e', 1, 'Las particiones hechas judicialmente no pueden ser rescindidas sino en los casos de saneamiento u otra causa legal, conforme al capítulo anterior, que trata de los efectos de la partición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c739606-b41b-49f2-af31-0f47c916b2b2', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1120', 'Partición anulable', 1005, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1b3454dd-3c71-4357-8117-6faeee7e1362', '7c739606-b41b-49f2-af31-0f47c916b2b2', 1, 'La partición será anulable si se hubiere hecho con preterición de alguna persona que haya tenido título para heredar en el momento de abrir la sucesión; pero sólo en el caso que hubiere mediado dolo o mala fe por parte de sus coherederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e496e8c-dd2f-47d3-a39c-5c7547b2699b', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1121', NULL, 1006, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('159b1433-a478-4521-9294-4e7ced2b8c9c', '3e496e8c-dd2f-47d3-a39c-5c7547b2699b', 1, 'Si no hubiere mediado dolo o mala fe, o si el título para la herencia intestada se adquiere con posterioridad a la partición, ésta no se rescindirá, pero el preterido tendrá derecho a la parte del valor de los bienes que le corresponderían, determinándose su valor en juicio de expertos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2afc0300-75bd-4aa4-ae25-05ce04e36158', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1122', 'Partición nula', 1007, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25bff804-420c-46a2-b024-022de781e0b9', '2afc0300-75bd-4aa4-ae25-05ce04e36158', 1, 'La partición hecha con un heredero falso, es nula en cuanto tenga relación con él, y en cuanto su personalidad perjudique a otros interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9b7c955-31ae-49e2-972d-5a1a5cb21d4f', 'a0000000-0000-0000-0000-000000000001', '9c93c169-f150-4bd3-81ab-df45aeb03b3c', '1123', 'Partición suplementaria', 1008, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a6d0ed1-d391-4d92-82ff-f0d1c191894f', 'a9b7c955-31ae-49e2-972d-5a1a5cb21d4f', 1, 'Si hecha la partición aparecieren algunos bienes omitidos en ella, se hará una división suplementaria, en la cual se observarán las disposiciones anteriores.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('330038f8-70b0-4f22-862c-43cf7b1d8be5', 'a9b7c955-31ae-49e2-972d-5a1a5cb21d4f', 2, 'DEL REGISTRO DE LA PROPIEDAD');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3d83ad2e-ecfa-4654-920c-8d00d4cc4e9a', 'a9b7c955-31ae-49e2-972d-5a1a5cb21d4f', 3, 'DE LA INSCRIPCION EN GENERAL');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5015d143-f750-4aa7-95d0-27d922639cf8', 'a9b7c955-31ae-49e2-972d-5a1a5cb21d4f', 4, 'DE LOS TITULOS SUJETOS A INSCRIPCION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('244e5292-45ed-479c-975e-ceab6e69198b', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1124.20', NULL, 1009, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99097d69-48f6-4a2b-b536-d4f39352adb9', '244e5292-45ed-479c-975e-ceab6e69198b', 1, 'El Registro de la Propiedad es una institución pública que tiene por objeto la inscripción, anotación y cancelación de los actos y contratos relativos al dominio y demás derechos reales sobre bienes inmuebles y muebles identificables, con excepción de las garantías mobiliarias que se constituyan de conformidad con la Ley de Garantías Mobiliarias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9341ea1-390d-4957-abed-f89665624cee', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1125', NULL, 1010, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eed7d418-7de8-48a0-9ef1-d7d0d251561a', 'a9341ea1-390d-4957-abed-f89665624cee', 1, 'En el Registro se inscribirán: 1. Los títulos que acrediten el dominio de los inmuebles y de los derechos reales impuestos sobre los mismos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff28986d-480c-4c62-9863-4aca8b940b9a', 'a9341ea1-390d-4957-abed-f89665624cee', 2, '2. Los títulos traslativos de dominio de los inmuebles y en los que se constituyan, reconozcan, modifiquen o extingan derechos de usufructo, uso, habitación, patrimonio familiar, hipoteca, servidumbre y cualesquiera otros derechos reales sobre inmuebles; y los contratos de promesa sobre inmuebles o derechos reales sobre los mismos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4750af4b-8406-4e00-932f-345a4c69b0e5', 'a9341ea1-390d-4957-abed-f89665624cee', 3, '3. La posesión que conste en título supletorio legalmente expedido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa5e6829-b42d-4cef-aa26-63a179dc656b', 'a9341ea1-390d-4957-abed-f89665624cee', 4, '4. Los actos y contratos que trasmitan en fideicomiso los bienes inmuebles o derechos reales sobre los mismos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6eded69f-38b9-4dc7-9ca0-9f8d59897840', 'a9341ea1-390d-4957-abed-f89665624cee', 5, '5. Las capitulaciones matrimoniales, si afectaren bienes inmuebles o derechos reales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a83e5a91-f879-4c0b-b866-e1fd2a63a8ff', 'a9341ea1-390d-4957-abed-f89665624cee', 6, '6. Los títulos en que conste que un inmueble se sujeta al régimen de propiedad horizontal; y el arrendamiento o subarrendamiento, cuando lo pida uno de los contratantes; y obligatoriamente, cuando sea por más de tres años o que se haya anticipado la renta por más de un año;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c37a12e1-4c6d-4ba6-90ed-e6d1d540308c', 'a9341ea1-390d-4957-abed-f89665624cee', 7, '7. Los ferrocarriles, tranvías, canales, muelles u obras públicas de índole semejante, así como los buques, naves aéreas, y los gravámenes que se impongan sobre cualesquiera de estos bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('54babb91-fdc6-49c6-9d65-e7f5aa9ffc68', 'a9341ea1-390d-4957-abed-f89665624cee', 8, '20 Reformado como aparece en el texto por el Artículo 77, del Decreto No. 51-77 publicado en el Diario de Centro América el 01 de enero de 2008.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d50e7a1-78ed-440e-89e6-d14a969a1876', 'a9341ea1-390d-4957-abed-f89665624cee', 9, '8. Los títulos en que se constituyan derechos para la explotación de minas e hidrocarburos y su transmisión y gravámenes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e85fa12-d76b-4106-bd39-b03b9bc075a7', 'a9341ea1-390d-4957-abed-f89665624cee', 10, '9. Las concesiones otorgadas por el Ejecutivo para el aprovechamiento de las aguas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96dae0f8-bd22-403c-b9bf-88121c627eb6', 'a9341ea1-390d-4957-abed-f89665624cee', 11, '10. La prenda común, la prenda agraria, ganadera, industrial o comercial;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96f0009f-96a4-4c1b-8484-641edcb487d5', 'a9341ea1-390d-4957-abed-f89665624cee', 12, '11. La posesión provisional o definitiva de los bienes del ausente; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3339b752-14d3-439a-906e-5f85068275e6', 'a9341ea1-390d-4957-abed-f89665624cee', 13, '12. La declaratoria judicial de interdicción y cualquiera sentencia firme por la que se modifique la capacidad civil de las personas propietarias de derechos sujetos a inscripción o la libre disposición de los bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9a266cd-acf7-4780-9ae2-d67c363e525a', 'a9341ea1-390d-4957-abed-f89665624cee', 14, '13. Los edificios que se construyan en predio ajeno con el consentimiento del propietario; los ingenios, grandes beneficios, desmotadoras y maquinaria agrícola o industrial que constituyan unidad económica independiente del fundo en que estén instaladas.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37eeeeb1-36d7-4d0a-9355-8d706d68a484', 'a9341ea1-390d-4957-abed-f89665624cee', 15, '14. Los vehículos automotores y demás muebles fácilmente identificables por los números y modelos de fabricación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1bc2d25-a99b-443d-88f3-b928dc739ec9', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1126', NULL, 1011, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0a4ae691-35a1-431f-b3cf-41e940caf7a1', 'd1bc2d25-a99b-443d-88f3-b928dc739ec9', 1, 'Se inscribirán asimismo en el Registro, los instrumentos o títulos expresados en el artículo anterior, otorgados o expedidos en país extranjero, que reúnan los requisitos necesarios para hacer fe en juicio, y las providencias o sentencias firmes pronunciadas en el extranjero, cuando se hayan mandado cumplimentar por los tribunales de la República, y afecten derechos reales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cf8b7731-164b-4964-841e-b2c475bdc199', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1127', NULL, 1012, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2265d15-87df-4eec-8b82-a4e17e5b2244', 'cf8b7731-164b-4964-841e-b2c475bdc199', 1, 'La inscripción en el Registro puede pedirse por cualquier persona que tenga interés en asegurar el derecho que se deba inscribir. Los registradores harán toda inscripción, anotación o cancelación, dentro del término de ocho días, contado desde la fecha de recepción del documento. Si éste diere lugar a varias de las operaciones antes indicadas, el término se ampliará en seis días más.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67eb6238-0669-45be-89a0-30cbb754297f', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1128', NULL, 1013, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71b89321-2dc0-43ec-ba2e-b9d29968dc06', '67eb6238-0669-45be-89a0-30cbb754297f', 1, 'Si el documento presentado no fuere inscribible o careciere de los requisitos legales necesarios, el registrador lo hará constar en un libro especial que se llevará para tales efectos y en el propio documento, el cual devolverá al interesado, expresando la hora y fecha de recepción en el Registro, así como la ley en que se funda para suspender o denegar la inscripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d31ec13-f0f8-4a18-8dc1-cf98154097b0', 'a0000000-0000-0000-0000-000000000001', 'eff4cc84-86dc-42f3-b488-2ce35fe7905d', '1129', NULL, 1014, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d381a628-2f0a-46a0-9084-e9b47eba9723', '7d31ec13-f0f8-4a18-8dc1-cf98154097b0', 1, 'En ningún tribunal ni oficina pública se admitirán escrituras ni documentos sujetos a inscripción, que no hubieren sido razonados por el registrador');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70e2af55-28e1-4801-9fe7-e23da9bc213c', '7d31ec13-f0f8-4a18-8dc1-cf98154097b0', 2, 'DE LA FORMA Y EFECTOS DE LA INSCRIPCION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a4c45358-ab1f-4329-b219-8fbcac9b68a5', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1130', NULL, 1015, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e22dc2d9-3068-4a64-a01c-c6845c6d71b2', 'a4c45358-ab1f-4329-b219-8fbcac9b68a5', 1, 'La primera inscripción será la del título de propiedad o de posesión y sin ese requisito no podrá inscribirse otro título o derecho real relativo al mismo bien. Dicha inscripción solamente podrá modificarse, ampliarse o enmendarse en los siguientes casos: 1. En virtud de resolución judicial firme;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('426438aa-1641-4c77-9fef-631f45a78c9d', 'a4c45358-ab1f-4329-b219-8fbcac9b68a5', 2, '2. A la presentación de testimonio de escritura pública:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1332cdab-ec7f-4c52-80ea-7f7fbd0197c4', 'a4c45358-ab1f-4329-b219-8fbcac9b68a5', 3, 'a) Cuando los otorgantes de un acto ó contrato que haya dado origen a la primera inscripción de un bien mueble, inmueble o derecho real, comparezcan todos solicitando la modificación, ampliación o enmienda de tal inscripción, por haberse cometido error u omisión en la escritura pública o en el documento original; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d06219fc-a30f-465c-a1a5-ac875e1eb716', 'a4c45358-ab1f-4329-b219-8fbcac9b68a5', 4, 'b) Cuando el propietario solicite que se consigne la ubicación o la dirección del inmueble. En estos casos los datos los declarará bajo juramento en la escritura pública correspondiente y el notario transcribirá el documento extendido por la municipalidad respectiva, en el que conste la ubicación o dirección del bien de que se trate y su identificación registral;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f94bfec4-0e2a-4be7-9fbe-a3402ff34f27', 'a4c45358-ab1f-4329-b219-8fbcac9b68a5', 5, '3. En los demás casos que expresamente autorice la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f47cf1ef-86c0-4d11-bfb2-263652dd961c', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1131.21', NULL, 1016, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc5593d0-420b-47a9-94e4-10bff320d507', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 1, 'Toda inscripción expresará:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1a3b863-9d84-4cc3-a30f-d0786a8f1482', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 2, '1. Si la finca es rústica o urbana, su ubicación indicando el municipio y departamento en que se encuentra, área, rumbos o azimuts; o coordenadas geográficas debidamente georeferenciadas al sistema geodésico nacional; medidas lineales y colindancias; su nombre y dirección si lo tuviere. Tales datos se expresarán en el documento que se presente para su inscripción en Registro de la Propiedad respectivo y en los planos que podrán ser realizados por ingenieros civiles, arquitectos e ingenieros agrónomos, que se encuentren colegiados activos en la república de Guatemala. Se exceptúan de la obligación de presentar planos firmados por los profesionales indicados, los casos de titulaciones supletorias y desmembraciones de las fincas rústicas menores de siete mil metros cuadrados, y las urbanas que se localizan en');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43aa4494-50e6-4be1-bf7d-b9f419e0f974', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 3, '21 Reformado como aparece en el texto el numeral 1 por el Artículo 1 del Decreto No. 33-2000 publicado en el Diario de Centro América el 14 de junio de 2000.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d36fcd39-5d69-42ee-a7e9-9cfc8009a30d', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 4, 'aquellas poblaciones recónditas del país en que no fuere posible localizar a uno de los profesionales indicados, extremo que el Notario deberá hacer constar en el instrumento correspondiente, con la salvedad de que si se tratare de tres desmembraciones o más de la finca matriz, o en el caso de parcelamientos urbanos, el Registro de Propiedad respectivo exigirá como requisito para la inscripción de cada una de las nuevas fincas que los planos sean suscritos de conformidad con las exigencias que contiene el párrafo anterior.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7fc56050-200d-411f-90c1-3b294cd04a82', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 5, '2. La naturaleza, extensión, condiciones y cargas del derecho que se inscriba y su valor si constare;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6102daca-98ff-442f-a983-8bbc522248a9', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 6, '3. La naturaleza, extensión, condiciones y cargas de derechos sobre los bienes que sean objeto de la inscripción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('df18bc86-b153-40e5-aec3-1a93d18a910a', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 7, '4. La naturaleza del acto o contrato, la fecha y lugar de éste;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('62ebf1b7-031c-4da0-9ba9-b7bfd17041bf', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 8, '5. Los nombres completos de las personas otorgantes del acto o contrato;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f74ea606-a445-466e-854c-c544dded4208', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 9, '6. El juez, funcionario o notario que autorice el título;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74137af8-9c50-4043-8803-9010ca07f2d1', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 10, '7. La fecha de entrega del documento al Registro con expresión de la hora, el número que le corresponde según el libro de entregas, el número de duplicado y el tomo en que se archivará; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4f489439-88b8-473e-a042-f409667d3396', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 11, '8. Firma autógrafa y sello del registrador titular, registrador sustituto o registrador auxiliar que autorice la operación, así como el sello del Registro. La firma autógrafa podrá ser sustituida por firma electrónica, digitalizada o impresa por cualquier medio electrónico, que producirá los mismos efectos jurídicos que la autógrafa, siempre que se cumpla con las normas de seguridad establecidas y aprobadas por el Registro para garantizar su legitimidad.22');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5eff6b8f-ffbc-4055-ad72-0bf122bf62ab', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 12, 'Los requisitos a que se refiere el inciso 1, sólo serán necesarios en la primera inscripción.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db2f547a-8c36-4419-9673-521a1a13cb76', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 13, 'La inscripción de bienes muebles identificables se hará con los requisitos y en la forma establecida en el artículo 1214 de este Código.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f29563ce-ec09-4e3f-bc25-c8d0bbc22995', 'f47cf1ef-86c0-4d11-bfb2-263652dd961c', 14, '22 Reformado como aparece en el texto por el Artículo 1, del Decreto No. 42-2006, publicado en el Diario de Centro América el 19 de diciembre de 2006.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('badc62c8-d18e-4966-bf87-6ad0ee092c9d', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1132.23', NULL, 1017, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a41fd85d-72aa-4be3-9a99-7e5ef1966591', 'badc62c8-d18e-4966-bf87-6ad0ee092c9d', 1, 'Todo documento se presentará por duplicado al registro: la copia se extenderá en papel sellado del menor valor y se conservará con la clasificación del caso en la oficina. De los documentos otorgados en el extranjero, se presentará por duplicado certificación notarial. Cuando el Registro esté en capacidad de hacerlo, sustituirá los duplicados que se indican en este artículo por tomas microfílmicas de los documentos originales, disponiéndose la forma más apropiada para su clasificación y conservación');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f6dc1da-55d3-4048-8d4e-fda09c3d8fd8', 'badc62c8-d18e-4966-bf87-6ad0ee092c9d', 2, 'Las razones en los títulos sujetos a inscripción, consistirán en un resumen o una trascripción completa de los correspondientes asientos, impresos por medios mecánicos, electrónicos, computarizados o por cualquier otro proceso de reproducción, llevarán la firma y sello del registrador que la extiende y el sello del Registro. La firma deberá constar utilizando cualquiera de las formas que establece el numeral 8o. del artículo anterior.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4f7d8eb-dc64-488c-8bbb-217e1800206a', 'badc62c8-d18e-4966-bf87-6ad0ee092c9d', 3, 'Adicionado el tercer párrafo por el Artículo 2, del Decreto Del Congreso Número 42-2006 el 19-12-2006');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('699112a2-1e6a-44f6-91cc-96c1aa4ca67f', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1133', NULL, 1018, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('06376c23-fddc-4e77-a666-640d0593c61e', '699112a2-1e6a-44f6-91cc-96c1aa4ca67f', 1, 'Cuando la finca corresponda por su situación a dos o más departamentos, se inscribirá en el registro del territorio donde estuviere enclavada la casa de habitación o las principales oficinas; en su defecto, en el registro del departamento donde estuviere ubicada la mayor parte del terreno. En igualdad de circunstancias, si no hubiere casa ni oficina el interesado la inscribirá en cualquiera de los departamentos en que esté situada la finca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aaf4e151-3860-4028-8501-d83260f779ff', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1134', NULL, 1019, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e90e3e33-65f0-4d2f-b822-9e18ffaf2186', 'aaf4e151-3860-4028-8501-d83260f779ff', 1, 'En las inscripciones relativas a un bien anteriormente inscrito, se omitirán aquellas circunstancias que respecto de él consten ya en el registro, haciéndose sólo referencia a ellas y citándose el número y el libro y folio en que se encuentran; pero se cuidará de expresar las alteraciones que el mismo haya sufrido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('36f38fc8-09e5-43f4-b62a-010711b2142d', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1135', NULL, 1020, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e028f72-4588-494c-a13f-fe2686ab5e7b', '36f38fc8-09e5-43f4-b62a-010711b2142d', 1, 'Cuando hubiere de inscribirse algún acto o contrato traslativo de dominio, en que haya mediado precio, se expresará el que resulte del título, si ha sido al contado o a plazos y la forma en que debe pagarse. Las mismas circunstancias se expresarán también en la permuta y en la adjudicación en pago, si alguno de los interesados quedare obligado a satisfacer al otro cualquiera diferencia en numerario o en especie.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d168489f-c6a0-4bd6-944e-18a8204729e5', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1136', NULL, 1021, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0338255b-96b4-4ff5-b730-74cc212f8d85', 'd168489f-c6a0-4bd6-944e-18a8204729e5', 1, 'Las inscripciones hipotecarias y prendarías expresarán las condiciones a que estén sujetos los créditos, el importe de la obligación garantizada y el plazo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9127f444-e74a-4d53-b048-30a6066893fc', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1137', NULL, 1022, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('184315bb-b946-42a7-9d3c-8ea1006edbb2', '9127f444-e74a-4d53-b048-30a6066893fc', 1, 'Las servidumbres se harán constar en la inscripción de la propiedad, tanto del predio dominante como del predio sirviente; pero si fueren constituidas con el');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('982fbab3-c576-44e9-b0a3-1a77aef416e7', '9127f444-e74a-4d53-b048-30a6066893fc', 2, '23 Adicionado el tercer párrafo por el Artículo 2, del Decreto No. 42-2006, publicado en el Diario de Centro América el 19 de diciembre de 2006.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a0c695b-f0c1-460f-8ee1-bd0114c58f3e', '9127f444-e74a-4d53-b048-30a6066893fc', 3, 'carácter de uso público y a favor de pueblos, ciudades o municipios, sólo se harán constar en el predio sirviente, cuando no hubiere predio dominante determinado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('81694ccd-2f1f-40f8-a3ba-6459d9a6da2b', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1138', NULL, 1023, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae94ef45-456f-484d-8760-162a324327f1', '81694ccd-2f1f-40f8-a3ba-6459d9a6da2b', 1, 'El cumplimiento de las condiciones suspensivas, resolutorias o rescisorias que afecten los actos o contratos inscritos, se hará constar en el registro por una nueva inscripción a favor de quien corresponda, al ser presentada la escritura pública respectiva o la resolución judicial que lo ordene.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('198885ff-285e-4a2c-835a-87e729ae75bd', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1139', NULL, 1024, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9f80e98-6143-49b0-bde5-9587563495fb', '198885ff-285e-4a2c-835a-87e729ae75bd', 1, 'Las inscripciones de las resoluciones judiciales a que se refieren los incisos 11 y 12 del artículo 1126, expresarán la especie de incapacidad y las limitaciones declaradas en cuanto a la libre disposición de los bienes. Estas inscripciones comprenderán todos los bienes inscritos a nombre de la persona a que se refiere la resolución judicial firme.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('74f47354-ae92-4e01-9590-7ed080d0353c', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1140', NULL, 1025, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('713468ee-d142-4641-973a-611b651b85b2', '74f47354-ae92-4e01-9590-7ed080d0353c', 1, 'Si el inmueble perteneciere en común a varias personas, se hará una sola inscripción mientras no se practique la división entre los copartícipes o alguno de éstos transfiera su derecho a otro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a548364-db32-4c55-be83-8a25747a5aa6', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1141', NULL, 1026, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de9392af-af30-413e-a75a-b79b3d2c6e8b', '6a548364-db32-4c55-be83-8a25747a5aa6', 1, 'Entre dos o más inscripciones de una misma fecha y relativas a la misma finca o derecho, determinará la preferencia la anterioridad en la hora de la entrega del título en el registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63393588-8284-49c6-b200-76a5a783f7dc', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1142', NULL, 1027, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2901480e-f3a0-435b-83c2-3afcbb0e9d5c', '63393588-8284-49c6-b200-76a5a783f7dc', 1, 'Si se presentare el mismo día al Registro, despacho que contenga orden o mandamiento judicial de anotación de demanda o embargo y testimonio de escritura pública de actos o contratos que afecten a los mismos bienes o derechos, se atenderá a la hora de entrega de los documentos. Si fueren presentados a un mismo tiempo, tendrá preferencia el documento que sea anterior de acuerdo a la numeración del libro de entregas del Registro. En tales casos, el registrador hará las inscripciones y anotaciones que procedan en la forma indicada con anterioridad. Si el interesado no estuviere conforme con lo actuado, podrá proceder de conformidad con el artículo 1164 de este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d6f52af7-2b90-4503-84a1-b6d13f7f6e5d', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1143', NULL, 1028, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c7f8e618-4ffc-4e08-87fa-0bc1375babf8', 'd6f52af7-2b90-4503-84a1-b6d13f7f6e5d', 1, 'Si al hacerse una inscripción o anotación resultare del título algún otro derecho real no inscrito anteriormente, el registrador procederá a hacer acto continuo la inscripción separada y especial que corresponda a tal derecho. Esta inscripción, desde su fecha, producirá efecto contra tercero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b4743bf5-8153-413a-9064-cc92fca49db5', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1144', NULL, 1029, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce47619e-1046-4430-8de9-400792f9b5fb', 'b4743bf5-8153-413a-9064-cc92fca49db5', 1, 'Los títulos supletorios inscritos, producirán los mismos efectos del título de dominio, de conformidad con lo establecido en el artículo 637 de este Código.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9301efca-59c5-4bde-9d52-f9ccb422e7e5', 'b4743bf5-8153-413a-9064-cc92fca49db5', 2, 'ARTICULO 1145. La inscripción será nula cuando por omisión de alguna de las circunstancias que debe contener, o por estar extendida con inexactitud, hubiere inducido a error a un tercero y éste, o alguna de las partes contratantes aparezcan perjudicadas en el registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f11a099-461f-4884-af64-1e2b8e67b7ce', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1146', NULL, 1030, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a66db1f-1a14-4cb9-8db0-9d3a5b09922a', '0f11a099-461f-4884-af64-1e2b8e67b7ce', 1, 'La inscripción no convalida los actos o contratos nulos según las leyes. Esto no obstante, los actos o contratos que se ejecuten u otorguen por persona que en el registro aparezca con derecho a ello, una vez inscritos, no se invalidarán en cuanto a tercero, aunque después se anule o resuelva el derecho del otorgante, en virtud de causas que no aparezcan del mismo registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5035e90f-8ca4-40bc-b490-ca88e82a0f6f', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1147', NULL, 1031, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b47d27e3-b85c-4a9c-b1d7-a76cd8c1fd41', '5035e90f-8ca4-40bc-b490-ca88e82a0f6f', 1, 'Las acciones rescisorias o resolutorias no perjudicarán a tercero que haya inscrito su derecho, exceptuándose: 1. Las acciones rescisorias o resolutorias estipuladas expresamente por las partes, que consten en el registro; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4ca3cc0-c216-4aaa-9544-25c57222b397', '5035e90f-8ca4-40bc-b490-ca88e82a0f6f', 2, '2. La acción revocatoria de enajenación en fraude de acreedores, cuando el tercero haya sido cómplice en el fraude o el derecho lo haya adquirido a título gratuito.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92152b14-cf62-40b9-9be4-75ff1470ab20', '5035e90f-8ca4-40bc-b490-ca88e82a0f6f', 3, 'En los dos casos del inciso 2, no perjudicará a tercero la acción revocatoria que no se hubiere entablado dentro de un año, contado desde el día de la enajenación fraudulenta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78e61ed1-23ac-4d69-95ac-c2268df1a0b4', 'a0000000-0000-0000-0000-000000000001', '097b8549-eeaf-4f82-9fcf-c3d165eec923', '1148', NULL, 1032, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29832e3f-1fa5-42d0-ba84-10f983466767', '78e61ed1-23ac-4d69-95ac-c2268df1a0b4', 1, 'Únicamente perjudicará a tercero lo que aparezca inscrito o anotado en el registro. Por tercero se entiende el que no ha intervenido como parte en el acto o contrato. Los títulos inscritos o anotados surtirán efectos contra tercero y aun contra los acreedores singularmente privilegiados, desde la fecha de su entrega al Registro.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4315ba1-6fc2-4d12-978e-bc0f84502e62', '78e61ed1-23ac-4d69-95ac-c2268df1a0b4', 2, 'DE LAS ANOTACIONES Y SUS EFECTOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b56c522-8553-424c-b49d-11d4bfbfc668', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1149', NULL, 1033, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2501ad44-1b87-47d4-a850-8294575a38e6', '7b56c522-8553-424c-b49d-11d4bfbfc668', 1, 'Podrán obtener anotación de sus respectivos derechos:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32270671-d3b5-48da-b845-390c158b6bca', '7b56c522-8553-424c-b49d-11d4bfbfc668', 2, '1. El que demandare en juicio la propiedad, constitución, modificación o extinción de derechos reales sobre inmuebles u otros derechos reales sujetos a inscripción, o la cancelación o modificación de ésta; 2. El que obtuviere mandamiento judicial de embargo que se haya verificado sobre derechos reales inscritos del deudor; 3. Los legatarios y acreedores ciertos del causante en derechos reales de la herencia; 4. El que demandare la declaración o presunción de muerte, la incapacidad por interdicción, la posesión de los bienes del ausente, o que se modifique la capacidad civil de las personas en cuanto a la libre disposición de sus bienes; 5. El que presentare título cuya inscripción no puede hacerse definitivamente por faltas que sean subsanables en el término de treinta (30) días, pasados los cuales la anotación se tendrá por cancelada de hecho; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('724a4e3d-e048-45a4-afc6-8cae29201fd1', '7b56c522-8553-424c-b49d-11d4bfbfc668', 3, '6. El que en cualquier otro caso tuviere derecho a pedir anotación preventiva, conforme a lo dispuesto en este Código o en otra ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3de3e72e-81e6-44b1-961b-fa02ba154562', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1150', NULL, 1034, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4211a6a1-e621-4ae7-a84d-f918fa6819cf', '3de3e72e-81e6-44b1-961b-fa02ba154562', 1, 'Las anotaciones que procedan de orden judicial, en los casos de los incisos 1, 2, 4, y 6 del artículo anterior, las hará el registrador al recibir el despacho que deberá librar el tribunal respectivo. En el caso del inciso 3, será necesario que el derecho conste de manera fehaciente, pero si hubieren transcurrido seis meses desde la muerte del causante, la anotación sólo la hará el registrador de orden judicial.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cfe58d1e-f781-43b3-b4ab-c67671d446f8', '3de3e72e-81e6-44b1-961b-fa02ba154562', 2, 'En los demás casos, bastará la solicitud del interesado ante el registrador justificando su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('946ac1ae-e1b4-42d5-9670-6849002c1ae1', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1151', NULL, 1035, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('16c7a6d4-6c80-4277-a379-a04df5757b2f', '946ac1ae-e1b4-42d5-9670-6849002c1ae1', 1, 'Las anotaciones que procedan de providencias judiciales no se suspenderán por apelación u oposición de parte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eac8cf68-81f6-487b-873b-aa975c70d66c', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1152', NULL, 1036, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4fc14c9c-1a4d-48dc-abd8-a739861df577', 'eac8cf68-81f6-487b-873b-aa975c70d66c', 1, 'El interesado en la anotación de un inmueble que no esté inscrito en el registro, tiene derecho de hacer personalmente todas las gestiones necesarias para obtener la inscripción del inmueble de que se trate.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aa5066d5-eeef-49ed-b1c8-b05736b1d47d', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1153', NULL, 1037, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7485bffc-730c-486c-818d-bdf33cd01c8e', 'aa5066d5-eeef-49ed-b1c8-b05736b1d47d', 1, 'El legatario de género o cantidad, no podrá exigir anotación sobre bienes inmuebles o derechos reales legados a otros especialmente, y el legatario de inmuebles determinados o de crédito o pensiones asignados sobre ellos, no podrá constituir su anotación sino sobre los mismos bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c812023-8d42-4ad5-85bd-24d289a7a50d', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1154', NULL, 1038, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9cdc9d2b-2103-493b-b997-9c82a6d2ddc6', '7c812023-8d42-4ad5-85bd-24d289a7a50d', 1, 'Si alguno de los legatarios fuere persona incierta, la anotación de su legado se practicará de oficio por el registrador, al anotarse otros legados o al inscribirse la herencia a favor del heredero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6bde553d-3c15-487d-b4b7-bd0aec23033d', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1155', NULL, 1039, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03136ef0-c203-400e-a88f-986fbcc9d0ce', '6bde553d-3c15-487d-b4b7-bd0aec23033d', 1, 'El acreedor que obtenga anotación a su favor en el caso del inciso 2º, del artículo 1149, será preferido, en cuanto a los bienes anotados, solamente a los que tengan contra el mismo deudor un crédito contraído con posterioridad a dicha anotación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('99f13684-ee86-4f9a-acb1-cbb493009c0c', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1156', NULL, 1040, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3aae932b-05be-4dc0-9ef0-dbcbe9071a01', '99f13684-ee86-4f9a-acb1-cbb493009c0c', 1, 'La anotación preventiva no da preferencia a los legatarios entre sí, ni al acreedor sobre los demás de su misma clase.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc676d66-f603-407c-9eb3-a8558f29a055', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1157', NULL, 1041, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef1bc551-6850-4dbd-9c0b-9415febdbed3', 'fc676d66-f603-407c-9eb3-a8558f29a055', 1, 'La anotación a favor del acreedor a la herencia o del legatario que no lo fuera de especie, ni de rentas o derechos reales constituidos sobre un inmueble determinado, caducará al año de su fecha, y en consecuencia, deberá cancelarse de oficio por el registrador, aun cuando haya sido decretada judicialmente. Si al vencimiento del año no fuere aún exigible el legado o el crédito, se considerará subsistente la anotación hasta dos meses después del día en que puedan exigirse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e12f8f0-80bb-4c69-a88d-49ceeecb2be8', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1158', NULL, 1042, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa2e224b-83bd-4489-bd12-9d061fab8e32', '0e12f8f0-80bb-4c69-a88d-49ceeecb2be8', 1, 'Si antes de expirar el término de la anotación resultare ésta ineficaz para garantizar el crédito o legado, por razón de las cargas o condiciones especiales de los bienes anotados, podrá pedir el acreedor a la herencia o el legatario, que se anoten otros bienes, si los hubiere susceptibles de tal gravamen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a9224eb-c6d5-4344-a4b8-6c318974ad1d', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1159', NULL, 1043, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9081f508-8e31-47c7-abd3-3fa6be3f0cb1', '4a9224eb-c6d5-4344-a4b8-6c318974ad1d', 1, 'El legatario de rentas o pensiones podrá pedir, en cualquier tiempo, que la anotación hecha a su favor se convierta en inscripción hipotecaria, si el testador hubiere consignado las porciones sobre inmuebles determinados de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4537f00e-f38b-42dd-a1f1-b79df021e30d', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1160', NULL, 1044, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a9e2ecd-a0d4-4b6d-842f-43470b2a1e52', '4537f00e-f38b-42dd-a1f1-b79df021e30d', 1, 'Si el legatario hubiere anotado su derecho, podrá pedir, en cualquier tiempo, la inscripción hipotecaria de los bienes inmuebles de la herencia gravados por el testador, que existan en poder del heredero o legatario obligado a dar la pensión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d471116-99e9-429a-9fc1-a15a2e5017cf', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1161', NULL, 1045, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc418864-4ed3-4070-baad-8ee586e60d6c', '2d471116-99e9-429a-9fc1-a15a2e5017cf', 1, 'Cuando se presente al Registro de la Propiedad un testamento en que se constituya patrimonio familiar, el registrador hará, de oficio, anotación provisional sobre los bienes afectados por el patrimonio, la que se cancelará al hacerse la inscripción definitiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1e45ed58-eaad-4c83-8cf8-06143116c132', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1162', NULL, 1046, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f8320ccd-667b-49b0-b33d-8bd3665516eb', '1e45ed58-eaad-4c83-8cf8-06143116c132', 1, 'Cuando la anotación preventiva a que se refiere el inciso 5º del Artículo 1149 de este Código, se convierta en inscripción definitiva de un derecho, surtirá sus efectos desde la fecha de tal anotación y en esos supuestos el registrador, a solicitud escrita de quien la hubiere obtenido, cancelará las inscripciones de fecha posterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5cf6a2f6-97a1-47d8-b2b4-1d1e30630962', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1163', NULL, 1047, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32ee1d03-da10-4b96-8a27-9b4ece332065', '5cf6a2f6-97a1-47d8-b2b4-1d1e30630962', 1, 'Los bienes inmuebles o derechos reales anotados podrán enajenarse o gravarse, pero sin perjuicio del derecho de aquel a cuyo favor se haya hecho la anotación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9d763b91-5cee-4e7b-8c12-11de7e5eb8d6', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1164', NULL, 1048, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f5d6fcf-0f36-4a52-9976-eff8c45433c6', '9d763b91-5cee-4e7b-8c12-11de7e5eb8d6', 1, 'El interesado que no estuviere conforme con la denegatoria, suspensión de la anotación, cancelación o inscripción de los documentos presentados al Registro, podrá ocursar en la vía incidental al registrador ante Juez de Primera Instancia del ramo civil de la circunscripción departamental donde tenga su sede el Registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5588971d-783e-4bba-9a15-456559774f6b', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1165', NULL, 1049, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c18be64e-b79e-4977-99d5-71ef9a7d8170', '5588971d-783e-4bba-9a15-456559774f6b', 1, 'La anotación preventiva pierde sus efectos a los treinta días de efectuada o al vencimiento de la prórroga que se hubiere otorgado y, será cancelada de oficio por el registrador, si durante ese plazo no se hubiere presentado el documento que subsane la omisión. También deberá ser cancelada a solicitud escrita de quien la obtuvo, del propietario del bien o derecho anotado o mediante la presentación del despacho judicial que así lo disponga. En todo caso, el registrador pondrá razón al margen del libro correspondiente de toda cancelación o prórroga de anotación preventiva que inscriba.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f9c0b95f-71a6-4158-9a96-0a0d9bb5d07e', 'a0000000-0000-0000-0000-000000000001', 'ca6a14b0-cfdb-42a4-9aee-d21bd995eb5f', '1166', NULL, 1050, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('da48eb8d-aebd-41d7-895b-a671a1231cb7', 'f9c0b95f-71a6-4158-9a96-0a0d9bb5d07e', 1, 'Toda anotación expresará: el inmueble o derecho real a que se contraiga; el juez que la hubiere decretado, si fuere el caso; las personas a quienes');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('626c6739-bbcb-4b1e-89c2-de0605cc7c66', 'f9c0b95f-71a6-4158-9a96-0a0d9bb5d07e', 2, 'afecte, el título de su procedencia, el importe de las obligaciones si pudieren determinarse; la fecha y hora de la entrega del documento en el Registro. La falta de alguno de estos requisitos hará ineficaz la anotación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ebb82918-9bc4-4934-aea7-83f1c019542a', 'f9c0b95f-71a6-4158-9a96-0a0d9bb5d07e', 3, 'DE LAS CANCELACIONES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d134200d-2b9f-4945-b6c3-0a05fab9f610', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1167', NULL, 1051, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48d41fb1-58dd-4271-8b62-92145eff07ce', 'd134200d-2b9f-4945-b6c3-0a05fab9f610', 1, 'Las inscripciones se cancelarán en virtud del documento en que conste haberse extinguido legalmente los derechos u obligaciones inscritos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46a4f3c9-e116-4e3f-b35e-a827d9513a75', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1168', 'La cancelación podrá hacerse parcial o totalmente', 1052, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46c65fdb-dac2-450f-83f6-2a6f7cbfb381', '46a4f3c9-e116-4e3f-b35e-a827d9513a75', 1, 'En el primer caso deberá indicarse con la claridad, la parte respecto de la cual se hace la cancelación');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54a7df28-850c-4ff2-9478-1c0110185311', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1169', NULL, 1053, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bcc3ab1f-fe0f-45a1-94b4-5b95ea243357', '54a7df28-850c-4ff2-9478-1c0110185311', 1, 'Podrá pedirse la cancelación total de las inscripciones y anotaciones: 1. Cuando se extingue por completo el inmueble objeto de la inscripción o el derecho real inscrito;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('959021df-93eb-49bd-b197-0c9e0becff4c', '54a7df28-850c-4ff2-9478-1c0110185311', 2, '2. Cuando se declare la nulidad del documento en cuya virtud se haya hecho la inscripción; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5da34ff-9d23-4f5f-907c-a756e4fc273b', '54a7df28-850c-4ff2-9478-1c0110185311', 3, '3. Cuando se declare la nulidad de la inscripción a consecuencia de lo dispuesto en el artículo 1145.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7fffc5f0-cbb7-4ca8-83e3-9b432e209c42', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1170', NULL, 1054, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e312a75-3da3-4b6c-9395-7469182368b3', '7fffc5f0-cbb7-4ca8-83e3-9b432e209c42', 1, 'El registrador, a solicitud escrita de parte interesada, cancelará: 1.   Las inscripciones hipotecadas con plazo inscrito, cuando hubieren transcurrido diez años después de haber vencido éste o su prórroga y, por el transcurso de dos años, los demás derechos reales sobre inmuebles.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c0543df6-d3aa-4400-99e3-8304b961ed02', '7fffc5f0-cbb7-4ca8-83e3-9b432e209c42', 2, '2.   Las inscripciones de derechos sobre bienes muebles identificables, cuando hubieren pasado tres años desde el vencimiento del plazo o de la prórroga inscritos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a8c64cc2-db4d-42a5-90d8-637efa40b9d1', '7fffc5f0-cbb7-4ca8-83e3-9b432e209c42', 3, '3.   Las anotaciones de demanda y de embargo después de cinco años de su fecha; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('837071af-358f-4abb-b60d-cc58316180cf', '7fffc5f0-cbb7-4ca8-83e3-9b432e209c42', 4, '4.   La prenda agraria después de dos años del vencimiento del plazo fijado en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0578e92c-7e1e-4ea3-9b5a-49eaa7416fc3', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1171', NULL, 1055, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('550e8525-c260-49bc-8b16-a22a397354f6', '0578e92c-7e1e-4ea3-9b5a-49eaa7416fc3', 1, 'Además de lo previsto en el inciso 3º del artículo 1170 de este Código, las inscripciones o anotaciones decretadas judicialmente en los casos establecidos en los incisos 1, 2, 4 y 6 del artículo 1149, se cancelarán en cualquier tiempo a la presentación del despacho que contenga la resolución judicial que así lo disponga. En los demás casos del citado artículo, podrá hacerse la cancelación, al');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1424fd15-9be0-4a67-850a-beee84e1e0ce', '0578e92c-7e1e-4ea3-9b5a-49eaa7416fc3', 2, 'presentarse testimonio de escritura pública en la cual exprese su consentimiento la persona a cuyo favor se hubiere hecho la inscripción o anotación, sus causahabientes o representantes legítimos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('32218e06-a75d-4f4f-91e2-8d304ab84eb3', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1172', NULL, 1056, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b19a48c-9485-47e2-a552-d72dec0703b9', '32218e06-a75d-4f4f-91e2-8d304ab84eb3', 1, 'La anotación se cancelará, no sólo cuando se extinga el derecho anotado, sino también cuando en escritura pública se convenga, o en providencia judicial se disponga convertirla en definitiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('643376b9-a9bf-40bd-b188-1e9305883e2c', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1173', NULL, 1057, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c035714a-90fe-4454-acc7-c82ef1194cfe', '643376b9-a9bf-40bd-b188-1e9305883e2c', 1, 'Cuando se presente al registro un título traslativo de dominio o derecho real, otorgado en virtud de remate por ejecución judicial, se cancelará de oficio todo embargo, anotación o inscripción posterior a la inscripción o anotación del derecho que hubiere motivado el remate. Asimismo, se cancelará la anotación de la demanda de nulidad o falsedad del título que haya dado lugar a la ejecución y al remate.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('98ad1be8-4129-4304-8f90-d1a1af645a0d', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1174', NULL, 1058, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b9dd6645-de98-4519-85d8-ec3d1214e720', '98ad1be8-4129-4304-8f90-d1a1af645a0d', 1, 'Toda cancelación contendrá los requisitos siguientes: 1. La clase de documento en cuya virtud se haga la cancelación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6cfba03a-7d41-46b9-ab02-3c8de08081ed', '98ad1be8-4129-4304-8f90-d1a1af645a0d', 2, '2. La fecha del documento y la de entrega en el registro;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff836f10-0b0b-41c1-8e49-e9d643925bb3', '98ad1be8-4129-4304-8f90-d1a1af645a0d', 3, '3. La designación del juez que hubiere expedido el documento o del notario ante quien se haya otorgado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0d1b775c-db1f-48e2-a878-f9104d043989', '98ad1be8-4129-4304-8f90-d1a1af645a0d', 4, '4. Los nombres de los interesados en la cancelación; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('182b018a-0713-4a2b-bd09-b2744d6f366b', '98ad1be8-4129-4304-8f90-d1a1af645a0d', 5, '5. La inscripción o anotación que se cancele.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8d84ea00-4359-405d-8e70-99f180386736', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1175', NULL, 1059, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('462fd099-b6af-4f8e-a1e2-e9cbbc6c58cf', '8d84ea00-4359-405d-8e70-99f180386736', 1, 'El registrador, bajo su responsabilidad, suspenderá o denegará la cancelación conforme a lo dispuesto para las inscripciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17b838f5-3fba-4ca4-9a24-2c0da0959217', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1176', NULL, 1060, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('167c15d3-91ca-4586-92cb-27c4335b1c6c', '17b838f5-3fba-4ca4-9a24-2c0da0959217', 1, 'Será nula la cancelación en perjuicio de tercero: 1. Cuando no dé a conocer claramente la inscripción cancelada;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88a6f818-7d2a-4a1c-8840-07d8f614690b', '17b838f5-3fba-4ca4-9a24-2c0da0959217', 2, '2. Cuando en la cancelación parcial no se de a conocer claramente la parte del inmueble que haya desaparecido, o la parte de la obligación que se extinga y la que subsista; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77bb1cb7-22ea-41d5-a05d-94914fa45147', '17b838f5-3fba-4ca4-9a24-2c0da0959217', 3, '3. Cuando la cancelación no tenga la fecha de la entrega en el registro, del instrumento en que se haya convenido por las partes u ordenado por el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f137e476-a2e5-4746-b4b2-75313a3d3add', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1177', NULL, 1061, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6670ad1b-7f14-494c-8087-8278a4d2df0f', 'f137e476-a2e5-4746-b4b2-75313a3d3add', 1, 'Cuando una cancelación se declare nula en virtud de causas que no aparezcan en el asiento, tal nulidad no podrá perjudicar a tercero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7192e1a6-04a8-4249-b3e1-6697d66879c8', 'a0000000-0000-0000-0000-000000000001', 'f2ef2dac-b045-4f83-8891-ad5c60d1ab60', '1178', NULL, 1062, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfbfe733-570d-44c9-857e-676839c91847', '7192e1a6-04a8-4249-b3e1-6697d66879c8', 1, 'Cuando una finca tuviere quince o más inscripciones de dominio o hipotecarias, el registrador las cancelará y abrirá nueva inscripción con los datos que de las inscripciones resulten, transcribiendo a ella toda inscripción o anotación que estuviere vigente. El registrador podrá exigir de los interesados los demás datos que juzgue necesarios.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28607ff0-fad3-434d-aec5-3ed1c9b23668', '7192e1a6-04a8-4249-b3e1-6697d66879c8', 2, 'CERTIFICACIONES DE REGISTRO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f4b3abe7-3da4-4b09-b57d-fc7dcff63584', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1179', NULL, 1063, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7c29be4d-5b32-4564-9fcd-ff3304bdd470', 'f4b3abe7-3da4-4b09-b57d-fc7dcff63584', 1, 'La liberación o gravamen de los bienes inmuebles o derechos reales sobre los mismos, sólo podrá acreditarse por la certificación del registro en que se haga constar el estado de dichos bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cb6578f8-9aeb-4d0f-b2a5-ab058b4443a0', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1180', NULL, 1064, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('26e11af8-009a-41e1-aacd-0a7beedc8d75', 'cb6578f8-9aeb-4d0f-b2a5-ab058b4443a0', 1, 'Los registradores expedirán las certificaciones que se les pidan, relativas a los bienes inscritos en el Registro. Dichas certificaciones se solicitarán por escrito y se extenderán sin citación alguna, debiendo pagar el solicitante los honorarios fijados en el Arancel.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('138c46f6-4ef9-4b3f-8ffe-d7c2a310529a', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1181', NULL, 1065, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e355c8f-bcf0-4e5a-9402-49bb86a5bf6b', '138c46f6-4ef9-4b3f-8ffe-d7c2a310529a', 1, 'Cuando se expidiere certificación de una inscripción cancelada, el registrador insertará en todo caso a continuación de ella, copia literal del asiento de cancelación. De la misma manera, el registrador hará mérito en la certificación, de cualquier título que estuviere presentado solamente, pero que tenga relación con el asiento certificado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('34baaed8-9aac-4622-9e5d-68ae604446f3', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1182', NULL, 1066, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4aee7d30-54de-4c41-9ab2-5be6cac84028', '34baaed8-9aac-4622-9e5d-68ae604446f3', 1, 'Cuando el registrador dudare si está o no subsistente una inscripción, por dudar también de la validez o eficacia de la cancelación que a ella se refiere, insertará a la letra ambos asientos en la certificación, expresando que lo hace así por haber dudado si dicha cancelación reúne las circunstancias necesarias para producir todos sus efectos legales, debiendo expresar también los motivos de la duda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3270fc5a-d405-45b8-8091-490746dd585f', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1183.24', NULL, 1067, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1f5de8fb-55ae-4828-b639-ff6a5eef8274', '3270fc5a-d405-45b8-8091-490746dd585f', 1, 'Las certificaciones se extenderán por medio de fotocopias, fotostáticas, transcripción mecánica o por cualquier medio de reproducción físico informático, magnético o electrónico y llevarán la firma y sello del registrador que la extiende y sello del Registro, salvo lo dispuesto en el párrafo siguiente. La firma deberá constar por cualquiera de los medios y con los efectos jurídicos que establece el numeral 8o. del artículo 1131. Las certificaciones pueden ser sustituidas por copias fotográficas, legalizadas por el registrador.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b43b9d5c-ab43-4f9c-8e77-3fb45120ab9c', '3270fc5a-d405-45b8-8091-490746dd585f', 2, '24 Reformado como aparece en el texto por el Artículo 3, del Decreto No. 42-2006, publicado el 19 de diciembre de 2006.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('40e00077-762a-4e5e-8e2d-ef020c70cffa', 'a0000000-0000-0000-0000-000000000001', '6f6734be-d5fd-4403-a1d0-327373bca2ee', '1184', NULL, 1068, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b6a4e52c-8386-44eb-a523-3eacdd13904b', '40e00077-762a-4e5e-8e2d-ef020c70cffa', 1, 'Cuando las certificaciones que expida el registrador no fueren conformes con los asientos a que se refieren, se estará a lo que de éstos resulte, salvo la acción del perjudicado por aquéllas para exigir la indemnización correspondiente del registrador que hubiere cometido la falta.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e6f77a7-9d81-421e-9fda-22d8d8b5caca', '40e00077-762a-4e5e-8e2d-ef020c70cffa', 2, 'DE LAS INSCRIPCIONES ESPECIALES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45c5b5c4-7e50-4ad1-9f2b-f543a3dac3e5', '40e00077-762a-4e5e-8e2d-ef020c70cffa', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1d6b8593-0f9b-42c5-a926-5b3eae6ccf9f', 'a0000000-0000-0000-0000-000000000001', 'ed7c6c23-fea0-4206-b754-94ae2685320b', '1185', NULL, 1069, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0510f981-c363-42a4-946d-d8bb03cf9aeb', '1d6b8593-0f9b-42c5-a926-5b3eae6ccf9f', 1, 'En el registro de la Propiedad se llevarán por separado los registros siguientes: de prenda agraria, de testamentos y donaciones por causa de muerte, de propiedad horizontal, de fábricas inmovilizadas, de buques y aeronaves, canales, muelles, ferrocarriles y otras obras públicas de índole semejante, de minas e hidrocarburos de muebles identificables y otros que establezcan leyes especiales. También se llevarán los registros de la prenda común, de la prenda ganadera, industrial y comercial, cuyas modalidades serán objeto de disposiciones especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4c2d1ca8-9ad7-48a8-9338-ce6b49027f0a', 'a0000000-0000-0000-0000-000000000001', 'ed7c6c23-fea0-4206-b754-94ae2685320b', '1186', NULL, 1070, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b1e050f0-9b3e-4c09-8ca6-b1afc778e99e', '4c2d1ca8-9ad7-48a8-9338-ce6b49027f0a', 1, 'Sin perjuicio de hacerse la inscripción en los libros especiales cuando las operaciones se refieran a las expresadas en los incisos 5, 6, 10, 11 y 12 del artículo 1125, se anotarán los inmuebles que afecten tales inscripciones.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c6622a13-0d53-4243-8c8c-591cdf284a22', '4c2d1ca8-9ad7-48a8-9338-ce6b49027f0a', 2, 'ARTICULO 1187. Salvo disposiciones especiales, las reglas establecidas para la inscripción en general, se observarán en las inscripciones de que trata este título.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba8bb583-c412-4aad-b08d-a07dcf6ca939', '4c2d1ca8-9ad7-48a8-9338-ce6b49027f0a', 3, 'REGISTRO DE LA PRENDA AGRARIA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('84520a82-0505-4f71-9b26-0c111f2c8edb', 'a0000000-0000-0000-0000-000000000001', '8139a149-ab14-4057-8e33-e0ad6b8f8445', '1188', NULL, 1071, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8781b5f6-024c-4c80-b576-926eb10c481c', '84520a82-0505-4f71-9b26-0c111f2c8edb', 1, 'La partida de inscripción de la prenda agraria contendrá: 1. El nombre de inscripción del fundo a que la prenda pertenezca;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a63b7be5-ff7e-4556-8698-7c88cc5d713b', '84520a82-0505-4f71-9b26-0c111f2c8edb', 2, '2. El nombre de los contratantes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b2b5ac7-e8e3-41d9-9f55-ba07cd254167', '84520a82-0505-4f71-9b26-0c111f2c8edb', 3, '3. El lugar y la fecha del contrato;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('016db9b4-0aba-4f35-b0a6-05023cd1906e', '84520a82-0505-4f71-9b26-0c111f2c8edb', 4, '4. La suma recibida en préstamo y la forma en que deberá devolverse;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c291382-1a46-42c8-a9a1-8f88a44f6182', '84520a82-0505-4f71-9b26-0c111f2c8edb', 5, '5. El nombre del notario que autorizó el contrato;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5917df33-d8f8-4894-bb9e-9ae24b440a0a', '84520a82-0505-4f71-9b26-0c111f2c8edb', 6, '6. Los intereses estipulados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14ece712-2f68-4b49-8d37-232aec696a12', '84520a82-0505-4f71-9b26-0c111f2c8edb', 7, '7. El plazo de la obligación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12618309-4143-471c-8b43-37d65450c9f9', '84520a82-0505-4f71-9b26-0c111f2c8edb', 8, '8. Las cosas dadas en prenda, con especificación de todas las circunstancias que sirvan para identificarlas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d060bcf4-222f-4853-b9fe-b04088c4f811', '84520a82-0505-4f71-9b26-0c111f2c8edb', 9, '9. Las condiciones especiales que hayan pactado los contratantes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27e3680c-51ed-4656-a859-b95a7d1d7695', '84520a82-0505-4f71-9b26-0c111f2c8edb', 10, '10. Los detalles que se requieran para la claridad y precisión del asiento.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3241c751-bcba-41c1-98f9-1e9c206f911c', '84520a82-0505-4f71-9b26-0c111f2c8edb', 11, 'ARTICULO 1189. Cuando las cosas dadas en prenda se encuentren en departamentos que correspondan a distintas oficinas del Registro, el documento respectivo deberá ser presentado e inscrito en todas ellas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dea6b973-b8c7-4e8f-8e9e-8b0a8b5d8c29', 'a0000000-0000-0000-0000-000000000001', '8139a149-ab14-4057-8e33-e0ad6b8f8445', '1190', NULL, 1072, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4f4723f0-8259-4c7b-aac8-b590c7889d98', 'dea6b973-b8c7-4e8f-8e9e-8b0a8b5d8c29', 1, 'Tan pronto como se registre un contrato de prenda sin tradición, se anotará al margen de la inscripción de dominio del fundo de que legalmente formen parte las cosas pignoradas. Esta anotación se cancelará al mismo tiempo que la inscripción de prenda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('04d69616-308f-40ec-9607-ba93d59cecd1', 'a0000000-0000-0000-0000-000000000001', '8139a149-ab14-4057-8e33-e0ad6b8f8445', '1191', NULL, 1073, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4347b267-ce37-426f-8045-eb975938574d', '04d69616-308f-40ec-9607-ba93d59cecd1', 1, 'En los casos en que para la cancelación o rescisión de la prenda, no mediare instrumento público o sentencia firme, bastará la solicitud escrita del acreedor y deudor ante el registrador, quien levantará el acta respectiva y hará las operaciones correspondientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('788620ce-4870-4b95-bffa-cc53bfba5715', 'a0000000-0000-0000-0000-000000000001', '8139a149-ab14-4057-8e33-e0ad6b8f8445', '1192', NULL, 1074, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('798762b7-b6c4-4a65-b92d-ccea167a15f8', '788620ce-4870-4b95-bffa-cc53bfba5715', 1, 'Cuando ocurriere la venta judicial de bienes pignorados, el registrador cancelará tanto la inscripción prendaria, como la anotación en el inmueble o mueble que la soporte, a la presentación del testimonio de la escritura pública de adjudicación en pago otorgada judicialmente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1026db84-32be-491f-b3b3-7c648b843862', '788620ce-4870-4b95-bffa-cc53bfba5715', 2, 'REGISTRO DE TESTAMENTOS Y DE DONACIONES POR CAUSA DE MUERTE');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9aa73b38-d7db-4355-b941-f017db39dca6', 'a0000000-0000-0000-0000-000000000001', '89e50efd-4122-423a-8773-23ee8060b755', '1193', NULL, 1075, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad0b6cee-48d7-425b-a682-352c748737a6', '9aa73b38-d7db-4355-b941-f017db39dca6', 1, 'En el registro de testamentos y donaciones por causa de muerte, se hará constar: 1. En el libro de testamentos abiertos y donaciones por causa de muerte: el nombre del testador o donante con todas las identificaciones que aparecen en el testamento o donación; el lugar, fecha y hora; el folio o folios que correspondan al protocolo; el número y registro del papel sellado en que estuviere extendido el original; y la constancia de haber firmado el testador o donante, o el nombre de la persona que firmó a su ruego;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('073a9705-3d11-456b-8c87-7348037b16fa', '9aa73b38-d7db-4355-b941-f017db39dca6', 2, '2. En el libro de testamento cerrados: copia íntegra del acta que protege el testamento;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7ba22781-dd5b-4e39-bc0d-6ebf0f2ac168', '9aa73b38-d7db-4355-b941-f017db39dca6', 3, '3. En el libro de testamentos especiales: los mismos datos que contiene el inciso 1, de este artículo, en lo que sea aplicable; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bad3af6c-d962-4a73-b6cc-dc74c710752d', '9aa73b38-d7db-4355-b941-f017db39dca6', 4, '4. La ampliación, revocación, nulidad o insubsistencia de testamentos o donaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('582ba1bd-f862-462d-a1d3-63df91de3485', 'a0000000-0000-0000-0000-000000000001', '89e50efd-4122-423a-8773-23ee8060b755', '1194', NULL, 1076, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20945f23-cdb3-4935-a49e-629729b4c8ed', '582ba1bd-f862-462d-a1d3-63df91de3485', 1, 'Muerto el testador se presentará el testimonio del testamento abierto con duplicado y certificación del acta de defunción para que sea anotado en el libro de asientos y razonado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e3d76c0-8f7b-4924-8212-0fb0ad6b2779', '582ba1bd-f862-462d-a1d3-63df91de3485', 2, 'REGISTRO DE LA PROPIEDAD HORIZONTAL');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c89b79db-bc8f-41e9-ad70-9c26aa3dc825', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1195', NULL, 1077, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a72f41b-110e-4011-a1af-0b3e6544ec4f', 'c89b79db-bc8f-41e9-ad70-9c26aa3dc825', 1, 'La propiedad horizontal deberá inscribirse formando tantas fincas separadas como pisos o unidades tenga la edificación. El testimonio de la escritura que origine la primera inscripción del edificio, deberá acompañarse de una copia de los planos del mismo y los planos de cada unidad o piso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('caecc512-b81a-46cd-8da3-5284196f515a', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1196', NULL, 1078, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b965e41a-295e-4de9-92ca-4e5cea3f77dd', 'caecc512-b81a-46cd-8da3-5284196f515a', 1, 'Los planos deben detallar la situación, dimensiones y colindancias del terreno, así como una descripción del edificio, incluyendo sus servicios de agua, electricidad y cualesquiera otros de que goce; y descripción de cada piso o unidad, su situación, colindancias y datos que sean necesarios para identificarlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2139b873-0659-4c39-8410-9f4f626450be', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1197', NULL, 1079, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5f7cd2fc-2df7-4731-a981-82d641e6baa9', '2139b873-0659-4c39-8410-9f4f626450be', 1, 'La inscripción del edificio, como finca matriz, se debe practicar en la finca con cuyo número aparezca inscrito el terreno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d7483342-dc0f-4a98-8cb5-dd1d8287d75d', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1198', NULL, 1080, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cff2c692-ba41-4a33-b2cd-4499780fe68b', 'd7483342-dc0f-4a98-8cb5-dd1d8287d75d', 1, 'Cada piso, departamento o habitación que reúna los requisitos que establece este Código, se debe inscribir como finca independiente de la finca matriz, y cada una de las nuevas fincas debe tener notas marginales de mutua referencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4614d58e-a2e9-4ac1-9c07-bb6bd633c7a6', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1199', NULL, 1081, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f10d0e78-4ee3-47ff-a87d-1d7a3f8791e8', '4614d58e-a2e9-4ac1-9c07-bb6bd633c7a6', 1, 'La inscripción del edificio en la finca matriz ha de expresar las circunstancias que para toda inscripción señala el artículo 1131, en cuanto fueren aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c157dd13-43ba-481d-8645-ec47eb98c53f', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1200', NULL, 1082, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b71187d-dbc4-4d81-b148-c6ea6f54f9b9', 'c157dd13-43ba-481d-8645-ec47eb98c53f', 1, 'En la inscripción deben expresarse los elementos comunes a favor del o de los que resulten ser titular o titulares del edificio total; y en su caso, de los que correspondan a cada piso, departamento o habitación, en la proporción respectiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('528ee1fa-2f63-4ac6-9a0f-938e3e2db315', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1201', NULL, 1083, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cfddedef-a074-4774-8cb0-011615a52963', '528ee1fa-2f63-4ac6-9a0f-938e3e2db315', 1, 'Al inscribirse un piso, departamento o habitación, se deben expresar las mismas circunstancias que indican los artículos anteriores. En cuanto a la parte que en los elementos comunes generales o limitados, en su caso, corresponde a los titulares, el registrador hará una breve referencia al asiento de la finca matriz en que aparezcan inscritos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6c9a68e-77a5-4322-88ea-447ba3f08489', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1202', NULL, 1084, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e2dbf63-de95-45b6-a33e-e2c664e86b5e', 'b6c9a68e-77a5-4322-88ea-447ba3f08489', 1, 'Para que cada piso, departamento o habitación, pueda inscribirse independientemente de la finca matriz, es indispensable que se encuentre terminada su construcción, lo que deberá acreditarse mediante constancia extendida por la respectiva municipalidad o por el profesional director de la obra, la que el notario insertará en el instrumento público que corresponda.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88d94732-e0ba-4080-b9e4-ab4d1a4353c7', 'b6c9a68e-77a5-4322-88ea-447ba3f08489', 2, 'Cuando la construcción no estuviere concluida, la inscripción tendrá carácter provisional y se convertirá en definitiva a solicitud del interesado, acompañando la constancia a que se refiere el párrafo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('18369822-d512-49bc-b91c-fbd25edb4fb9', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1203', NULL, 1085, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de04a679-5208-4975-92d3-18df000456f0', '18369822-d512-49bc-b91c-fbd25edb4fb9', 1, 'La parte proporcional o porcentaje en los elementos comunes que corresponda al titular de cada piso o unidad, se entiende transmitida o gravada conjuntamente con éste, sin necesidad de inscribir dicha transmisión o gravamen de la parte proporcional de esos elementos en la finca matriz.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bae7cb2b-6f94-43fd-8611-52ff6290974e', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1204', NULL, 1086, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('abca3002-f51d-4950-9437-172927e5f4ae', 'bae7cb2b-6f94-43fd-8611-52ff6290974e', 1, 'La adición de nuevos pisos o la adquisición de nuevas porciones de terreno colindantes, efectuadas por la totalidad de titulares para que formen parte de los elementos comunes del edificio, se ha de inscribir en la finca matriz, con la cual deben unificarse las nuevas parcelas adquiridas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('79154111-ea97-4e37-b77b-9dfc503f33e5', 'a0000000-0000-0000-0000-000000000001', '5a3dc314-66cf-4f9c-9c9a-f99e8e4453b3', '1205', NULL, 1087, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e8d7595-2f50-4ead-8aec-7fc266756b20', '79154111-ea97-4e37-b77b-9dfc503f33e5', 1, 'La cancelación total o parcial de gravámenes que afecten el edificio en general y las anotaciones preventivas que hagan referencia expresa al edificio o a los elementos comunes del mismo en su totalidad, se deben practicar en la finca matriz, dejando anotación marginal en las fincas filiales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f8611f6-fac9-4df8-9286-e32976d35e16', '79154111-ea97-4e37-b77b-9dfc503f33e5', 2, 'OTROS REGISTROS ESPECIALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3b3d419a-953a-42c4-bfc8-91487f4e6d55', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1206', NULL, 1088, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ad41b71-938a-4d57-ae39-3d1e2eaf3b82', '3b3d419a-953a-42c4-bfc8-91487f4e6d55', 1, 'Las inscripciones de que trata este capítulo deberán hacerse con los requisitos que se exigen para toda clase de inscripciones, en cuanto fueren aplicables, y se anotarán al margen de la inscripción de cada uno de los inmuebles que afecten.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2fce228c-b953-4be7-a8e1-f3c2abddf489', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1207', NULL, 1089, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d846540e-a9cf-4668-b07c-230ea831e772', '2fce228c-b953-4be7-a8e1-f3c2abddf489', 1, 'Los buques y naves aéreas, canales, muelles, ferrocarriles, y otras obras públicas de índole semejante, y los derechos reales que los afecten, deberán inscribirse en el registro central de la propiedad en los libros destinados a tales bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fd230aeb-31d4-42ce-bfd9-85ce66422de3', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1208', NULL, 1090, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b07cd98-911a-421e-a253-e297dfd39ee6', 'fd230aeb-31d4-42ce-bfd9-85ce66422de3', 1, 'La inscripción de una de las obras mencionadas la hará el registrador a la presentación de la escritura constitutiva de la concesión o contrato, debidamente aprobado. La primera inscripción deberá expresar la naturaleza y descripción de la obra y todo lo que ella comprenda como necesario para su existencia o explotación, de conformidad con los términos y condiciones de la concesión legalmente aprobada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2e930b7d-33aa-4ae8-8ebe-f64e6a06ce1f', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1209', NULL, 1091, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e30b31a3-2cff-4f99-b594-87bb03a7e120', '2e930b7d-33aa-4ae8-8ebe-f64e6a06ce1f', 1, 'Si la inscripción se hace durante la construcción de la obra pública, podrá adicionarse o rectificarse al concluir la obra o terminar cada una de las secciones, presentando al efecto, certificación auténtica en que conste que el funcionario competente se da por recibido de la obra o de la sección que se pone al servicio público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c920ba1-9d07-4c60-9acd-5ef1ad2c5012', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1210', NULL, 1092, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b118530-24c8-4b35-80f2-81ed81be6c8e', '1c920ba1-9d07-4c60-9acd-5ef1ad2c5012', 1, 'En cuanto el concesionario adquiera en forma legal, el terreno para la construcción de ferrocarril, canal, muelle u obras de la misma índole, se inscribirán los títulos de la adquisición, en la forma prevenida en el artículo 1208.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('530b771a-7f55-4471-ba06-e6549fc9be27', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1211', NULL, 1093, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('59e8a8e7-1bdd-4860-b07c-5f04d0fe6d7a', '530b771a-7f55-4471-ba06-e6549fc9be27', 1, 'Las estaciones, almacenes, presas, puentes, acueductos y demás obras que constituyan parte integrante de la vía o canal, como necesarias para su existencia o explotación, no requieren inscripción separada, sino que se incluirán en la inscripción general de la obra; pero, las fincas rústicas o urbanas que adquiera la compañía concesionaria y que estén separadas de la vía o canal, deben inscribirse separadamente con las condiciones y requisitos que exige la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e0dbada1-186c-4ebb-815c-b0829d61ffd7', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1212', NULL, 1094, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4729c7b3-434b-4d1b-8c35-90f314e894fa', 'e0dbada1-186c-4ebb-815c-b0829d61ffd7', 1, 'El dominio del Estado sobre los hidrocarburos naturales en sus diferentes condiciones, los carbones minerales y las sustancias minerales metálicas que se encuentran en el subsuelo, es inalienable e imprescriptible y deberá inscribirse con tales requisitos en un libro especial, formando un inmueble separado del fundo en cuyo subsuelo se encuentre ubicado el yacimiento o la mina respectiva. En la inscripción de dicho fundo se anotará la desmembración del dominio del subsuelo y en la nueva finca que se forme a favor del Estado, se expresarán el número, folio y libro de la finca en cuyo subsuelo se formó el nuevo inmueble.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3bf3c3e5-3c79-4ebe-b102-30fa589ff034', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1213', NULL, 1095, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eba1fe08-e6e5-49fd-9e3f-3978c686b517', '3bf3c3e5-3c79-4ebe-b102-30fa589ff034', 1, 'El dominio útil de los hidrocarburos, carbones minerales y minas, se inscribirá en el mismo libro, a favor de los concesionarios, con las condiciones establecidas en el respectivo contrato que se hará constar en escritura pública y asimismo se inscribirán las transferencias de dominio y derechos reales que los afecten, que se regularán por las prescripciones comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('18004652-afbc-4e1c-bc24-1db130801793', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1214', NULL, 1096, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b485c80b-7b14-4b25-a2be-dc0779e47759', '18004652-afbc-4e1c-bc24-1db130801793', 1, 'La inscripción de un bien mueble identificable se hará en libro especial a la presentación de la escritura o documento legalizado o copia legalizada de los mismos en que conste la transferencia de dominio y con los requisitos que además establezca el reglamento del Registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f7d67fb8-4393-4828-bfda-56c31fc631ab', 'a0000000-0000-0000-0000-000000000001', '7bdfccf2-3149-4837-9003-26cc703ade42', '1215', NULL, 1097, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba0ba3d8-026a-4f09-8e59-8a8602a5c4c7', 'f7d67fb8-4393-4828-bfda-56c31fc631ab', 1, 'La primera inscripción de un buque o nave particular será la de propiedad del mismo. Para extender esta inscripción deberá presentarse la escritura de propiedad y copia certificada de la matrícula del buque expedida en la forma legal. El cambio de matrícula se hará constar en nueva inscripción. La primera inscripción de propiedad del buque, contendrá la descripción del mismo, expresando las circunstancias que sirvan para identificarlo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0137bf50-4e39-4936-ba0b-3d02033dc3da', 'f7d67fb8-4393-4828-bfda-56c31fc631ab', 2, 'DE LOS REGISTROS Y DE LOS REGISTRADORES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96e77ddd-866b-4803-83b9-7705f8f96083', 'f7d67fb8-4393-4828-bfda-56c31fc631ab', 3, 'ESTABLECIMIENTO DE INSPECCION DE REGISTROS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('63a78c8a-b9c0-4991-ade1-2fe39aa974da', 'a0000000-0000-0000-0000-000000000001', '3e33fdb1-2a7d-40f1-ab01-ddd774770a1a', '1216', NULL, 1098, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05463d21-2860-4ee1-8da4-d6fa2a928622', '63a78c8a-b9c0-4991-ade1-2fe39aa974da', 1, 'El registro de la Propiedad de la zona central con sede en la ciudad capital, tendrá a su cargo el registro de las demás zonas que no lo tengan propio y como registro general, el control y vigilancia de los demás registros de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d475b4cd-3d76-4730-87f0-7e9df273ec4b', 'a0000000-0000-0000-0000-000000000001', '3e33fdb1-2a7d-40f1-ab01-ddd774770a1a', '1217', NULL, 1099, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('68a57a6a-0106-4e53-ada6-734c8caae611', 'd475b4cd-3d76-4730-87f0-7e9df273ec4b', 1, 'La inspección de cada registro la tendrá a su cargo el juez de Primera Instancia de lo Civil, designado anualmente por la Corte Suprema de Justicia, si fueren varios los jueces del departamento en que tenga su sede el respectivo registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fc42535-3475-4104-ac41-d81584441b94', 'a0000000-0000-0000-0000-000000000001', '3e33fdb1-2a7d-40f1-ab01-ddd774770a1a', '1218', NULL, 1100, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a43d727-dc81-4586-a037-2020662602e1', '6fc42535-3475-4104-ac41-d81584441b94', 1, 'Los jueces de Primera Instancia visitarán el registro de su jurisdicción, para darse cuenta de la marcha de la oficina, del estado en que se encuentren los libros y archivos del mismo registro y de la actividad y competencia del personal. Extenderá acta en que haga constar sus observaciones y si el despacho se encuentra al día o si sufre retraso; enviando copia de la misma acta a la Corte suprema de Justicia para que si fuere del caso, dicte las medidas que estime convenientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bf9e81e8-9bf8-4060-9404-404946e79408', 'a0000000-0000-0000-0000-000000000001', '3e33fdb1-2a7d-40f1-ab01-ddd774770a1a', '1219', NULL, 1101, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ec23189-25be-4830-bb07-4ea6e240c2be', 'bf9e81e8-9bf8-4060-9404-404946e79408', 1, 'Si los jueces notaren alguna falta de formalidad por parte de los registradores, en el modo de llevar el registro, o en el arreglo de los documentos que a él corresponda, dictarán las disposiciones necesarias para corregirla y, en su caso, sancionarán a los registradores en la forma que establece este Código.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('500095b3-b2d1-4aab-8082-279510c887f1', 'bf9e81e8-9bf8-4060-9404-404946e79408', 2, 'LIBROS QUE DEBEN LLEVARSE EN EL REGISTRO.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fe2fbbba-35bd-454d-823a-783eca2e4f6c', 'a0000000-0000-0000-0000-000000000001', 'bf360810-a6f7-4c6b-8fa2-f62cc3206a1a', '1220', NULL, 1102, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e250bd73-2d1d-4e06-bc49-7fda1baaa7ab', 'fe2fbbba-35bd-454d-823a-783eca2e4f6c', 1, 'En los registros es obligatorio llevar los siguientes libros principales: 1. De entrega de documentos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed30c6d4-3369-4592-bae7-f5254b1ebf81', 'fe2fbbba-35bd-454d-823a-783eca2e4f6c', 2, '2. De inscripciones;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('782790ec-45af-444e-a13a-bc3886920171', 'fe2fbbba-35bd-454d-823a-783eca2e4f6c', 3, '3. De cuadros estadísticos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('39666722-2fdd-4b62-be1a-a057c3c99a8e', 'fe2fbbba-35bd-454d-823a-783eca2e4f6c', 4, '4. De índices por orden alfabético de apellidos de los propietarios y poseedores de inmuebles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('769275ba-6fd0-45ae-bf8e-44ba4f845bca', 'a0000000-0000-0000-0000-000000000001', 'bf360810-a6f7-4c6b-8fa2-f62cc3206a1a', '1221.25', NULL, 1103, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('585740f2-1824-41a7-b035-e6dbef0aca2e', '769275ba-6fd0-45ae-bf8e-44ba4f845bca', 1, 'El registrador llevará, asimismo, los libros que sean necesarios para las inscripciones especiales y los demás que determine el reglamento del registro. Los libros podrán ser electrónicos y físicos. El Registrador queda facultado para innovar progresivamente los controles y sistemas de operación implementando toda clase de programas, técnicas y procesos para efectuar, formalizar y ejecutar todas las operaciones regístrales, utilizando para ello medios informáticos, computarizados, digitales, magnéticos, electrónicos, de');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f627278-d7da-4646-af85-687945bd5e7b', '769275ba-6fd0-45ae-bf8e-44ba4f845bca', 2, '25 Reformado como aparece en el texto por el Artículo 4, del Decreto No. 42-2006, publicado en el Diario de Centro América el 19 de diciembre de 2006.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('29c9ec51-07df-4ddf-94f6-41f613742155', '769275ba-6fd0-45ae-bf8e-44ba4f845bca', 3, 'teleproceso y de cualquier otra naturaleza, de acuerdo a las posibilidades económicas y conforme a las normas de seguridad establecidas y aprobadas por el Registro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e2e7cc15-5647-41f3-9cd8-56783b4c84e6', 'a0000000-0000-0000-0000-000000000001', 'bf360810-a6f7-4c6b-8fa2-f62cc3206a1a', '1222', NULL, 1104, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('06c28240-c23c-4352-ba63-8e07003d97c8', 'e2e7cc15-5647-41f3-9cd8-56783b4c84e6', 1, 'Los libros de los registros serán públicos; no se sacarán por ningún motivo de la oficina del registro donde se mantendrán con todas las precauciones necesarias para su conservación y seguridad. Las diligencias judiciales y extrajudiciales que exijan la exhibición de dichos libros, se practicarán precisamente en la misma oficina.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67064289-5f55-4b5f-8b24-07d0c879e084', 'a0000000-0000-0000-0000-000000000001', 'bf360810-a6f7-4c6b-8fa2-f62cc3206a1a', '1223', 'Sólo harán fe los libros del registro llevados legalmente', 1105, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0495209d-9ec3-4850-9026-c654ae0c2956', 'a0000000-0000-0000-0000-000000000001', 'bf360810-a6f7-4c6b-8fa2-f62cc3206a1a', '1224', NULL, 1106, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1481fbd-74db-40bd-9b3b-661283e2985d', '0495209d-9ec3-4850-9026-c654ae0c2956', 1, 'Los libros que se encuentren destruidos o deteriorados de tal manera que sea difícil su consulta, serán repuestos bajo la responsabilidad del registrador, previa autorización judicial. Hecha la transcripción, el registrador cerrará el nuevo libro con una razón en que haga constar estar confrontadas y conformes con el original todas las partidas transcritas.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71a94fd2-490b-4e4f-957d-7dffafc17492', '0495209d-9ec3-4850-9026-c654ae0c2956', 2, 'DE LOS REGISTRADORES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c398310e-2793-4910-b866-40bb46c1b524', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1225', NULL, 1107, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1363c7a0-5472-4b05-97bd-d7bf39ef3899', 'c398310e-2793-4910-b866-40bb46c1b524', 1, '26 Cada registro estará a cargo de un registrador propietario, nombrado por el Presidente de la República, mediante acuerdo gubernativo a través del Ministerio de Gobernación. Su permuta, traslado o cesación serán acordados en la misma forma. Cada registro podrá contar con uno o varios registradores auxiliares, designados por el registrador propietario bajo su responsabilidad, quienes firmarán las razones, documentos, asientos, inscripciones, anotaciones y cancelaciones que determine dicho funcionario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3be9c34-cece-438c-9236-dc56da56ea98', 'c398310e-2793-4910-b866-40bb46c1b524', 2, 'Cada registrador auxiliar tendrá las mismas calidades del registrador propietario, estará sujeto a las mismas limitaciones y garantizará las responsabilidades en que pudiere incurrir, con hipoteca o fianza. El registrador propietario fijará el importe de la garantía, conforme al criterio y límites a que se refiere el Artículo 1228 de este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16957aa5-d150-4d0c-aefe-c1327cbc157f', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1226', NULL, 1108, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c978b3a-c4ef-4fa4-9c17-e91e1599a2c5', '16957aa5-d150-4d0c-aefe-c1327cbc157f', 1, 'Para ser nombrado registrador de la Propiedad se requiere ser guatemalteco de origen, notario y abogado colegiado activo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0d448c07-fbdf-4a92-aacd-f9e18dd92a2b', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1227', NULL, 1109, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('02460c90-505f-42ea-a86b-06bc0d538359', '0d448c07-fbdf-4a92-aacd-f9e18dd92a2b', 1, 'El cargo de registrador es incompatible con el ejercicio de las profesiones de abogado y notario y con todo empleo o cargo público.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('619a3170-46aa-469a-8092-1078fa471223', '0d448c07-fbdf-4a92-aacd-f9e18dd92a2b', 2, '26 Reformado como aparece en el texto por el Artículo 1 del Decreto No. 85-97, publicado en el Diario de Centro América el 01 de noviembre de 1997.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b4fde89d-cf84-4445-a6b7-cfa074ad4690', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1228', NULL, 1110, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3f59494c-6732-4e4e-9452-3c2c61558ff9', 'b4fde89d-cf84-4445-a6b7-cfa074ad4690', 1, 'Los registradores antes de entrar a ejercer sus cargos, garantizarán las responsabilidades en que pudieren incurrir, con hipoteca o fianza. El Ministerio de Gobernación fijará el importe de la garantía atendiendo a la importancia del registro entre mil y diez mil quetzales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33174f70-9391-4ff8-b53b-b51298295a36', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1229', NULL, 1111, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fdc22db4-241c-4e12-9dfc-ca84dac9ab06', '33174f70-9391-4ff8-b53b-b51298295a36', 1, 'La garantía de que trata el artículo anterior no se cancelará, sino hasta un año después de haber cesado el registrador en el ejercicio de su cargo, salvo que hubiere pendiente alguna reclamación contra el registrador, en cuyo caso, la cancelación quedará sujeta a las resultas del juicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d9921981-cee5-4cc8-b2fa-a817b6c7dbab', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1230', NULL, 1112, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40093513-ba0c-4b26-afaa-558ecbd48566', 'd9921981-cee5-4cc8-b2fa-a817b6c7dbab', 1, 'Si la garantía fuere hipotecaria y quedare un saldo insoluto al rematarse el inmueble, el registrador responderá con sus demás bienes por dicho saldo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('86f9c051-c554-4669-8f82-c90f489111fe', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1231', NULL, 1113, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d1327a5-9f2d-4637-a478-17d08057a878', '86f9c051-c554-4669-8f82-c90f489111fe', 1, 'Los registradores enviarán al registrador de la capital, durante el mes de enero de cada año, un cuadro estadístico relativo al año anterior, que contendrá: las enajenaciones y su precio, con separación de fincas rústicas y urbanas; los derechos reales impuestos sobre ellas y su valor si constare; las hipotecas, número de fincas hipotecadas, importe de los capitales asegurados con ellas y las cancelaciones verificadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7d3c7ec-4743-4c02-9563-dfd506c1df45', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1232', NULL, 1114, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ffc085dd-a2da-4099-9c3b-ebcdeb2c9ec2', 'b7d3c7ec-4743-4c02-9563-dfd506c1df45', 1, 'En el mes de febrero de cada año, el registrador de la capital, enviará al Ministerio de Gobernación un cuadro con los datos estadísticos que deberá comprender todas las operaciones efectuadas en los registros de la Propiedad. Los datos estadísticos se compilarán por dicho registrador en el libro respectivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b6df993-2388-4366-a2fc-833084b8e88c', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1233', NULL, 1115, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('764ec9d8-1209-4adc-8091-b7981ea9a3d2', '7b6df993-2388-4366-a2fc-833084b8e88c', 1, 'En cada Registro habrá un registrador sustituto, de nombramiento del Ejecutivo a propuesta y bajo la responsabilidad del propietario, para que haga las veces de éste en los casos de ausencia, enfermedad o incompatibilidad en el desempeño de sus funciones. El sustituto tendrá las mismas calidades que el propietario. Si excediere de un mes el tiempo de la interinidad, el sustituto deberá prestar garantía en los mismos términos que el propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90236e72-a908-4e26-9a95-013676622d50', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1234', NULL, 1116, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a8db6df4-a582-49ae-abef-55b9ecfe4008', '90236e72-a908-4e26-9a95-013676622d50', 1, 'El registrador sustituto hará las veces del propietario accidentalmente, cuando éste, su cónyuge o sus parientes Intervengan en un documento inscribible o sean parte en el juicio de que proceda el mandamiento u orden para una inscripción o anotación. Cuando exista incompatibilidad en ambos registradores, el Ministerio de Gobernación designará, en cada caso, al notario que deba autorizar las operaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('92b0906f-1234-4071-aa31-e97dacc1c646', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1235', NULL, 1117, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d028320e-2ea4-41aa-ba09-50b118fbd487', '92b0906f-1234-4071-aa31-e97dacc1c646', 1, 'Los registradores no son parte en ningún litigio en que se ventile la validez o nulidad de una inscripción, excepto cuando se les deduzca responsabilidad por abusos de sus funciones o por defecto de una inscripción, y en los ocursos de queja.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ad1602c-43dd-42b1-9e52-b1f645289cb3', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1236', NULL, 1118, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be0f9308-0943-482e-a43a-3649ff2b5866', '6ad1602c-43dd-42b1-9e52-b1f645289cb3', 1, 'Quien por culpa del registrador aparezca en el registro indebidamente exonerado de alguna obligación o gravamen inscrito, quedará responsable de dicha obligación o gravamen, solidariamente con el registrador; y éste responderá además, de los daños y perjuicios que por tales daños u omisiones se hayan causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a80e12b-6aec-4807-ae58-f0331101e57c', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1237', 'El juez de 1ª', 1119, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e65436f6-70b0-4fcd-99e1-d3db9ea87519', '7a80e12b-6aec-4807-ae58-f0331101e57c', 1, 'Instancia a cuya jurisdicción pertenezca el registro, será el competente para conocer de las demandas que por daños y perjuicios procedan contra el registrador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a75d73b-e37d-4176-be2a-207820e3d62e', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1238', NULL, 1120, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('efb2e82e-6d8b-41ee-b0b3-113cc5b32e18', '7a75d73b-e37d-4176-be2a-207820e3d62e', 1, 'Las infracciones de esta ley o de los reglamentos relativos al registro, cometidas por los registradores, aunque no causen perjuicio a tercero, ni constituyan delito, serán castigadas con multas de cinco a cincuenta quetzales. La multa será impuesta por el juez del departamento a que corresponda el registro y sin más trámite que las diligencias necesarias para averiguar el hecho. Quedan al penado expeditos los recursos legales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7f6a35a-d819-4009-a386-746827922599', '7a75d73b-e37d-4176-be2a-207820e3d62e', 2, 'El importe de las multas ingresará a los fondos de justicia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af12e2d3-8597-4a9d-88a6-1471553742df', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1239', NULL, 1121, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e27644e4-e2d7-4312-bba5-b0920efdfbc9', 'af12e2d3-8597-4a9d-88a6-1471553742df', 1, 'Lo dispuesto en los artículos anteriores, en cuanto a la indemnización de daños y perjuicios y sujeción a multas, no obstará a la imposición de la pena que, en caso de delito, proceda conforme a las leyes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('41c9e768-3aad-4c68-a224-dac331ee7656', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1240', NULL, 1122, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aec56051-3a02-4f36-acb7-6f80db3dbce9', '41c9e768-3aad-4c68-a224-dac331ee7656', 1, 'Cuando un registrador fuere condenado a la vez a la indemnización de daños y perjuicios y al pago de la multa, se pagarán de preferencia los primeros.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('25ca9fd4-031a-4a71-b6c3-169639722775', 'a0000000-0000-0000-0000-000000000001', 'aa7e9186-7bd4-457e-afc1-96b866ca6d71', '1241', NULL, 1123, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('10a0ff23-bed5-491d-a2eb-0db0d49c47f0', '25ca9fd4-031a-4a71-b6c3-169639722775', 1, 'Los registradores percibirán los honorarios que fije el Arancel y costearán sin tasa alguna, los gastos ordinarios de oficina, que incluyen a la provisión y conservación de los libros del registro');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('acc90bf4-3450-4e9f-8ce2-db9bf2b4fa08', '25ca9fd4-031a-4a71-b6c3-169639722775', 2, 'ERRORES EN LOS LIBROS Y SU RECTIFICACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5653772e-9db8-4803-a835-eee2ecf63675', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1242', NULL, 1124, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae24eb78-3bdc-4bb8-b20e-b911b7f3734b', '5653772e-9db8-4803-a835-eee2ecf63675', 1, 'Los registradores, antes de firmar y sellar los asientos del Registro, cuidarán de revisarlos para salvar las palabras testadas o intercaladas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('05e42316-647f-4eb7-a8d3-f3c116671188', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1243', NULL, 1125, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38413440-b360-42bb-a2cd-f3d6a0b9b3ef', '05e42316-647f-4eb7-a8d3-f3c116671188', 1, 'No podrán corregirse los errores u omisiones cometidos en los libros del Registro, con tachas o intercalando palabras entre líneas, después de firmados los asientos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16f5b208-71a8-441f-92bc-69e2218785f3', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1244', NULL, 1126, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('139e28d2-d37d-4fdd-8dc7-f48c9d1e7ce9', '16f5b208-71a8-441f-92bc-69e2218785f3', 1, 'Los registradores no pueden rectificar sin consentimiento del interesado los errores materiales. Se entiende que hay error material, cuando se han escrito unas palabras por otras, omitido la expresión de alguna circunstancia, cuya falta no causa nulidad, o equivocado los nombres propios o las cantidades al copiarlas del');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ce986be-fb50-4ed0-9b0a-26d852af5fd2', '16f5b208-71a8-441f-92bc-69e2218785f3', 2, 'título, sin cambiar por eso el sentido general de la inscripción, ni el de ninguno de sus conceptos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('02409e89-1c46-4552-83dc-6aace24a20e7', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1245', NULL, 1127, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f4fad2a7-a0b6-40b8-b193-45480ae08e20', '02409e89-1c46-4552-83dc-6aace24a20e7', 1, 'Los errores de concepto no pueden rectificarse sino por acuerdo unánime de los interesados, y en defecto de tal acuerdo, mediante resolución judicial que ordene la rectificación. Los errores de concepto cometidos en asientos de presentación o en anotaciones marginales, pueden ser rectificados por el registrador, cuando el asiento principal basta para que aquéllos sean conocidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('05a29685-230a-4943-9b79-58c579945a49', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1246', NULL, 1128, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2122ec63-bb91-41cc-9c9a-e58c8d508f77', '05a29685-230a-4943-9b79-58c579945a49', 1, 'Se entenderá que se comete error de concepto, cuando alguna de las palabras expresadas en la inscripción alteren o varíen su verdadero sentido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('92a5a39b-f6da-4715-b3b6-0022e35f9ea4', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1247', NULL, 1129, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa84a199-4ca5-47c2-bc35-804f1b486a59', '92a5a39b-f6da-4715-b3b6-0022e35f9ea4', 1, 'El registrador o cualquiera de los interesados en un asiento, pueden oponerse a la rectificación que otros soliciten por causa de error de concepto, siempre que a juicio de aquéllos el concepto que se supone equivocado esté conforme con el mérito del título a que el asiento se refiere. La cuestión que se suscite con este motivo, se decidirá judicialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('abb0e93d-6138-4d87-b2b9-79ee8f8fc262', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1248', NULL, 1130, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94038789-bddc-422f-8d5b-10ef113300b5', 'abb0e93d-6138-4d87-b2b9-79ee8f8fc262', 1, 'Los errores de concepto se rectifican por un nuevo asiento, que se extenderá mediante la presentación del mismo título ya inscrito, si el registrador reconoce su error o el juez lo declara; y en virtud de nuevo título si el error ha sido cometido a causa de la redacción vaga, ambigua, o inexacta del título primitivo y las partes convienen en ello, o se declara así por resolución judicial. Siempre que se rectifique un error en virtud del mismo título antes presentado, son de cuenta del registrador los gastos y perjuicios que del error se originen.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b602f7c8-2849-4498-9b05-cfa25fef0b71', 'abb0e93d-6138-4d87-b2b9-79ee8f8fc262', 2, 'En caso contrario, pagarán los interesados los gastos de la nueva inscripción y los demás que la rectificación ocasione.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('118cd65f-7254-4dbc-bcff-01a87cd5d221', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1249', NULL, 1131, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8fa0f842-88fb-4b58-bce7-9be05f573a40', '118cd65f-7254-4dbc-bcff-01a87cd5d221', 1, 'Cuando los errores materiales o de concepto anulen una inscripción, no habrá lugar a la rectificación sino mediante declaración judicial. El asiento rectificado no produce efecto en ningún caso, sino desde la fecha de la rectificación sin perjuicio del derecho de los terceros para reclamar de la falsedad o nulidad del título a que se refiere el asiento equivocado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 'a0000000-0000-0000-0000-000000000001', '44cb0d21-9fa2-4fb8-bfee-637cd1dd37ca', '1250', NULL, 1132, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11d42901-d9ea-4bd6-a24c-cd5f6816caea', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 1, 'Respecto a los detalles sobre el modo de llevar el registro, los registradores observarán las prescripciones contenidas en el reglamento del ramo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a733fa83-5acb-4871-ae6f-af1d1d82d5d9', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 2, 'DEL DERECHO DE OBLIGACIONES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c63921b6-35bd-40f9-9e4d-ef0ad01b4937', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 3, 'PRIMERA PARTE');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6654bbf-5dbd-45b0-9816-06e4269d4854', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 4, 'DE LAS OBLIGACIONES EN GENERAL');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3100da6-2105-4706-a728-8d338b7f6961', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 5, 'DEL NEGOCIO JURIDICO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5cc1560-b276-4c33-889c-448f1a2ce559', '8fdea084-cd63-4e9d-9706-b62c6ce5cccc', 6, 'DE LA DECLARACION DE VOLUNTAD');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e41087a7-7244-4f30-af30-76eee8d916c9', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1251', NULL, 1133, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f3b67001-ba93-4525-927b-89aa2223f169', 'e41087a7-7244-4f30-af30-76eee8d916c9', 1, 'El negocio jurídico requiere para su validez: capacidad legal del sujeto que declara su voluntad, consentimiento que no adolezca de vicio y objeto lícito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b50bcc93-418b-4ac8-936d-84b9456fdcf7', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1252', NULL, 1134, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b59d236d-fe16-4021-b1ed-db4ecb6edba9', 'b50bcc93-418b-4ac8-936d-84b9456fdcf7', 1, 'La manifestación de voluntad puede ser expresa o tácita y resultar también de la presunción de la ley en los casos en que ésta lo disponga expresamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fa2d9f36-f98a-441a-accf-6b867ed248ba', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1253', NULL, 1135, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc0498b8-1700-4b58-9508-8a60b495cf72', 'fa2d9f36-f98a-441a-accf-6b867ed248ba', 1, 'El silencio no se considerará como manifestación tácita de voluntad sino en los casos en que existe, para la parte a quien afecta, la obligación de explicarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('363336c1-8f7e-43c0-946f-b3db8b64a2b7', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1254', NULL, 1136, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f41af9f-4935-41f5-ac67-b73174cb69ee', '363336c1-8f7e-43c0-946f-b3db8b64a2b7', 1, 'Toda persona es legalmente capaz para hacer declaración de voluntad en un negocio jurídico, salvo aquéllas a quienes la ley declare específicamente incapaces.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ab792f0-07ba-49d5-8ac4-7109c089398c', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1255', NULL, 1137, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01dac60b-9d70-4940-b90f-da8f2e848e89', '6ab792f0-07ba-49d5-8ac4-7109c089398c', 1, 'La incapacidad relativa de una de las partes no puede ser invocada por la otra en su propio beneficio, si oportunamente la hubiere conocido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7cd192ed-9ed0-453e-b6e6-ef3b325ea9b6', 'a0000000-0000-0000-0000-000000000001', '30aad5be-2685-42ef-9428-0137eb557887', '1256', NULL, 1138, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95d027cc-e4cc-4c00-b173-32bfea02346d', '7cd192ed-9ed0-453e-b6e6-ef3b325ea9b6', 1, 'Cuando la ley no declare una forma específica para un negocio jurídico, los interesados pueden usar la que juzguen conveniente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0404d89-936d-4e2b-ac0c-56426f7b67dd', '7cd192ed-9ed0-453e-b6e6-ef3b325ea9b6', 2, 'VICIOS DE LA DECLARACION DE VOLUNTAD');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f3459ade-3ff6-413a-a2c5-f29319cfe49f', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1257', NULL, 1139, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('455aa751-271c-4a57-a1c1-7a46bead0ca8', 'f3459ade-3ff6-413a-a2c5-f29319cfe49f', 1, 'Es anulable el negocio jurídico cuando la declaración de voluntad emane de error, de dolo, de simulación o de violencia. La nulidad no puede pedirla o demandarla la parte que hubiere causado el vicio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d82cde5-a54f-4bb0-881e-b4c41ac28253', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1258', NULL, 1140, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87490dfb-2b41-4164-9052-755b032eb360', '7d82cde5-a54f-4bb0-881e-b4c41ac28253', 1, 'El error es causa de nulidad cuando recae sobre la sustancia de la cosa que le sirve de objeto, o sobre cualquiera circunstancia que fuere la causa principal de la declaración de voluntad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6611847b-bdbe-4e7f-968f-369aaaa27a77', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1259', NULL, 1141, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77b99406-f56c-45d4-abf2-f5009b27d337', '6611847b-bdbe-4e7f-968f-369aaaa27a77', 1, 'El error sobre la persona sólo invalidará el negocio jurídico cuando la consideración a ella hubiere sido el motivo principal del mismo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b3c4f9a0-0707-44fc-9d3a-d579aec85214', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1260', 'El error de cuenta sólo dará lugar a su corrección', 1142, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b42b70b1-07bf-48ad-a3b2-b48e94e6057a', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1261', NULL, 1143, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9aa6ae1e-66ee-403d-b30f-ee383d6ca28a', 'b42b70b1-07bf-48ad-a3b2-b48e94e6057a', 1, 'Dolo es toda sugestión o artificio que se emplee para inducir a error o mantener en él a alguna de las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('91b8dd8e-6a50-44bf-9435-59d288b188da', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1262', NULL, 1144, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55617f10-955a-4b5e-bd60-49b310289925', '91b8dd8e-6a50-44bf-9435-59d288b188da', 1, 'El dolo de una de las partes y el dolo que proviene de un tercero, sabiéndolo aquélla, produce la nulidad si ha sido la causa determinante del negocio jurídico.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e34c666e-c97a-4552-83ff-4b3141672385', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1263', NULL, 1145, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e178cdfa-6c98-466c-b5e2-06b20805d2da', 'e34c666e-c97a-4552-83ff-4b3141672385', 1, 'La omisión dolosa produce los mismos efectos que la acción dolosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('554cbac7-97ec-4e34-98a5-3110b25baa95', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1264', NULL, 1146, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('baf63b7c-d74c-4f6e-bfaf-232d9b835073', '554cbac7-97ec-4e34-98a5-3110b25baa95', 1, 'Será ineficaz el consentimiento prestado por violencia o intimidación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b89c3a17-f6e6-4c01-bd3a-5ee77e5eb7a7', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1265', NULL, 1147, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42831d69-b7da-46fa-94d3-a6d74c3e0a6c', 'b89c3a17-f6e6-4c01-bd3a-5ee77e5eb7a7', 1, 'La violencia o intimidación deben ser de tal naturaleza que causen impresión profunda en el ánimo de una persona razonable y le inspiren el temor de exponer su persona o su honra o la de su cónyuge o conviviente de hecho, ascendientes, descendientes o hermanos, a un mal grave o a la pérdida considerable de sus bienes. Si se trata de otras personas, el juez podrá declarar la nulidad según las circunstancias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('59aeecde-b791-4795-b931-0f15ab4119e0', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1266', NULL, 1148, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f85b312-7558-4464-a21f-8e7805e33810', '59aeecde-b791-4795-b931-0f15ab4119e0', 1, 'Para calificar la violencia o intimidación, debe atenderse a la edad, al sexo, a la condición de la persona y demás circunstancias que puedan influir sobre su gravedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f17f65cf-cb32-4e08-8eb3-0699111791fe', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1267', NULL, 1149, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9679529-3feb-4a90-9f6b-de27e6b39fa7', 'f17f65cf-cb32-4e08-8eb3-0699111791fe', 1, 'La amenaza del ejercicio regular de un derecho y el temor reverencial, esto es, el sólo temor de desagradar a las personas a quienes se debe sumisión y respeto, no anularán el acto o negocio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2789b5a-daba-4234-95a9-823c6cbc4cc7', 'a0000000-0000-0000-0000-000000000001', '8117f051-fffc-45c9-b263-d4b7edeec6bd', '1268', NULL, 1150, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a07b1ef-a8dc-4516-bca1-8412824c12ce', 'c2789b5a-daba-4234-95a9-823c6cbc4cc7', 1, 'Si habiendo cesado la violencia o siendo conocido el error o el dolo, el que sufrió la violencia o padeció el engaño ratifica su voluntad o no reclama dentro del término de la prescripción, el negocio adquiere toda su validez.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3e78d1be-e7e2-4b8c-bb1c-1adda3422f46', 'c2789b5a-daba-4234-95a9-823c6cbc4cc7', 2, 'NEGOCIOS JURIDICOS CONDICIONALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33b430a5-901a-4a5e-9658-a7baf9036729', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1269', NULL, 1151, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d96852d5-a680-4ba6-b880-45b1439f9400', '33b430a5-901a-4a5e-9658-a7baf9036729', 1, 'En los negocios jurídicos condicionales, la adquisición de los derechos, así como la resolución o pérdida de los ya adquiridos, dependen del acontecimiento que constituye la condición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc702d69-510d-4a5f-bb3e-1699cb800ee2', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1270', NULL, 1152, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0a626fff-2a34-4647-a379-843dd48c6c82', 'fc702d69-510d-4a5f-bb3e-1699cb800ee2', 1, 'El negocio condicional surte efectos desde el cumplimiento de la condición, salvo estipulación en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a1397ae4-f715-4d0e-b946-4d9768c84786', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1271', NULL, 1153, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8407bf34-8980-4a09-bfbc-30d7f5d5092b', 'a1397ae4-f715-4d0e-b946-4d9768c84786', 1, 'Se puede estipular cualesquiera condiciones que no sean contrarias a las leyes ni a la moral. No vician el contrato y se tienen por no puestas las condiciones imposibles y las contrarias a las leyes o a las buenas costumbres.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c60b244a-12ef-4ff3-87a8-20421771cbcc', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1272', NULL, 1154, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95cb3038-8596-407a-9014-65c971c89201', 'c60b244a-12ef-4ff3-87a8-20421771cbcc', 1, 'Es nulo el negocio contraído bajo una condición cuyo cumplimiento depende en lo absoluto de la voluntad de la parte obligada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e94c03f9-af45-4dbb-b953-dfe251f0aa90', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1273', NULL, 1155, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93a9f868-11d0-48ff-9c7b-0141be68ff3e', 'e94c03f9-af45-4dbb-b953-dfe251f0aa90', 1, 'Se tendrá por cumplida la condición cuando el obligado impide voluntariamente su cumplimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('384be46a-1e3a-44fc-9e2c-de72b7e1be0f', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1274', NULL, 1156, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46a4a8e9-252b-4146-8f9a-6fcaf4f3bee9', '384be46a-1e3a-44fc-9e2c-de72b7e1be0f', 1, 'El negocio jurídico sujeto a la condición de que se verifique un acontecimiento dentro de un término, caduca si pasa el término sin realizarse la condición, o antes si hay certidumbre de que no puede cumplirse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('db839ed9-8e51-488c-9a93-03e9c711d47b', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1275', NULL, 1157, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b12492a-2396-483e-85db-467863b35394', 'db839ed9-8e51-488c-9a93-03e9c711d47b', 1, 'Si la condición es de que no se verifique cierto acontecimiento dentro de un término, se entiende cumplida desde que pasa el término o llega a ser cierto que el acontecimiento no puede realizarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb49b148-f980-4b32-91fe-71410b91eb5c', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1276', NULL, 1158, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bb1bc95-81db-4cb3-b9da-654a9bfc82e4', 'bb49b148-f980-4b32-91fe-71410b91eb5c', 1, 'El acreedor puede, antes del cumplimiento de la condición, ejercitar las acciones conducentes a la conservación de su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3521000-d163-41c8-a1ff-c820456d2313', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1277', NULL, 1159, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82b9aaae-7d2b-4b94-a788-f3b552fcd257', 'd3521000-d163-41c8-a1ff-c820456d2313', 1, 'El cumplimiento de la condición es indivisible, aunque consista en una prestación divisible.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3f3766e-7f26-4907-aae1-2a66fdcb11ee', 'a0000000-0000-0000-0000-000000000001', 'bbfdd3d8-2c4c-488f-9af3-bf9f125adfda', '1278', 'La condición resolutoria expresa, opera de pleno derecho', 1160, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3b654e25-f868-47b2-9a3b-8f77bbc6ba92', 'd3f3766e-7f26-4907-aae1-2a66fdcb11ee', 1, 'DEL PLAZO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ae45920b-5f2f-4c0b-8313-693ceaed01d1', 'a0000000-0000-0000-0000-000000000001', '602c869c-68f5-4d36-8173-343aed4949aa', '1279', NULL, 1161, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d68b6e11-7517-43ba-ac93-508f9ba1a843', 'ae45920b-5f2f-4c0b-8313-693ceaed01d1', 1, 'El plazo solamente fija el día o fecha de la ejecución o extinción del acto o negocio jurídico.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9eba9f2-9405-4bfa-8e93-39d7fbbfb889', 'a0000000-0000-0000-0000-000000000001', '602c869c-68f5-4d36-8173-343aed4949aa', '1280', NULL, 1162, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56a99a72-bc47-4f9e-8270-385eef92f8e7', 'a9eba9f2-9405-4bfa-8e93-39d7fbbfb889', 1, 'No puede exigirse el cumplimiento de la prestación antes del vencimiento del plazo, pero si el que pagó ignoraba la existencia de ese plazo cuando hizo el pago, tendrá derecho a reclamar del acreedor los intereses o los frutos que éste hubiere percibido por el anticipo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4b1cb760-1c8e-4581-b846-ff8e8e667399', 'a0000000-0000-0000-0000-000000000001', '602c869c-68f5-4d36-8173-343aed4949aa', '1281', NULL, 1163, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6361e2f2-d45b-4b3b-9503-7cb3e91b6e3d', '4b1cb760-1c8e-4581-b846-ff8e8e667399', 1, 'Perderá el deudor el derecho de utilizar el plazo: 1. Cuando después de contraída la obligación resulte insolvente, salvo que garantice la deuda;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b48a58c6-f7c3-4b15-96c9-fbc47e06536a', '4b1cb760-1c8e-4581-b846-ff8e8e667399', 2, '2. Cuando no otorgue al acreedor las garantías a que se hubiere comprometido; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1090774f-dd81-440e-9331-a684a6f6edf6', '4b1cb760-1c8e-4581-b846-ff8e8e667399', 3, '3. Cuando por acto propio hubiese disminuido las garantías y cuando por caso fortuito desaparecieran, a menos que sean inmediatamente sustituidas por otras, a satisfacción del acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('77820199-02a1-4873-8395-fec2286e8b19', 'a0000000-0000-0000-0000-000000000001', '602c869c-68f5-4d36-8173-343aed4949aa', '1282', NULL, 1164, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('830d4d70-855a-4b98-b507-2875fff9c06e', '77820199-02a1-4873-8395-fec2286e8b19', 1, 'El plazo se presume convenido en favor del deudor, a menos que resulte del tenor del instrumento o de otras circunstancias, que ha sido fijado en favor del acreedor o de las dos partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83575306-baeb-4af5-80ff-bacc25ca7339', 'a0000000-0000-0000-0000-000000000001', '602c869c-68f5-4d36-8173-343aed4949aa', '1283', NULL, 1165, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('403179ab-06ef-46e7-8bb3-e0d30cd3a66a', '83575306-baeb-4af5-80ff-bacc25ca7339', 1, 'Si el negocio no señala plazo, pero de su naturaleza y circunstancias se dedujere que ha querido concederse al deudor, el juez fijará su duración. También fijará el juez la duración del plazo cuando éste haya quedado a voluntad del deudor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0f3f7f0-56ab-4582-b6d9-56138bd937db', '83575306-baeb-4af5-80ff-bacc25ca7339', 2, 'DE LA SIMULACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7cdb4c68-e762-48c9-b3c7-d95dac24e11e', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1284', NULL, 1166, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('272740b1-81cd-4667-b4be-c37f187bdaea', '7cdb4c68-e762-48c9-b3c7-d95dac24e11e', 1, 'La simulación tiene lugar: 1. Cuando se encubre el carácter jurídico del negocio que se declara, dándose la apariencia de otro de distinta naturaleza;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5c334b9d-3a5b-4ba6-a3e6-49d37a876946', '7cdb4c68-e762-48c9-b3c7-d95dac24e11e', 2, '2. Cuando las partes declaran o confiesan falsamente lo que en realidad no ha pasado o se ha convenido entre ellas; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf86b3fc-e4a4-4dc0-9314-b2f0b4561d98', '7cdb4c68-e762-48c9-b3c7-d95dac24e11e', 3, '3. Cuando se constituyen o transmiten derechos a personas interpuestas, para mantener desconocidas a las verdaderamente interesadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('be01b53b-f965-46a2-8121-2190428607ec', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1285', NULL, 1167, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a04cd62f-be88-41e8-ad23-5a2187f44ac5', 'be01b53b-f965-46a2-8121-2190428607ec', 1, 'La simulación es absoluta cuando la declaración de voluntad nada tiene de real; y es relativa, cuando a un negocio jurídico se le da una falsa apariencia que oculta su verdadero carácter.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ba8a46d5-2e5d-444a-8e57-4238ab27dc0b', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1286', 'La simulación absoluta no produce ningún efecto jurídico', 1168, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7886e9f-ed2d-4ce0-aacb-66abb6b1d9d0', 'ba8a46d5-2e5d-444a-8e57-4238ab27dc0b', 1, 'La simulación relativa, una vez demostrada, producirá los efectos del negocio jurídico encubierto, siempre que su objeto sea lícito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60b716dd-2e97-450d-b3ec-ca5739b83c12', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1287', NULL, 1169, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac465dd0-fcc8-4c6d-a49f-6899c064b159', '60b716dd-2e97-450d-b3ec-ca5739b83c12', 1, 'La simulación no anula el negocio jurídico cuando no tiene un fin ilícito ni causa perjuicio a ninguna persona.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('305db732-15f4-4522-9804-f564d7b6e14a', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1288', NULL, 1170, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bfd12f0-8953-4b05-8223-64e708e39b5e', '305db732-15f4-4522-9804-f564d7b6e14a', 1, 'La acción de simulación es imprescriptible entre las partes que simularon y para los terceros perjudicados con la simulación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('44a656d5-8a22-4f21-a87e-8274f3a11810', 'a0000000-0000-0000-0000-000000000001', 'f65248bb-1198-4a6f-800c-f7613a8a7dcc', '1289', NULL, 1171, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('308ab11b-5788-4e9b-9183-8824e1c3be66', '44a656d5-8a22-4f21-a87e-8274f3a11810', 1, 'Si la persona favorecida por la simulación ha transferido a otro sus derechos, la acción contra el tercero sólo será admisible si la transmisión tuvo lugar a título gratuito. Si la transmisión se operó a título oneroso, la revocación sólo será posible, si el subadquirente obró con mala fe.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e325001-1cc0-45ab-9c9a-5a98f53dcbd0', '44a656d5-8a22-4f21-a87e-8274f3a11810', 2, 'DE LA REVOCACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c011afa0-92c0-4d1a-a0dd-960af7238171', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1290', NULL, 1172, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eea43931-743f-4e3f-b67c-bfe2a3ac4ab6', 'c011afa0-92c0-4d1a-a0dd-960af7238171', 1, 'Todo acreedor puede pedir la revocación de los negocios celebrados por el deudor en perjuicio o fraude de sus derechos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ef59137-ab6e-4d8d-89d9-28f7157ec5e7', 'c011afa0-92c0-4d1a-a0dd-960af7238171', 2, 'Sólo los acreedores cuyos créditos sean anteriores al negocio impugnado, pueden ejercitar la acción revocatoria,');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d5b1c7b-585d-4b30-98ef-ec6efa8caa73', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1291', NULL, 1173, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('054a4cad-26e7-457d-bf74-7d5c0da7abe3', '4d5b1c7b-585d-4b30-98ef-ec6efa8caa73', 1, 'Los negocios de disposición a título gratuito realizados por el deudor insolvente, o reducido a la insolvencia a consecuencia de dichos negocios, pueden ser revocados a instancia de los acreedores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4b163a11-9362-458f-ac9b-b3ba0ac69771', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1292', NULL, 1174, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eaf0dc5a-c6cf-41ae-8d8c-60f078f950ea', '4b163a11-9362-458f-ac9b-b3ba0ac69771', 1, 'Si el negocio fuere oneroso, la revocación sólo tendrá lugar cuando haya mala fe de parte del deudor y del adquirente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4883b9ca-b302-4985-a546-f336b4115998', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1293', NULL, 1175, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8021b1f7-5baa-4502-9532-cc63551e5b54', '4883b9ca-b302-4985-a546-f336b4115998', 1, 'La revocación puede tener lugar, tanto en los negocios en que el deudor enajena los bienes que efectivamente posee, como en aquellos en que renuncia derechos constituidos a su favor y cuyo goce no fuere exclusivamente personal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('73f1a97e-7e70-4f02-8dbf-90d3e8e9533b', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1294', 'La acción revocatoria debe seguirse a instancia del acreedor', 1176, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40b873ff-c52d-47d3-a22b-455f37205ffe', '73f1a97e-7e70-4f02-8dbf-90d3e8e9533b', 1, 'La revocación sólo será declarada en interés de los acreedores que la hubiesen pedido y hasta el importe de sus créditos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('745e6e3b-df01-4a6b-9392-8fea9b41648a', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1295', NULL, 1177, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc446f48-e3eb-4387-9f86-ef76a02cf0de', '745e6e3b-df01-4a6b-9392-8fea9b41648a', 1, 'La acción revocatoria cesará luego que el deudor satisfaga su deuda o adquiera bienes con qué poder cubrirla. La persona a quien se hubiesen enajenado los bienes del deudor, puede hacer cesar la acción de los acreedores satisfaciendo el crédito de los que se hubiesen presentado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8efa1021-ed26-4a05-9319-d8b72e296be9', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1296', NULL, 1178, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c737e53c-2eb2-430b-8612-757566a22281', '8efa1021-ed26-4a05-9319-d8b72e296be9', 1, 'Revocado el negocio fraudulento del deudor, los bienes se devolverán por el que los adquirió de mala fe, con todos sus frutos; o indemnización de daños y perjuicios cuando la restitución de dichos bienes no fuere posible.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e15fc068-eef8-4f2f-99e6-2bc2dd0d0c82', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1297', NULL, 1179, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43a76206-d96f-44b2-aed1-6162d672c208', 'e15fc068-eef8-4f2f-99e6-2bc2dd0d0c82', 1, 'La acción concedida al acreedor contra el primer adquirente, no procede contra el tercer poseedor sino cuando éste ha adquirido de mala fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ce8dc29d-11db-4862-a066-08fa2b2746c5', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1298', NULL, 1180, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('904b2c97-6567-460a-899d-2341133a0070', 'ce8dc29d-11db-4862-a066-08fa2b2746c5', 1, 'Son también revocables los pagos hechos en estado de insolvencia, por cuenta de obligaciones a cuyo cumplimiento no podía ser compelido el deudor al tiempo de hacerlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1299', NULL, 1181, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0416666-0c20-4da9-a247-663516349877', '50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 1, 'Se presumen fraudulentos: 1. Los pagos anticipados hechos por el deudor concursado o declarado en quiebra, dentro de los diez días anteriores a la fecha fijada para la cesación de pagos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b085339-cbd3-4e1b-a5a5-8492596fb5c6', '50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 2, 'Hay pago anticipado en el descuento de pagarés o facturas a cargo del fallido y en el que se verifique mediante renuncia del plazo estipulado a favor del deudor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2eea6cb9-f086-461d-bc63-6207bc8f85f6', '50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 3, '2. Todo gravamen que, dentro del propio término de diez días, se constituya sobre los bienes del fallido, por deudas contraídas en el mismo término o con anterioridad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7add45ab-e191-46af-98c0-02f05b95431c', '50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 4, '3. Las enajenaciones a título oneroso o gravámenes constituidos sobre bienes, realizados por las personas contra las cuales se hubiere pronunciado antes sentencia condenatoria en relación a tales bienes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6fd206cd-bc95-4810-93ab-1a8f1e08ea48', '50a9bcac-6ca9-49ad-830b-e5cb2a76c6b5', 5, '4. Las enajenaciones hechas por el fallecido o concursado después del día fijado para la cesación de pagos o dentro de los diez días que la han precedido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c427cd86-0da8-49f5-a6e6-bd65f77cbf82', 'a0000000-0000-0000-0000-000000000001', '992676d8-18ea-4877-b4e9-a9e167ee15e5', '1300', NULL, 1182, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a86ab16b-7931-4eba-aede-91e153111595', 'c427cd86-0da8-49f5-a6e6-bd65f77cbf82', 1, 'La acción revocatoria prescribe en un año, contado desde la celebración del negocio o desde la fecha en que se verificó el pago o se hizo la renuncia del derecho.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96126707-53b7-4c1d-a4e5-d3be6d978307', 'c427cd86-0da8-49f5-a6e6-bd65f77cbf82', 2, 'DE LA NULIDAD');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5908d9a0-8a3b-4825-bf71-952d3a345056', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1301', NULL, 1183, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('068edd09-f520-4709-aea8-1b684357d54a', '5908d9a0-8a3b-4825-bf71-952d3a345056', 1, 'Hay nulidad absoluta en un negocio jurídico, cuando su objeto sea contrario al orden público o contrario a leyes prohibitivas expresas, y por la ausencia o no concurrencia de los requisitos esenciales para su existencia. Los negocios que adolecen de nulidad absoluta no producen efecto si son revalidables por confirmación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f039ef0d-14c0-4fad-92e1-346c6b270ee9', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1302', NULL, 1184, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b9e879f8-3278-4fad-a2e7-6572aefc8bb3', 'f039ef0d-14c0-4fad-92e1-346c6b270ee9', 1, 'La nulidad puede ser declarada de oficio por el juez cuando resulte manifiesta. Puede también ser alegada por los que tengan interés o por el Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('64280d57-6010-4a83-8e91-4bc95f8559f1', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1303', NULL, 1185, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14d2fcc0-e5d7-4153-b6f7-f7d26f2a6d1e', '64280d57-6010-4a83-8e91-4bc95f8559f1', 1, 'El negocio jurídico es anulable: 1. Por incapacidad relativa de las partes o de una de ellas; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3de30e3a-3e1b-47f5-a72a-c586101f456e', '64280d57-6010-4a83-8e91-4bc95f8559f1', 2, '2. Por vicios del consentimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ab1a3af-557c-4244-9932-67b9a2680716', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1304', NULL, 1186, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35335345-e888-4c2c-b133-5db1b7aae98e', '3ab1a3af-557c-4244-9932-67b9a2680716', 1, 'Los negocios que adolecen de nulidad relativa pueden revalidarse confirmándolos expresamente o dando cumplimiento a la obligación, a sabiendas del vicio que los hace anulables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cda85f9d-2c5f-4518-bfa0-30554d942851', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1305', NULL, 1187, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('482fedf3-9e26-41f7-90d5-a12bea82cc2f', 'cda85f9d-2c5f-4518-bfa0-30554d942851', 1, 'La revalidación expresa debe hacerse con los mismos requisitos que exige la ley para la celebración del negocio que se trata de revalidar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dae656ba-b90c-4d0d-8f97-c0d22dceb0bd', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1306', NULL, 1188, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a92dc85a-32b3-4182-b6ba-b31be1cc39d8', 'dae656ba-b90c-4d0d-8f97-c0d22dceb0bd', 1, 'La confirmación expresa o tácita de un negocio viciado de nulidad relativa implica la renuncia a la acción o excepción de nulidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5b3ea277-2000-4bfd-80bd-b94df7c62e18', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1307', NULL, 1189, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2e4596ca-6792-4ab1-84f7-0e0dbc9fb35a', '5b3ea277-2000-4bfd-80bd-b94df7c62e18', 1, 'La confirmación surte efectos desde la fecha de la celebración del negocio que se confirma, pero no perjudicará derechos de terceros de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('77dd59ad-67a2-480b-b9e7-29d5efa38ba5', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1308', NULL, 1190, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('127627bd-b13a-433a-8274-f063b639161f', '77dd59ad-67a2-480b-b9e7-29d5efa38ba5', 1, 'La nulidad de una o más de las disposiciones de un negocio jurídico no perjudica a las otras, siempre que sean separables. La nulidad de la obligación principal lleva consigo la de las obligaciones accesorias; pero la nulidad de éstas no induce la de la obligación principal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1cf0f3f9-fc73-4250-8904-9ba7843a16d8', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1309', NULL, 1191, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d52f453-5158-4cb7-9594-8e638d862268', '1cf0f3f9-fc73-4250-8904-9ba7843a16d8', 1, 'El negocio que adolece de nulidad relativa surte todos sus efectos mientras en sentencia firme no se declare dicha nulidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2028694e-12c5-4264-b818-4c29e26c91ec', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1310', NULL, 1192, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de5bde0e-fe64-4596-b8b6-b48529361a27', '2028694e-12c5-4264-b818-4c29e26c91ec', 1, 'La nulidad que se funde en vicios del consentimiento de las partes o de una de ellas, solamente se podrá intentar por la parte cuyo consentimiento está viciado o por quien resultare directamente perjudicado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c5e8a2a6-120d-4e5e-8815-c828ecd146ef', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1311', NULL, 1193, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca6498b0-d8d1-47a2-874e-fc6f41ef40cc', 'c5e8a2a6-120d-4e5e-8815-c828ecd146ef', 1, 'La nulidad procede con respecto a las obligaciones de los ausentes, de los menores y de los incapaces, cuando no se han observado las formalidades requeridas por la ley, o cuando los menores o incapaces actúan sin intervención de las personas que los representan. En estos casos, la acción de nulidad por parte del menor, incapaz o ausente, corresponde a su representante legal o al Ministerio Público.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('716627e6-d784-4acc-a817-697ecd9e0c71', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1312', NULL, 1194, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eec86e6f-d2fe-4675-a9d6-060379195afd', '716627e6-d784-4acc-a817-697ecd9e0c71', 1, 'El derecho de pedir la nulidad relativa dura dos años contados desde el día en que se contrajo la obligación, salvo los casos en que la ley fije término distinto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('57ba9fc3-050a-4c55-bbe5-b33847f7c44c', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1313', NULL, 1195, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3670eb2e-1816-4893-b2d2-c6c1cbcd8fe6', '57ba9fc3-050a-4c55-bbe5-b33847f7c44c', 1, 'Si la nulidad se fundare en violencia o temor grave, el término es de un año, contado de la fecha en que la violencia cesó o el temor grave ha debido razonablemente desaparecer.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bad657b1-2f20-4fc5-97ae-2709344c1723', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1314', NULL, 1196, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('036dfc98-0d22-4ef1-bb7f-e1d5be4a6520', 'bad657b1-2f20-4fc5-97ae-2709344c1723', 1, 'Las partes deben restituirse recíprocamente lo que han recibido o percibido como consecuencia del negocio anulado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fe157ce2-a4e5-41c1-92d4-ce0c796ea629', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1315', NULL, 1197, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f59405b6-2324-4ca6-bfed-2c41e3452db3', 'fe157ce2-a4e5-41c1-92d4-ce0c796ea629', 1, 'En los casos en que ambas partes han percibido frutos, productos o intereses, serán compensables hasta la fecha de la notificación de la demanda de nulidad, y desde esta fecha serán restituibles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b85a0658-3651-4f58-bb8e-fc800957460f', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1316', NULL, 1198, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a35b02e-520b-4601-ac07-631060c795fa', 'b85a0658-3651-4f58-bb8e-fc800957460f', 1, 'La restitución de las cosas debe hacerse en el estado que guardaban en el momento de la celebración del negocio. Las mejoras o deterioros se abonarán por quien corresponda, salvo que el deterioro proceda de caso fortuito, fuerza mayor, vicio o defectos ocultos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f370fb6-25df-4f8c-b484-e40e8e8aaec7', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1317', NULL, 1199, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1dd29ff-3928-4f97-8031-c747c694d6ad', '4f370fb6-25df-4f8c-b484-e40e8e8aaec7', 1, 'Si a una de las partes le fuere imposible la restitución de la cosa, cumplirá entregando otra de igual especie, calidad y valor, o devolviendo el precio que tenía en el momento de la celebración del negocio; y si la nulidad de la obligación o la imposibilidad de la entrega provienen de mala fe, pagará además los daños y perjuicios que correspondan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b9e883d6-cc18-474e-a9ad-87bb483a2d45', 'a0000000-0000-0000-0000-000000000001', '01190d96-e29a-4b5d-a829-552ed37baac7', '1318', NULL, 1200, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5c81452-c942-425a-9b62-1d4a835e6b57', 'b9e883d6-cc18-474e-a9ad-87bb483a2d45', 1, 'La devolución de las cosas, declarada la nulidad, debe hacerse simultáneamente, y si esto no fuere posible, dentro del término que fijen las partes o, en su defecto, el juez.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20eed7c0-d1b0-4ca5-a9a8-99c1a2758dae', 'b9e883d6-cc18-474e-a9ad-87bb483a2d45', 2, 'DE LAS OBLIGACIONES SUS MODALIDADES Y EFECTOS');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b099e62c-c596-4b50-b04e-899f1c686d41', 'b9e883d6-cc18-474e-a9ad-87bb483a2d45', 3, 'DISPOSICIONES PRELIMINARES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('393642db-4de7-4b0b-893d-0f067ad2c64f', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1319', NULL, 1201, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55622b86-1146-425d-9bf7-071fb183f267', '393642db-4de7-4b0b-893d-0f067ad2c64f', 1, 'Toda obligación resultante de un acto o declaración de voluntad consiste en dar, hacer o no hacer alguna cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('30d2659f-2148-4ff3-bdab-0736e0090e39', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1320', NULL, 1202, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72ced1e5-aa7a-4f53-97d9-f8aaea53947d', '30d2659f-2148-4ff3-bdab-0736e0090e39', 1, 'La obligación de dar cosa determinada comprende su entrega y la de sus accesorios y pertenencias, así como los frutos que produzca desde que se perfecciona el convenio. El deudor es responsable, asimismo, de su conservación, hasta que verifique la entrega.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('07f4272e-f4c6-4a4f-b1c7-2784b6faf64e', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1321', NULL, 1203, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b0664d8-24e2-45e4-a3b3-83b17b71e731', '07f4272e-f4c6-4a4f-b1c7-2784b6faf64e', 1, 'En las obligaciones de dar cosa determinada únicamente por su especie, la elección corresponde al deudor, salvo pacto en contrario. El deudor cumplirá eligiendo cosas de regular calidad, y de la misma manera procederá el acreedor, cuando se le hubiere dejado la elección.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52c4cb90-d477-4874-9347-c2c4fb6e1006', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1322', NULL, 1204, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b2f0913-6f6a-4c86-862e-ee3cbc90fa01', '52c4cb90-d477-4874-9347-c2c4fb6e1006', 1, 'En los casos a que se refiere el artículo anterior, el deudor no podrá, antes de la individualización de la cosa, eximirse de la entrega, alegando la pérdida por caso fortuito o fuerza mayor. Practicada la elección, se aplicarán las reglas establecidas sobre obligaciones de dar cosas ciertas o determinadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ab9b3f8-1052-49f9-beb4-598ac4072281', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1323', NULL, 1205, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f4c2ba64-9d51-4a91-bd21-aa623e35c3c4', '7ab9b3f8-1052-49f9-beb4-598ac4072281', 1, 'En las obligaciones de hacer, el incumplimiento del obligado da derecho al acreedor para hacer por si o por medio de tercero, a costa del deudor, lo que se hubiere convenido, si la calidad del ejecutante fuere indiferente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e668e62-4ea2-4f4a-9f2e-e9271af48d8e', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1324', NULL, 1206, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb55c2d1-3811-4a43-ba7e-b1aebd7dfb65', '5e668e62-4ea2-4f4a-9f2e-e9271af48d8e', 1, 'Si el acreedor prefiere la prestación por el deudor, pedirá que se le fije un término prudencial para que cumpla la obligación, y si no la cumpliere, será obligado a pagar daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ee357e37-b7f7-44ff-9e1b-912fc56432ee', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1325', NULL, 1207, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64281b72-a4e4-4ff0-bc8f-441e14f05fc6', 'ee357e37-b7f7-44ff-9e1b-912fc56432ee', 1, 'Si la obligación de hacer resultare imposible sin culpa del deudor, la obligación queda extinguida. El deudor debe devolver en este caso al acreedor lo que por razón de la obligación hubiere recibido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6de7f920-f4e4-4878-bf0f-ae3a9d94cab8', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1326', NULL, 1208, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0dd7da7-e394-4adc-b55c-c84ae2541387', '6de7f920-f4e4-4878-bf0f-ae3a9d94cab8', 1, 'Si la obligación es de no hacer, el obligado incurre en daños y perjuicios por el solo hecho de la contravención.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f2eff17f-507a-480a-872a-69a25d0420de', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1327', NULL, 1209, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('947f43e0-08cb-4f5f-95a3-c23f37209aea', 'f2eff17f-507a-480a-872a-69a25d0420de', 1, 'El acreedor tiene derecho para exigir que se obligue al deudor a destruir lo que se hubiere hecho contraviniendo lo pactado, o a que se le autorice la destrucción por cuenta del deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ba3ec58b-98e7-405a-b84a-6f1e06571938', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1328', NULL, 1210, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('492f6b14-f2f7-44d1-85c7-439e051bf2b4', 'ba3ec58b-98e7-405a-b84a-6f1e06571938', 1, 'Si no fuere posible destruir lo que se hubiere hecho o si la prestación fuere indestructible por su naturaleza, como la divulgación de un secreto industrial, el acreedor tendrá derecho de exigir daños y perjuicios por la contravención.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cde5bae6-c01a-46cf-90e5-e8ebeefc0aab', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1329', NULL, 1211, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7b8cc792-f418-460e-a870-717e7861acf0', 'cde5bae6-c01a-46cf-90e5-e8ebeefc0aab', 1, 'La obligación personal queda garantizada con los bienes enajenables que posea el deudor en el momento de exigirse su cumplimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4a0733cd-98a8-4732-8c67-860bb7a44cd9', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1330', NULL, 1212, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37a6529c-24d3-4481-8dff-8a3d3a226207', '4a0733cd-98a8-4732-8c67-860bb7a44cd9', 1, 'Cuando las condiciones bajo las cuales fuere contraída la obligación cambiaren de manera notable, a consecuencia de hechos extraordinarios imposibles de prever y de evitar, haciendo su cumplimiento demasiado oneroso para el deudor, el convenio podrá ser revisado mediante declaración judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('43ba9ca6-db3d-46ed-b59c-fe9b1bda7e1c', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1331', NULL, 1213, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93109896-85e4-4963-b997-117f0672e49a', '43ba9ca6-db3d-46ed-b59c-fe9b1bda7e1c', 1, 'La pérdida o deterioro de la cosa objeto de la obligación, antes de la entrega, se regirá por las reglas siguientes: 1. Si se pierde sin culpa del deudor, la obligación quedará sin efecto y se devolverá lo que se hubiere recibido por cuenta del convenio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef51fd8e-a08e-49e5-a53b-53cd48fd83de', '43ba9ca6-db3d-46ed-b59c-fe9b1bda7e1c', 2, '2. Si la pérdida fue por culpa del deudor, éste responderá al acreedor por el valor de la cosa y los daños y perjuicios; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c0dd2919-cdde-4ef0-85f7-48e58ffe9d80', '43ba9ca6-db3d-46ed-b59c-fe9b1bda7e1c', 3, '3. Si la cosa se deteriora sin culpa del deudor, el acreedor podrá rescindir el convenio o recibir la cosa en el estado en que se encuentre, con indemnización de daños y perjuicios en ambos casos, o disminución proporcional del precio si lo hubiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('42876192-9d64-4b7e-86b5-2470079995ba', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1332', NULL, 1214, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c8e2ec6-9422-45bf-bcbe-8163e23ce8dd', '42876192-9d64-4b7e-86b5-2470079995ba', 1, 'Si el deterioro de la cosa fuere de tal importancia que la haga inútil para el fin que se proponía el acreedor, se procederá como en el caso de pérdida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d40d8568-f2b7-485e-a204-1238280495de', 'a0000000-0000-0000-0000-000000000001', 'c9940613-b914-482a-99d3-193cc03c7df8', '1333', NULL, 1215, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d0ebfeb-6bd0-4717-aa97-13426e4e0800', 'd40d8568-f2b7-485e-a204-1238280495de', 1, 'Las mejoras originadas por la naturaleza de la cosa o por el transcurso del tiempo, corresponden al acreedor. Si las mejoras se hicieren por el deudor con el consentimiento del acreedor, éste debe pagarlas. Estas normas serán aplicables siempre que la cosa sea entregada al acreedor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7111224b-258f-4183-8fa4-96c159323461', 'd40d8568-f2b7-485e-a204-1238280495de', 2, 'OBLIGACIONES ALTERNATIVAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e842a206-56c6-4000-998e-6ae79afdc3c3', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1334', NULL, 1216, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('381d1da8-ce5f-48bb-8d8a-2aa1fdb61119', 'e842a206-56c6-4000-998e-6ae79afdc3c3', 1, 'El obligado alternativamente a diversas prestaciones, cumple ejecutando íntegramente una de ellas. El acreedor no puede ser compelido a recibir parte de una y parte de otra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9cd23168-80d2-48d5-90ce-ba07af192130', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1335', NULL, 1217, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0a7b5917-1c3b-4e39-bf7b-96c5c9494377', '9cd23168-80d2-48d5-90ce-ba07af192130', 1, 'La elección corresponde al deudor, a menos que expresamente se concediere al acreedor. La elección no puede recaer en prestaciones que resultaren imposibles, ilícitas o que no hubieran podido ser objeto de la obligación.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('89af348e-c1de-485d-a81e-6f30f4f4565a', '9cd23168-80d2-48d5-90ce-ba07af192130', 2, 'La elección no producirá efectos sino desde que fuere notificada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9eec9ff7-56a6-4bc3-80cd-69e275647099', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1336', NULL, 1218, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a3a9a44-b497-4343-83cf-555292b7cd3f', '9eec9ff7-56a6-4bc3-80cd-69e275647099', 1, 'El deudor perderá el derecho de elección cuando de las prestaciones a que alternativamente estuviere obligado, solo una fuere realizable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cb89a975-efdb-4733-81ec-a789abef34a7', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1337', NULL, 1219, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afd2e201-a8db-4283-924f-bf5af57277bc', 'cb89a975-efdb-4733-81ec-a789abef34a7', 1, 'El acreedor tendrá derecho a la indemnización de daños y perjuicios cuando, por culpa del deudor hubieren desaparecido todas las cosas que alternativamente fueron objeto de la obligación, o se hubiera hecho imposible el cumplimiento de ésta. La indemnización se fijará tomando por base el valor de la última cosa desaparecida o el del servicio que últimamente se hubiere hecho imposible.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e026dede-628d-40ce-84b0-5ab3b716d06d', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1338', NULL, 1220, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1cdf1761-1435-45a7-85eb-62f8aac3f8cb', 'e026dede-628d-40ce-84b0-5ab3b716d06d', 1, 'Cuando la elección corresponde al acreedor, la obligación cesará de ser alternativa desde el día en que haya sido notificada al deudor. Mientras no se hubiere hecho la notificación, las responsabilidades del deudor se regirán por las reglas siguientes:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb0bcb2f-8888-4928-b60f-62ffef9d12fe', 'e026dede-628d-40ce-84b0-5ab3b716d06d', 2, '1. Si alguna de las cosas se perdió sin culpa del deudor, cumplirá entregando la que el acreedor elija entre las restantes o la que haya quedado si una sola subsistiera;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd643a6a-8854-420d-a9e6-6f83446be9c1', 'e026dede-628d-40ce-84b0-5ab3b716d06d', 3, '2. Si la pérdida de alguna de las cosas sobrevino por culpa del deudor, el acreedor podrá reclamar cualquiera de las que subsistan, o el precio de la que, por culpa de aquél, hubiera desaparecido; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5934888f-9af0-4cec-a117-24d66071ed28', 'e026dede-628d-40ce-84b0-5ab3b716d06d', 4, '3. Si todas las cosas se hubieren perdido por culpa del deudor, la elección del acreedor recaerá sobre su precio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e7e63b0-0671-44fa-91bc-ab2bc8d6e575', 'e026dede-628d-40ce-84b0-5ab3b716d06d', 5, 'Las mismas reglas se aplicarán a las obligaciones de hacer o de no hacer, en el caso de que algunas o todas las prestaciones resultaren imposibles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a02beccf-fc1c-495e-85f9-c08b9cf7f1de', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1339', NULL, 1221, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c491df91-7808-4b77-8506-297300a6cd8d', 'a02beccf-fc1c-495e-85f9-c08b9cf7f1de', 1, 'Cuando la elección debe ser hecha por varias personas, el juez concederá un plazo para que se pongan de acuerdo. Si no hubiere acuerdo decidirá la mayoría, y si no hicieren la elección o no hubiere mayoría, elegirá el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f6f3db36-6639-43bb-9b8e-b389fd8b9c05', 'a0000000-0000-0000-0000-000000000001', '4c92f41e-9e79-4eca-873b-f4aa8cbd6d28', '1340', NULL, 1222, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0961216-6119-4dee-a10f-99bef4c008cf', 'f6f3db36-6639-43bb-9b8e-b389fd8b9c05', 1, 'Si el deudor es omiso en hacer la elección, el juez le señalará un plazo para que cumpla con hacerla, y si vencido este plazo el deudor se mantuviera en la omisión, la elección corresponderá al acreedor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afeac519-0f28-480a-9401-76525a1da3e6', 'f6f3db36-6639-43bb-9b8e-b389fd8b9c05', 2, 'OBLIGACIONES FACULTATIVAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dcea198c-e56e-4b34-9f3b-47b7e0eec97f', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1341', NULL, 1223, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14f36860-e984-4637-91cc-7fa9ac695503', 'dcea198c-e56e-4b34-9f3b-47b7e0eec97f', 1, 'Obligación facultativa es la que, no teniendo por objeto sino una sola prestación, da al deudor el derecho de sustituir esa prestación por otra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('263b453b-7362-4bae-9c00-4f10c7daa0f7', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1342', NULL, 1224, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d03a1e6-97f2-4f36-bd9d-0672410af34b', '263b453b-7362-4bae-9c00-4f10c7daa0f7', 1, 'La naturaleza de la obligación facultativa se determina únicamente por la prestación principal que forma el objeto de ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bc5be936-d79b-4d19-871f-34fc2b25b202', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1343', NULL, 1225, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56a4a473-f717-4996-9e87-db2a3f912475', 'bc5be936-d79b-4d19-871f-34fc2b25b202', 1, 'La obligación facultativa será nula por un vicio inherente a la prestación principal, aunque la prestación accesoria no tenga vicio alguno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7027c17c-8893-4fcb-a75b-b374f9232e6f', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1344', NULL, 1226, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46a53dbb-ee27-4ad1-942d-45f617dcbbfa', '7027c17c-8893-4fcb-a75b-b374f9232e6f', 1, 'La obligación facultativa se extingue cuando la cosa que forma el objeto de la prestación principal perece sin culpa del deudor, antes que éste se haya constituido en mora, o porque se hubiere hecho imposible su cumplimiento, aunque el objeto de la prestación accesoria no hubiese perecido y fuese posible su entrega.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('249c970e-8301-41b9-b58b-9cadc4965496', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1345', NULL, 1227, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7b68629-ea8d-4868-95d6-8608fdea778c', '249c970e-8301-41b9-b58b-9cadc4965496', 1, 'No tendrán influencia alguna sobre la prestación principal, ni la pérdida o deterioro de la cosa ni la imposibilidad del hecho o de la omisión que constituye el objeto de la prestación accesoria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2961fc7e-0734-4dc6-aed4-0d68bb7e255a', 'a0000000-0000-0000-0000-000000000001', 'cfb259e6-d6b2-4099-acf2-b272e1456504', '1346', NULL, 1228, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3c3968b9-f0ac-47bd-943f-bcbae2470d52', '2961fc7e-0734-4dc6-aed4-0d68bb7e255a', 1, 'En caso de duda sobre si la obligación es alternativa o facultativa, se tendrá por facultativa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34d89989-9785-40af-9ddc-afabf27b66a1', '2961fc7e-0734-4dc6-aed4-0d68bb7e255a', 2, 'OBLIGACIONES MANCOMUNADAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('395f25a0-4b3a-47b2-937c-4569c26d188c', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1347', NULL, 1229, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5bccc1d-33ca-4646-94c3-69bf0c1319a1', '395f25a0-4b3a-47b2-937c-4569c26d188c', 1, 'Hay mancomunidad cuando en la misma obligación son varios los acreedores o varios los deudores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('94b89534-956d-493e-b77c-97817a117a93', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1348', 'Mancomunidad simple', 1230, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fbb8443e-addb-4cf4-9f63-c9ac87c809b1', '94b89534-956d-493e-b77c-97817a117a93', 1, 'Por la simple mancomunidad no queda obligado cada uno de los deudores a cumplir íntegramente la obligación, ni tiene derecho cada uno de los acreedores para exigir el total cumplimiento de la misma. En este caso, el crédito o la deuda se consideran divididos en tantas partes como acreedores o deudores haya, y cada parte constituye una deuda o un crédito separados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('776be906-1e5a-47c7-87c3-d4f96eff80e5', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1349', NULL, 1231, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('165649f8-1e76-442d-9bbd-e287bc0eb91d', '776be906-1e5a-47c7-87c3-d4f96eff80e5', 1, 'Los actos de uno solo de los acreedores, dirigidos contra uno solo de los deudores, no aprovechan a los otros acreedores ni perjudican a los otros deudores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec56fb67-c1cd-44c0-9e08-0eae617a29b4', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1350', NULL, 1232, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc7b7313-5b16-4d72-9e7d-ca6dbc68d290', 'ec56fb67-c1cd-44c0-9e08-0eae617a29b4', 1, 'La mora o la culpa de uno de los deudores no afecta a los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d64cb99b-10c8-4964-b5a8-e66bc9b2e554', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1351', NULL, 1233, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('662e8972-360e-44cc-a383-be5e5fb31294', 'd64cb99b-10c8-4964-b5a8-e66bc9b2e554', 1, 'Para que la prescripción de una obligación se interrumpa respecto de todos los deudores, se requiere la citación de todos ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('030c4b43-b3d9-4724-a416-1f4896a65a37', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1352', 'Mancomunidad solidaria', 1234, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c4e44d1-c87e-4e39-b6f6-82060943c57a', '030c4b43-b3d9-4724-a416-1f4896a65a37', 1, 'La obligación mancomunada es solidaria cuando varios deudores están obligados a una misma cosa, de manera que todos o cualquiera de ellos pueden ser constreñidos al cumplimiento total de la obligación, y el pago hecho por uno solo libera a los demás; y es solidaria con respecto a los acreedores cuando cualquiera de ellos tiene el derecho de exigir la totalidad del crédito, y el pago hecho a uno de ellos libera al deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('98a97e6e-d9f9-41d9-af7c-66d9719a30f7', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1353', NULL, 1235, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9cdf294d-e185-42cc-acb1-92462afb9657', '98a97e6e-d9f9-41d9-af7c-66d9719a30f7', 1, 'La solidaridad no se presume; debe ser expresa por convenio de las partes o por disposición de la ley. La solidaridad expresa podrá pactarse aunque los acreedores o deudores no se obliguen del mismo modo ni por plazos, ni condiciones iguales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('68f4b77f-4f47-4939-91f0-7cab1d4d6581', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1354', NULL, 1236, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94b3fdd8-edb6-4f65-93c4-d63e0ac7e052', '68f4b77f-4f47-4939-91f0-7cab1d4d6581', 1, 'Cada uno de los acreedores o deudores solidarios puede hacer todo lo que sea útil a los demás, pero no lo que les sea perjudicial. La acción ejercitada contra cualquiera de los deudores solidarios perjudica a todos ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60b8d4d1-fb28-41f3-912a-89b974d2cd33', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1355', NULL, 1237, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cbebb419-63d1-427e-b457-46e072f557c1', '60b8d4d1-fb28-41f3-912a-89b974d2cd33', 1, 'El deudor podrá hacer el pago a cualquiera de los acreedores solidarios, pero si hubiere sido demandado por alguno de ellos, a éste hará el pago con notificación de los demás interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ebb3610-9298-4357-80f8-d10eee603dff', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1356', NULL, 1238, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('68e67bdb-54f0-49eb-a1b6-174126c958be', '9ebb3610-9298-4357-80f8-d10eee603dff', 1, 'Cada uno de los deudores solidarios es responsable del hecho propio para con sus codeudores en el cumplimiento de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b624ca72-4aac-4a75-b385-d042b46c172d', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1357', NULL, 1239, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0732e48-26a0-48c5-830e-c228e82b026d', 'b624ca72-4aac-4a75-b385-d042b46c172d', 1, 'El acreedor puede dirigirse contra cualquiera de los deudores solidarios, o contra todos ellos simultáneamente. La reclamación entablada contra uno no será obstáculo para las que se dirijan posteriormente contra los demás, mientras la obligación no estuviere totalmente satisfecha.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('990739c5-e67b-4df3-8b00-e05261ee25a7', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1358', NULL, 1240, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab39a294-711e-4b5e-af63-1e99f71cf7c3', '990739c5-e67b-4df3-8b00-e05261ee25a7', 1, 'El pago total por uno de los deudores solidarios extingue la obligación. El deudor que hizo el pago total puede reclamar de sus codeudores la parte que a cada uno de ellos corresponde en la obligación, con los intereses respectivos y gastos necesarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d62556c6-a90a-447a-a8ee-62d5fc3291e5', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1359', NULL, 1241, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d380f8c5-028f-46fc-9d12-356317f57afe', 'd62556c6-a90a-447a-a8ee-62d5fc3291e5', 1, 'Si uno de los deudores solidarios resulta insolvente, la parte que le corresponde en la obligación se distribuirá a prorrata entre los codeudores solventes y el que hizo el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a4a5f9e7-7ea2-4292-b471-b1713fe217cc', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1360', NULL, 1242, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('532b517a-2b5e-49ee-916f-6ca137bc482e', 'a4a5f9e7-7ea2-4292-b471-b1713fe217cc', 1, 'El deudor solidario podrá utilizar contra el acreedor todas las excepciones que le sean personales, las que se originen de la naturaleza de la obligación y las comunes a todos los codeudores. El deudor solidario que no opone la prescripción, o las excepciones comunes a todos los codeudores, pierde el derecho de repetir contra los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ac1a5baf-f9e3-4b50-adbf-85bb3f906206', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1361', NULL, 1243, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57c64834-801f-4b7d-ad95-7fab35c9d943', 'ac1a5baf-f9e3-4b50-adbf-85bb3f906206', 1, 'Cualquier acto que interrumpa la prescripción en favor de uno de los acreedores o en contra de uno de los deudores solidarios, aprovecha o perjudica a los restantes, siempre que el tiempo exigido por la ley haya debido correr del mismo modo para todos ellos. El acreedor sólo podrá exigir a los deudores, cuyas obligaciones no hayan prescrito, el valor de éstas, deducida la parte que corresponde a los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6c42735e-4630-4ce0-8884-612670a8e489', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1362', NULL, 1244, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50ed4b71-0856-4770-a8be-e47b3b3b6f24', '6c42735e-4630-4ce0-8884-612670a8e489', 1, 'Si el acreedor de uno de los deudores solidarios, sólo exige de él la parte que le corresponde, no se entenderá interrumpida la prescripción respecto de los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d6289a7-a171-4bd9-aff3-8b179b62d24a', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1363', NULL, 1245, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a4cc84de-53c3-4e17-bbc0-88dd26194b7b', '2d6289a7-a171-4bd9-aff3-8b179b62d24a', 1, 'La sentencia condenatoria obtenida por uno de los acreedores solidarios contra el deudor común, aprovecha a los otros. La sentencia absolutoria del deudor aprovecha a éste contra todos los acreedores solidarios, a menos que haya sido fundada en una causa personal del acreedor demandante.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a06f678-705a-4700-9b56-da1ea5cbe4c3', '2d6289a7-a171-4bd9-aff3-8b179b62d24a', 2, 'ARTICULO 1364. La novación hecha por el acreedor con uno de los deudores solidarios libera a todos los codeudores. Sin embargo, si el acreedor ha exigido la adhesión de los codeudores y éstos la han rehusado, el primitivo crédito subsiste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d319f31-2f22-45d7-a503-3de50fa89130', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1365', NULL, 1246, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('466095fe-c95c-4b26-b94d-c72deffea802', '2d319f31-2f22-45d7-a503-3de50fa89130', 1, 'La novación o transacción hecha entre uno de los acreedores solidarios y el deudor común, sólo afecta la parte del acreedor que las celebró.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1a477759-93da-4009-a1ce-22be3cae1612', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1366', NULL, 1247, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99b35f17-3c43-416d-af19-c42c3be17966', '1a477759-93da-4009-a1ce-22be3cae1612', 1, 'El pago parcial aceptado por el acreedor y la quita o remisión que hiciere a uno de los deudores solidarios, no altera sus derechos por el resto de la deuda, ni los de los deudores entre sí.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('803b477f-514c-4849-90f7-519a58724aa3', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1367', NULL, 1248, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0dd3d96b-027c-4e7a-826a-c96b800f97de', '803b477f-514c-4849-90f7-519a58724aa3', 1, 'Si uno de los acreedores solidarios libera solamente a uno de los deudores solidarios, ese hecho no altera los derechos de los demás acreedores ni las obligaciones de los demás deudores por el resto de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d9e0ca0-2483-4d1c-ae61-e9fc3096a9ff', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1368', NULL, 1249, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7ebdf027-14c1-4591-8e32-e5984e9736c5', '2d9e0ca0-2483-4d1c-ae61-e9fc3096a9ff', 1, 'La confusión libera a los otros codeudores por la parte de aquél en cuya persona se han reunido las calidades de acreedor y de deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e83c945a-258a-46e2-9349-e9969ccc7068', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1369', NULL, 1250, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('942460ed-037a-42f8-befd-fef881ceb5da', 'e83c945a-258a-46e2-9349-e9969ccc7068', 1, 'El deudor solidario no puede oponer compensación al acreedor por lo que éste deba a otro de los codeudores solidarios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fe9f88cc-679b-4bc6-a697-c3a2317fcd31', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1370', NULL, 1251, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7545668-7e56-4f7e-86c9-6d19a9c0240f', 'fe9f88cc-679b-4bc6-a697-c3a2317fcd31', 1, 'Si el acreedor hubiere renunciado a la solidaridad respecto a uno de los codeudores y otro de ellos cae en insolvencia, la parte de deuda del insolvente será repartida proporcionalmente entre todos los deudores, comprendiendo al que había sido liberado de la solidaridad. Sin embargo, si se comprueba que el acreedor quiso liberar de toda obligación al deudor, respecto del cual renunció a la solidaridad, la parte proporcional de éste quedará a cargo del acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('752b53be-15fc-44da-a2f7-37fe44bd3ea4', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1371', NULL, 1252, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('43a7b55d-dd2e-48bb-bef0-7f861d99d91d', '752b53be-15fc-44da-a2f7-37fe44bd3ea4', 1, 'Si la cosa debida perece por culpa de cualquiera de los deudores solidarios, todos serán solidariamente responsables del precio y de los daños y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72b36c6c-317c-4edf-9cc4-1f976d7c766e', '752b53be-15fc-44da-a2f7-37fe44bd3ea4', 2, 'perjuicios. Los deudores solidarios no culpables tendrán derecho a que el culpable reintegre la parte de precio que le corresponde y la totalidad de los daños y perjuicios pagados al acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('806e3173-541f-4121-97ee-a9064d31478a', 'a0000000-0000-0000-0000-000000000001', '0c8288db-1c71-4042-9a90-643cb41459f8', '1372', NULL, 1253, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('07ab762e-599a-4e8a-9b3a-7994c819d805', '806e3173-541f-4121-97ee-a9064d31478a', 1, 'Cada uno de los sucesores de un deudor solidario estará obligado a pagar la cuota que le corresponde en proporción a su haber hereditario, salvo que la obligación sea indivisible; pero todos los sucesores serán considerados en conjunto como un solo deudor solidario, con relación a los otros deudores.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ffe2e458-15a6-4316-a3de-b349cbf3d25c', '806e3173-541f-4121-97ee-a9064d31478a', 2, 'OBLIGACIONES DIVISIBLES E INDIVISIBLES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cac55786-a5c3-4747-b63b-18aa90a3e80a', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1373', NULL, 1254, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d481360b-f469-43ee-b13d-895724916ea0', 'cac55786-a5c3-4747-b63b-18aa90a3e80a', 1, 'Las obligaciones son divisibles cuando su objeto es susceptible de cumplirse parcialmente; e indivisibles si las prestaciones no pueden ser cumplidas sino por entero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('edfe3ae8-a7b4-422d-94b9-631ab2d73217', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1374', NULL, 1255, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b18d0d62-eba6-486e-95e3-3e3a43faa4c2', 'edfe3ae8-a7b4-422d-94b9-631ab2d73217', 1, 'El deudor no puede obligar al acreedor a recibir por partes el pago de una deuda aunque ésta sea divisible, salvo convenio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('87892ed1-08ea-4399-a879-a4cec2290bf0', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1375', NULL, 1256, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38c3c984-97f1-445a-bbca-ae1554bb8b0f', '87892ed1-08ea-4399-a879-a4cec2290bf0', 1, 'La solidaridad no da a la obligación el carácter de indivisible, ni la indivisibilidad de la obligación la hace solidaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('236fcee2-b55a-4167-bb04-a808357d9ca8', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1376', NULL, 1257, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e45015d-b969-497e-8f77-b650209d1bbf', '236fcee2-b55a-4167-bb04-a808357d9ca8', 1, 'La obligación se considera indivisible: 1. Cuando tiene por objeto la entrega de un cuerpo cierto;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('010b50e0-83ee-4218-bb78-109c221515b6', '236fcee2-b55a-4167-bb04-a808357d9ca8', 2, '2. Cuando uno solo de los deudores está encargado de ejecutar la prestación; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2331022-3e71-495a-a856-376146f52a63', '236fcee2-b55a-4167-bb04-a808357d9ca8', 3, '3. Cuando las partes convienen expresamente en que la prestación no pueda satisfacerse parcialmente o cuando por la naturaleza de la obligación sea imposible su cumplimiento parcial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('77115950-0c3c-49ca-ab5b-be28428fd4cf', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1377', NULL, 1258, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42c51e90-6cb6-49a5-98a6-cdf69a016a8a', '77115950-0c3c-49ca-ab5b-be28428fd4cf', 1, 'En las obligaciones indivisibles, el acreedor no puede dirigir su acción contra uno solo de los deudores, sino contra todos a la vez, salvo que uno solo esté encargado de ejecutar la prestación, en cuyo caso, el deudor tiene derecho de pedir que se cite y emplace a sus codeudores para el efecto de repetir contra ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a17d06db-de6a-4cd0-8616-1238bfe3f200', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1378', NULL, 1259, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ac43b9e-efaf-4031-b93d-50d5ca401b51', 'a17d06db-de6a-4cd0-8616-1238bfe3f200', 1, 'Cuando es indivisible la obligación contraída con cláusula de indemnización, se incurre en ésta por culpa de cualquiera de los deudores; pero los codeudores no culpables tendrán derecho a que el culpable les reintegre la parte que hubiere tenido que pagar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af17b489-fd8e-4865-a25d-b73384a918e3', 'a0000000-0000-0000-0000-000000000001', '8d47bd53-909b-451a-a562-555b723a2476', '1379', NULL, 1260, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f708c552-2fe6-4686-8b49-eefca36bc7c3', 'af17b489-fd8e-4865-a25d-b73384a918e3', 1, 'Si es divisible la obligación contraída con cláusula de indemnización, o simplemente mancomunada, será obligada a pagarla solamente el deudor que contravino a la obligación y por la parte que le corresponde.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72817b9d-7d87-42cc-82ed-d337ce2aabb0', 'af17b489-fd8e-4865-a25d-b73384a918e3', 2, 'CUMPLIMIENTO DE LAS OBLIGACIONES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('80c4ee61-6f91-4a41-b53b-73f5acc0d975', 'af17b489-fd8e-4865-a25d-b73384a918e3', 3, 'PARRAFO I Pago');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('02c257ab-f7a9-4ad7-b1c3-cb7a0b7e628d', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1380', NULL, 1261, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('39c60f91-e0a5-4163-8a62-2aa2a5f31382', '02c257ab-f7a9-4ad7-b1c3-cb7a0b7e628d', 1, 'El cumplimiento de la prestación puede ser ejecutado por un tercero, tenga o no interés y ya sea consintiendo o ignorándolo el deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3c72cf68-3f2c-4fc7-a1ca-cfad48ff363f', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1381', NULL, 1262, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fabf5c45-1d76-4709-8f4f-8a8a6f1234de', '3c72cf68-3f2c-4fc7-a1ca-cfad48ff363f', 1, 'En las obligaciones de hacer, el acreedor no puede ser compelido a recibir la prestación o el servicio de un tercero, cuando la calidad y circunstancias de la persona del deudor hubieren sido motivo determinante al establecer la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3f6bebbd-8916-4fa7-9b4e-b3e8f5cba876', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1382', NULL, 1263, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('863a510e-da99-4185-bf97-faa0a42a1bbd', '3f6bebbd-8916-4fa7-9b4e-b3e8f5cba876', 1, 'El que pague por cuenta de otro puede repetir lo que pagó, a no ser que lo hubiere hecho contra la voluntad expresa del deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9173a19f-cb9f-4230-be6e-94ebbaa73686', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1383', NULL, 1264, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('748a99c7-2b63-400c-984e-f42384f02b7c', '9173a19f-cb9f-4230-be6e-94ebbaa73686', 1, 'Para hacer pago válidamente en las obligaciones de dar en que se ha de transferir la propiedad de la cosa, es necesario ser dueño de lo que se da en pago y tener capacidad para enajenarlo. Sin embargo, si el pago hubiere consistido en una cantidad de dinero u otra cosa fungible, no habrá repetición contra el acreedor que la hubiere gastado o consumido de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cf9f7893-2d84-496e-9e7c-73ff551bd9ee', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1384', NULL, 1265, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('89f2b22d-f287-4d18-8ca0-0a05ad117ac1', 'cf9f7893-2d84-496e-9e7c-73ff551bd9ee', 1, 'El pago debe hacerse al acreedor o a quien tenga su mandato o representación legal. El pago hecho a quien no tuviere facultad para recibirlo, es válido si el acreedor lo ratifica o se aprovecha de él.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2b6fe2c8-f583-4786-9411-39399f6f14bd', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1385', NULL, 1266, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2598adf-3979-49ab-81fc-6b470090142d', '2b6fe2c8-f583-4786-9411-39399f6f14bd', 1, 'No es válido el pago que se haga directamente al menor o incapaz. Sin embargo, si lo pagado se invirtió en su beneficio personal o en la conservación de su patrimonio, se extingue la obligación en la parte invertida en esos fines.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83c97418-51a9-40c8-981a-e0abced1eda1', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1386', NULL, 1267, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a928a920-774d-40a2-9f52-e97f236bd41a', '83c97418-51a9-40c8-981a-e0abced1eda1', 1, 'No se puede obligar al acreedor a aceptar cosa distinta de la que se le debe, aunque el valor de la ofrecida sea igual o mayor, salvo disposición especial de la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e3d4a84-cdd5-4f38-9397-85fe643a9821', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1387', NULL, 1268, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c5e265a1-44fa-4eea-bae7-72a5f072f756', '8e3d4a84-cdd5-4f38-9397-85fe643a9821', 1, 'El pago deberá hacerse del modo que se hubiere pactado, y no podrá efectuarse parcialmente sino por convenio expreso por disposición de la ley. Sin embargo, cuando la deuda tuviere una parte líquida y otra ilíquida, podrá el acreedor exigir el pago de la primera sin esperar a que se liquide la segunda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6238c229-0fda-412f-b2e8-0e64059df12c', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1388', NULL, 1269, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2bbfd8e4-e9f8-431a-adf7-db1cd566c6bf', '6238c229-0fda-412f-b2e8-0e64059df12c', 1, 'No extingue la obligación el deudor que paga a su acreedor después de estar notificado judicialmente para que no lo verifique.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('faaffa89-3919-4f82-a691-d9db640e2aba', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1389', NULL, 1270, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46537ce4-7619-498b-ab99-5f85de3d23a5', 'faaffa89-3919-4f82-a691-d9db640e2aba', 1, 'Es válido el pago hecho de buena fe al que está en posesión del derecho de cobrar, aunque sea después vencido en juicio sobre la propiedad del crédito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c994948c-e137-44f9-ac82-e50c153bbf69', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1390', NULL, 1271, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f077df62-e389-4b21-b557-0c67a5f0ed86', 'c994948c-e137-44f9-ac82-e50c153bbf69', 1, 'El deudor que paga tiene derecho de exigir el documento que acredite el pago; y de retener éste mientras dicho documento no le sea entregado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a61f3c3-8b49-42e7-954f-fe88f20138d7', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1391', NULL, 1272, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('80c29962-0bcf-4dbf-b980-7e321a08de82', '6a61f3c3-8b49-42e7-954f-fe88f20138d7', 1, 'El portador de un recibo se reputa autorizado para recibir el pago, a menos que las circunstancias se opongan a admitir esta presunción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83999086-328e-4106-ab2a-89b5ef166aa6', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1392', NULL, 1273, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf917b65-928d-4ef5-9204-6bc1bce2afca', '83999086-328e-4106-ab2a-89b5ef166aa6', 1, 'La entrega del documento original que justifica el crédito, hecha por el acreedor al deudor, hace presumir la liberación de éste, mientras no se pruebe lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e20d2ac3-46ef-44af-a1df-d63bdd648af8', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1393', NULL, 1274, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('921ff2c6-af6a-481a-bb03-c2f4c205bab1', 'e20d2ac3-46ef-44af-a1df-d63bdd648af8', 1, 'El pago hecho al tenedor de un título al portador extingue la deuda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ee6d8d5e-3f00-4233-9211-337f277db31f', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1394', NULL, 1275, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f15bf822-38ed-46f8-a37a-ccb6aea5ec48', 'ee6d8d5e-3f00-4233-9211-337f277db31f', 1, 'El pago hecho por medio de cheque, queda sujeto a la condición de que éste se haga efectivo a su presentación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e594ab38-fa7f-421e-a4cf-412493b5e53e', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1395', NULL, 1276, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('09ff0ac2-757f-42f3-85f3-825183e1035f', 'e594ab38-fa7f-421e-a4cf-412493b5e53e', 1, 'El pago en moneda nacional lo hará el deudor entregando igual cantidad numérica con arreglo al valor nominal que tenga la moneda en la fecha en que se le requiera de pago, siempre que ya sea exigible la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83c0577d-f500-4784-a7aa-b068575475f3', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1396.27', NULL, 1277, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42db081f-d3e9-4a04-a4f3-1c3d6274b98b', '83c0577d-f500-4784-a7aa-b068575475f3', 1, 'Derogado');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e330f21c-55f2-4836-97f5-78d8f16a764a', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1397', NULL, 1278, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0dbace5-d06e-40ab-b753-1d0be5cc1677', 'e330f21c-55f2-4836-97f5-78d8f16a764a', 1, 'Si el pago tuviere que hacerse en especie y hubiere imposibilidad de entregar la misma cantidad y calidad, el deudor satisfará el valor que la cosa tenga en el tiempo y lugar señalados para el pago, salvo que se haya fijado precio al celebrarse el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('da9405be-79a9-4b6d-a4ae-5925caadbcda', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1398', 'El pago se hará en el lugar designado en el contrato', 1279, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec5bbc38-badc-4ec4-8351-03ba4df23a48', 'da9405be-79a9-4b6d-a4ae-5925caadbcda', 1, 'Si no se designó y se trata de cosa cierta y determinada, se hará el pago en lugar en que la cosa existía al tiempo de contraerse la obligación. En cualquier otro caso, el pago debe hacerse en el domicilio del deudor al tiempo de exigirse la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78ce6ebd-d25e-42af-8c22-23b38e3dcc6d', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1399', NULL, 1280, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('60eb77d1-321d-4d86-937a-cf42458c3449', '78ce6ebd-d25e-42af-8c22-23b38e3dcc6d', 1, 'Los gastos extrajudiciales y judiciales que ocasione el pago serán cubiertos por el deudor, debiendo los últimos ser fijados por el juez con arreglo a la ley.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3579cb7a-a618-456e-82c0-6e201bedd91c', '78ce6ebd-d25e-42af-8c22-23b38e3dcc6d', 2, '27 Derogado por el Artículo 28 del Decreto No. 17-2002, publicado el 01 de junio de 2002.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ddc1aaa6-768d-463f-81a6-0a3a08c5155d', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1400', NULL, 1281, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45eb705b-c190-4f9b-9f13-ecd444f7895b', 'ddc1aaa6-768d-463f-81a6-0a3a08c5155d', 1, 'El acreedor que después de celebrado el contrato cambia voluntariamente de domicilio, deberá indemnizar al deudor los gastos que haga por este motivo para efectuar el pago, si la obligación debe cumplirse en el domicilio de aquél.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('39de64c5-3588-4090-85dd-2c524df56ff9', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1401', NULL, 1282, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e41e4fe-973a-4bc4-9817-6804e05822d5', '39de64c5-3588-4090-85dd-2c524df56ff9', 1, 'Las obligaciones deben ser ejecutadas sin demora, a no ser que circunstancias relativas a su naturaleza, modo o lugar fijado para el cumplimiento, impliquen la necesidad de un plazo, que fijará el juez prudencialmente si no estuviere señalado por la ley. Si las partes hubieren señalado plazo, el pago debe ser hecho el día de su vencimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('01e74007-f240-4a19-8767-6a5dfc4242f6', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1402', NULL, 1283, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52821e5c-7e88-437b-a393-99aca510e057', '01e74007-f240-4a19-8767-6a5dfc4242f6', 1, 'En los pagos periódicos la constancia de pago del último período hace presumir el pago de los anteriores, salvo prueba en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('692d83cf-72ae-4f55-8802-4fd062d3fc96', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1403', NULL, 1284, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e98c39d-a542-4946-b454-c43c9305f250', '692d83cf-72ae-4f55-8802-4fd062d3fc96', 1, 'El pago del capital supone el de los intereses, salvo que se hubiere aceptado el pago con la reserva expresa correspondiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b8f1c19-e76d-4499-b3c0-62b73edc856a', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1404', NULL, 1285, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8674fde5-6807-4ee0-b3f1-654832447476', '7b8f1c19-e76d-4499-b3c0-62b73edc856a', 1, 'El deudor de diversas obligaciones a favor del mismo acreedor, tiene derecho a declarar al hacer el pago, a qué deuda debe aplicarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('284c7afa-b559-4b0c-996d-8e72e217ce0c', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1405', NULL, 1286, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2e4aec0-92a3-43fd-a723-70b2b44ec41e', '284c7afa-b559-4b0c-996d-8e72e217ce0c', 1, 'Si el deudor, no obstante la imputación hecha por él, aceptare recibo del acreedor imputando el pago a alguna deuda especialmente, no puede pedir que se aplique a otra, a menos que hubiere causa que invalide la imputación hecha por el acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c878bc3e-be01-4316-b02b-9001944a5356', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1406', NULL, 1287, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1aecdff6-d332-41d0-bc30-af13cf09caaa', 'c878bc3e-be01-4316-b02b-9001944a5356', 1, 'No expresándose a qué deuda debe hacerse la imputación, se entenderá aplicado el pago a la que sea de plazo vencido; si hay varias de plazo vencido a la que fuere más onerosa para el deudor; si son de igual naturaleza, a la más antigua; y si todas son iguales, el pago se imputará proporcionalmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5db0192-0757-4263-85fe-f12abe81a771', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1407', NULL, 1288, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f0da49e-d275-4507-9607-cc0557220a02', 'b5db0192-0757-4263-85fe-f12abe81a771', 1, 'El que debe capital e intereses no puede, sin consentimiento del acreedor, aplicar el pago al capital antes que a los intereses, ni éstos antes que a los gastos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('364cfa68-8e13-45be-9d06-dc631e23bd36', 'b5db0192-0757-4263-85fe-f12abe81a771', 2, 'PARRAFO II PAGO POR CONSIGNACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6c455b9f-b6ce-4289-8276-6e1925d8dcf3', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1408', NULL, 1289, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('86ffb832-6575-42bc-b18f-bf24dc25b387', '6c455b9f-b6ce-4289-8276-6e1925d8dcf3', 1, 'Se paga por consignación, depositando la suma o cosa que se debe ante un juez competente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1409', NULL, 1290, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03dc9bd7-a447-4598-90f6-1b3315b25d03', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 1, 'La consignación procede: 1. Cuando el acreedor se negare a recibir la cantidad o cosa que se le debe;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d6b12bf-c0ca-4d26-9e8e-2697dd711283', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 2, '2. Cuando el acreedor fuere incapaz de recibir el pago y careciere de representación legal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8158d3b4-56ea-451e-a108-a6a109a9846d', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 3, '3. Cuando el acreedor no se encuentre en el lugar en que debe hacerse el pago y no tuviere en dicho lugar apoderado conocido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fef8d4a-ba72-49ce-a416-8456062e8495', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 4, '4. Cuando fuere dudoso el derecho del acreedor y concurrieren otras personas a exigir el pago, o cuando el acreedor fuere desconocido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3598ed4c-c134-4dc6-bda6-3bc8386e7d70', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 5, '5. Cuando la deuda fuere embargada o retenida en poder del deudor, y éste quisiese exonerarse del depósito;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f331fa23-9474-4b34-8489-94f964b9f89d', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 6, '6. Cuando se hubiere perdido el título de la deuda;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1198246c-7e05-4e72-92ac-3bf2ed3bf345', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 7, '7. Cuando el rematario o adjudicatario de bienes gravados quiera redimirlos de las cargas que pesan sobre ellos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa480e14-0439-4714-8c5c-6456c82006dd', 'bd27c7e8-3812-4539-93ff-9fe3ca88a1b6', 8, '8. En cualquier otro caso en que el deudor no pueda hacer directamente un pago válido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5be521b5-da4b-4297-abef-ae5e80ab14e9', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1410', NULL, 1291, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0e96042-967b-4172-b101-2563f32c6f05', '5be521b5-da4b-4297-abef-ae5e80ab14e9', 1, 'Para que la consignación produzca efecto, es necesario: 1. Que se haga ante juez competente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2acc58de-3f21-4f2d-b41a-84a5debb418d', '5be521b5-da4b-4297-abef-ae5e80ab14e9', 2, '2. Que se haga por persona capaz o hábil para verificar el pago;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5dd786cf-a78d-44a7-adc7-066991abefbc', '5be521b5-da4b-4297-abef-ae5e80ab14e9', 3, '3. Que comprenda la totalidad de la deuda líquida y exigible, con sus intereses y costas si las hubiere; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8717e9ff-42d2-4ad2-810b-ad9b292b8800', '5be521b5-da4b-4297-abef-ae5e80ab14e9', 4, '4. Que esté cumplida la condición, si la deuda fuere condicional, o vencido el plazo si se estipuló en favor del acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('237674fc-0100-49e5-9620-12cf716fb759', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1411', NULL, 1292, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c6a6686-27c8-4447-a8a3-b51e3596b51a', '237674fc-0100-49e5-9620-12cf716fb759', 1, 'Declarada válida la consignación, la obligación quedará extinguida desde la fecha en que se hizo el depósito y, en consecuencia, los riesgos de la cosa pasan desde ese mismo día al acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fcba28ad-c6a6-4bb4-8fdc-2ff7577d4ea6', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1412', NULL, 1293, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f964a1c8-975d-434c-a5fc-fb88147c15cd', 'fcba28ad-c6a6-4bb4-8fdc-2ff7577d4ea6', 1, 'El deudor puede retirar la consignación mientras el acreedor no la haya aceptado o no fuere declarada válida. En tales casos, la obligación subsistirá con todas sus condiciones, modalidades y garantías.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('47717e0d-34b0-4c8c-b657-580fb6461759', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1413', NULL, 1294, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7817982b-e31c-4820-981b-fa9e5d1ec2dc', '47717e0d-34b0-4c8c-b657-580fb6461759', 1, 'Declarada válida la consignación, el deudor sólo puede retirarla con el consentimiento expreso del acreedor y, en tal caso, cesan las responsabilidades de los codeudores, fiadores y demás garantes de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e68f6e12-4b51-4123-ae04-7c061adccb87', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1414', NULL, 1295, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('02ba1150-3a59-47ac-9f43-c5ca5cdf89c5', 'e68f6e12-4b51-4123-ae04-7c061adccb87', 1, 'Si lo debido es cosa cierta y determinada que deba entregarse en el lugar en que se encuentra, el deudor, al ofrecer el pago, requerirá al acreedor para que');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dd9b6d82-9cf9-4625-a71e-8a6010ce763d', 'e68f6e12-4b51-4123-ae04-7c061adccb87', 2, 'la reciba, y si éste no la recibiere, podrá el deudor pedir al juez que la ponga en depósito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9902b8b1-1e9b-479a-a792-19fa0b713e67', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1415', NULL, 1296, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a8fb4b76-122d-4615-a8cf-0c0fb702cf14', '9902b8b1-1e9b-479a-a792-19fa0b713e67', 1, 'Si se tratare de un inmueble o de una cosa destinada a permanecer en el lugar, puede el deudor, después de requerir al acreedor para que la reciba y entre en posesión, obtener del juez el nombramiento de un interventor, si el acreedor se opusiere a recibirla. En los casos de este artículo y del anterior, una vez formalizado el depósito o la intervención a cargo de un tercero, el deudor quedará libre de responsabilidad.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e1070a92-9884-444e-8f04-53c333551022', '9902b8b1-1e9b-479a-a792-19fa0b713e67', 2, 'PARRAFO III Pago por cesión de bienes');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('de8d888f-544d-41c3-928a-51490a6862d5', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1416', NULL, 1297, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19604fb9-dfda-40ec-a093-bee6861f4183', 'de8d888f-544d-41c3-928a-51490a6862d5', 1, 'El deudor puede hacer cesión de bienes a sus acreedores cuando se encuentre en la imposibilidad de continuar sus negocios o de pagar sus deudas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fca40808-3b4d-47eb-ad32-1813d7361ccc', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1417', 'La cesión de bienes puede ser extrajudicial o judicial', 1298, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('04392cc6-e825-4542-b740-d701c6c808ff', 'fca40808-3b4d-47eb-ad32-1813d7361ccc', 1, 'La primera es contractual, y la segunda es un beneficio que se concede al deudor de buena fe que por accidentes inevitables o por causas que no le pueden ser imputadas, suspende el pago de sus deudas o está en inminente riesgo de suspenderlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c36eefe3-029f-459a-9827-67ce86157d39', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1418', NULL, 1299, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03438487-b06b-4497-b7e9-740e26b82f3a', 'c36eefe3-029f-459a-9827-67ce86157d39', 1, 'La cesión judicial de bienes debidamente aprobada, produce los efectos siguientes: 1. La separación del deudor de la administración de sus bienes, quien no podrá recibir pagos válidamente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('124ff812-45e4-41e6-adb9-a031b55644ab', 'c36eefe3-029f-459a-9827-67ce86157d39', 2, '2. La liquidación de los negocios del deudor, la realización de los bienes cedidos y el pago y cobro de las deudas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64dab513-911a-4a66-bd98-c25839f31e38', 'c36eefe3-029f-459a-9827-67ce86157d39', 3, '3. La suspensión definitiva de las ejecuciones entabladas contra el deudor y de los intereses respectivos, por créditos no garantizados con hipoteca, subhipoteca o prenda; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5cc8b810-3a62-4036-886b-3b86f45747bf', 'c36eefe3-029f-459a-9827-67ce86157d39', 4, '4. La extinción de las deudas en virtud de los pagos que se hagan, aunque lo que alcance cada acreedor no baste para el pago total, siempre que el que haga la cesión sea una persona individual.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef74317a-94e6-49cf-bcec-a1fe6fca633a', 'c36eefe3-029f-459a-9827-67ce86157d39', 5, 'Si fuere una sociedad y sus bienes no alcanzaren el pago total, subsistirá la responsabilidad de los socios conforme el contrato y naturaleza de la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('973d6981-dcd8-488e-9c9d-52f413a9f677', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1419', NULL, 1300, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8fcfa7e6-c2f2-4669-ada1-5103e1e1d4fd', '973d6981-dcd8-488e-9c9d-52f413a9f677', 1, 'Los acreedores, una vez aceptada la cesión judicial, pueden celebrar convenios con el deudor para la administración y venta de los bienes cedidos. En estos');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c15a7f0b-3c1b-43ed-aa99-43efe5ef43b4', '973d6981-dcd8-488e-9c9d-52f413a9f677', 2, 'arreglos se procederá conforme a las disposiciones del Código Procesal Civil y Mercantil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e6ee1d7-8b59-46b8-b3ee-bf561a159978', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1420', NULL, 1301, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d81bd21-5ca9-481f-a13b-2d0ae9dde414', '0e6ee1d7-8b59-46b8-b3ee-bf561a159978', 1, 'Dentro de un año posterior a la aprobación del convenio o de la cesión judicial, cualquiera de los acreedores puede impugnar la cesión por dolo o culpa del cedente; y si se comprobare que hubo dolo o culpa, quedarán subsistentes las obligaciones del deudor, sin perjuicio de otras responsabilidades.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e072a639-dd9f-4fd1-8e71-92e9612a46d6', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1421', NULL, 1302, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71fff548-caa4-49de-a07d-17778a5cbc1d', 'e072a639-dd9f-4fd1-8e71-92e9612a46d6', 1, 'El deudor puede recobrar los bienes o parte de ellos antes de su venta o adjudicación, pagando a los acreedores las deudas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('819356a4-379f-4d6a-9178-4d3dc9beed6c', 'a0000000-0000-0000-0000-000000000001', 'ac7765df-f30b-4c19-b354-2bbf2690588f', '1422', NULL, 1303, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35bed8cb-cf3b-4948-b2ff-b93bee1b883e', '819356a4-379f-4d6a-9178-4d3dc9beed6c', 1, 'La cesión judicial de bienes está sujeta al procedimiento señalado en el Código Procesal Civil y Mercantil; y el pago de los créditos deberá hacerse de conformidad con lo que disponga la ley para la graduación de acreedores.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc605cfc-0ef0-4139-88a1-59eac8f16629', '819356a4-379f-4d6a-9178-4d3dc9beed6c', 2, 'INCUMPLIMIENTO DE LAS OBLIGACIONES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec290b4c-97d4-4aee-90ba-a009d7e80de1', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1423', NULL, 1304, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8ddd8b3d-abdd-4e52-961b-e63bf784dc24', 'ec290b4c-97d4-4aee-90ba-a009d7e80de1', 1, 'El incumplimiento de la obligación por el deudor se presume por culpa suya mientras no pruebe lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('efa9121d-0cb2-48cd-aada-fca8446baf7a', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1424', 'Culpa', 1305, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d8da5149-3d55-4db6-8672-6c9e76b10ec3', 'efa9121d-0cb2-48cd-aada-fca8446baf7a', 1, 'La culpa consiste en una acción u omisión perjudicial a otro, en que se incurre por ignorancia, impericia o negligencia, pero sin propósito de dañar.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b95d49c4-ff28-4eb4-8ebe-6bd320f1bbcb', 'efa9121d-0cb2-48cd-aada-fca8446baf7a', 2, 'ARTICULO 1425. La responsabilidad por culpa debe graduarse atendiendo a la naturaleza de la obligación y a las circunstancias de las personas, de tiempo y de lugar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d57e6718-98de-4ab5-a14b-13f6d143c345', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1426', NULL, 1306, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0f02cf6-e83a-4326-8980-46135fe16b9e', 'd57e6718-98de-4ab5-a14b-13f6d143c345', 1, 'El deudor no es responsable de la falta de cumplimiento de la obligación por caso fortuito o fuerza mayor, a no ser que en el momento en que ocurriere, hubiere estado en mora.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38a4cf18-ebdd-4182-8197-b3882205056e', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1427', NULL, 1307, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('51ef1290-2db9-486b-9d79-63c9199e5826', '38a4cf18-ebdd-4182-8197-b3882205056e', 1, 'La deuda de cosa determinada proveniente de hechos ilícitos, obligará al responsable aun por caso fortuito o fuerza mayor, a no ser que habiendo ofrecido la cosa al que debió recibirla, éste se haya constituido en mora.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b875e4d7-d066-434c-ab6b-08df0253b158', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1428', 'Mora', 1308, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d9839cb-c7a4-42a2-9e08-35139872e291', 'b875e4d7-d066-434c-ab6b-08df0253b158', 1, 'El deudor de una obligación exigible se constituye en mora por la interpelación del acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8849d02a-e1fb-45b1-9e31-22547188c20f', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1429', NULL, 1309, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70c5659c-e3fe-4ab5-b47f-6d1e51ccfabf', '8849d02a-e1fb-45b1-9e31-22547188c20f', 1, 'El acreedor también incurre en mora cuando sin motivo legal no acepta la prestación que se le ofrece, o rehusa realizar los actos preparatorios que le incumben para que el deudor pueda cumplir su obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4bf60afc-3924-420b-996e-b2f30f0205ba', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1430', NULL, 1310, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c6dd5489-2e6a-4571-9ed7-2bd1f9698edd', '4bf60afc-3924-420b-996e-b2f30f0205ba', 1, 'El requerimiento para constituir en mora al deudor o al acreedor, debe ser judicial o notarial. La notificación de la demanda de pago equivale al requerimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65bf1051-74fa-4eee-9605-913d2bb0d6de', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1431', NULL, 1311, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d8e4a5f-3186-42e4-ad58-12e6f125ef74', '65bf1051-74fa-4eee-9605-913d2bb0d6de', 1, 'No es necesario el requerimiento: 1. Cuando la ley o el pacto lo declaran expresamente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('79e557a2-9ee2-40d3-a19c-efd722264e67', '65bf1051-74fa-4eee-9605-913d2bb0d6de', 2, '2. Cuando de la naturaleza y circunstancias de la obligación resultare que la designación de la época en que debía cumplirse la prestación, fue motivo determinante para que aquélla se estableciera;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2fb0f098-4e46-43ea-a320-f489cc757394', '65bf1051-74fa-4eee-9605-913d2bb0d6de', 3, '3. Cuando el cumplimiento de la obligación se ha imposibilitado por culpa del deudor, o éste ha declarado que no quiere cumplirla; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d647a980-8df8-490c-b8d2-ed2744d937ea', '65bf1051-74fa-4eee-9605-913d2bb0d6de', 4, '4. Cuando la obligación procede de acto o hecho ilícito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8124d458-224f-47d1-a6ca-3312620bf57f', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1432', NULL, 1312, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5028339-ccbb-4289-8832-ea315ffb172b', '8124d458-224f-47d1-a6ca-3312620bf57f', 1, 'En las obligaciones recíprocas ninguno de los obligados incurre en mora sino desde que alguno de ellos cumple su prestación o garantiza su cumplimiento en la parte que le concierne.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b66fe123-2c04-42f0-a542-829938e2f905', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1433', 'Daños y perjuicios', 1313, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d112c3e6-49fc-4853-aec1-03a4354335bf', 'b66fe123-2c04-42f0-a542-829938e2f905', 1, 'Establecida legalmente la situación de mora, el deudor está obligado a pagar al acreedor los daños y perjuicios resultantes del retardo, y corren a su cargo todos los riesgos de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b9d0388e-7dcd-4f32-b4f1-6eeb68664515', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1434', NULL, 1314, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e566e628-b8f0-4992-b89a-fa50286a5eef', 'b9d0388e-7dcd-4f32-b4f1-6eeb68664515', 1, 'Los daños, que consisten en las pérdidas que el acreedor sufre en su patrimonio, y los perjuicios, que son las ganancias lícitas que deja de percibir, deben ser consecuencia inmediata y directa de la contravención, ya sea que se hayan causado o que necesariamente deban causarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3aa2e9f8-dd87-499e-9fd5-d5d45ba9bff4', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1435', NULL, 1315, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27f7998d-6c37-4813-ba19-b5a3ed385468', '3aa2e9f8-dd87-499e-9fd5-d5d45ba9bff4', 1, 'Si la obligación consiste en el pago de una suma de dinero y el deudor incurre en mora, la indemnización de daños y perjuicios, no habiendo pacto en contrario, consistirá en el pago de los intereses convenidos y, a falta de convenio, en el interés legal hasta el efectivo pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9efee89f-676b-4dd3-b17a-f902511bf2cf', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1436', 'Cláusula de indemnización', 1316, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94890b4a-a96f-4427-a91b-a6f3bd0ab57a', '9efee89f-676b-4dd3-b17a-f902511bf2cf', 1, 'Las partes pueden fijar anticipadamente una cantidad que deberá pagar el que deje de cumplir la obligación, o no la cumpla de la manera convenida, o retarde su cumplimiento; la cual, en tales casos, compensa los daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('37b47e1a-cba6-4ab9-883f-88265e20a04b', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1437', NULL, 1317, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce0ee868-b4c1-45fe-adac-7d9060a940a8', '37b47e1a-cba6-4ab9-883f-88265e20a04b', 1, 'El acreedor puede exigir el cumplimiento de la obligación o el pago de la cantidad convenida, pero no las dos cosas, a no ser que ésta se exija por el simple retardo o por el cumplimiento imperfecto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a2baffde-2bbe-4ef4-ba74-3cb69c1d57d4', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1438', NULL, 1318, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12799d5f-0e93-4384-80aa-a13f142425a2', 'a2baffde-2bbe-4ef4-ba74-3cb69c1d57d4', 1, 'Si la obligación hubiere sido cumplida en parte, imperfectamente o con retardo, procederá la reducción proporcional de la cantidad indemnizatoria, y si las partes no se pusieren de acuerdo, la fijará el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67870869-18ea-44cd-8020-f94d6e8cdcd6', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1439', NULL, 1319, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b287f02-d130-4664-aada-d4c1d7ed128b', '67870869-18ea-44cd-8020-f94d6e8cdcd6', 1, 'En caso de exigirse la indemnización, el acreedor no está obligado a probar los daños y perjuicios, ni el deudor podrá eximirse de pagarla pretendiendo probar que no los hubo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52129021-2336-4127-9c5e-fd50a993797b', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1440', NULL, 1320, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f4b0ca34-10c2-44b6-9408-c6be1a78b480', '52129021-2336-4127-9c5e-fd50a993797b', 1, 'La indemnización convenida anticipadamente por las partes no puede exceder de la cuantía de la obligación principal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('daeab848-2b6b-4845-a412-b61cad3b2464', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1441', NULL, 1321, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ca1c035-ea54-4c1e-9517-ea4035417293', 'daeab848-2b6b-4845-a412-b61cad3b2464', 1, 'La cláusula de indemnización será insubsistente cuando se trate de asegurar con ella el cumplimiento de obligaciones que no pueden exigirse judicialmente, salvo los casos expresamente consignados en la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5a135f99-80e9-4957-8a65-89785a714837', 'a0000000-0000-0000-0000-000000000001', 'b56135a9-3077-494a-86c0-02366b3bec8a', '1442', NULL, 1322, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c26a0541-3bdc-4696-8a43-360d29676501', '5a135f99-80e9-4957-8a65-89785a714837', 1, 'Las arras dadas en garantía del cumplimiento de una obligación, constituyen el equivalente de los daños y perjuicios provenientes de la inejecución, siempre que mediare culpa; y si el incumplimiento procediere de quien las recibió, éste deberá restituir el doble de lo que hubiere recibido.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d53eb348-e9ca-46b4-b224-89d68f60cdd0', '5a135f99-80e9-4957-8a65-89785a714837', 2, 'TRANSMISION DE LAS OBLIGACIONES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9b6b6549-2bea-4ba7-b7ba-67f259380fd5', '5a135f99-80e9-4957-8a65-89785a714837', 3, 'CESION DE DERECHOS');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0774c768-e87c-419a-a26d-e269180faa37', '5a135f99-80e9-4957-8a65-89785a714837', 4, 'TRANSMISION DE LAS OBLIGACIONES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('114542f2-efcf-4fd3-bf26-003d2f4e2dfe', '5a135f99-80e9-4957-8a65-89785a714837', 5, 'CESION DE DERECHOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6d996eab-efae-4088-a118-46d6a791fc56', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1443', NULL, 1323, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40d59f4c-e12a-40c4-bfc6-932ab06f9a46', '6d996eab-efae-4088-a118-46d6a791fc56', 1, 'El acreedor puede ceder sus derechos sin el consentimiento del deudor, salvo que haya convenio en contrario o que no lo permita la ley o la naturaleza del derecho. En la cesión se observarán las disposiciones relativas al negocio jurídico que le dé origen, en lo que no estuvieren modificadas en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab110f52-466f-422b-ba8a-13515d3009e1', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1444', NULL, 1324, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('59990d9e-b30d-4f10-a18d-368bb8a330e1', 'ab110f52-466f-422b-ba8a-13515d3009e1', 1, 'La cesión comprende todos los derechos accesorios cuando no se pacte lo contrario. Cuando la cesión hubiere sido por menor valor del monto del crédito, el deudor podrá extinguir su obligación reembolsando al cesionario la cantidad que haya pagado por la cesión y los gastos que la misma le hubiere ocasionado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd8f9e08-d48e-4a37-88c0-b6cec2b0ddea', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1445', NULL, 1325, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1eb97058-377f-44a3-b787-0a6c3a6d7041', 'dd8f9e08-d48e-4a37-88c0-b6cec2b0ddea', 1, 'La cesión debe hacerse en escritura pública si se trata de derechos sobre inmuebles o que deben inscribirse en el Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9c325270-0763-4e06-9448-6ef4625c16b6', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1446', NULL, 1326, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9547bf39-49f9-45b8-8298-6e609ea6e2f9', '9c325270-0763-4e06-9448-6ef4625c16b6', 1, 'Las acciones o títulos nominativos se transfieren por endoso, a falta de disposiciones especiales en el contrato de su creación. Los documentos y efectos a la orden se transfieren por endoso, y los documentos al portador por la mera tradición.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56a5166f-7bef-4e86-b314-c0e4b09dacc5', '9c325270-0763-4e06-9448-6ef4625c16b6', 2, 'Los efectos públicos negociables quedan sujetos en cuanto a su transferencia, a las disposiciones de la ley que autoriza su emisión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('07a812a7-557a-4fe4-8bd8-1566b19f53d7', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1447', NULL, 1327, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98e4d63c-2938-441f-976a-dc4b9575eaaa', '07a812a7-557a-4fe4-8bd8-1566b19f53d7', 1, 'Si la cesión no comprendiere la totalidad del derecho y el título quedare en poder del cedente, se hará constar esta circunstancia en el documento de cesión y el cedente estará obligado a exhibirlo cuando lo necesitare el cesionario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('01a1a75d-8fb3-446c-bcc8-29c275398b0b', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1448', NULL, 1328, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2cd13d3a-8c53-40be-bcfc-76dd1162f09e', '01a1a75d-8fb3-446c-bcc8-29c275398b0b', 1, 'La cesión no produce efecto contra el deudor ni contra tercero sino desde que se notifica al deudor o desde que éste se muestra sabedor de ella. Se entiende que el deudor tiene conocimiento de la cesión cuando ejecuta un hecho que lo supone, como un principio de pago al cesionario o la contestación de la demanda promovida por éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6476d5b3-76f2-4c01-b1eb-bf72be22aa8c', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1449', NULL, 1329, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6667952f-754a-432b-b1d4-bf2de27fafc4', '6476d5b3-76f2-4c01-b1eb-bf72be22aa8c', 1, 'La notificación de la cesión deberá hacerla el cedente o el cesionario, ya sea judicialmente o por medio de notario. Esta diligencia no es necesaria cuando el acreedor está facultado por el deudor para ceder el crédito sin su notificación. Tampoco es necesaria en los documentos endosables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0425b5de-385f-4cb0-8fed-b06cd54a5670', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1450', NULL, 1330, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d102b5bb-3666-40b3-9f83-4e3d55760a62', '0425b5de-385f-4cb0-8fed-b06cd54a5670', 1, 'Cuando no se trate de títulos a la orden o al portador, el deudor a quien se notifique la cesión puede oponer al cesionario, todas las excepciones que podría oponer al cedente por causas anteriores a la notificación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('468f89c7-2825-40ec-8b8b-ca8267328684', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1451', NULL, 1331, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44ae1637-d35b-4542-96a5-596448d606fd', '468f89c7-2825-40ec-8b8b-ca8267328684', 1, 'El que cede un crédito u otro derecho, sólo responde de su legitimidad y existencia al tiempo de la cesión, salvo que se haya comprometido expresamente con el cesionario a garantizar la solvencia del deudor, o que se trate de documentos endosables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a2a5d16c-40e0-4655-aafd-f41220861da0', 'a0000000-0000-0000-0000-000000000001', '6111eb00-557b-480d-b172-730c1f993ade', '1452', NULL, 1332, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2fdb7eb-249b-4fe3-bb75-90d143e19c04', 'a2a5d16c-40e0-4655-aafd-f41220861da0', 1, 'La responsabilidad del cedente que se compromete a garantizar la solvencia del deudor, se limita al momento en que la obligación sea exigible, salvo convenio en contrario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a7e33197-147a-41e9-bae7-b63832a746a2', 'a2a5d16c-40e0-4655-aafd-f41220861da0', 2, 'SUBROGACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('415ab698-8491-4c14-b3b0-fb2577c40f43', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1453', NULL, 1333, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5c645a1-bc8f-4758-b61a-3abd86775ede', '415ab698-8491-4c14-b3b0-fb2577c40f43', 1, 'La subrogación tiene lugar cuando el acreedor sustituye en el tercero que paga, todos los derechos, acciones y garantías de la obligación');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8fbd9a5c-2e8f-41e1-9ff8-12c08290829a', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1454', NULL, 1334, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be7f36b7-618c-4837-97ae-2f3482fe9afa', '8fbd9a5c-2e8f-41e1-9ff8-12c08290829a', 1, 'El que subroga no puede ejercer los derechos y acciones del acreedor sino hasta la concurrencia de la suma efectivamente pagada por él para la liberación del deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f7b3899-0a52-4a25-8c93-edd3698bb80e', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1455', NULL, 1335, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a86b2e85-a24e-422f-8fd7-d365fde2d718', '7f7b3899-0a52-4a25-8c93-edd3698bb80e', 1, 'La subrogación tiene lugar por ministerio de la ley, sin necesidad de declaración alguna de los interesados: 1. Cuando el que es acreedor paga a otro acreedor que le es preferente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2eb7b2fa-cec4-4ac0-b97f-1932659a61ea', '7f7b3899-0a52-4a25-8c93-edd3698bb80e', 2, '2. Cuando el tercero que paga tiene interés jurídico en el cumplimiento de la obligación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f58b0c1-0c3f-45d4-8a1f-ff194d9ac0bb', '7f7b3899-0a52-4a25-8c93-edd3698bb80e', 3, '3. Cuando el tercero no interesado en la obligación paga con anuencia del deudor; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14ab061c-2ceb-4294-b7f0-fc61eca39f5c', '7f7b3899-0a52-4a25-8c93-edd3698bb80e', 4, '4. Cuando un heredero paga con sus bienes propios alguna deuda de la herencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f649e8ba-1d0d-41f9-8a5f-8a8f0da6aaad', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1456', NULL, 1336, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01598614-f700-4b86-9d07-5174a9390df4', 'f649e8ba-1d0d-41f9-8a5f-8a8f0da6aaad', 1, 'Cuando la deuda fuere pagada por el deudor con dinero que un tercero le prestare con ese objeto, el prestamista subrogará al acreedor por ministerio de la ley, en sus derechos, si el préstamo constare en documento fehaciente en que se declare que el dinero fue prestado para el pago de la deuda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d113a9d6-b618-4d47-8824-964520860459', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1457', NULL, 1337, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e375bbd5-47ab-4570-a2da-e959e2ee66a9', 'd113a9d6-b618-4d47-8824-964520860459', 1, 'La subrogación legal en provecho del que ha pagado una deuda a la cual estaba obligado con otros, lo autoriza a ejercer los derechos y acciones del acreedor, salvo los efectos de la confusión en cuanto a la parte que corresponda al subrogado en la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50d2a407-f78b-412c-86ee-8c8556887770', 'a0000000-0000-0000-0000-000000000001', '2615859b-7a0d-44b8-b150-18bdd4857ebf', '1458', NULL, 1338, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74d1c591-44b6-488b-b217-42d7fd07f3e5', '50d2a407-f78b-412c-86ee-8c8556887770', 1, 'Si el subrogado lo hubiere sido sólo en parte y los bienes del deudor no alcanzaren a pagar la totalidad del crédito, el pago se hará a prorrata.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be821a79-688a-4357-92f0-00277678fcd1', '50d2a407-f78b-412c-86ee-8c8556887770', 2, 'TRANSMISION DE DEUDAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6ef8f982-5191-46ed-b9ec-ec4310b0d4ca', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1459', NULL, 1339, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('35515e03-d146-4ba6-928f-5fe74176ef0d', '6ef8f982-5191-46ed-b9ec-ec4310b0d4ca', 1, 'La sustitución del deudor en una obligación personal y su liberación, se verifican por convenio entre el acreedor y el tercero que se sustituye.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c375c38a-c5c8-4ed6-a4cd-ff9a7f64c41d', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1460', NULL, 1340, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bec851a6-5bbd-4e92-b29a-f6ef3c4a31c7', 'c375c38a-c5c8-4ed6-a4cd-ff9a7f64c41d', 1, 'La sustitución también puede convenirse entre el deudor y el tercero, siempre que el acreedor consienta expresa o tácitamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c542492-1294-4e19-b216-99a9f58ed061', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1461', NULL, 1341, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('added8ef-3749-4fed-b583-79e470d8bb93', '1c542492-1294-4e19-b216-99a9f58ed061', 1, 'Se presume que el acreedor consiente en la sustitución del deudor, cuando permite que el sustituto ejecute actos que debía ejecutar el deudor, como el pago de intereses o la amortización parcial o periódica del capital, siempre que lo haga en nombre propio y no por cuenta del deudor primitivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('454fafac-c2c4-4003-a3c6-5e9fbd9b6c43', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1462', NULL, 1342, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6fb449f5-f638-4632-8c33-f49e4afd6d08', '454fafac-c2c4-4003-a3c6-5e9fbd9b6c43', 1, 'El acreedor que exonera al antiguo deudor aceptando otro en su lugar, no puede repetir contra el primero si el nuevo se encuentra insolvente, salvo pacto en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3458837-849c-46d0-b1c9-dc109ab0256e', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1463', NULL, 1343, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95c8ef6d-39b9-4707-888c-7f054ba61354', 'd3458837-849c-46d0-b1c9-dc109ab0256e', 1, 'El deudor sustituto queda obligado en los mismos términos en que lo estaba el deudor primitivo; pero si la deuda estuviere garantizada con fianza, esta garantía cesará con la sustitución del deudor, a menos que el fiador consienta expresamente en que continúe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eae38da4-38de-4450-8cc2-708388e8fd2b', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1464', NULL, 1344, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f71ccab2-6f8c-414e-96c4-2192abfc0600', 'eae38da4-38de-4450-8cc2-708388e8fd2b', 1, 'Si la obligación estuviere garantizada con hipoteca o prenda, la transferencia de la cosa pignorada o hipotecada transmite la deuda, con todas sus consecuencias y modalidades, sin necesidad de convenio expreso de los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d28429b4-fb0e-4d27-9797-e84398f3c1c1', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1465', NULL, 1345, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5540fe1-abd0-467e-ba23-7af0b4612cde', 'd28429b4-fb0e-4d27-9797-e84398f3c1c1', 1, 'La persona que adquiere un patrimonio o una empresa con activo y pasivo, es responsable de las deudas y obligaciones de la misma hasta el importe de los bienes adquiridos, siempre que el precio de la adquisición esté de acuerdo con su valor efectivo aceptado por los acreedores. Si el precio no hubiere sido aceptado por los acreedores, la responsabilidad del adquirente y cedente serán solidarias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1f02c493-5cd2-4fe3-b9b3-ccb5d28def99', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1466', NULL, 1346, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('79f1439f-bae6-46a5-85ca-3689ca4d8972', '1f02c493-5cd2-4fe3-b9b3-ccb5d28def99', 1, 'Cuando dos empresas se fusionan, transfiriéndose recíprocamente su activo y pasivo, la empresa nueva responderá de todo el pasivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1262a90d-e6c6-4600-80c5-06c787c8a7f8', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1467', NULL, 1347, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc38f515-5afb-4789-827c-e890a80704bb', '1262a90d-e6c6-4600-80c5-06c787c8a7f8', 1, 'El deudor sustituto puede oponer al acreedor las excepciones que se originen de la naturaleza de la deuda y las que sean personales, pero no puede oponer las que sean personales al deudor primitivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56d86c89-ece3-4106-96c0-d486379fe835', 'a0000000-0000-0000-0000-000000000001', '7e64b5eb-f96e-4635-99ab-3553caf02d9b', '1468', NULL, 1348, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96876d12-d0c2-4dfe-a671-92e655576a2c', '56d86c89-ece3-4106-96c0-d486379fe835', 1, 'Cuando se declara nula la sustitución del deudor, la antigua deuda subsiste con todos sus accesorios, pero con la reserva de derechos adquiridos por terceros de buena fe. En este caso, el deudor primitivo es responsable por la disminución de la garantía.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6584bd06-bcd5-49b1-ac01-7de7efebeb7b', '56d86c89-ece3-4106-96c0-d486379fe835', 2, 'EXTINCION DE OBLIGACIONES');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b2af006-7d1c-479f-a9d5-0df03c8243e2', '56d86c89-ece3-4106-96c0-d486379fe835', 3, 'COMPENSACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50fea334-3064-4b50-a990-9e1b26505064', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1469', NULL, 1349, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('457df841-2b9d-4e2b-9422-f31a6a2a6b59', '50fea334-3064-4b50-a990-9e1b26505064', 1, 'La compensación tiene lugar cuando dos personas reúnen la calidad de deudores y acreedores recíprocamente y por su propio derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b67fbf06-abe3-4185-82ba-72b6ba9a8ebd', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1470', NULL, 1350, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('431f5a47-5222-486b-9aa6-951608f1fe53', 'b67fbf06-abe3-4185-82ba-72b6ba9a8ebd', 1, 'La compensación no puede tener lugar en perjuicio de tercero y solamente procede cuando las deudas consisten en dinero o en cosas fungibles de la misma especie y calidad, y son igualmente líquidas y exigibles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1adb8e83-68d1-43b6-a7be-9a048b1a0145', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1471', NULL, 1351, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9d47f64-81e4-4a59-b1c3-69bec8428138', '1adb8e83-68d1-43b6-a7be-9a048b1a0145', 1, 'Para que la compensación produzca sus efectos es necesario que la oponga la parte interesada y, una vez opuesta, extingue las dos deudas desde la fecha de su coexistencia y hasta la cantidad que importe la menor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('00588997-3ddd-49d7-aebf-7c83d0ce8d51', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1472', NULL, 1352, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aca0d22b-71a8-471b-8caa-64de07b0d614', '00588997-3ddd-49d7-aebf-7c83d0ce8d51', 1, 'La prescripción no impide la compensación cuando no se había consumado en el momento en que las obligaciones eran compensables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6427cc19-29ac-4ab7-be8c-612755f40da2', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1473', NULL, 1353, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74f9a90e-ed1f-456c-819a-0d973b09bce0', '6427cc19-29ac-4ab7-be8c-612755f40da2', 1, 'No procede la compensación: 1. En la demanda sobre la restitución del despojo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac525b6c-c283-475e-b23a-8e47423b4931', '6427cc19-29ac-4ab7-be8c-612755f40da2', 2, '2. En la demanda sobre la restitución de un depósito; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2127a52d-6a8b-4767-8daa-0d8644ddcecd', '6427cc19-29ac-4ab7-be8c-612755f40da2', 3, '3. En lo que se debe por alimentos presentes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eed12ba4-1830-4857-917d-800968c1105a', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1474', NULL, 1354, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7c4c7d45-3d78-4a0c-b0b8-47214557cff3', 'eed12ba4-1830-4857-917d-800968c1105a', 1, 'El corredor o cualquiera otra persona intermediaria, no puede compensar las sumas que reciban para comprar objetos determinados, ni el precio que se les entregue por las cosas que venden, con las cantidades que les deban los comitentes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('648e4184-992e-406b-b576-bea797a331d9', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1475', NULL, 1355, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ab2c970-f79b-4d73-9431-aaabdd9cb6b1', '648e4184-992e-406b-b576-bea797a331d9', 1, 'El fiador, o el que ha dado sus bienes en garantía de la deuda de otro, puede oponer la compensación de lo que el acreedor le debe a él o al deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4ad84885-fe88-42ff-bf1d-cb6c79d37f8d', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1476', NULL, 1356, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9a32e6d1-17aa-46cd-8bd1-9d3dc1e1d479', '4ad84885-fe88-42ff-bf1d-cb6c79d37f8d', 1, 'Cuando las deudas deban ser pagadas en diferentes lugares, se tendrán en cuenta para la compensación los gastos de transporte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc34b21a-76f1-4b18-befe-df246ca8d673', 'a0000000-0000-0000-0000-000000000001', '480a7d74-6aa3-4065-9714-aa00a5926760', '1477', NULL, 1357, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c8f95079-fd3a-447a-a04d-e03cc7d08a4c', 'fc34b21a-76f1-4b18-befe-df246ca8d673', 1, 'Cuando haya varias deudas compensables debidas por la misma persona, se observarán para la compensación las reglas establecidas para la imputación de pagos. El que paga una deuda compensable sabiendo que lo es, sin oponer compensación, cuando exija su crédito que pudo ser compensado, no puede aprovecharse en perjuicio de tercero, de las garantías que hubiere tenido dicho crédito al tiempo de hacer el pago.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e23b963-e42f-4502-a365-d1694d67a176', 'fc34b21a-76f1-4b18-befe-df246ca8d673', 2, 'NOVACION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e62c4798-a908-461c-ad46-3535fb8fbed9', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1478', NULL, 1358, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0146d37-cb83-414b-b86a-db72f8e321b0', 'e62c4798-a908-461c-ad46-3535fb8fbed9', 1, 'Hay novación cuando deudor y acreedor alteran sustancialmente la obligación sustituyéndola por otra.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee9dfb3e-c759-4422-a339-68aab1cd0cfa', 'e62c4798-a908-461c-ad46-3535fb8fbed9', 2, 'La novación no se presume; es necesario que la voluntad de efectuarla resulte claramente del nuevo convenio, o que la antigua y la nueva obligación sean de todo punto incompatibles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2db78cbe-7769-415a-894a-aafd518a05a9', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1479', NULL, 1359, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('89db87d4-2f2b-4f8f-9472-1aaa380a2426', '2db78cbe-7769-415a-894a-aafd518a05a9', 1, 'La novación extingue las garantías y obligaciones accesorias, a menos que el acreedor y deudor convengan expresamente en la reserva; pero no valdrá ésta cuando la garantía la hubiere prestado un tercero que no acepte expresamente la nueva obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ef0d968-4dac-40ef-96a4-2b89739fef97', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1480', NULL, 1360, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ecfdca74-180b-4fff-9543-793f5dd81dd6', '1ef0d968-4dac-40ef-96a4-2b89739fef97', 1, 'La novación no altera el orden y preferencia de las garantías constituidas por el deudor cuando se trata de bienes de su propiedad o de bienes de terceros que hayan prestado su consentimiento para la nueva obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c7652524-2ee3-412d-aa9f-15a16521efab', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1481', NULL, 1361, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9895354a-307c-4dac-8496-eeb58fbcd1c9', 'c7652524-2ee3-412d-aa9f-15a16521efab', 1, 'La prórroga del plazo de una deuda no constituye novación, pero pone fin a la responsabilidad de los fiadores y extingue las garantías constituidas sobre bienes que no sean del deudor, salvo que los fiadores o los dueños de las cosas dadas en garantía accedan expresamente a la prórroga.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f819d76e-34db-4847-8be0-c688267e524c', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1482', NULL, 1362, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3ae6349-866d-41f0-aec0-aa188ddf34f4', 'f819d76e-34db-4847-8be0-c688267e524c', 1, 'La sola reducción del plazo no constituye novación, pero no podrá cobrárseles a los fiadores que no hayan aceptado expresamente la reducción, sino hasta que expire el plazo primitivamente estipulado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6a760b15-e7ff-46f6-b23c-a102dd8dd36d', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1483', NULL, 1363, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01d3fbe5-c47c-4d24-ab47-e85822388b5d', '6a760b15-e7ff-46f6-b23c-a102dd8dd36d', 1, 'Cuando la nueva obligación consista simplemente en añadir o quitar una especie, género o cantidad a la primera, los codeudores subsidiarios o solidarios no podrán ser obligados por el exceso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6df05cd5-d89b-42d3-a149-36efcdd96ead', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1484', NULL, 1364, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('167bfb79-4970-430c-a6d6-e83050b5fe60', '6df05cd5-d89b-42d3-a149-36efcdd96ead', 1, 'Si la nueva obligación se limita a señalar una cantidad como indemnización para el caso de incumplimiento y ambas son exigibles al mismo tiempo, las garantías constituidas subsistirán sólo hasta la concurrencia de la deuda principal sin la indemnización; y si únicamente ésta fuere exigible quedarán extinguidas las garantías y exonerados los codeudores solidarios o subsidiarios que no hubieren aceptado el nuevo convenio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1d8e39f7-0180-4c8f-beee-a36dad51adce', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1485', NULL, 1365, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d41d03c9-9514-4c04-be84-460bf0c3806d', '1d8e39f7-0180-4c8f-beee-a36dad51adce', 1, 'La reducción del tipo de interés en las deudas consistentes en dinero y la reducción de rentas, no constituyen novación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3d6b45fb-bfc8-4605-b6ad-952b441d12da', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1486', NULL, 1366, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('365196cc-7667-4f89-a4d1-6cd148bbe63c', '3d6b45fb-bfc8-4605-b6ad-952b441d12da', 1, 'La simple mutación del lugar para el pago, deja subsistentes las garantías de la obligación constituidas por terceros, pero sin ningún gravamen más para éstos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('995b7830-49f3-456b-ba43-7d13cc39b8db', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1487', NULL, 1367, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ec221a9f-2412-4f24-9262-afb327b5a7c8', '995b7830-49f3-456b-ba43-7d13cc39b8db', 1, 'La novación no produce efectos si la antigua obligación era nula o estaba extinguida. La obligación simplemente anulable queda confirmada por la novación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f0e18c41-fad9-4aec-b053-07282b406328', 'a0000000-0000-0000-0000-000000000001', '0d082ff1-a249-4142-b51a-1af39ede3d3e', '1488', NULL, 1368, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('da257487-d684-47cf-bdfb-fa16ad1df718', 'f0e18c41-fad9-4aec-b053-07282b406328', 1, 'Si solamente la nueva obligación fuere nula, la anterior renacerá con todas sus condiciones, modalidades, privilegios y garantías.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b51a36be-3b3f-4625-95e6-be574603bd59', 'f0e18c41-fad9-4aec-b053-07282b406328', 2, 'REMISION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cd5120be-6373-4463-b5d0-d91631a57278', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1489', NULL, 1369, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93a87069-cb50-4151-bdd7-40037be6eb52', 'cd5120be-6373-4463-b5d0-d91631a57278', 1, 'La remisión de la deuda hecha por el acreedor y aceptada por el deudor, extingue la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f9c0f3cc-933a-433a-88e5-186dbb25005f', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1490', NULL, 1370, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef2d3f5e-f3cd-4f94-9c98-33c149bcf543', 'f9c0f3cc-933a-433a-88e5-186dbb25005f', 1, 'El perdón de la deuda hecha al deudor, aunque no sea aceptado por éste, extingue la obligación de los fiadores y cualesquiera otras garantías.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f3c5ce52-34c3-4e9d-835d-ae08bd32cda1', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1491', NULL, 1371, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc62ab00-3dc9-4b70-abf4-a6f2d690c489', 'f3c5ce52-34c3-4e9d-835d-ae08bd32cda1', 1, 'La condonación hecha a uno de los deudores simplemente mancomunados, sólo extingue la obligación del deudor que fue perdonado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e92cf9e7-7c65-4851-824e-c9bbc6cf6ac8', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1492', NULL, 1372, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac064d20-9e9f-41e3-a29a-2c36b89d6bbf', 'e92cf9e7-7c65-4851-824e-c9bbc6cf6ac8', 1, 'La condonación hecha a uno de los fiadores simples, no extingue la obligación del deudor ni la de los demás fiadores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b30e4ba1-07c2-4173-9105-6c3a2063fc82', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1493', NULL, 1373, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56bb65eb-b017-4ee5-81c3-c503ba165ed2', 'b30e4ba1-07c2-4173-9105-6c3a2063fc82', 1, 'Si el deudor cayere en insolvencia, el acreedor cobrará su crédito de los demás fiadores, rebajada la parte que corresponda al fiador que fue perdonado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed5f8c99-bb4d-4c8b-b45f-de1bfb61f820', 'a0000000-0000-0000-0000-000000000001', '1fcd0102-c666-4eca-acfc-63e146b2db79', '1494', NULL, 1374, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ab9becf-4392-42bb-af37-9fedb4ad7c14', 'ed5f8c99-bb4d-4c8b-b45f-de1bfb61f820', 1, 'Se presume la remisión de la obligación accesoria de prenda cuando la cosa pignorada, después de entregada al acreedor, se hallare en poder del deudor, salvo prueba en contrario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4c037dc-2739-4df8-bd08-81983f3536fc', 'ed5f8c99-bb4d-4c8b-b45f-de1bfb61f820', 2, 'CONFUSION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('75269d1f-eaa3-485b-bd8a-2b291d8ad3f5', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1495', NULL, 1375, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c7df7a3-7f82-4c27-93e5-367dfe0d0f79', '75269d1f-eaa3-485b-bd8a-2b291d8ad3f5', 1, 'La reunión en una misma persona de la calidad de acreedor y deudor, extingue la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d8996685-5a45-4e8c-a0ed-c320f928e3f5', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1496', NULL, 1376, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('799657e5-b1fb-456f-8f74-82e3c7d750c8', 'd8996685-5a45-4e8c-a0ed-c320f928e3f5', 1, 'Si por cualquier causa el acto que originó la confusión se anulare o rescindiere, se restablece la situación primitiva con todos sus privilegios, garantías y accesorios, sin perjuicio de tercero y de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('214a41ce-28f4-408e-acd7-87567969ae1f', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1497', NULL, 1377, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff565de3-b155-43e4-b97a-b594ec952420', '214a41ce-28f4-408e-acd7-87567969ae1f', 1, 'La confusión que se verifica en el deudor principal aprovecha a sus fiadores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('597136dd-eb33-4ea6-ae52-f5dd46d1f052', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1498', NULL, 1378, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('68982c22-fc50-4f1c-a6ac-eafe9edcbd8a', '597136dd-eb33-4ea6-ae52-f5dd46d1f052', 1, 'La confusión que se verifica en la persona del fiador no extingue la obligación principal ni la de los demás fiadores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16e2a170-5dd2-4dc2-9d9c-c27c725e16e7', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1499', NULL, 1379, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74a94c2c-b1c7-4153-a444-f8b3852312f3', '16e2a170-5dd2-4dc2-9d9c-c27c725e16e7', 1, 'Si concurre la calidad de acreedor en uno de varios deudores simplemente mancomunados, no quedan libres los demás sino en la parte que correspondía a su codeudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ac26eab1-d170-4c43-9de9-942f404c9cf2', 'a0000000-0000-0000-0000-000000000001', '942cc8ad-a4ac-4729-898c-bff158ea1d39', '1500', NULL, 1380, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d9c8e27-c7db-4d05-b3f5-c35e386dce89', 'ac26eab1-d170-4c43-9de9-942f404c9cf2', 1, 'Los créditos y deudas del heredero que no haya sido instituido a título universal, no se confunden con las deudas y créditos hereditarios.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fee942c7-dd12-4e9c-817a-be749b18062d', 'ac26eab1-d170-4c43-9de9-942f404c9cf2', 2, 'PRESCRIPCION EXTINTIVA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5e85421c-5ede-4670-96f2-5a41f006dc0b', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1501', NULL, 1381, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('82984079-6acc-4e9b-b81b-7ce79f32423c', '5e85421c-5ede-4670-96f2-5a41f006dc0b', 1, 'La prescripción extintiva, negativa o liberatoria, ejercitada como acción o como excepción por el deudor, extingue la obligación. La prescripción de la obligación principal produce la prescripción de la obligación accesoria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8d3e701d-6532-406a-b31d-acd9e6843619', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1502', NULL, 1382, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1846d7d5-a8df-4e6d-9756-a2e014cf9fc6', '8d3e701d-6532-406a-b31d-acd9e6843619', 1, 'Las personas impedidas de administrar sus bienes, pueden reclamar contra sus representantes legales, cuyo dolo o negligencia hubiere sido causa de la prescripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('da5c1f36-db78-4b12-8eff-3b03a2f0c9ea', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1503', NULL, 1383, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a7eb4ec-7ff9-4750-84f3-0dfa8e7dc110', 'da5c1f36-db78-4b12-8eff-3b03a2f0c9ea', 1, 'Los que tienen capacidad para obligarse pueden renunciar la prescripción ya adquirida, pero no el derecho de prescribir para lo sucesivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('deda06e9-a1e9-441c-86ae-d1893f43bfcd', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1504', NULL, 1384, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f0d6d4b1-4620-405f-b707-034e80c602ae', 'deda06e9-a1e9-441c-86ae-d1893f43bfcd', 1, 'Se entiende renunciada la prescripción, si el deudor confiesa deber sin alegar prescripción o si paga el todo o parte de la deuda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c87c8a57-b8bf-4d83-b4db-698c254030e0', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1505', NULL, 1385, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e8f8f04-c1c4-4bae-a374-af33ef01e1cb', 'c87c8a57-b8bf-4d83-b4db-698c254030e0', 1, 'No corre el término para la prescripción: 1. Contra los menores y los incapacitados, durante el tiempo que estén sin representante legal constituido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40b07b53-861c-4376-8959-811643429187', 'c87c8a57-b8bf-4d83-b4db-698c254030e0', 2, '2. Entre padres e hijos, durante la patria potestad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('099f092d-6c50-4b01-9980-095a1fc35463', 'c87c8a57-b8bf-4d83-b4db-698c254030e0', 3, '3. Entre los menores e incapacitados y sus tutores, mientras dure la tutela;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b56dc45a-1cc5-44c9-9538-ffc726091570', 'c87c8a57-b8bf-4d83-b4db-698c254030e0', 4, '4. Entre los copropietarios, mientras dure la indivisión; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dcc6395a-9a16-4905-9fdd-3dd4d8afb356', 'c87c8a57-b8bf-4d83-b4db-698c254030e0', 5, '5. Entre los cónyuges, durante el matrimonio; y entre hombre y mujer, durante la unión de hecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('40b250db-5cbd-4629-8c51-792e8fc08f6a', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1506', NULL, 1386, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dcc9ba4a-cfbb-4935-969f-b17d2324fce9', '40b250db-5cbd-4629-8c51-792e8fc08f6a', 1, 'La prescripción se Interrumpe: 1. Por demanda judicial debidamente notificada o por cualquier providencia precautoria ejecutada, salvo si el acreedor desistiere de la acción intentada, o el demandado fuere absuelto de la demanda, o el acto judicial se declare nulo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('281e87f7-3dec-4632-8ba4-c73cd71249c7', '40b250db-5cbd-4629-8c51-792e8fc08f6a', 2, '2. Si la persona a cuyo favor corre la prescripción, reconoce expresamente, depalabra o por escrito, o tácitamente por hechos indudables, el derecho de la persona contra quien prescribe; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18c70f37-af47-4afa-b76b-25df84cf4fc0', '40b250db-5cbd-4629-8c51-792e8fc08f6a', 3, '3. Por el pago de intereses o amortizaciones por el deudor, así como por el cumplimiento parcial de la obligación por parte de éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('14352b5e-9b17-4556-97de-e8d2d4867cb6', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1507', NULL, 1387, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38be88c5-4cca-4bef-8c22-7729ac2f7763', '14352b5e-9b17-4556-97de-e8d2d4867cb6', 1, 'El efecto de la interrupción es inutilizar para la prescripción todo el tiempo corrido antes de ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dcaed58b-e944-4834-a6ec-1e45ed7df052', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1508', NULL, 1388, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15aee0e0-7898-40e7-bc82-7a2bcaa59c8b', 'dcaed58b-e944-4834-a6ec-1e45ed7df052', 1, 'La prescripción extintiva se verifica en todos los casos no mencionados en disposiciones especiales, por el transcurso de cinco años, contados desde que la obligación pudo exigirse; y si ésta consiste en no hacer, desde el acto contrario a la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc4e30ac-c115-48d8-8b88-d93fa5a20cab', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1509', NULL, 1389, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64b03905-4bb9-485f-9eaf-0ee70988500d', 'dc4e30ac-c115-48d8-8b88-d93fa5a20cab', 1, 'En las obligaciones a plazo y en las condiciones, se cuenta el término para la prescripción, desde que el plazo se cumple o la condición se verifica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('848cf305-1b60-484d-9c4d-fbf02cf78500', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1510', NULL, 1390, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba6a1171-d326-4771-a15f-50c8d477d795', '848cf305-1b60-484d-9c4d-fbf02cf78500', 1, 'La prescripción de la acción de garantía por razón de saneamiento, se cuenta desde el día en que tuvo lugar la evicción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1b3fd01c-c09d-42bf-a589-06ebced2da8a', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1511', NULL, 1391, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad80da86-62b4-4969-9a43-707fa6b6f380', '1b3fd01c-c09d-42bf-a589-06ebced2da8a', 1, 'En las obligaciones con intereses, la prescripción del capital, vencido el plazo, se cuenta desde la fecha del último pago de los intereses.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cc53cea3-b6f2-4e47-a8fb-b204fbc5e34a', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1512', NULL, 1392, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e3ab153b-574b-4c47-9016-cb329c6cc09f', 'cc53cea3-b6f2-4e47-a8fb-b204fbc5e34a', 1, 'La prescripción de la obligación de rendir cuentas comienza a correr desde el día en que el obligado termina su administración; y la de la acción para cobrar el saldo de aquéllas, desde el día en que la cuenta sea aprobada por los interesados o por sentencia firme.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2cc339b7-c182-4705-923f-399bb45e429b', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1513', NULL, 1393, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6e033da4-e6d3-47c8-8533-fecd3b81afa8', '2cc339b7-c182-4705-923f-399bb45e429b', 1, 'Prescribe en un año la responsabilidad civil proveniente de delito o falta, y la que nace de los daños o perjuicios causados en las personas. La prescripción corre desde el día en que recaiga sentencia firme condenatoria, o desde aquel en que se causó el daño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('07a97399-277e-4cb2-9561-bf0f9a4e8824', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1514', NULL, 1394, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3ce23d6-f095-438a-865f-4bbd34952a82', '07a97399-277e-4cb2-9561-bf0f9a4e8824', 1, 'Prescriben en dos años: 1. Los honorarios, sueldos, salarios, jornales y otras retribuciones por prestación de cualquier servicio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('09c819bb-a003-4ebb-a87b-cc85fe851d73', '07a97399-277e-4cb2-9561-bf0f9a4e8824', 2, '2. La acción de cualquier comerciante para cobrar el precio de los objetos vendidos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce4cb2e6-5302-46ee-8165-889bb5cae876', '07a97399-277e-4cb2-9561-bf0f9a4e8824', 3, '3. La acción de los dueños de hoteles y toda clase de casas de hospedaje para cobrar el importe de las pensiones y la de los fondistas y demás personas que suministran alimentos, para cobrar el precio de estos; y,');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cbae3aaa-514b-4794-b709-f34e9da34380', '07a97399-277e-4cb2-9561-bf0f9a4e8824', 4, '4. Las pensiones, rentas, alquileres y cualesquiera otras prestaciones periódicas no cobradas, a su vencimiento, ya se haga el cobro en virtud de acción real o de acción personal.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('120dc988-3d53-4f48-b70a-35e15ebdc7ee', '07a97399-277e-4cb2-9561-bf0f9a4e8824', 5, 'En estos casos la prescripción corre desde el día en que el acreedor puede exigir el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78acb3c4-4af0-465e-a804-cf31b2a55b24', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1515', NULL, 1395, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('649455c0-5caf-4068-8abe-4e69a37b6bb3', '78acb3c4-4af0-465e-a804-cf31b2a55b24', 1, 'La obligación de rendir cuentas que tienen todos los que administran bienes ajenos, y la acción para cobrar el saldo de ellos, prescriben por el término de tres años.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('01899586-fe90-4d2d-9fac-e0503431cb0d', 'a0000000-0000-0000-0000-000000000001', '54468d72-5146-45b3-bc9d-3081404f4b7e', '1516', NULL, 1396, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46d3de45-56ae-4514-8987-ed169159db53', '01899586-fe90-4d2d-9fac-e0503431cb0d', 1, 'Las disposiciones del presente capítulo se entienden sin perjuicio de lo que en este Código o en leyes especiales se establezca respecto a otros casos de prescripción.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('115fad57-8396-4f1d-ad1b-353116e89fd6', '01899586-fe90-4d2d-9fac-e0503431cb0d', 2, 'OBLIGACIONES PROVENIENTES DE CONTRATO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3332d661-01b2-4798-b586-e3e2a95c5334', '01899586-fe90-4d2d-9fac-e0503431cb0d', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9f1b769a-2d63-47f6-937f-fac939fb90a9', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1517', NULL, 1397, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98bceb2a-6f5b-420a-a3e4-0389ccec6964', '9f1b769a-2d63-47f6-937f-fac939fb90a9', 1, 'Hay contrato cuando dos o más personas convienen en crear, modificar o extinguir una obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('773e7afd-2bc0-47c8-ba66-27837fec12da', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1518', NULL, 1398, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f2845739-0035-49dd-87eb-8d159aa7f1f1', '773e7afd-2bc0-47c8-ba66-27837fec12da', 1, 'Los contratos se perfeccionan por el simple consentimiento de las partes, excepto cuando la ley establece determinada formalidad como requisito esencial para su validez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e15eff3-62c6-482a-9e8a-9922fa7b53d0', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1519', NULL, 1399, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('60dc34aa-ec7d-4b01-bd64-09669b5b7bf7', '3e15eff3-62c6-482a-9e8a-9922fa7b53d0', 1, 'Desde que se perfecciona un contrato obliga a los contratantes al cumplimiento de lo convenido, siempre que estuviere dentro de las disposiciones legales relativas al negocio celebrado, y debe ejecutarse de buena fe y según la común intención de las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec3c29c1-f7be-4e87-9569-04c1e81b7fc3', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1520.28', 'Contrato de adhesión', 1400, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('249f9157-c2c4-41b2-874a-236bc03472b5', 'ec3c29c1-f7be-4e87-9569-04c1e81b7fc3', 1, 'Los contratos de adhesión, en que las condiciones que regulan el servicio que se ofrece al público son establecidas sólo por el oferente, quedan perfectos cuando la persona que usa el servicio acepta las condiciones impuestas. 29 Las normas y tarifas de estos negocios deben ser previamente aprobadas por el Ejecutivo, para que pueda actuar la persona o empresa que hace la oferta, incurriendo en responsabilidad en caso contrario. Cuando la variación de las circunstancias en que fue autorizado un servicio de carácter público haga demasiado onerosas las normas y tarifas aceptadas, puede el Procurador General');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99e4ab41-98a0-4ad4-a28a-04d112f75b8f', 'ec3c29c1-f7be-4e87-9569-04c1e81b7fc3', 2, '28 Derogado el segundo párrafo por el Artículo 2 del Decreto No. 20-97 publicado en el Diario de Centro América el 08 de abril de 1997. 29 Adicionado como aparece en el texto este párrafo por el Artículo 15 el Decreto No. 34-2001, publicado en el Diario de Centro América el 07 de agosto de 2001.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1743106e-d399-419f-ae26-b00cfab0cc55', 'ec3c29c1-f7be-4e87-9569-04c1e81b7fc3', 3, 'de la Nación o el representante de la municipalidad respectiva, pedir la revisión de las condiciones impuestas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb0f5d04-901b-44de-9bcb-0cb7ffed30de', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1521', 'Proposición de contrato', 1401, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42d88140-5fcd-4ed3-bcdd-7fca02f199d1', 'bb0f5d04-901b-44de-9bcb-0cb7ffed30de', 1, 'La persona que propone a otra la celebración de un contrato fijándole un plazo para aceptar, queda ligada por su oferta hasta la expiración del plazo. Si no se ha fijado plazo, el autor de la oferta queda desligado si la aceptación no se hace inmediatamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8774f4ab-02b0-4ce0-afe0-daedbde84f5b', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1522', NULL, 1402, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18b1486f-c1e6-4836-a09d-34ba319d06d9', '8774f4ab-02b0-4ce0-afe0-daedbde84f5b', 1, 'La oferta contendrá las condiciones del contrato y se hará en términos precisos y concretos. La respuesta se dará lisa y llanamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3027965c-14a6-44fd-a270-2c62db884cb0', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1523', NULL, 1403, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7c43678-46dc-4351-b0f6-39aef5b204e1', '3027965c-14a6-44fd-a270-2c62db884cb0', 1, 'Cuando la oferta se haga a persona ausente, el contrato se forma en el momento en que el proponente recibe la contestación de aquella dentro del plazo de la oferta. Si la oferta se hiciere sin fijación de plazo, el autor de ella quedará ligado durante el tiempo suficiente para que la contestación llegue a su conocimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b49187d2-fce5-401c-b605-44bbfe3c64e4', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1524', NULL, 1404, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('116930fe-4265-4d90-9bdf-0bd92ebeb2c0', 'b49187d2-fce5-401c-b605-44bbfe3c64e4', 1, 'El contrato por teléfono se considera celebrado entre presentes, y tanto en este caso como en el del artículo anterior, el contrato se reputa celebrado en el lugar en que se hizo la oferta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4ce7b930-c559-4a32-9938-3b270ea56cb0', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1525', NULL, 1405, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('30b472d5-fb21-45aa-8a6c-92b5b707aee6', '4ce7b930-c559-4a32-9938-3b270ea56cb0', 1, 'Si por alguna circunstancia la aceptación llegare tardíamente a conocimiento del oferente, éste lo comunicará sin dilación al aceptante, bajo pena de responder por los daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e6a95869-5eb9-458b-b27a-ab71af7b18aa', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1526', NULL, 1406, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d0c84cf-f126-4d28-a4bd-148ffa8ef520', 'e6a95869-5eb9-458b-b27a-ab71af7b18aa', 1, 'Si el negocio fuere de aquellos en que no se acostumbra la aceptación expresa, o cuando el oferente la hubiere dispensado, se reputará concluido el contrato si la oferta no fue rehusada sin dilación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6c7074e2-2321-4029-b523-2f8e8697a3a2', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1527', NULL, 1407, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14e207d0-7a2a-442d-81f4-1fef355ac94c', '6c7074e2-2321-4029-b523-2f8e8697a3a2', 1, 'Se considera inexistente la aceptación, si antes de ella o junto con ella, llegare a conocimiento del oferente la retractación del aceptante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2f1fd4e3-36e6-43b2-a564-8a8596bd69e9', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1528', NULL, 1408, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7c4e015-f7c6-4e4b-8b71-1e614feb075e', '2f1fd4e3-36e6-43b2-a564-8a8596bd69e9', 1, 'No tendrá efecto la oferta si el proponente falleciere o perdiere su capacidad para contratar, antes de haber recibido la aceptación; o si falleciere o perdiere su capacidad la otra parte antes de haber aceptado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d2589370-1e0a-4bce-89bc-b769f42890bb', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1529', NULL, 1409, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab41fab4-7209-42cd-b878-1fbd3f6cf6dc', 'd2589370-1e0a-4bce-89bc-b769f42890bb', 1, 'Los derechos y obligaciones de los contratantes pasan a los herederos y demás sucesores de las partes, a menos que lo contrario resulte de la ley, de la convención o de la naturaleza misma del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1a0ef8b-6b9b-4abc-9bbf-3ee9703af90d', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1530', 'Contrato a favor y a cargo de tercero', 1410, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9c48d9fe-c58a-465d-b302-af941301bdbd', 'd1a0ef8b-6b9b-4abc-9bbf-3ee9703af90d', 1, 'Se puede prometer por el hecho de un tercero con cargo de indemnización si éste no cumple. La responsabilidad del promitente cesará desde el momento en que el tercero acepté la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ad0b42cb-2f77-4996-95de-41cebc48f477', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1531', NULL, 1411, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5780c05b-7d4a-4603-8b80-ac5237c783fd', 'ad0b42cb-2f77-4996-95de-41cebc48f477', 1, 'El que estipulare en favor de un tercero tiene derecho a exigir el cumplimiento de la obligación. El mismo derecho incumbe al tercero cuando así resulte del fin contemplado en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e382a7f5-78d5-4827-ba6c-275adb92554f', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1532', NULL, 1412, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('74cfe3b0-5b7a-406c-8d57-895ef504db74', 'e382a7f5-78d5-4827-ba6c-275adb92554f', 1, 'Cuando se dejare al tercero favorecido por el contrato el derecho de reclamar la ejecución de lo pactado, no dependerá del estipulante exonerar al deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cf21343f-41c4-4c0d-a5cb-0452e6b66b71', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1533', NULL, 1413, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72571696-d57f-44c6-bec8-866e27ba79be', 'cf21343f-41c4-4c0d-a5cb-0452e6b66b71', 1, 'El estipulante puede reservarse el derecho de substituir al tercero designado en el contrato, independientemente de la voluntad de éste y del otro contratante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('75016ec4-2d87-4387-a7d8-f09cd5add440', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1534', 'Efectos del contrato', 1414, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('470ecc3e-0418-4d37-b187-3e14b614d1ce', '75016ec4-2d87-4387-a7d8-f09cd5add440', 1, 'Los que celebren un contrato, están obligados a concluirlo y a resarcir los daños y perjuicios resultantes de la inejecución o contravención por culpa o dolo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1bdb6d48-5249-4602-b8bf-8df67e203a1d', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1535', NULL, 1415, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47599905-8cd7-4024-9878-f02df6459e9e', '1bdb6d48-5249-4602-b8bf-8df67e203a1d', 1, 'En todo contrato bilateral hay condición resolutoria y ésta se realiza cuando alguna de las partes falta al cumplimiento de la obligación en lo que le concierne. El interesado puede pedir la resolución del contrato o reclamar su ejecución, y en ambos casos, el pago de daños y perjuicios, si los hubiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d9fb7f8b-f45e-473d-b507-9d6bc84fe552', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1536', NULL, 1416, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46a2ff3c-d331-422b-bb5a-dd41ce5eed15', 'd9fb7f8b-f45e-473d-b507-9d6bc84fe552', 1, 'También se podrá pedir la resolución del contrato, aun después de haber optado por reclamar el cumplimiento, si éste resultare imposible con posterioridad a la demanda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3d170d2f-cbee-4c88-8c59-4a38fdbc7c79', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1537', NULL, 1417, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('952c59b0-6328-4478-a972-b932803f7d07', '3d170d2f-cbee-4c88-8c59-4a38fdbc7c79', 1, 'El que ha dado motivo para la falta de cumplimiento o invalidez de un contrato, no podrá invocar en su favor esa causa para pedir su resolución.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('904f37fa-ef7b-4476-92f1-46144c20d105', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1538', 'Objeto del contrato', 1418, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd932036-3376-4795-8437-0da1713147a2', '904f37fa-ef7b-4476-92f1-46144c20d105', 1, 'No sólo las cosas que existen pueden ser objeto de los contratos, sino las que se espera que existan; pero es necesario que las unas y las otras estén determinadas, a lo menos, en cuanto a su género. La cantidad puede ser incierta con tal que el contrato fije reglas o contenga datos que sirvan para determinarla.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f33a72e2-7fd4-45e0-a670-91beccd81345', '904f37fa-ef7b-4476-92f1-46144c20d105', 2, 'Los hechos han de ser posibles, determinados y en su cumplimiento han de tener interés los contratantes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4f4959fa-59dd-4df8-b47b-cdeff070a496', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1539', NULL, 1419, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2cd1ec5c-472d-4713-8fa8-09e8a73f024e', '4f4959fa-59dd-4df8-b47b-cdeff070a496', 1, 'Se prohíbe todo contrato sobre el derecho de suceder en los bienes de una persona que no ha fallecido, o cuyo fallecimiento se ignora.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8a064752-0c4d-499c-8fbe-453fa80bda5f', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1540', NULL, 1420, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01b3cd19-be32-49d0-85b0-445f80484c03', '8a064752-0c4d-499c-8fbe-453fa80bda5f', 1, 'Si después de celebrado un contrato bilateral sobreviniere a una de las partes disminución de su patrimonio, capaz de comprometer o hacer dudosa la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ff3c098-47b2-4769-af9f-990f142ab508', '8a064752-0c4d-499c-8fbe-453fa80bda5f', 2, 'prestación que le incumbe, puede la parte que debe efectuar su prestación en primer lugar, rehusar su ejecución, hasta que la otra satisfaga la que le concierne o dé garantías suficientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8d229f61-0cb3-4e76-bd41-29bca51e5b2b', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1541', NULL, 1421, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('994f2dea-4f62-4f9d-89a0-4c2432e32e70', '8d229f61-0cb3-4e76-bd41-29bca51e5b2b', 1, 'Mientras las partes no estén conformes sobre todos los extremos del contrato, no se considerará concluido. La conformidad sobre puntos aislados no producirá obligación, aunque se haya consignado por escrito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('645859f3-2cb2-42d6-b32c-86b1e345069c', 'a0000000-0000-0000-0000-000000000001', '35cc3369-8896-4030-bf0e-3f51c84ec4cf', '1542', NULL, 1422, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bf6ff67-6f8d-43af-b211-eea20e1da65d', '645859f3-2cb2-42d6-b32c-86b1e345069c', 1, 'Contratos usurarios La persona que aprovechándose de la posición que ocupe, o de la necesidad, inexperiencia o ignorancia de otra, la induzca a conceder ventajas usurarias o a contraer obligaciones notoriamente perjudiciales a sus intereses, está obligada a devolver lo que hubiere recibido, con los daños y perjuicios, una vez declarada judicialmente la nulidad del convenio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5ef4b57-db14-433e-8f04-576b4e2afafa', '645859f3-2cb2-42d6-b32c-86b1e345069c', 2, 'SANEAMIENTO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba72fea4-efc0-4bf0-a9c2-9688fa01917f', '645859f3-2cb2-42d6-b32c-86b1e345069c', 3, 'PARRAFO I Disposiciones generales');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('73f706e4-3c8b-4747-bf91-0736ec427075', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1543', NULL, 1423, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a63b4d22-f589-49fc-9a08-8007af846320', '73f706e4-3c8b-4747-bf91-0736ec427075', 1, 'El enajenante está sujeto al saneamiento por evicción o por vicios ocultos, en todo contrato oneroso en que se transfiere la propiedad, la posesión, el uso, goce o disfrute de una cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('949fdc52-2e1a-4b9b-a349-a85951f67fe0', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1544', NULL, 1424, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd644167-7cff-4dd8-aac4-2132dbe4a796', '949fdc52-2e1a-4b9b-a349-a85951f67fe0', 1, 'Los contratantes pueden ampliar o restringir por pacto expreso los efectos del saneamiento y aun convenir en que éste no se preste; pero la renuncia al saneamiento no será válida si hubiere mediado mala fe por parte del enajenante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e4b431b-702f-49a7-8a3f-92ab75693526', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1545', NULL, 1425, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c52c2ba2-7182-4b49-88ec-0f89c924987a', '9e4b431b-702f-49a7-8a3f-92ab75693526', 1, 'Cuando ha sido renunciado el saneamiento, llegado que sea el momento de prestarlo, debe el enajenante devolver únicamente el precio que recibió, si el contrato fuere traslativo de dominio; salvo que el caso de saneamiento ocurrido hubiere sido renunciado de manera expresa, para cuyo efecto, al celebrarse el contrato, está obligado el que enajena a declarar los gravámenes y limitaciones que afectan a la cosa, así como los vicios ocultos que conozca.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a5269b87-ff93-4138-8dff-dfb538fe1a7a', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1546', NULL, 1426, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6c4f17a5-53fa-4baa-b79e-f2d31540c7ba', 'a5269b87-ff93-4138-8dff-dfb538fe1a7a', 1, 'El adquirente puede pedir la rescisión del contrato en lugar del saneamiento, si sólo hubiere perdido una parte de la cosa, siempre que esta parte fuere de tal importancia con respecto al todo, que sin ella no la habría adquirido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0efb2127-c65b-40e1-a480-4cc059b50dce', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1547', NULL, 1427, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff85d445-f2af-472a-94d3-a724c6c7b4e0', '0efb2127-c65b-40e1-a480-4cc059b50dce', 1, 'Si por razón del saneamiento estuviere obligado el enajenante a pagar una cantidad que exceda de la mitad del precio que recibió, podrá rescindir el contrato satisfaciendo el valor que tenga la cosa al tiempo de la rescisión, más los gastos y perjuicios ocasionados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87d63ae6-a23f-428b-95a0-8b57207d0e0e', '0efb2127-c65b-40e1-a480-4cc059b50dce', 2, 'PARRAFO II Saneamiento por evicción');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7d458c4-82a9-4152-9a67-78c64659dee1', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1548', NULL, 1428, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0bd1a36-18e2-4329-843b-d841d05b7ff1', 'b7d458c4-82a9-4152-9a67-78c64659dee1', 1, 'Tendrá lugar la evicción cuando se prive al adquirente, por sentencia firme en virtud de un derecho anterior a la enajenación, de todo o parte de la cosa adquirida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('111a70f9-bc86-4382-b847-68733fd31196', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1549', NULL, 1429, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('411fdcef-269f-4a97-8585-8517a12b93be', '111a70f9-bc86-4382-b847-68733fd31196', 1, 'Si el derecho del demandante no era perfecto antes de la enajenación y se perfeccionó por culpa o descuido del adquirente, no habrá lugar al saneamiento por evicción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('80f16795-d220-4c56-a07c-bef2b0214e61', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1550', NULL, 1430, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56dcaeb4-13eb-4546-8fbb-e02b86917f79', '80f16795-d220-4c56-a07c-bef2b0214e61', 1, 'Promovido juicio contra el adquirente en los casos en que hay lugar al saneamiento, debe el demandado hacer citar al enajenante en la forma establecida en el Código Procesal Civil y Mercantil para el emplazamiento de terceros.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d0adbf70-db8f-4496-8b30-f51e618e13e5', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1551', NULL, 1431, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('66669b32-66c0-4f89-b52d-d06fe5071b47', 'd0adbf70-db8f-4496-8b30-f51e618e13e5', 1, 'Si el enajenante comparece y quiere tomar la defensa, se seguirá contra él sólo el procedimiento, pero el adquirente podrá intervenir como parte para la conservación de sus derechos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6d128598-bd80-42c2-9efa-520d62fca7ad', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1552', NULL, 1432, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47b59e46-1223-4529-9092-f5ec6d053254', '6d128598-bd80-42c2-9efa-520d62fca7ad', 1, 'Si el enajenante se allana al saneamiento, podrá siempre el adquirente continuar por sí mismo el procedimiento; y si es vencido, no tendrá derecho para exigir de aquél el reembolso de los gastos del juicio, ni el de los frutos percibidos durante el mismo y satisfechos al dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f372aaa4-dadf-42c9-a75b-4f32b26ed6ff', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1553', NULL, 1433, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0bfd73bf-725c-4b60-879b-ea85ae050224', 'f372aaa4-dadf-42c9-a75b-4f32b26ed6ff', 1, 'El precio que el enajenante está obligado a sanear, es el que tenga la cosa al tiempo de perderla el adquirente, pero si fuere menor del que tenía al adquirirla y el enajenante hubiere procedido de mala fe, podrá exigirse el precio que tenía la cosa al tiempo de la enajenación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1554', NULL, 1434, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6336dc22-a5b3-4344-b67f-e7c8121e3fe6', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 1, 'Realizada la evicción, tendrá derecho el adquirente a exigir del enajenante, además de la restitución del precio, lo siguiente: 1. Los frutos que haya sido obligado a restituir;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1b9b7792-fd59-4271-9e2e-4321f5ee63d9', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 2, '2. El pago de las mejoras necesarias y útiles que hubiere hecho el adquirente, y los gastos de conservación de la cosa;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('da8ab784-d826-4bf0-950b-ce09b99a2815', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 3, '3. Los gastos del juicio que haya motivado la evicción y, en su caso, los del procedimiento seguido con el obligado al saneamiento; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41549430-6ba0-440e-9269-958248fba5d7', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 4, '4. Los gastos e impuestos del contrato que haya satisfecho.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('517c228a-57e2-4f22-8a05-c7bc6f37fb7a', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 5, 'ARTICULO 1555. Si el juicio terminare por sentencia absolutoria en favor del adquirente, no estará obligado, el que enajenó, a indemnizarle los perjuicios y gastos');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b782d757-c0e8-48b6-a595-a299960368b4', '2149d7a3-fc38-4c4d-a527-05fc4c05ac13', 6, 'que el proceso le hubiere causado, sino en cuanto fuere imputable a hecho o culpa del enajenante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60221484-a4f4-4b7f-9747-ebc5411861b9', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1556', NULL, 1435, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98a60fb6-7b75-44dc-af18-f074254c76b2', '60221484-a4f4-4b7f-9747-ebc5411861b9', 1, 'Si se perdiera solamente una parte de la cosa, el precio que debe sanearse será el de la parte perdida, fijado en relación a su importancia o en proporción al precio total.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50f39f92-a984-4858-a7c9-f44b9ecb72d6', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1557', NULL, 1436, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ccf96876-b9b7-4a3a-bc4f-3995259be6be', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 1, 'El enajenante que ha procedido de mala fe está obligado, en caso de saneamiento, a pagar al adquirente las mejoras de recreo y los daños y perjuicios causados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cc8b7106-a86f-4c83-9965-973b08f9a9ee', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 2, 'RTICULO 1558. El adquirente pierde el derecho al saneamiento por evicción, en los casos siguientes: 1. Si omite hacer citar de evicción al enajenante;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b09bbc4-019f-49f0-9f1a-7f7641efe6c5', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 3, '2. Cuando sin consentimiento del enajenante, transige, desiste del juicio o lo somete a juicio de árbitros;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c06cd5d9-0ca5-4b22-9a6a-cf94fc4bd78d', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 4, '3. Si habiéndose hecho cargo de la defensa, la descuida, se deja condenar por rebeldía o abandona el juicio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92ab274b-8dd7-4db3-846a-f60534bbab0f', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 5, '4. Si no hace uso de los recursos legales contra las resoluciones que afectan directamente al negocio principal;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5988ccc3-baec-43e9-a1a1-a51dd110a360', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 6, '5. Si a sabiendas no opone la excepción de prescripción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36e8ef38-32f1-4960-b485-8f1de63db7cb', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 7, '6. Si no emplea en la defensa los documentos que le haya suministrado el enajenante;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('159ecd84-c838-47c2-b3b4-d1804a3bd4ad', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 8, '7. Si comete dolo en el juicio en que fue vencido, o se prueba colusión entre él y el demandante; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('33fcc7a6-d0dd-4ba4-b573-e4b077ef42a9', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 9, '8. Si a sabiendas adquirió cosa ajena o litigiosa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ddf99e08-ad27-43c5-a578-57f8e5d013be', '50f39f92-a984-4858-a7c9-f44b9ecb72d6', 10, 'PARRAFO III Saneamiento por vicios ocultos');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6c149277-7e71-4395-ac1d-2d432415be1e', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1559', NULL, 1437, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea93f29c-a5e5-42f2-8974-4c6be18b0270', '6c149277-7e71-4395-ac1d-2d432415be1e', 1, 'El enajenante está obligado al saneamiento por los vicios o defectos ocultos de la cosa enajenada que la hagan impropia o inútil para uso a que se la destina, o que disminuya este uso de tal modo que, de haberlos conocido el adquirente, no hubiera aceptado la cosa o el precio convenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fd67a91e-28cd-433e-94d9-dc7e08c5a986', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1560', NULL, 1438, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb917924-3ecd-446b-aae7-f62b05a87160', 'fd67a91e-28cd-433e-94d9-dc7e08c5a986', 1, 'El enajenante no es responsable de los defectos o vicios manifiestos o que están a la vista, ni tampoco de los que no lo están si el adquirente, por razón de');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50e9da60-626f-4352-947a-55c4be5e10a3', 'fd67a91e-28cd-433e-94d9-dc7e08c5a986', 2, 'su oficio o profesión, debe fácilmente conocerlos, salvo el caso de que el enajenante haya declarado que la cosa la entregaba sin ningún defecto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('356b2a47-b70e-45ba-b47b-a3f51233d1d2', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1561', NULL, 1439, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f1dcc853-077a-4bc0-af04-91d4314a8c48', '356b2a47-b70e-45ba-b47b-a3f51233d1d2', 1, 'Por los vicios ocultos de la cosa tiene el adquirente derecho de ejercitar, a su elección, la acción redhibitoria para que se rescinda el contrato, o la acción estimatoria para que se le devuelva del precio lo que la cosa vale menos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e768cced-0c7a-476a-af5c-c14d37ec7057', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1562', NULL, 1440, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('834e6bec-f27d-4e6b-834b-b62b6de0f6bc', 'e768cced-0c7a-476a-af5c-c14d37ec7057', 1, 'Si se probare que el enajenante conocía los defectos de la cosa, está obligado a indemnizar daños y perjuicios, además de restituir el precio. Si los ignoraba, no está obligado sino a la restitución del precio y al pago de los gastos del contrato si se hubieren causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('01df192f-05b6-4ea0-9919-3dec0541decf', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1563', NULL, 1441, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f39d0110-4a4d-41f0-9778-5b328bbf57e6', '01df192f-05b6-4ea0-9919-3dec0541decf', 1, 'El enajenante sufre la pérdida de la cosa, enajenándose dos o más cosas con la cosa si perece por los vicios ocultos que tenía; pero si prueba que la destrucción pudo evitarse y no se evitó por culpa del adquirente, éste sólo tendrá derecho a la reducción del precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7a719338-7dd6-4680-aaf5-1b8bde2cd5aa', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1564', NULL, 1442, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e743f2bc-348e-4a6d-82c8-7d6c3e423d4e', '7a719338-7dd6-4680-aaf5-1b8bde2cd5aa', 1, 'En las ventas judiciales no habrá lugar a la responsabilidad por daños y perjuicios, pero sí a todo lo demás dispuesto en los artículos anteriores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bf691054-52b8-4c1a-867b-a08719d34299', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1565', NULL, 1443, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('79a45e8d-497a-489e-8278-fcf97c2d5c6d', 'bf691054-52b8-4c1a-867b-a08719d34299', 1, 'Enajenándose dos o más cosas conjuntamente, sea por un precio alzado o señalando a cada una su precio, el vicio de una sola da lugar al saneamiento de ella, pero no de las demás, a no ser que aparezca que el adquirente no habría recibido la cosa o cosas buenas sin la que resulte viciada, o que la cosa consista en un rebaño o partida de ganado y el vicio fuere una enfermedad contagiosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('444dfce9-707c-4fb7-97d0-ad5b254d026a', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1566', NULL, 1444, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4fbe695-f196-4e3c-a159-faf3311fa2d7', '444dfce9-707c-4fb7-97d0-ad5b254d026a', 1, 'En la adquisición de un tiro, yunta o pareja de animales, o juego de otras cosas, se presume que el adquirente no habría aceptado una sola de ellas ni adquirido el juego incompleto aunque se hubiere señalado precio separado a cada uno de los animales o cosas que lo componen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c7ba18d-e3a4-419b-9712-9dc0f18410ca', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1567', NULL, 1445, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8050193c-0664-430c-b36c-c3cf53e5b8b2', '1c7ba18d-e3a4-419b-9712-9dc0f18410ca', 1, 'Si el animal que se enajena muere dentro de los siete días siguientes a la entrega, procederá al saneamiento si el adquirente probare que la muerte se debió a enfermedad o causa anterior a la enajenación o a la entrega si ésta, no fuere simultánea con la enajenación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a7c6f6e8-0cac-40dc-94dd-99dd6796658d', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1568', NULL, 1446, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ac4f108-a2b6-4829-a9aa-1284baf13fd0', 'a7c6f6e8-0cac-40dc-94dd-99dd6796658d', 1, 'No serán objeto de contrato los ganados y animales que padezcan enfermedades contagiosas. Cualquier contrato que se hiciere respecto de ellos será nulo. También será nulo el contrato de enajenación de los ganados y animales, si, expresándose en el mismo contrato el servicio o uso para que se adquieren, resultaren inútiles para prestarlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('23efb8c5-bf1c-4c10-9df1-1817cac323ec', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1569', NULL, 1447, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('84d791d9-8e56-4ed4-b646-7e9bc104fa4d', '23efb8c5-bf1c-4c10-9df1-1817cac323ec', 1, 'El saneamiento por los vicios ocultos de los animales y ganados no tendrá lugar en las ventas hechas en feria, ni en la de caballerías enajenadas como de desecho, salvo el caso previsto en la primera parte del artículo anterior.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4a3ab60-0b7e-4d25-a255-2cb91cd7a74b', '23efb8c5-bf1c-4c10-9df1-1817cac323ec', 2, 'ARTICULO 1570. Si la cosa enajenada fuere inmueble y resultare gravado con servidumbres no aparentes de las que no se dió noticia al adquirente al tiempo de contratar, puede éste ejercitar la acción de reducción del precio, si no prefiere la redhibición; pero deberá intentar aquélla dentro de tres meses contados desde el día en que tenga conocimiento de la servidumbre.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fac8ec1a-d47b-4cbe-a272-57444904a21b', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1571', NULL, 1448, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2add200-bbbd-4a72-b5c4-a5616ae22790', 'fac8ec1a-d47b-4cbe-a272-57444904a21b', 1, 'Si el enajenante ha garantizado el buen funcionamiento de la cosa por un tiempo determinado y resultare, durante su transcurso, defecto en el funcionamiento, debe el adquirente hacerlo saber a aquél dentro de los quince días siguientes al descubrimiento del defecto; y si el enajenante no procede a su inmediata reparación, podrá exigir el saneamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2fa16120-9018-4eff-9ff5-e208381a0aea', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1572', NULL, 1449, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('901a2cff-3bca-4dfd-b703-6c5211240875', '2fa16120-9018-4eff-9ff5-e208381a0aea', 1, 'La acción redhibitoria o la estimatoria deben deducirse dentro de los seis meses siguientes a la entrega de la cosa. Las mismas acciones, por los vicios ocultos de los animales, deberán ejercitarse dentro de quince días de la fecha de su entrega al adquirente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a04a1988-9795-4966-a1a8-4370d42c5599', 'a0000000-0000-0000-0000-000000000001', '83621f18-d8ad-4a22-9bea-7bfba0d6a856', '1573', NULL, 1450, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36e5e22d-a957-45cf-82fe-a7f87d4b3880', 'a04a1988-9795-4966-a1a8-4370d42c5599', 1, 'La acción redhibitoria excluye la estimatoria, y viceversa; intentada una de ellas, el adquirente queda privado de la otra.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0506cbb-75e5-4fca-846f-3314df76c2e9', 'a04a1988-9795-4966-a1a8-4370d42c5599', 2, 'FORMA DE LOS CONTRATOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('06e61eb5-dfd4-43d2-bfda-3a4d20a81124', 'a0000000-0000-0000-0000-000000000001', 'a6613447-989e-4772-8f76-f6855e1d87e4', '1574', NULL, 1451, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c6049e25-374e-4e00-80c4-2bc0173ea51f', '06e61eb5-dfd4-43d2-bfda-3a4d20a81124', 1, 'Toda persona puede contratar y obligarse: 1. Por escritura pública;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25fae216-4f2f-4abe-a433-6ddeda27eea0', '06e61eb5-dfd4-43d2-bfda-3a4d20a81124', 2, '2. Por documento privado o por acta levantada ante el alcalde del lugar;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2ce6b6a-1cb5-4c93-9491-bddcf19d4660', '06e61eb5-dfd4-43d2-bfda-3a4d20a81124', 3, '3. Por correspondencia; y,');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc4362d7-a85d-4ca3-a708-6300a013081c', '06e61eb5-dfd4-43d2-bfda-3a4d20a81124', 4, '4. Verbalmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ae8c7f03-0db6-4eb6-b10f-748e05c1399a', 'a0000000-0000-0000-0000-000000000001', 'a6613447-989e-4772-8f76-f6855e1d87e4', '1575', NULL, 1452, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4aaac07-034a-4c0e-a68f-57e3074110ff', 'ae8c7f03-0db6-4eb6-b10f-748e05c1399a', 1, 'El contrato cuyo valor exceda de trescientos quetzales, debe constar por escrito. Si el contrato fuere mercantil puede hacerse verbalmente si no pasa de mil quetzales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('621ae4f7-593f-4a7f-ae1c-cfa931a725ba', 'a0000000-0000-0000-0000-000000000001', 'a6613447-989e-4772-8f76-f6855e1d87e4', '1576', NULL, 1453, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ca32eec-7112-4c42-a16c-80217481d649', '621ae4f7-593f-4a7f-ae1c-cfa931a725ba', 1, 'Los contratos que tengan que inscribirse o anotarse en los registros, cualquiera que sea su valor, deberán constar en escritura pública.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e8ebc15-34b3-414d-997c-bdf7c72d7d93', '621ae4f7-593f-4a7f-ae1c-cfa931a725ba', 2, 'Sin embargo, los contratos serán válidos y las partes pueden compelerse recíprocamente al otorgamiento de escritura pública, si se establecieren sus requisitos esenciales por confesión judicial del obligado o por otro medio de prueba escrita.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3188aa19-434e-4ab8-9dcb-66d7a1416772', 'a0000000-0000-0000-0000-000000000001', 'a6613447-989e-4772-8f76-f6855e1d87e4', '1577', NULL, 1454, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('594dbce7-87dc-47e0-983d-d385484911bf', '3188aa19-434e-4ab8-9dcb-66d7a1416772', 1, 'Deberán constar en escritura pública los contratos calificados expresamente como solemnes, sin cuyo requisito esencial no tendrán validez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ce62d39d-7ced-4da5-b18f-0957bead6fc6', 'a0000000-0000-0000-0000-000000000001', 'a6613447-989e-4772-8f76-f6855e1d87e4', '1578', NULL, 1455, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f63fef1a-0ab8-44d4-bb41-845cd6766dc3', 'ce62d39d-7ced-4da5-b18f-0957bead6fc6', 1, 'La ampliación, ratificación o modificación de un contrato debe hacerse constar en la misma forma que la ley señala para el otorgamiento del propio contrato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('218aa0ca-6b11-4e1c-9518-771f1038a81c', 'ce62d39d-7ced-4da5-b18f-0957bead6fc6', 2, 'RESCISION DE LOS CONTRATOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('580541c5-e387-4877-ab09-e6f57c478c9e', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1579', NULL, 1456, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7cf278c7-f85e-4e5f-a733-3d43c9054bc9', '580541c5-e387-4877-ab09-e6f57c478c9e', 1, 'Los contratos válidamente celebrados pendientes de cumplimiento, pueden rescindirse por mutuo consentimiento o por declaración judicial en los casos que establece este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5672e31c-40d1-4a0a-bb4f-11dac76d18be', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1580', NULL, 1457, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4cdc95ac-e983-4982-9e1f-5923976681f7', '5672e31c-40d1-4a0a-bb4f-11dac76d18be', 1, 'En caso de haberse perjudicado un tercero por la rescisión, se reputará subsistente la obligación sólo en lo que sea relativo a los derechos de la persona perjudicada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ea7928ad-194c-44b2-8b87-f3983b0bd319', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1581', NULL, 1458, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b6106c7-f474-43fa-9fb2-d591a9fb5e83', 'ea7928ad-194c-44b2-8b87-f3983b0bd319', 1, 'La condición resolutoria convenida por los contratantes deja sin efecto el contrato desde el momento en que se realiza, sin necesidad de declaración judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6806e4ad-0d5b-40cd-a3e6-220144f86342', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1582', NULL, 1459, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('287787b5-3697-4577-985b-ed7fe606b235', '6806e4ad-0d5b-40cd-a3e6-220144f86342', 1, 'La resolución de un contrato por efecto de la condición resolutoria implícita, debe ser declarada judicialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fb2bb5c1-0c90-4274-97b2-387241eb5ba6', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1583', NULL, 1460, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b896a6d-fa7b-404a-85ec-5e3b052fc840', 'fb2bb5c1-0c90-4274-97b2-387241eb5ba6', 1, 'Verificada o declarada la rescisión o resolución de un contrato, vuelven las cosas al estado en que se hallaban antes de celebrarse; en consecuencia, las partes deberán restituirse lo que respectivamente hubieren recibido. Los servicios prestados deberán justipreciarse ya sea para pagarlos o para devolver el valor de los no prestados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed9f6e28-28f5-4b66-8550-ab17b402892a', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1584', NULL, 1461, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f853d9b0-7cbb-43dd-8f3f-2bd8d76a8f1a', 'ed9f6e28-28f5-4b66-8550-ab17b402892a', 1, 'En la rescisión por mutuo consentimiento ninguna de las partes podrá reclamar daños y perjuicios, frutos ni intereses, si no lo hubieren convenido expresamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4108463e-a7de-40cb-a7f3-03fd2563830a', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1585', NULL, 1462, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9329afa7-de43-49e6-9dbc-2df76ccf049d', '4108463e-a7de-40cb-a7f3-03fd2563830a', 1, 'La acción para pedir la rescisión dura un año, contado desde la fecha de la celebración del contrato, salvo que la ley fije otro término en casos especiales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3207df01-d402-4bbd-8be6-7011f375d6f0', 'a0000000-0000-0000-0000-000000000001', 'e34fe7ba-ab9e-4ed3-a919-b4baf9cd91a7', '1586', NULL, 1463, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c659a07a-a67b-4f4b-bd50-331599144ed9', '3207df01-d402-4bbd-8be6-7011f375d6f0', 1, 'Son aplicables a la rescisión y resolución las disposiciones de los artículos 1314, 1315. 1316, 1317 y 1318 de este Código.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3758027-58cd-46eb-8957-601d10a641dd', '3207df01-d402-4bbd-8be6-7011f375d6f0', 2, 'DIVISION DE LOS CONTRATOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('47c9e963-ceba-4259-8290-c484cab19097', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1587', NULL, 1464, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b538fe11-8632-426f-b49f-36a6afdfdd66', '47c9e963-ceba-4259-8290-c484cab19097', 1, 'Los contratos son unilaterales, si la obligación recae solamente sobre una de las partes contratantes; son bilaterales, si ambas partes se obligan recíprocamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33e73b9b-d74b-40dd-9197-1af701b9635c', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1588', NULL, 1465, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d9a7404e-2edd-4f94-98be-37a4f32c88de', '33e73b9b-d74b-40dd-9197-1af701b9635c', 1, 'Son consensuales cuando basta el consentimiento de las partes para que sean perfectos; y reales, cuando se requiere para su perfección la entrega de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('396dc223-9541-47fd-925d-b0e9d8d1a449', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1589', NULL, 1466, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8d184216-1a8d-40b4-b4c9-e3b2b2635ecf', '396dc223-9541-47fd-925d-b0e9d8d1a449', 1, 'Son principales, cuando subsisten por sí solos; y accesorios, cuando tienen por objeto el cumplimiento de otra obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fe138531-1f4d-45f1-928b-3751badde8a6', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1590', NULL, 1467, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4999b5c-0e28-4ff3-a1d5-74c2a0d40dea', 'fe138531-1f4d-45f1-928b-3751badde8a6', 1, 'Es contrato oneroso aquel en que se estipulan provechos y gravámenes recíprocos; y gratuito, aquel en que el provecho es solamente de una de las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('565160f7-5347-4586-88fc-c40ead9ed15a', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1591', NULL, 1468, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('231e59fb-71f8-4d66-a0c2-3766b488e5c3', '565160f7-5347-4586-88fc-c40ead9ed15a', 1, 'El contrato oneroso es conmutativo cuando las prestaciones que se deben las partes son ciertas desde que se celebra el contrato, de tal suerte que ellas pueden apreciar inmediatamente el beneficio o la pérdida que les cause éste. Es aleatorio, cuando la prestación debida depende de un acontecimiento incierto que determina la ganancia o pérdida, desde el momento en que ese acontecimiento se realice.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9534a541-c74c-476a-aaff-122d66e698ef', 'a0000000-0000-0000-0000-000000000001', '63d04590-864b-41cf-bef7-fcec675db5c0', '1592', NULL, 1469, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('94d31ca7-6855-43ac-adf7-7de3118e6b3c', '9534a541-c74c-476a-aaff-122d66e698ef', 1, 'Son condicionales los contratos cuya realización o cuya subsistencia depende de un suceso incierto o ignorado por las partes; y absolutos, aquellos cuya realización es independiente de toda condición.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc470309-3271-42b1-b5e8-ea19d2721d35', '9534a541-c74c-476a-aaff-122d66e698ef', 2, 'INTERPRETACION DE LOS CONTRATOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bab5a503-cbb6-4a7c-84d1-768dcda92599', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1593', NULL, 1470, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7846ef65-a45c-4a90-ab9e-f056411f45e8', 'bab5a503-cbb6-4a7c-84d1-768dcda92599', 1, 'Cuando los términos o conceptos del contrato son claros y no dejan lugar a duda sobre la intención de los contratantes, se estará al sentido literal de sus cláusulas. Si las palabras fueren diferentes o contrarias a la intención evidente de los contratantes, prevalecerá ésta sobre aquéllas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b62e9d7c-300e-4483-a120-b729d7e84607', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1594', NULL, 1471, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bf89c50-85f3-436e-b05e-7d8c360a7494', 'b62e9d7c-300e-4483-a120-b729d7e84607', 1, 'Por muy generales que sean los términos en que aparezca redactado un contrato, no deberán entenderse comprendidos en él, cosas distintas y casos diferentes de aquellos sobre los que los interesados se propusieron contratar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('113ac6be-0e12-4cf7-8ffa-611659278015', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1595', NULL, 1472, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa61bb35-23d8-466b-aeb9-9cc84730a65c', '113ac6be-0e12-4cf7-8ffa-611659278015', 1, 'Las frases y palabras que puedan interpretarse en diverso sentido, deben entenderse en aquel que sea más conforme con la materia del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc66f872-eece-4f7d-93d6-e2af8ec45fce', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1596', NULL, 1473, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c1019cd3-8bd1-431c-8fd4-6c588ddf073e', 'fc66f872-eece-4f7d-93d6-e2af8ec45fce', 1, 'Si alguna cláusula permitiere diversos o contrarios sentidos, deberá entenderse en el más adecuado para que produzca efecto, según la naturaleza del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cbed092c-b403-4b73-885c-bb8ce76ba6d6', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1597', NULL, 1474, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('454e9f98-de20-41e9-b308-bb0190d76e53', 'cbed092c-b403-4b73-885c-bb8ce76ba6d6', 1, 'Cuando dos o más cláusulas se contradigan entre sí, de tal manera que sea imposible su coexistencia, prevalecerá la cláusula o las cláusulas que sean más conformes con la naturaleza del contrato y con la intención de las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a4e1090b-c868-4dfd-a2c1-428b05649086', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1598', NULL, 1475, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc736a05-a37a-4ea6-b9e7-393b3382f0d1', 'a4e1090b-c868-4dfd-a2c1-428b05649086', 1, 'Las cláusulas de los contratos se interpretarán las unas por las otras, atribuyendo a las dudosas el sentido que resulte del conjunto de todas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c4e1b127-5e1a-4def-8edc-4ffdd1f1a4bd', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1599', NULL, 1476, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bac80b20-96bc-45d1-81e7-4cf4d639e631', 'c4e1b127-5e1a-4def-8edc-4ffdd1f1a4bd', 1, 'Las cláusulas ambiguas se interpretarán con arreglo a lo que el uso y la costumbre determinan en el lugar en que el contrato se haya otorgado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7488627-6774-42a8-a5ca-f8174b40bc05', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1600', NULL, 1477, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('53ebd36f-bfe7-4d69-bad5-ada2a06f29ba', 'b7488627-6774-42a8-a5ca-f8174b40bc05', 1, 'Las cláusulas oscuras, ambiguas o contradictorias de un contrato, insertas en modelos o formularios preparados de antemano por uno de los contratantes, se interpretarán en favor del otro contratante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f27c303a-2e34-4649-9eea-29762a86e03d', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1601', NULL, 1478, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4171be04-2915-4e2e-befa-d7403ec593c1', 'f27c303a-2e34-4649-9eea-29762a86e03d', 1, 'Cuando en un contrato se ha expresado un caso para explicar la obligación, no se entenderá que se quiso restringir toda la obligación a este caso solamente, excluyendo los otros a que naturalmente se extienda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d505f6ca-92e5-4730-b8e9-01437283efd3', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1602', NULL, 1479, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d4051b42-e645-4cf2-9d7b-43706fa4a2c2', 'd505f6ca-92e5-4730-b8e9-01437283efd3', 1, 'Si la duda no puede resolverse por los medios indicados debe decidirse en favor del obligado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6cf417b5-ccc2-45ce-9cfb-254e1a4ccd26', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1603', NULL, 1480, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6fef436e-3d29-4bb4-8e51-f6c0379c94a2', '6cf417b5-ccc2-45ce-9cfb-254e1a4ccd26', 1, 'Tratándose de una obligación, debe estarse, en caso de duda, más por la negativa que por la afirmativa, y viceversa, si se trata de una liberación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46504d4c-68f2-4161-8612-0dbfcb8209a5', 'a0000000-0000-0000-0000-000000000001', '2c951023-0cf8-4840-80b8-d88d5f72723d', '1604', NULL, 1481, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6bfbee2e-c567-4da9-911c-4a7289280697', '46504d4c-68f2-4161-8612-0dbfcb8209a5', 1, 'Cuando por los términos en que está concebido el contrato, no pueda conocerse la intención o voluntad de los contratantes sobre el objeto principal, la obligación carece de valor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cdcc481d-4b14-44fc-9479-f11f93bb3d08', '46504d4c-68f2-4161-8612-0dbfcb8209a5', 2, 'OBLIGACIONES PROVENIENTES DE HECHOS LICITOS SIN CONVENIO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff25475d-92d8-4e44-bbc4-89d6cd9f1ff7', '46504d4c-68f2-4161-8612-0dbfcb8209a5', 3, 'GESTION DE NEGOCIOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('492c58cc-6558-4e7e-9809-f57263825262', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1605', NULL, 1482, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('104e5d71-f43a-4679-8921-85fdb994a2ba', '492c58cc-6558-4e7e-9809-f57263825262', 1, 'El que sin convenio se encarga voluntariamente de los negocios de otro, está obligado a dirigirlos y manejarlos útilmente y en provecho del dueño. Cesará la gestión desde el momento en que el interesado o quien lo represente, se persone en el negocio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('47661db1-2bbe-4690-a1fa-0dec8c73c79f', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1606', NULL, 1483, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fe3a601a-bc88-431f-90e6-5e97636ba8ca', '47661db1-2bbe-4690-a1fa-0dec8c73c79f', 1, 'El gestor debe dar aviso de su gestión al dueño, tan pronto como sea posible y esperar su decisión, a menos que haya peligro en la demora.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4f3b53d-720c-4caa-8938-c3b5a1f13885', '47661db1-2bbe-4690-a1fa-0dec8c73c79f', 2, 'Si no fuere posible dar ese aviso, el gestor debe continuar su gestión hasta que concluya el asunto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('842edba3-6f11-4969-bd3b-f063acec9051', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1607', NULL, 1484, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7920be61-7750-4747-ac91-d759f1c3812f', '842edba3-6f11-4969-bd3b-f063acec9051', 1, 'El gestor queda sujeto, en el ejercicio de la gestión, a las obligaciones y responsabilidades del mandatario, en lo que sean aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('91ff34cc-0680-4f18-93b7-ee94e4857d4e', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1608', NULL, 1485, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d6ae461-d37e-4bfc-a4ec-66a2da2bdcb7', '91ff34cc-0680-4f18-93b7-ee94e4857d4e', 1, 'Cuando dos o más personas tomaren a su cargo la gestión de los negocios de un tercero, su responsabilidad será solidaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('49517802-25d4-4e31-aa73-dcf81b9a6834', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1609', NULL, 1486, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c72c7d55-8fe2-4f25-a12b-958b0eb74c95', '49517802-25d4-4e31-aa73-dcf81b9a6834', 1, 'El juez apreciará para fijar la amplitud de la responsabilidad, las circunstancias que indujeron al gestor a encargarse de la gestión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9563dd6f-08fe-4d57-9825-6e184d4f2f81', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1610', NULL, 1487, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb0b5fd5-9fbd-45c6-8034-5bca86bee661', '9563dd6f-08fe-4d57-9825-6e184d4f2f81', 1, 'El gestor responderá del caso fortuito cuando verifique operaciones distintas del giro habitual de los negocios del dueño, cuando hubiere pospuesto el interés de éste al suyo propio, o cuando inició la gestión contra la voluntad manifiesta o presunta del dueño. Cesa la responsabilidad del gestor por caso fortuito, si prueba que habría sobrevenido igualmente, aunque se hubiera abstenido de la gestión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('24b76fc6-6a74-46bb-8832-a17716f36430', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1611', NULL, 1488, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c36e8e0d-20eb-4d81-a527-dbc2024bf84f', '24b76fc6-6a74-46bb-8832-a17716f36430', 1, 'La ratificación de la gestión por parte del dueño, produce los efectos del mandato expreso y opera retroactivamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a3b951c8-7b4e-443a-a8ee-45be6e7eba5e', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1612', NULL, 1489, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b46fa58d-52a2-457e-a3ee-290b2352073f', 'a3b951c8-7b4e-443a-a8ee-45be6e7eba5e', 1, 'Aunque no hubiese ratificado expresamente la gestión ajena, el dueño de los bienes o negocios que aproveche las ventajas de la misma, será responsable de las obligaciones contraídas en su interés e indemnizará al gestor los gastos necesarios y útiles que hubiere hecho y los perjuicios que hubiere sufrido en el desempeño de la gestión. La misma obligación le concierne cuando la gestión hubiere tenido por objeto evitar algún perjuicio inminente y manifiesto, aunque de ellos no resultare provecho alguno.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9d76393-1aea-43c3-8819-5f73bb59601b', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1613', NULL, 1490, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f34e6fe-1a6f-42ff-aa8e-81afb0c90c21', 'a9d76393-1aea-43c3-8819-5f73bb59601b', 1, 'La utilidad o necesidad del gasto en que incurra el gestor, se apreciará, no por el resultado obtenido, sino según las circunstancias del momento en que se hizo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('57273d74-38f7-4614-8a77-c4f43e953b15', 'a0000000-0000-0000-0000-000000000001', '3194060a-3f67-422f-b2c1-c44459202ff2', '1614', NULL, 1491, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32c5b21a-ff19-445f-9db2-9344cceef8f2', '57273d74-38f7-4614-8a77-c4f43e953b15', 1, 'Cuando sin conocimiento del obligado a prestar alimentos, los diese un extraño, tendrá derecho éste a reclamar los de aquél, a no constar que los dio por motivo de piedad y sin ánimo de reclamarlos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('941ca52b-5c6c-41cf-8635-5a900c99bba7', '57273d74-38f7-4614-8a77-c4f43e953b15', 2, 'ARTICULO 1615. Los gastos funerarios suministrados por quien no tenía obligación, y en relación a la posición social de la persona y a los usos del lugar, deberán ser satisfechos con los bienes del causante, y si éstos no fueren suficientes o no hubiere dejado, responderán las personas que en vida habrían tenido la obligación de alimentarle.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c93f146e-8755-4da8-b210-e3cdd3db8bf5', '57273d74-38f7-4614-8a77-c4f43e953b15', 3, 'ENRIQUECIMIENTO SIN CAUSA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f7c871ee-185d-4002-9f92-8c90fb7e0d1d', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1616', NULL, 1492, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('240d3d8e-f549-43da-a5f2-dac0dc52c81d', 'f7c871ee-185d-4002-9f92-8c90fb7e0d1d', 1, 'La persona que sin causa legítima se enriquece con perjuicio de otra, está obligada a indemnizarla en la medida de su enriquecimiento indebido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7af74019-0e2f-4568-b022-12c097fe098a', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1617', NULL, 1493, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0305030b-ab07-4f4d-ad94-05c321d00fba', '7af74019-0e2f-4568-b022-12c097fe098a', 1, 'No hay enriquecimiento sin causa en los contratos celebrados lícitamente, cualquiera que sea la utilidad que obtenga una de las partes contratantes; salvo el caso contemplado en el artículo 1542.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6aaf5fae-1772-470b-9ac6-1e997051db0d', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1618', NULL, 1494, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c7d12afb-4191-4a37-89d2-9b09d7728bdc', '6aaf5fae-1772-470b-9ac6-1e997051db0d', 1, 'El que ha pagado alguna cosa por error de haberse creído deudor de ella, tiene derecho a recobrarla del que la recibió indebidamente. Sin embargo, cuando una persona, a consecuencia de un error suyo, ha pagado una deuda ajena, no tendrá derecho de repetición contra el que, a consecuencia del pago, ha suprimido o cancelado un título necesario para el cobro de su crédito; pero podrá intentar contra el deudor las acciones del acreedor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd3b482f-dfac-454d-beb1-a3dddef74015', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1619', NULL, 1495, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9cb20348-0bfe-46ae-b3d7-64f4ad4dcd5b', 'dd3b482f-dfac-454d-beb1-a3dddef74015', 1, 'Si el que recibe lo indebido fuere menor o incapaz, solamente restituirá lo que existe en su poder y lo consumido en su propio provecho; salvo el caso de mala fe imputable al menor, o de que lo haya recibido por medio de su representante legal, casos en los cuales se aplicarán las prescripciones relativas a las personas capaces.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('27ffef52-b887-4ea2-afa8-151b8a3b6fc1', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1620', NULL, 1496, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4f39ce0b-493b-4322-84d2-506ccaddf95b', '27ffef52-b887-4ea2-afa8-151b8a3b6fc1', 1, 'Si el que de buena fe recibe la cosa indebida y la enajena antes de haber sido notificado de la demanda de restitución, estará obligado a restituir el precio recibido o a ceder la acción para reclamarlo del comprador. Si la enajenación hubiere sido hecha a título gratuito, la donación no subsistirá.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c574969a-05a0-4e0b-9b17-e48146dabee7', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1621', NULL, 1497, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0bf7a0f-79db-4ff9-be33-fad55dde7581', 'c574969a-05a0-4e0b-9b17-e48146dabee7', 1, 'Si actuó de mala fe el que recibió lo que no se le debía, estará obligado, no sólo a la restitución prescrita en el artículo anterior, sino también a los frutos o los intereses legales desde la fecha del pago indebido, y a reparar el detrimento que hubiere sufrido la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('95511a7b-7e29-4ff4-9878-b83de81f3762', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1622', NULL, 1498, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('298f52a2-cb1a-4df6-ac76-60d2f54491f3', '95511a7b-7e29-4ff4-9878-b83de81f3762', 1, 'En el caso de haberse perdido en todo o en parte la cosa indebidamente pagada, sólo estará obligado el que la recibió de buena fe, a satisfacerla total o parcialmente, si tuvo culpa en su pérdida. Mas, el que la recibió con mala fe, restituirá en todo caso su valor y satisfará los intereses devengados desde el día en que se le pagó indebidamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('748f86db-c65c-48a2-9aee-11c89d3524c9', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1623', NULL, 1499, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('63f83a09-1530-482b-bb2c-fde1c1ffadcd', '748f86db-c65c-48a2-9aee-11c89d3524c9', 1, 'Si el que recibió con mala fe la cosa indebidamente pagada, la enajenare y el tercero adquirente ha procedido también con mala fe, ambos responderán solidariamente al dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c887c146-50bc-47f2-af39-6ecbe1260851', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1624', NULL, 1500, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('172c9750-8f3d-427a-85c8-e65c5bff27a5', 'c887c146-50bc-47f2-af39-6ecbe1260851', 1, 'El que de buena fe hubiere aceptado un pago indebido, tiene derecho a que se le abonen los gastos necesarios y a retirar las mejoras útiles, si con la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('16970cd2-a3d4-4b01-a85b-1c118ae80663', 'c887c146-50bc-47f2-af39-6ecbe1260851', 2, 'separación no sufre detrimento la cosa dada en pago. Si con la separación sufriere deterioro, tiene derecho a que se le pague una cantidad equivalente al aumento de valor que recibió la cosa con la mejora hecha.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('81b8d043-dd60-4934-9d96-00d2cff4179f', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1625', NULL, 1501, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e050692c-cbc7-49de-bc2c-c0059a6af2e7', '81b8d043-dd60-4934-9d96-00d2cff4179f', 1, 'No se puede recobrar lo pagado que no habiéndose podido exigir con arreglo a las leyes, se hubiere satisfecho según la equidad. Tampoco se puede recobrar lo que se hubiese dado con objeto de alimentos o por causa de piedad, si en el acto de la entrega no se hizo reserva de reclamar el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a0c14877-c743-4ba9-bb2f-af5e3731455a', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1626', NULL, 1502, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d7b0c636-7256-4f94-b1f9-bc1efe7b02b5', 'a0c14877-c743-4ba9-bb2f-af5e3731455a', 1, 'Está sujeto a las reglas del pago indebido el que se hace para extinguir una obligación condicional, cuya condición no se ha cumplido; o por una causa que ha dejado de existir.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f6a0a90-bc25-4fcb-ab7a-e8748dd5f8e0', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1627', NULL, 1503, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e3f6fee2-9fe5-4fbc-8a58-72797e36f9fd', '7f6a0a90-bc25-4fcb-ab7a-e8748dd5f8e0', 1, 'Pasan a los respectivos herederos los derechos y obligaciones sobre lo indebidamente pagado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5ab4c936-ecec-40d2-9d1d-d7ccdc83eea2', 'a0000000-0000-0000-0000-000000000001', '554b6a39-6889-4b3c-ad8a-abf147f08206', '1628', NULL, 1504, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed564aac-7ec6-4f11-b299-a1a50f97fce0', '5ab4c936-ecec-40d2-9d1d-d7ccdc83eea2', 1, 'La acción para recobrar lo indebidamente pagado prescribe en un año, contado de la fecha en que se hizo el pago indebido.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d7e2c16e-977f-4575-af3e-f61c923438a3', '5ab4c936-ecec-40d2-9d1d-d7ccdc83eea2', 2, 'DE LA DECLARACION UNILATERAL DE LA VOLUNTAD');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb7dbedb-9f61-4618-8c6a-3185cc31e5fc', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1629', 'Oferta al público', 1505, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70dfd5b8-3d0f-4994-a1ee-3377c592d379', 'eb7dbedb-9f61-4618-8c6a-3185cc31e5fc', 1, 'La persona que ofrezca al público objetos en determinado precio, queda obligada a sostener su ofrecimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8aaa903b-c663-45e7-b411-942182285980', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1630', 'Promesa de recompensa', 1506, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32e831c1-986c-421e-9f7d-813f83d628b4', '8aaa903b-c663-45e7-b411-942182285980', 1, 'El que hace oferta por la prensa u otro medio de difusión, de remunerar una prestación o un hecho, contrae la obligación de cumplir lo prometido. Cualquiera que realice la prestación, aun cuando no haya tenido conocimiento de la existencia de la promesa, puede exigir del obligado la recompensa ofrecida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0182bd31-a926-4997-8e9b-2fe26b74bb83', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1631', NULL, 1507, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8abcf6a9-0896-4245-b5fa-8917656ee88a', '0182bd31-a926-4997-8e9b-2fe26b74bb83', 1, 'La promesa pública de recompensa podrá revocarse, cuando exista justa causa para ello, en la misma forma que la oferta, a no ser que la prestación se hubiere ya realizado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aace8adf-f9a7-4c8e-9b45-d8b44fadb9d7', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1632', NULL, 1508, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3bae9b7-d73f-49fe-8a8c-74cf0c10fbc7', 'aace8adf-f9a7-4c8e-9b45-d8b44fadb9d7', 1, 'La revocación obliga al promitente a reembolsar los gastos hechos por quienes de buena fe comenzaron a ejecutar el hecho y dieron aviso de haber principiado; pero la suma total que se reembolse no podrá exceder del monto de la remuneración ofrecida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e34c2862-3cba-452f-86d6-1ce2fe9fc127', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1633', NULL, 1509, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6d599e73-65f2-48eb-96a8-5598d7e78b9b', 'e34c2862-3cba-452f-86d6-1ce2fe9fc127', 1, 'El que hubiere realizado la prestación o comenzado a ejecutarla, podrá reclamar el reembolso dentro de los dos meses siguientes a la fecha de la publicación de la revocatoria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('64634c54-fa10-434f-9f96-0e5d1e80e4b2', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1634', NULL, 1510, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('725d0cb6-04c3-47a7-aee1-15826e01799b', '64634c54-fa10-434f-9f96-0e5d1e80e4b2', 1, 'Si el hecho por el cual se prometió la recompensa se hubiese ejecutado por varias personas, tendrá derecho a recibirla la que primero realizó la ejecución. Si el hecho fue ejecutado simultáneamente por varios, cada uno recibirá una parte igual de la recompensa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34815f96-8270-4014-9d1d-1cdfcdd1f04e', '64634c54-fa10-434f-9f96-0e5d1e80e4b2', 2, 'Si la recompensa no es divisible, o si, según el tenor de la promesa, hubiere de obtenerla uno solo, se sorteará entre los interesados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f68175b7-0abb-4045-a25d-d116e0d3adf5', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1635', NULL, 1511, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1347d89b-ddde-4a08-8f5f-6a7d98d41fd7', 'f68175b7-0abb-4045-a25d-d116e0d3adf5', 1, 'En los concursos en que haya promesa de recompensa, es requisito indispensable que se fije plazo para la presentación de la obra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1fb28c08-5e0a-4a27-8db0-beb0c7e184b5', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1636', NULL, 1512, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfadc6b7-1418-44b7-84a2-49f668ec715e', '1fb28c08-5e0a-4a27-8db0-beb0c7e184b5', 1, 'La persona o personas designadas para la calificación de los trabajos, están obligadas a decidir a quién o a quiénes debe entregarse el premio ofrecido o si ninguna de las obras presentadas merece la recompensa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e464ef21-c905-4cc8-a92f-48638bdb784e', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1637', NULL, 1513, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad9a5d07-4970-49f8-ad6a-310c58d1702b', 'e464ef21-c905-4cc8-a92f-48638bdb784e', 1, 'El promitente sólo podrá exigir la propiedad de la obra premiada, cuando haya estipulado esta condición en la promesa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c2232b68-5b26-414d-8fb7-b13531730e69', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1638', 'Títulos al portador', 1514, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e72e7c31-cbd1-439e-bc15-db3b97871f33', 'c2232b68-5b26-414d-8fb7-b13531730e69', 1, 'Son títulos al portador los que no están expedidos a favor de persona determinada, contengan o no la cláusula "al portador". Estos títulos se transmiten por la simple tradición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e064c2b-d7e1-4437-8068-98dbfe517a6d', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1639', NULL, 1515, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('da9f5cb2-499f-40b0-b01f-18caa8966039', '0e064c2b-d7e1-4437-8068-98dbfe517a6d', 1, 'El poseedor de un título al portador puede reclamar del emisor la prestación debida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c982e3a8-1768-4130-a2ff-a1f9af2fd397', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1640', NULL, 1516, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8cfe3397-aa7b-4487-9860-a202d58afd70', 'c982e3a8-1768-4130-a2ff-a1f9af2fd397', 1, 'El emisor está obligado a pagar a cualquiera que le presente y entregue el título, salvo que hubiere sido notificado judicialmente para retener el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('175e37e7-276a-4bce-b625-1c2a939908d5', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1641', NULL, 1517, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d0a7e9ec-b039-4d08-80fb-86ea6a4c88da', '175e37e7-276a-4bce-b625-1c2a939908d5', 1, 'El emisor no puede oponer más excepciones que las que se refieren a la nulidad del título, las que se deriven de su texto o las que tenga en contra del portador que lo presente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4875adc7-ea79-4f7c-b6f6-14fe5d961f95', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1642', NULL, 1518, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bb5c331-cb8b-45fd-965f-cdb5a9ac82ef', '4875adc7-ea79-4f7c-b6f6-14fe5d961f95', 1, 'El suscriptor de un título al portador está obligado, aun cuando haya sido robado o perdido, o haya entrado a la circulación sin su voluntad. Para la eficacia de la obligación al portador será indiferente que el título se haya puesto en circulación después de la muerte o de la incapacidad del que lo suscribe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d69c4ed2-bd69-4529-b0ce-9b41d9e71a2f', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1643', NULL, 1519, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19638161-bcb8-4840-89e3-91f3de10da5b', 'd69c4ed2-bd69-4529-b0ce-9b41d9e71a2f', 1, 'No podrán emitirse títulos al portador en serie, que contengan la obligación de pagar una suma de dinero, sin autorización gubernativa, previa');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d12e6d93-471b-47fd-84a6-20c96d299976', 'd69c4ed2-bd69-4529-b0ce-9b41d9e71a2f', 2, 'comprobación de estar cumplidos los requisitos y formalidades establecidos en leyes especiales. Los títulos de esta naturaleza puestos en circulación sin la autorización gubernativa son nulos, pero el emisor en este caso, es responsable de los daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7f169ccb-24c7-461d-bb9f-eda1d6e7fdc4', 'a0000000-0000-0000-0000-000000000001', 'cda0a098-94e6-4f76-9f13-43d81d46e6ae', '1644', NULL, 1520, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67665cfa-116c-4a0f-81d4-1077f0384964', '7f169ccb-24c7-461d-bb9f-eda1d6e7fdc4', 1, 'La reposición de títulos que por su deterioro no estuvieren en condiciones de circular, siempre que los caracteres distintivos del mismo puedan reconocerse con seguridad, será hecha por el emisor, a costa del interesado, previa aprobación del juez de Primera Instancia del domicilio del suscriptor del título.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ad80507-3aca-4fac-9ecf-d0b54b2da749', '7f169ccb-24c7-461d-bb9f-eda1d6e7fdc4', 2, 'OBLIGACIONES QUE PROCEDEN DE HECHOS Y ACTOS ILICITOS');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0210b333-3bc6-48af-9fbb-d6111e0c274c', '7f169ccb-24c7-461d-bb9f-eda1d6e7fdc4', 3, 'TODO DAÑO DEBE INDEMNIZARSE');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca5d7b86-2f0b-4a19-af14-630c07189d1c', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1645', NULL, 1521, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b21c05e-0b8b-4f69-90ff-55509bb9b36d', 'ca5d7b86-2f0b-4a19-af14-630c07189d1c', 1, 'Toda persona que cause daño o perjuicio a otra, sea intencionalmente, sea por descuido o imprudencia, está obligada a repararlo, salvo que demuestre que el daño o perjuicio se produjo por culpa o negligencia inexcusable de la víctima.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c9aa807f-82ac-41c5-b0e2-ab71023498b4', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1646', NULL, 1522, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('849a44fd-7f8c-42d0-9c07-0876dde2bc4d', 'c9aa807f-82ac-41c5-b0e2-ab71023498b4', 1, 'El responsable de un delito doloso o culposo, está obligado a reparar a la víctima los daños o perjuicios que le haya causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a8fbb47d-f5b3-414f-a602-346bd086367c', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1647', NULL, 1523, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f6761103-d551-441d-a5da-27b3e095e390', 'a8fbb47d-f5b3-414f-a602-346bd086367c', 1, 'La exención de responsabilidad penal no libera de la responsabilidad civil, a no ser que el juez así lo estimare atendiendo a las circunstancias especiales del caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fee560cb-9fd1-440e-83c1-2eeb3852091c', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1648', NULL, 1524, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ceb176d9-f772-44e3-829d-7e6d98801c4a', 'fee560cb-9fd1-440e-83c1-2eeb3852091c', 1, 'La culpa se presume, pero esta presunción admite prueba en contrario. El perjudicado sólo está obligado a probar el daño o perjuicio sufrido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88068865-6b24-4caf-855e-ce9b08e32c73', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1649', 'Accidentes de trabajo', 1525, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cb338261-1455-4ea0-920e-568170b234c5', '88068865-6b24-4caf-855e-ce9b08e32c73', 1, 'En los accidentes de trabajo son responsables los patronos, aunque mediare culpa del trabajador; pero no responderá del accidente cuando el trabajador lo haya voluntariamente producido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c3315006-642c-41ce-a6ee-a67308cf97dd', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1650', NULL, 1526, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('73f1dc0d-c193-48cf-885c-fda51492bc96', 'c3315006-642c-41ce-a6ee-a67308cf97dd', 1, 'La persona o empresa que habitual o accidentalmente ejerciere una actividad en la que hiciere uso de mecanismos, instrumentos, aparatos o sustancias peligrosas por sí mismos, por la velocidad que desarrollen, por su naturaleza explosiva o inflamable, por la energía de la corriente eléctrica que conduzcan o por otras causas análogas, está obligada a responder del daño o perjuicio que cause, salvo que pruebe que ese daño o perjuicio se produjo por dolo de la víctima.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d3beeb82-8bfa-40d0-8fc6-d5fd0819b28f', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1651', 'Medios de transporte', 1527, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5772ec9f-4c5d-44c3-87ef-5d5fd797f5e6', 'd3beeb82-8bfa-40d0-8fc6-d5fd0819b28f', 1, 'Las empresas o el dueño de cualquier medio de transporte, serán solidariamente responsables con los autores y cómplices de los daños o perjuicios que causen las personas encargadas de los vehículos, aun cuando');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9732b72b-4b06-4520-866d-e30fcf3da738', 'd3beeb82-8bfa-40d0-8fc6-d5fd0819b28f', 2, 'la persona que los cause no sea empleada de dichas empresas o del dueño del medio de transporte, siempre que el encargado de los vehículos se los haya encomendado, aunque fuere de manera transitoria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e9d6ba62-81d0-4aa5-a766-020d636499de', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1652', NULL, 1528, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('db909c34-4eb3-4d4a-a10a-a2d72608ce65', 'e9d6ba62-81d0-4aa5-a766-020d636499de', 1, 'La responsabilidad a que se refiere el artículo anterior, cesa si se comprueba que el damnificado hubiere dado lugar al daño o perjuicio resultante o cuando hubiere procedido con manifiesta violación de las leyes y reglamentos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d98d74df-0842-4113-879b-4d5272520567', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1653', 'Abuso del derecho', 1529, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('70f4663d-ea46-45d1-b9e1-afff49aff7ce', 'd98d74df-0842-4113-879b-4d5272520567', 1, 'El exceso y mala fe en el ejercicio de un derecho, o la abstención del mismo, que cause daños o perjuicios a las personas o propiedades, obliga al titular a indemnizarlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7c09e80d-3eb7-45a2-9da8-89f759f02b13', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1654', NULL, 1530, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a11e279d-303f-4b19-a5a0-67b7e2338b12', '7c09e80d-3eb7-45a2-9da8-89f759f02b13', 1, 'Si la persona que reclama la indemnización ha contribuido a causar el daño o perjuicio, la obligación de repararlo se deducirá en proporción a su participación en él.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('657269d4-5bb3-4da4-b764-d5c36c3ea1af', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1655', 'Lesiones corporales', 1531, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a941a348-93eb-4d7f-9814-8fc2d0d4c35e', '657269d4-5bb3-4da4-b764-d5c36c3ea1af', 1, 'Si el daño consiste en lesiones corporales, la víctima tiene derecho al reembolso de los gastos de curación y al pago de los daños o perjuicios que resulten de su incapacidad corporal, parcial o total para el trabajo, fijado por el juez en atención a las siguientes circunstancias: 1. Edad, estado civil, oficio o profesión de la persona que hubiere sido afectada;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4545bcf-4ecf-4820-9527-adaf69e53f6c', '657269d4-5bb3-4da4-b764-d5c36c3ea1af', 2, '2. Obligación de la víctima de alimentar a las personas que tengan derecho conforme a la ley; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dad99f72-8865-4fd5-ac8a-de564f933ceb', '657269d4-5bb3-4da4-b764-d5c36c3ea1af', 3, '3. Posibilidad y capacidad de pago de la parte obligada.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('825e8077-9cf5-4095-b29e-8da7104eeb70', '657269d4-5bb3-4da4-b764-d5c36c3ea1af', 4, 'En caso de muerte, los herederos de la víctima, o las personas que tenían derecho a ser alimentadas por ella, podrán reclamar la indemnización que será fijada de conformidad con las disposiciones anteriores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('15112fe5-4ea2-46c5-aa70-6283d6b614eb', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1656', 'Difamación', 1532, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('06b2d4a1-4487-4c3e-83e7-22c420993271', '15112fe5-4ea2-46c5-aa70-6283d6b614eb', 1, 'En caso de difamación, calumnia o injuria, la reparación se determinará en proporción al daño moral y a los perjuicios que se derivaron.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('05931380-6851-4e75-8c48-dce447e77861', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1657', NULL, 1533, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7c79cf4-5f51-4a1f-9d33-49ff11887fa2', '05931380-6851-4e75-8c48-dce447e77861', 1, 'Si varias personas son culpables del daño o perjuicio derivado de hecho ilícito, serán solidariamente responsables, salvo que pueda determinarse la parte de daño o perjuicio causado por cada una. El que haya pagado la totalidad de la indemnización podrá repetir contra cada uno de los otros por la parte que fije el juez, según el grado de participación de cada cual en el hecho, y si no fuere posible determinarlo, por partes iguales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('744b414f-2dc8-472c-b6df-fc2272ed3d1d', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1658', NULL, 1534, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('149909e1-9d3f-4035-8e74-ca9530c7cb8b', '744b414f-2dc8-472c-b6df-fc2272ed3d1d', 1, 'El que causa daño o perjuicio para preservarse a sí mismo o para proteger a un tercero de un peligro inminente, está obligado, no obstante a la reparación que fije el juez de manera equitativa y según las circunstancias; pero si la');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('733f7e2b-7dea-45b6-95d6-8d826c7204b5', '744b414f-2dc8-472c-b6df-fc2272ed3d1d', 2, 'protección redunda exclusivamente en favor del tercero, éste será obligado a dicha reparación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('185d4d60-c7a3-490d-8ef8-e665791a4128', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1659', NULL, 1535, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('22973632-7027-4cf4-8622-8ea9df85c542', '185d4d60-c7a3-490d-8ef8-e665791a4128', 1, 'El que causa daño o perjuicio estando privado accidentalmente de discernimiento, no queda exento de responsabilidad, a menos que pruebe que cayó en este estado sin su culpa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f9a5b94-b5ab-41b9-bad9-3c12874677f2', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1660', 'Menores de edad', 1536, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e2ec38fd-4d7b-400d-a0aa-6c1691b71f85', '0f9a5b94-b5ab-41b9-bad9-3c12874677f2', 1, 'El menor de edad, pero mayor de quince años, y el incapaz cuando obra en momentos de lucidez, son responsables de los daños o perjuicios que ocasionen. En los demás casos son responsables los padres, tutores o guardadores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4c123408-6435-4d91-b1b1-9cb38ee99188', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1661', NULL, 1537, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2aca406-6790-45b2-8f39-4d0899699ed7', '4c123408-6435-4d91-b1b1-9cb38ee99188', 1, 'Los directores de establecimientos de enseñanza y los jefes de taller son responsables, en su caso, por los daños o perjuicios que causen los alumnos o aprendices menores de quince años, mientras estén bajo su autoridad o vigilancia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('038ec69a-c022-47b5-a899-478c73328c96', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1662', NULL, 1538, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('df607cdc-eaf2-4a87-91a3-eea4ce130fd2', '038ec69a-c022-47b5-a899-478c73328c96', 1, 'La responsabilidad a que se refieren los dos artículos anteriores cesa, si las personas comprendidas en ellos justifican que les fue imposible evitar el daño o perjuicio. Esta imposibilidad no resulta de la circunstancia de haber sucedido el hecho fuera de su presencia si aparece que ellos no han ejercido vigilancia sobre los menores o incapaces.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('12a2b31c-f358-4324-ab70-0b120058b22f', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1663', 'Responsabilidad de los patronos', 1539, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e897a528-b12d-4916-be7c-13d2ab1fbb67', '12a2b31c-f358-4324-ab70-0b120058b22f', 1, 'Los patronos y los dueños de talleres, hoteles, establecimientos mercantiles o industriales y, en general, las personas que tienen a otra bajo su dependencia, responden por los daños o perjuicios que causen sus empleados y demás trabajadores en actos del servicio. También están obligados a responder por los actos ajenos, los que teniendo la posesión o el mando de un objeto o elemento cualquiera, lo entreguen o transfieran a persona que no ofrezca las garantías necesarias para manejarlo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc1a405b-1dc6-4895-9f43-d0617ac94672', '12a2b31c-f358-4324-ab70-0b120058b22f', 2, 'El que pague puede repetir contra el autor del daño o perjuicio lo que hubiere pagado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9df494ee-ea44-467d-b89b-b42b2284b2ce', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1664', NULL, 1540, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45008b4f-e772-4978-b47d-d2b0d4a0abb5', '9df494ee-ea44-467d-b89b-b42b2284b2ce', 1, 'Personas jurídicas Las personas jurídicas son responsables de los daños o perjuicios que causen sus representantes legales en el ejercicio de sus funciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93bb24fb-2699-4a0e-8bdf-eca629f6a787', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1665', 'Estado y municipalidades', 1541, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('470639bd-c86d-4f19-8629-b9c81433af4f', '93bb24fb-2699-4a0e-8bdf-eca629f6a787', 1, 'El Estado y las municipalidades son responsables de los daños o perjuicios causados por sus funcionarios o empleados en el ejercicio de sus cargos. Esta responsabilidad es subsidiaria y sólo podrá hacerse efectiva cuando el funcionario o empleado directamente responsable no tenga bienes, o los que tenga no sean suficientes para responder del daño o perjuicio causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d2bd208-c045-4cb8-8b2c-50711fb67274', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1666', NULL, 1542, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b260e2a9-c9ab-4fd5-8c9b-8a2ad737888e', '7d2bd208-c045-4cb8-8b2c-50711fb67274', 1, 'En los casos de los tres artículos anteriores, el que paga el daño o perjuicio tiene derecho a repetir contra el que lo causó, salvo que éste hubiere procedido de conformidad con instrucciones recibidas de aquél y sin excederse de ellas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a1ea653a-cbcf-446d-bb4d-bb5ce94ac25a', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1667', 'Apremio y prisión ilegales', 1543, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95663e7d-ce84-4798-af07-9a7cf2951fd9', 'a1ea653a-cbcf-446d-bb4d-bb5ce94ac25a', 1, 'El que origina un apremio o prisión ilegales y el que los ordena, son responsables solidariamente por el daño o perjuicio que causen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5952cba5-776e-466e-9a4a-04da90884de8', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1668', 'Profesionales', 1544, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('369812ea-22fc-43eb-aa32-952b08d54389', '5952cba5-776e-466e-9a4a-04da90884de8', 1, 'El profesional es responsable por los daños o perjuicios que cause por ignorancia o negligencia inexcusables, o por divulgación de los secretos que conoce con motivo de su profesión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a04e27e9-021e-415f-8d43-1049a5eb9a5f', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1669', 'Dueños de animales', 1545, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ceef0714-3fc8-4b00-8802-9530a22bf017', 'a04e27e9-021e-415f-8d43-1049a5eb9a5f', 1, 'El dueño o poseedor de un animal, o el que lo tenga a su cuidado, es responsable por los daños o perjuicios que cause, aun en el caso de que se le hubiere escapado o extraviado sin su culpa. Pero si el animal fuere provocado o sustraído por un tercero o hubiese mediado culpa del ofendido, la responsabilidad recaerá sobre éste y no sobre aquéllos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1d23c593-71a5-461b-a8a0-0a0f5fc06919', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1670', 'Propietarios de edificios', 1546, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8c342451-b8df-44db-89da-41f181c4e26e', '1d23c593-71a5-461b-a8a0-0a0f5fc06919', 1, 'El que se hallare amenazado de un daño o perjuicio proveniente del edificio o de la obra de otro, instalaciones o árboles, tiene derecho a exigir del propietario que tome las medidas necesarias para evitar el peligro, de acuerdo con lo que al respecto dispone este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cbbffada-2ea4-488b-8ae5-6446d665faa5', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1671', NULL, 1547, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b07acb75-0e3e-46c7-8258-c365771e564f', 'cbbffada-2ea4-488b-8ae5-6446d665faa5', 1, 'El propietario de un edificio es responsable del daño o perjuicio causado por la ruina total o parcial del mismo. Si la ruina se debió a defecto de construcción, la responsabilidad del dueño será solidaria con la del constructor, pero el propietario podrá repetir contra aquél para reembolsarse de lo que hubiere pagado por los daños o perjuicios sufridos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('844c6abf-c305-475c-82f2-1d4303f7413f', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1672', NULL, 1548, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3252bff4-72d7-4071-b462-b6d96a5ca2aa', '844c6abf-c305-475c-82f2-1d4303f7413f', 1, 'Los propietarios, arrendatarios, poseedores y, en general, las personas que se aprovechan de los bienes, responderán, igualmente: 1. Por los daños o perjuicios que causen las cosas que se arrojaren o cayeren de los mismos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e63c7daf-bb35-40b4-9dcf-c4bd114ed1cc', '844c6abf-c305-475c-82f2-1d4303f7413f', 2, '2. Por la caída de árboles, cuando no sea ocasionada por fuerza mayor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7ad5a2d-1570-43f2-865f-b8083941d439', '844c6abf-c305-475c-82f2-1d4303f7413f', 3, '3. Por las emanaciones de cloacas o depósitos de materias infectantes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4989404-756d-4966-8d25-935180a62746', '844c6abf-c305-475c-82f2-1d4303f7413f', 4, '4. Por el humo o gases que sean nocivos, perjudiquen o causen molestia a las personas o a las propiedades;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d4249b7a-5241-4211-861a-c3459cfce483', '844c6abf-c305-475c-82f2-1d4303f7413f', 5, '5. Por los desagües, acueductos, instalaciones, depósitos de agua, materiales o sustancias que humedezcan o perjudiquen la propiedad del vecino; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72e1124b-77c5-40ab-afd9-70b22b6eb890', '844c6abf-c305-475c-82f2-1d4303f7413f', 6, '6. Por el ruido, trepidación, peso o movimiento de las máquinas o por cualesquiera otra causa que origine el daño o perjuicio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bd0afc50-56d6-450c-9139-77da65eccaab', '844c6abf-c305-475c-82f2-1d4303f7413f', 7, 'En todos estos casos, el perjudicado tiene derecho a exigir que cese la causa que motiva el daño o perjuicio y la indemnización si procediere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1498f3f4-3ab7-4136-9826-f68037beceea', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1673', 'Prescripción', 1549, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b09db5f4-8d49-44c5-9606-efd1645c8c77', '1498f3f4-3ab7-4136-9826-f68037beceea', 1, 'La acción para pedir la reparación de los daños o perjuicios a que se refiere este título, prescribe en un año, contado desde el día en que el daño se causó, o en que el ofendido tuvo conocimiento del daño o perjuicio, así como de quien lo produjo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('97b9f794-eafa-4181-ad51-ed0c945c80ca', '1498f3f4-3ab7-4136-9826-f68037beceea', 2, 'SEGUNDA PARTE DE LOS CONTRATOS EN PARTICULAR');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a6a0a7b-af90-4216-b76b-6fb231544fb7', '1498f3f4-3ab7-4136-9826-f68037beceea', 3, 'DE LA PROMESA Y DE LA OPCION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('091d3035-c182-4c7f-b532-808831ee18b4', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1674', NULL, 1550, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b1457a28-c583-4030-b52f-542d7d1e02d5', '091d3035-c182-4c7f-b532-808831ee18b4', 1, 'Se puede asumir por contrato la obligación de celebrar un contrato futuro. La promesa de contrato debe otorgarse en la forma exigida por la ley para el contrato que se promete celebrar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('343c17f3-20fc-418e-83c7-97ac11031112', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1675', 'La promesa de contrato puede ser unilateral o bilateral', 1551, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1f75aae1-07bd-44c9-a33a-d55e4d43e579', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1676', NULL, 1552, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3c237a12-e820-409e-9ca8-0a44b71d160e', '1f75aae1-07bd-44c9-a33a-d55e4d43e579', 1, 'La promesa unilateral es la estipulación que una persona hace a favor de otra, otorgándole la opción de adquirir una cosa o un derecho en las condiciones pactadas y por el tiempo convenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('001f7df4-65de-4b81-9ce0-fb37c96aff56', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1677', NULL, 1553, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d0048e0-6efc-4cd3-b3b2-b0797643084e', '001f7df4-65de-4b81-9ce0-fb37c96aff56', 1, 'La opción puede ser contrato independiente o celebrarse como pacto accesorio de otro y, en ambos casos, debe contener las condiciones en que ha de realizarse el convenio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('de306aa5-fadf-4e0a-98d3-3923bd34e7f2', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1678', NULL, 1554, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c93d540f-9cac-49f2-9889-02d7a46071cd', 'de306aa5-fadf-4e0a-98d3-3923bd34e7f2', 1, 'La aceptación del optante debe ser expresa y no puede ceder a otro su derecho de opción, si no estuviere expresamente facultado por el promitente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5463d28c-4a11-4900-a3a7-190be9ead07c', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1679', NULL, 1555, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d249911-2c63-4c81-9a53-3a845deb0823', '5463d28c-4a11-4900-a3a7-190be9ead07c', 1, 'La promesa bilateral de contrato obliga a ambas partes y les da derecho a exigir la celebración del contrato prometido de entero acuerdo con lo estipulado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('991e01ec-7b34-457c-b08e-b2e3d4363a71', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1680', NULL, 1556, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ad55d8a-4ac5-41dd-866f-0537a95c49a2', '991e01ec-7b34-457c-b08e-b2e3d4363a71', 1, 'Cuando la promesa se refiera a enajenación de bienes inmuebles o derechos reales sobre los mismos, el contrato debe inscribirse en el Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7865bcb2-c579-4f61-a265-2304af1a4f76', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1681', NULL, 1557, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15d06eb8-b295-48f2-99da-b7e5dd6b7baf', '7865bcb2-c579-4f61-a265-2304af1a4f76', 1, 'El plazo en el contrato de promesa no podrá exceder de dos años si se tratare de bienes inmuebles o derechos reales sobre los mismos, y de un año, si se tratare de otros bienes o prestaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('365af778-9f88-4667-bc4d-d5aecbc30e1f', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1682', NULL, 1558, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7170ed53-40c5-4142-a4a1-b4ef3634332a', '365af778-9f88-4667-bc4d-d5aecbc30e1f', 1, 'Si no se fijare plazo convencional, se entenderá que las partes se sujetan al plazo señalado en el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed5147a8-5459-4e17-aa68-72185a0fa921', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1683', NULL, 1559, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ced8ce8-9b5d-4807-988d-6d39ae780a9e', 'ed5147a8-5459-4e17-aa68-72185a0fa921', 1, 'Si el promitente se negare a otorgar la escritura para dar forma legal al contrato prometido, en su rebeldía lo hará el juez, salvo que la cosa haya pasado a tercero de buena fe, en cuyo caso la promesa se resolverá en el pago de daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2940b191-f9dc-4acf-909f-f8500eac8a7b', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1684', NULL, 1560, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8005e66d-b7bd-4312-a55e-06ce05afa623', '2940b191-f9dc-4acf-909f-f8500eac8a7b', 1, 'La acción para exigir el cumplimiento de la promesa, deberá entablarse dentro de los tres meses siguientes al vencimiento del plazo convencional o legal. Vencido el plazo a que se refiere el párrafo anterior para entablar la acción, sin que ésta se haya ejercitado, las partes quedan libres de toda obligación. En este caso, si hubo arras, las devolverá quién las recibió.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('28cf87b9-5e74-443a-998b-c4c41441f934', 'a0000000-0000-0000-0000-000000000001', 'cec2972b-92ea-4aa4-bc4e-a1357a67bf34', '1685', NULL, 1561, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e55864ed-7d99-4e53-b5ac-46c5e807584b', '28cf87b9-5e74-443a-998b-c4c41441f934', 1, 'Cuando en la promesa se conviene en el pago de una multa sin expresar que este pago es sin perjuicio del cumplimiento del contrato, pagada la multa cesa la obligación de celebrar el contrato prometido.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad4f8049-1f47-4717-8ffe-87a1d1396eb6', '28cf87b9-5e74-443a-998b-c4c41441f934', 2, 'DEL MANDATO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6f1d2f70-c9a2-4fb3-9467-d8d307addba9', '28cf87b9-5e74-443a-998b-c4c41441f934', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e3c8baf-cb2c-4b9b-99d9-428bbb04e992', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1686', NULL, 1562, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('85ac88f9-a209-46e4-a7a5-f0642687002f', '0e3c8baf-cb2c-4b9b-99d9-428bbb04e992', 1, 'Por el mandato, una persona encomienda a otra la realización de uno o más actos o negocios. El mandato puede otorgarse con representación o sin ella. En el mandato con representación, el mandatario obra en nombre del mandante y los negocios que realice dentro de las facultades que se le hayan conferido, obligan directamente al representado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa8ecc10-3f1e-4de8-9802-21db748bb477', '0e3c8baf-cb2c-4b9b-99d9-428bbb04e992', 2, 'En el mandato sin representación, el mandatario obra en nombre propio, sin que los terceros tengan acción directa contra el mandante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1687', NULL, 1563, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48edf582-3a74-4815-a5d9-14f4af0c196c', 'c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 1, 'El mandato debe constar en escritura pública como requisito esencial para su existencia, y puede ser aceptado expresa o tácitamente. No es necesaria la escritura pública:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4b3e894-8c9e-4c1d-ae64-e9b227fc9978', 'c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 2, '1. Cuando se trate de asuntos cuyo valor no exceda de mil quetzales, en cuyo caso puede otorgarse el mandato en documento privado, legalizado por notario, o en acta levantada ante el alcalde o juez local, con las formalidades legales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3aed9a62-03eb-42fe-a684-ebe3adb8ba15', 'c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 3, 'Sin embargo, si el mandato se refiere a la enajenación o gravamen de bienes inmuebles o derechos reales sobre los mismos, es obligatorio el otorgamiento del poder en escritura pública; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('879cbb02-d97b-4a7d-a0f5-10f2050b81ac', 'c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 4, '2. Cuando la representación se confiere por cartas- poderes para la asistencia a juntas y demás actos en que la ley lo permite.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('77790b46-fd10-49e8-8cde-bc8dd1f4dc57', 'c59ff74f-2a1e-4dad-982d-68bcb4b3d35b', 5, 'El mandato para asuntos judiciales queda sujeto, especialmente, a lo que establecen las leyes procesales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33d5a3d2-74f1-47fb-aa23-fb78f7066b5a', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1688', NULL, 1564, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e1cb1367-4271-4bab-8d26-d85ecbf714c8', '33d5a3d2-74f1-47fb-aa23-fb78f7066b5a', 1, 'Pueden ser objeto de mandato, todos los actos o negocios para los que la ley no exige intervención personal del interesado. No se puede dar poder para testar o donar por causa de muerte, ni para modificar o revocar dichas disposiciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2ea79782-cfd4-427a-950d-ad8e806bd75c', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1689', NULL, 1565, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55588d64-0814-4779-ae9c-2aa8c9c6407e', '2ea79782-cfd4-427a-950d-ad8e806bd75c', 1, 'Sólo es gratuito el mandato si el mandatario hace constar, de manera expresa, que lo acepta de ese modo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('36212bf8-f9d6-4623-a70b-031b22520d3e', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1690', 'El mandato es general o especial', 1566, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27b8cd02-0d35-46a5-8b9f-ffebd61d99f3', '36212bf8-f9d6-4623-a70b-031b22520d3e', 1, 'El general comprende todos los negocios del poderdante y el especial se contrae a uno o más asuntos determinados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('07711e07-5216-4cf3-b548-87b5bc397a06', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1691', NULL, 1567, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37a8dbaa-6eab-4a34-ac77-e76747a714b7', '07711e07-5216-4cf3-b548-87b5bc397a06', 1, 'Los representantes de los menores, incapaces o ausentes, no pueden dar poder general sino solamente especial para asunto determinado que no pueda ser atendido personalmente por ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7606f5c5-5b59-4c79-a3d5-d2200106aa89', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1692', NULL, 1568, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8d836ff8-70b6-4d29-8345-6a98a998cfa7', '7606f5c5-5b59-4c79-a3d5-d2200106aa89', 1, 'Se necesita poder especial para donar entre vivos, contraer matrimonio, otorgar capitulaciones matrimoniales, pactar las bases referentes a la separación o al divorcio, demandar la nulidad o insubsistencia del matrimonio, constituir patrimonio de familia, reconocer hijos y negar la paternidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('51c08c91-0ac2-44f0-945b-1ec6916b6180', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1693', NULL, 1569, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c80d3baf-7c0d-49fc-a070-b0b74f07cf98', '51c08c91-0ac2-44f0-945b-1ec6916b6180', 1, 'El poder general necesita cláusula especial para enajenar, hipotecar, afianzar, transigir, gravar o disponer de cualquier otro modo la propiedad del mandante, y para todos los demás actos en que la ley lo requiera. La facultad para celebrar negocios o contratos implica la de otorgar los correspondientes documentos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17008da5-1769-4749-b6c3-bd36bb5c0a79', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1694', NULL, 1570, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('09bdba01-118c-4da8-89f2-1562cfa9fb08', '17008da5-1769-4749-b6c3-bd36bb5c0a79', 1, 'No se puede ejercer al mismo tiempo poder de varias personas cuando entre éstas hay colisión de derechos. Tampoco puede un sólo mandatario');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9520a53-a07f-4013-8146-e74b568db4f7', '17008da5-1769-4749-b6c3-bd36bb5c0a79', 2, 'otorgar contratos, representando a la vez los derechos o intereses de las dos partes contratantes, sin autorización de los mandantes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bdc306eb-35ee-4556-8555-92ad0339b4da', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1695', NULL, 1571, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99e00380-a39d-4f57-a444-90f383fa7175', 'bdc306eb-35ee-4556-8555-92ad0339b4da', 1, 'El marido no puede, sin el consentimiento expreso de la mujer ni ésta sin el de aquél, dar poder para asuntos relativos a los bienes comunes o para contratos de los que resulten obligaciones para ambos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17109f43-2998-46a1-81e1-a2e019e8a00b', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1696', NULL, 1572, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28986268-b4de-43e5-9f57-2a68bca1ae3b', '17109f43-2998-46a1-81e1-a2e019e8a00b', 1, 'Por las personas jurídicas confieren poder las personas individuales que las representen, debiendo limitarse el mandato a los negocios que son objeto de la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9487e621-fb5f-4431-bf52-1e4ae4cf9a35', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1697', NULL, 1573, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('128abf05-135b-48f7-926e-cb899d4f2d55', '9487e621-fb5f-4431-bf52-1e4ae4cf9a35', 1, 'Para que las personas jurídicas puedan ejercer mandato, es necesario que las operaciones a que el poder se refiera entren en el curso de los negocios de aquéllas, o que, de conformidad con el instrumento de su constitución o respectivos estatutos, estén facultados los gerentes o representantes para aceptarlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7a80e9e-7719-4f52-844a-4f01d0e88dae', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1698', NULL, 1574, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5cf2464-1ec8-4559-955c-ff4c69e426c9', 'b7a80e9e-7719-4f52-844a-4f01d0e88dae', 1, 'No puede ejercer mandato el fallido mientras no se le rehabilite; el sentenciado por cualquier delito mientras no haya purgado la condena o sido rehabilitado y, en casos especiales, las personas a quienes la ley lo prohíbe o tienen incompatibilidad o impedimento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('84ad1308-26ac-44a1-824b-122e2d8e91a3', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1699', NULL, 1575, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57d447f6-df26-4c19-9622-2685195531d4', '84ad1308-26ac-44a1-824b-122e2d8e91a3', 1, 'El mandato es esencialmente revocable, aun cuando se haya conferido con plazo o para asunto determinado; pero si hubiere sido aceptado, la revocación sólo producirá efecto desde la fecha y hora en que se notifique al apoderado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('29866dcd-4e33-4067-b58b-d040446e4dfe', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1700', NULL, 1576, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fdd120a9-6545-4ff0-b0e0-2b11423929f7', '29866dcd-4e33-4067-b58b-d040446e4dfe', 1, 'Es válido el poder otorgado en el extranjero con sujeción a las formalidades externas prescritas por las leyes del lugar en que se otorga; pero si para el acto o contrato, objeto del poder, la ley de Guatemala exige facultad especial, debe sujetarse a lo dispuesto en ésta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('245885bf-cba2-4406-bf97-7427a5ef102d', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1701', NULL, 1577, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd571569-adf5-4ccb-96a1-25472f55ec16', '245885bf-cba2-4406-bf97-7427a5ef102d', 1, 'El poder que se da a dos o más personas será ejercitado conjuntamente si el mandante no expresó que se ejercite por separado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f633d391-2411-4233-b320-3826861730c8', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1702', NULL, 1578, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ebcb2f52-89ce-496d-99fe-5040ad7d0b2e', 'f633d391-2411-4233-b320-3826861730c8', 1, 'El mandato en que se le confiere al apoderado la facultad de otorgar poderes o sustituir el que se le otorga, no autoriza al mandatario para dar facultades no comprendidas en el mandato, ni más amplias que las que le fueron conferidas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('508e6c70-f69c-408a-bc98-49c72efce1a8', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1703', NULL, 1579, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d14d4890-9b8d-4597-a026-e23db109d5de', '508e6c70-f69c-408a-bc98-49c72efce1a8', 1, 'Es nulo lo que el apoderado haga excediéndose de los límites del mandato o sin contener éste las facultades necesarias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1ce3df65-9fb8-4553-91b6-f63e84f9af44', 'a0000000-0000-0000-0000-000000000001', '16c3e6f7-9b15-4bbf-97fe-52559ab51860', '1704', NULL, 1580, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f4d08a2-2571-48ab-a195-c7b09fdb277e', '1ce3df65-9fb8-4553-91b6-f63e84f9af44', 1, 'El testimonio de la escritura pública del mandato y el de la revocación deben presentarse al Registro de Poderes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9774d2e6-5428-4c46-ba66-0b32f5ba5e4f', '1ce3df65-9fb8-4553-91b6-f63e84f9af44', 2, 'OBLIGACIONES DEL MANDATARIO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5c373d20-169e-4973-b01a-706f631e3ac9', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1705', NULL, 1581, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34c73709-5eb9-4bd4-a575-d9ecfca9554b', '5c373d20-169e-4973-b01a-706f631e3ac9', 1, 'El mandatario queda obligado por la aceptación, a desempeñar con diligencia el mandato y a responder de los daños y perjuicios que, de no ejecutarlo, se ocasionen al mandante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7695e20-21b8-4fdc-9d68-54c6edd2606b', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1706', NULL, 1582, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7af91f0d-911f-408e-92a8-3aad2987ca38', 'b7695e20-21b8-4fdc-9d68-54c6edd2606b', 1, 'El mandatario debe sujetarse a las instrucciones del mandante, y no separarse ni excederse de las facultades y límites del mandato. Está obligado a dar cuenta de su administración, a informar de sus actos y a entregar los bienes del mandante que tenga en su poder, en cualquier tiempo en que este lo pida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('758b9c3b-e07f-469f-b7b8-1e1279ad7be7', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1707', NULL, 1583, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95c6a72d-65c2-411b-809a-ab3d70bfbd8b', '758b9c3b-e07f-469f-b7b8-1e1279ad7be7', 1, 'El apoderado debe desempeñar personalmente el mandato y sólo podrá sustituirlo si estuviere facultado expresamente para hacerlo. Queda libre de responsabilidad el apoderado cuando hace la sustitución en la persona designada por el mandante.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e5e6d792-1ea7-40bd-89ec-2a9fa6ef26d6', '758b9c3b-e07f-469f-b7b8-1e1279ad7be7', 2, 'Si la designación se hiciere por el apoderado, éste es responsable si la sustitución recayere en persona notoriamente incapaz o insolvente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aaf0f8ea-32cc-4542-b1af-43dcc1bf6f9c', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1708', NULL, 1584, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f626295b-b4be-4d20-a741-b9122396e4af', 'aaf0f8ea-32cc-4542-b1af-43dcc1bf6f9c', 1, 'Aceptado el mandato no puede el apoderado renunciarlo sin justa causa cuando hubiere negocios pendientes de cuya interrupción pueden resultar perjuicios al mandante; y si lo renuncia, deberá continuar la gestión de los asuntos pendientes hasta que se le remplace.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('39559e3f-f6fd-4a46-854e-7dad7bebcfae', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1709', NULL, 1585, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bcb069ca-8042-4c5d-ae4c-cc8008af5182', '39559e3f-f6fd-4a46-854e-7dad7bebcfae', 1, 'Cuando el mandatario queda inhabilitado o le sobrevienen causas de incompatibilidad y el mandante no ha designado sustituto, podrá el juez nombrarlo bajo su responsabilidad para mientras aquél lo hace, pero solamente para continuar los asuntos pendientes de carácter urgente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a8469a97-e6f1-4a05-89b4-5fd757297adb', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1710', NULL, 1586, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('626421ea-9a74-4424-b47c-23e74f42be5d', 'a8469a97-e6f1-4a05-89b4-5fd757297adb', 1, 'Sin la autorización previa y escrita del mandante, no puede el mandatario usar ni adquirir para sí ni para sus parientes legales las sumas o bienes que de él haya recibido o por su cuenta; bajo pena de nulidad y pago de daños y perjuicios que se sobrevengan al mandante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('21c55ba0-b4e2-43b9-a327-071b8e2ae01a', 'a0000000-0000-0000-0000-000000000001', '6025db2a-750f-49d7-ae86-e53c1e5b7448', '1711', NULL, 1587, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d6aa9fe-d589-4ea6-b442-3e43c9e42bbd', '21c55ba0-b4e2-43b9-a327-071b8e2ae01a', 1, 'Si una causa imprevista y fundada hiciere perjudicial a juicio del mandatario la ejecución de las instrucciones recibidas, podrá suspender su cumplimiento, bajo su responsabilidad, dando cuenta al mandante por el medio más rápido posible.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc3d51eb-8a9c-420f-8359-5477633521e5', '21c55ba0-b4e2-43b9-a327-071b8e2ae01a', 2, 'OBLIGACIONES DEL MANDANTE');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f8b13fb4-ae03-4425-87ec-14d881e0fd85', 'a0000000-0000-0000-0000-000000000001', 'd4a22401-a43b-43ce-bb37-8d32836226aa', '1712', NULL, 1588, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e1777c30-927c-49e7-92ba-6f2b07173d0b', 'f8b13fb4-ae03-4425-87ec-14d881e0fd85', 1, 'El mandante debe cumplir todas las obligaciones que el mandatario haya contraído dentro de los límites del mandato. En lo que el mandatario se haya excedido, no queda obligado el mandante sino cuando lo ratifica expresa o tácitamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3b3c6022-2f83-422d-9b2d-475ce130a6a4', 'a0000000-0000-0000-0000-000000000001', 'd4a22401-a43b-43ce-bb37-8d32836226aa', '1713', NULL, 1589, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f1ef9f3-fe71-4e2b-b35d-cb5d30166034', '3b3c6022-2f83-422d-9b2d-475ce130a6a4', 1, 'El mandante debe anticipar al mandatario, si éste lo pide, las cantidades necesarias para la ejecución del mandato. Si el mandatario las hubiera anticipado, debe reembolsarlas el mandante, aunque el negocio no haya salido bien, siempre que el mandatario no haya incurrido en culpa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('58e91b8d-c612-40b4-a36a-8fc663c5729e', '3b3c6022-2f83-422d-9b2d-475ce130a6a4', 2, 'El reembolso comprenderá los intereses de la cantidad anticipada, a contar desde el día en que se hizo la anticipación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9cb10ea9-5c07-4fc0-b3e5-da0ee01d8f30', 'a0000000-0000-0000-0000-000000000001', 'd4a22401-a43b-43ce-bb37-8d32836226aa', '1714', NULL, 1590, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d6536411-f2b3-4eaf-9ae5-c1f268385ac0', '9cb10ea9-5c07-4fc0-b3e5-da0ee01d8f30', 1, 'Debe también el mandante indemnizar al mandatario de todos los daños y perjuicios que le haya causado el cumplimiento del mandato, sin culpa ni dolo del mismo mandatario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('675d3394-e577-4b74-ae51-4d7b080fecef', 'a0000000-0000-0000-0000-000000000001', 'd4a22401-a43b-43ce-bb37-8d32836226aa', '1715', NULL, 1591, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('81bb6284-0892-4af2-8fc6-20b7b8cd8014', '675d3394-e577-4b74-ae51-4d7b080fecef', 1, 'El mandatario podrá retener las cosas que son objeto del mandato hasta que el mandante realice la indemnización y rembolso de que tratan los artículos anteriores.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5ff0f596-fd5e-4fca-8fdf-27e38fe1678f', 'a0000000-0000-0000-0000-000000000001', 'd4a22401-a43b-43ce-bb37-8d32836226aa', '1716', NULL, 1592, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f71db7e-066b-47eb-8f27-0722642692c7', '5ff0f596-fd5e-4fca-8fdf-27e38fe1678f', 1, 'Si dos o más personas han nombrado un mandatario para un negocio común, quedan obligadas solidariamente para todos los efectos del mandato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('880c27f6-8997-4af4-b064-bf6d6d15548c', '5ff0f596-fd5e-4fca-8fdf-27e38fe1678f', 2, 'TERMINACION DEL MANDATO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('abfd5eb7-af93-4cc8-b2a3-2033cee34317', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1717', NULL, 1593, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f37032d-80c6-47bb-a1cd-d930f61b0f3b', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 1, 'El mandato termina: 1. Por vencimiento del término para el que fue otorgado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('447a46ba-9a3f-4d5b-8b81-c2d4403af43b', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 2, '2. Por concluirse el asunto para el que se dio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25da869e-03c5-4d60-832a-09167acdbbf1', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 3, '3. Por revocación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2d0c505-2923-4c54-a5da-9ec5a274bfa4', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 4, '4. Por renuncia del mandatario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('01d543d1-910c-4539-8037-088af9654e6d', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 5, '5. Por muerte o interdicción del mandante o del mandatario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b513d119-0c66-437b-a096-97282cb1b271', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 6, '6. Por quiebra del mandante o porque sobrevenga al mandatario causa que conforme a la ley lo inhabilite para ejercer mandatos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('63e812b2-76c4-4ffa-8d98-ff486dbdbbec', 'abfd5eb7-af93-4cc8-b2a3-2033cee34317', 7, '7. Por disolución de la persona jurídica que lo hubiere otorgado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('68ada5b3-ce9f-422b-8591-74a56e2d3fb8', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1718', NULL, 1594, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99d5d989-c1a6-403f-bb57-9328c605d1c0', '68ada5b3-ce9f-422b-8591-74a56e2d3fb8', 1, 'La revocación deberá notificarse tanto al mandatario como a las personas interesadas en el asunto o negocio pendiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c6645e5d-1ad8-40db-bbc6-f8948d78f6eb', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1719', NULL, 1595, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cff9cd5e-eb76-4ad6-b5d4-e21a499f38c5', 'c6645e5d-1ad8-40db-bbc6-f8948d78f6eb', 1, 'La revocación notificada únicamente al mandatario no puede oponerse a terceros que ignorándolo hubieren tratado con él y así lo prueben; pero en tal caso queda al mandante su derecho expedito contra el mandatario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc4118e9-cf78-4bcf-801a-7bec1aeb6b39', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1720', NULL, 1596, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fa52ce76-35d9-411c-9ef4-792fc645b1cd', 'dc4118e9-cf78-4bcf-801a-7bec1aeb6b39', 1, 'El nombramiento de nuevo mandatario para que se encargue del mismo o de los mismos asuntos o negocios, sin expresar que queda vigente el mandato anterior, equivale a la revocación de éste. Los efectos de la revocación comienzan desde el día en que se notifica al anterior mandatario el nombramiento del sucesor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5df9810e-946e-41c5-8f40-da476744770a', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1721', NULL, 1597, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6e6cea12-4e81-4186-b282-609fa716cf41', '5df9810e-946e-41c5-8f40-da476744770a', 1, 'Por la revocación que el mandante haga del mandato quedan revocados los poderes y las sustituciones que el apoderado haya otorgado, salvo que el poderdante expresamente los confirme. Esta revocación debe notificarse a los sustitutos para que surta sus efectos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('82eed37a-4bae-4aad-b65d-e258b84c0fcd', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1722', NULL, 1598, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45a73ea7-8483-41a1-9901-58c101f437e1', '82eed37a-4bae-4aad-b65d-e258b84c0fcd', 1, 'Muerto el mandante, el apoderado deberá continuar ejerciendo el mandato, pero solamente para asuntos pendientes y mientras se apersonan los representantes legales; y en ningún caso para nuevos negocios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb1859af-9323-4619-92d1-236030b41aa3', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1723', NULL, 1599, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('24e72176-6ed1-4f38-b025-fee5a848ea84', 'eb1859af-9323-4619-92d1-236030b41aa3', 1, 'Lo que haya hecho el mandatario después de la muerte del mandante o de haber sido cesado en el cargo, será válido si procedió ignorando esas circunstancias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a3587aa-36b4-4f52-8202-84f40bc07601', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1724', NULL, 1600, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8df033f3-bce2-4b66-85f5-ef170fcd4b6a', '3a3587aa-36b4-4f52-8202-84f40bc07601', 1, 'En caso de muerte del mandatario, sus herederos o cualquier persona que tenga interés, deberán dar aviso al mandante y mientras éste resuelve lo conveniente, harán lo que las circunstancias exijan para la conservación de los bienes. En ausencia del mandante, el aviso se dará al juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4892942b-9e51-4d7c-a6d5-f654308279b3', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1725', NULL, 1601, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4e141e5-aa7e-4e42-bc1f-d06d22f57541', '4892942b-9e51-4d7c-a6d5-f654308279b3', 1, 'Pasa a los herederos del mandatario la obligación de rendir cuentas al mandante cuando aquél hubiere administrado bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb8370a3-4a36-4961-87d8-c11a4dee992c', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1726', NULL, 1602, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2f9c54e3-96ac-4ddd-89be-d33c7cbdce28', 'eb8370a3-4a36-4961-87d8-c11a4dee992c', 1, 'El mandato general que no exprese duración, se considera conferido por diez años contados desde la fecha del otorgamiento salvo prórroga otorgada con las mismas formalidades del mandato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d12e31a2-78ae-4ba6-9909-1c532431f91c', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1727', NULL, 1603, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2fc4ea55-99f5-42c5-8b87-953d76bf8cfa', 'd12e31a2-78ae-4ba6-9909-1c532431f91c', 1, 'Las acciones derivadas del mandato que no tengan término especial de prescripción, duran un año contado de la fecha en que terminó el mandato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7b985ab0-7451-47df-9af2-6c6a08cb8ae2', 'd12e31a2-78ae-4ba6-9909-1c532431f91c', 2, 'DE LA SOCIEDAD.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56e4c366-6800-417d-bc2c-a25c807583b2', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1728', NULL, 1604, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c81fed3e-1c69-4feb-acac-52df1c6d0f7a', '56e4c366-6800-417d-bc2c-a25c807583b2', 1, 'La sociedad es un contrato por el que dos o más personas convienen en poner en común bienes o servicios para ejercer una actividad económica y dividirse las ganancias.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0a8afc34-ac59-42d2-8964-f52364984533', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1729', NULL, 1605, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('034fc0d8-72de-49ac-83fe-071cfea54419', '0a8afc34-ac59-42d2-8964-f52364984533', 1, 'La sociedad debe celebrarse por escritura pública e inscribirse en el Registro respectivo para que pueda actuar como persona jurídica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60b7fe36-71a8-4bce-8164-ce7d55336832', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1730', NULL, 1606, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea2e9141-e8e1-4094-a754-24ec2fd7a9a0', '60b7fe36-71a8-4bce-8164-ce7d55336832', 1, 'La escritura de sociedad deberá expresar lo siguiente: 1. Objeto de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93110464-24fa-4263-b249-fedd94eddc3e', '60b7fe36-71a8-4bce-8164-ce7d55336832', 2, '2. Razón social;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7b1cbfb9-a3f5-4c8a-95f3-5dc13a2ccc5b', '60b7fe36-71a8-4bce-8164-ce7d55336832', 3, '3. Domicilio de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e279303-7dbc-4067-bdba-6e6d650ff879', '60b7fe36-71a8-4bce-8164-ce7d55336832', 4, '4. Duración de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a08f0e5-e655-46c5-9fe3-7adf696017c6', '60b7fe36-71a8-4bce-8164-ce7d55336832', 5, '5. Capital y la parte que aporta cada socio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('acb3a865-3816-47ff-a23f-2d53b6985d12', '60b7fe36-71a8-4bce-8164-ce7d55336832', 6, '6. Parte de utilidades o pérdidas que se asigne a cada socio, fecha y forma de su distribución;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb4ccf9e-dffa-4841-b059-35f81547ad19', '60b7fe36-71a8-4bce-8164-ce7d55336832', 7, '7. Casos en que procederá la disolución de la sociedad antes de su vencimiento; y las bases que en todo caso de disolución deberán observarse para la liquidación y división del haber social;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e831a45f-805b-4af3-bd69-bb26cb89ad7c', '60b7fe36-71a8-4bce-8164-ce7d55336832', 8, '8. Cantidad que puede tomar periódicamente cada socio para sus gastos personales;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67a48ab0-1d39-4b5b-bc0a-41976cc0d3b5', '60b7fe36-71a8-4bce-8164-ce7d55336832', 9, '9. Modo de resolver las diferencias que surjan entre los socios; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d1eecb3e-c746-459c-83e5-183615c56201', '60b7fe36-71a8-4bce-8164-ce7d55336832', 10, '10. La forma de administración de la sociedad, y los demás pactos que acuerden los socios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fdb5ef7-566a-4465-94d7-a10aa14284f2', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1731', NULL, 1607, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b709057-eb2f-4fb6-a336-1efb04f6462f', '6fdb5ef7-566a-4465-94d7-a10aa14284f2', 1, 'Si la sociedad se constituye para propósito u objeto que por su naturaleza tenga duración limitada, pero cuyo plazo no sea posible fijar, se entenderá que su duración será por el tiempo necesario para la realización de aquel objeto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6899aa33-469f-47d7-a5b7-2d226fd0ce5d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1732', NULL, 1608, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bfc8ccf5-ddcf-4ec2-af14-bda8294ce89d', '6899aa33-469f-47d7-a5b7-2d226fd0ce5d', 1, 'Son nulas y se tienen por no puestas las cláusulas del contrato de sociedad en que se estipule que alguno de los socios no participará en las ganancias o que la parte del capital o bienes que aporte estarán libres de responsabilidad o riesgo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b2618a8-30eb-4a5c-a4a8-e4d1f927a942', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1733', NULL, 1609, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27c7418e-7a64-416d-a8dc-aa37d01815ac', '7b2618a8-30eb-4a5c-a4a8-e4d1f927a942', 1, 'No pueden los socios hacer pacto alguno reservado, ni oponer contra el contenido de la escritura de sociedad ningún documento privado ni prueba testimonial.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a11814d-47c4-465f-8579-a726b92ae42f', '7b2618a8-30eb-4a5c-a4a8-e4d1f927a942', 2, 'Las ampliaciones o modificaciones sobre este contrato, se harán con las mismas solemnidades y requisitos exigidos para su celebración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('807fd395-ad58-4a92-891b-2947a448eb72', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1734', NULL, 1610, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('901503d1-39cc-43bc-b8ce-af36c3cd34a4', '807fd395-ad58-4a92-891b-2947a448eb72', 1, 'La aportación de bienes implica la transmisión de su dominio a la sociedad como persona jurídica, salvo que expresamente se pacte otra cosa. Los inmuebles o derechos reales sobre los mismos, deberán inscribirse en el Registro de la Propiedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c93c1e8b-6028-41fa-a3a4-1f9c586e8e0e', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1735', NULL, 1611, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('978b03ca-2066-4740-94fe-94fff3cb9808', 'c93c1e8b-6028-41fa-a3a4-1f9c586e8e0e', 1, 'El socio que contrate en nombre de la sociedad antes de que ésta pueda actuar como persona jurídica, queda directamente responsable por los efectos del contrato celebrado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cae1dde9-50a2-4d83-9ef2-4b1c489013b3', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1736', NULL, 1612, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a3d0d19-4ac4-4bfa-9645-68e80a863c67', 'cae1dde9-50a2-4d83-9ef2-4b1c489013b3', 1, 'Los cónyuges no pueden celebrar entre sí contrato de sociedad que implique la formación de una persona jurídica, salvo que figuren como consocios terceras personas. Se exceptúa también el caso de sustitución legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d9a7aa26-c79f-45e8-b326-72275ee7c144', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1737', NULL, 1613, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8bd0b416-1ece-46ec-af69-3394edc6ee92', 'd9a7aa26-c79f-45e8-b326-72275ee7c144', 1, 'Durante el matrimonio no puede la mujer, sin el consentimiento del marido, ni éste sin el de aquélla, celebrar con terceros contrato de sociedad en relación a bienes comunes o aportar a una sociedad esta clase de bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('308ee2a2-2b54-43f5-b341-1e3b72ff1a03', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1738', NULL, 1614, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b30d9cb-ec79-43d7-af14-79b375d109ed', '308ee2a2-2b54-43f5-b341-1e3b72ff1a03', 1, 'El tutor y el guardador no pueden celebrar contrato de sociedad con sus representados mientras no haya terminado la minoría de edad o la incapacidad y estén aprobadas las cuentas de la tutela y canceladas las garantías.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('120fec9f-dbdf-459e-b7bf-50708280c44d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1739', NULL, 1615, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c0993c8-9bbd-41c2-86da-75760164f3eb', '120fec9f-dbdf-459e-b7bf-50708280c44d', 1, 'No pueden celebrar contratos de sociedad los declarados en quiebra mientras no hayan sido rehabilitados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ab69a250-2ab2-4618-a481-eb0e9d43c05c', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1740', NULL, 1616, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c4a1ee12-5176-42ec-bb72-e6d170927e0c', 'ab69a250-2ab2-4618-a481-eb0e9d43c05c', 1, 'Por los menores o incapaces podrán sus representantes celebrar contrato de sociedad, previa autorización Judicial por utilidad comprobada. La responsabilidad de los menores o incapaces se limitará al monto de su aportación entregada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3e425874-7dbb-494c-8fdf-47d46f2a301f', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1741', NULL, 1617, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11fdccca-9024-4a64-944c-b09fe415acdb', '3e425874-7dbb-494c-8fdf-47d46f2a301f', 1, 'La razón o firma social se formará con el nombre y apellido de uno de los socios; o los apellidos de dos o más, con la agregación de las palabras "Sociedad Civil".');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d39a477d-fed6-4b64-b8c7-50d3c5810d0c', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1742', NULL, 1618, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40112910-00a6-4701-81e6-d4969be5e531', 'd39a477d-fed6-4b64-b8c7-50d3c5810d0c', 1, 'Las obligaciones sociales se garantizan con los bienes de la sociedad; y si éstos no fueren suficientes, con los bienes propios de los socios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78ff6ce0-c2af-442d-81e8-d3e08dfbccf2', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1743', NULL, 1619, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8e648faf-481e-4b08-b661-4fc053ca9f16', '78ff6ce0-c2af-442d-81e8-d3e08dfbccf2', 1, 'A la sociedad no pueden ser aportados como capital social de menores sus bienes inmuebles o derechos de propiedad sobre ellos, pero sí los frutos o productos de dichos bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9a5505c0-f1d5-471f-840d-d0d3b459365d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1744', NULL, 1620, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0f5c9a01-58f3-4064-a66d-4b3df7359e38', '9a5505c0-f1d5-471f-840d-d0d3b459365d', 1, 'Los socios deben poner en la masa común dentro del plazo convenido, sus respectivos capitales; y contra el moroso puede la sociedad proceder');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b858bf2-4e75-4e45-bcc8-afddaa0e2480', '9a5505c0-f1d5-471f-840d-d0d3b459365d', 2, 'ejecutivamente hasta que se verifique la entrega o rescindir el contrato en cuanto a dicho socio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c71149f6-85bb-44d3-af35-571f401f9a05', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1745', NULL, 1621, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d6dba02b-f05c-4166-b593-907601e4ea73', 'c71149f6-85bb-44d3-af35-571f401f9a05', 1, 'Cada socio está obligado a entregar y sanear a la sociedad la cosa que prometió.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('421308b2-26fc-4ce2-86ec-5e1a19e21705', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1746', NULL, 1622, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b33b9a2f-c4b6-4707-b64a-819e31a203e1', '421308b2-26fc-4ce2-86ec-5e1a19e21705', 1, 'El socio que retarde la entrega de su capital, cualquiera que sea la causa, debe abonar a la sociedad el interés legal del dinero que no entregó a su debido tiempo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56d56d64-ddac-42da-abde-628978f69e05', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1747', NULL, 1623, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('646be515-a694-488c-a1ec-d37650f97de5', '56d56d64-ddac-42da-abde-628978f69e05', 1, 'Los socios que ponen su industria en común, darán cuenta a la sociedad de las utilidades que hayan obtenido del ejercicio de esa industria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a8767c2-a675-4c32-8c93-3609e9250d92', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1748', NULL, 1624, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c475a442-c2e6-47fd-86af-653b8cdd0d1c', '3a8767c2-a675-4c32-8c93-3609e9250d92', 1, 'El riesgo de las cosas ciertas y determinadas, no fungibles, que se aportan a la sociedad para que sólo sean comunes su uso, frutos o productos, corresponde al socio propietario. Si las cosas aportadas son fungibles o no pueden guardarse sin que se deterioren, o se aportaron para ser vendidas, el riesgo corresponde a la sociedad. También corresponderá a la misma, a falta de pacto especial, el riesgo de las cosas justipreciadas al aportarse y, en este caso, la reclamación se limitará al precio en que fueron tasadas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3781a58f-4dc2-4bfa-9da1-2340dd1e6895', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1749', NULL, 1625, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('618dbffb-5a6a-4cfd-874f-165f3175bffa', '3781a58f-4dc2-4bfa-9da1-2340dd1e6895', 1, 'Cualquier daño o perjuicio causado en los intereses de la sociedad por dolo, abuso de facultades o negligencia grave de algún socio, constituye a su autor en la obligación de indemnizarlo si los consocios lo exigen, con tal que no pueda colegirse de acto alguno la aprobación o ratificación expresa o virtual del hecho sobre que se funda la reclamación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ccebd964-a7dc-4a35-b5ab-17e31384888c', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1750', NULL, 1626, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3ff9f4dc-10f8-4ce6-a2be-e03b4fc5ccc9', 'ccebd964-a7dc-4a35-b5ab-17e31384888c', 1, 'Ningún socio puede distraer ni segregar del fondo común para sus gastos particulares, mayor cantidad que la designada a cada uno en las cláusulas del contrato. Además de responder los socios por los daños o perjuicios que resulten a la sociedad, a causa de haber ellos tomado cantidades del fondo común, abonarán el interés legal correspondiente a éstas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3582c946-19ee-4011-b9a1-f864003a3630', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1751', NULL, 1627, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('607477ce-5d5f-4841-8d71-fe18cc7f858b', '3582c946-19ee-4011-b9a1-f864003a3630', 1, 'La sociedad abonará a los socios los gastos que hicieren al desempeñar los negocios de ella, y les indemnizará de los daños o perjuicios que les sobrevinieren con ocasión inmediata y directa de los mismos negocios; pero no de los que hayan sufrido por culpa suya o por caso fortuito o por otra causa independiente, mientras se ocupaban en servicio de la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('55839865-f445-4d2f-a340-7f16ff907234', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1752', NULL, 1628, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eb05acf6-3720-4dfa-91bf-46cca87682c2', '55839865-f445-4d2f-a340-7f16ff907234', 1, 'En caso de no haberse determinado en el contrato la parte que cada socio deba tener en las ganancias o pérdidas, se dividirán unas y otras a prorrata del capital que cada uno aportó a la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('abce48d7-d289-4c2c-b52a-cb39088af440', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1753', NULL, 1629, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c486b640-ca34-4263-b6c3-9b74530645ee', 'abce48d7-d289-4c2c-b52a-cb39088af440', 1, 'Si se estipuló la parte de las ganancias sin mencionarse la de las pérdidas, se hará la distribución de éstas en la misma proporción que la de aquéllas y al contrario; de modo que la expresión de las unas sirva para las otras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eef075b5-59c8-416f-9467-68a54f48e271', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1754', NULL, 1630, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('86f6dbc8-2bd3-47e5-a3e4-1fcb7477c271', 'eef075b5-59c8-416f-9467-68a54f48e271', 1, 'La parte que deba tener en la ganancia el socio que no aportó más que su industria, será igual a la porción correspondiente al socio que contribuyó con más capital; y si son iguales los capitales, o es uno sólo el socio que lo ha aportado, la ganancia del socio industrial será igual a la de los otros.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f2fa9662-04cf-45ff-9be8-6bdc9d5ca31d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1755', NULL, 1631, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a385ba0-e784-4687-b8e6-bea831315bdc', 'f2fa9662-04cf-45ff-9be8-6bdc9d5ca31d', 1, 'El socio industrial, sufrirá también las pérdidas, cuando sean mayores que todo el capital de la sociedad; y entonces participará de ellas sólo en la parte que excedan del capital.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b228e761-d05f-4121-bd42-993ae896d4e5', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1756', NULL, 1632, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91d3279d-05d2-4d5d-bdae-9431e7c2c790', 'b228e761-d05f-4121-bd42-993ae896d4e5', 1, 'No puede reclamar contra la distribución de las ganancias o pérdidas el socio que la aceptó expresa o tácitamente, ni el que hubiese dejado pasar tres meses desde que tuvo conocimiento de ella, sin usar de su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5877618-d7c1-4255-9454-908a5e2f375d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1757', NULL, 1633, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('30786ed7-ce9c-4a15-985c-0e40303644d9', 'b5877618-d7c1-4255-9454-908a5e2f375d', 1, 'La administración de los negocios de la sociedad, debe sujetarse a lo dispuesto en el contrato. Si está encargada a uno o más de los socios, los demás no pueden oponerse ni revocarle la administración sino en los casos de dolo, culpa, inhabilidad o incumplimiento de sus obligaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b5c1511b-4269-45dc-a050-1a11bc08a48a', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1758', NULL, 1634, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('266bd2fa-5d6f-44cb-b802-42c32b6acbde', 'b5c1511b-4269-45dc-a050-1a11bc08a48a', 1, 'A falta de convenios especiales sobre la administración, se observarán las reglas siguientes: 1. Cada socio es administrador; y, como tal, puede obrar a nombre de la sociedad sin perjuicio del derecho de los otros para oponerse a un acto antes que se perfeccione;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0522460-7cf6-4d52-8f4d-9c737c39e065', 'b5c1511b-4269-45dc-a050-1a11bc08a48a', 2, '2. Puede asimismo cada socio servirse de los bienes puestos en común, empleándolos en su destino natural; sin perjudicar los intereses de la sociedad, ni impedir que los demás socios usen de igual derecho;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f11d2625-e42d-4c08-b00a-0336878c34b0', 'b5c1511b-4269-45dc-a050-1a11bc08a48a', 3, '3. Cada uno de los socios tiene el derecho de obligar a los demás para que concurran a los gastos que exige la conservación de las cosas de la sociedad; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44a2e1de-eca2-44ff-8bb3-42ef7f72824b', 'b5c1511b-4269-45dc-a050-1a11bc08a48a', 4, '4. Ninguno de los socios puede hacer innovaciones en los bienes inmuebles que dependen de la sociedad, aun cuando las considere ventajosas a ella si no consienten los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f02f416f-3625-4622-8364-3d8f5f185161', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1759', NULL, 1635, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f8c9411f-a310-4b68-98ee-c13aaa60807d', 'f02f416f-3625-4622-8364-3d8f5f185161', 1, 'El socio que no es administrador, no puede celebrar ningún contrato sobre los bienes pertenecientes a la sociedad, aunque sean muebles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bed4f2d0-5a3e-4295-ab19-56b81c4d79ad', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1760', NULL, 1636, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ff76675-e7b2-48a8-a07d-de286c6ea11d', 'bed4f2d0-5a3e-4295-ab19-56b81c4d79ad', 1, 'Ningún socio puede transmitir a otra persona, sin consentimiento de los demás, el interés que tenga en la sociedad; ni ponerla en lugar suyo para que desempeñe los oficios que le tocan en la administración de los negocios sociales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('21de8daf-8c33-4a0a-8164-1a661d68c5f8', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1761', NULL, 1637, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a8b41c6-f074-44e5-9193-ad39e774696e', '21de8daf-8c33-4a0a-8164-1a661d68c5f8', 1, 'Son obligatorios para todos los socios los contratos celebrados por el socio administrador, o por el que estuviese autorizado para ello.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2063f7f1-09d3-470d-b378-cd82492e119f', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1762', NULL, 1638, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('98828420-2905-4dc6-9ef4-a1935e57c743', '2063f7f1-09d3-470d-b378-cd82492e119f', 1, 'Quedan igualmente obligados todos los socios por la deuda de que se ha aprovechado la sociedad, aunque se haya contraído por algún socio sin autorización.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('927cb53e-29d3-41ff-806f-80bd35347d74', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1763', NULL, 1639, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ca0ddc6-83af-4738-aa9f-fb8b019f4e1e', '927cb53e-29d3-41ff-806f-80bd35347d74', 1, 'No debe contraerse obligación nueva si expresamente lo contradice uno de los socios administradores; pero si llegare a contraerse producirá sus efectos legales en cuanto al acreedor y el que la contrajo, quedará responsable de los daños o perjuicios que cause a la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1e776aa-fe73-4cd6-bb1a-87158a35da3a', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1764', NULL, 1640, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad052d4f-fc88-4a0b-a1cd-54938bf9b012', 'd1e776aa-fe73-4cd6-bb1a-87158a35da3a', 1, 'Todos los socios tienen derecho de examinar el estado de la administración, y de hacer las reclamaciones convenientes al interés común, con arreglo a lo pactado en la escritura de sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6f45b788-80c7-4c24-974d-1ff5806881ad', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1765', NULL, 1641, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb657cd8-cfbe-4d77-8aae-91ea29bd400e', '6f45b788-80c7-4c24-974d-1ff5806881ad', 1, 'El pago hecho a uno de los socios administradores por un deudor particular suyo, que lo es también de la sociedad, se imputará proporcionalmente a ambos créditos, aunque el socio lo hubiere aplicado íntegramente en la carta de pago a su crédito particular; pero si se aplicó al crédito de la sociedad, se cumplirá esta disposición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9288deb8-98b0-4830-87ed-021dc6cbc4c4', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1766', NULL, 1642, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87856369-4b67-480c-8695-f4066bf5eafe', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 1, 'Puede rescindirse el contrato de la sociedad parcialmente, o disolverse y extinguirse en su totalidad. Se rescinde parcialmente:');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50338d77-c2d2-4466-8746-acad301c25e9', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 2, '1. Si un socio para sus negocios propios usa del nombre, de las garantías o del patrimonio perteneciente a la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ce7915d7-b8e7-4521-93a1-3bd6cf61b969', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 3, '2. Si ejerce funciones administrativas el socio a quien no corresponde desempeñarlas, según el contrato de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5a02fbf-d696-43ba-ac9c-d66308cfa36b', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 4, '3. Si el socio administrador comete fraude en la administración o cuentas de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('872ae368-1554-4865-b977-63ed797bf7be', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 5, '4. Si cualquiera de los socios se ocupa de sus negocios privados, cuando está obligado por el contrato a ocuparse en provecho de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5286165c-5ff7-496f-bb39-4904eea6f1ea', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 6, '5. Si alguno de los socios incurre en los casos de los artículos 1744 y 1749, según la gravedad de las circunstancias; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0de34b8-2627-4717-905b-d2dee0ee413b', '9288deb8-98b0-4830-87ed-021dc6cbc4c4', 7, '6. Si se ha ausentado el socio que tiene obligación de prestar servicios personales a la sociedad; y requerido para regresar no lo verifica, o manifiesta que está impedido para hacerlo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('71414167-d43a-4922-bfdb-e3820beb9b80', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1767', NULL, 1643, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6304dcf8-a7ca-4aff-9305-264448f6448a', '71414167-d43a-4922-bfdb-e3820beb9b80', 1, 'Rescindido parcialmente el contrato, queda el socio culpable excluido de la sociedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4053ad3a-1def-4f14-8873-56fecbcca726', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1768', NULL, 1644, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f6d6a98f-54de-417c-95e2-92cf34ebce1f', '4053ad3a-1def-4f14-8873-56fecbcca726', 1, 'Se disuelve totalmente el contrato de sociedad: 1. Por concluirse el tiempo convenido para su duración, por acabarse la empresa o el negocio que fue objeto de la sociedad o por haberse vuelto imposible su consecución;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15a7a6d5-7a88-4b42-bb68-2d8ab8d89d9c', '4053ad3a-1def-4f14-8873-56fecbcca726', 2, '2. Por la pérdida de más del cincuenta por ciento del capital, a menos que el contrato social señale un porcentaje menor;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2e478489-8f5e-4185-b296-9c4155f43595', '4053ad3a-1def-4f14-8873-56fecbcca726', 3, '3. Por quiebra de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('20bd1b2c-c38d-4d75-b349-1118607622df', '4053ad3a-1def-4f14-8873-56fecbcca726', 4, '4. Por muerte de uno de los socios; a no ser que la escritura contenga el pacto expreso para que continúen los herederos del socio difunto;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d730754f-fa70-43fb-880e-f2a1c29d78d5', '4053ad3a-1def-4f14-8873-56fecbcca726', 5, '5. Por la interdicción judicial de uno de los socios, o por cualquiera otra causa que le prive de la administración de sus bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ffa6a1fc-12cd-412e-88d7-5b938b8c2d17', '4053ad3a-1def-4f14-8873-56fecbcca726', 6, '6. Por quiebra de cualquiera de los socios; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9f41bf9-bfbc-4f7f-880e-4615eeca4859', '4053ad3a-1def-4f14-8873-56fecbcca726', 7, '7. Por voluntad de uno de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ce461b84-bc47-4613-b985-3808470cd5d8', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1769', NULL, 1645, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf26e3a1-5286-4e44-aae7-d76e9ded3dba', 'ce461b84-bc47-4613-b985-3808470cd5d8', 1, 'En los casos de los incisos 4º, 5º, 6º, y 7º, del artículo anterior, no se entenderá disuelta la sociedad, si quedando dos o más socios quieren de mutuo acuerdo continuarla, o lo hubieren pactado al tiempo de la celebración del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f78b2659-2808-4dce-987a-bd73bdf43438', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1770', NULL, 1646, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7ceac5cd-7599-4c35-a835-dca9e9b9d598', 'f78b2659-2808-4dce-987a-bd73bdf43438', 1, 'La prórroga de una sociedad debe formalizarse antes del vencimiento del plazo y con las mismas solemnidades y requisitos exigidos para la celebración del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8f93abe7-2132-48bb-b4a8-51b5cbd10e50', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1771', NULL, 1647, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2ccb975-7e3d-4306-b541-966fb6a00e89', '8f93abe7-2132-48bb-b4a8-51b5cbd10e50', 1, 'Si uno de los socios promete poner en común la propiedad de una cosa cuya importancia sea tal que equivalga al objeto fundamental del negocio, si ésta se pierde antes de verificarse la entrega, se disuelve el contrato respecto de todos los socios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('08193967-161b-4663-b2a8-5b27b2930b5f', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1772', NULL, 1648, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0beff2b7-ef8c-4e30-a993-b02bade30969', '08193967-161b-4663-b2a8-5b27b2930b5f', 1, 'La cláusula de que muerto un socio continuarán en su lugar sus herederos, no obliga a estos a entrar en la sociedad; pero obliga a los demás socios a recibirlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f0266783-39a0-4015-a112-08ff32f59919', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1773', NULL, 1649, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('deed3a38-277a-4e1e-b496-87b836ec7b08', 'f0266783-39a0-4015-a112-08ff32f59919', 1, 'Si continúa la sociedad después del fallecimiento de un socio y los herederos de éste no entran en ella, sólo tienen derecho a la parte que correspondía al difunto al tiempo de su muerte; y no participan de los resultados posteriores, sino en cuanto sea una consecuencia necesaria de lo practicado antes de la muerte del socio a quien heredan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4b4c1343-1f4f-43e0-8f10-bb7c15b02b30', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1774', NULL, 1650, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7113c0fa-d984-46b2-93a6-2769d2c92f78', '4b4c1343-1f4f-43e0-8f10-bb7c15b02b30', 1, 'La conclusión de la sociedad por voluntad de uno de los socios sólo tiene lugar en las que se celebran por tiempo ilimitado; y cuando el renunciante no procede de mala fe ni intempestivamente. Hay mala fe en el socio que renuncia, cuando pretende hacer un lucro particular, que no tendría, subsistiendo la sociedad; y procede intempestivamente, cuando lo hace en circunstancias de no haberse concluido una negociación y de convenir que continúe la sociedad por algún tiempo más, para evitarse el daño o perjuicio que de lo contrario le resultaría.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed122631-3196-4f0b-911f-a8f079b5f518', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1775', NULL, 1651, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('75d2b3c1-b873-47f8-8431-a1d597cbaf1a', 'ed122631-3196-4f0b-911f-a8f079b5f518', 1, 'Ningún socio puede pedir la disolución de la sociedad celebrada por tiempo determinado antes del plazo convenido; a no ser que para ello concurran motivos justos, como cuando otro socio falta a sus deberes, o el que se separa padece una enfermedad habitual que lo inhabilita para los negocios de la sociedad, o han sobrevenido otras causas, cuya gravedad y legitimidad se dejan al arbitrio del juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('94477556-26e3-4050-be1c-223a8f392e69', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1776', NULL, 1652, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e3d50e25-f922-44ee-a2c6-bcd0e8e70569', '94477556-26e3-4050-be1c-223a8f392e69', 1, 'Los socios están obligados recíprocamente a darse cuenta de la administración y sus resultados, tanto activos como pasivos, pasan a sus herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dc5fc63d-0628-4f6d-b865-fa4622404c52', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1777', NULL, 1653, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e6006b65-4a70-48e4-9576-bd945b54476f', 'dc5fc63d-0628-4f6d-b865-fa4622404c52', 1, 'Terminada la sociedad, subsistirá la persona jurídica pero solamente para los efectos de la liquidación, correspondiendo a los liquidadores representarla en juicio activa y pasivamente. Al entrar en liquidación se agregarán a la razón social las palabras: "en liquidación".');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('197fb188-39de-4365-95c2-c0c4ee168ae3', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1778', NULL, 1654, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('73cf9cf9-8a9b-4683-99c0-899711340126', '197fb188-39de-4365-95c2-c0c4ee168ae3', 1, 'La liquidación de la sociedad deberá hacerse en la forma y por las personas que exprese el contrato social o el convenio de disolución. Si nada se estipuló acerca del nombramiento del liquidador o liquidadores y los socios no se ponen de acuerdo, el nombramiento se hará por el juez competente, debiendo recaer en persona de reconocida responsabilidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54d9211a-e765-4f7e-8662-a612b87dca12', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1779', NULL, 1655, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6ce0c535-e1b9-467e-8424-1eac169eddd1', '54d9211a-e765-4f7e-8662-a612b87dca12', 1, 'El liquidador es un mandatario y como tal deberá sujetarse a las reglas que se le hubieren señalado; si fuere nombrado por el Juez y alguno de los socios lo pide, deberá caucionar su responsabilidad a satisfacción del juez. Los acreedores que representen por lo menos el veinticinco por ciento del pasivo de la sociedad pueden pedir también que el liquidador, cualquiera que sea la procedencia de su nombramiento, caucione su responsabilidad a satisfacción del mismo funcionario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b1ed26c6-7194-45a1-92f1-c5c2c78a6caf', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1780', NULL, 1656, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e03ac082-718f-4d52-ad94-f3ba818f6dfa', 'b1ed26c6-7194-45a1-92f1-c5c2c78a6caf', 1, 'Si fueren varios los liquidadores deberán proceder conjuntamente, y su responsabilidad será solidaria. La discrepancia de pareceres entre ellos será sometida a la resolución de los socios, y en su defecto el juez competente decidirá.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca14e93b-a265-4a88-ac1d-e9371535431b', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1781', NULL, 1657, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9d56c5f2-a34e-4109-9e93-0caecc99b577', 'ca14e93b-a265-4a88-ac1d-e9371535431b', 1, 'El término para la liquidación no excederá de seis meses y cuando transcurra éste sin que se hubiere concluido, cualquiera de los socios o de los acreedores podrá pedir al juez competente que fije un término prudencial para concluirla, quien previo conocimiento de causa lo acordará así. Si apareciere que la demora obedece a culpa de los liquidadores procederá su remoción sin perjuicio de las responsabilidades en que hubieren incurrido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ff015043-2075-4e4d-8745-45f8413680b8', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1782', NULL, 1658, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a23befd-9df1-4f90-94c8-3f5a67a70d99', 'ff015043-2075-4e4d-8745-45f8413680b8', 1, 'Hecha la liquidación de la sociedad, se observará en los pagos el orden siguiente: 1. Gastos de liquidación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9bcd278f-d024-4c59-be32-6700ad3fdc3d', 'ff015043-2075-4e4d-8745-45f8413680b8', 2, '2. Deudas de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('006abc19-3af9-4013-b503-b09d165979ac', 'ff015043-2075-4e4d-8745-45f8413680b8', 3, '3. Aportes de los socios; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5276ec1-94fa-49fd-85e9-7c9e17258983', 'ff015043-2075-4e4d-8745-45f8413680b8', 4, '4. Utilidades.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fcb9f259-dc76-4f52-8a04-6f9ca8de7c5f', 'ff015043-2075-4e4d-8745-45f8413680b8', 5, 'Si los bienes de la sociedad no alcanzan a cubrir las deudas, se procederá con arreglo a lo dispuesto en materia de concurso o quiebra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eae05c6c-27a5-4c8f-a8ba-46894aa949cb', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1783', NULL, 1659, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6176983a-e51f-45cc-848c-b4f8ff3ff4e6', 'eae05c6c-27a5-4c8f-a8ba-46894aa949cb', 1, 'Los socios no pueden exigir la restitución de su capital antes de concluirse la liquidación de la sociedad, a menos que consista en el usufructo de los bienes introducidos al fondo común.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('afdad27f-41ca-4c80-8e90-1836b766dece', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1784', NULL, 1660, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c5d1ba7-8f99-485a-badb-a2d29993d13c', 'afdad27f-41ca-4c80-8e90-1836b766dece', 1, 'Terminada la sociedad y practicada la liquidación, el reparto de utilidades se hará por el liquidador o liquidadores observando las disposiciones relativas a la partición de herencia, salvo lo que hubieren estipulado los socios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('267b811d-bc88-44fa-9ea2-3eecef43912d', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1785', NULL, 1661, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('85630dfe-8f70-4f0c-9f29-ee7db5cb45e2', '267b811d-bc88-44fa-9ea2-3eecef43912d', 1, 'No estando determinadas las facultades del liquidador no podrá ejecutar otros actos y contratos que los que tiendan directamente al cumplimiento de su encargo, en consecuencia, el liquidador no podrá gravar los bienes sociales, ni tomar dinero a préstamo, ni transigir sobre los derechos de la sociedad ni someterlos a arbitraje, a menos que, previa Justificación, obtenga autorización judicial para ello.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d14aff4-cfbc-49a4-b578-221bb9c9a601', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1786', NULL, 1662, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e155ed2c-9c73-4e58-9174-b4187dff4f26', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 1, 'Además de los deberes que su título impone al liquidador, estará obligado: 1. A formar inventario al tomar posesión de su cargo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ace51885-5169-4a66-bc02-db4fd27c75d9', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 2, '2. A continuar y concluir las operaciones pendientes al tiempo de la disolución;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7f4556b-9703-485d-98cb-8e8d9b68626c', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 3, '3. A exigir la cuenta de su administración a cualquiera que haya manejado intereses de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7efc527-348e-4f61-8a07-add3382f308c', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 4, '4. A liquidar y cancelar las deudas de la sociedad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f901fbe3-9b3c-40d5-9961-124ae4df6d7c', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 5, '5. A cobrar los créditos activos, percibir su importe, cancelar los gravámenes que los garanticen y otorgar los correspondientes finiquitos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('060ee21b-aaee-4379-b52a-10101e1bf8d0', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 6, '6. A vender los bienes sociales, aun cuando haya algún menor o incapacitado entre los socios, con tal que no hayan sido destinados por éstos para ser adjudicados en especie;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27669c8f-30fa-44ac-8d10-acf9a5ac0579', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 7, '7. A presentar estado de liquidación cuando cualquiera de los socios lo pida; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('90db086c-402a-4ee9-ad39-ced66c67545b', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 8, '8. A rendir al final de la liquidación una cuenta general y comprobada de su administración.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5cd88f98-4f17-4bcd-bd9b-ee1cb4c02d3e', '7d14aff4-cfbc-49a4-b578-221bb9c9a601', 9, 'Si el liquidador fuere el administrador de la sociedad extinguida, deberá presentar en esa época la cuenta de su gestión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('052fcf95-f3be-45cb-9438-9228fc11e728', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1787', NULL, 1663, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2dc80dc6-a84d-42ec-80db-62c755240716', '052fcf95-f3be-45cb-9438-9228fc11e728', 1, 'El liquidador nombrado por los socios puede ser removido por el voto de la mayoría y renunciar el cargo, según las reglas del mandato. El nombrado por el juez, si hubiere aceptado el cargo, solo podrá renunciar por justa causa legalmente comprobada, y ser removido por dolo, culpa, inhabilidad o incumplimiento de sus obligaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('410212b3-87ce-4049-8263-5e1b7d74c712', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1788', NULL, 1664, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bc82179-63f2-4b70-9b32-deaaa0129704', '410212b3-87ce-4049-8263-5e1b7d74c712', 1, 'Haciendo por sí mismos la liquidación, los socios se ajustarán a las reglas precedentes y procederán como en el caso de administración conjunta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7a8ec43-ed25-4728-911b-0626592c1149', 'a0000000-0000-0000-0000-000000000001', '4d5785a8-f803-479d-8370-795db15a2391', '1789', NULL, 1665, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9dba1ed0-90fd-44b9-aaff-9b8b9dbfef89', 'b7a8ec43-ed25-4728-911b-0626592c1149', 1, 'Las acciones de los acreedores contra los socios, las de los socios y acreedores contra el liquidador y las de los socios entre sí prescriben en tres años contados desde la fecha en que termine la liquidación, salvo que la ley fije término menor según la naturaleza de la obligación o del título.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7961e227-c7b6-44ed-9d86-eb32e4b3152d', 'b7a8ec43-ed25-4728-911b-0626592c1149', 2, 'DE LA COMPRAVENTA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12c020dc-5e85-4593-a8c9-937060a44ea9', 'b7a8ec43-ed25-4728-911b-0626592c1149', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d01b9f4a-26b0-4a5d-a4d1-88c071f35337', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1790', NULL, 1666, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9ae5c867-04db-4378-bbe4-d7791ef7bd62', 'd01b9f4a-26b0-4a5d-a4d1-88c071f35337', 1, 'Por el contrato de compraventa el vendedor transfiere la propiedad de una cosa y se compromete a entregarla, y el comprador se obliga a pagar el precio en dinero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7e3b5758-87bd-40a2-85f5-52acb1586883', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1791', NULL, 1667, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f60681a0-fc76-4dec-85fa-13d108f13140', '7e3b5758-87bd-40a2-85f5-52acb1586883', 1, 'El contrato de compraventa queda perfecto entre las partes desde el momento en que convienen en la cosa y en el precio, aunque ni la una ni el otro se hayan entregado. Queda prohibido el pacto de retroventa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e3c55a11-cccc-45dd-9d18-21a203e5726a', '7e3b5758-87bd-40a2-85f5-52acb1586883', 2, 'ARTICULO1792. El marido no puede comprar de su mujer ni ésta de aquél, aunque haya separación de bienes. No quedan incluidas en la prohibición las adjudicaciones en pago entre cónyuges por razón de liquidación de la sociedad conyugal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e335c023-941e-44d5-b407-df8b30d78520', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1793', NULL, 1668, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1a2fd594-ce7b-4d65-95ae-50a7963ca4a2', 'e335c023-941e-44d5-b407-df8b30d78520', 1, 'No pueden comprar por sí ni por interpósita persona: 1. Los administradores de bienes, los que tengan bajo su administración o cuidado;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('191cc01c-9480-4b55-9889-8f2299bf57be', 'e335c023-941e-44d5-b407-df8b30d78520', 2, '2. Los depositarios judiciales, interventores, síndicos y liquidadores, los bienes del depósito, intervención, quiebra o liquidación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37cd9f30-ad62-4d62-a5c6-47bb1cd5250f', 'e335c023-941e-44d5-b407-df8b30d78520', 3, '3. Los jueces y demás funcionarios o empleados, los abogados, expertos, procuradores y mandatarios judiciales, los bienes que son objeto de los expedientes o diligencias en que intervienen;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef182d71-b5ed-4f5e-a5c4-4c8ab556bf91', 'e335c023-941e-44d5-b407-df8b30d78520', 4, '4. Los corredores y martilleros jurados, los bienes cuya venta se hace con su intervención; y los notarios, los bienes cuyas actas de remate autoricen;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4483aba9-0a98-4ada-94ec-ba94b4f0656a', 'e335c023-941e-44d5-b407-df8b30d78520', 5, '5. El mandatario, los del mandante sin el consentimiento expreso de éste; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3b5dd4b-1f6c-49dc-9e2e-d10af6208595', 'e335c023-941e-44d5-b407-df8b30d78520', 6, '6. El albacea, los de la testamentaría mientras no estén aprobadas las cuentas de su administración.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2107dbc7-ff34-49f4-84e0-ea77826a1be9', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1794', 'Ninguno puede vender sino lo que es de su propiedad', 1669, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0ff7ffa3-d579-4a4c-bed6-845768f5e613', '2107dbc7-ff34-49f4-84e0-ea77826a1be9', 1, 'La venta de cosa ajena es nula, y el vendedor debe restituir el precio si lo hubiere recibido y responder de daños y perjuicios si hubiere procedido de mala fe. El que comprare lo suyo por haberlo creído de otro, tiene derecho a conservar la cosa y a que se le restituya el precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e0270bdf-1226-4829-9323-6169b80e6304', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1795', NULL, 1670, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9365f000-95cb-4dfd-a4f7-07bbd6c6f668', 'e0270bdf-1226-4829-9323-6169b80e6304', 1, 'Los representantes de menores, incapaces o ausentes y los depositarios, administradores, interventores o liquidadores, no pueden vender los bienes que tengan a su cargo sin llenar previamente las formalidades que para cada caso señala la ley.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('207927e6-eab0-4d39-b87c-48a91f3219ff', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1796', NULL, 1671, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7025f0a7-f0cf-4cf1-b7e2-9397a7466ed0', '207927e6-eab0-4d39-b87c-48a91f3219ff', 1, 'No hay compraventa si los contratantes no convienen en el precio o en la manera de determinarlo; pueden convenir en que el precio lo fije un tercero, y si');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('666e0a79-24c5-4538-8497-af86ca5c7989', '207927e6-eab0-4d39-b87c-48a91f3219ff', 2, 'éste no quiere o no puede hacerlo, el contrato quedará sin efecto; pero si la cosa fuere entregada, se presumirá que las partes han aceptado el precio corriente que tenga en el día y lugar en que se hubiere celebrado el contrato, o el precio medio en caso de diversidad de precios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ad3f6581-c9ce-4430-9318-3eea00d86b7f', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1797', NULL, 1672, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fb5c0a46-d451-44c5-95c5-d927de78693b', 'ad3f6581-c9ce-4430-9318-3eea00d86b7f', 1, 'Se considerará fijado el precio cuando los contratantes aceptan el que la cosa tuviere en lugar y tiempo determinados. Si fueren varios los precios, se entenderá que convinieron en el precio medio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5dd03628-7920-4c89-a0a6-a32d02825da8', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1798', NULL, 1673, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee588c6e-01ac-428d-a706-df693045bd22', '5dd03628-7920-4c89-a0a6-a32d02825da8', 1, 'Se entiende fijado el precio en el contrato si las partes se refieren al que resulte de una tasación íntegra o con cierta rebaja convenida, siempre que además se sometan a decisión judicial en el caso de que alguna de ellas no se conforme con la tasación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c60b0246-765f-45ce-b975-19f4f054d74d', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1799', NULL, 1674, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e38105f5-3ea5-4585-a396-4a0c1b5dd272', 'c60b0246-765f-45ce-b975-19f4f054d74d', 1, 'Las cosas que se acostumbra comprar al gusto, o que las partes convienen en sujetar a prueba antes de comprarlas, no se consideran vendidas hasta que el comprador quede satisfecho. El plazo para la prueba, salvo estipulación, es de tres días, contados desde que el vendedor las ponga a disposición del comprador; y si éste no aceptare dentro de dicho término, se le tendrá por desistido del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5af5e713-0a58-4750-b324-a39e814ee164', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1800', NULL, 1675, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c310fd39-a122-475f-9e96-3b386e67a24b', '5af5e713-0a58-4750-b324-a39e814ee164', 1, 'La compra sobre muestras, lleva implícita la condición de resolver el contrato si las cosas no resultaren conformes con las muestras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e8e1eba-4bd8-481f-81aa-87cfdcdc2b08', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1801', NULL, 1676, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7c75e4c-cfc1-4e62-b299-5ca05533ec78', '9e8e1eba-4bd8-481f-81aa-87cfdcdc2b08', 1, 'Vendida una cosa expresando su especie y calidad, el comprador tiene derecho de que se resuelva el contrato si la cosa no resulta de la especie y calidad convenidas. Cuando se hubiere expresado el uso que se va a dar a la cosa, la calidad debe corresponder a ese uso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3a3543ac-14b7-480b-a7f8-79efb29b0206', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1802', NULL, 1677, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('51da6fc4-b7e9-42cc-926c-b283c8a2708c', '3a3543ac-14b7-480b-a7f8-79efb29b0206', 1, 'En la venta de cosas que están en tránsito, el comprador podrá resolver el contrato si no llegaren en buen estado y en el tiempo convenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c71197fd-4749-4955-adf4-87959117f11b', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1803', NULL, 1678, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('520ec647-c88b-47c3-ad95-31f9ca1beb91', 'c71197fd-4749-4955-adf4-87959117f11b', 1, 'Cuando se estipula que la cosa debe ser entregada en lugar determinado, la compra se entiende celebrada bajo condición de que la cosa llegue a su destino.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c8d9bfbf-79bf-43a7-b1fa-034d143d2be8', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1804', NULL, 1679, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed841738-8d7a-44cb-b4d9-df1a6cb82acc', 'c8d9bfbf-79bf-43a7-b1fa-034d143d2be8', 1, 'Si al tiempo de celebrarse el contrato se hubiere perdido en su totalidad la cosa objeto del mismo, el convenio quedará sin efecto. Si se hubiese perdido sólo en parte, el comprador podrá optar entre desistir del contrato, o reclamar la parte existente abonando su precio en proporción al total convenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('308d52e8-fdbd-4e86-897c-7e5ca57a6dd9', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1805', NULL, 1680, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ee5c09d-6328-480a-ad1c-d90c1463bd2d', '308d52e8-fdbd-4e86-897c-7e5ca57a6dd9', 1, 'Pueden venderse las cosas futuras, antes de que existan en especie, y también una esperanza incierta. Igualmente pueden venderse las cosas o derechos litigiosos, o con limitaciones, gravámenes o cargas, siempre que el vendedor instruya previamente al comprador, de dichas circunstancias y así se haga constar en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('255d1223-c95b-4061-98f2-098aaa5884d1', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1806', NULL, 1681, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87839c0e-e4db-4978-86dc-3e57370dea7a', '255d1223-c95b-4061-98f2-098aaa5884d1', 1, 'Se puede vender un derecho hereditario, sin especificar los bienes de que se compone; y en tal caso, el vendedor sólo responderá de su calidad de heredero. El vendedor deberá pagar al comprador las cosas de la herencia, de las que se hubiere aprovechado; y a su vez, el comprador, satisfacer al vendedor las deudas y cargas que en razón de la herencia hubiere pagado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90a1de4d-71f1-45c4-bd01-ac0a915e50e9', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1807', NULL, 1682, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6edf5292-095e-4e71-be76-9ecda23c1979', '90a1de4d-71f1-45c4-bd01-ac0a915e50e9', 1, 'Si una misma cosa mueble se hubiere vendido a diferentes personas, prevalecerá la venta hecha al que de buena fe se halle en posesión de la cosa; y si ninguno tuviere la posesión, prevalecerá la venta primera en fecha.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8010b492-299d-4aae-9c73-1658611028d3', 'a0000000-0000-0000-0000-000000000001', 'c2177918-513b-441b-b652-fcc0ea486966', '1808', NULL, 1683, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18fedf34-af3d-4977-8bb8-9dce37798af2', '8010b492-299d-4aae-9c73-1658611028d3', 1, 'Si la cosa vendida fuere inmueble o derecho real sobre inmuebles, prevalecerá la venta que primero se haya inscrito en el Registro, y si ninguna lo ha sido, será válida la venta anterior en fecha.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('26243805-ff5d-4ede-a6f3-a5aaa66146ba', '8010b492-299d-4aae-9c73-1658611028d3', 2, 'OBLIGACIONES DEL VENDEDOR');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78e0c300-0668-4152-92aa-49a13a62fdb4', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1809', NULL, 1684, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0a266f05-8b67-4737-bc74-3be764fb9c33', '78e0c300-0668-4152-92aa-49a13a62fdb4', 1, 'El vendedor está obligado a entregar la cosa vendida y a garantizar al comprador la pacífica y útil posesión de la misma. La entrega se hará en el lugar señalado en el contrato, y a falta de convenio, en el lugar en que la cosa se encuentre al tiempo de la venta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('77d7edaf-34f1-4415-8714-64b83ad74409', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1810', NULL, 1685, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f90d9f75-2e35-4149-bed8-1d4a8e569b22', '77d7edaf-34f1-4415-8714-64b83ad74409', 1, 'La entrega de la cosa vendida puede ser real, simbólica o legal. La primera consiste en la entrega material de la cosa vendida o del título si se trata de un derecho.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2b570cd5-1907-4a35-95ce-643dc740c7dc', '77d7edaf-34f1-4415-8714-64b83ad74409', 2, 'La entrega simbólica se realiza empleando alguna forma o figura con la cual el comprador se da por recibido de la cosa vendida.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e8b46be9-9d71-4015-a0c8-f3344e8899a6', '77d7edaf-34f1-4415-8714-64b83ad74409', 3, 'La entrega legal tiene lugar cuando la ley considera recibida la cosa por el comprador aun sin estar materialmente entregada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e4d357e1-eb24-49d9-b23d-d7caefaf5859', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1811', NULL, 1686, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('409f4876-cfc3-43f9-a427-63fbb4d17919', 'e4d357e1-eb24-49d9-b23d-d7caefaf5859', 1, 'Si los contratantes no fijaren plazo, la entrega de la cosa vendida se hará inmediatamente, a no ser que se tratare de cosas cuya entrega debe prepararse, en cuyo caso el vendedor deberá tenerlas a disposición del comprador dentro de las veinticuatro horas siguientes a la celebración del contrato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('299d9b93-268f-4302-8dbe-cbe04ae6d2a4', 'e4d357e1-eb24-49d9-b23d-d7caefaf5859', 2, 'Si el vendedor no entrega la cosa, el comprador puede pedir que se le ponga en posesión de ella, o la resolución del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5637117c-bcb3-460e-b1e0-ff0c0919b0d0', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1812', NULL, 1687, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('25d865b2-5066-4a37-86d0-0ba94e66229a', '5637117c-bcb3-460e-b1e0-ff0c0919b0d0', 1, 'La entrega de la cosa vendida se entiende verificada: 1. Por la transmisión del conocimiento, certificado de depósito o carta de porte;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c8bdabc-d155-46c9-8122-b41b41cef9af', '5637117c-bcb3-460e-b1e0-ff0c0919b0d0', 2, '2. Por el hecho de fijar su marca el comprador con consentimiento del vendedor en las cosas compradas; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d70fc0da-f1af-4fe9-8407-ac42d44c1b21', '5637117c-bcb3-460e-b1e0-ff0c0919b0d0', 3, '3. Por cualquier otro medio autorizado por el uso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38c320f9-316f-45a7-a855-24975533a1bf', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1813', NULL, 1688, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f5295bbb-2482-471e-ac73-d457eeff8a8c', '38c320f9-316f-45a7-a855-24975533a1bf', 1, 'El riesgo de la cosa recae sobre el contratante que tenga la posesión material y el uso de la misma, salvo convenio en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7d7c034a-179a-47cf-a3d5-2c7defdcd526', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1814', NULL, 1689, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c9612a76-d200-4730-8a5b-85aec045bb4e', '7d7c034a-179a-47cf-a3d5-2c7defdcd526', 1, 'En caso de resolución del contrato por falta de entrega de la cosa, el vendedor deberá devolver el precio pagado y los intereses corridos hasta la devolución, más los daños y perjuicios; pero sólo devolverá el precio si el comprador, al tiempo de celebrar el contrato, hubiere conocido el obstáculo del que ha provenido la falta de entrega de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4d48f855-e651-4d4e-936b-95346e3bdb58', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1815', NULL, 1690, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a10f287f-d8ef-4cec-8339-73b86d3a1492', '4d48f855-e651-4d4e-936b-95346e3bdb58', 1, 'La cosa vendida debe entregarse en el estado en que se hallaba en el momento del contrato; y desde ese día los frutos pertenecen al comprador, salvo lo que estipulen las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('519a9145-f71e-45e2-9176-968e73b27159', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1816', NULL, 1691, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee9012f4-73c5-49f5-b4a8-f7ff5b1c542a', '519a9145-f71e-45e2-9176-968e73b27159', 1, 'Si después de perfeccionada la venta, el vendedor consume, altera o enajena y entrega a otro las cosas vendidas, el comprador podrá exigir otras equivalentes en especie, calidad y cantidad o, en su defecto, su valor a juicio de peritos, con indemnización de daños y perjuicios en ambos casos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('61e4b4a2-f216-40d1-a324-2fd25770b294', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1817', NULL, 1692, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1368d8c5-5403-4178-bcf5-fc8d896d6818', '61e4b4a2-f216-40d1-a324-2fd25770b294', 1, 'El comprador que contratare en conjunto una determinada cantidad de cosas o efectos, no está obligado a recibir una parte bajo promesa de que se le entregará posteriormente lo restante. Pero si el comprador aceptare las entregas parciales, la venta se tendrá por consumada en cuanto a las porciones recibidas, aun cuando el vendedor no le entregue las restantes. En este caso el comprador podrá compeler al vendedor a que cumpla íntegramente el contrato o a que indemnice los daños o perjuicios que le cause el cumplimiento imperfecto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2a5c4973-d6cb-4758-b083-1c4653cbcbd2', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1818', NULL, 1693, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dd0505d7-23d0-4ef4-80d8-d16d5d9967a7', '2a5c4973-d6cb-4758-b083-1c4653cbcbd2', 1, 'Entregadas las cosas vendidas, el comprador no será oído sobre defecto de calidad o falta de cantidad siempre que al tiempo de la entrega las hubiere examinado y recibido sin previa protesta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1c3564ec-02c9-4a63-a1a7-f96df55684c1', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1819', NULL, 1694, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('775a3570-728c-4f0c-91b5-9bed5b0881d5', '1c3564ec-02c9-4a63-a1a7-f96df55684c1', 1, 'Cuando las cosas fueren entregadas en fardos o bajo cubierta que impida su reconocimiento y el comprador hiciere una formal y expresa reserva del derecho de examinarla, podrá reclamar dentro de tres días inmediatos al de la entrega, comprobando las faltas de cantidad o defecto de calidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03bddac6-127d-45fe-9319-131f18a51ef2', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1820', NULL, 1695, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f85664bf-8450-4e83-9455-8f2a879f4c85', '03bddac6-127d-45fe-9319-131f18a51ef2', 1, 'Si la venta fuere de bienes inmuebles y se hubiese hecho fijando su área, o a razón de un precio por unidad de medida, el comprador está obligado a pagar lo que se halle de más y el vendedor a devolver el precio correspondiente a lo que se encuentre de menos, siempre que el exceso o falta no pase de la décima parte del todo vendido. La acción para ejercitar este derecho prescribe en un año contado desde la fecha del contrato o del día fijado por las partes para verificar la medida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1d9792f3-f6e3-4f87-8899-fc3c44f00f43', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1821', NULL, 1696, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5a57589-df2e-4efc-97ae-00a03410fcb7', '1d9792f3-f6e3-4f87-8899-fc3c44f00f43', 1, 'Cuando el comprador no puede pagar inmediatamente la diferencia del precio que resulte a su cargo, estará obligado el vendedor a concederle un término para el pago. Si lo negare, el juez, con arreglo a las circunstancias del caso, acordará un término que no exceda de tres meses contados desde la aprobación de la medida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('357a454b-e611-4fe7-966e-744563726fc5', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1822', NULL, 1697, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c31d2f2b-4c71-4d34-a263-870db579b1e0', '357a454b-e611-4fe7-966e-744563726fc5', 1, 'Si el exceso o falta en la extensión de la cosa vendida es mayor que un décimo, queda a elección del comprador, o pagar lo que hubiese de más y cobrar en su caso lo que resulte de menos, o rescindir el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('738444a8-e320-4519-a23e-1419a0b4e8cc', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1823', NULL, 1698, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b85c374f-16bf-45bf-9fc6-18c12181d14b', '738444a8-e320-4519-a23e-1419a0b4e8cc', 1, 'Si un inmueble se ha vendido determinando expresamente sus linderos, el vendedor estará obligado a entregar todo lo que esté comprendido dentro de dichos linderos, aunque haya exceso o disminución en las medidas indicadas en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c90724d4-859a-4b2f-85fc-aed98863c058', 'a0000000-0000-0000-0000-000000000001', '066a55c9-71b1-42c8-8698-83878de02fb4', '1824', NULL, 1699, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea2bbd84-c63c-4f76-9f20-576fba42e478', 'c90724d4-859a-4b2f-85fc-aed98863c058', 1, 'Salvo uso o pacto en contrario, el vendedor debe satisfacer los gastos de la entrega de la cosa vendida; y el comprador los de escritura.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('91023843-9f42-4305-9ed6-4410a7db7ca1', 'c90724d4-859a-4b2f-85fc-aed98863c058', 2, 'DE LAS OBLIGACIONES DEL COMPRADOR');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ca00de5-421a-47e1-b2bd-36d98fba5dff', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1825', NULL, 1700, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c824e75d-8985-48de-b639-80ca739fc2b1', '0ca00de5-421a-47e1-b2bd-36d98fba5dff', 1, 'La obligación principal del comprador es pagar el precio en el día, lugar y forma estipulados en el contrato. A falta de convenio, el precio debe ser pagado en el lugar y momento en que se hace la entrega de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('43ce4693-b054-42a3-9061-1a0a74dde1f7', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1826', NULL, 1701, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c867ebeb-f48d-4fb1-a7df-4dac471e79f6', '43ce4693-b054-42a3-9061-1a0a74dde1f7', 1, 'El comprador que no ha pagado el precio y ha recibido la cosa, está obligado al pago de intereses en los casos siguientes: 1. Si así se estipuló en el contrato;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('178d2055-6aa5-40f8-a82b-616fab0cd91a', '43ce4693-b054-42a3-9061-1a0a74dde1f7', 2, '2. Si la cosa produce frutos o rentas; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99f1dc5d-9f19-4ab2-a4c1-6e7be8501645', '43ce4693-b054-42a3-9061-1a0a74dde1f7', 3, '3. Si fuere requerido judicial o notarialmente para el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e6954e88-2c5f-4e78-8efa-7efd666330c8', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1827', NULL, 1702, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8cd6f19a-a3b2-42a9-8cc3-d5b81966b3f5', 'e6954e88-2c5f-4e78-8efa-7efd666330c8', 1, 'Cuando se ha pagado parte del precio, y en el contrato no se estipuló plazo para el pago de la otra parte, si el comprador no paga el resto dentro del plazo que el juez señale prudencialmente, o no otorga la garantía convenida, puede el vendedor pedir la rescisión, devolviendo la parte de precio pagado, deducidos los impuestos y gastos del contrato que hubiere hecho efectivos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e819a63f-f48b-4d26-a6b9-dd025fa37aca', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1828', NULL, 1703, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5707e1a4-b670-4c2d-8ad2-ef7ec99b2440', 'e819a63f-f48b-4d26-a6b9-dd025fa37aca', 1, 'Si el comprador fuere perturbado en la posesión o hubiere motivo justificado para temer que lo será, podrá el juez autorizarlo para retener la parte del precio que baste a cubrir la responsabilidad del vendedor, salvo que éste haga cesar la perturbación o garantice el saneamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3ebedcce-c3da-4f51-ba19-db13d796b6ab', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1829', NULL, 1704, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a16f330-9ddd-4a8c-87a6-6298e2640eb2', '3ebedcce-c3da-4f51-ba19-db13d796b6ab', 1, 'En las ventas a plazos la retención a que se refiere el artículo anterior, comenzará por el último vencimiento estipulado en el contrato y los que le precedan, hasta completar la cantidad cuya retención haya sido autorizada judicialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2987bb71-cf28-4652-8094-a1d36cd83eba', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1830', NULL, 1705, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e79399e0-ff34-4b4f-a4e6-4001039db32f', '2987bb71-cf28-4652-8094-a1d36cd83eba', 1, 'El comprador está obligado a recibir la cosa en el lugar y tiempo convenidos, o en su defecto, en los legales, y si rehusare sin justa causa recibirla o si por su culpa se demorare la entrega, correrán a su cargo los riesgos de la cosa y los gastos de su conservación y el vendedor tendrá además el derecho de cobrarle los daños y perjuicios que le causare. Si la cosa fuere mueble, el vendedor puede pedir su depósito a costa del comprador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e10cc169-e399-4277-ad8d-3613b5a7374c', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1831', NULL, 1706, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ab098a24-2c21-44b1-abf6-faade6f9e5ea', 'e10cc169-e399-4277-ad8d-3613b5a7374c', 1, 'El comprador es responsable de la baja del precio y de las costas, en la resolución de la venta por falta de pago del precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('60fd5e6e-3448-4c0d-b253-a2542d5400bb', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1832', NULL, 1707, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5689e1d-a0df-4d49-ac95-0e499001cdf3', '60fd5e6e-3448-4c0d-b253-a2542d5400bb', 1, 'El comprador tiene derecho de retener el precio mientras se le demora la entrega de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bbf49dc9-43d0-4a86-9961-396b843155b8', 'a0000000-0000-0000-0000-000000000001', 'c3472aa4-53c3-4945-93ee-6e9c33bc2ca2', '1833', NULL, 1708, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5c8771a9-39ed-4065-90c0-ea4a7e8441f4', 'bbf49dc9-43d0-4a86-9961-396b843155b8', 1, 'Si se ha fijado plazo para el pago del precio y el vendedor demora la entrega de la cosa, el plazo se contará de la fecha de la entrega y no de la estipulada en el contrato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d3f3e20e-84bd-4a8c-947a-ced691896285', 'bbf49dc9-43d0-4a86-9961-396b843155b8', 2, 'COMPRAVENTA POR ABONOS CON O SIN RESERVA DE DOMINIO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fac8997b-dc45-45b9-9715-da57993a88a3', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1834', NULL, 1709, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0378671-f47b-4685-b57a-8c2aa008f535', 'fac8997b-dc45-45b9-9715-da57993a88a3', 1, 'Es válida la venta en pacto de reserva del dominio, mientras el comprador no pague totalmente el precio o no se realice la condición a que las partes sujetan la consumación del contrato. El comprador obtiene por esta modalidad de venta la posesión y uso de la cosa, salvo convenio en contrario; pero mientras no haya adquirido la plena propiedad, le queda prohibido cualquier enajenación o gravamen de su derecho sin previa autorización escrita del vendedor.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e1c1e1d-0ac8-4799-90f3-26b000802cf8', 'fac8997b-dc45-45b9-9715-da57993a88a3', 2, 'Cuando el precio se paga totalmente o se cumple la condición, la propiedad plena se transfiere al comprador sin necesidad de ulterior declaración. En este caso, el vendedor deberá dar aviso por escrito al Registro de la Propiedad, dentro de los ocho días de haberse cancelado totalmente el precio, para que se haga la anotación respectiva. La falta de cumplimiento de esta disposición será sancionada por el juez con multa de diez quetzales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3b8cfc44-870e-4d9b-98b1-1545c17f195f', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1835', NULL, 1710, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7e0be82c-76ce-41b8-b279-6ca46983e059', '3b8cfc44-870e-4d9b-98b1-1545c17f195f', 1, 'La venta con pago del precio en abonos, con o sin reserva de dominio de bienes inmuebles, o de muebles susceptibles de identificarse de manera indubitable, debe inscribirse en el Registro de la Propiedad; su rescisión o resolución producirá efectos contra tercero que hubiere adquirido los bienes de que se trata. Si el contrato se refiere a bienes muebles que no pueden identificarse y por lo mismo su venta no pueda registrarse, no serán perjudicados los terceros adquirentes de buena fe.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2cd89cd4-dbc1-4087-9ccc-aaa7f08716a1', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1836', NULL, 1711, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('63c19fc4-8b5e-46b8-b82f-959a21d1a3f4', '2cd89cd4-dbc1-4087-9ccc-aaa7f08716a1', 1, 'El contrato de compraventa en abonos con reserva o no de dominio, puede resolverse por falta de pago de cuatro o más mensualidades consecutivas si el contrato fuere de bienes inmuebles. En este caso, el vendedor devolverá al comprador el precio recibido descontándose una equitativa compensación por el uso de la cosa, que fijará el juez oyendo el dictamen de peritos, si las partes no se ponen de acuerdo');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('79a5fd1a-d3d9-451a-adca-2af6c562431f', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1837', NULL, 1712, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('699ad26a-0800-4121-b942-4a57dbcab1fa', '79a5fd1a-d3d9-451a-adca-2af6c562431f', 1, 'Si la venta fuere de bienes muebles, el vendedor tiene derecho en caso de resolución del contrato, de hacer suyos los abonos pagados, como indemnización por el uso y depreciación de la cosa. Sin embargo, el vendedor queda obligado a reintegrar al comprador cualquier excedente que obtuviere en la reventa, después de hacerse pago del saldo del precio que motivó la resolución del contrato más los gastos realizados y comprobados para lograr la reventa. Si el precio de la reventa se paga al contado, el pago se hará inmediatamente al acreedor, y si se pacta en amortizaciones, en la misma forma se hará el pago');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4047d443-ca84-4bc2-b692-4813ed095ded', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1838', NULL, 1713, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6f65ce70-8945-4478-9f0a-7a3a53f670c7', '4047d443-ca84-4bc2-b692-4813ed095ded', 1, 'Serán por cuenta del comprador todos los gastos de uso, conservación y reparaciones de la cosa mueble así como el pago de impuestos y licencias. Tratándose de bienes inmuebles, las mejoras se regularán en caso de rescisión, por las disposiciones del capítulo IV, título VII de la 2ª parte del libro 5º en lo que fueren aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fcb9f0d3-f13c-4948-8fda-0198e1d0854b', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1839', NULL, 1714, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c18103a2-034e-4703-8157-764cddf01a58', 'fcb9f0d3-f13c-4948-8fda-0198e1d0854b', 1, 'La cosa será recuperada por el vendedor abonando el valor de las mejoras que no sean separables, pero tendrá derecho a ser indemnizado por los daños que el comprador hubiere causado a la propiedad.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('03107330-77fe-4e25-b29f-68d4a2545a15', 'fcb9f0d3-f13c-4948-8fda-0198e1d0854b', 2, 'Si la cosa produjo frutos o rentas, el comprador los devolverá al vendedor; pero si en los abonos se hubieren Incluido intereses, se hará compensación entre aquéllos y éstos, devolviéndose solamente la diferencia si la hubiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8912d2a9-b544-41ec-acf2-ba969ecd5571', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1840', NULL, 1715, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('807eed8e-daef-42be-afc9-369b5923eb96', '8912d2a9-b544-41ec-acf2-ba969ecd5571', 1, 'El vendedor puede reservarse la entrega material de la cosa para cuando el precio se haya acabado de pagar, o cuando hubiere entregado un número determinado de abonos. En estos casos, si el contrato se resuelve, el vendedor devolverá las sumas que haya recibido y los intereses legales si no estuvieren estipulados. El comprador que hubiere pagado la mitad del precio o más, puede exigir que el vendedor le garantice la entrega de la cosa o la devolución de los abonos si el vendedor se negare.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c8c33056-299d-4c2d-a8b4-3b752b0d805d', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1841', NULL, 1716, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('361cbee0-cab5-4526-a371-7c07e685018d', 'c8c33056-299d-4c2d-a8b4-3b752b0d805d', 1, 'Es nula la estipulación de que el comprador perderá a favor del vendedor los abonos que hubiere efectuado, aunque sea título de multa o de retribución por el uso de la cosa, salvo lo dispuesto en el artículo 1837.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3b82e156-2660-4c99-881e-9149955ae73b', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1842', NULL, 1717, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d85c38f9-fede-483c-ab32-f26dc7b304e3', '3b82e156-2660-4c99-881e-9149955ae73b', 1, 'La calificación de arrendamiento, depósito o cualquiera otra denominación que se dé a la venta no surtirá otros efectos que los que se expresan en este capítulo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('913e72bd-c54d-4433-bda2-63a81e8ef522', 'a0000000-0000-0000-0000-000000000001', 'e204a58e-3e11-4abe-ad05-aa3e73145e7a', '1843', NULL, 1718, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('531bf129-56d8-4add-a289-4c5aa0b00523', '913e72bd-c54d-4433-bda2-63a81e8ef522', 1, 'Las condiciones impuestas por las compañías o empresas lotificadoras o constructoras, deberán ser aprobadas por la autoridad gubernativa para que se reconozca su validez.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('21191e44-f288-4cad-af8a-b753ceb4ad14', '913e72bd-c54d-4433-bda2-63a81e8ef522', 2, 'PACTOS DE RESCISION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b2969b06-7917-4500-ac16-e76d784df90b', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1844', NULL, 1719, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3c129aab-fb15-42e2-bb92-b78f67dc0cea', 'b2969b06-7917-4500-ac16-e76d784df90b', 1, 'Pueden las partes estipular en el contrato que la venta se rescindirá si no se paga el precio en cierto día determinado. Sin embargo, el comprador de bienes inmuebles podrá pagar el precio después del día señalado mientras no hubiere incurrido en mora en virtud de requerimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('369a555c-25fb-4613-a574-7a5890ee297e', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1845', NULL, 1720, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb1b19ca-b816-40d7-aa12-0ef87c103a6c', '369a555c-25fb-4613-a574-7a5890ee297e', 1, 'La venta de cosas que no sean inmuebles se entenderá rescindida sin necesidad de requerimiento, si a la expiración del término convenido no se presentó el comprador a pagar el precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6b0904fc-f0f6-4533-a7db-b88605256909', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1846', NULL, 1721, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28d98210-92e8-446d-b0de-24d21d287f80', '6b0904fc-f0f6-4533-a7db-b88605256909', 1, 'Si estipulado el pacto de rescisión, el comprador paga más de la mitad del precio total, no procederá la rescisión y el vendedor solamente tendrá derecho a exigir el pago del resto, costas y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b3c33e16-098a-4905-a9c2-ce96f23d764d', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1847', NULL, 1722, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c39f35b8-89c9-4d8e-89b9-a5b6486e328a', 'b3c33e16-098a-4905-a9c2-ce96f23d764d', 1, 'Puede también estipularse en el contrato que la venta se rescindirá a solicitud del vendedor si dentro de un término fijado hubiere quién dé más por la cosa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee0bc486-8d11-4137-95c9-938675b74df8', 'b3c33e16-098a-4905-a9c2-ce96f23d764d', 2, 'Este término no podrá exceder en ningún caso de seis meses si se tratare de inmuebles o de tres si se tratare de otros bienes, y se contará de la fecha de la celebración del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d7ce8eb8-384f-4995-976b-78c175e07a33', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1848', NULL, 1723, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3377471-695a-4c97-a1c5-8f98ecd28a0d', 'd7ce8eb8-384f-4995-976b-78c175e07a33', 1, 'Estipulado el pacto a que se refiere el artículo anterior, el comprador goza de preferencia para quedarse con la cosa pagando la diferencia de precio. Para el ejercicio de este derecho deberá notificársele al comprador el ofrecimiento del precio mayor. Pagada la diferencia por el comprador el pacto se tendrá por concluido aunque el término por el cual se estipuló no lo estuviere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d9d78f7c-84ca-4440-a34e-9cb23ede646e', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1849', NULL, 1724, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7eae7539-94ff-4718-95d7-63a35f48b48d', 'd9d78f7c-84ca-4440-a34e-9cb23ede646e', 1, 'No procede la rescisión si se prueba colusión entre el vendedor y el que ofrece mayor precio. Se entenderá que hubo colusión si el comprador exige que el precio mayor se deposite en efectivo y no se deposita dentro de los tres días siguientes al requerimiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('16271745-3ca7-495c-b014-5fffbc513d2f', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1850', NULL, 1725, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7c336aae-fc38-426f-815c-f4b8516e68eb', '16271745-3ca7-495c-b014-5fffbc513d2f', 1, 'Las mejoras que hubiere hecho el comprador en la cosa y el aumento del valor que ésta tenga por el transcurso del tiempo, deben serle pagados si por el ofrecimiento de precio mayor se rescinde la venta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9402200e-2948-4f9b-9aca-a42f6cc31e34', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1851', NULL, 1726, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3db9d794-bc95-4ffc-ba20-42c1a7b98d58', '9402200e-2948-4f9b-9aca-a42f6cc31e34', 1, 'La rescisión voluntaria de la venta sin pacto especial previo, solamente puede hacerse dentro del año de la celebración del contrato, si se tratare de bienes inmuebles o derechos reales sobre los mismos y dentro de los seis meses, si se tratare de otros bienes.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1d88a19b-6258-4f03-a5cf-bbec035ae0cd', '9402200e-2948-4f9b-9aca-a42f6cc31e34', 2, 'DE LA PERMUTA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4671a8ed-647a-4904-9ba3-90172fedf337', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1852', NULL, 1727, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a144906-2fb2-42bf-9187-e394c7a5deb0', '4671a8ed-647a-4904-9ba3-90172fedf337', 1, 'La permuta es un contrato por el cual cada uno de los contratantes transmite la propiedad de una cosa a cambio de la propiedad de otra. Cada permutante es vendedor de la cosa que da y comprador de la que recibe en cambio; y cada una de las cosas es precio de la otra. Este contrato se rige por los mismos principios del contrato de compraventa, en lo que fueren aplicables.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('374f8c41-0800-4034-9aed-c769f526b4db', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1853', NULL, 1728, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41b115c2-5c8b-4c34-a409-44e45f71acfa', '374f8c41-0800-4034-9aed-c769f526b4db', 1, 'Si la cosa que se entrega se ha de pagar parte en dinero y parte en otros bienes, el contrato será de permuta siempre que la porción estipulada en dinero no llegue a la mitad del precio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f54fcac3-6d77-43a6-8750-8e9cb4d1c738', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1854', NULL, 1729, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8a5a0dd8-62d5-4616-9a70-3b2106564b92', 'f54fcac3-6d77-43a6-8750-8e9cb4d1c738', 1, 'El permutante que sufra evicción de la cosa que recibió, o que la devuelva en razón de sus vicios, puede reclamar a su elección, la restitución de la cosa que dio, si se halla aún en poder del otro permutante, o el valor de la cosa que se le hubiese dado en cambio, con el pago de daños y perjuicios.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('99f55049-50ee-43fd-814a-55b2c269ce58', 'f54fcac3-6d77-43a6-8750-8e9cb4d1c738', 2, 'DONACION ENTRE VIVOS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c0c7361f-283f-4bb1-aadc-d438a9ff96be', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1855', NULL, 1730, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5830802b-0f98-4155-8986-44d17e752291', 'c0c7361f-283f-4bb1-aadc-d438a9ff96be', 1, 'La donación entre vivos es un contrato por el cual una persona transfiere a otra la propiedad de una cosa, a título gratuito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('98f84bed-dd34-4b67-ad8a-6c3621f64ed5', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1856', NULL, 1731, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eed2ff83-d97c-44f5-9cd1-fce9feb08429', '98f84bed-dd34-4b67-ad8a-6c3621f64ed5', 1, 'La donación entre vivos también puede ser remuneratoria y onerosa, pero en este último caso, sólo constituye donación el exceso que hubiere en el precio de la cosa, deducidos los gravámenes o cargas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('70c46607-059b-415e-832c-ca62dfc0dd25', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1857', NULL, 1732, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be97d699-592b-4468-939c-052e4d3d7e7c', '70c46607-059b-415e-832c-ca62dfc0dd25', 1, 'El donatario puede aceptar en el momento de la donación o en acto separado. Si aceptare con posterioridad, para que el contrato quede perfecto debe notificarse la aceptación al donante en forma auténtica.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('67d335bf-f8cb-4178-9b2e-099af7023477', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1858', NULL, 1733, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4fa8aa5f-c35f-46e7-8fd6-3c93c379c733', '67d335bf-f8cb-4178-9b2e-099af7023477', 1, 'Si el donante muere antes que el donatario haya aceptado la donación, puede éste, sin embargo, aceptarla y los herederos del donante están obligados a entregar la cosa donada. Si muere el donatario antes de aceptar la donación, queda ésta sin efecto, y sus herederos nada podrán pedir al donante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('97cf341a-4542-4ca6-934f-ceb2cbd940ab', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1859', NULL, 1734, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc63677f-84bd-4404-94fa-1e6d27a3dcc0', '97cf341a-4542-4ca6-934f-ceb2cbd940ab', 1, 'El donatario se subroga en todos los derechos y acciones que en caso de evicción corresponderían al donante. Este, en cambio, no queda obligado al saneamiento de las cosas donadas, salvo si la donación fuere onerosa o remuneratoria, en cuyo caso responderá el donante de la evicción hasta la concurrencia del gravamen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9b7a1549-1c33-4928-99b0-3240e76389d5', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1860', NULL, 1735, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f938821b-4efa-4bd2-ae3c-94541c95ee12', '9b7a1549-1c33-4928-99b0-3240e76389d5', 1, 'La donación puede hacerse por medio de apoderado; pero el poder debe designar la persona del donatario y especificar los bienes objeto de la donación y condiciones a que queda sujeta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90c56ee3-600d-454d-a793-ce6610c6577a', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1861', NULL, 1736, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b43bd0b-cb54-4eba-8636-6224d7608c7f', '90c56ee3-600d-454d-a793-ce6610c6577a', 1, 'La donación que se haga a los menores, incapaces o ausentes, la aceptarán sus representantes legales; pero, cuando se trate de donaciones condicionales y onerosas, deberá preceder autorización judicial, como en el caso de utilidad y necesidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('33173297-044d-49fc-a575-a02ab9f76c40', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1862', NULL, 1737, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('39a9ce34-4b41-410a-ab40-b065d9112259', '33173297-044d-49fc-a575-a02ab9f76c40', 1, 'La donación de bienes inmuebles debe otorgarse y aceptarse por escritura pública.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('969d6b52-07c1-44f0-89d9-f8159bb2ffbf', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1863', NULL, 1738, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d798f5c3-eb06-401b-b0b7-d879798052c8', '969d6b52-07c1-44f0-89d9-f8159bb2ffbf', 1, 'Toda donación será estimada; y si comprendiere todos o la mayor parte de los bienes o los más productivos, deberán detallarse en el instrumento en que se otorgue el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f6fab87e-d25e-441c-a21c-b3d7720f1e5c', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1864', NULL, 1739, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('331f71d2-5ac5-4017-a4b8-06aa152aa0a3', 'f6fab87e-d25e-441c-a21c-b3d7720f1e5c', 1, 'El donatario quedará obligado con los acreedores y alimentistas del donante y con el hijo nacido con posterioridad, solamente hasta el valor de los bienes');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2a8a962e-5a06-4268-b593-64bb70122dc3', 'f6fab87e-d25e-441c-a21c-b3d7720f1e5c', 2, 'donados al tiempo de hacerse la donación, si el donante no tuviere medios para cumplir estas obligaciones; pero podrá eximirse de responsabilidad haciendo abandono de los bienes donados o de la parte suficiente para cubrirlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56e6dcaf-2fc3-4c81-80af-d12e14c6e11c', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1865', NULL, 1740, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ef34b8c0-8144-42d6-a55c-b63e1914ccd4', '56e6dcaf-2fc3-4c81-80af-d12e14c6e11c', 1, 'En las donaciones onerosas, el donatario quedará obligado por la parte que efectivamente constituye la donación, en los términos del artículo anterior, una vez deducido el monto de las obligaciones impuestas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bcdd99eb-5270-47f7-b244-c928c410bfe0', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1866', NULL, 1741, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea767bdd-263e-4441-b830-cd1bf7448f0f', 'bcdd99eb-5270-47f7-b244-c928c410bfe0', 1, 'La donación gratuita, y la onerosa en la parte que constituya la donación efectiva, pueden ser revocados por causa de ingratitud del donatario. Esta facultad es personal del donante e irrenunciable, y se otorga en los casos siguientes: 1. Si el donatario comete algún delito contra la persona, la honra o los bienes del donante, su cónyuge, conviviente de hecho, sus ascendientes o descendientes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b554f8f3-097b-44e7-af7d-32369e6d6eef', 'bcdd99eb-5270-47f7-b244-c928c410bfe0', 2, '2. Por acusar o denunciar de algún delito al donante, salvo que el delito se hubiere cometido contra el donatario, su cónyuge, conviviente de hecho, sus ascendientes o descendientes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f803c761-bca7-49be-9cd7-f7bc922de351', 'bcdd99eb-5270-47f7-b244-c928c410bfe0', 3, '3. Por negarse indebidamente a alimentar al donante que careciere de bienes, o si lo desamparare o abandonare cuando estuviere necesitado de asistencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d8ee9923-87c1-4ec5-8345-0cb8f7496c8a', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1867', NULL, 1742, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('42a43957-a945-4783-829d-a5d00ff5376f', 'd8ee9923-87c1-4ec5-8345-0cb8f7496c8a', 1, 'La revocación de la donación por ingratitud sólo puede hacerse contra el donatario; sin embargo, si hubiere sido iniciada en vida de éste, podrá continuarse contra los herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7afed5cc-f74c-499e-b000-7dfa841862c8', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1868', NULL, 1743, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ee3b70b-4d40-48df-b3a0-4908dc66b1c3', '7afed5cc-f74c-499e-b000-7dfa841862c8', 1, 'Cuando el donatario cause voluntariamente la muerte del donante, se invalida por el mismo hecho la donación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fd2e2eef-765d-4aed-b537-a957e6efd0b5', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1869', NULL, 1744, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('34f97650-7502-4cba-9605-556591e5c855', 'fd2e2eef-765d-4aed-b537-a957e6efd0b5', 1, 'La revocación que haga el donante por causa de ingratitud, no producirá efecto alguno si no se notifica al donatario o a sus herederos dentro de los sesenta días siguientes a la fecha en que se otorgue la escritura pública de revocación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('59524a38-c136-4b7e-b8a2-95b7bb50620c', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1870', NULL, 1745, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27754ed8-62b6-4f49-8593-62e7e12e1c9f', '59524a38-c136-4b7e-b8a2-95b7bb50620c', 1, 'El donatario o sus herederos podrán oponerse a la revocación que haga el donante, contradiciendo las causas que éste invoque, para que judicialmente se decida sobre el mérito de ellas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a2bb3760-e3f4-4f61-bdb4-9612966d07d2', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1871', NULL, 1746, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c1cd620f-a4e5-4d8c-8453-1d116cf479d9', 'a2bb3760-e3f4-4f61-bdb4-9612966d07d2', 1, 'Queda consumada la revocación que no fuere contradicha dentro de los sesenta días siguientes a la fecha en que sea notificada al donatario o a sus herederos.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f9eea3b0-bd44-4ba8-ae17-1b3f91e95b50', 'a2bb3760-e3f4-4f61-bdb4-9612966d07d2', 2, 'ARTICULO 1872. No son revocables las donaciones remuneratorias, las que se hacen con motivo de matrimonio que se ha efectuado y los obsequios que se acostumbra por razones sociales o de piedad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2b5bbcdf-8ae8-45d0-a369-db60d11cbff6', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1873', NULL, 1747, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('adaa8ed7-ee08-4638-9c7c-6efcaf22f46c', '2b5bbcdf-8ae8-45d0-a369-db60d11cbff6', 1, 'La revocación de la donación perjudica a tercero desde que se presentare al Registro la escritura, si se tratare de bienes inmuebles, y desde que se hiciere saber a los terceros o se publicare la revocación, si se tratare de otra clase de bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a5929e8a-1b28-42cf-a0d3-18ba820b215d', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1874', NULL, 1748, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6f386231-2ca2-4d7a-9dc3-b8ad88355790', 'a5929e8a-1b28-42cf-a0d3-18ba820b215d', 1, 'La facultad de revocar la donación por causa de ingratitud dura seis meses, contados desde que el donante tuvo conocimiento del hecho que la motiva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ce0dc0f-8eaa-4b11-aed8-f37308743119', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1875', NULL, 1749, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b1ead9e-48b5-4cd8-a25e-2a3cc9afcbe7', '9ce0dc0f-8eaa-4b11-aed8-f37308743119', 1, 'Si la donación fuere onerosa y el donatario no cumpliere la prestación a que se hubiere obligado, o sin justa causa la suspende o interrumpe, puede el donante rescindir el contrato; sin embargo, si la obligación del donatario consistiere en el pago de una pensión o deuda y hubiere pagado la mitad o más, el donante o sus herederos no podrán rescindir el contrato sino solamente reducir la donación efectiva en cuanto a los bienes que sean necesarios para completar el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4af86abf-7e26-447c-b4d1-284f730f6d59', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1876', NULL, 1750, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0c62aa49-2c79-49b7-a2ec-a76f587add6a', '4af86abf-7e26-447c-b4d1-284f730f6d59', 1, 'El donante que desmejora de fortuna puede reducir la donación en la parte necesaria para sus alimentos. Si fueren varias las donaciones hechas a diversas personas, la reducción comenzará por la última en fecha y se continuará con la inmediata anterior hasta llegar a la más antigua.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('57533038-40a9-4290-adf1-31266d00d987', '4af86abf-7e26-447c-b4d1-284f730f6d59', 2, 'Habiendo diversas donaciones otorgadas en la misma fecha, se hará la reducción a prorrata.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6a3cec8-0da5-47e2-b892-2096ecd8df66', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1877', NULL, 1751, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d7c25ef-3c2a-48ef-8d5c-0082edf9b189', 'b6a3cec8-0da5-47e2-b892-2096ecd8df66', 1, 'Si no fuere posible la devolución de las cosas donadas, al revocarse, rescindirse o reducirse la donación, el donatario estará obligado a devolver el valor que hayan tenido al tiempo de hacerse la donación, o la parte de ese valor, según los casos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('23aa8386-5772-4f82-b52f-c76d77f9542b', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1878', NULL, 1752, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6a1c38c9-de5a-4ac4-be79-d3124a462cc5', '23aa8386-5772-4f82-b52f-c76d77f9542b', 1, 'Los frutos y productos de las cosas donadas corresponden al donatario hasta el día en que se le notifique la revocación, rescisión o reducción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3cd17705-d645-4c12-bc3d-2d55151c72d6', 'a0000000-0000-0000-0000-000000000001', 'ad92f025-33a0-4bb1-a15d-e42266b74d5c', '1879', NULL, 1753, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('be76e94b-d782-4d1d-b499-2f859e0f8ac9', '3cd17705-d645-4c12-bc3d-2d55151c72d6', 1, 'La acción para pedir la reducción o rescisión de la donación dura seis meses, contados desde el día en que sobrevino el motivo de la reducción o rescisión.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2c536ac8-4ba3-4dc1-a7ef-8981f8cecedb', '3cd17705-d645-4c12-bc3d-2d55151c72d6', 2, 'DEL ARRENDAMIENTO');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7bef196a-9e87-43fb-9ee2-0865d10a5bc8', '3cd17705-d645-4c12-bc3d-2d55151c72d6', 3, 'DISPOSICIONES GENERALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('64f804c9-1b6b-4992-95a7-c5cff4ded666', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1880', NULL, 1754, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('36f03f73-9daf-4d0a-ad11-bbb8a4db704f', '64f804c9-1b6b-4992-95a7-c5cff4ded666', 1, 'El arrendamiento es el contrato por el cual una de las partes se obliga a dar el uso o goce de una cosa por cierto tiempo, a otra que se obliga a pagar por ese uso o goce un precio determinado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3bcf7820-84b4-4af1-be50-21bfa59b213f', '64f804c9-1b6b-4992-95a7-c5cff4ded666', 2, 'Todos los bienes no fungibles pueden ser objeto de este contrato, excepto aquellos que la ley prohíbe arrendar y los derechos estrictamente personales.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9abd8100-c711-4be2-9496-5bc5d3000423', '64f804c9-1b6b-4992-95a7-c5cff4ded666', 3, 'La renta o precio del arrendamiento debe consistir en dinero o en cualquiera otra cosa equivalente, con tal que sea cierta y determinada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a8788a60-8d6b-49e9-b04b-a23079f27033', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1881', NULL, 1755, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7d5847a-5021-45ee-8f17-fd773b59fbb8', 'a8788a60-8d6b-49e9-b04b-a23079f27033', 1, 'Puede dar bienes en arrendamiento el propietario que tenga capacidad para contratar, así como el que por ley o pacto tenga esta facultad respecto de los bienes que administra.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('35b1a199-f5d3-4570-a5dd-a77154798ab6', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1882', NULL, 1756, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ba584820-4d00-4468-8e04-879dec59a25d', '35b1a199-f5d3-4570-a5dd-a77154798ab6', 1, 'El marido necesita del consentimiento de su cónyuge para dar en arrendamiento los bienes comunes del patrimonio conyugal por un plazo mayor de 3 años o con anticipo de la renta por más de un año.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bafd1188-8a30-46c1-bb7a-631183ff60ee', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1883', NULL, 1757, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c89c1974-f28f-4631-95ed-395170990fbc', 'bafd1188-8a30-46c1-bb7a-631183ff60ee', 1, 'El copropietario de cosa indivisa no puede darla en arrendamiento sin el consentimiento de sus condueños.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0e6206e5-7dee-480d-bca4-9a31c885166a', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1884', NULL, 1758, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d8e9377-9e3d-43f8-a93c-6661e7860027', '0e6206e5-7dee-480d-bca4-9a31c885166a', 1, 'No pueden tomar en arrendamiento: 1. Los administradores de bienes ajenos, los bienes que estén a su cargo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9a9ccdbc-a5e5-4c9f-8e4a-834ee10efc22', '0e6206e5-7dee-480d-bca4-9a31c885166a', 2, '2. El mandatario, los bienes del mandante, a no ser con el consentimiento expreso de éste; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad215182-b609-490b-9b62-72c4cd7812ef', '0e6206e5-7dee-480d-bca4-9a31c885166a', 3, '3. Los funcionarios y empleados públicos, los bienes que son objeto de los asuntos en que intervienen por razón de su cargo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('25ec7d51-99d9-40ac-9918-6cccd4626995', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1885', NULL, 1759, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('97c8d604-7325-480a-b369-780fdaa186e0', '25ec7d51-99d9-40ac-9918-6cccd4626995', 1, 'Cuando una misma cosa se hubiere arrendado a dos o más personas, tendrá la preferencia el primer contratante, y si los contratos fueren de la misma fecha, el que tenga la cosa en su poder; pero, sí el arrendamiento debe inscribirse en el registro de la propiedad, la preferencia corresponderá al que primero haya inscrito su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e13ee53a-31e8-4921-abc8-c993e2a32b9e', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1886', 'El plazo del arrendamiento será fijado por las partes', 1760, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e0555fa8-0cf5-4feb-be6b-923fe634daf7', 'e13ee53a-31e8-4921-abc8-c993e2a32b9e', 1, 'El arrendatario tendrá derecho de tanteo para la renovación del contrato por un nuevo plazo, siempre que haya cumplido voluntariamente todas las obligaciones que contrajo en favor del arrendador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('baf205cc-f8fa-4b1f-9a72-e112a42a60dd', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1887', NULL, 1761, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('980cad4d-d67d-478a-a888-c4cdebca6594', 'baf205cc-f8fa-4b1f-9a72-e112a42a60dd', 1, 'Vencido el plazo del arrendamiento, si el arrendatario no devuelve la cosa y el arrendador no la reclama y, en cambio, recibe la renta del período siguiente sin hacer reserva alguna, se entenderá prorrogado el contrato en las mismas condiciones, pero por plazo indeterminado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('526b95fe-f43c-43db-b16c-1fc1598114f6', 'baf205cc-f8fa-4b1f-9a72-e112a42a60dd', 2, 'La prórroga del contrato por voluntad expresa o tácita de las partes, extingue las fianzas y seguridades que un tercero haya prestado para garantizarlo, salvo que el fiador se obligue expresamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('aa79579e-85c1-40b7-96a1-98d5c8d4d4e1', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1888', NULL, 1762, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44e3ed45-b165-4f2e-b77e-2b92bd7d4291', 'aa79579e-85c1-40b7-96a1-98d5c8d4d4e1', 1, 'En los arrendamientos cuya duración se cuenta por años forzosos y voluntarios, estos últimos se convierten en obligatorios si el optante no avisa al otro, con tres meses de anticipación, que terminará el contrato cuando se acaben los años forzosos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('609d8119-0e07-47a3-ad3c-50ec7b48c0fc', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1889', NULL, 1763, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32bc493f-ab4c-4eb7-98fc-e230a00bfb0b', '609d8119-0e07-47a3-ad3c-50ec7b48c0fc', 1, 'Las cláusulas del contrato que sean oscuras o dudosas sobre la duración del arrendamiento, se interpretarán a favor del arrendatario que no haya sido moroso en el pago de la renta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cebb41a6-d1c5-4a6f-b3ee-a39f34321fc4', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1890', NULL, 1764, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4da9a3a2-59f8-4cd0-b72d-9a638b37d064', 'cebb41a6-d1c5-4a6f-b3ee-a39f34321fc4', 1, 'El arrendatario podrá subarrendar en todo o en parte la cosa arrendada si no le ha sido prohibido expresamente, pero no puede ceder el contrato sin expreso consentimiento del arrendador. El subarriendo total o parcial no menoscaba los derechos ni las obligaciones que respectivamente corresponden al arrendador y al arrendatario, ni altera las garantías constituidas para seguridad del contrato de arrendamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2a433a44-3502-4d92-8265-73a464604d29', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1891', NULL, 1765, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2e5d6f9-bec3-4c19-96a7-d75f5cdab6dc', '2a433a44-3502-4d92-8265-73a464604d29', 1, 'El subarrendatario no podrá usar la cosa en otros términos ni para otros usos que los estipulados con el primer arrendador; y será responsable solidariamente con el arrendatario por todas las obligaciones a favor del arrendador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('da2062c2-fe5c-4d88-bf00-56eb55e96bb2', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1892', NULL, 1766, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d5f7f83c-764e-496f-a84d-5c775c840724', 'da2062c2-fe5c-4d88-bf00-56eb55e96bb2', 1, 'Cesado el arrendamiento caducan los subarrendamientos aunque su plazo no hubiere vencido; salvo el derecho del subarrendatario para exigir del arrendatario la indemnización correspondiente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54c0898f-efe6-47ac-902b-b0667bf54b1d', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1893', NULL, 1767, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3145c403-b9d9-4e98-96cb-a98e7e2acd2d', '54c0898f-efe6-47ac-902b-b0667bf54b1d', 1, 'Ninguna de las partes puede mudar la forma de la cosa arrendada sin consentimiento de la otra. La violación de este precepto da derecho al perjudicado para exigir que la cosa se reponga al estado que guardaba anteriormente, o a que se rescinda el contrato si la modificación fue de tal importancia que la haga desmerecer para el objeto del arrendamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('82a58ce3-cdca-445d-98bc-4f6682504b1a', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1894', NULL, 1768, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('779d0abf-9c12-4a5e-be6e-986df2fec9be', '82a58ce3-cdca-445d-98bc-4f6682504b1a', 1, 'Si durante el arrendamiento el arrendador enajena la cosa, el nuevo dueño no podrá negarse a mantener en el uso de ella al arrendatario mientras no expire el término del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83949268-319c-403c-a9d8-55eae8c9134e', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1895', NULL, 1769, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f7358b0-8f1f-43c9-b3df-74a8020c8cc0', '83949268-319c-403c-a9d8-55eae8c9134e', 1, 'Si el arrendatario abandonare la cosa arrendada, el contrato se tendrá por resuelto y el arrendador tendrá derecho a que se le entregue judicialmente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03dd2e50-f871-4285-9f06-01e806937e3a', 'a0000000-0000-0000-0000-000000000001', 'd5b0a189-a83a-44ef-850e-0ff3f4ee739a', '1896', NULL, 1770, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ea24aef9-22a7-4cbe-a6d1-c93bfd25e2af', '03dd2e50-f871-4285-9f06-01e806937e3a', 1, 'Los arrendamientos de bienes nacionales, municipales o de entidades autónomas o semiautónomas, estarán sujetos a sus leyes respectivas y, subsidiariamente, a lo dispuesto en este Código.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('48cd164f-44d3-406f-86b4-2d1b5bae176e', '03dd2e50-f871-4285-9f06-01e806937e3a', 2, 'OBLIGACIONES Y DERECHOS DEL ARRENDADOR');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ca8968a5-094d-4629-9b00-e4bea18a41cf', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1897', NULL, 1771, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b7f72531-b383-4ae3-886a-8af6757cc3a5', 'ca8968a5-094d-4629-9b00-e4bea18a41cf', 1, 'El arrendador está obligado a entregar la cosa en estado de servir al objeto del arrendamiento. La entrega debe hacerse inmediatamente si no se fija plazo; pero si el arrendatario debe pagar la renta anticipadamente o prestar garantía, mientras no cumpla estas obligaciones, no estará obligado el arrendador a entregar la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('460c3d5a-49d8-4ae4-bf5a-2dc8abc3dc14', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1898', NULL, 1772, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3a0b2688-eedb-424b-9741-aaefadfb248f', '460c3d5a-49d8-4ae4-bf5a-2dc8abc3dc14', 1, 'El arrendador que de buena fe da en arrendamiento cosa ajena, se libra de responsabilidad si presenta otra de iguales o mejores condiciones al arrendatario, aunque no la acepte.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc14c926-54ec-47fb-a7aa-7568e59d7bb0', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1899', NULL, 1773, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b9973985-cc15-4410-b9a3-665e52df17ee', 'fc14c926-54ec-47fb-a7aa-7568e59d7bb0', 1, 'Si el arrendatario sabía que la cosa era ajena y no se cuidó de asegurarse de la facultad del arrendador para celebrar el contrato, no tendrá derecho a ninguna indemnización por la falta de entrega o la privación de la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('71470b01-0ed1-48d3-9c05-8d0636f07b0e', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1900', NULL, 1774, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4665f4c-8ffd-4ae3-a03a-c5bb86ddd9ee', '71470b01-0ed1-48d3-9c05-8d0636f07b0e', 1, 'Si la cosa se destruye antes de la entrega, en su totalidad o de modo que quede inútil para el propósito del arrendamiento, sin culpa del arrendador, no tendrá obligación de indemnizar al arrendatario, pero devolverá la renta si se hubiere anticipado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54b4ac58-b9ad-4146-8967-07808a191761', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1901', NULL, 1775, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a6e8501e-fb23-4f25-83a3-ebf5b360089e', '54b4ac58-b9ad-4146-8967-07808a191761', 1, 'El arrendador está obligado: 1. A poner en conocimiento del arrendatario, en el acto de celebrarse el contrato, los vicios ocultos de la cosa y las limitaciones y gravámenes que puedan perjudicarle;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('367f371b-2362-4ae7-a5c2-83a4940603f9', '54b4ac58-b9ad-4146-8967-07808a191761', 2, '2. A mantener al arrendatario en el goce pacífico de la cosa durante el arrendamiento;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('04ac1ddf-2731-4921-8404-dec457841c7b', '54b4ac58-b9ad-4146-8967-07808a191761', 3, '3. A no estorbar ni embarazar de manera alguna el uso de la cosa arrendada, a no ser por causa de reparaciones urgentes e Indispensables;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('522e0af1-5b69-4a3a-91db-5fa714c9731b', '54b4ac58-b9ad-4146-8967-07808a191761', 4, '4. A conservar la cosa arrendada en el mismo estado, durante el arrendamiento, haciendo para ello todas las reparaciones necesarias;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ae94b2c1-f1a4-4167-97a6-cb7ab73b06bf', '54b4ac58-b9ad-4146-8967-07808a191761', 5, '5. A defender el uso de la cosa contra un tercero que pretenda tener o quiera ejercer algún derecho sobre ella; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e37a7d32-5302-489e-b330-b96f13a1199c', '54b4ac58-b9ad-4146-8967-07808a191761', 6, '6. A pagar los impuestos fiscales y municipales que gravitan sobre la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1ae966f-0988-4145-9dcb-1865e3b54a68', 'a0000000-0000-0000-0000-000000000001', '8e307aae-9a81-4a9e-bb3e-81df20ef518c', '1902', NULL, 1776, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7096bc95-e2be-4a5d-acb2-fcce15db700f', 'd1ae966f-0988-4145-9dcb-1865e3b54a68', 1, 'Si el arrendador no hiciere las reparaciones que sean necesarias para impedir la destrucción o deterioro de la cosa, después de ser avisado de la urgencia de su realización, quedará a elección del arrendatario rescindir el arrendamiento o solicitar autorización judicial para hacerlas por su cuenta. El juez, con');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41c8498c-4b0b-43d3-bd23-43a265f83d14', 'd1ae966f-0988-4145-9dcb-1865e3b54a68', 2, 'conocimiento de causa, fijará la cantidad máxima que el arrendatario podrá gastar y la parte de alquileres o rentas que deberá aplicarse al pago.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f3a99002-a53e-4670-aa60-8ab6cfbdfcb4', 'd1ae966f-0988-4145-9dcb-1865e3b54a68', 3, 'OBLIGACIONES Y DERECHOS DEL ARRENDATARIO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('46bc961c-4fc1-42fb-9076-5b2ce37d4358', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1903', NULL, 1777, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9fb5c4cb-b528-4317-b2f5-4990b0b6200f', '46bc961c-4fc1-42fb-9076-5b2ce37d4358', 1, 'El arrendatario está obligado a pagar la renta desde el día en que reciba la cosa, en los plazos, forma y lugar convenidos. A falta de convenio, la renta se pagará vencida, a la presentación del recibo firmado por el arrendador o su representante legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fb1aa700-0381-4373-9482-6eab3c99df07', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1904', NULL, 1778, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ca04f115-7dbe-4c62-885f-daf2b15ae7aa', 'fb1aa700-0381-4373-9482-6eab3c99df07', 1, 'Si el contrato se rescinde o se declara terminado antes de vencerse el plazo, o si la cosa se devuelve después de vencido el contrato, la renta correrá hasta el día en que efectivamente sea devuelta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('049bd299-d629-4dcd-b6c1-491e8f662ca2', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1905', NULL, 1779, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('346e9dbc-1008-427f-98a2-d13b0406c739', '049bd299-d629-4dcd-b6c1-491e8f662ca2', 1, 'No es válida la estipulación de que el arrendatario pagará la totalidad de las rentas por devolución de la cosa antes del vencimiento del plazo, salvo lo dispuesto en el artículo 1888.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d44c602e-c19e-4f59-ad01-2dc32ddcfad3', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1906', NULL, 1780, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('471a2d05-6753-4269-883c-2e221f43c6b2', 'd44c602e-c19e-4f59-ad01-2dc32ddcfad3', 1, 'Si el arrendatario se ve impedido, sin culpa suya, del uso total o parcial de la cosa arrendada, no está obligado a pagar la renta en el primer caso, y tiene derecho, en el segundo, a una rebaja proporcional que, a falta de acuerdo, fijará el juez. En ambos casos, si el impedimento dura más de dos meses, el arrendatario podrá pedir la rescisión del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('516fe32f-ff5c-4279-adf1-24473d8dd0b9', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1907', NULL, 1781, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f9f362a-5d62-46d5-af0a-b320d914701f', '516fe32f-ff5c-4279-adf1-24473d8dd0b9', 1, 'El arrendatario está obligado: 1. A servirse de la cosa solamente para el uso convenido, y a falta de convenio, para el que corresponda según su naturaleza y destino;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('52596b6d-e3cc-4873-962e-9f5864570e8d', '516fe32f-ff5c-4279-adf1-24473d8dd0b9', 2, '2. A responder de todo daño o deterioro que el bien arrendado sufra por su culpa o la de sus familiares, dependientes y subarrendatarios, así como los que causen los animales y cosas que en ella tenga; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fc2782a-9cd6-4305-86a3-0db707b4dcd1', '516fe32f-ff5c-4279-adf1-24473d8dd0b9', 3, '3. A devolver la cosa, al terminar el arrendamiento, en el estado en que se le entregó, salvo los desperfectos inherentes al uso prudente de ella.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d8ec8f1-5d7c-4d7c-b0ee-67843769a4a7', '516fe32f-ff5c-4279-adf1-24473d8dd0b9', 4, 'Si la entrega se hizo por inventario, la devolución deberá hacerse de conformidad con el mismo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('54c7d911-7822-42e3-9c13-79f25384178d', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1908', NULL, 1782, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('393b6a57-1228-431e-bd42-2ddf8bfaff9a', '54c7d911-7822-42e3-9c13-79f25384178d', 1, 'El arrendatario que establece en el inmueble arrendado una industria peligrosa, tiene obligación de asegurarlo contra los riesgos que se originan del ejercicio de esa industria, siendo responsable por los daños que se causen si así no lo hiciere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('677e03b6-936d-4990-b692-c2709fe74716', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1909', NULL, 1783, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('308839ae-26bb-4cc9-9161-c1ff9a737370', '677e03b6-936d-4990-b692-c2709fe74716', 1, 'Serán de cuenta del arrendatario las reparaciones llamadas locativas, pero serán de cuenta del arrendador si los deterioros provinieren de mala calidad o defecto de construcción de la cosa arrendada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3638fe45-2e0a-4181-93e4-dbb0591a775d', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1910', NULL, 1784, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ed9e3ec5-8400-43a9-bd4d-9eaee3705c2e', '3638fe45-2e0a-4181-93e4-dbb0591a775d', 1, 'Se entiende por reparaciones locativas las que según la costumbre del lugar son a cargo del arrendatario y, en general, las de aquellos deterioros que ordinariamente se producen por culpa del arrendatario, sus familiares o dependientes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c38e5bab-8d2b-4c1c-a66c-b063c333c77f', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1911', NULL, 1785, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('18d920aa-d51c-4816-9686-c61eb5262037', 'c38e5bab-8d2b-4c1c-a66c-b063c333c77f', 1, 'El arrendatario está obligado a poner inmediatamente en conocimiento del arrendador, de cualquiera usurpación o imposición de servidumbre que se intente contra el inmueble, siendo responsable de los perjuicios que cause su omisión.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('300ef4f8-2e62-495b-9ab6-bd4152bcb728', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1912', NULL, 1786, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a8aac3df-8d91-4519-8981-206b44dfa976', '300ef4f8-2e62-495b-9ab6-bd4152bcb728', 1, 'El arrendatario es responsable del incendio del bien objeto del arrendamiento, a no ser que provenga de caso fortuito, fuerza mayor o vicio de construcción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5cc4401f-bac7-49c8-be44-469978d80c5f', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1913', NULL, 1787, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67ea85a2-e5ba-476f-8f14-f14a30c1e3e6', '5cc4401f-bac7-49c8-be44-469978d80c5f', 1, 'Si son varios los arrendatarios, todos son responsables del incendio en la proporción de la parte que respectivamente ocupan, a no ser que se pruebe que el incendio comenzó en la habitación de alguno de ellos, quien en tal caso será el único responsable.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('956c3941-5ed3-4dc1-ad77-234a6e05ac13', 'a0000000-0000-0000-0000-000000000001', 'c37814bf-528a-4567-9695-ad02012ed124', '1914', NULL, 1788, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d45ae292-3c29-4f14-a2cd-2c6730b9c218', '956c3941-5ed3-4dc1-ad77-234a6e05ac13', 1, 'Cesa la responsabilidad del arrendatario, en caso de incendio, si la cosa estuviere asegurada; salvo el derecho del asegurador contra el arrendatario si el incendio fue causado por culpa de éste.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('222db481-aa18-4850-a766-5eba0e6aa0be', '956c3941-5ed3-4dc1-ad77-234a6e05ac13', 2, 'DE LAS MEJORAS');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('74bb7b19-5922-4c3a-97c9-ff92e46dd097', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1915', NULL, 1789, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b048acf4-c027-44a6-b588-ad655085211d', '74bb7b19-5922-4c3a-97c9-ff92e46dd097', 1, 'El arrendatario tiene facultad de hacer en la cosa arrendada, sin alterar su forma, todas las mejoras de que quiera gozar durante el arrendamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3b01dff-4619-4761-be09-711d7497dd67', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1916', NULL, 1790, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d635494-542b-4f2c-b0c8-40edde701838', 'e3b01dff-4619-4761-be09-711d7497dd67', 1, 'Las mejoras son necesarias, cuando tienen por objeto impedir la destrucción o el deterioro de la cosa. Son útiles cuando, sin pertenecer a la clase de necesarias, aumentan el valor y renta de la cosa en que se ponen.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6d4ebf23-b2a9-4c5a-a41e-61409aaab5cb', 'e3b01dff-4619-4761-be09-711d7497dd67', 2, 'Y son de recreo cuando, sin ser necesarias ni útiles, sirven para ornato, lucimiento o mayor comodidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ba4a9c39-d936-4a23-bfdd-eecbfff93299', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1917', NULL, 1791, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aeeb2efa-5f72-45ed-89db-841999b0ca71', 'ba4a9c39-d936-4a23-bfdd-eecbfff93299', 1, 'Ninguna mejora es abonable al arrendatario, salvo convenio por escrito en que el dueño se haya obligado a pagarla. Quedan exceptuadas de esta disposición las reparaciones necesarias o las locativas que sean de cuenta del arrendador, las cuales serán abonables si se hacen por el arrendatario después de notificar al primero, privada o judicialmente, la necesidad de la reparación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('22559f0a-a999-4ee8-8274-9ade11bc854d', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1918', NULL, 1792, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2e1e38a3-c4c2-4a78-9ac3-4131f3f30344', '22559f0a-a999-4ee8-8274-9ade11bc854d', 1, 'Es nulo el contrato sobre abono de mejoras en que no se especifica, al menos aproximadamente, cuáles deben ser éstas y cuánta será la mayor cantidad que con tal objeto pueda gastar el arrendatario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('45f422eb-ff83-4c10-9392-076b92652e01', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1919', NULL, 1793, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f46f516-2b0a-4fd5-8361-a237316adc3e', '45f422eb-ff83-4c10-9392-076b92652e01', 1, 'Puede el arrendador autorizar al arrendatario para que invierta en mejorar la cosa arrendada, una o más de sus rentas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d36e631-75a0-4dc6-a501-34752080022f', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1920', NULL, 1794, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27b0d277-36f7-47d5-bcac-d3644ebe232c', '2d36e631-75a0-4dc6-a501-34752080022f', 1, 'También puede autorizarse al arrendatario, para que de sus fondos propios gaste en mejoras de la cosa, hasta la cantidad que se estipule.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('038da872-6fea-4797-a548-0225d88c009e', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1921', NULL, 1795, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e8dcb0b0-eabd-4f39-a15d-eb3c9e87fbeb', '038da872-6fea-4797-a548-0225d88c009e', 1, 'Cuando el arrendatario haya puesto mejoras con consentimiento del dueño, o sin él, para gozar de ellas durante el tiempo del arrendamiento y dejarlas después a beneficio de la finca, sin responsabilidad de éste; si antes de concluirse ese tiempo se interrumpe el arrendamiento por causa o culpa del dueño, desde entonces se hacen abonables las mejoras necesarias o útiles. En este caso, el dueño o el que le suceda en la cosa responderá, o bien de todo el valor de ellas si no las hubiere disfrutado todavía el arrendatario, o sólo de una parte proporcional al tiempo que faltaba del contrato si ya hubiese empezado a gozarlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9d4b36db-62cc-40c4-9e12-baa3ad7079b3', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1922', NULL, 1796, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6877c45a-f28a-4444-bbf4-54cc4f29f072', '9d4b36db-62cc-40c4-9e12-baa3ad7079b3', 1, 'La tasación de mejoras se arreglará: 1. Al convenio de las partes; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a4e5dd4-a330-4ab9-a9a2-62b6f37ab145', '9d4b36db-62cc-40c4-9e12-baa3ad7079b3', 2, '2. A lo gastado en ponerlas y conservarlas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cce14c36-1c9b-49f7-bf20-19abbc3ab081', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1923', NULL, 1797, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cee6e0a0-8820-4eb1-8a13-608b2a2f99e6', 'cce14c36-1c9b-49f7-bf20-19abbc3ab081', 1, 'Siempre que se haga tasación de mejoras abonables al arrendatario, se incluirá en ella y se rebajará de su monto, el valor de los daños o deterioros a que se refiere el inciso 2, del artículo 1907.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('41e97d7f-5d67-40e2-979d-47b8134276ba', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1924', NULL, 1798, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5a3ae919-d224-4368-a511-e71cdc46be45', '41e97d7f-5d67-40e2-979d-47b8134276ba', 1, 'Si son separables las mejoras que no se deben abonar, puede separarlas el arrendatario que las puso. Si no son separables, o si no puede hacerse la separación sin destruirlas, el arrendador puede impedir que se destruyan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ddc0ee35-166e-4e24-839d-24107c19be6f', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1925', NULL, 1799, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('05ae3e48-cb33-4129-8fbd-5db4e7b292f5', 'ddc0ee35-166e-4e24-839d-24107c19be6f', 1, 'Las mejoras que sean abonables por haberse puesto conforme a lo convenido legalmente entre el dueño y el arrendatario, serán pagadas en cantidad, tiempo y forma, según convenio.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('931fd367-e4d8-4fa2-bcb7-e1ed2399b77b', 'ddc0ee35-166e-4e24-839d-24107c19be6f', 2, 'Faltando acuerdo sobre el modo de verificarse el pago de estas mejoras, se hará con la cantidad que baste de la renta del último año del arrendamiento.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6839ebf5-dced-4887-a38c-945538411b81', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1926', NULL, 1800, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6821b5c4-d998-4b9f-abbf-b8671d8c4280', '6839ebf5-dced-4887-a38c-945538411b81', 1, 'Cuando en un contrato de arrendamiento se designa por renta una cantidad menor de la que produce la cosa, con el objeto explícito de que la mejore el arrendatario, si éste no cumple con poner las mejoras, el arrendador tiene derecho a pedir la rescisión del contrato; la devolución de las cantidades que se rebajaron de la renta, en consideración a las mejoras; los intereses de la suma a que estas cantidades asciendan, y la indemnización de los perjuicios que se le hubieren causado. Tiene los mismos derechos el arrendador, cuando de cualquier otro modo se entrega o deja al arrendatario alguna cantidad destinada expresamente para mejoras, si éste no cumple con la obligación de mejorar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('45efad96-6a5c-45d9-8a6a-85726d36c63b', 'a0000000-0000-0000-0000-000000000001', '5710c5b9-e48b-42a1-989e-2a9a09598e94', '1927', NULL, 1801, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fdd870b2-4432-433e-ba8f-edc443c6ef5e', '45efad96-6a5c-45d9-8a6a-85726d36c63b', 1, 'Si el arrendatario hubiese puesto sólo una parte más o menos considerable de las mejoras a que estaba obligado, el juez resolverá, según las circunstancias, sobre la rescisión del contrato, pero siempre habrá lugar a la devolución de las cantidades que dejaron de emplearse en mejoras, al pago de sus respectivos intereses y a la indemnización de los perjuicios causados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15ead68e-ee80-4324-bd09-dbe308b807ea', '45efad96-6a5c-45d9-8a6a-85726d36c63b', 2, 'DEL MODO DE TERMINAR EL ARRENDAMIENTO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b12d0725-15bb-408b-bacd-61798d1b4770', 'a0000000-0000-0000-0000-000000000001', '6e631a84-ea33-44b1-a7e8-9fa38f008b39', '1928', NULL, 1802, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f2f04b91-9996-4d65-a2f7-779f81b95a1e', 'b12d0725-15bb-408b-bacd-61798d1b4770', 1, 'El arrendamiento termina por el cumplimiento del plazo fijado en el contrato, o por la ley, o por estar satisfecho el objeto para el que la cosa fue arrendada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fb0bf720-e599-4e0e-ade8-e6809bcb2d98', 'a0000000-0000-0000-0000-000000000001', '6e631a84-ea33-44b1-a7e8-9fa38f008b39', '1929', NULL, 1803, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('731bfa9f-b4da-4580-9ad8-91c4b75263c4', 'fb0bf720-e599-4e0e-ade8-e6809bcb2d98', 1, 'Termina también el arrendamiento: 1. Por convenio expreso;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa58547e-4501-4bfd-8e2b-5d492e66da84', 'fb0bf720-e599-4e0e-ade8-e6809bcb2d98', 2, '2. Por nulidad o rescisión del contrato;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f55c96c3-b3b1-4101-b267-9f0eba292f51', 'fb0bf720-e599-4e0e-ade8-e6809bcb2d98', 3, '3. Por pérdida o destrucción total de la cosa arrendada; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ded2971d-dace-44de-9b71-e6a691f17cff', 'fb0bf720-e599-4e0e-ade8-e6809bcb2d98', 4, '4. Por expropiación o evicción de la cosa arrendada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('997af2b5-7557-4a60-963c-ee2879484c21', 'a0000000-0000-0000-0000-000000000001', '6e631a84-ea33-44b1-a7e8-9fa38f008b39', '1930', NULL, 1804, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b31a7ca0-98cd-47da-9a4b-8986af765007', '997af2b5-7557-4a60-963c-ee2879484c21', 1, 'Puede rescindirse el arrendamiento: 1. Si el arrendador o el arrendatario faltan al cumplimiento de sus respectivas obligaciones;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('40b86dc3-d2a0-4452-8b64-c76fd6ee6cc4', '997af2b5-7557-4a60-963c-ee2879484c21', 2, '2. Si, tratándose de una finca rústica, el arrendatario abandona las plantaciones existentes al tiempo de celebrar el contrato o no las cultiva con la debida diligencia;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dfd5b1f5-09dd-4d60-8dc8-a6a73444f7a7', '997af2b5-7557-4a60-963c-ee2879484c21', 3, '3. Si entregada la cosa arrendada y debiendo el arrendatario garantizar el pago de la renta, se niega a hacerlo o no lo hace en el término convenido;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('97cc29f4-8f6a-486f-82ea-d9ab883a0ee4', '997af2b5-7557-4a60-963c-ee2879484c21', 4, '4. Por mayoría de edad del menor, rehabilitación del incapaz o vuelta del ausente, en los arrendamientos que hubieren celebrado sus respectivos representantes con plazo mayor de tres años;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fc26e2e8-a1cc-4980-a8d3-e52bd3bf261e', '997af2b5-7557-4a60-963c-ee2879484c21', 5, '5. Por subarrendar contra prohibición expresa del arrendador;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4ecc8012-be90-4a2e-873b-bd246232c50c', '997af2b5-7557-4a60-963c-ee2879484c21', 6, '6. Por usar el arrendatario la cosa arrendada con fines contrarios a la moral o al orden público o a la salubridad pública; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a5da1886-10d7-4c22-a841-1cccfdf26a2a', '997af2b5-7557-4a60-963c-ee2879484c21', 7, '7. Por muerte del arrendatario, si sus herederos no desean continuar con el arrendamiento.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8b30f440-9cdb-411e-8752-01b2595176ef', '997af2b5-7557-4a60-963c-ee2879484c21', 8, 'DISPOSICIONES ESPECIALES RELATIVAS AL ALQUILER DE CASAS Y LOCALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1a43851f-d23a-47c4-a4a7-250833215b45', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1931', NULL, 1805, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c802bf2d-4cd3-45d3-9171-e89333e0c2fa', '1a43851f-d23a-47c4-a4a7-250833215b45', 1, 'No podrá darse en arrendamiento una casa, habitación o local, sin que reúna las condiciones de higiene y salubridad que exige el código respectivo. El propietario o arrendador deberá presentar la tarjeta de habitabilidad del inmueble, expedida por el funcionario competente, para que el contrato pueda otorgarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('cfbacaac-3903-42d3-839a-3736e814743c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1932', NULL, 1806, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45533a47-3c7a-4ff1-8e63-c099a49438be', 'cfbacaac-3903-42d3-839a-3736e814743c', 1, 'El arrendador que no realice las obras que ordene la autoridad que corresponda para que un local sea habitable e higiénico, responderá de los daños y perjuicios que los inquilinos que lo ocupan sufran por su causa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('24b45ec5-2936-4776-82e9-8e5e35ea8676', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1933', NULL, 1807, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('12cf924c-f6f6-47df-a68c-f7255d39b6f3', '24b45ec5-2936-4776-82e9-8e5e35ea8676', 1, 'Los gastos corrientes que ocasionen las disposiciones sobre limpieza, salubridad e higiene que ordenen las autoridades respectivas, son a cargo del arrendatario, si no consisten en modificaciones o mejoras que, según la ley, corresponda hacer al arrendador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('455489a6-5f83-46a7-b36f-2b970893365e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1934', NULL, 1808, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('747d24dd-b640-4e07-b84e-9441c0e8049e', '455489a6-5f83-46a7-b36f-2b970893365e', 1, 'Si se alquila una casa o local amueblado, deberán especificarse los muebles en el contrato y se entenderá que el arrendamiento de éstos es por el mismo tiempo que el del edificio, a no ser que haya convenio en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9edc61e5-2b68-44a8-9a0d-d7ccd2a10a98', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1935', NULL, 1809, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2777ed0d-abb9-45af-9528-5d0ab446bc60', '9edc61e5-2b68-44a8-9a0d-d7ccd2a10a98', 1, 'Salvo estipulación expresa, es a cargo del inquilino el consumo de la energía eléctrica y servicio telefónico, así como el agua que exceda de la que corresponde al inmueble o la cantidad determinada en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17cbe260-3f53-4bcc-aecd-a1e15a5e38ac', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1936', NULL, 1810, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8376191d-7ecc-4910-a1da-bf8f9132d7a9', '17cbe260-3f53-4bcc-aecd-a1e15a5e38ac', 1, 'El pago de la renta se hará en los períodos estipulados, y a falta de convenio, el pago se hará por meses vencidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('694e786c-0671-4f91-8dc2-f07f92255ed1', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1937', NULL, 1811, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('fd8383c1-5e42-49e2-ab39-815ab04ced71', '694e786c-0671-4f91-8dc2-f07f92255ed1', 1, 'El inquilino deberá devolver la casa o local al fin del arrendamiento, en el estado en que le fue entregado, tomándose en consideración el deterioro ocasionado por el uso y goce legítimos. En cuanto a los deterioros graves del inmueble, deberá probar que no fueron causados por su culpa ni la de sus huéspedes, dependientes o subarrendatarios, y, a falta de esta prueba, será responsable por el valor de las reparaciones.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b31fc3a-0a81-42f8-9a18-ae0f3476ea3a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1938', NULL, 1812, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88a8a279-7af6-4cf2-badd-a8ddb37f68a4', '8b31fc3a-0a81-42f8-9a18-ae0f3476ea3a', 1, 'La restitución del edificio la hará el arrendatario desocupándolo enteramente y entregándolo con las llaves al arrendador.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8875bcf2-a565-4504-8b26-979d2cbcdee4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1939', NULL, 1813, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6af40d14-ddf9-451d-9675-eb1f3218d875', '8875bcf2-a565-4504-8b26-979d2cbcdee4', 1, 'El arrendatario podrá poner fin al arrendamiento dando aviso por escrito al arrendador, por lo menos con treinta días de anticipación si se tratare de vivienda y con sesenta días de anticipación si se tratare de locales de negocios u oficinas, salvo lo dispuesto en el artículo 1888.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('35df8b54-ad83-4edc-918a-940775df693c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1940', NULL, 1814, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64d80454-c1c9-4800-93f9-469ab9031a3b', '35df8b54-ad83-4edc-918a-940775df693c', 1, 'El arrendador podrá dar por terminado el arrendamiento en los casos generales establecidos en el artículo 1930 y en los especiales siguientes: 1. Cuando el arrendatario no esté solvente con el pago de la renta y adeuda por lo menos dos meses vencidos;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5571b3d4-f5c8-4cb7-8e34-995f3e7bfc98', '35df8b54-ad83-4edc-918a-940775df693c', 2, '2. Cuando el propietario necesite la casa o vivienda para habitarla él y su familia, siempre que compruebe esta circunstancia. En la familia se comprende su esposa o conviviente de hecho, hijos, padres, o personas que dependan de él económicamente;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('11440da5-d94e-4c56-abc6-7297edaadd59', '35df8b54-ad83-4edc-918a-940775df693c', 3, '3. Cuando el inmueble necesite reparaciones indispensables para mantener su estado de habitabilidad o de seguridad, o vaya a construirse nueva edificación;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c52d9a19-9cf9-4f84-bc69-fa523de868b5', '35df8b54-ad83-4edc-918a-940775df693c', 4, '4. Cuando la vivienda o local sufran deterioros por culpa del arrendatario, o de sus familiares o dependientes, que no sean producidos por el uso normal del inmueble;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('32f3c4f9-3085-42f8-8d82-c45dd082186d', '35df8b54-ad83-4edc-918a-940775df693c', 5, '5. Cuando se trate de inmuebles del Estado o de las municipalidades que sean necesarios para la instalación de sus dependencias, oficinas o servicios; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('37f3fd34-3b61-4354-84e2-4bc68b8b0d17', '35df8b54-ad83-4edc-918a-940775df693c', 6, '6. Cuando el propietario necesite el local para instalar su negocio o cualquiera otra actividad lícita, siempre que no tenga otro inmueble con las condiciones adecuadas para tal fin.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ece9ba2-487e-4729-aa6f-dd28cc95c62a', '35df8b54-ad83-4edc-918a-940775df693c', 7, 'Ocurrido cualquiera de los casos anteriores, se procederá de acuerdo con lo que establecen las leyes respectivas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('880fc445-8bbb-4099-988f-0c6dcf0f5ffa', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1941', NULL, 1815, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f697abb3-e758-4572-9b95-c272a984d7dc', '880fc445-8bbb-4099-988f-0c6dcf0f5ffa', 1, 'Las disposiciones consignadas en este capítulo regirán sin perjuicio de lo establecido en la ley especial de inquilinato u otra ley de emergencia que regule');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b041355d-49d1-44e4-9891-eaa83224f570', '880fc445-8bbb-4099-988f-0c6dcf0f5ffa', 2, 'este contrato, en cuanto a fijación de renta y demás condiciones no determinadas en los artículos anteriores.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f11f2e92-a455-4bdd-8c4a-cac3666b6898', '880fc445-8bbb-4099-988f-0c6dcf0f5ffa', 3, 'DEL MUTUO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38a4a24e-400d-4590-a62a-f091e5ed343b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1942', NULL, 1816, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cec617eb-cdfa-4ff6-b03e-4438a278bcd2', '38a4a24e-400d-4590-a62a-f091e5ed343b', 1, 'Por el contrato de mutuo una persona entrega a otra dinero u otras cosas fungibles, con el cargo de que se le devuelva igual cantidad de la misma especie y calidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('08ff9ced-39ab-4ef7-8a83-396d27bf4d9d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1943', NULL, 1817, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff4762a7-c14a-4e07-907b-d85fed0dbf9b', '08ff9ced-39ab-4ef7-8a83-396d27bf4d9d', 1, 'La cosa objeto del mutuo se transmite para su consumo al mutuario y queda a su cargo la mejora, deterioro, depreciación o destrucción que sobrevenga después.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('df64a0c5-a9f7-4328-a57a-0fdf31ffc0d2', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1944', NULL, 1818, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a405d662-a0ec-4d7a-a596-033db521dab3', 'df64a0c5-a9f7-4328-a57a-0fdf31ffc0d2', 1, 'El mutuante es responsable de los daños que sufra el mutuario por la mala calidad o vicios ocultos de la cosa prestada, si conoció los defectos y no le dio aviso oportunamente. No se reputan vicios ocultos los que el mutuario ha podido conocer por él mismo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af5e6e0d-25ab-4357-bdf2-33e6911d57a7', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1945', NULL, 1819, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e1ccbb32-0f61-4c9e-9d0e-248b59b5f71c', 'af5e6e0d-25ab-4357-bdf2-33e6911d57a7', 1, 'Si el mutuante ignoraba los vicios ocultos de la cosa, sólo está obligado a sufrir la reducción proporcional de su valor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5c811b93-1c9e-4443-8403-4cdf2c83bb53', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1946', NULL, 1820, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7f280edc-98ff-495c-8e82-2e008a99f890', '5c811b93-1c9e-4443-8403-4cdf2c83bb53', 1, 'Salvo pacto en contrario, el deudor pagará intereses al acreedor y, a falta de convenio, se presumirá que las partes aceptaron el interés legal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1894402f-d58d-466c-9e4a-48cc137da6eb', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1947.30', NULL, 1821, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41673ddb-020c-49f6-983c-8a5eb59a32d1', '1894402f-d58d-466c-9e4a-48cc137da6eb', 1, 'El interés legal es igual al promedio ponderado de las tasas de interés activas publicadas de los bancos del sistema al día anterior a la fecha de su fijación, reducido en dos puntos porcentuales. En defecto de su publicación o en caso de duda o discrepancia, se solicitará informe a la Superintendencia de Bancos el cual tendrá carácter definitivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('94eca9d8-60ab-4498-9c89-9568998866d3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1948.31', 'Las partes pueden acordar el interés que les parezca', 1822, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7fd11807-ce8a-4830-a40a-0fefa25a4e64', '94eca9d8-60ab-4498-9c89-9568998866d3', 1, 'Cuando la tasa de interés pactada sea manifiestamente desproporcionada con relación al interés corriente en el mercado, el juez podrá reducirlo equitativamente, tomando en cuenta la tasa indicada en el artículo 1947 y las circunstancias del caso.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('688c5f00-b5bb-45a1-966e-3572d8531b84', '94eca9d8-60ab-4498-9c89-9568998866d3', 2, '30 Reformado como aparece en el texto por el Artículo 9 del Decreto No. 29-95, publicado en el Diario de Centro América el 18 de mayo de 1995. 31 Reformado como aparece en el texto por el Artículo 10 del Decreto No. 29-95, publicado en el Diario de Centro América el 18 de mayo de 1995.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd1bc8b3-3670-4e77-b2e4-1df58a1ceb8d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1949', 'Queda prohibida la capitalización de intereses', 1823, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d9263672-5d04-48fa-a908-81bd6ed73ddb', 'dd1bc8b3-3670-4e77-b2e4-1df58a1ceb8d', 1, 'Se exceptúa a las instituciones bancarias que se sujetarán a lo que sobre el particular establezca la Junta Monetaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52bcb2b1-aa31-47d9-bb79-2bca1a86f1e0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1950', NULL, 1824, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('936195bf-e5c2-4c0d-92ca-ddba642b1a82', '52bcb2b1-aa31-47d9-bb79-2bca1a86f1e0', 1, 'Si en el contrato no se ha fijado plazo para la restitución de lo prestado, se entenderá que es el de seis meses si el mutuo consiste en dinero; y si lo prestado fueren cereales u otros productos agrícolas, la devolución se hará en la próxima cosecha de los mismos o semejantes frutos o productos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec52a4d2-579e-490c-85a5-624baf4c3f2c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1951', NULL, 1825, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e549869-770a-4c8a-a0c7-44e42bfc7203', 'ec52a4d2-579e-490c-85a5-624baf4c3f2c', 1, 'En los prestamos de dinero, el pago de los intereses caídos o de los incurridos después del vencimiento del plazo, no implicará prórroga de éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1810683c-1ed7-4a3c-af21-d7eb6771ee23', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1952', NULL, 1826, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('07053787-9d8f-4f32-a7a2-66f2740834dd', '1810683c-1ed7-4a3c-af21-d7eb6771ee23', 1, 'Si se han prestado cosas fungibles que no sean dinero, se deberá restituir igual cantidad del mismo género y calidad, aunque el precio de ellas haya bajado o subido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('65ecc546-3702-4d1a-b142-d1f306c54cd6', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1953', NULL, 1827, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('210f73a5-8137-441d-a81e-66ced4549bd5', '65ecc546-3702-4d1a-b142-d1f306c54cd6', 1, 'Si las cosas fueren apreciadas al tiempo del contrato, el deudor está obligado a satisfacer el valor que se les dio, aunque valgan más o menos al tiempo del pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b7a77f7c-0dc0-4a29-a4c7-a3422ca0e239', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1954', NULL, 1828, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ac1d02e1-1f9a-48d6-8343-d4829437985c', 'b7a77f7c-0dc0-4a29-a4c7-a3422ca0e239', 1, 'Si no fuere posible al mutuario restituir en género, podrá pagar el valor que la cosa prestada tenga el día en que debiera ser devuelta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52d8fe5b-2e8b-448e-b100-d168ccb0a194', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1955', NULL, 1829, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3528bd90-ddbe-4ad4-8270-8af4243deae5', '52d8fe5b-2e8b-448e-b100-d168ccb0a194', 1, 'El préstamo en dinero se arreglará para la restitución, a lo establecido en los artículos 1395 y 1396.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('902c8e4b-9063-4bff-bbb4-f73a96a1bc12', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1956', NULL, 1830, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5d4460fc-a8af-405a-8cc9-6a5295e61cb9', '902c8e4b-9063-4bff-bbb4-f73a96a1bc12', 1, 'El deudor de una suma de dinero puede anticipar el pago, pero cubriendo los intereses respectivos por todo el tiempo que falte para el vencimiento del plazo.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c0fcdac-83a2-4fae-87dd-c0ce23e4cc91', '902c8e4b-9063-4bff-bbb4-f73a96a1bc12', 2, 'DEL COMODATO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7b0bc160-72dd-4207-b2f7-fdac149ee239', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1957', NULL, 1831, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('411fe790-554b-4223-88d0-ee0dbabaaa08', '7b0bc160-72dd-4207-b2f7-fdac149ee239', 1, 'Por el contrato de comodato una persona entrega a otra, gratuitamente, algún bien mueble no fungible o semoviente, para que se sirva de él por cierto tiempo y para cierto fin y después lo devuelva.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('21b6391f-2c8b-45b1-bf4d-fee8408418ee', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1958', NULL, 1832, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d994eeaf-be67-432f-9742-0cf5912abfd1', '21b6391f-2c8b-45b1-bf4d-fee8408418ee', 1, 'Sólo pueden dar en comodato el que tiene la libre disposición de la cosa y el arrendatario y usufructuario que no tengan prohibición.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4dafd7e4-154d-4c2e-8ae8-5d856e8d7e2e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1959', 'Corresponden al comodante los aumentos de la cosa', 1833, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('faaf3a53-ac39-4ca4-9713-e2ff5c692fbe', '4dafd7e4-154d-4c2e-8ae8-5d856e8d7e2e', 1, 'También le corresponden los menoscabos o pérdidas, cuando no sean debidos a culpa del comodatario o no haya habido pacto de satisfacer daños o perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('10cdf1ec-97cb-496f-8012-6d86b93d03ba', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1960', NULL, 1834, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7664bc61-369a-456e-9a05-96421213d6d1', '10cdf1ec-97cb-496f-8012-6d86b93d03ba', 1, 'Si fue tasada la cosa al entregarla, responderá el comodatario de la pérdida de ella, aún por caso fortuito, salvo pacto en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ed17b290-5e21-4ad3-8c92-e3fabfd1a56e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1961', NULL, 1835, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e0f2de9-ad31-456b-a060-21ee0f745a1d', 'ed17b290-5e21-4ad3-8c92-e3fabfd1a56e', 1, 'El comodato se entiende otorgado en consideración a la persona del comodatario, y éste no podrá transferirlo, salvo pacto expreso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('72c0206c-bbf7-43d5-be52-f937a217baa0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1962', NULL, 1836, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('93305a36-e4db-4003-9ebd-767c81a14371', '72c0206c-bbf7-43d5-be52-f937a217baa0', 1, 'Son obligaciones del comodante: 1. Avisar si la cosa prestada tiene algún vicio oculto, siendo responsable, en caso contrario, de los daños o perjuicios que resulten de los vicios ocultos si, conociéndolos, no dio aviso al comodatario;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e923043b-23c9-4b57-9a55-069eb7c4a42b', '72c0206c-bbf7-43d5-be52-f937a217baa0', 2, '2. No pedir lo que prestó antes del vencimiento del plazo estipulado; y, en defecto de convención antes de haber servido en el uso para que fue prestado; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b95797a0-26d7-4ab6-a158-cddcc3e45c03', '72c0206c-bbf7-43d5-be52-f937a217baa0', 3, '3. Pagar los gastos extraordinarios e indispensables que hubiere hecho el comodatario para la conservación de la cosa prestada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a25dfe85-eae0-4855-a886-ac4dc6965427', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1963', NULL, 1837, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d05dc0b7-7d49-4853-98db-b0dde1329f6c', 'a25dfe85-eae0-4855-a886-ac4dc6965427', 1, 'Si el comodante necesita con urgencia imprevista la cosa prestada, o si ésta corre peligro de perecer si continúa en poder del comodatario, podrá exigir que se le devuelva antes de cumplido el plazo o antes de que se haya usado de ella, y el juez, según las circunstancias, resolverá lo que proceda.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e5181791-c364-4cda-aab9-79a0f7aafe30', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1964', NULL, 1838, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bf7e4241-0267-454c-b494-81bfce39b72d', 'e5181791-c364-4cda-aab9-79a0f7aafe30', 1, 'Son obligaciones del comodatario: 1. Cuidar la cosa prestada;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c68a5094-5604-46ac-a097-9b32fa0938ef', 'e5181791-c364-4cda-aab9-79a0f7aafe30', 2, '2. Emplearla en el uso señalado por su naturaleza o por el pacto; siendo responsable de su pérdida o deterioro proveniente del abuso, aun por caso fortuito;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b0902efe-5b5d-4bdd-9726-a3c7695a9389', 'e5181791-c364-4cda-aab9-79a0f7aafe30', 3, '3. Hacer los gastos ordinarios que exija la cosa mientras dure el comodato; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('684c00b1-c2f9-444d-8402-36a4078c20bf', 'e5181791-c364-4cda-aab9-79a0f7aafe30', 4, '4. Devolver la cosa en el término estipulado o después del uso determinado en el contrato, sin más deterioro que el proveniente del uso ordinario de ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78195d76-6061-4b04-9da9-85ee28639044', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1965', NULL, 1839, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('95fbe5db-724a-4ad9-b488-cd5d05bcdae1', '78195d76-6061-4b04-9da9-85ee28639044', 1, 'Si terminado el comodato y requerido el comodante demora recibir la cosa, todo riesgo será a su cargo y deberá reembolsar los gastos que el comodatario hiciere para conservarla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f105730-4b5f-4c4f-b56b-8957823e4481', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1966', NULL, 1840, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ad838971-bcc3-4cf3-a6d2-7da47c0bf95a', '0f105730-4b5f-4c4f-b56b-8957823e4481', 1, 'El comodatario que demora la devolución de la cosa, responde de la pérdida de la cosa y de los daños y perjuicios, aunque provengan de caso fortuito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('704512fe-97f2-427e-922a-8ac03b1194b4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1967', NULL, 1841, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('53baac72-5b57-4c8d-8be4-2df783fa0826', '704512fe-97f2-427e-922a-8ac03b1194b4', 1, 'Es responsable el comodatario de la pérdida de la cosa y de los daños y perjuicios que resulten de su dolo o culpa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('93253db5-ce9b-4dec-b66d-71eb1b0ca13c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1968', NULL, 1842, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('19394c1f-bf79-43d3-be72-aba74a9d5a43', '93253db5-ce9b-4dec-b66d-71eb1b0ca13c', 1, 'Cuando sea imposible devolver la cosa prestada, el comodatario entregará otra de la misma especie y calidad, o el valor que le corresponda, a elección del comodante, arreglándose a las circunstancias de tiempo y lugar en que debía restituirse. Si la cosa fue valorada al tiempo de la celebración del contrato, el precio que el comodatario devolverá, será el valor que se le dio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('88daaa05-559f-4b1a-9f76-7aa154e653e0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1969', NULL, 1843, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2d61d2e7-e493-4b24-b8aa-bf68e09a53b5', '88daaa05-559f-4b1a-9f76-7aa154e653e0', 1, 'Pagada la cosa prestada en caso de haberse perdido, si la hallare después el comodatario, no podrá ser obligado el comodante a recibirla.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9018049b-247a-4237-b215-d9e430956c0f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1970', NULL, 1844, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1917ad99-edd2-4252-acb1-c50aca1f1570', '9018049b-247a-4237-b215-d9e430956c0f', 1, 'Si la cosa fuere hallada por el comodante, podrá retenerla, restituyendo el precio que se le dio, o quedarse con éste devolviendo aquélla al comodatario. Hallándola un tercero, tiene el comodatario derecho a recobrarla como suya.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('284d1d7a-cd6f-4086-89e0-d589262fd0ee', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1971', NULL, 1845, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cf621936-7780-4b77-8e5a-a0d4f813441f', '284d1d7a-cd6f-4086-89e0-d589262fd0ee', 1, 'El comodatario no puede retener la cosa en seguridad ni en compensación de lo que le debe el comodante, pero si la deuda procede de gastos extraordinarios e indispensables en beneficio de la misma cosa, podrá retenerla en calidad de depósito mientras no se le haga el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('133f8dd5-b184-4486-8ee2-ea89c75b6ee4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1972', NULL, 1846, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5b67b242-fe9e-4235-81c8-7e521ad91d7e', '133f8dd5-b184-4486-8ee2-ea89c75b6ee4', 1, 'Cuando en el contrato de comodato sean varios los comodatarios, todos ellos responderán solidariamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9e9cd11a-be8f-4d61-b869-fcc9e595e106', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1973', NULL, 1847, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2ced6136-29ac-4200-9546-d2b4e38f246c', '9e9cd11a-be8f-4d61-b869-fcc9e595e106', 1, 'El comodante que pagare las responsabilidades civiles provenientes de daños y perjuicios causados por el uso de la cosa prestada, tiene derecho a repetir contra el comodatario por lo que hubiere sido obligado a pagar.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4b6775b8-914a-4a54-8d3d-154cbbc92f38', '9e9cd11a-be8f-4d61-b869-fcc9e595e106', 2, 'DEL DEPÓSITO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c4f3945d-89de-4354-bfb7-42b6ac6fdb5d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1974', NULL, 1848, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a54dd91e-a853-4b6f-8b67-fec01302e85a', 'c4f3945d-89de-4354-bfb7-42b6ac6fdb5d', 1, 'Por el contrato de depósito una persona recibe de otra alguna cosa para su guarda y conservación, con la obligación de devolverla cuando la pida el depositante, o la persona a cuyo favor se hizo, o cuando lo ordene el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('06aec3a1-a52a-4e2f-bd9a-f9a087f8b834', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1975', NULL, 1849, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('060a0cfd-8640-49da-9c64-691e5dfae7ef', '06aec3a1-a52a-4e2f-bd9a-f9a087f8b834', 1, 'No es necesaria la entrega de la cosa cuando el que la tiene en su poder por otro título, acepta el depósito expresamente o en virtud de mandato de autoridad competente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('799cc467-dfca-4772-9e0d-d393263b1148', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1976', NULL, 1850, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8dcbca58-8950-41c1-ae35-073d8c27725f', '799cc467-dfca-4772-9e0d-d393263b1148', 1, 'El menor de edad que acepte el depósito está obligado a restituir la cosa depositada si se conserva aún en su poder, o el provecho que hubiere recibido de su enajenación; y si hubiere procedido de mala fe, podrá ser condenado al pago de daños y perjuicios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d41de764-8ccc-4dcf-99d8-8004f95d5e10', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1977', NULL, 1851, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f709bbd8-f66c-44e3-afc2-98d35f04d3e8', 'd41de764-8ccc-4dcf-99d8-8004f95d5e10', 1, 'El depositario tiene derecho a exigir retribución por el depósito, salvo pacto en contrario. Si las partes no se pusieren de acuerdo, fijará el juez dicha retribución equitativamente, según las circunstancias del caso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('95491708-25b4-444a-b730-4ea474c06f0a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1978', NULL, 1852, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a499a960-dde6-4b64-b385-0701b61adee0', '95491708-25b4-444a-b730-4ea474c06f0a', 1, 'Son obligaciones del depositario: 1. Guardar la cosa depositada y abstenerse de hacer uso de ella;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c5cd123-3f38-4fde-a3fd-a79c75640b57', '95491708-25b4-444a-b730-4ea474c06f0a', 2, '2. No registrar las cosas que se han depositado en arca, cofre, fardo o paquete, cerrados o sellados;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('653b58aa-4f84-42ca-95dc-17b99f7b40b3', '95491708-25b4-444a-b730-4ea474c06f0a', 3, '3. Dar aviso inmediato al depositante o en su caso al juez, del peligro de pérdida o deterioro de la cosa depositada y de las medidas que deben adoptarse para evitarlo; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e7ce0fe3-a339-451c-998b-dd15ba872f0d', '95491708-25b4-444a-b730-4ea474c06f0a', 4, '4. Indemnizar los daños y perjuicios que por su dolo o culpa sufriere el depositante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d477a49c-00eb-4b03-b5d8-8bbc014d03eb', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1979', NULL, 1853, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7d40f190-3e53-4619-b76e-72b0176adb3f', 'd477a49c-00eb-4b03-b5d8-8bbc014d03eb', 1, 'Los depositarios de documentos que devenguen intereses, están obligados a realizar el cobro de éstos en las fechas de su vencimiento, así como a ejecutar los actos necesarios para que tales documentos conserven su vigencia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3718d4f6-c422-42fe-a816-3fac9c817b7d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1980', NULL, 1854, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c3ca040b-a0ae-4212-8d5a-e28da7d2756a', '3718d4f6-c422-42fe-a816-3fac9c817b7d', 1, 'Si por culpa del depositario se hubiere roto la cerradura o el sello de un depósito que se hizo en caja, fardo o paquete cerrado o sellado, sin hacerse constar su contenido y así lo admitió el depositario, se tendrá como cierta la declaración jurada del depositante acerca del contenido, mientras no se pruebe lo contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('03633e26-b512-4028-8cb7-d71fb304c3c5', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1981', NULL, 1855, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('72d4986c-d887-4b55-b01d-d08cafec2556', '03633e26-b512-4028-8cb7-d71fb304c3c5', 1, 'El depositante está obligado a satisfacer al depositario los gastos hechos en la guarda y la conservación de la cosa y resarcirle los daños y perjuicios que el depósito le hubiere causado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b1f65dbb-3a3b-424a-a9f1-fb396552cd06', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1982', NULL, 1856, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d4233c9c-5957-441e-83a9-0b7301df4a5f', 'b1f65dbb-3a3b-424a-a9f1-fb396552cd06', 1, 'El depositario podrá retener la cosa depositada mientras no se le hayan pagado o garantizado los gastos o los daños y perjuicios a que se refiere el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2684a8ea-5fb6-4dfd-8234-a64117f8b85d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1983', NULL, 1857, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9986f1cf-8a38-4c9a-a648-dd912c46386d', '2684a8ea-5fb6-4dfd-8234-a64117f8b85d', 1, 'Es de cuenta del depositante el deterioro o pérdida de la cosa sin culpa del depositario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78c55c22-237d-448d-854b-5616199eb1e7', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1984', NULL, 1858, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1953652-fc2c-4f54-9750-8af512338901', '78c55c22-237d-448d-854b-5616199eb1e7', 1, 'Cuando al celebrarse el contrato se faculta al depositario para usar la cosa, y no se tratare de depósito de moneda corriente en instituciones de crédito, el contrato será de mutuo si se trata de cosas fungibles, o de comodato, si de cosas que no perecen con el primer uso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8032edc9-4034-440e-af4d-5b757d566bc5', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1985', NULL, 1859, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('49cc855c-116a-4809-8dd8-269ee965d18b', '8032edc9-4034-440e-af4d-5b757d566bc5', 1, 'El depósito hecho en favor de un tercero, si éste no manifestare aceptarlo dentro de dos meses desde el día que el depositante o depositario le haya dado aviso, podrá recuperarlo el depositante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('af6b93ba-b839-476c-96f4-b91f79f98642', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1986', NULL, 1860, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6802f132-54b7-41a4-af2b-fe85247e912e', 'af6b93ba-b839-476c-96f4-b91f79f98642', 1, 'Si fueren dos o más los depositantes, todos concurrirán a recibir el depósito y no se entregará a ninguno de ellos sin el consentimiento de los demás.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ee45ee3-135f-4cb5-b441-cb316e81f7fe', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1987', NULL, 1861, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0e1c59b8-f28d-4df7-946e-c1a5be35379c', '7ee45ee3-135f-4cb5-b441-cb316e81f7fe', 1, 'Si el depósito se hizo por un apoderado o administrador, cuyo cargo terminó, se devolverá la cosa al dueño o a su nuevo representante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('69e0e535-9b7f-489f-befb-16b123280080', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1988', NULL, 1862, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('53838793-27f8-4651-beb1-cb880237178d', '69e0e535-9b7f-489f-befb-16b123280080', 1, 'El depositario no debe restituir el depósito a la misma persona de quien lo recibió: 1. Si el juez manda retenerlo;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bdb75116-63d1-4503-8c9b-5eb13f71d069', '69e0e535-9b7f-489f-befb-16b123280080', 2, '2. Si aparece que la cosa pertenecía a otra persona, o que había sido robada; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('15034d88-baea-42d7-b58c-123ca3afcd32', '69e0e535-9b7f-489f-befb-16b123280080', 3, '3. Si el depositante es persona incapaz.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8b69fe33-03b4-465e-9048-3fc7c3f47b11', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1989', NULL, 1863, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4772eda4-d243-4246-9846-f9e76155d42a', '8b69fe33-03b4-465e-9048-3fc7c3f47b11', 1, 'En el caso segundo del artículo anterior, el depositario está obligado a dar cuenta inmediatamente al juez, para lo que proceda; y en el caso tercero, se devolverá el depósito a la persona que, según la ley, represente al depositante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52559177-2374-4e2b-b5b5-8a6c7786da78', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1990', NULL, 1864, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8f7649b5-e5e4-4d7a-a4e8-276130f95746', '52559177-2374-4e2b-b5b5-8a6c7786da78', 1, 'Por muerte del depositante se restituirá el depósito a sus herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8d01279a-0174-4210-bd70-4d4c8dbe73aa', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1991', NULL, 1865, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f20b9017-15b8-4a50-89ae-f1d2a1bba796', '8d01279a-0174-4210-bd70-4d4c8dbe73aa', 1, 'La devolución del depósito se hará en el mismo lugar en que fue recibido, salvo pacto en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b464a815-753d-4c7c-aa42-f1a3b2c8a235', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1992', NULL, 1866, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('67c47db8-7962-4a6c-9c89-48ce27a3f265', 'b464a815-753d-4c7c-aa42-f1a3b2c8a235', 1, 'No habiendo plazo, el depositario puede devolver la cosa depositada avisando al depositante con prudente anticipación si el caso lo requiere.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5a195d93-056b-45e4-b14d-4c66f3b9d8d9', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1993', NULL, 1867, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9e6f35ab-33b7-4730-b225-d2c4e5df29c9', '5a195d93-056b-45e4-b14d-4c66f3b9d8d9', 1, 'Las cosas depositadas no podrán ser trasladadas fuera del lugar señalado en el contrato, sino por causa de necesidad y con previo aviso al depositante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('391feaac-85cc-491d-afb1-2161b85dc6c8', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1994', NULL, 1868, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0063ac41-8007-4b88-ba9f-6591ae0b633a', '391feaac-85cc-491d-afb1-2161b85dc6c8', 1, 'Aun cuando se haya fijado plazo para la restitución del depósito, debe entregarse luego que el depositante lo reclame, a no ser que se haya trasladado a otra parte la cosa depositada, de acuerdo con lo dispuesto en el artículo anterior.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9a474a8-5b1f-41be-a7b2-7f7698f60983', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1995', NULL, 1869, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5aeffe85-6452-4b8f-9dd8-399d974e0fc6', 'a9a474a8-5b1f-41be-a7b2-7f7698f60983', 1, 'El depositario que rehúse entregar el depósito, fuera de los casos expresados en el artículo 1988, responderá por los intereses, desde que incurra en mora, más los daños y perjuicios que se hubieren causado al depositante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6330d711-ac1c-46e5-92a4-a6d1720970fe', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1996', NULL, 1870, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a61e9185-cfb8-4aab-9212-860fe57e7754', '6330d711-ac1c-46e5-92a4-a6d1720970fe', 1, 'El depositario tiene derecho a que se le exonere del depósito, cuando ya no puede guardarlo con seguridad o sin perjuicio de sí mismo. Pero si tomó el encargo mediante un precio o salario, sólo podrá admitirse su renuncia por un cambio imprevisto de circunstancias a juicio del juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('90880188-0b7a-461a-bdd6-1789b4c00599', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1997', NULL, 1871, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f9c65db5-5948-44ff-bfca-76bfa3f9cfd3', '90880188-0b7a-461a-bdd6-1789b4c00599', 1, 'Las cosas litigiosas pueden ser depositadas en un tercero por disposición judicial; pero si el depósito se hizo por consentimiento de las partes, termina cuando ellas convienen en ponerle fin.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2d0129c0-e770-4b7a-96ab-0fd3f3ceefc3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1998', 'El depósito judicial termina por orden de juez competente', 1872, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f8559b3e-0350-4fc9-bd13-926e50aae637', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '1999', NULL, 1873, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c1e4c469-1349-4079-a4d9-b8de493bcb15', 'f8559b3e-0350-4fc9-bd13-926e50aae637', 1, 'El depósito de dinero en moneda corriente en las instituciones de crédito está sujeto a lo dispuesto en leyes especiales. Se presume nulo el depósito de dinero constituido en persona no autorizada por la ley para recibirlo, salvo prueba en contrario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('604c662b-bb3d-41d4-aaaa-cc284798ec87', 'f8559b3e-0350-4fc9-bd13-926e50aae637', 2, 'DEL CONTRATO DE OBRA O EMPRESA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d1ead835-93e9-4af8-a12d-9ceaa214e490', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2000', NULL, 1874, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1dedf20a-f0bf-43d4-b5b6-2905c85fb1b9', 'd1ead835-93e9-4af8-a12d-9ceaa214e490', 1, 'Por el contrato de obra o empresa, el contratista se compromete a ejecutar y entregar una obra que le encarga otra persona, mediante un precio que ésta se obliga a pagar.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5342374d-6c17-46a1-b559-f4d3da770b92', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2001', NULL, 1875, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa22a8df-07a9-49e7-a6f8-d22c7d244b7e', '5342374d-6c17-46a1-b559-f4d3da770b92', 1, 'El riesgo de la obra correrá a cargo del contratista o empresario hasta el momento de la entrega, a no ser que el que hubiere de recibirla incurriere en mora, o hubiere convenio expreso en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8cc3711a-4209-45d0-95ed-32e07a3862ae', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2002', NULL, 1876, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b5df5473-4195-41a1-82b7-f60c134f9d01', '8cc3711a-4209-45d0-95ed-32e07a3862ae', 1, 'Cuando se haya invitado a varios constructores para hacer planos, diseños o presupuestos, con el objeto de escoger el que parezca mejor, y estén sabidos de esta circunstancia, no tienen derecho a cobrar honorarios, salvo ofrecimiento o convenio en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('215019f2-afc7-4a40-a3f6-4550ffba5b92', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2003', NULL, 1877, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa17ec42-0d16-4043-9241-174cb5a7f391', '215019f2-afc7-4a40-a3f6-4550ffba5b92', 1, 'El contratista cuyo plano o presupuesto haya sido aceptado, no puede cobrar honorarios aparte del que le corresponda en la obra si él mismo tomare a su cargo el trabajo; pero si éste no se realizare por causa del dueño, podrá cobrar el precio del plano, diseño o presupuesto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83617c3a-0b89-4bdb-97bd-99b88e8c460b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2004', NULL, 1878, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c9ca114b-0179-4392-baf0-18207ee599b6', '83617c3a-0b89-4bdb-97bd-99b88e8c460b', 1, 'Podrá también el autor del plano, diseño o presupuesto, cobrar su valor cuando la obra se ejecutare conforme al mismo, por otra persona, aun cuando se hayan hecho modificaciones en los detalles.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dd509e0c-2602-4284-8085-8f3d7724f45b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2005', NULL, 1879, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dbe07d1b-3278-4f7c-89a5-692d5c0ea02a', 'dd509e0c-2602-4284-8085-8f3d7724f45b', 1, 'El contratista está obligado a hacer la obra de entera conformidad con las especificaciones del contrato y, a falta de ellas, en la forma, condiciones y calidades acostumbradas en el lugar en que la obra se ejecute y que sean necesarias para el uso a que se destina. El contratista está obligado, además, a sujetarse a los principios de la técnica y al plano o diseño que haya aceptado el dueño.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bf423658-c92b-4702-a153-eea179394c13', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2006', NULL, 1880, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9105c54e-9f90-4859-8e5f-8006d6baf021', 'bf423658-c92b-4702-a153-eea179394c13', 1, 'Aceptado por el dueño el presupuesto, plano o diseño, no podrá ser modificado sino por convenio expreso de ambas partes, y por escrito si el contrato constare en esa forma.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4ca42583-b67f-4dda-92ff-519a3f5a275e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2007', NULL, 1881, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('38e12ef2-670c-465a-bea4-134da3b14e41', '4ca42583-b67f-4dda-92ff-519a3f5a275e', 1, 'Salvo pacto en contrario, el contratista que se encarga por un precio determinado de la construcción de un edificio u otra obra, en vista de un plano convenido con el propietario y con un plazo estipulado, no puede pedir aumento del');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f7eb7b5d-8f11-4eae-8642-7705054d7dc8', '4ca42583-b67f-4dda-92ff-519a3f5a275e', 2, 'precio aunque ocurran aumentos en los salarios o en el valor de los materiales; pero podrá hacerlo cuando se haya realizado algún cambio en el plano, que produzca aumento de obra, siempre que hubiese dado su autorización el propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('89dd0f27-d0ab-4c85-9c12-9dfbf938a924', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2008', NULL, 1882, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a637635d-d254-47f7-91d8-b49098976abc', '89dd0f27-d0ab-4c85-9c12-9dfbf938a924', 1, 'Si en el curso de la obra resultare indispensable introducir modificaciones para terminarla satisfactoriamente, el contratista deberá avisarlo al dueño, haciéndole saber el aumento del precio; y si se negare a aceptar las modificaciones sin causa justificada, podrá rescindirse el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ad640c07-c1c8-41e0-adf5-3ea0906634b0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2009', NULL, 1883, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4e7ba881-ed6d-4190-b3e0-a8a9b71356c9', 'ad640c07-c1c8-41e0-adf5-3ea0906634b0', 1, 'El contratista es responsable del trabajo ejecutado por las personas que ocupare en la obra con su trabajo o con su material, y éstas no tendrán acción contra el dueño de ella sino hasta la cantidad que éste adeude al contratista cuando se hace la reclamación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0f3c9c73-17c2-40ba-b7f6-b20266ebcdd3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2010', NULL, 1884, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ede58d45-6190-43e4-8e2e-d95ac514ed32', '0f3c9c73-17c2-40ba-b7f6-b20266ebcdd3', 1, 'El contratista no puede encargar a otro la obra encomendada, a menos que se haya pactado lo contrario o que lo consienta el dueño; pero, en todo caso, la obra se hará bajo la responsabilidad del contratista.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('051c58fa-cb71-4684-b78c-c66d79269f9b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2011', NULL, 1885, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('018a8a85-6ee2-4dd7-b9cd-70b6460128f0', '051c58fa-cb71-4684-b78c-c66d79269f9b', 1, 'El dueño puede separarse del contrato pagando al contratista el trabajo realizado, los materiales empleados y la indemnización que fije el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e3499010-5121-4e37-bbeb-89357f572586', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2012', NULL, 1886, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('425ca856-1a69-4b68-abe8-f2efc904347a', 'e3499010-5121-4e37-bbeb-89357f572586', 1, 'El contratista es responsable de la infracción de las leyes y reglamentos administrativos y municipales referentes a la obra que se le encomendó y de todo daño o perjuicio que por la construcción se cause a terceros.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ca9cfdb-a7ef-4c33-8224-4471e9be1179', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2013', NULL, 1887, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3cdfbc7d-efe1-4db6-ac42-66f670ac5a9b', '7ca9cfdb-a7ef-4c33-8224-4471e9be1179', 1, 'El dueño está obligado a pagar el precio en la forma y plazos convenidos y, a falta de estipulación, al serle entregada la obra a su satisfacción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6fee31f0-f9eb-4366-a516-e6bb7bb01b58', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2014', NULL, 1888, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1f657513-38a4-463f-b7b2-9736f7448d19', '6fee31f0-f9eb-4366-a516-e6bb7bb01b58', 1, 'Si requerido el dueño de la obra para recibirla no concurre el día señalado o no hace, al recibirla, los reparos o reservas del caso, se entenderá que la recibe a su entera satisfacción, excepto en cuanto a vicios o defectos ocultos y a la responsabilidad especial relativa a la construcción de edificios.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('143ae70f-19dd-40df-8de4-ea3b5172cc96', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2015', NULL, 1889, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('46f1f72b-e408-4584-8933-b6c09b96ca2d', '143ae70f-19dd-40df-8de4-ea3b5172cc96', 1, 'El contratista es responsable por la destrucción o deterioro debidos a dolo o culpa de su parte, durante cinco años, contados desde la fecha de la entrega. Si el contratista y el ingeniero arquitecto o constructor fueren personas distintas, la responsabilidad será solidaria.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d04038c4-2c0e-434a-b15a-b8a4cf4f6c28', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2016', NULL, 1890, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d03adaf5-b321-493e-8e43-a76acae15716', 'd04038c4-2c0e-434a-b15a-b8a4cf4f6c28', 1, 'Igual responsabilidad corresponde cuando la destrucción o deterioro proceden de defectos en el terreno o cimiento, si el contratista no hace al dueño las advertencias convenientes antes de emprender la construcción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2e58ac4a-2bff-4aaa-a7d2-a55ad541b983', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2017', NULL, 1891, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('73684860-b2e2-47a9-8126-aa018ff788c4', '2e58ac4a-2bff-4aaa-a7d2-a55ad541b983', 1, 'La responsabilidad que establecen los artículos anteriores, es aplicable al caso de que el deterioro proceda de vicios de construcción no aparentes, o los defectos o deterioros se originen de haber modificado el plano o diseño sin autorización del propietario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ac183dd-5dcc-4c8f-ae30-19a861489dbd', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2018', NULL, 1892, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('17f6795e-4ba5-4926-8429-d328f7888aba', '0ac183dd-5dcc-4c8f-ae30-19a861489dbd', 1, 'El contratista que recibiere anticipos a cuenta del precio convenido, no iniciare la obra, ésta no avanzare en proporción a las sumas recibidas, sufriere atrasos injustificados, o empleare materiales de construcción que no llene las especificaciones del contrato, responderá al dueño por los daños y perjuicios que resulten. Asimismo el contratista podrá ser acusado criminalmente por el afectado o sus herederos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('49a3e7f2-398a-408d-8e6e-69927ee06aad', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2019', NULL, 1893, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('347de336-ced4-4587-b509-964677edec2e', '49a3e7f2-398a-408d-8e6e-69927ee06aad', 1, 'Cuando se ha encargado cierta obra a una persona por razón de sus cualidades personales, el contrato se rescinde por la muerte de ella. En este caso, el propietario debe abonar a los herederos del contratista en proporción del precio convenido, el valor de la parte de obra ejecutada y de los materiales preparados.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b3b3cfe1-9e7f-47b3-8922-402d44855138', '49a3e7f2-398a-408d-8e6e-69927ee06aad', 2, 'También procederá la rescisión, cuando el contratista no pueda terminar la obra por causa independiente de su voluntad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('17dfc464-9e86-4e67-a968-17c1907b3ac1', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2020', NULL, 1894, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f8995c1d-3875-45ee-b9c8-fd4b9dcb87c4', '17dfc464-9e86-4e67-a968-17c1907b3ac1', 1, 'Si muere el dueño de la obra no se rescindirá el contrato, y sus herederos serán responsables del cumplimiento para con el contratista.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('83ebe00b-baa2-4ce6-bf6f-94e51cd0b7f3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2021', NULL, 1895, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('83e5ce32-d8bf-42dd-99cb-269837ffbff1', '83ebe00b-baa2-4ce6-bf6f-94e51cd0b7f3', 1, 'El que se obliga a hacer una obra por piezas o por medida, puede exigir que el dueño la reciba en partes y se la pague en proporción de las que reciba.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5feb9285-4ed8-4df1-b961-081009d01d9c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2022', NULL, 1896, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('88071786-dccc-4252-82df-92bf7fc07edc', '5feb9285-4ed8-4df1-b961-081009d01d9c', 1, 'La parte pagada se presume aprobada y recibida por el dueño; pero no habrá lugar a esa presunción, solamente porque el propietario haya hecho adelantos a buena cuenta del precio de la obra, si no se expresa que el pago se aplique a la parte ya entregada.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0013ef5d-9ac1-494d-b59b-015b319588be', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2023', NULL, 1897, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bc4823f2-18d6-4712-abd5-7099653089e4', '0013ef5d-9ac1-494d-b59b-015b319588be', 1, 'Lo dispuesto en los dos artículos anteriores, no se observará cuando las piezas que se manden construir no puedan ser útiles, sino formando reunidas un todo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b057a97d-d17f-4f47-8cd2-ad3fb19b2877', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2024', NULL, 1898, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b753b4f-bbfc-4fac-8999-8e92acb4dab4', 'b057a97d-d17f-4f47-8cd2-ad3fb19b2877', 1, 'Cuando la obra fue ajustada sin designación del número de piezas o de la medida total, el contrato puede resolverse por uno y otro contratante, concluidas que sean las partes designadas, pagándose la parte concluida.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bdd60137-cbea-4303-8c08-f9ddef222065', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2025', NULL, 1899, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('61272660-0ea7-4c2b-a316-ddfc583e2ab1', 'bdd60137-cbea-4303-8c08-f9ddef222065', 1, 'Pagado el contratista de lo que le corresponde, según el artículo anterior, el dueño queda en libertad de continuar la obra, empleando a otras personas, aun cuando aquella siga conforme al mismo plano, diseño o presupuesto.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5a3a060d-4aad-4ce7-8731-f28d6023e926', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2026', NULL, 1900, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e72ae214-98bd-4b2b-a998-bdba23067306', '5a3a060d-4aad-4ce7-8731-f28d6023e926', 1, 'El constructor de una obra mueble tiene derecho de retenerla mientras no se le pague, y su crédito será cubierto preferentemente con el precio de dicha obra.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cbdfc007-8ce0-4da9-865f-81f8d9958a80', '5a3a060d-4aad-4ce7-8731-f28d6023e926', 2, 'DE LOS SERVICIOS PROFESIONALES');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bfb15036-8a66-4dac-aa53-207e8decf160', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2027', NULL, 1901, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('c2239106-0dba-42fe-9f76-7253d3bba066', 'bfb15036-8a66-4dac-aa53-207e8decf160', 1, 'Los profesionales que presten sus servicios y los que los soliciten, son libres para contratar sobre honorarios y condiciones de pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('78c15660-a23f-40b9-a436-2fbeec31d4f3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2028', NULL, 1902, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7fba0f61-047a-451f-86a5-2bf01fbc3b87', '78c15660-a23f-40b9-a436-2fbeec31d4f3', 1, 'A falta de convenio, la retribución del profesional se regulará de conformidad con el arancel respectivo y, si no hubiere, será fijada por el juez, tomando en consideración la importancia y duración de los servicios y las circunstancias económicas del que debe pagarlos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a85bc4d6-62a4-4de7-8de7-5f89d38d7f87', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2029', NULL, 1903, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('326c3c27-6320-4a35-abc5-c0cdb51cd2dd', 'a85bc4d6-62a4-4de7-8de7-5f89d38d7f87', 1, 'El profesional tiene derecho, además de la retribución, a que se le paguen los gastos que haya hecho con motivo de los servicios prestados, justificándolos y comprobándolos debidamente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f964353d-5dd0-44f6-b9b5-da943d2e50cd', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2030', NULL, 1904, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f01ed39f-bb9b-4e9a-a750-30e325906e34', 'f964353d-5dd0-44f6-b9b5-da943d2e50cd', 1, 'Si varias personas encomendaren un negocio o solicitaren servicios profesionales en un mismo asunto, serán solidariamente responsables por el pago de los honorarios y gastos causados con tal motivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2f660484-721f-4d4b-98a3-777e8a07ff2f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2031', NULL, 1905, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6054b482-2303-4b29-b0c9-a6621c8414fc', '2f660484-721f-4d4b-98a3-777e8a07ff2f', 1, 'Cuando varios profesionales hubieren prestado sus servicios en un mismo asunto, cada uno de ellos tendrá derecho a ser retribuido proporcionalmente a los servicios prestados y al reembolso de los gastos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38006354-fb18-4b3d-a7ff-4523f4d37508', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2032', NULL, 1906, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6e7c5742-cce8-48a6-9e3d-7c8308ad9f21', '38006354-fb18-4b3d-a7ff-4523f4d37508', 1, 'Salvo pacto en contrario, los que prestaren servicios profesionales tendrán derecho a ser retribuidos, cualquiera que sea el éxito o resultado del negocio o asunto en el cual hubieren intervenido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bfc9a3b4-599f-4959-8c39-9f876fe2e0d2', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2033', NULL, 1907, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('987ff1dc-22c9-4bd3-aca2-fca3c930d319', 'bfc9a3b4-599f-4959-8c39-9f876fe2e0d2', 1, 'El profesional está obligado a prestar sus servicios con toda dedicación y diligencia y con arreglo a las prescripciones de la ciencia o arte de que se trate, siendo responsable de los daños y perjuicios que cause por dolo, culpa o Ignorancia inexcusable, o por la divulgación de los secretos de su cliente.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('db6a9982-a444-42b0-8775-aee77978425d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2034', NULL, 1908, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('53bfd244-9ac4-4d06-987e-fc6c4f56938d', 'db6a9982-a444-42b0-8775-aee77978425d', 1, 'Cuando un profesional no pueda continuar prestando sus servicios, deberá avisar con la debida anticipación, según la naturaleza del trabajo, a la persona que los contrató, quedando responsable de daños y perjuicios si se separare sin dar aviso y sin dejar persona competente que lo sustituya.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5bf367dd-1845-4cb8-b2b8-8ef3fcaaea2f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2035', NULL, 1909, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('077ce7f8-bfb7-4a35-b823-dd1f457c43e3', '5bf367dd-1845-4cb8-b2b8-8ef3fcaaea2f', 1, 'Si la persona que contrató los servicios no está conforme con su desarrollo o con los actos o conducta del profesional, puede rescindir el contrato pagando el trabajo y los gastos efectuados, cantidad que fijará el juez, si hubiere desacuerdo entre las partes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f39ae114-92f4-45b7-ad8a-66a33d750d27', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2036', NULL, 1910, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5e5024da-6791-440e-84a3-90bfce3355c6', 'f39ae114-92f4-45b7-ad8a-66a33d750d27', 1, 'Las personas que, sin tener título facultativo o autorización legal, prestaren servicios profesionales para los cuales la ley exige ese requisito, además de incurrir en las penas respectivas, no tendrán derecho a retribución y serán responsables de los daños y perjuicios que hubieren ocasionado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('140a6403-9f84-40f0-8c9b-d5bc1f422044', 'f39ae114-92f4-45b7-ad8a-66a33d750d27', 2, 'DEL CONTRATO DE EDICION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec73a9a9-3e5a-4318-a9e8-1b90eb5e0d16', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2037', NULL, 1911, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('269d10ab-9f0f-4a0f-9475-868dcfc9ef50', 'ec73a9a9-3e5a-4318-a9e8-1b90eb5e0d16', 1, 'al 2065.32 DEROGADOS.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d7279606-7527-4506-bf18-9740b50ad449', 'ec73a9a9-3e5a-4318-a9e8-1b90eb5e0d16', 2, 'DE LOS CONTRATOS DE DIFUSION POR RADIO, TELEVISION, CINEMATOGRAFIA O GRABACION, Y DE REPRESENTACION TEATRAL O ESCENICA.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('288c72ab-119f-4fa6-92de-a9b66152eeae', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2066', NULL, 1912, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2323b1e-46df-485f-b8ea-4142f3ba71ca', '288c72ab-119f-4fa6-92de-a9b66152eeae', 1, 'al 2076.33 DEROGADOS.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('782efaf1-e6df-4b9f-8ed6-5504b9b3877c', '288c72ab-119f-4fa6-92de-a9b66152eeae', 2, 'DEL HOSPEDAJE');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('952411dd-bd8e-403c-b8f8-6b28e24b0f9e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2077', NULL, 1913, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56dd2c23-fd65-4c03-8c1f-3965d8a4e6ac', '952411dd-bd8e-403c-b8f8-6b28e24b0f9e', 1, 'al 2084.34 DEROGADOS.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('28a2f473-954e-4371-b64e-067a9d68ae23', '952411dd-bd8e-403c-b8f8-6b28e24b0f9e', 2, 'DEL TRANSPORTE');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('26e50c9f-be11-4e2a-994a-b916c30636a5', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2085', NULL, 1914, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c31acda-32ba-48e1-9972-b8a7ac6bf2ec', '26e50c9f-be11-4e2a-994a-b916c30636a5', 1, 'al 2099.35 DEROGADO.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('246fc8fa-ce98-4686-a486-5b7ba65663a5', '26e50c9f-be11-4e2a-994a-b916c30636a5', 2, 'DE LA FIANZA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb03ee98-c505-494d-9bb4-d20f8e649786', '26e50c9f-be11-4e2a-994a-b916c30636a5', 3, '32 Derogados los artículos 2037 al 2065, por el Artículo I del Capitulo II Disposiciones Derogatorias y Modificatorias del Decreto No. 2-70, publicado en el Diario de Centro América el 22 de junio de 1970.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('433b7741-2d4f-435b-8fb2-8a97a18f9c02', '26e50c9f-be11-4e2a-994a-b916c30636a5', 4, '33 Derogados los artículos 2066 al 2076, por el Artículo I del Capitulo II Disposiciones Derogatorias y Modificatorias del Decreto No. 2-70, publicado en el Diario de Centro América el 22 de junio de 1970. 34 Derogados los artículos 2077 al 2084, por el Artículo I del Capitulo II Disposiciones Derogatorias y Modificatorias del Decreto No. 2-70, publicado en el Diario de Centro América el 22 de junio de 1970. 35 Derogados los artículos 2085 al 2099, por el Artículo I del Capitulo II Disposiciones Derogatorias y Modificatorias del Decreto No. 2-70, publicado en el Diario de Centro América el 22 de junio de 1970.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('45b896b3-4e34-42de-96f1-02d1a491c8b3', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2100', NULL, 1915, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0fbb10a9-a978-4061-8730-982a1ae1c8f4', '45b896b3-4e34-42de-96f1-02d1a491c8b3', 1, 'Por el contrato de fianza una persona se compromete a responder por las obligaciones de otra. El fiador puede estipular con el deudor una remuneración por el servicio que le presta.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d11a7703-5cd8-416c-9ede-c53a3822e42a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2101', 'La fianza debe constar por escrito para su validez', 1916, true, 1);
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('52a8e52a-4c45-4cc3-8ef5-29290c534c48', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2102', NULL, 1917, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f74a4ac3-3b9a-4a64-85b0-6e379011062e', '52a8e52a-4c45-4cc3-8ef5-29290c534c48', 1, 'El fiador sólo será responsable por aquello a que expresamente se hubiere comprometido. Puede obligarse, a menos pero no a más que el deudor principal, tanto en la cantidad como en lo oneroso de las condiciones. Si se hubiere obligado a más, se tendrá por reducida su obligación en cuanto al exceso.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1532b144-7d83-4523-94be-7e1c8c923822', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2103', NULL, 1918, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee566dff-5815-437d-b278-1aa6f31d1e7e', '1532b144-7d83-4523-94be-7e1c8c923822', 1, 'El fiador puede limitar su responsabilidad constituyendo prenda o hipoteca. Si la fianza no fuere limitada, el fiador queda obligado no sólo por la obligación principal sino por el pago de intereses, indemnización de daños y perjuicios en caso de mora, y gastos judiciales. El fiador no responderá de otros daños y perjuicios y gastos judiciales, sino de los que se hubieren causado después de haber sido requerido para el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2aac1602-b456-4daa-800a-0b8bcb650e87', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2104', NULL, 1919, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d692d2d2-bc32-46fe-b160-7d16e8db3b9c', '2aac1602-b456-4daa-800a-0b8bcb650e87', 1, 'Es nula la fianza qué recae sobre una obligación que no es válida. Se exceptúa el caso en que la nulidad proceda de incapacidad personal del deudor, si el fiador tuvo conocimiento de la incapacidad al tiempo de obligarse.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7972f8f7-f7e3-4300-8ce9-062fc57333a2', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2105', NULL, 1920, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e4474970-eabd-42f2-8e1c-1df47ddb6261', '7972f8f7-f7e3-4300-8ce9-062fc57333a2', 1, 'El fiador puede pedir que el fiado le garantice las resultas de la fianza: 1. Si el deudor está para ausentarse de la república;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b150b239-3a80-4321-9978-f9befe319d6f', '7972f8f7-f7e3-4300-8ce9-062fc57333a2', 2, '2. Si el deudor, ha sufrido menoscabo en sus bienes, de modo que se halle en riesgo de Insolvencia;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7a97ef75-4de9-4c02-bb5f-210a6bf424f8', '7972f8f7-f7e3-4300-8ce9-062fc57333a2', 3, '3. Si hubiere temor justificado de que el deudor oculte o dilapide sus bienes;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9383543f-0e61-468d-8365-57e6a30e01dc', '7972f8f7-f7e3-4300-8ce9-062fc57333a2', 4, '4. Si el fiador ha sido demandado por el acreedor para el pago de la deuda; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3d8d49eb-d77e-442a-a0e6-75bb20f71205', '7972f8f7-f7e3-4300-8ce9-062fc57333a2', 5, '5. Cuando el deudor se haya obligado a obtener el relevo de la fianza dentro de cierto plazo, y éste haya vencido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c67777b2-bc08-4e4c-ac95-d2c517f88905', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2106', NULL, 1921, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7032f777-0017-4561-8b5d-adf100b83e47', 'c67777b2-bc08-4e4c-ac95-d2c517f88905', 1, 'No puede compelerse al fiador a pagar al acreedor, sin previa excusión de los bienes del deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b37ac3f8-83d1-4b04-b3f4-b3f838645e07', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2107', NULL, 1922, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3088b068-2bd3-47be-bef9-fc6eed78194e', 'b37ac3f8-83d1-4b04-b3f4-b3f838645e07', 1, 'La excusión no tiene lugar: 1. Cuando el fiador ha renunciado expresamente a ella;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b4b00723-6ee6-44ba-9291-7c66f5172c57', 'b37ac3f8-83d1-4b04-b3f4-b3f838645e07', 2, '2. Cuando se ha obligado solidariamente con el deudor; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7dfd51c0-1484-4730-b0ee-79a6e2323914', 'b37ac3f8-83d1-4b04-b3f4-b3f838645e07', 3, '3. En caso de quiebra o de cesión de bienes del deudor.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('100b321e-8acf-4ca2-8659-9665246a2363', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2108', NULL, 1923, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b7cddd2-5abf-4b95-8a87-1086b8603a8a', '100b321e-8acf-4ca2-8659-9665246a2363', 1, 'Para que el fiador pueda aprovecharse del beneficio de la excusión, debe oponerlo al acreedor luego que éste lo requiera para el pago, y señalarle bienes realizables del deudor que sean suficientes para cubrir el importe de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('50952f8d-6bd5-4d06-9bac-157bf3524c79', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2109', NULL, 1924, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3fe73384-dcd6-493e-ae98-4dee7b08be9f', '50952f8d-6bd5-4d06-9bac-157bf3524c79', 1, 'El fiador podrá hacer valer las excepciones que contra el acreedor correspondan al deudor, aunque éste las hubiere renunciado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb5e4587-07b7-42ee-9f5a-95a11531084f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2110', NULL, 1925, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('31b8336d-09f8-4d06-849d-e33c47f88c29', 'bb5e4587-07b7-42ee-9f5a-95a11531084f', 1, 'El fiador puede pedir que se le exonere de la fianza haciendo el depósito judicial de la cantidad de dinero adeudado y los intereses hasta el vencimiento del plazo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f8f08c44-2719-4b72-a35f-b8670b33ea43', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2111', NULL, 1926, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2105d773-2da6-432b-b34e-0797c638dea4', 'f8f08c44-2719-4b72-a35f-b8670b33ea43', 1, 'La cláusula de que el plazo de la obligación principal se prorroga a voluntad de ambas partes sin necesidad de nueva escritura o documento, no prorroga la fianza, salvo que el fiador haga constar expresamente la aceptación de la cláusula de la prórroga y la duración de ésta, la cual podrá concederse al constituirse la fianza.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5618c480-1eb2-40a7-a393-052ecef624c1', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2112', NULL, 1927, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('47646117-c879-4565-b7ee-5db56b931cb4', '5618c480-1eb2-40a7-a393-052ecef624c1', 1, 'Si el fiador viniere a estado de insolvencia, puede el acreedor exigir al deudor otro fiador abonado, y si no lo presentare dentro del término que les señale el juez, el acreedor podrá dar por vencido el plazo de la obligación principal.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('fc103f67-9cb4-4eb1-80d8-9780a799a1b4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2113', NULL, 1928, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('701bf167-8f6f-4fa8-8ba3-f1e4f27afffd', 'fc103f67-9cb4-4eb1-80d8-9780a799a1b4', 1, 'La solvencia del fiador, se estima atendiendo a sus bienes y al estado de sus negocios. No se tomarán en cuenta para este objeto, los bienes litigiosos ni los que estén garantizando alguna obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('4bb663bf-3a6f-4520-9901-62c00b25df05', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2114', NULL, 1929, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('87d88440-4331-49c8-8a62-7b26966fd864', '4bb663bf-3a6f-4520-9901-62c00b25df05', 1, 'El fiador que paga o cumple la obligación del deudor en todo o en parte, tiene derecho a que éste le reembolse la totalidad de lo pagado. El fiador se subroga por el pago en los derechos que el acreedor tenía contra el deudor, pero cualquiera reducción o beneficio que hubiere obtenido del acreedor aprovechará al deudor y, en consecuencia, no podrá exigirle más de lo que efectivamente haya pagado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e1657c15-b2a9-4504-9190-1e21fa8b0c35', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2115', NULL, 1930, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5cd212b8-3799-4806-bb81-66059306d3a2', 'e1657c15-b2a9-4504-9190-1e21fa8b0c35', 1, 'Si fueren varios los fiadores, el que satisfaga la deuda tiene derecho para cobrarla de los demás cofiadores, rebajada la parte que a prorrata le corresponde.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c481fedd-3b05-4eed-8a5f-e029e5cdadfa', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2116', NULL, 1931, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1ea2666f-46b6-4117-a1e7-7d8ad54da374', 'c481fedd-3b05-4eed-8a5f-e029e5cdadfa', 1, 'El fiador de una obligación que pagare la deuda de varios deudores solidarios entre sí, tiene derecho a repetir por el total contra todos o cada uno de ellos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d14b55fb-9fcf-4a45-9ab1-e9286feda19b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2117', NULL, 1932, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a3d32111-fda2-42df-9d52-2701774e619f', 'd14b55fb-9fcf-4a45-9ab1-e9286feda19b', 1, 'La prórroga concedida al deudor sin el expreso consentimiento del fiador, extingue la obligación de éste.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2c3673d2-8327-4151-b1bc-6ec89bb2d849', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2118', NULL, 1933, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0185394e-99b1-44c0-a67e-383ec4409e48', '2c3673d2-8327-4151-b1bc-6ec89bb2d849', 1, 'Si la fianza se prestó por tiempo indeterminado y no hubiere convenio expreso en contrario, se extinguirá la obligación del fiador al cumplirse un año de la fecha del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a024b325-8606-490a-9b15-2f38b85548b4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2119', NULL, 1934, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('794ae7bb-f705-4f03-a782-44e59fca18c8', 'a024b325-8606-490a-9b15-2f38b85548b4', 1, 'El fiador del fiador no está obligado para con el acreedor sino en el caso de que el deudor principal y todos los fiadores de éste no hayan cumplido la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f43bced9-ec22-4410-a506-212b4feed6b6', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2120', NULL, 1935, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5fd9c105-d628-4c73-b40a-97d5197b8080', 'f43bced9-ec22-4410-a506-212b4feed6b6', 1, 'Los derechos y obligaciones del fiador pasan a sus herederos en proporción a la parte que les corresponda.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a73dbaae-20c4-4f7c-adda-c80d5764f6d3', 'f43bced9-ec22-4410-a506-212b4feed6b6', 2, 'DE LA RENTA VITALICIA');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bc42bf15-c4fc-48d8-93a6-e17d4b61078a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2121', NULL, 1936, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('f09fd919-701d-4856-95ef-9c7e8e3acaed', 'bc42bf15-c4fc-48d8-93a6-e17d4b61078a', 1, 'Por el contrato aleatorio de renta vitalicia, una persona transmite el dominio de determinados bienes a otra que se obliga, en cambio, a pagar periódicamente una pensión durante la vida del rentista. El rentista puede ser el que transfiere la propiedad de los bienes o un tercero designado por éste en el contrato.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aa7dac97-345c-4a7c-ba1e-b2c10ec30ac7', 'bc42bf15-c4fc-48d8-93a6-e17d4b61078a', 2, 'La renta vitalicia puede también constituirse a título gratuito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d6f8c310-a2bc-4521-9817-754067053d4d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2122', NULL, 1937, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7b152c32-a2d6-4689-92db-49a3aa8367db', 'd6f8c310-a2bc-4521-9817-754067053d4d', 1, 'Para la validez del contrato se requiere su otorgamiento en escritura pública, la cual contendrá la especificación y valor de los bienes que se transmiten, la identificación del rentista si fuere un tercero y la pensión o renta que ha de pagársele, el propósito de la renta, la garantía que asegure su pago y las condiciones que crean convenientes las partes. Si se trata de inmuebles se observarán, además, los requisitos necesarios para su inscripción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('38d6c08d-1f21-4a91-a742-08fe6f9a6a00', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2123', NULL, 1938, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3baee16e-177f-43c0-9d9d-975581f23b90', '38d6c08d-1f21-4a91-a742-08fe6f9a6a00', 1, 'El rentista puede ser persona jurídica, pero en tal caso, la renta terminará con la vida del instituyente o con la vida de la persona designada por él al otorgarse el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('04c0f8dd-380d-4d4b-b496-df3d26bc93aa', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2124', NULL, 1939, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e8d2c9bc-2af5-46f6-acb7-bd420404149a', '04c0f8dd-380d-4d4b-b496-df3d26bc93aa', 1, 'El contrato es nulo si la persona sobre cuya vida se constituye ha muerto antes de su otorgamiento o dentro del plazo que el contrato señale y que no podrá bajar de tres meses.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b6ef94d8-9d71-4aca-bb4e-9be81b949f5d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2125', NULL, 1940, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('51ea4c4b-d359-4cf9-873c-a917184b2931', 'b6ef94d8-9d71-4aca-bb4e-9be81b949f5d', 1, 'Si al constituirse la renta a favor de varias personas, no se expresa la parte de que gozará cada una, se entiende que es por partes iguales. La muerte de cualquiera de ellas no acrece la parte de las que sobrevivan, salvo disposición en contrario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('746e6072-6193-4c36-9e78-355db2a46d5b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2126', NULL, 1941, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('76daa6b3-64f8-4f74-8b75-16024ac3b541', '746e6072-6193-4c36-9e78-355db2a46d5b', 1, 'El que está obligado a pagar alimentos no podrá hacer transferencia de bienes por renta, sin garantizar previamente el derecho de los alimentistas.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('68f1375b-0ea7-4b87-8ba7-ca6673bea560', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2127', NULL, 1942, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('21c630c0-a100-47dc-88c2-5b12904b0333', '68f1375b-0ea7-4b87-8ba7-ca6673bea560', 1, 'Si la renta hubiere sido destinada para alimentos, o si por las circunstancias sobrevenidas al rentista hubiere de destinarse a ese objeto, no será compensable, ni embargable la que corresponde al período que esté corriendo, ni las futuras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c56ba270-0451-417b-b208-a8b0cae19c4c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2128', NULL, 1943, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bbc7e3dc-1ca9-4192-92d4-38196a2d7443', 'c56ba270-0451-417b-b208-a8b0cae19c4c', 1, 'El deudor de renta vitalicia debe prestar garantía suficiente a favor del rentista. Si no cumpliere esta obligación, el acreedor puede demandar la resolución del contrato y la restitución de los bienes si ya hubieren sido entregados.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0355e937-5a65-439f-a53e-4be71e7bf048', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2129', NULL, 1944, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ff8d8de2-064c-4a24-b84d-507bba686163', '0355e937-5a65-439f-a53e-4be71e7bf048', 1, 'Si la garantía prestada hubiere disminuido o se hiciere insuficiente, el rentista puede solicitar su ampliación, y si el obligado no estuviere de acuerdo, corresponderá al juez calificar tales circunstancias. Si el deudor no la ampliara de conformidad con la declaración judicial, podrá pedirse la rescisión del contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('769ff41a-bbcb-421d-8fd0-babd3e8d7523', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2130', NULL, 1945, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1bd36232-ff83-4564-95fd-cf39b82e5758', '769ff41a-bbcb-421d-8fd0-babd3e8d7523', 1, 'La renta vitalicia se extingue con la muerte de la persona sobre cuya vida fue constituida. Si muere el deudor, la obligación de pagar la renta pasa a sus herederos, en forma solidaria, salvo lo que se establezca en el contrato.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2bfde325-7300-47f1-98a0-13d7449757fd', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2131', NULL, 1946, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9309f673-0986-40cf-921c-f3be8e2447c5', '2bfde325-7300-47f1-98a0-13d7449757fd', 1, 'La falta de pago de la renta sólo da derecho al rentista para demandar el pago de las que estén vencidas y el aseguramiento de las futuras.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a08274ec-18d5-4f6a-85d9-6656b1c76bc5', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2132', NULL, 1947, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('489f27d7-bc9d-4725-af5c-cf15e921c65d', 'a08274ec-18d5-4f6a-85d9-6656b1c76bc5', 1, 'La renta correspondiente al período en que muere el que la disfrute, se pagará en proporción a los días que éste vivió; pero si debía pagarse por plazos anticipados, se pagará el importe del plazo que durante la vida del rentista hubiere comenzado a correr.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('14182f77-e172-4774-b9ee-f1195f3df4f0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2133', NULL, 1948, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14b8097b-ce40-4943-a874-06cc72fba7b9', '14182f77-e172-4774-b9ee-f1195f3df4f0', 1, 'Si la renta a título gratuito debe comenzar a pagarse desde que muera el instituyente y antes falleciere el beneficiario sin que aquél designare al sustituto, la renta corresponderá a los herederos del que la instituyó. Pero si la renta hubiere sido establecida en compensación de servicios u obligaciones, pasará a los herederos del beneficiario.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('372e064a-8616-408e-813f-1609f9e06df8', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2134', NULL, 1949, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4d65c4fc-f8f4-4c8e-af41-8d8e519afea0', '372e064a-8616-408e-813f-1609f9e06df8', 1, 'En la renta instituida para ser pagada a la muerte del instituyente, si el rentista no aceptare la pensión, ésta pasará a los herederos del que la instituyó, excluyéndose al beneficiario si también fuere heredero.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('845814c4-b21b-422c-8fae-7e91eae22321', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2135', NULL, 1950, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cd2cd1e1-9e5e-4eb0-b9b5-9016dd5bb0fc', '845814c4-b21b-422c-8fae-7e91eae22321', 1, 'El tercero rentista a título gratuito, no puede enajenar ni gravar su derecho a la renta si no hubiere sido facultado expresamente por el que la estableció, y en caso de que lo haga por estar facultado, siempre terminará la renta la fecha en que debía concluir para el rentista que enajenó su derecho.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bca4db1b-fe28-4b9f-a885-e48adb8e7eef', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2136', NULL, 1951, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1e120f0d-e818-4ae4-9dbb-e50f66a96b70', 'bca4db1b-fe28-4b9f-a885-e48adb8e7eef', 1, 'Si el deudor fuere responsable criminalmente de la muerte del rentista o de la persona sobre cuya vida se constituyó la renta, devolverá el capital al instituyente o a sus herederos, sin deducción de lo que hubiere pagado.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a0df628a-b474-4290-a99e-51481c6ecb82', 'bca4db1b-fe28-4b9f-a885-e48adb8e7eef', 2, 'LOTERIAS Y RIFAS; APUESTAS Y JUEGO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bb0f6440-e524-4a34-bbde-86cc14a6eb75', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2137', NULL, 1952, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('aaeed933-1108-48db-8478-62ad13065ffa', 'bb0f6440-e524-4a34-bbde-86cc14a6eb75', 1, 'La participación o interés en una lotería o rifa, sólo se acreditará con el billete o documento legalmente expedido.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ec2dfa6b-5f85-4832-8e4a-0ebfd08f68c4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2138', NULL, 1953, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6b361e74-9c21-40a7-a294-06ebee989261', 'ec2dfa6b-5f85-4832-8e4a-0ebfd08f68c4', 1, 'Los derechos que se deriven del billete al portador corresponden al tenedor de éste, sin que tenga que justificar la forma en que lo adquirió. Si el billete fuere nominativo, la transferencia se operará por endoso igualmente nominativo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('ef26d224-a7cc-44d0-b6fc-f38e515d0b29', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2139', NULL, 1954, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2c963d4-6aba-49b9-ac1b-47852d5b92fc', 'ef26d224-a7cc-44d0-b6fc-f38e515d0b29', 1, 'El sorteo deberá hacerse con intervención de la autoridad competente; y salvo lo dispuesto en leyes especiales, no podrá correrse el sorteo, sin que la propia autoridad haga constar en acta, que ha sido vendido, por lo menos, el ochenta por ciento de los billetes emitidos, y que los billetes no vendidos han sido retirados y destruidos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('25c2fa31-a73c-4cac-9407-b4aca8959a6f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2140', NULL, 1955, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('64494c19-5456-439c-ab2e-1bcc358a0e5e', '25c2fa31-a73c-4cac-9407-b4aca8959a6f', 1, 'El producto de la venta de billetes se mantendrá en depósito hasta que los favorecidos en el sorteo hayan sido pagados, salvo que el empresario o persona responsable, preste garantía suficiente a juicio de la autoridad judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9d42cb20-2d2b-485b-a3df-a51f1bab8d8a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2141', NULL, 1956, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('71d0fb62-58f5-4155-ab5d-fa42f92ee513', '9d42cb20-2d2b-485b-a3df-a51f1bab8d8a', 1, 'Si por cualquier motivo no se corriere el sorteo en la fecha indicada en los billetes o en la prórroga debidamente autorizada, los tenedores de billetes podrán exigir la devolución del valor que representen.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('bafc2d0b-9186-4373-9fef-88b9a1419b46', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2142', NULL, 1957, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('44239922-a3d9-4663-a05e-6154c483ea67', 'bafc2d0b-9186-4373-9fef-88b9a1419b46', 1, 'El billete o documento de participación legalmente expedido, es título ejecutivo para reclamar el pago de lo ganado o la devolución de lo pagado, si la lotería o rifa no llegare a realizarse, sin que pueda oponerse compensación o novación de contrato para eludir el pago.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('d7189a87-c3ee-4c6b-9d3b-9c7f41a400b0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2143', NULL, 1958, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('733437a0-9e44-4b8c-ba6a-29ce1ad4e9c5', 'd7189a87-c3ee-4c6b-9d3b-9c7f41a400b0', 1, 'El empresario o persona responsable están obligados a pagar el premio del billete a la presentación de éste, a menos que hubiere orden judicial, en cuyo caso se depositará el valor en la persona o institución que designe el juez.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('eb4d713a-4ec5-4314-a745-9acaaf9d97b6', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2144', NULL, 1959, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6e67598c-9bc1-415c-afc0-505234187d7e', 'eb4d713a-4ec5-4314-a745-9acaaf9d97b6', 1, 'Fuera de las disposiciones anteriores, las loterías o rifas, cuando se permitan, quedarán sujetas a las leyes y reglamentos especiales que regulen esta materia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9d716663-d8f6-4b2c-a2c3-96b0ba84dd23', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2145', NULL, 1960, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('4c0c37a4-3fa6-4f2b-ab63-2fab157f7f43', '9d716663-d8f6-4b2c-a2c3-96b0ba84dd23', 1, 'No hay acción para reclamar lo que se gane en apuestas o juegos. El que pierde no puede repetir lo que haya pagado voluntariamente, a no ser que haya mediado dolo, o que fuere menor o inhabilitado para administrar sus bienes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c648d7d6-809a-4411-a6f1-a39b0973c0da', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2146', NULL, 1961, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6be4d1e2-54b5-4ff3-bb17-642c8a35e3a5', 'c648d7d6-809a-4411-a6f1-a39b0973c0da', 1, 'También procede la repetición a solicitud del cónyuge del que perdió, cuando el monto de lo pagado les prive de los medios económicos necesarios para las necesidades familiares, en cuyo caso, el juez podrá obligar al que ganó a que restituya la cantidad que cubra los gastos ordinarios y normales de la familia.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f1a2ca2c-6994-44f1-ada9-0dc3dbc6f24c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2147', NULL, 1962, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2c23b3c3-ab86-45b0-9f44-7427e9900419', 'f1a2ca2c-6994-44f1-ada9-0dc3dbc6f24c', 1, 'Las deudas de juego o apuestas no pueden compensarse ni ser convertidas por novación en obligaciones civilmente eficaces.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('6e3267eb-823b-431b-b4a4-d0f97013704d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2148', NULL, 1963, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('6046a7c2-a048-4a84-9a9e-cba87a046137', '6e3267eb-823b-431b-b4a4-d0f97013704d', 1, 'El que hubiere firmado una obligación que se derive de una deuda de juego o de apuesta, puede anularla probando la causa real de la obligación.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0a0ecdbf-1f9d-4d3d-88d3-b18f603805ac', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2149', NULL, 1964, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('038872e5-1477-4418-9e74-1894b4755e8e', '0a0ecdbf-1f9d-4d3d-88d3-b18f603805ac', 1, 'Si a una obligación de juego o de apuesta se le hubiere dado la forma de título a la orden o al portador, el suscriptor debe pagarla al portador de buena fe, sin perjuicio de las acciones que procedan contra el que ganó.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7bbd3967-bd7b-44f1-a55e-74593f490c30', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2150', NULL, 1965, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('55e228a0-0dfc-4ffa-ad7f-d697e067b028', '7bbd3967-bd7b-44f1-a55e-74593f490c30', 1, 'Cuando las personas se sirvan del medio de la suerte para dividir cosas comunes o terminar cuestiones, producirá, en el primer caso, los efectos de una partición legítima y en el segundo, los de una transacción.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('56d61474-b2b4-4c72-9ff8-2ef094aa9aa9', '7bbd3967-bd7b-44f1-a55e-74593f490c30', 2, 'LA TRANSACCION');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('de15177a-22ab-4044-b71b-a241b3373b9d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2151', NULL, 1966, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('50b12b61-b879-4ca3-a472-b0511c96ef14', 'de15177a-22ab-4044-b71b-a241b3373b9d', 1, 'La transacción es un contrato por el cual las partes, mediante concesiones recíprocas, deciden de común acuerdo algún punto dudoso o litigioso, evitan el pleito que podría promoverse o terminan el que está principiado.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('dbf7bf0c-5eef-40cd-9510-61659d7fc491', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2152', NULL, 1967, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('dc80bbd9-8476-4479-b475-6994f393c924', 'dbf7bf0c-5eef-40cd-9510-61659d7fc491', 1, 'Para que la transacción sea válida se requiere: 1. Que las partes tengan capacidad para disponer de lo que sea objeto de la transacción;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('776a28d0-0b3b-4685-a820-4674250155b4', 'dbf7bf0c-5eef-40cd-9510-61659d7fc491', 2, '2. Que las cosas o cuestiones sobre las cuales se transige, sean dudosas o litigiosas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1bb7abdb-2359-4e2e-bf48-e826cb889435', 'dbf7bf0c-5eef-40cd-9510-61659d7fc491', 3, '3. Que las partes se prometan, cedan o den algo recíprocamente; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0cfb686d-6717-45a7-b5fd-a62deaf66877', 'dbf7bf0c-5eef-40cd-9510-61659d7fc491', 4, '4. Que, cuando se celebre por medio de mandatario, éste tenga facultad especial, no sólo para transigir, sino para los actos y contratos derivados de la transacción que necesiten facultad especial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f33cab9e-3be1-4c7a-83f6-931464b1e2a7', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2153', NULL, 1968, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('8fb82efa-9f41-4ff1-807c-4f73467766a8', 'f33cab9e-3be1-4c7a-83f6-931464b1e2a7', 1, 'La transacción puede referirse a todos o solamente a alguno o algunos de los puntos controvertidos; pero, en todo caso, no se comprende en la transacción sino lo que se ha expresado por las partes, sea que la intención de ellas se hubiere manifestado en términos generales o especiales, o que se conozca esta intención como consecuencia necesaria de lo expresado en el convenio.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('04b35834-8f00-4449-bca3-4225b47ce53a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2154', NULL, 1969, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('2cea8760-d417-4723-b47c-afd45703901c', '04b35834-8f00-4449-bca3-4225b47ce53a', 1, 'La renuncia que se haga de derechos, acciones y pretensiones, comprende solamente los que se refieren a la disputa que dio lugar a la transacción.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e472c130-2cee-42d9-b992-2fae800058f8', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2155', NULL, 1970, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('eac0bd68-6ebb-4d57-a8bd-7f173d567220', 'e472c130-2cee-42d9-b992-2fae800058f8', 1, 'La transacción celebrada por uno o algunos de los interesados, no obliga ni favorece a los demás si no la aceptan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('2db98c5b-3a0d-49b6-8a19-2ad25d2d31d0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2156', NULL, 1971, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('3b619ba4-52b1-4af2-85e4-487ed8f4fc6a', '2db98c5b-3a0d-49b6-8a19-2ad25d2d31d0', 1, 'Si una cosa que fue materia de transacción resulta ajena, se pierde para todos los que transigieron, en proporción del interés que hubiere correspondido a cada uno. La parte en cuyo poder quedó y se perdió la cosa, tiene derecho a que los demás con quienes celebró la transacción, le devuelvan lo que dio por ella.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('62faadab-1772-4684-8bc0-e09e9dd74c37', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2157', NULL, 1972, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('afe5b0d5-dc87-4e7a-b781-ae9f3dbb11e1', '62faadab-1772-4684-8bc0-e09e9dd74c37', 1, 'Ha lugar al saneamiento en las transacciones, cuando una de las partes da a la otra alguna cosa que no era objeto de la disputa.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('ee72c62c-953b-41c6-bdc7-d69be777f4cd', '62faadab-1772-4684-8bc0-e09e9dd74c37', 2, 'RTICULO 2158. Se prohíbe transigir: 1. Sobre el estado civil de las personas;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('cba71215-4cc2-4bcc-9e5e-7f4bd01cbea7', '62faadab-1772-4684-8bc0-e09e9dd74c37', 3, '2. Sobre la validez o nulidad del matrimonio o del divorcio;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('bb16c746-402f-4b47-bf2e-5bcc7535437a', '62faadab-1772-4684-8bc0-e09e9dd74c37', 4, '3. Sobre la responsabilidad penal en los delitos que dan lugar a procedimiento de oficio; pero puede transigirse sobre la responsabilidad civil proveniente del delito;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9f30e774-8e71-42d4-8ae1-4f4ed4016452', '62faadab-1772-4684-8bc0-e09e9dd74c37', 5, '4. Sobre el derecho a ser alimentado; pero no sobre el monto de los alimentos y sobre alimentos pretéritos; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('9fbfc8c2-6ba1-4b10-8bc9-c7f11cbd2ae6', '62faadab-1772-4684-8bc0-e09e9dd74c37', 6, '5. Sobre lo que se deja por disposición de última voluntad, mientras viva el testador o donante.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('3fc9a78b-61a4-432b-aaa8-cf9abdc03b53', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2159', NULL, 1973, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('92a8e32b-1026-4289-a3ec-78f38f931e75', '3fc9a78b-61a4-432b-aaa8-cf9abdc03b53', 1, 'Los representantes de menores, Incapaces o ausentes no pueden transigir sobre los bienes de las personas que representan, sin autorización judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a9d01b8d-e999-4d38-b5a4-5c7bc6b3b43f', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2160', NULL, 1974, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7c9debad-5304-4c52-bf25-a34460215c9e', 'a9d01b8d-e999-4d38-b5a4-5c7bc6b3b43f', 1, 'El marido no puede sin el consentimiento de la mujer, ni ésta sin el de aquél, transigir sobré los bienes comunes.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8fc05c26-9df2-44f9-8eb6-0621fe14088d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2161', NULL, 1975, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('96c364b1-0854-40f8-81c6-e6f55f504113', '8fc05c26-9df2-44f9-8eb6-0621fe14088d', 1, 'Los que administran bienes nacionales o municipales, sólo podrán transigir con autorización o aprobación del Ejecutivo.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9ff973db-a1b6-4901-a7b4-91e91679621e', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2162', NULL, 1976, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0de06b4b-cc95-4663-b210-253465d33e89', '9ff973db-a1b6-4901-a7b4-91e91679621e', 1, 'Las asociaciones se ajustarán para transigir, a la ley de su creación o al instrumento de su constitución o estatutos. A falta de dichas disposiciones, se procederá con autorización judicial.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('b3b9ead8-b226-4b61-af17-1e37a3409ca8', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2163', NULL, 1977, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2f7d701-49fd-4bb4-a2a1-56f2b1f1faa5', 'b3b9ead8-b226-4b61-af17-1e37a3409ca8', 1, 'Ni aun después de que el menor haya cumplido la mayoría de edad, o el Incapaz haya sido rehabilitado, podrá el tutor transigir con él sobre los bienes que');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b9b9cd8d-1875-4044-b397-c26f767a89ae', 'b3b9ead8-b226-4b61-af17-1e37a3409ca8', 2, 'administró, si no están aprobadas judicialmente las cuentas de la tutela y canceladas las garantías legales.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e109c42f-6aed-49b3-aa67-7780f9de4f40', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2164', NULL, 1978, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('31e112c6-140b-42f1-a225-f8892f806c01', 'e109c42f-6aed-49b3-aa67-7780f9de4f40', 1, 'Los depositarios sólo podrán transigir sobre sus derechos y gastos causados en la conservación del depósito, pero no sobre la cosa objeto del depósito.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('e2cc6106-83ed-4bfb-8c1a-9953929c7e12', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2165', NULL, 1979, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a1a28e69-15f0-46ba-9cfd-8ae4efc60f20', 'e2cc6106-83ed-4bfb-8c1a-9953929c7e12', 1, 'Para que el socio administrador o representante pueda transigir sobre los bienes o derechos pertenecientes a una sociedad, necesita autorización expresa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0ef4f2f2-e6df-40b3-86c8-ea2fcaf7ec06', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2166', NULL, 1980, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5578c782-7ad1-46d1-8afa-ba056706caca', '0ef4f2f2-e6df-40b3-86c8-ea2fcaf7ec06', 1, 'Son causas especiales de nulidad en las transacciones: 1. Si celebrada por causa o con vista de un título nulo, no se hizo en ella mérito de tal nulidad;');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1c540466-0d68-45c0-82f3-c1e5aa982b61', '0ef4f2f2-e6df-40b3-86c8-ea2fcaf7ec06', 2, '2. Si se celebró en asunto en el que ya había recaído sentencia definitiva y las partes, o una de ellas, lo ignoraban; y');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b69c85d7-acc9-4900-a761-fa8f3cb5b818', '0ef4f2f2-e6df-40b3-86c8-ea2fcaf7ec06', 3, '3. Si se celebró en virtud de documentos que después se declaran falsos.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('008bede7-bc68-4b5b-851c-4152a932818a', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2167', NULL, 1981, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('e9cb7240-2386-4079-a794-0d828feec78c', '008bede7-bc68-4b5b-851c-4152a932818a', 1, 'El error de cálculo en las transacciones debe enmendarse y no es causa de nulidad.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('69e8dd26-6294-4818-8324-6b71acb15fd0', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2168', NULL, 1982, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a461877a-6137-4cbf-827b-e942a18facfc', '69e8dd26-6294-4818-8324-6b71acb15fd0', 1, 'Si los interesados convinieren en la transacción una pena adicional, ésta no podrá exceder de la quinta parte del valor que tenga la cosa.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('5c17b7d3-7906-4f0c-b181-4a59644de096', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2169', NULL, 1983, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('603e0b47-0e1d-4f70-aacc-3c068fa36605', '5c17b7d3-7906-4f0c-b181-4a59644de096', 1, 'La transacción debe redactarse por escrito, sea en escritura pública o en documento privado legalizado por notario; o bien, mediante acta judicial, o petición escrita dirigida al juez, cuyas firmas estén autenticadas por notario.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('27501f1b-fb9e-411a-9901-32bc296ddd0d', '5c17b7d3-7906-4f0c-b181-4a59644de096', 2, 'DEL COMPROMISO');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('8e8e5113-34d3-443d-836e-1a9ea187b7e4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2170.36', NULL, 1984, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('a2c76da6-1394-45c4-a013-932d2d888a5c', '8e8e5113-34d3-443d-836e-1a9ea187b7e4', 1, 'Derogado');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('f8323c4b-d965-4d1a-8c06-e63e229e943b', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2171.37', NULL, 1985, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('0b89d019-8d50-48f3-953b-62cc212186a4', 'f8323c4b-d965-4d1a-8c06-e63e229e943b', 1, 'Derogado');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('a35c9392-35d2-4e9c-a9f2-bf5e7fff059c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2172', NULL, 1986, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1fc8ea69-2ce8-4728-a930-f6e7019f9a87', 'a35c9392-35d2-4e9c-a9f2-bf5e7fff059c', 1, 'No se puede someter a árbitros los asuntos en que está prohibido transigir.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('7ea0b5f9-d3c0-4b8b-92d7-d19f2166b6a9', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2173', NULL, 1987, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('31b9d809-8cf4-435d-aa49-97cf355d3886', '7ea0b5f9-d3c0-4b8b-92d7-d19f2166b6a9', 1, 'El marido no puede sin el consentimiento de la mujer, ni ésta sin el de aquél, comprometer en árbitros los negocios que afecten bienes comunes. 36 Derogado por el Artículo 55, del Decreto No. 67-95 publicado en el Diario de Centro América el 25 de noviembre de 1995. 37 Ibídem.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c3e16064-a6d5-4304-9896-809b7b6d6784', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2174', NULL, 1988, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('45d5b618-f775-4234-92b8-9c9255ab501f', 'c3e16064-a6d5-4304-9896-809b7b6d6784', 1, 'Los representantes de menores, incapaces y ausentes necesitan autorización Judicial para comprometer en árbitros los asuntos de las personas que representan.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('c34d7010-a8fa-4d7f-a2bf-77ca2de607c7', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2175.38', NULL, 1989, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('5ec146e8-3510-4ecf-95c4-a81d0924512e', 'c34d7010-a8fa-4d7f-a2bf-77ca2de607c7', 1, 'Derogado');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('53837a0e-155f-4945-bab8-53582bbc5e71', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2176.39', NULL, 1990, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('328f2eb0-fa7b-448d-b78e-ea825492bbf2', '53837a0e-155f-4945-bab8-53582bbc5e71', 1, 'Derogado');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('48537576-2c27-46c9-ab5d-41754740270d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2177', NULL, 1991, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d2021092-9cc8-46a7-a27f-6d21241872c0', '48537576-2c27-46c9-ab5d-41754740270d', 1, 'En cuanto al modo de proceder en los compromisos y a la extensión y efectos de estos, se estará a lo que determina el Código Procesal Civil y Mercantil.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('988f9b0d-a8d9-42c1-adb5-01fe92050c2c', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2178.40', NULL, 1992, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('de1219f9-eb8c-4629-81cb-32bb182882d5', '988f9b0d-a8d9-42c1-adb5-01fe92050c2c', 1, 'Este Código entrará en vigor el primero de julio de mil novecientos sesenta y cuatro.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('0c7c25aa-5577-4547-9293-d9a98c011b54', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2179.41', NULL, 1993, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('705cdbc6-3931-4bdd-aa2b-bc3fe625bda2', '0c7c25aa-5577-4547-9293-d9a98c011b54', 1, 'Al entrar en vigor el nuevo Código, queda derogado el Código Civil contenido en el Decreto legislativo número 1932, el libro 111 del Código Civil de 1877, promulgado por el Decreto del Ejecutivo número 176, los Decretos del Congreso números 375, 444, 1145, 1289 y 1318, que son las Leyes de Adopción, de Uniones de Hecho, celebración del Matrimonio y propiedad horizontal, respectivamente en cuanto a las disposiciones que ya están comprendidas o que estén en oposición con lo establecido en este Código.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('1e4739e6-bc16-4f8b-967c-514f3ccf37bf', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '2180.42', NULL, 1994, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('b2db8095-2739-4759-a3b3-4d8d6b87b52f', '1e4739e6-bc16-4f8b-967c-514f3ccf37bf', 1, 'Los conflictos en la aplicación de preceptos contradictorios entre lo dispuesto en leyes anteriores y lo acordado en este Código, se resolverán de conformidad con lo que establece la Ley Constitutiva del Organismo Judicial, especialmente en lo que ordena el artículo 250 de dicha ley, salvo el término de la prescripción que será el señalado por la ley vigente al tiempo en que la obligación fue contraída.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('56bd83fc-d282-491e-ae4b-3101e1debcf4', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '124.43', 'TRANSITORIO', 1995, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('7db1f611-5598-44c9-bd21-114e9d7f70f4', '56bd83fc-d282-491e-ae4b-3101e1debcf4', 1, 'Mientras se promulga la nueva ley de aguas de dominio público, quedan en vigor los capítulos II, III, IV y V del título II y, II y III del título VI del Código Civil, Decreto legislativo 1932.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('66c12e7f-0639-4405-96a9-d205d8cfd6d5', '56bd83fc-d282-491e-ae4b-3101e1debcf4', 2, '38 Ibídem. 39 Ibídem. 40 Reformado como aparece en el texto por el Artículo 1, del Decreto No. 180, publicado en el Diario de Centro América el 27 de febrero de 1964. 41 Reformado como aparece en el texto por el Artículo 122, del Decreto No. 218, publicado en el Diario de Centro América el 01 de julio de 1964. 42 Reformado como parece en el texto por el Artículo 123, del Decreto No.218, publicado en el Diario de Centro América el 01 de julio de 1964. 43 Adicionado por el Artículo 124, del Decreto No. 218, publicado en el Diario de Centro América el    01 de julio de 1964.');
INSERT INTO articles (id, law_id, section_id, number, heading, position, is_current, version) VALUES ('9025a328-f69e-435a-9fc0-38f78d774d4d', 'a0000000-0000-0000-0000-000000000001', '9777a4c7-763f-4887-b3b7-f291691bf28b', '11.44', 'TRANSITORIO', 1996, true, 1);
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('1cdda019-f2d7-4fd2-a2c7-ab28ff71f7bd', '9025a328-f69e-435a-9fc0-38f78d774d4d', 1, 'Para los créditos bancarios cuyo plazo no haya vencido y que tengan pactado un régimen de tasa de interés vinculado a la tasa máxima fijada por la Junta Monetaria, ésta publicará semanalmente, para ese propósito, una tasa de referencia que se calculará tomando como base el promedio ponderado de las tasas máximas que hayan aplicado los bancos del sistema al resto de sus carteras crediticias de la semana anterior de la revisión de la tasa correspondiente.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('41fdc0dd-26ac-45db-9711-9da4010e77db', '9025a328-f69e-435a-9fc0-38f78d774d4d', 2, 'DADO EN EL PALACIO NACIONAL: EN LA CIUDAD DE GUATEMALA, A LOS CATORCE DIAS DEL MES DE SETIEMBRE DE MIL NOVECIENTOS SESENTA Y TRES.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('08d2b7f7-b791-489d-851d-775b42064deb', '9025a328-f69e-435a-9fc0-38f78d774d4d', 3, 'PUBLIQUESE Y CUMPLASE.');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('14cba778-61f5-49d4-985e-605e2759eddc', '9025a328-f69e-435a-9fc0-38f78d774d4d', 4, 'ENRIQUE PERALTA AZURDIA JEFE DEL GOBIERNO DE LA REPUBLICA MINISTRO DE LA DEFENSA NACIONAL');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('d745599b-f69b-4d76-a0d8-82034759e912', '9025a328-f69e-435a-9fc0-38f78d774d4d', 5, 'EL MINISTRO DE GOBERNACION LUIS MAXIMILIANO SERRANO CORDOVA');
INSERT INTO paragraphs (id, article_id, position, text) VALUES ('17b6f62d-d58f-45c5-8e9d-ec0035d49841', '9025a328-f69e-435a-9fc0-38f78d774d4d', 6, '44 Adicionado como aparece en el texto por el Artículo 11, del Decreto No. 29-95, publicado en el Diario de Centro América el 18 de mayo de 1995.');